		// Souvenir dans la ruche (demande de Jeff, 2026-08-03) : etat ephemere purement client, vit
		// tant que l'application reste ouverte (meme mecanisme que les champs Voix des Championnes
		// ci-dessus) - jamais persiste, jamais un nouveau systeme.
		private static Guid hiveVictoryMemoryLastEncounterId = Guid.Empty;
		private static float hiveVictoryMemoryUntilUnscaledTime = float.NegativeInfinity;
		private static string hiveVictoryMemoryLabel = string.Empty;
		private const float HiveVictoryMemorySeconds = 12f;

		private static void StampHiveVictoryMemory(bool legendary)
		{
			hiveVictoryMemoryUntilUnscaledTime = Time.unscaledTime + HiveVictoryMemorySeconds;
			hiveVictoryMemoryLabel = legendary
				? BeeLocalization.Text("hive.victory_memory.legendary", "Victoire légendaire — la ruche s'en souviendra")
				: BeeLocalization.Text("hive.victory_memory.decisive", "Victoire éclatante — la ruche célèbre son retour");
		}

		private static bool HiveVictoryMemoryActive() => Time.unscaledTime < hiveVictoryMemoryUntilUnscaledTime;

		// Souvenir dans la ruche (demande de Jeff, 2026-08-03) : une banniere tres discrete, jamais un
		// panneau - apparait pres du haut de l'ecran, s'estompe sur la derniere seconde. Reutilise
		// GetPremiumTexture/DrawSolid dans le meme style que le reste de l'interface, aucun nouvel
		// asset. Performance : ne dessine strictement rien en dehors de la fenetre de 12s.
		private static void DrawHiveVictoryMemoryBanner()
		{
			if (!HiveVictoryMemoryActive()) return;
			float remaining = hiveVictoryMemoryUntilUnscaledTime - Time.unscaledTime;
			float alpha = Mathf.Clamp01(remaining);

			Rect banner = new Rect(Screen.width * 0.5f - 210f, 18f, 420f, 40f);
			Color previous = GUI.color;
			GUI.color = new Color(1f, 1f, 1f, alpha);
			GUI.DrawTexture(banner, GetPremiumTexture("selected-glow"), ScaleMode.StretchToFill, true);
			GUI.color = previous;
			GUI.Label(banner, hiveVictoryMemoryLabel,
				new GUIStyle(titleStyle) { alignment = TextAnchor.MiddleCenter, normal = { textColor = new Color(1f, 0.92f, 0.72f, alpha) } });
