        // Chaine de secours pour tout materiau cree au runtime pour la ruche 3D. "Universal Render
        // Pipeline/Lit" n'est jamais reference que dynamiquement ici (aucun asset serialise ne le
        // pointe), et ce projet n'a aucun asset de pipeline de rendu assigne dans Graphics/Quality
        // Settings - dans ces conditions, l'etape de build de Unity peut retirer ce shader d'un
        // executable empaquete meme s'il fonctionne normalement dans l'Editeur, ce qui fait retomber
        // Unity sur son materiau d'erreur magenta pour l'objet concerne. Meme chaine de secours deja
        // utilisee par les scripts de capture internes (Editor/Sandbox*Capture.cs), reprise ici pour la
        // scene reellement jouee.
        private static readonly string[] HiveRuntimeMaterialShaderCandidates =
        {
            "Universal Render Pipeline/Lit",
            "Universal Render Pipeline/Unlit",
            "Unlit/Color",
            "Sprites/Default"
        };

        private static bool hiveRuntimeMaterialFallbackWarned;

        private static Material CreateHiveRuntimeMaterial()
        {
            for (int i = 0; i < HiveRuntimeMaterialShaderCandidates.Length; i++)
            {
                Shader shader = Shader.Find(HiveRuntimeMaterialShaderCandidates[i]);
                if (shader == null) continue;
                if (i > 0 && !hiveRuntimeMaterialFallbackWarned)
                {
                    hiveRuntimeMaterialFallbackWarned = true;
                    Debug.LogWarning(
                        "Hive runtime material fallback: '" + HiveRuntimeMaterialShaderCandidates[0] +
                        "' unavailable in this build, using '" + shader.name + "' instead.");
                }
                return new Material(shader);
            }
            return new Material(Shader.Find("Sprites/Default"));
        }

        public static void EnsureSceneObjects()
        {
            if (root != null) return;
            BuildCells();
            root = new GameObject(RootName);
            root.transform.position = new Vector3(0f, 0.38f, 0f);
            root.transform.rotation = Quaternion.Euler(0f, -8f, 0f);
            CreateProductLighting(root.transform);
            CreateWaxAmbience(root.transform);
            for (int i = 0; i < Cells.Count; i++)
            {
                HiveHexCell cell = Cells[i];
                GameObject hex = new GameObject("Hive Hex " + cell.CellId);
                hex.transform.SetParent(root.transform, false);
                hex.transform.localPosition = AxialToWorld(cell.Q, cell.R);
                CreateHexLayer(hex.transform, "Deep Shadow", 0.94f, new Vector3(0.08f, -0.115f, -0.08f), new Color(0.07f, 0.035f, 0.014f, 0.92f));
                CreateRuntimeIsoWall(hex.transform, "Left Wax Wall", -1, 0.84f, new Color(0.38f, 0.18f, 0.04f));
                CreateRuntimeIsoWall(hex.transform, "Right Wax Wall", 1, 0.84f, new Color(0.62f, 0.30f, 0.055f));
                CreateHexLayer(hex.transform, "Outer Wax Rim", 0.86f, new Vector3(0f, -0.032f, 0f), new Color(0.96f, 0.58f, 0.075f));
                CreateHexLayer(hex.transform, "Inner Caramel Rim", 0.77f, new Vector3(0f, -0.014f, 0f), DepthColor(cell.State));

                hex.AddComponent<MeshFilter>().sharedMesh = CreateHexMesh(0.66f);
                MeshRenderer renderer = hex.AddComponent<MeshRenderer>();
                renderer.material = CreateHiveRuntimeMaterial();
                renderer.material.color = StateColor(cell.State);
                MeshCollider collider = hex.AddComponent<MeshCollider>();
                collider.sharedMesh = hex.GetComponent<MeshFilter>().sharedMesh;
                hex.AddComponent<HiveViewCellMarker>().CellId = cell.CellId;

                GameObject rim = new GameObject("Hive Hex Rim " + cell.CellId);
                rim.name = "Hive Hex Rim " + cell.CellId;
                rim.transform.SetParent(hex.transform, false);
                rim.transform.localPosition = new Vector3(0f, 0.012f, 0f);
                rim.AddComponent<MeshFilter>().sharedMesh = CreateHexMesh(cell.CellId == focusedCellId ? 0.93f : 0.82f);
                MeshRenderer rimRenderer = rim.AddComponent<MeshRenderer>();
                rimRenderer.material = CreateHiveRuntimeMaterial();
                if (rimRenderer != null) rimRenderer.material.color = RimColor(cell, cell.CellId == focusedCellId);

                GameObject highlight = new GameObject("Hive Hex Wax Highlight " + cell.CellId);
                highlight.transform.SetParent(hex.transform, false);
                highlight.transform.localPosition = new Vector3(-0.10f, 0.026f, -0.12f);
                highlight.AddComponent<MeshFilter>().sharedMesh = CreateHexMesh(0.31f);
                MeshRenderer highlightRenderer = highlight.AddComponent<MeshRenderer>();
                highlightRenderer.material = CreateHiveRuntimeMaterial();
                highlightRenderer.material.color = HighlightColor(cell.State);
                CreateWaxGrain(hex.transform, cell);
                CreateStateTokenVisuals(hex.transform, cell, cell.CellId == focusedCellId);

                GameObject badge = GameObject.CreatePrimitive(PrimitiveType.Cube);
                badge.name = "Hive State Badge " + cell.CellId + " " + StateBadge(cell.State);
                badge.transform.SetParent(hex.transform, false);
                badge.transform.localPosition = new Vector3(0.36f, 0.095f, 0.36f);
                badge.transform.localScale = BadgeScale(cell.State);
                Renderer badgeRenderer = badge.GetComponent<Renderer>();
                if (badgeRenderer != null) badgeRenderer.material.color = BadgeColor(cell.State);
                CreateZoneProp(hex.transform, cell);
            }

            CreateQueenCore(root.transform);
        }

        public static void HandlePointer(Camera camera)
        {
            if (camera == null || !Input.GetMouseButtonDown(0)) return;
            if (PremiumUiBlocksWorldInput()) return;
            Ray ray = camera.ScreenPointToRay(Input.mousePosition);
            if (Physics.Raycast(ray, out RaycastHit hit, 200f))
            {
                HiveViewCellMarker marker = hit.collider.GetComponent<HiveViewCellMarker>() ?? hit.collider.GetComponentInParent<HiveViewCellMarker>();
                if (marker != null && !string.IsNullOrWhiteSpace(marker.CellId))
                {
                    focusedCellId = marker.CellId;
                    lastTouchFeedback = "Selection ruche: " + focusedCellId;
                    RefreshSelectionRims();
                }
            }
        }

        // --- External host bridge (Environment2D5D HiveMap integration) ---
        // Minimal public entry points so a scene outside this monolith's own SpatialV3
        // flow can reuse the mini-chat / full "CHAT ROYAL" screen widgets (EnsureChatData
        // is hardcoded local demo data, not server-backed; DrawPremiumPanel/DrawChatScreen
        // are self-contained IMGUI drawing) WITHOUT calling EnsureSceneObjects(), which
        // builds an entire second 3D hex-grid hive scene these widgets don't need. Verified
        // by reading EnsureChatData, MiniChatFloatingShouldRender, DrawPremiumPanel and
        // DrawChatScreen: none of them touch `root`/the hex cells/anything EnsureSceneObjects
        // creates.
        //
        // DrawInternal() ALSO never calls EnsureSceneObjects() (confirmed: that method has
        // exactly one call site, LivingHiveDemoBootstrap.Start(), outside this file
        // entirely) and returns immediately after drawing the splash/login gate while
        // splashAuthGateState != EnteredHive. So Draw(fps, compact) itself is safe to call
        // for the splash/login flow too, as long as the caller stops calling it once
        // EnteredHive (to avoid it proceeding into the full hive-view UI, which HiveMap has
        // its own uGUI replacement for).
        public static bool HasEnteredHiveForExternalHost => splashAuthGateState == SplashAuthGateState.EnteredHive;

        // Entering the hive (via the splash's "Jouer en demo locale"/login flow)
        // auto-starts a guided onboarding tutorial (e.g. "DefenseWelcome"), which blocks
        // MiniChatFloatingShouldRender (and presumably other overlays) until completed.
        // HiveMap doesn't reuse the monolith's tutorial UI, so there's no way for the
        // player to actually advance/dismiss it here — this skips it outright so the
        // reused widgets (mini-chat, etc.) aren't silently blocked forever.
        public static void SkipGuidedTutorialForExternalHost()
        {
            guidedCollectionTutorialStep = GuidedCollectionTutorialStep.Inactive;
        }

        // M043Y-CL: this used to be `communicationPanelOpen`, which is actually the small
        // persistent floating mini-chat's own flag (see its other name, MiniChatOpenForProof,
        // same field) - true almost all the time since the mini-chat is meant to float
        // non-modally alongside the rest of the HUD. Every real consumer of this property
        // (HiveMapOverlayInputGateBootstrap, HiveMapQueueSidebarBootstrap, AnyModalOpenForExternalHost)
        // wants "is a full-screen exclusive Communication surface open", the same meaning
        // BarrackOverlayOpenForExternalHost/AllianceOverlayOpenForExternalHost/etc. have for
        // their own screens - so it was blocking/hiding the entire HUD (top resource bar,
        // bottom rail, queue sidebar, world decorations) any time the mini-chat was simply
        // visible, not just when the actual CHAT ROYAL/Mail screen was open (Jeff, 2026-09-03:
        // "tu efface tout... le menu, les files d'attente, la barre de ressources du haut").
        // chatScreenOpen/courierScreenOpen are the two real full-screen states drawn inside
        // DrawCommunicationOverlayForExternalHost - this now matches them, not the mini-chat.
        public static bool CommunicationOverlayOpenForExternalHost => chatScreenOpen || courierScreenOpen;

        // M043Y-CL: the small persistent floating mini-chat is non-modal by design (Jeff:
        // it must keep the rest of the HUD - top resource bar, bottom rail, queue sidebar -
        // visible while open, unlike the real full-screen Chat Royal/Mail screens above).
        // World decorations (production ready-glow/bee-swirl badges) still must not paint
        // through ITS panel specifically though, so this exposes just enough for callers to
        // do a precise per-rect overlap check instead of a blanket full-screen hide.
        public static bool MiniChatOnlyOpenForExternalHost => communicationPanelOpen && !chatScreenOpen && !courierScreenOpen;

        public static Rect MiniChatFloatingRectForExternalHost => MiniChatFloatingRectForProof(IsPortraitLayout(), Screen.width, Screen.height);

        public static Rect MiniChatOcclusionRectForExternalHost => MiniChatFloatingOcclusionRect(false);

        // EnsureStyles() touches GUI.skin, which throws outside an OnGUI call — this can
        // be invoked from a uGUI Button's onClick (EventSystem.Update, not OnGUI), so it
        // must stay style-free. DrawCommunicationOverlayForExternalHost (called from the
        // real OnGUI every frame) already calls EnsureStyles() before drawing.
        public static void ToggleCommunicationOverlayForExternalHost()
        {
            ToggleMiniChat();
        }

        public static void CloseCommunicationOverlayForExternalHost()
        {
            courierScreenOpen = false;
            CloseChatScreen();
            CloseMiniChat();
        }

        // MAIL tab inside the Communication overlay: HiveMap's 5-button menu merged the
        // old SandboxPlayground rail's separate "Mail" button (-> OpenCourierScreen /
        // DrawCourierScreen, the "COURRIER" screen) into the same Communication button as
        // chat, so the switch between the two now happens as a tab inside this overlay
        // instead of via two different rail buttons. Same EnsureSceneObjects()-free
        // guarantee as the rest of this bridge region.
        public static bool MailOverlayOpenForExternalHost => courierScreenOpen;

        public static void OpenMailOverlayForExternalHost()
        {
            if (!communicationPanelOpen) OpenMiniChat();
            CloseChatScreen();
            OpenCourierScreen();
        }

        private static void SwitchToChatFromMailForExternalHost()
        {
            courierScreenOpen = false;
            OpenChatScreen();
        }

        public static void DrawCommunicationOverlayForExternalHost(bool compact)
        {
            if (!communicationPanelOpen) return;
            EnsureStyles();
            int previousDepth = GUI.depth;
            if (chatScreenOpen || courierScreenOpen) GUI.depth = HiveMapUiOcclusion.ModalWindowGuiDepth;
            try
            {
                if (courierScreenOpen) DrawCourierScreen(compact);
                else if (chatScreenOpen) DrawChatScreen(compact);
                else DrawMiniChatFloating(compact, false);
                if (chatScreenOpen || courierScreenOpen) DrawCommunicationTabBarForExternalHost(compact);
            }
            finally
            {
                GUI.depth = previousDepth;
            }
        }

        private static void DrawCommunicationTabBarForExternalHost(bool compact)
        {
            bool onMail = courierScreenOpen;
            float tabWidth = compact ? 84f : 100f;
            float tabHeight = 30f;
            Rect chatTab = new Rect((Screen.width - tabWidth * 2f) / 2f, 44f, tabWidth, tabHeight);
            Rect mailTab = new Rect(chatTab.x + tabWidth, chatTab.y, tabWidth, tabHeight);

            DrawPremiumPanel(chatTab, onMail ? new Color(0.05f, 0.04f, 0.025f, 0.90f) : new Color(1f, 0.60f, 0.14f, 0.95f), new Color(0.86f, 0.58f, 0.16f, 0.85f));
            GUI.Label(chatTab, "CHAT", new GUIStyle(centeredTinyLabelStyle) { fontSize = 10, fontStyle = FontStyle.Bold });
            if (GUI.Button(chatTab, string.Empty, GUIStyle.none) && onMail)
            {
                AudioManager.Instance?.PlayUIClick();
                SwitchToChatFromMailForExternalHost();
            }

            DrawPremiumPanel(mailTab, onMail ? new Color(1f, 0.60f, 0.14f, 0.95f) : new Color(0.05f, 0.04f, 0.025f, 0.90f), new Color(0.86f, 0.58f, 0.16f, 0.85f));
            GUI.Label(mailTab, "MAIL", new GUIStyle(centeredTinyLabelStyle) { fontSize = 10, fontStyle = FontStyle.Bold });
            if (GUI.Button(mailTab, string.Empty, GUIStyle.none) && !onMail)
            {
                AudioManager.Instance?.PlayUIClick();
                OpenMailOverlayForExternalHost();
            }
        }

        // Settings ("Parametres") panel — real preferences (reduced motion, economy mode,
        // sound, music, language), PlayerPrefs-backed, not a placeholder. Replaces
        // LivingHiveMenuCanvas's old local uGUI placeholder (4 toggles wired to nothing) —
        // see HiveMapSettingsBootstrap / LivingHiveSettingsBridge for the wiring. Same
        // EnsureSceneObjects()-free guarantee as Communication above:
        // DrawMobileComfortSettingsPanel only touches PlayerPrefs-backed preference state.
        public static bool SettingsOverlayOpenForExternalHost => activeMainMenuId == "Settings";

        public static void OpenSettingsOverlayForExternalHost()
        {
            EnsureMobileComfortPreferencesLoaded();
            activeMainMenuId = "Settings";
        }

        public static void CloseSettingsOverlayForExternalHost()
        {
            activeMainMenuId = string.Empty;
        }

        public static void ToggleSettingsOverlayForExternalHost()
        {
            if (SettingsOverlayOpenForExternalHost) CloseSettingsOverlayForExternalHost();
            else OpenSettingsOverlayForExternalHost();
        }

        public static void DrawSettingsOverlayForExternalHost(bool compact)
        {
            if (!SettingsOverlayOpenForExternalHost) return;
            EnsureStyles();
