        private static void DrawSplashTab(Rect rect, string label, bool active, SplashAuthGateState target)
        {
            DrawPremiumPanel(
                rect,
                active ? new Color(0.62f, 0.34f, 0.055f, 0.96f) : new Color(0.12f, 0.09f, 0.045f, 0.95f),
                active ? new Color(1f, 0.80f, 0.18f, 1f) : new Color(0.78f, 0.54f, 0.18f, 0.84f));
            GUI.Label(rect, label, active ? activeNavButtonStyle : navButtonStyle);

            // The splash remains interactive even if a previous overlay left GUI.enabled false.
            bool previousEnabled = GUI.enabled;
            GUI.enabled = true;
            bool clicked = GUI.Button(rect, string.Empty, GUIStyle.none);
            GUI.enabled = previousEnabled;
            if (clicked)
            {
                splashAuthGateState = target;
                splashAuthMessage = target == SplashAuthGateState.Splash
                    ? "Choisis une entree demo locale. Aucun compte serveur live."
                    : "Mode demo local. Validation minimale uniquement.";
            }
        }

