                DrawSplashDeveloperRouteButton(new Rect(menu.x + 12f + (buttonWidth + gap), rowY, buttonWidth, buttonHeight), "Connexion", SplashDevelopmentSceneConfig.LoginScenePath, false);
                DrawSplashSkipActOneButton(new Rect(menu.x + 12f + (buttonWidth + gap) * 2f, rowY, buttonWidth, buttonHeight));
            }

            rowY += buttonHeight + gap;
            DrawDebugToggleButton(new Rect(menu.x + 12f, rowY, menu.width - 24f, buttonHeight), "Contours SVG zones (Debug)", ref showReferenceContoursDebug);
        }

        private static void DrawSplashDeveloperRouteButton(Rect rect, string label, string scenePath, bool highlighted)
        {
