        private static void DrawLoginGate(Rect panel, float y, bool portrait)
        {
            float pad = portrait ? 16f : 30f;
            float width = panel.width - pad * 2f;
            ConnectionTruthState truth = CurrentConnectionTruthState();

            bool operationPending = IsMobileAccountSessionOperationPending();
            bool authenticated = truth == ConnectionTruthState.AuthenticatedLive ||
                truth == ConnectionTruthState.AuthenticatedLocal;
            bool canCollectCredentials = truth == ConnectionTruthState.Ready;
            bool googleOperationPending = IsMobileGoogleLoginPending();
            bool googleReady = !authenticated && truth == ConnectionTruthState.Ready && mobileAccountSessionClient != null && !string.IsNullOrWhiteSpace(mobileGoogleOAuthClientId) &&
                mobileGoogleLoginRequestFactory != null;

            // Le contenu (titre + carte de disponibilite + champs/boutons) peut depasser la
            // hauteur du panneau sur les viewports courts (paysage bas, petite fenetre Game
            // view) - tout est dessine en coordonnees locales dans une scrollview pour rester
            // atteignable au lieu d'etre coupe silencieusement.
            float viewportHeight = Mathf.Max(80f, (panel.yMax - 84f) - y);
            Rect viewport = new Rect(panel.x + pad, y, width, viewportHeight);
            const float ContentBudget = 640f;
            float innerWidth = width - 18f;

            loginGateScroll = GUI.BeginScrollView(viewport, loginGateScroll, new Rect(0f, 0f, innerWidth, ContentBudget));
            float ly = 0f;

            GUI.Label(new Rect(0f, ly, innerWidth, 34f), BeeLocalization.Text("splash.account.title", "Compte officiel"), new GUIStyle(titleStyle) { fontSize = portrait ? 21 : 26 });
            ly += portrait ? 44f : 48f;

            float readinessHeight = portrait ? 146f : 126f;
            DrawAccountSessionReadinessCard(new Rect(0f, ly, innerWidth, readinessHeight), portrait);
            ly += readinessHeight + (portrait ? 16f : 18f);

            if (truth == ConnectionTruthState.Offline)
            {
                bool previousEnabledReconnect = GUI.enabled;
                GUI.enabled = previousEnabledReconnect && !operationPending;
                if (DrawSplashPrimaryButton(
                    new Rect(0f, ly, innerWidth, portrait ? 54f : 60f),
                    BeeLocalization.Text("splash.account.reconnect", "Reprendre la connexion"),
                    "world"))
                {
                    BeginMobileAccountReconnect();
                }
                GUI.enabled = previousEnabledReconnect;
                GUI.EndScrollView();
                return;
            }

            if (authenticated)
            {
                if (DrawSplashPrimaryButton(
                    new Rect(0f, ly, innerWidth, portrait ? 54f : 60f),
                    BeeLocalization.Text("splash.login.official_continue", "Continuer avec la session officielle"),
                    "queen"))
                {
                    EnterHiveFromSplash(mobileAccountSessionClient.ServerGameplayAuthorityGranted
                        ? "official_server_session"
                        : "official_account_local_preview");
                }

                ly += portrait ? 66f : 74f;
                bool previousEnabledAuth = GUI.enabled;
                GUI.enabled = previousEnabledAuth && !operationPending;
                if (DrawSplashSecondaryButton(
                    new Rect(0f, ly, innerWidth, portrait ? 48f : 50f),
                    BeeLocalization.Text("splash.login.logout", "Déconnecter cet appareil")))
                {
                    BeginMobileAccountLogout();
                }
                GUI.enabled = previousEnabledAuth;
                GUI.EndScrollView();
                return;
            }

            if (canCollectCredentials)
            {
                float fieldHeight = portrait ? 46f : 44f;
                mobileAccountEmail = DrawAuthField(
                    new Rect(0f, ly, innerWidth, fieldHeight),
                    BeeLocalization.Text("splash.login.official_email", "Courriel du compte"),
                    mobileAccountEmail);
                ly += fieldHeight + (portrait ? 20f : 18f);
                mobileAccountPassword = DrawAuthPasswordField(
                    new Rect(0f, ly, innerWidth, fieldHeight),
                    BeeLocalization.Text("splash.login.official_password", "Mot de passe"),
                    mobileAccountPassword);
                ly += fieldHeight + (portrait ? 14f : 12f);

                bool previousEnabled = GUI.enabled;
                GUI.enabled = previousEnabled && !operationPending;
                string submitLabel = operationPending
                    ? BeeLocalization.Text("splash.login.official_connecting", "Connexion sécurisée…")
                    : BeeLocalization.Text("splash.login.official_submit", "Se connecter en sécurité");
                if (DrawSplashPrimaryButton(
                    new Rect(0f, ly, innerWidth, portrait ? 52f : 54f),
                    submitLabel,
                    "world"))
                {
                    BeginMobileAccountLogin();
                }
                GUI.enabled = previousEnabled;
                ly += portrait ? 62f : 66f;
            }

            if (googleReady)
            {
                bool previousEnabledGoogle = GUI.enabled;
                GUI.enabled = previousEnabledGoogle && !operationPending && !googleOperationPending;
                string googleLabel = googleOperationPending
                    ? BeeLocalization.Text("splash.login.official_connecting", "Connexion sécurisée…")
                    : BeeLocalization.Text("splash.login.google_button", "Se connecter avec Google");
                if (DrawSplashPrimaryButton(new Rect(0f, ly, innerWidth, portrait ? 52f : 54f), googleLabel, "queen"))
                {
                    BeginMobileGoogleLogin();
                }
                GUI.enabled = previousEnabledGoogle;
                ly += (portrait ? 52f : 54f) + (portrait ? 14f : 12f);
            }

            if (DrawSplashPrimaryButton(new Rect(0f, ly, innerWidth, portrait ? 54f : 60f), BeeLocalization.Text("splash.login.local_demo", "Continuer en démo locale"), "hive"))
            {
                EnterHiveFromSplash("demo_local_guest");
            }
            ly += portrait ? 54f : 60f;

            if (!googleReady)
            {
                ly += portrait ? 14f : 12f;
                DrawDisabledFutureAuthNotice(new Rect(0f, ly, innerWidth, portrait ? 44f : 40f));
                ly += portrait ? 44f : 40f;
            }

            GUI.EndScrollView();
        }

