        private static void BeginSubmitDisplayName()
        {
            if (createAccountDisplayNameChecking) return;
            string name = (createAccountDisplayNameInput ?? string.Empty).Trim();
            if (name.Length < 3 || name.Length > 20)
            {
                SetSplashAuthMessage("splash.create_account.error.display_name_invalid", true);
                return;
            }

            createAccountDisplayNameChecking = true;
            SetSplashAuthMessage("splash.create_account.checking", false);
            createAccountDisplayNameTask = MobileAccountSessionRuntimeBootstrap.SubmitDisplayNameAsync(name);
        }

