        private static bool ValidateLocalDemoProfile()
        {
            if (!string.IsNullOrWhiteSpace(splashAuthUserName) && splashAuthUserName.Trim().Length >= 3)
            {
                SetSplashAuthMessage("splash.message.local_profile_created", false, splashAuthUserName.Trim());
                return true;
