        private static void EnterHiveFromSplash(string route)
        {
            splashAuthGateState = SplashAuthGateState.EnteredHive;
            splashAuthLastRoute = route;
            SetSplashAuthMessage("splash.message.entered", false, route);
            bool officialGameplay = mobileAccountSessionClient != null &&
                mobileAccountSessionClient.State == MobileAccountSessionState.Authenticated &&
                mobileAccountSessionClient.ServerGameplayAuthorityGranted;
            localPreviewLoopMessage = officialGameplay
                ? BeeLocalization.Text("splash.message.official_session", "Session officielle · serveur autoritaire")
                : BeeLocalization.Text("splash.message.local_preview", "Aperçu non officiel · simulation locale");
            SetReferenceSurfaceModeForProof("hive");
            BeginGuidedCollectionTutorial();
            LoadHiveMapScene();
        }

        private static void LoadHiveMapScene()
        {
            string scenePath = SplashDevelopmentSceneConfig.HiveMapScenePath;
#if UNITY_EDITOR
            if (!SplashDevelopmentSceneConfig.IsSceneEnabledInBuildSettings(scenePath))
            {
                UnityEditor.EditorBuildSettings.scenes = new[]
                {
                    new UnityEditor.EditorBuildSettingsScene(scenePath, true)
                }.Concat(UnityEditor.EditorBuildSettings.scenes).ToArray();
            }
#endif
            string message;
            if (SplashDevelopmentSceneConfig.TryOpenScene(scenePath, out message))
            {
                SetSplashAuthMessage(message, false);
            }
            else
            {
                SetSplashAuthMessage("Echec chargement HiveMap: " + message, true);
            }
        }

        private static void SkipActOneTutorialForDevelopment()
        {
            int preSkipWorkers = localPreviewWorkers;
            int preSkipSoldiers = localPreviewSoldiers;
            int preSkipGuardians = localPreviewGuardians;
            int preSkipScouts = localPreviewScouts;
            int preSkipWingrunners = localPreviewWingrunners;
            int preSkipDarters = localPreviewDarters;
            float preSkipHoney = localPreviewHoney;
            float preSkipWax = localPreviewWax;
            float preSkipPollen = localPreviewPollen;
            float preSkipCapacityUsed = localPreviewCapacityUsed;
            Dictionary<string, int> preSkipBuildingLevels = new Dictionary<string, int>(localPreviewBuildingLevels, StringComparer.Ordinal);

            SetPlayableHiveLoopProofState("idle");

            // SetPlayableHiveLoopProofState overwrites every stat with a fixed proof/screenshot baseline
            // (built for internal capture harnesses, reused here for the real player-facing skip button) -
            // restore whatever the player had actually earned before the reset, never letting it regress (PB-007).
            localPreviewHoney = Mathf.Max(localPreviewHoney, preSkipHoney);
            localPreviewWax = Mathf.Max(localPreviewWax, preSkipWax);
            localPreviewPollen = Mathf.Max(localPreviewPollen, preSkipPollen);
            localPreviewCapacityUsed = Mathf.Min(localPreviewCapacityMax, Mathf.Max(localPreviewCapacityUsed, preSkipCapacityUsed));
            LocalPreviewHiveProgressCodec.MergePopulationCount(localPreviewHiveProgress, "workers", preSkipWorkers);
            LocalPreviewHiveProgressCodec.MergePopulationCount(localPreviewHiveProgress, "soldiers", preSkipSoldiers);
            LocalPreviewHiveProgressCodec.MergePopulationCount(localPreviewHiveProgress, "guardians", preSkipGuardians);
            LocalPreviewHiveProgressCodec.MergePopulationCount(localPreviewHiveProgress, "scouts", preSkipScouts);
            LocalPreviewHiveProgressCodec.MergePopulationCount(localPreviewHiveProgress, "wingrunners", preSkipWingrunners);
            LocalPreviewHiveProgressCodec.MergePopulationCount(localPreviewHiveProgress, "darters", preSkipDarters);
            foreach (KeyValuePair<string, int> preSkipBuildingLevel in preSkipBuildingLevels)
            {
                LocalPreviewHiveProgressCodec.MergeBuildingLevel(localPreviewHiveProgress, preSkipBuildingLevel.Key, preSkipBuildingLevel.Value);
            }

            ClaimGuidedChapterReward(1, GuidedChapterOneRewardHoney, 0f, 0f);
            ClaimGuidedChapterReward(2, GuidedChapterTwoRewardHoney, GuidedChapterTwoRewardWax, 0f);
            ClaimGuidedChapterReward(3, GuidedChapterThreeRewardHoney, 0f, GuidedChapterThreeRewardPollen);
            ClaimGuidedChapterReward(4, GuidedChapterFourRewardHoney, GuidedChapterFourRewardWax, 0f);
            ClaimGuidedChapterReward(5, GuidedChapterFiveRewardHoney, GuidedChapterFiveRewardWax, 0f);

            LocalPreviewHiveProgressCodec.MergeBuildingLevel(localPreviewHiveProgress, "wax_workshop", 3);
            LocalPreviewHiveProgressCodec.MergeBuildingLevel(localPreviewHiveProgress, "guard_post", 3);
            LocalPreviewHiveProgressCodec.MergeBuildingLevel(localPreviewHiveProgress, "honey_storage", 2);
            LocalPreviewHiveProgressCodec.MergePopulationCount(localPreviewHiveProgress, "workers", 34);
            LocalPreviewHiveProgressCodec.MergePopulationCount(localPreviewHiveProgress, "soldiers", 20);
            LocalPreviewHiveProgressCodec.MergePopulationCount(localPreviewHiveProgress, "guardians", 10);
            LocalPreviewHiveProgressCodec.MergePopulationCount(localPreviewHiveProgress, "scouts", 6);

            localPreviewBuildingLevels.Clear();
            for (int i = 0; i < localPreviewHiveProgress.buildings.Count; i++)
            {
                LocalPreviewBuildingProgress entry = localPreviewHiveProgress.buildings[i];
                localPreviewBuildingLevels[entry.hotspotId] = entry.level;
            }
            localPreviewWorkers = localPreviewHiveProgress.workers;
            localPreviewSoldiers = localPreviewHiveProgress.soldiers;
            localPreviewGuardians = localPreviewHiveProgress.guardians;
            localPreviewScouts = localPreviewHiveProgress.scouts;
            localPreviewWingrunners = localPreviewHiveProgress.wingrunners;
            localPreviewDarters = localPreviewHiveProgress.darters;
            localPreviewHiveProgressStore?.Write(JsonUtility.ToJson(localPreviewHiveProgress));

            splashAuthGateState = SplashAuthGateState.EnteredHive;
            splashAuthLastRoute = "dev_skip_act_one";
            SetSplashAuthMessage("splash.message.entered", false, "dev_skip_act_one");
            localPreviewLoopMessage = BeeLocalization.Text("splash.message.local_preview", "Aperçu non officiel · simulation locale");
            SetReferenceSurfaceModeForProof("hive");
            localPreviewSessionPrompt = "Developpement : Acte I termine, jeu libre.";
            LoadHiveMapScene();
        }

