        private static bool IsMobileAccountSessionOperationPending()
        {
            return (mobileAccountLoginTask != null && !mobileAccountLoginTask.IsCompleted) ||
                (mobileAccountLogoutTask != null && !mobileAccountLogoutTask.IsCompleted);
        }

        private static bool IsMobileGoogleLoginPending()
        {
            return (mobileGoogleOAuthFlowTask != null && !mobileGoogleOAuthFlowTask.IsCompleted) ||
                (mobileGoogleLoginTask != null && !mobileGoogleLoginTask.IsCompleted);
        }

        private static void BeginMobileGoogleLogin()
        {
            if (IsMobileAccountSessionOperationPending() || IsMobileGoogleLoginPending() || mobileAccountSessionClient == null ||
                mobileGoogleLoginRequestFactory == null || string.IsNullOrWhiteSpace(mobileGoogleOAuthClientId))
            {
                SetSplashAuthMessage("splash.message.official_unavailable", true);
                return;
            }

            try
            {
                MobileAccountSessionRuntimeBootstrap.CloseGameplayForSignedOutSession();
                mobileGoogleOAuthFlowTask = GoogleOAuthLoginFlow.RunAsync(mobileGoogleOAuthClientId, CancellationToken.None);
                SetSplashAuthMessage("splash.login.official_connecting", false);
            }
            catch (Exception)
            {
                SetSplashAuthMessage("splash.login.error.google_failed", true);
            }
        }

        private static void BeginMobileAccountLogin()
        {
            if (IsMobileAccountSessionOperationPending() || mobileAccountSessionClient == null ||
                mobileAccountLoginRequestFactory == null || !accountSessionGate.CanSubmitLogin)
            {
                SetSplashAuthMessage("splash.message.official_unavailable", true);
                mobileAccountPassword = string.Empty;
                return;
            }

            string email = mobileAccountEmail == null ? string.Empty : mobileAccountEmail.Trim();
            string password = mobileAccountPassword ?? string.Empty;
            try
            {
                MobileAccountSessionRuntimeBootstrap.CloseGameplayForSignedOutSession();
                MobileAccountLoginRequest request = mobileAccountLoginRequestFactory(email, password);
                mobileAccountLoginTask = mobileAccountSessionClient.LoginAsync(request);
                SetSplashAuthMessage("splash.login.official_connecting", false);
            }
            catch (MobileAccountSessionException exception)
            {
                SetSplashAuthMessage(MobileAccountErrorMessageKey(exception.SafeCode), true);
            }
            catch
            {
                SetSplashAuthMessage("splash.login.error.generic", true);
            }
            finally
            {
                password = string.Empty;
                mobileAccountPassword = string.Empty;
            }
        }

        private static void BeginMobileAccountReconnect()
        {
            if (IsMobileAccountSessionOperationPending() || mobileAccountSessionClient == null ||
                mobileAccountSessionClient.State != MobileAccountSessionState.Offline)
                return;

            mobileAccountLoginTask = mobileAccountSessionClient.RestoreOrRefreshAsync();
            SetSplashAuthMessage("splash.login.official_connecting", false);
        }

        private static void BeginMobileAccountLogout()
        {
            if (IsMobileAccountSessionOperationPending() || mobileAccountSessionClient == null) return;
            mobileAccountEmail = string.Empty;
            mobileAccountPassword = string.Empty;
            mobileAccountLogoutTask =
                LogoutMobileAccountAndPurgeGameplayAsync(
                    mobileAccountSessionClient);
            SetSplashAuthMessage("splash.login.logging_out", false);
        }

        private static async Task LogoutMobileAccountAndPurgeGameplayAsync(
            MobileAccountSessionClient sessionClient)
        {
            await MobileAccountSessionRuntimeBootstrap
                .PurgeGameplayOutboxForExplicitLogoutAsync();
            await sessionClient.LogoutAsync();
        }

        private static void PumpMobileAccountSessionOperations()
        {
            if (mobileGoogleOAuthFlowTask != null && mobileGoogleOAuthFlowTask.IsCompleted)
            {
                Task<GoogleOAuthLoginFlow.Result> completedFlow = mobileGoogleOAuthFlowTask;
                mobileGoogleOAuthFlowTask = null;
                try
                {
                    GoogleOAuthLoginFlow.Result flowResult = completedFlow.GetAwaiter().GetResult();
                    GoogleLoginRequest request = mobileGoogleLoginRequestFactory(flowResult.AuthorizationCode, flowResult.CodeVerifier, flowResult.RedirectUri);
                    mobileGoogleLoginTask = mobileAccountSessionClient.LoginWithGoogleAsync(request);
                }
                catch (MobileAccountSessionException exception)
                {
                    Debug.LogWarning("Bee Kingdom Google OAuth flow failed with safe code '" + exception.SafeCode + "': " + exception.Message);
                    SetSplashAuthMessage(MobileAccountErrorMessageKey(exception.SafeCode), true);
                }
                catch (Exception exception)
                {
                    Debug.LogWarning("Bee Kingdom Google OAuth flow failed unexpectedly (" + exception.GetType().FullName + "): " + exception.Message);
                    SetSplashAuthMessage("splash.login.error.google_failed", true);
                }
            }

            if (mobileGoogleLoginTask != null && mobileGoogleLoginTask.IsCompleted)
            {
                Task<GameAccountSession> completedGoogleLogin = mobileGoogleLoginTask;
                mobileGoogleLoginTask = null;
                try
                {
                    GameAccountSession session = completedGoogleLogin.GetAwaiter().GetResult();
                    if (session.IsNewAccount || !session.IsOnboarded)
                    {
                        newAccountNeedsDisplayName = true;
                        createAccountDisplayNameInput = string.Empty;
                        SetSplashAuthMessage("splash.create_account.title", false);
                    }
                    else
                    {
                        MobileAccountSessionRuntimeBootstrap.TryConfigureGameplayForActiveSession();
                        SetSplashAuthMessage("splash.login.connected", false);
                    }
                }
                catch (MobileAccountSessionException exception)
                {
                    Debug.LogWarning("Bee Kingdom Google login failed with safe code '" + exception.SafeCode + "': " + exception.Message);
                    SetSplashAuthMessage(MobileAccountErrorMessageKey(exception.SafeCode), true);
                }
                catch (Exception exception)
                {
                    Debug.LogWarning("Bee Kingdom Google login post-processing failed unexpectedly (" + exception.GetType().FullName + "): " + exception.Message);
                    SetSplashAuthMessage("splash.login.error.generic", true);
                }
            }

            if (createAccountDisplayNameTask != null && createAccountDisplayNameTask.IsCompleted)
            {
                Task<MobileAccountSessionRuntimeBootstrap.DisplayNameSubmitResult> completedDisplayName = createAccountDisplayNameTask;
                createAccountDisplayNameTask = null;
                createAccountDisplayNameChecking = false;
                MobileAccountSessionRuntimeBootstrap.DisplayNameSubmitResult result;
                try
                {
                    result = completedDisplayName.GetAwaiter().GetResult();
                }
                catch (Exception)
                {
                    result = MobileAccountSessionRuntimeBootstrap.DisplayNameSubmitResult.Failure("auth.display_name_rejected");
                }

                if (result.Succeeded)
                {
                    newAccountNeedsDisplayName = false;
                    MobileAccountSessionRuntimeBootstrap.TryConfigureGameplayForActiveSession();
                    EnterHiveFromSplash("official_new_account_onboarded");
                    SetSplashAuthMessage("splash.create_account.success", false);
                }
                else
                {
                    SetSplashAuthMessage(MobileAccountErrorMessageKey(result.ErrorCode), true);
                }
            }

            if (mobileAccountLoginTask != null && mobileAccountLoginTask.IsCompleted)
            {
                Task<GameAccountSession> completed = mobileAccountLoginTask;
                mobileAccountLoginTask = null;
                try
                {
                    completed.GetAwaiter().GetResult();
                    mobileAccountEmail = string.Empty;
                    mobileAccountPassword = string.Empty;
                    MobileAccountSessionRuntimeBootstrap.TryConfigureGameplayForActiveSession();
                    SetSplashAuthMessage("splash.login.connected", false);
                }
                catch (MobileAccountSessionException exception)
                {
                    Debug.LogWarning("Bee Kingdom login failed with safe code '" + exception.SafeCode + "': " + exception.Message);
                    SetSplashAuthMessage(MobileAccountErrorMessageKey(exception.SafeCode), true);
                }
                catch (Exception exception)
                {
                    Debug.LogWarning("Bee Kingdom login post-processing failed unexpectedly (" + exception.GetType().FullName + "): " + exception.Message + "\n" + exception.StackTrace);
                    SetSplashAuthMessage("splash.login.error.generic", true);
                }
            }

            if (mobileAccountLogoutTask != null && mobileAccountLogoutTask.IsCompleted)
            {
                Task completed = mobileAccountLogoutTask;
                mobileAccountLogoutTask = null;
                try
                {
                    completed.GetAwaiter().GetResult();
                    SetSplashAuthMessage("splash.login.logged_out", false);
                }
                catch (MobileAccountSessionException exception)
                {
                    SetSplashAuthMessage(
                        exception.Error == MobileAccountSessionError.RemoteLogoutFailure
                            ? "splash.login.logged_out_remote_warning"
                            : MobileAccountErrorMessageKey(exception.SafeCode),
                        true);
                }
                catch
                {
                    SetSplashAuthMessage("splash.login.logged_out_remote_warning", true);
                }
                finally
                {
                    MobileAccountSessionRuntimeBootstrap.CloseGameplayForSignedOutSession();
                }
            }
        }

        private static string MobileAccountErrorMessageKey(string safeCode)
        {
            switch (safeCode)
            {
                case "auth.invalid_credentials":
                    return "splash.login.error.invalid_credentials";
                case "auth.account_locked":
                case "auth.rate_limited":
                    return "splash.login.error.account_locked";
                case "auth.account_disabled":
                    return "splash.login.error.account_disabled";
                case "auth.client_version_unsupported":
                    return "splash.login.error.client_version";
                case "auth.session_limit":
                    return "splash.login.error.session_limit";
                case "auth.google_sign_in_failed":
                    return "splash.login.error.google_failed";
                case "auth.display_name_taken":
                    return "splash.create_account.error.display_name_taken";
                case "auth.display_name_invalid":
                    return "splash.create_account.error.display_name_invalid";
                case "auth.unavailable":
                    return "splash.message.official_unavailable";
                case "auth.protected_storage_unavailable":
                case "auth.protected_storage_read_failed":
                case "auth.protected_storage_write_failed":
                case "auth.protected_storage_delete_failed":
                    return "splash.login.error.protected_storage";
                case "auth.session_expired":
                case "auth.session_missing":
                    return "splash.login.error.session_expired";
                default:
                    return "splash.login.error.generic";
            }
        }

        private static void SetSplashAuthMessage(string key, bool warning, params object[] arguments)
        {
            splashAuthMessage = arguments != null && arguments.Length > 0
                ? BeeLocalization.Format(key, arguments)
                : BeeLocalization.Text(key);
            splashAuthMessageLocale = BeeLocalization.CurrentLocale;
            splashAuthMessageIsWarning = warning;
        }

        private static void SetSplashAuthMessageLiteral(string message, bool warning)
        {
            splashAuthMessage = message ?? string.Empty;
            splashAuthMessageLocale = BeeLocalization.CurrentLocale;
            splashAuthMessageIsWarning = warning;
        }

