        private static Rect DrawWorldMapArtLayer(Texture2D art, bool portrait)
        {
            float minZoom = portrait ? 1.05f : 1.0f;
            float maxZoom = portrait ? 1.82f : 1.45f;
            worldMapTargetZoom = Mathf.Clamp(worldMapTargetZoom, minZoom, maxZoom);
            worldMapZoom = SmoothWorldMapZoom(worldMapZoom, worldMapTargetZoom, minZoom, maxZoom);
            float baseWidth = art.width > 0 ? art.width : 1536f;
            float baseHeight = art.height > 0 ? art.height : 1024f;
            float scale = Mathf.Max(Screen.width / baseWidth, Screen.height / baseHeight) * worldMapZoom;
            Vector2 focus = portrait ? new Vector2(baseWidth * 0.48f, baseHeight * 0.48f) : new Vector2(baseWidth * 0.50f, baseHeight * 0.50f);
            Rect artRect = new Rect(Screen.width * 0.5f - focus.x * scale + worldMapPan.x, Screen.height * 0.5f - focus.y * scale + worldMapPan.y, baseWidth * scale, baseHeight * scale);
            artRect = ClampReferenceArtRect(artRect);
            worldMapPan = new Vector2(artRect.x - (Screen.width * 0.5f - focus.x * scale), artRect.y - (Screen.height * 0.5f - focus.y * scale));
            GUI.DrawTexture(artRect, art, ScaleMode.StretchToFill, true);
            return artRect;
        }

        private static float SmoothWorldMapZoom(float current, float target, float minZoom, float maxZoom)
        {
            current = Mathf.Clamp(current, minZoom, maxZoom);
            target = Mathf.Clamp(target, minZoom, maxZoom);
            float dt = Mathf.Clamp(Time.unscaledDeltaTime > 0f ? Time.unscaledDeltaTime : 1f / 60f, 1f / 120f, 1f / 20f);
            float damped = Mathf.Lerp(current, target, 1f - Mathf.Exp(-WorldMapZoomDamping * dt));
            float maxStep = WorldMapMaxZoomSpeedPerSecond * dt;
            return Mathf.Clamp(Mathf.MoveTowards(current, damped, maxStep), minZoom, maxZoom);
        }

