        private static void DrawWorldMapRoute(Rect artRect, string fromId, string toId)
        {
            WorldMapPreviewNode from = WorldNodeById(fromId);
            WorldMapPreviewNode to = WorldNodeById(toId);
            Vector2 a = WorldMapPoint(artRect, from.Anchor);
            Vector2 b = WorldMapPoint(artRect, to.Anchor);
            Vector2 delta = b - a;
            float length = delta.magnitude;
            if (length <= 1f) return;

            Matrix4x4 previousMatrix = GUI.matrix;
            Color previous = GUI.color;
            GUIUtility.RotateAroundPivot(Mathf.Atan2(delta.y, delta.x) * Mathf.Rad2Deg, a);
            GUI.color = new Color(1f, 0.88f, 0.48f, 0.48f);
            for (float x = 18f; x < length - 18f; x += 18f)
            {
                GUI.DrawTexture(new Rect(a.x + x, a.y - 1.4f, 8f, 2.8f), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            }

            GUI.color = previous;
            GUI.matrix = previousMatrix;
        }

