        private static void HandleWorldMapNodeClick(Rect artRect, bool portrait)
        {
            Event current = Event.current;
            if (current == null) return;
            Rect mapRect = WorldMapInteractionRect(portrait);
            if (current.type == EventType.MouseMove)
            {
                hoveredWorldMapNodeId = WorldNodeAtScreenPoint(artRect, current.mousePosition, portrait).NodeId;
                return;
            }

            if (current.type == EventType.MouseDown && current.button == 0)
            {
                worldMapInputStart = current.mousePosition;
                worldMapInputStartedInMap = mapRect.Contains(current.mousePosition);
                hoveredWorldMapNodeId = WorldNodeAtScreenPoint(artRect, current.mousePosition, portrait).NodeId;
                return;
            }

            if (current.type != EventType.MouseUp || current.button != 0 || !worldMapInputStartedInMap) return;
            if (worldMapSelectionSuppressed || Vector2.Distance(worldMapInputStart, current.mousePosition) > ReferenceDragThresholdPixels)
            {
                worldMapInputStartedInMap = false;
                worldMapSelectionSuppressed = false;
                return;
            }

            WorldMapPreviewNode hit = WorldNodeAtScreenPoint(artRect, current.mousePosition, portrait);
            if (string.IsNullOrWhiteSpace(hit.NodeId)) return;
            focusedWorldMapNodeId = hit.NodeId;
            BeginReferenceFeedbackPulse(hit.PlayerOwned ? "preview" : hit.State.IndexOf("Server", StringComparison.OrdinalIgnoreCase) >= 0 ? "server" : "future");
            worldMapInputStartedInMap = false;
            worldMapSelectionSuppressed = false;
            current.Use();
        }

        private static WorldMapPreviewNode WorldNodeAtScreenPoint(Rect artRect, Vector2 point, bool portrait)
        {
            float hitRadius = portrait ? 30f : 42f;
            for (int i = WorldMapNodes.Length - 1; i >= 0; i--)
            {
                WorldMapPreviewNode node = WorldMapNodes[i];
                if (Vector2.Distance(WorldMapPoint(artRect, node.Anchor), point) <= hitRadius) return node;
            }

            return default;
        }

        private static Vector2 WorldMapPoint(Rect artRect, Vector2 normalized)
        {
            return new Vector2(artRect.x + artRect.width * normalized.x, artRect.y + artRect.height * normalized.y);
        }

        private static WorldMapPreviewNode FocusedWorldMapNode()
        {
            return WorldNodeById(focusedWorldMapNodeId);
        }

        private static WorldMapPreviewNode WorldNodeById(string nodeId)
        {
            for (int i = 0; i < WorldMapNodes.Length; i++)
            {
                if (WorldMapNodes[i].NodeId == nodeId) return WorldMapNodes[i];
            }

            return WorldMapNodes[0];
        }

        private static void HandleWorldMapGestures(Rect artRect, bool portrait)
        {
            if (PremiumUiBlocksWorldInput())
            {
                worldMapInputStartedInMap = false;
                worldMapSelectionSuppressed = false;
                return;
            }

            Rect mapRect = WorldMapInteractionRect(portrait);
            HandleWorldMapTouchGestures(mapRect);
            Event current = Event.current;
            if (current == null) return;

            if (current.type == EventType.ScrollWheel && mapRect.Contains(current.mousePosition))
            {
                float previousTarget = worldMapTargetZoom;
                float wheelStep = Mathf.Clamp(-current.delta.y * 0.035f, -WorldMapMaxPinchZoomStep, WorldMapMaxPinchZoomStep);
                worldMapTargetZoom = Mathf.Clamp(worldMapTargetZoom + wheelStep, portrait ? 1.05f : 1.0f, portrait ? 1.82f : 1.45f);
                KeepWorldMapPointUnderScreenPoint(artRect, current.mousePosition, previousTarget, worldMapTargetZoom);
                RecordWorldMapGesture("mouse-wheel-zoom", 0, Vector2.zero, wheelStep);
                current.Use();
                return;
            }

            if (current.type == EventType.MouseDrag && current.button == 0 && worldMapInputStartedInMap && mapRect.Contains(current.mousePosition))
            {
                worldMapPan += current.delta;
                worldMapSelectionSuppressed = true;
                RecordWorldMapGesture("mouse-pan", 1, current.delta, 0f);
                current.Use();
            }
        }

        private static void HandleWorldMapTouchGestures(Rect mapRect)
        {
            if (Input.touchCount == 0)
            {
                worldMapPinching = false;
                worldMapTouchPanning = false;
                worldMapLastPinchDistance = 0f;
                if (worldMapLastGestureMode != "proof") RecordWorldMapGesture("idle", 0, Vector2.zero, 0f);
                return;
            }

            if (Input.touchCount == 1)
            {
                worldMapPinching = false;
                worldMapLastPinchDistance = 0f;
                Touch touch = Input.GetTouch(0);
                Vector2 point = TouchToGuiPoint(touch.position);
                if (!mapRect.Contains(point)) return;
                Vector2 panDelta = new Vector2(touch.deltaPosition.x, -touch.deltaPosition.y);
                if (touch.phase == TouchPhase.Began)
                {
                    worldMapTouchPanning = false;
                    worldMapSelectionSuppressed = false;
                    RecordWorldMapGesture("one-finger-ready", 1, Vector2.zero, 0f);
                    return;
                }

                if (panDelta.magnitude < WorldMapTouchPanThresholdPixels && !worldMapTouchPanning)
                {
                    RecordWorldMapGesture("one-finger-hold", 1, Vector2.zero, 0f);
                    return;
                }

                worldMapTouchPanning = true;
                worldMapSelectionSuppressed = true;
                worldMapPan += panDelta;
                RecordWorldMapGesture("one-finger-pan", 1, panDelta, 0f);
                return;
            }

            Touch first = Input.GetTouch(0);
            Touch second = Input.GetTouch(1);
            Vector2 firstPoint = TouchToGuiPoint(first.position);
            Vector2 secondPoint = TouchToGuiPoint(second.position);
            if (!mapRect.Contains(firstPoint) || !mapRect.Contains(secondPoint))
            {
                worldMapPinching = false;
                worldMapTouchPanning = false;
                return;
            }

            float distance = Vector2.Distance(firstPoint, secondPoint);
            worldMapTouchPanning = false;
            worldMapSelectionSuppressed = true;
            if (!worldMapPinching || worldMapLastPinchDistance <= 1f)
            {
                worldMapPinching = true;
                worldMapLastPinchDistance = distance;
                RecordWorldMapGesture("two-finger-pinch-ready", Input.touchCount, Vector2.zero, 0f);
                return;
            }

            float pinchPixels = distance - worldMapLastPinchDistance;
            if (Mathf.Abs(pinchPixels) < WorldMapPinchThresholdPixels)
            {
                RecordWorldMapGesture("two-finger-pinch-threshold", Input.touchCount, Vector2.zero, 0f);
                return;
            }

            float delta = pinchPixels / Mathf.Max(1f, Mathf.Min(Screen.width, Screen.height));
            float zoomStep = Mathf.Clamp(delta * 1.6f, -WorldMapMaxPinchZoomStep, WorldMapMaxPinchZoomStep);
            worldMapTargetZoom = Mathf.Clamp(worldMapTargetZoom + zoomStep, IsPortraitLayout() ? 1.05f : 1.0f, IsPortraitLayout() ? 1.82f : 1.45f);
            worldMapLastPinchDistance = distance;
            RecordWorldMapGesture("two-finger-pinch-zoom", Input.touchCount, Vector2.zero, zoomStep);
        }

        private static void RecordWorldMapGesture(string mode, int touchCount, Vector2 panDelta, float pinchDelta)
        {
            worldMapLastGestureMode = mode;
            worldMapLastTouchCount = touchCount;
            worldMapLastPanDelta = panDelta;
            worldMapLastPinchDelta = pinchDelta;
        }

        private static void KeepWorldMapPointUnderScreenPoint(Rect artRect, Vector2 screenPoint, float previousZoom, float nextZoom)
        {
            if (Mathf.Approximately(previousZoom, nextZoom)) return;
            Vector2 normalized = new Vector2((screenPoint.x - artRect.x) / Mathf.Max(1f, artRect.width), (screenPoint.y - artRect.y) / Mathf.Max(1f, artRect.height));
            Vector2 before = new Vector2(artRect.x + artRect.width * normalized.x, artRect.y + artRect.height * normalized.y);
            float scale = nextZoom / Mathf.Max(0.01f, previousZoom);
            Vector2 after = new Vector2(artRect.x + artRect.width * scale * normalized.x, artRect.y + artRect.height * scale * normalized.y);
            worldMapPan += before - after;
        }

        private static Rect WorldMapInteractionRect(bool portrait)
        {
            if (portrait) return new Rect(0f, 102f, Screen.width, Mathf.Max(1f, Screen.height - 308f));
            return new Rect(226f, 72f, Mathf.Max(1f, Screen.width - 492f), Mathf.Max(1f, Screen.height - 184f));
        }

        private static Rect DrawReferenceArtLayer(Texture2D art, bool portrait)
        {
            if (!portrait)
            {
                referenceHiveTargetZoom = Mathf.Clamp(referenceHiveTargetZoom, 1.0f, 1.46f);
                referenceHiveZoom = SmoothReferenceHiveZoom(referenceHiveZoom, referenceHiveTargetZoom, 1.0f, 1.46f);
                float landscapeScale = Mathf.Max(Screen.width / ReferenceArtWidth, Screen.height / ReferenceArtHeight) * referenceHiveZoom;
                Vector2 landscapeFocus = new Vector2(ReferenceArtWidth * 0.5f, ReferenceArtHeight * 0.50f);
                Rect landscapeRect = new Rect(
                    Screen.width * 0.5f - landscapeFocus.x * landscapeScale + referenceMobilePan.x,
                    Screen.height * 0.5f - landscapeFocus.y * landscapeScale + referenceMobilePan.y,
                    ReferenceArtWidth * landscapeScale,
                    ReferenceArtHeight * landscapeScale);
                landscapeRect = ClampReferenceArtRect(landscapeRect);
                referenceMobilePan = new Vector2(
                    landscapeRect.x - (Screen.width * 0.5f - landscapeFocus.x * landscapeScale),
                    landscapeRect.y - (Screen.height * 0.5f - landscapeFocus.y * landscapeScale));
                GUI.DrawTexture(landscapeRect, art, ScaleMode.StretchToFill, true);
                return landscapeRect;
            }

            referenceHiveTargetZoom = Mathf.Clamp(referenceHiveTargetZoom, 1.02f, 1.68f);
            referenceHiveZoom = SmoothReferenceHiveZoom(referenceHiveZoom, referenceHiveTargetZoom, 1.02f, 1.68f);
            float scale = Mathf.Max(Screen.width / 620f, Screen.height / 1010f) * referenceHiveZoom;
            scale = Mathf.Max(scale, 0.80f);
            float width = ReferenceArtWidth * scale;
            float height = ReferenceArtHeight * scale;
            Vector2 focus = new Vector2(836f, 500f);
            Rect artRect = new Rect(
                Screen.width * 0.5f - focus.x * scale + referenceMobilePan.x,
                Screen.height * 0.43f - focus.y * scale + referenceMobilePan.y,
                width,
                height);

            artRect = ClampReferenceArtRect(artRect);
            referenceMobilePan = new Vector2(artRect.x - (Screen.width * 0.5f - focus.x * scale), artRect.y - (Screen.height * 0.43f - focus.y * scale));

            GUI.DrawTexture(artRect, art, ScaleMode.StretchToFill, true);
            return artRect;
        }

        private static void DrawWorldNode(Rect area, float x, float y, string label, string status, bool active)
        {
            Vector2 center = new Vector2(area.x + area.width * x, area.y + area.height * y);
            float scale = IsPortraitLayout() ? 0.82f : 1.34f;
            Rect node = new Rect(center.x - 48f * scale, center.y - 38f * scale, 96f * scale, 76f * scale);
            DrawPremiumPanel(node, active ? new Color(0.18f, 0.12f, 0.035f, 0.98f) : new Color(0.030f, 0.060f, 0.075f, 0.96f), active ? new Color(1f, 0.72f, 0.16f, 0.95f) : new Color(0.30f, 0.70f, 1f, 0.72f));
            DrawGameIcon(new Rect(node.x + 32f * scale, node.y + 8f * scale, 32f * scale, 32f * scale), active ? "hive" : "world", Color.white);
            GUI.Label(new Rect(node.x + 6f, node.y + 42f * scale, node.width - 12f, 20f * scale), label, new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter, fontSize = Mathf.RoundToInt(11f * scale) });
            GUI.Label(new Rect(node.x + 6f, node.y + 58f * scale, node.width - 12f, 16f * scale), status, new GUIStyle(centeredTinyLabelStyle) { fontSize = Mathf.RoundToInt(9f * scale) });
        }

        private static void DrawWorldLink(Rect area, float ax, float ay, float bx, float by)
        {
            Vector2 a = new Vector2(area.x + area.width * ax, area.y + area.height * ay);
            Vector2 b = new Vector2(area.x + area.width * bx, area.y + area.height * by);
            Vector2 direction = b - a;
            float length = direction.magnitude;
            if (length <= 1f) return;

            Matrix4x4 previousMatrix = GUI.matrix;
            GUIUtility.RotateAroundPivot(Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg, a);
            Color previousColor = GUI.color;
            GUI.color = new Color(0.30f, 0.70f, 1f, 0.50f);
            float thickness = IsPortraitLayout() ? 4f : 7f;
            GUI.DrawTexture(new Rect(a.x, a.y - thickness * 0.5f, length, thickness), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            GUI.color = previousColor;
            GUI.matrix = previousMatrix;
        }

        private static Rect ClampReferenceArtRect(Rect artRect)
        {
            if (artRect.width <= Screen.width) artRect.x = (Screen.width - artRect.width) * 0.5f;
            else artRect.x = Mathf.Clamp(artRect.x, Screen.width - artRect.width, 0f);

            if (artRect.height <= Screen.height) artRect.y = (Screen.height - artRect.height) * 0.5f;
            else artRect.y = Mathf.Clamp(artRect.y, Screen.height - artRect.height, 0f);

            return artRect;
        }

        private static void DrawPlayerChromeOcclusionMasks(bool portrait)
        {
            if (!portrait) return;

            Color previous = GUI.color;
            GUI.color = new Color(0.018f, 0.014f, 0.010f, 1f);
            GUI.DrawTexture(new Rect(0f, 0f, Screen.width, 126f), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            GUI.DrawTexture(new Rect(0f, Screen.height - 258f, Screen.width, 258f), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            GUI.color = previous;
        }

        private static bool IsPortraitLayout()
        {
            return Screen.height > Screen.width;
        }

        private static bool IsTabletLandscapeLayout()
        {
            return !IsPortraitLayout() && Screen.width >= 1600 && Screen.height >= 900;
        }

        private static float LandscapeUiScale()
        {
            if (IsPortraitLayout()) return 1f;
            if (Screen.width >= 1800 && Screen.height >= 1000) return 1.30f;
            if (Screen.width >= 1400 && Screen.height >= 850) return 1.18f;
            if (Screen.width >= 1200) return 1.08f;
            return 1f;
        }

        private static int ScaledFont(float baseSize)
        {
            return Mathf.RoundToInt(baseSize * LandscapeUiScale());
        }

