        private static float LandscapeContextPanelWidth()
        {
            return IsTabletLandscapeLayout() ? 332f : 292f;
        }

        private static float LandscapeContextPanelHeight()
        {
            return IsTabletLandscapeLayout() ? 264f : 248f;
        }

        private static Rect LandscapeContextPanelRect(float width, float height)
        {
            if (width <= 0f || height <= 0f) return new Rect(0f, 0f, 0f, 0f);
            float x = Mathf.Max(IsTabletLandscapeLayout() ? 160f : 148f, Screen.width - width - 18f);
            float y = Mathf.Min(
                118f,
                Mathf.Max(LandscapeTopHudHeight() + 12f, Screen.height - LandscapeBottomRailHeight() - height - 18f));
            return new Rect(x, y, width, height);
        }

        private static float LandscapeBottomRailHeight()
        {
