        }

        private static void HandleReferenceHiveGestures(Rect artRect, bool portrait)
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.Inactive)
            {
                referenceInputDragging = false;
                referenceSelectionSuppressed = false;
                return;
            }
            if (PremiumUiBlocksWorldInput())
            {
                referenceInputDragging = false;
                referenceSelectionSuppressed = false;
                referenceInputStartedInHive = false;
                return;
            }

            Rect hiveRect = ReferenceHiveInteractionRect(portrait);
            HandleReferenceTouchGestures(hiveRect);

            Event current = Event.current;
            if (current == null) return;

            if (current.type == EventType.ScrollWheel && hiveRect.Contains(current.mousePosition))
            {
                // M040-CL: Play Mode observed - scrolling inside the new Research panel's card
                // list (GUI.BeginScrollView) also zoomed the hive map behind it, since
                // IsPointOnFixedHiveUi only knows about small fixed icon/button rects, not the
                // large overlay panels gated by PremiumUiBlocksWorldInput() (Research, Alliance,
                // etc.) - reuse that existing flag here too instead of consuming/duplicating rects.
                if (IsPointOnFixedHiveUi(current.mousePosition, portrait) || PremiumUiBlocksWorldInput())
                {
                    uiInputBlockedHiveGestureForProof = true;
                    RecordReferenceGesture("ui-blocked-scroll", 0, Vector2.zero, 0f);
                    return;
                }

                float previousTarget = referenceHiveTargetZoom;
                float wheelStep = Mathf.Clamp(-current.delta.y * 0.035f, -ReferenceMaxPinchZoomStep, ReferenceMaxPinchZoomStep);
                referenceHiveTargetZoom = Mathf.Clamp(referenceHiveTargetZoom + wheelStep, portrait ? 1.02f : 1.0f, portrait ? 1.68f : 1.46f);
                KeepReferencePointUnderScreenPoint(artRect, current.mousePosition, previousTarget, referenceHiveTargetZoom);
                RecordReferenceGesture("mouse-wheel-zoom", 0, Vector2.zero, wheelStep);
                current.Use();
                return;
            }

            if (current.type == EventType.MouseDown && current.button == 0)
            {
                referenceInputStartedInHive = hiveRect.Contains(current.mousePosition) && !IsPointOnFixedHiveUi(current.mousePosition, portrait);
                if (hiveRect.Contains(current.mousePosition) && !referenceInputStartedInHive)
                {
                    uiInputBlockedHiveGestureForProof = true;
                    RecordReferenceGesture("ui-blocked-pointer", 1, Vector2.zero, 0f);
                }

                referenceInputStart = current.mousePosition;
                referenceInputDragging = false;
                referenceSelectionSuppressed = false;
                return;
            }

            if (current.type != EventType.MouseDrag || current.button != 0 || !referenceInputStartedInHive) return;
            if (!hiveRect.Contains(current.mousePosition)) return;
            if (Vector2.Distance(referenceInputStart, current.mousePosition) > ReferenceDragThresholdPixels)
            {
                referenceInputDragging = true;
            }

            referenceSelectionSuppressed = true;
            referenceMobilePan += current.delta;
            RecordReferenceGesture("mouse-pan", 1, current.delta, 0f);
            current.Use();
        }

        private static void HandleReferenceTouchGestures(Rect hiveRect)
        {
            if (Input.touchCount == 0)
            {
                referencePinching = false;
                referenceTouchPanning = false;
                referenceLastPinchDistance = 0f;
                if (referenceLastGestureMode != "proof") RecordReferenceGesture("idle", 0, Vector2.zero, 0f);
                return;
            }

            if (Input.touchCount == 1)
            {
                referencePinching = false;
                Touch touch = Input.GetTouch(0);
                Vector2 point = TouchToGuiPoint(touch.position);
                if (!hiveRect.Contains(point)) return;
                if (IsPointOnFixedHiveUi(point, IsPortraitLayout()))
                {
                    uiInputBlockedHiveGestureForProof = true;
                    RecordReferenceGesture("ui-blocked-touch", 1, Vector2.zero, 0f);
                    return;
                }

                Vector2 panDelta = new Vector2(touch.deltaPosition.x, -touch.deltaPosition.y);
                if (touch.phase == TouchPhase.Began)
                {
                    referenceTouchPanning = false;
                    referenceSelectionSuppressed = false;
                    RecordReferenceGesture("one-finger-ready", 1, Vector2.zero, 0f);
                    return;
                }

                if (panDelta.magnitude < ReferenceTouchPanThresholdPixels && !referenceTouchPanning)
                {
                    RecordReferenceGesture("one-finger-hold", 1, Vector2.zero, 0f);
                    return;
                }

                referenceTouchPanning = true;
                referenceSelectionSuppressed = true;
                referenceMobilePan += panDelta;
                RecordReferenceGesture("one-finger-pan", 1, panDelta, 0f);
                return;
            }

            Touch first = Input.GetTouch(0);
            Touch second = Input.GetTouch(1);
            Vector2 firstPoint = TouchToGuiPoint(first.position);
            Vector2 secondPoint = TouchToGuiPoint(second.position);
            if (!hiveRect.Contains(firstPoint) || !hiveRect.Contains(secondPoint))
            {
                referencePinching = false;
                referenceTouchPanning = false;
                return;
            }

            bool portrait = IsPortraitLayout();
            if (IsPointOnFixedHiveUi(firstPoint, portrait) || IsPointOnFixedHiveUi(secondPoint, portrait))
            {
                uiInputBlockedHiveGestureForProof = true;
                referencePinching = false;
                referenceTouchPanning = false;
                RecordReferenceGesture("ui-blocked-pinch", Input.touchCount, Vector2.zero, 0f);
                return;
            }

            float distance = Vector2.Distance(firstPoint, secondPoint);
            referenceTouchPanning = false;
            referenceSelectionSuppressed = true;
            if (!referencePinching || referenceLastPinchDistance <= 1f)
            {
                referencePinching = true;
                referenceLastPinchDistance = distance;
                RecordReferenceGesture("two-finger-pinch-ready", Input.touchCount, Vector2.zero, 0f);
                return;
            }

            if (Mathf.Abs(distance - referenceLastPinchDistance) < ReferencePinchThresholdPixels)
            {
                RecordReferenceGesture("two-finger-pinch-hold", Input.touchCount, Vector2.zero, 0f);
                return;
            }

            float delta = (distance - referenceLastPinchDistance) / Mathf.Max(1f, Mathf.Min(Screen.width, Screen.height));
            float zoomStep = Mathf.Clamp(delta * 1.6f, -ReferenceMaxPinchZoomStep, ReferenceMaxPinchZoomStep);
            referenceHiveTargetZoom = Mathf.Clamp(referenceHiveTargetZoom + zoomStep, IsPortraitLayout() ? 1.02f : 1.0f, IsPortraitLayout() ? 1.68f : 1.46f);
            referenceLastPinchDistance = distance;
            RecordReferenceGesture("two-finger-pinch-zoom", Input.touchCount, Vector2.zero, zoomStep);
        }

        private static float SmoothReferenceHiveZoom(float current, float target, float minZoom, float maxZoom)
        {
            float clampedCurrent = Mathf.Clamp(current, minZoom, maxZoom);
            float clampedTarget = Mathf.Clamp(target, minZoom, maxZoom);
            float deltaTime = Mathf.Max(Time.unscaledDeltaTime, 1f / 60f);
            float damped = Mathf.Lerp(clampedCurrent, clampedTarget, 1f - Mathf.Exp(-ReferenceZoomDamping * deltaTime));
            float maxStep = ReferenceMaxZoomSpeedPerSecond * deltaTime;
            return Mathf.Clamp(Mathf.MoveTowards(clampedCurrent, damped, maxStep), minZoom, maxZoom);
        }

        private static void RecordReferenceGesture(string mode, int touchCount, Vector2 panDelta, float pinchDelta)
        {
            referenceLastGestureMode = string.IsNullOrWhiteSpace(mode) ? "idle" : mode;
            referenceLastTouchCount = touchCount;
            referenceLastPanDelta = panDelta;
            referenceLastPinchDelta = pinchDelta;
        }

        private static Vector2 TouchToGuiPoint(Vector2 touchPosition)
        {
            return new Vector2(touchPosition.x, Screen.height - touchPosition.y);
        }

        private static bool IsPointOnFixedHiveUi(Vector2 point, bool portrait)
        {
            return IsPointOnFixedHiveUi(point, portrait, Screen.width, Screen.height);
        }

        private static bool IsPointOnFixedHiveUi(Vector2 point, bool portrait, float screenWidth, float screenHeight)
        {
            foreach (Rect rect in FixedHiveUiRects(portrait, screenWidth, screenHeight))
            {
                if (rect.Contains(point)) return true;
            }

            return false;
        }

        public static bool IsCommunicationPointBlockedForProof(Vector2 point, bool portrait, float screenWidth, float screenHeight)
        {
            Rect panel = MiniChatFloatingRectForProof(portrait, screenWidth, screenHeight);
            return communicationPanelOpen && MiniChatFloatingShouldRender(false) && panel.Contains(point);
        }

        private static Rect[] FixedHiveUiRects(bool portrait)
        {
            return FixedHiveUiRects(portrait, Screen.width, Screen.height);
        }

        private static Rect[] FixedHiveUiRects(bool portrait, float screenWidth, float screenHeight)
        {
            if (portrait)
            {
                bool detailVisible = referenceHotspotSelected && !detailPanelClosed;
                float panelHeight = detailVisible ? PortraitDetailPanelHeight : 0f;
                var portraitRects = new List<Rect>
                {
                    new Rect(0f, 0f, screenWidth, 126f),
                    new Rect(8f, screenHeight - 78f, screenWidth - 16f, 70f),
                    new Rect(10f, screenHeight - 78f - panelHeight - 12f, screenWidth - 20f, panelHeight)
                };

                if (activeMainMenuId == "Quests") portraitRects.Add(GuidedQuestMenuPanelRect(true, screenWidth, screenHeight));
                if (activeMainMenuId == "More") portraitRects.Add(PortraitMorePanelRect(screenWidth, screenHeight));
                if (activeMainMenuId == "Settings") portraitRects.Add(MobileComfortSettingsPanelRect(true, screenWidth, screenHeight));
                if (communicationPanelOpen && MiniChatFloatingShouldRender(false))
                {
                    Rect floating = MiniChatFloatingRectForProof(true, screenWidth, screenHeight);
                    portraitRects.Add(floating);
                    if (chatEmojiPanelOpen)
                    {
                        float composerHeight = 58f;
                        Rect composer = new Rect(floating.x + 8f, floating.yMax - composerHeight - 8f, floating.width - 16f, composerHeight);
                        portraitRects.Add(ChatEmojiPanelRect(composer));
                    }
                }
                if (referenceDetailInfoPopupOpen) portraitRects.Add(ReferenceDetailInfoPopupRect(true));
                return portraitRects.ToArray();
            }

            bool tablet = screenWidth >= 1600f && screenHeight >= 900f;
            bool detailVisibleLandscape = referenceHotspotSelected && !detailPanelClosed;
            float contextWidth = detailVisibleLandscape ? (tablet ? 332f : 292f) : 0f;
            float contextHeight = detailVisibleLandscape ? (tablet ? 264f : 248f) : 0f;
            float bottomRail = tablet ? 104f : 82f;
            float topHud = tablet ? 132f : 112f;
            float contextX = Mathf.Max(tablet ? 160f : 148f, screenWidth - contextWidth - 18f);
            float contextY = Mathf.Min(118f, Mathf.Max(topHud + 12f, screenHeight - bottomRail - contextHeight - 18f));

            var rects = new List<Rect>
            {
                new Rect(10f, 8f, 178f, 64f),
                new Rect(196f, 12f, 84f, 32f),
                new Rect(288f, 12f, 150f, 32f),
                new Rect(444f, 4f, Mathf.Max(1f, screenWidth - 448f), 46f),
                new Rect(screenWidth - 72f, 54f, 60f, 28f),
                new Rect(16f, 116f, tablet ? 132f : 116f, tablet ? 430f : 390f),
                new Rect(contextX, contextY, contextWidth, contextHeight),
                new Rect(0f, screenHeight - bottomRail - 10f, screenWidth, bottomRail + 10f)
            };

            if (playerMenuOpen) rects.Add(new Rect(10f, 80f, 300f, PlayerProfilePanelHeight));
            if (vipMenuOpen) rects.Add(new Rect(196f, 50f, 300f, 154f));
            if (powerMenuOpen) rects.Add(new Rect(288f, 52f, 336f, 174f));
            if (activeMainMenuId == "Quests") rects.Add(GuidedQuestMenuPanelRect(false, screenWidth, screenHeight));
            if (activeMainMenuId == "More") rects.Add(MoreMenuPanelRect(false, screenWidth, screenHeight));
            if (activeMainMenuId == "Settings") rects.Add(MobileComfortSettingsPanelRect(false, screenWidth, screenHeight));
            if (communicationPanelOpen && MiniChatFloatingShouldRender(false))
            {
                Rect floating = MiniChatFloatingRectForProof(false, screenWidth, screenHeight);
                rects.Add(floating);
                if (chatEmojiPanelOpen)
                {
                    float composerHeight = 54f;
                    Rect composer = new Rect(floating.x + 8f, floating.yMax - composerHeight - 8f, floating.width - 16f, composerHeight);
                    rects.Add(ChatEmojiPanelRect(composer));
                }
            }
            if (referenceDetailInfoPopupOpen) rects.Add(ReferenceDetailInfoPopupRect(false));
            return rects.ToArray();
        }

        private static void KeepReferencePointUnderScreenPoint(Rect artRect, Vector2 screenPoint, float previousZoom, float nextZoom)
        {
            if (Mathf.Approximately(previousZoom, nextZoom)) return;
            Vector2 artPoint = ScreenToReferenceArtPoint(artRect, screenPoint);
            float scaleBefore = artRect.width / ReferenceArtWidth;
            float scaleAfter = scaleBefore * (nextZoom / Mathf.Max(0.01f, previousZoom));
            Vector2 before = new Vector2(artRect.x + artPoint.x * scaleBefore, artRect.y + artPoint.y * scaleBefore);
            Vector2 after = new Vector2(artRect.x + artPoint.x * scaleAfter, artRect.y + artPoint.y * scaleAfter);
            referenceMobilePan += before - after;
        }

        private static Rect ReferenceHiveInteractionRect(bool portrait)
        {
            return ReferenceHiveInteractionRect(portrait, Screen.width, Screen.height);
        }

        private static Rect ReferenceHiveInteractionRect(bool portrait, float screenWidth, float screenHeight)
        {
            if (portrait)
            {
                const float top = 126f;
                const float bottom = 258f;
                return new Rect(0f, top, screenWidth, Mathf.Max(1f, screenHeight - top - bottom));
            }

            bool tablet = screenWidth >= 1600f && screenHeight >= 900f;
            float bottomRail = (tablet ? 104f : 82f) + 22f;
            return new Rect(0f, 0f, screenWidth, Mathf.Max(1f, screenHeight - bottomRail));
        }

        public static bool IsLandscapeHiveScreenPointInteractiveForProof(float screenWidth, float screenHeight, float x, float y)
        {
            Vector2 point = new Vector2(x, y);
            return ReferenceHiveInteractionRect(false, screenWidth, screenHeight).Contains(point)
                && !IsPointOnFixedHiveUi(point, false, screenWidth, screenHeight);
        }

        private static Vector2 ReferencePoint(Rect artRect, float x, float y)
        {
            return new Vector2(artRect.x + artRect.width * (x / ReferenceArtWidth), artRect.y + artRect.height * (y / ReferenceArtHeight));
        }

        private static Rect ReferenceRect(Rect artRect, float x, float y, float width, float height)
        {
            Vector2 point = ReferencePoint(artRect, x, y);
            return new Rect(point.x, point.y, artRect.width * (width / ReferenceArtWidth), artRect.height * (height / ReferenceArtHeight));
        }

