                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodPreparationRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodNursesWorking
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitSupplyRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitTreatmentRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationInspectionRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationTreatmentRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationDoctrineRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeAuditing
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeCalibrationRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeApplicationRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsSupplyRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsDeploymentRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsDoctrineRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseScouting
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseMobilizing
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseRecoveryRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseDoctrineRunning
