        private static void DrawReactiveHiveAmbience(Rect artRect, bool portrait)
        {
            HiveReactiveAmbienceState state = CurrentReactiveHiveAmbienceState();
            if (!state.IsVisible) return;

            ReferenceHiveHotspot hotspot = FindReferenceHotspot(state.ZoneId);
            if (string.IsNullOrWhiteSpace(hotspot.HotspotId)) return;

            HiveReactiveAmbienceDefinition definition = HiveReactiveAmbienceCatalog.DefinitionFor(state.Kind);
            int cueCount = definition.VisibleCueCount(mobileEconomyMode);
            if (cueCount <= 0) return;

            Vector2 visualAnchor = GetReferenceVisualAnchor(hotspot);
            Vector2 center = ReferencePoint(artRect, visualAnchor.x, visualAnchor.y);
            float baseRadius = portrait ? 50f : 66f;
            Rect visibility = new Rect(center.x - baseRadius * 1.9f, center.y - baseRadius * 1.9f, baseRadius * 3.8f, baseRadius * 3.8f);
            if (!ReferenceOverlayClipRect().Overlaps(visibility)) return;

            float time = Application.isPlaying ? Time.realtimeSinceStartup : 1.6f;
            Color previous = GUI.color;
            try
            {
                for (int index = 0; index < cueCount; index++)
                {
                    float phase = definition.MotionPhase(time, index, productionReducedMotionForProof);
                    float radius = baseRadius * Mathf.Lerp(0.90f, 1.52f, phase);
                    float fade = productionReducedMotionForProof ? 0.52f : Mathf.Lerp(0.62f, 0.14f, phase);
                    GUI.color = new Color(definition.Accent.r, definition.Accent.g, definition.Accent.b, definition.Accent.a * fade);
                    GUI.DrawTexture(
                        new Rect(center.x - radius, center.y - radius, radius * 2f, radius * 2f),
                        GetPremiumTexture("selected-glow"),
                        ScaleMode.ScaleToFit,
                        true);

                    float angle = phase * Mathf.PI * 2f + index * 1.9f;
                    Vector2 direction = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle) * 0.62f);
                    Vector2 cueCenter = center + direction * baseRadius * 1.16f;
                    if (state.Kind == HiveReactiveAmbienceKind.UpgradeActive)
                    {
                        DrawGuiLine(
                            center + direction * baseRadius * 0.72f,
                            center + direction * baseRadius * 1.34f,
                            new Color(definition.Accent.r, definition.Accent.g, definition.Accent.b, 0.58f),
                            portrait ? 1.8f : 2.2f);
                    }

                    string iconId = state.Kind == HiveReactiveAmbienceKind.ProductionFull
                        ? ManualProductionIcon(state.ZoneId)
                        : definition.IconId;
                    DrawSpecializedCueIcon(
                        cueCenter,
                        portrait ? 18f : 22f,
                        iconId,
                        definition.Accent,
                        state.Kind == HiveReactiveAmbienceKind.UpgradeActive ? 0.74f : 0.66f);
                }
            }
            finally
            {
                GUI.color = previous;
            }
        }

        private static HiveReactiveAmbienceState CurrentReactiveHiveAmbienceState()
        {
            string upgradeZoneId = IsUpgradeRunning() ? localPreviewUpgradeHotspotId : string.Empty;
            return HiveReactiveAmbienceCatalog.Resolve(upgradeZoneId, FirstFullProductionZoneId());
        }

        private static string FirstFullProductionZoneId()
        {
            if (HiveReactiveAmbienceCatalog.IsProductionZone(focusedReferenceHotspotId)
                && ManualProductionForecastFor(focusedReferenceHotspotId).State == ManualProductionForecastState.Full)
                return focusedReferenceHotspotId;

            string[] producerIds = { "honey_storage", "wax_workshop", "warehouse_cells" };
            for (int index = 0; index < producerIds.Length; index++)
            {
                if (ManualProductionForecastFor(producerIds[index]).State == ManualProductionForecastState.Full)
                    return producerIds[index];
            }
            return string.Empty;
        }

        private static void DrawAmbientHiveBeeTraffic(Rect artRect, bool portrait, float time, string activeBeeTaskZone)
        {
            int budget = HiveMaturityAmbientBeeCap(AmbientBeeBudget(portrait));
            int drawn = 0;
            for (int i = 0; i < AmbientBeeAgentPriority.Length && drawn < budget; i++)
            {
                if (!TryFindLiveHiveBeeAgent(AmbientBeeAgentPriority[i], out LiveHiveBeeAgent agent)
                    || !IsAmbientBeeAgentEligible(agent, portrait)) continue;

                bool active = IsBeeAgentActiveForCurrentTask(agent, activeBeeTaskZone);
                float activity = AmbientBeeActivityMultiplier(agent, active);
                Vector2 artPoint = AnimatedBeeArtPoint(agent, time, activity);
                Rect beeRect = WorkerBeeRectFromArtPoint(artRect, artPoint, agent.Size * 0.82f, portrait);
                if (!IsLiveBeeVisible(beeRect, portrait)) continue;

                float alpha = active ? 0.92f : agent.Family == BeePresenceFamily.Queen ? 0.72f : 0.62f;
                DrawLiveBeeMotionTrail(artRect, agent, artPoint, active ? 0.44f : 0.24f, portrait);
                DrawRuntimeWorkerBee(beeRect, agent.Phase, alpha, time, agent.Family == BeePresenceFamily.Guard);
                drawn++;
            }
        }

        private static int AmbientBeeBudget(bool portrait)
        {
            if (mobileEconomyMode) return portrait ? 3 : 5;
            return portrait ? 5 : 8;
        }

        // Une ruche qui respire (demande de Jeff, 2026-08-03) : reutilise le niveau VIP officiel deja
        // calcule ailleurs (signal de progression reelle du joueur, jamais une valeur de demo) pour
        // que la circulation ambiante des abeilles reste plus calme sur une jeune ruche et rejoigne
        // le plein budget deja tune pour Android/portrait des qu'un joueur s'est reellement investi.
        // Applique separement d'AmbientBeeBudget (qui reste le plafond materiel/economie deja teste)
        // - purement une reduction supplementaire de combien de ce plafond est reellement utilise.
        private static int HiveMaturityAmbientBeeCap(int budget)
        {
            float scale = officialVipLevel >= 8 ? 1f : officialVipLevel >= 3 ? 0.75f : 0.5f;
            return Mathf.Max(1, Mathf.Min(budget, Mathf.CeilToInt(budget * scale)));
        }

        private static int AmbientBeeCountForProof(bool portrait)
        {
            int count = 0;
            int budget = AmbientBeeBudget(portrait);
            for (int i = 0; i < AmbientBeeAgentPriority.Length && count < budget; i++)
            {
                if (TryFindLiveHiveBeeAgent(AmbientBeeAgentPriority[i], out LiveHiveBeeAgent agent)
                    && IsAmbientBeeAgentEligible(agent, portrait)) count++;
            }

            return count;
        }

        private static bool TryFindLiveHiveBeeAgent(string agentId, out LiveHiveBeeAgent agent)
        {
            for (int i = 0; i < LiveBeeAgents.Length; i++)
            {
                if (!string.Equals(LiveBeeAgents[i].AgentId, agentId, StringComparison.Ordinal)) continue;
                agent = LiveBeeAgents[i];
                return true;
            }

            agent = default;
            return false;
        }

        private static bool IsAmbientBeeAgentEligible(LiveHiveBeeAgent agent, bool portrait)
        {
            if (portrait && !agent.MobileVisible) return false;

            ReferenceHiveHotspot hotspot = FindReferenceHotspot(agent.ZoneId);
            if (string.IsNullOrWhiteSpace(hotspot.HotspotId)
                || hotspot.StateIcon == "future"
                || hotspot.StateIcon == "locked"
                || hotspot.StateIcon == "server"
                || hotspot.StateIcon == "disabled") return false;

            if (string.Equals(agent.AgentId, "worker-reserve-02", StringComparison.Ordinal))
            {
                if (!portrait) return true;
                float capacity = DisplayedManualProductionCapacity(agent.ZoneId);
                return capacity > 0f && DisplayedPendingManualProduction(agent.ZoneId) / capacity >= 0.45f;
            }

            return true;
        }

        private static float AmbientBeeActivityMultiplier(LiveHiveBeeAgent agent, bool active)
        {
            if (active) return 1.45f;

            float capacity = DisplayedManualProductionCapacity(agent.ZoneId);
            if (capacity > 0f)
            {
                float fill = Mathf.Clamp01(DisplayedPendingManualProduction(agent.ZoneId) / capacity);
                return Mathf.Lerp(0.72f, 1.32f, fill);
            }

            switch (agent.Family)
            {
                case BeePresenceFamily.Queen: return 0.46f;
                case BeePresenceFamily.Nurse: return 0.84f;
                case BeePresenceFamily.Guard: return IsTrainingRunning() ? 1.22f : 0.52f;
                case BeePresenceFamily.Scout: return 0.92f;
                default: return 0.76f;
            }
        }

        private static bool IsSpecializedZoneSelected(string zoneId)
        {
            return referenceHotspotSelected
                && !detailPanelClosed
                && string.Equals(focusedReferenceHotspotId, zoneId, StringComparison.Ordinal);
        }

        private static void DrawSpecializedAmbientBeeCue(
            Rect artRect,
            LiveHiveBeeAgent agent,
            Vector2 artPoint,
            bool portrait,
            float time,
            bool emphasized)
        {
            if (!HiveSpecializedBeeActivityCatalog.TryResolve(agent.ZoneId, out HiveSpecializedBeeActivityDefinition definition)) return;

            int cueCount = definition.VisibleCueCount(mobileEconomyMode);
            float alpha = emphasized ? 0.90f : portrait ? 0.46f : 0.54f;
            Vector2 beeCenter = ReferencePoint(artRect, artPoint.x, artPoint.y);
            Vector2 anchor = ReferencePoint(artRect, agent.Anchor.x, agent.Anchor.y);
            Vector2 target = ReferencePoint(artRect, agent.Target.x, agent.Target.y);
            float baseSize = emphasized ? (portrait ? 17f : 19f) : (portrait ? 11f : 13f);

            switch (definition.Kind)
            {
                case HiveSpecializedBeeCueKind.NectarCarry:
                    Vector2 nectarAnchor = emphasized ? anchor + new Vector2(0f, baseSize * 2.15f) : anchor;
                    Vector2 nectarTarget = emphasized ? target + new Vector2(0f, baseSize * 2.15f) : target;
                    if (emphasized)
                    {
                        DrawGuiLine(nectarAnchor, nectarTarget, new Color(0f, 0f, 0f, 0.58f * alpha), portrait ? 3.8f : 4.8f);
                        DrawGuiLine(nectarAnchor, nectarTarget, new Color(definition.Accent.r, definition.Accent.g, definition.Accent.b, 0.62f * alpha), portrait ? 1.5f : 1.8f);
                    }
                    for (int index = 0; index < cueCount; index++)
                    {
                        float phase = definition.MotionPhase(time, index, productionReducedMotionForProof);
                        Vector2 center = emphasized
                            ? Vector2.Lerp(nectarAnchor, nectarTarget, phase)
                            : beeCenter + new Vector2(-baseSize * 0.62f, baseSize * (0.22f + index * 0.48f));
                        DrawSpecializedCueIcon(
                            center,
                            baseSize,
                            definition.ResourceIconId,
                            definition.Accent,
                            alpha);
                    }
                    break;

                case HiveSpecializedBeeCueKind.WaxShaping:
                    for (int index = 0; index < cueCount; index++)
                    {
                        float phase = definition.MotionPhase(time, index, productionReducedMotionForProof) * Mathf.PI * 2f;
                        Vector2 center = target + new Vector2(Mathf.Cos(phase) * baseSize * 1.20f, Mathf.Sin(phase) * baseSize * 0.72f);
                        DrawSpecializedCueIcon(center, baseSize * 0.90f, definition.ResourceIconId, definition.Accent, alpha);
                    }
                    break;

                case HiveSpecializedBeeCueKind.PollenSorting:
                    for (int index = 0; index < cueCount; index++)
                    {
                        float phase = definition.MotionPhase(time, index, productionReducedMotionForProof);
                        float x = Mathf.Lerp(-baseSize * 1.35f, baseSize * 1.35f, phase);
                        float y = productionReducedMotionForProof ? 0f : Mathf.Sin((phase + index * 0.23f) * Mathf.PI * 2f) * baseSize * 0.32f;
                        DrawSpecializedCueIcon(target + new Vector2(x, y), baseSize * 0.84f, definition.ResourceIconId, definition.Accent, alpha);
                    }
                    break;

                case HiveSpecializedBeeCueKind.BroodNursing:
                    Vector2 nurseryCenter = Vector2.Lerp(anchor, target, 0.54f);
                    for (int index = 0; index < cueCount; index++)
                    {
                        float phase = definition.MotionPhase(time, index, productionReducedMotionForProof) * Mathf.PI * 2f;
                        Vector2 center = nurseryCenter + new Vector2(Mathf.Cos(phase) * baseSize * 1.75f, Mathf.Sin(phase) * baseSize * 1.05f);
                        DrawSpecializedCueIcon(center, baseSize * 0.76f, definition.ResourceIconId, definition.Accent, alpha * 0.84f);
                    }
                    break;

                case HiveSpecializedBeeCueKind.GuardPatrol:
                    DrawGuiLine(anchor, target, new Color(0f, 0f, 0f, 0.54f * alpha), portrait ? 3.5f : 4.5f);
                    DrawGuiLine(anchor, target, new Color(definition.Accent.r, definition.Accent.g, definition.Accent.b, 0.44f * alpha), portrait ? 1.2f : 1.6f);
                    for (int index = 0; index < cueCount; index++)
                    {
                        float phase = definition.MotionPhase(time, index, productionReducedMotionForProof);
                        Vector2 center = Vector2.Lerp(anchor, target, phase);
                        DrawSpecializedCueIcon(center, baseSize * 0.72f, definition.ResourceIconId, definition.Accent, alpha * 0.72f);
                    }
                    break;
            }
        }

        private static void DrawSpecializedCueIcon(Vector2 center, float size, string iconId, Color accent, float alpha)
        {
            Color previous = GUI.color;
            GUI.color = new Color(accent.r, accent.g, accent.b, accent.a * alpha * 0.68f);
            GUI.DrawTexture(
                new Rect(center.x - size * 0.72f, center.y - size * 0.72f, size * 1.44f, size * 1.44f),
                GetPremiumTexture("selected-glow"),
                ScaleMode.ScaleToFit,
                true);
            GUI.color = new Color(1f, 1f, 1f, alpha);
            GUI.DrawTexture(
                new Rect(center.x - size * 0.40f, center.y - size * 0.40f, size * 0.80f, size * 0.80f),
                GetIconTexture(iconId),
                ScaleMode.ScaleToFit,
                true);
            GUI.color = previous;
        }

        private static string ActiveBeeTaskZoneId()
        {
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.HoneyProduction) return "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCircuitRouteRunning)
                return guidedOpeningCircuitRoutePlan == "nursery_relay" ? "nursery_cluster" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCircuitMaintenanceRunning)
                return guidedOpeningCircuitMaintenancePlan == "ventilation_watch" ? "nursery_cluster" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCharterRunning)
                return guidedOpeningCharterPlan == "brood_bridge" ? "nursery_cluster" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCommissioningLoadRunning) return "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCommissioningSealRunning)
                return guidedOpeningCommissioningSealPlan == "brood_seal" ? "nursery_cluster" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodDiagnosisRunning) return "nursery_cluster";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodPreparationRunning) return "nursery_cluster";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodNursesWorking) return "nursery_cluster";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitSupplyRunning)
                return guidedBroodCircuitSupplyPlan == "pollen" ? "warehouse_cells" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitTreatmentRunning) return "nursery_cluster";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationInspectionRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationTreatmentRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationDoctrineRunning) return "nursery_cluster";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodWaxConsolidationRunning) return "wax_workshop";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerFeedProgress) return "nursery_cluster";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerEmergenceRunning) return "nursery_cluster";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerTrialRunning)
                return guidedWorkerTrialMode == "nursery" ? "nursery_cluster" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerFirstShiftRunning)
                return guidedWorkerAssignment == "nursery" ? "nursery_cluster" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCertificationTaskRunning)
                return guidedWorkerCertificationTaskPlan == "nursery" ? "nursery_cluster" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCertificationMentorshipRunning)
                return guidedWorkerCertificationMentorshipPlan == "mentorship" ? "nursery_cluster" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerWorkshopHandoffRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerWorkshopHandoffCollect)
                return guidedWorkerWorkshopHandoffPlan == "wax_convoy" ? "wax_workshop" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerWorkshopCommissionRunning) return "wax_workshop";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeAuditing) return "wax_workshop";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeCalibrationRunning) return "wax_workshop";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeApplicationRunning)
                return guidedUpgradeApplicationPlan == "nursery" ? "nursery_cluster" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsSupplyRunning) return "wax_workshop";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsDeploymentRunning)
                return guidedUpgradeOperationsDeploymentPlan == "nursery" ? "nursery_cluster" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsDoctrineRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeCertificationRunning) return "wax_workshop";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseScouting) return "guard_post";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseRecoveryRunning) return "guard_post";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseDoctrineRunning) return "guard_post";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessProductionRunning) return "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessPopulationRunning)
                return guidedReadinessPopulationPlan == "nurses" ? "nursery_cluster" : "guard_post";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessDefenseRunning) return "guard_post";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseVigilanceRunning) return "honey_storage";
            // Souvenir dans la ruche (demande de Jeff, 2026-08-03) : reutilise exactement le cluster
            // d'abeilles deja anime pour "guard_post" (voir DrawActiveTaskBeeCluster) - l'escouade qui
            // rentre est accueillie par le meme essaim que celui deja utilise pour la defense, sans
            // aucun nouveau rendu. Prioritaire sur les etats de routine ci-dessous, jamais sur un pas
            // de tutoriel guide en cours.
            if (HiveVictoryMemoryActive()) return "guard_post";
            if (IsDefenseRunning()) return "guard_post";
            if (IsResearchRunning()) return "research_node";
            if (IsUpgradeRunning()) return localPreviewUpgradeHotspotId;
            if (IsTrainingRunning()) return IsWorkerTrainingType(localPreviewTrainingTroopType) ? "nursery_cluster" : "guard_post";
            if (NowForUi() - localPreviewBroodFeedingFeedbackStartedAt <= BroodFeedingFeedbackSeconds) return "nursery_cluster";
            if (NowForUi() - localPreviewCollectionFeedbackStartedAt <= CollectionFeedbackSeconds) return localPreviewLastCollectedHotspotId;
            return string.Empty;
        }

        private static bool IsBeeAgentActiveForCurrentTask(LiveHiveBeeAgent agent, string activeBeeTaskZone)
        {
            if (string.IsNullOrWhiteSpace(activeBeeTaskZone)) return false;
            if (agent.ZoneId == activeBeeTaskZone) return true;

            if (activeBeeTaskZone == "guard_post")
            {
                return agent.Family == BeePresenceFamily.Guard && Vector2.Distance(agent.Anchor, new Vector2(956f, 266f)) < 220f;
            }

            if (activeBeeTaskZone == "honey_storage")
            {
                return agent.Family == BeePresenceFamily.Worker && Vector2.Distance(agent.Anchor, new Vector2(784f, 178f)) < 210f;
            }

            return false;
        }

        private static void DrawActiveTaskBeeCluster(Rect artRect, string activeBeeTaskZone, bool portrait, float time)
        {
            if (string.IsNullOrWhiteSpace(activeBeeTaskZone)) return;

            Vector2 center = ActiveBeeTaskCenter(activeBeeTaskZone);
            bool defenseInterception = activeBeeTaskZone == "guard_post" && IsDefenseRunning();
            bool defenseScouting = guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseScouting;
            if (!portrait)
            {
                Vector2 screenCenter = ReferencePoint(artRect, center.x, center.y);
                if (screenCenter.y < 188f) center.y += 52f;
            }

            LocalPreviewResearchDefinition activeResearch = IsResearchRunning() ? LocalPreviewResearchCatalog.Find(localPreviewResearchId) : null;
            int count = activeResearch != null
                ? activeResearch.AssignedBeeCount
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodDiagnosisRunning
                ? 1
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCircuitRouteRunning
                    ? Mathf.Max(1, guidedOpeningCircuitRouteAssignedBees)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCircuitMaintenanceRunning
                    ? Mathf.Max(1, guidedOpeningCircuitMaintenanceAssignedBees)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCharterRunning
                    ? Mathf.Max(1, guidedOpeningCharterAssignedBees)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCommissioningLoadRunning
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCommissioningSealRunning
                    ? Mathf.Max(1, guidedOpeningCommissioningAssignedBees)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodPreparationRunning
                    ? Mathf.Max(1, guidedBroodPreparationAssignedBees)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodNursesWorking
                ? Mathf.Max(1, guidedBroodAssignedNurses)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitSupplyRunning
                    ? Mathf.Max(1, guidedBroodCircuitSupplyAssignedBees)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitTreatmentRunning
                    ? Mathf.Max(1, guidedBroodCircuitTreatmentAssignedBees)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationInspectionRunning
                    ? Mathf.Max(1, guidedBroodIncubationInspectionAssignedBees)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationTreatmentRunning
                    ? Mathf.Max(1, guidedBroodIncubationTreatmentAssignedBees)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationDoctrineRunning
                    ? Mathf.Max(1, guidedBroodIncubationDoctrineAssignedBees)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerFeedProgress
                    ? Mathf.Max(1, guidedWorkerAssignedNurses)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerEmergenceRunning
                    ? Mathf.Max(1, guidedWorkerEmergenceAssignedBees)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerTrialRunning
                    ? Mathf.Max(1, guidedWorkerTrialAssignedBees)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerFirstShiftRunning
                    ? Mathf.Max(1, guidedWorkerFirstShiftAssignedBees)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCertificationTaskRunning
                    ? Mathf.Max(1, guidedWorkerCertificationTaskAssignedBees)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCertificationMentorshipRunning
                    ? Mathf.Max(1, guidedWorkerCertificationMentorshipAssignedBees)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerWorkshopHandoffRunning
                    ? Mathf.Max(1, guidedWorkerWorkshopHandoffAssignedBees)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerWorkshopCommissionRunning
                    ? Mathf.Max(1, guidedWorkerWorkshopCommissionAssignedBees)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeAuditing
                    ? Mathf.Max(1, guidedUpgradeAuditAssignedBuilders)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeRunning
                    ? Mathf.Max(1, guidedUpgradeAssignedBuilders)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeCalibrationRunning
                    ? Mathf.Max(1, guidedUpgradeCalibrationAssignedBuilders)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeApplicationRunning
                    ? Mathf.Max(1, guidedUpgradeApplicationAssignedBuilders)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsSupplyRunning
                    ? Mathf.Max(1, guidedUpgradeOperationsSupplyAssignedBuilders)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsDeploymentRunning
                    ? Mathf.Max(1, guidedUpgradeOperationsDeploymentAssignedBuilders)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeCertificationRunning
                    ? Mathf.Max(1, guidedUpgradeCertificationAssignedBuilders)
                : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsDoctrineRunning
                    ? Mathf.Max(1, guidedUpgradeOperationsDoctrineAssignedBuilders)
                    : defenseScouting
                        ? Mathf.Max(1, guidedDefenseScoutsAssigned)
                        : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseMobilizing
                            ? Mathf.Max(1, localPreviewDefenseGuardiansMobilized)
                            : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseRecoveryRunning
                                ? Mathf.Max(1, guidedDefenseRecoveryAssignedBees)
                            : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseDoctrineRunning
                                ? Mathf.Max(1, guidedDefenseDoctrineAssignedBees)
                            : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessProductionRunning
                                ? Mathf.Max(1, guidedReadinessProductionAssignedBees)
                            : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessPopulationRunning
                                ? Mathf.Max(1, guidedReadinessPopulationAssignedBees)
                            : guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessDefenseRunning
                                ? Mathf.Max(1, guidedReadinessDefenseAssignedBees)
                            : activeBeeTaskZone == "guard_post" ? (portrait ? 4 : 5) : (portrait ? 3 : 5);
            for (int i = 0; i < count; i++)
            {
                float phase = i * 0.31f + (activeBeeTaskZone == "guard_post" ? 0.22f : 0.05f);
                float orbit = Mathf.Repeat(time * (0.18f + i * 0.026f) + phase, 1f) * Mathf.PI * 2f;
                float radiusX = defenseInterception ? 94f : activeBeeTaskZone == "guard_post" ? 76f : 66f;
                float radiusY = defenseInterception ? 54f : activeBeeTaskZone == "guard_post" ? 46f : 38f;
                Vector2 organicOffset = new Vector2(
                    Mathf.Cos(orbit) * radiusX + Mathf.Sin(time * 1.7f + i) * 7f,
                    Mathf.Sin(orbit * 1.17f) * radiusY + Mathf.Cos(time * 1.3f + i * 0.7f) * 5f);
                Vector2 anchor = center + organicOffset;
                Vector2 target = center + new Vector2(Mathf.Cos(orbit + 1.4f) * radiusX * 0.55f, Mathf.Sin(orbit + 0.9f) * radiusY * 0.65f);
                string icon = defenseScouting ? "scout-bee" : activeBeeTaskZone == "guard_post" ? "guard-bee" : "worker-bee";
                BeePresenceFamily family = defenseScouting ? BeePresenceFamily.Scout : activeBeeTaskZone == "guard_post" ? BeePresenceFamily.Guard : BeePresenceFamily.Worker;
                float taskSize = defenseScouting ? (portrait ? 28f : 34f) : defenseInterception ? (portrait ? 38f : 44f) : (portrait ? 30f : 36f);
                LiveHiveBeeAgent taskAgent = new LiveHiveBeeAgent("active-task-" + i.ToString(CultureInfo.InvariantCulture), family, BeePresenceMotionKind.WalkCrawl, icon, activeBeeTaskZone, anchor, target, taskSize, phase, true);
                Vector2 artPoint = AnimatedBeeArtPoint(taskAgent, time);
                Rect beeRect = WorkerBeeRectFromArtPoint(artRect, artPoint, taskAgent.Size, portrait);
                if (!IsLiveBeeVisible(beeRect, portrait)) continue;
                DrawLiveBeeMotionTrail(artRect, taskAgent, artPoint, portrait ? 0.34f : 0.48f, portrait);
                DrawRuntimeWorkerBee(beeRect, phase, portrait ? 0.86f : 0.96f, time, activeBeeTaskZone == "guard_post");
            }
        }

        private static Vector2 ActiveBeeTaskCenter(string hotspotId)
        {
            if (string.Equals(hotspotId, "honey_storage", StringComparison.Ordinal)) return new Vector2(788f, 226f);
            if (string.Equals(hotspotId, "guard_post", StringComparison.Ordinal)) return IsDefenseRunning() ? new Vector2(1026f, 276f) : new Vector2(956f, 256f);

            for (int i = 0; i < ReferenceHotspots.Length; i++)
            {
                if (ReferenceHotspots[i].HotspotId == hotspotId) return GetReferenceVisualAnchor(ReferenceHotspots[i]);
            }

            return new Vector2(784f, 178f);
        }

        private static Vector2 AnimatedBeeArtPoint(LiveHiveBeeAgent agent, float time, float speedMultiplier = 1f)
        {
            if (productionReducedMotionForProof)
            {
                return agent.Anchor + new Vector2(Mathf.Sin((agent.Phase + 0.25f) * Mathf.PI * 2f) * 1.4f, Mathf.Cos((agent.Phase + 0.25f) * Mathf.PI * 2f) * 1.1f);
            }

            float t = Mathf.Repeat(time * MotionSpeed(agent.Motion) * Mathf.Max(0.1f, speedMultiplier) + agent.Phase, 1f);
            float smooth = Mathf.SmoothStep(0f, 1f, t <= 0.5f ? t * 2f : (1f - t) * 2f);
            Vector2 path = Vector2.Lerp(agent.Anchor, agent.Target, smooth);
            float wing = Mathf.Sin((time + agent.Phase) * Mathf.PI * 2f);

            switch (agent.Motion)
            {
                case BeePresenceMotionKind.Idle:
                    return agent.Anchor + new Vector2(Mathf.Sin((time + agent.Phase) * 1.7f) * 6f, wing * 4f);
                case BeePresenceMotionKind.ShortFlight:
                    return path + new Vector2(wing * 8f, -Mathf.Sin(t * Mathf.PI) * 18f);
                case BeePresenceMotionKind.WalkCrawl:
                    return path + new Vector2(wing * 2f, Mathf.Sin(t * Mathf.PI * 2f) * 3f);
                case BeePresenceMotionKind.LocalCollection:
                    return path + new Vector2(Mathf.Sin(t * Mathf.PI * 4f) * 4f, -Mathf.Sin(t * Mathf.PI) * 8f);
                case BeePresenceMotionKind.ZoneEntryExit:
                    return path + new Vector2(Mathf.Sin(t * Mathf.PI * 2f) * 5f, Mathf.Cos(t * Mathf.PI * 2f) * 5f);
                default:
                    return agent.Anchor;
            }
        }

        private static float MotionSpeed(BeePresenceMotionKind motion)
        {
            switch (motion)
            {
                case BeePresenceMotionKind.Idle: return 0.22f;
                case BeePresenceMotionKind.ShortFlight: return 0.48f;
                case BeePresenceMotionKind.WalkCrawl: return 0.30f;
                case BeePresenceMotionKind.LocalCollection: return 0.38f;
                case BeePresenceMotionKind.ZoneEntryExit: return 0.34f;
                default: return 0.25f;
            }
        }

        private static Rect BeeRectFromArtPoint(Rect artRect, Vector2 artPoint, float artSize, bool portrait)
        {
            float screenSize = artRect.width * (artSize / ReferenceArtWidth) * (portrait ? 1.22f : 1.0f);
            screenSize = Mathf.Clamp(screenSize, portrait ? 38f : 44f, portrait ? 58f : 68f);
            Vector2 point = ReferencePoint(artRect, artPoint.x, artPoint.y);
            return new Rect(point.x - screenSize * 0.5f, point.y - screenSize * 0.5f, screenSize, screenSize);
        }

        private static Rect WorkerBeeRectFromArtPoint(Rect artRect, Vector2 artPoint, float artSize, bool portrait)
        {
            float screenSize = artRect.width * (artSize / ReferenceArtWidth) * (portrait ? 1.08f : 1.0f);
            screenSize = Mathf.Clamp(screenSize, portrait ? 22f : 26f, portrait ? 34f : 40f);
            Vector2 point = ReferencePoint(artRect, artPoint.x, artPoint.y);
            return new Rect(point.x - screenSize * 0.5f, point.y - screenSize * 0.5f, screenSize, screenSize);
        }

        private static void DrawLiveBeeMotionTrail(Rect artRect, LiveHiveBeeAgent agent, Vector2 artPoint, float alpha, bool portrait)
        {
            if (productionReducedMotionForProof
                || mobileEconomyMode
                || portrait
                || (agent.Motion != BeePresenceMotionKind.LocalCollection && agent.Motion != BeePresenceMotionKind.ShortFlight)) return;

            Vector2 from = ReferencePoint(artRect, agent.Anchor.x, agent.Anchor.y);
            Vector2 to = ReferencePoint(artRect, artPoint.x, artPoint.y);
            float distance = Vector2.Distance(from, to);
            if (distance < 12f) return;

            Color trail = agent.Motion == BeePresenceMotionKind.LocalCollection
                ? new Color(1f, 0.68f, 0.08f, 0.18f * alpha)
                : new Color(0.58f, 0.86f, 1f, 0.14f * alpha);
            DrawGuiLine(from, to, trail, 2.2f);
        }

        private static bool IsLiveBeeVisible(Rect rect, bool portrait)
        {
            if (rect.xMax < 2f || rect.yMax < 2f || rect.x > Screen.width - 2f || rect.y > Screen.height - 2f) return false;
            float topReserved = portrait ? 126f : 70f;
            float bottomReserved = portrait ? 118f : 78f;
            if (rect.y < topReserved || rect.yMax > Screen.height - bottomReserved) return false;
            if (!portrait && rect.xMax > Screen.width - 398f && rect.y > 102f && rect.y < 660f) return false;
            if (!portrait && rect.x < 136f && rect.y > 104f && rect.y < 524f) return false;
            return true;
        }

        private static void DrawLiveBeeAgent(Rect rect, LiveHiveBeeAgent agent, float alpha, float time)
        {
            Color previous = GUI.color;
            Rect shadow = new Rect(rect.x + rect.width * 0.08f, rect.y + rect.height * 0.32f, rect.width * 0.96f, rect.height * 0.76f);
            GUI.color = new Color(0f, 0f, 0f, 0.28f * alpha);
            GUI.DrawTexture(shadow, GetPremiumTexture("soft-shadow"), ScaleMode.ScaleToFit, true);

            float wingPulse = productionReducedMotionForProof ? 1f : 1f + Mathf.Sin((time + agent.Phase) * 17f) * 0.10f;
            Rect wingLeft = new Rect(rect.x - rect.width * 0.04f, rect.y + rect.height * 0.14f, rect.width * 0.48f * wingPulse, rect.height * 0.38f);
            Rect wingRight = new Rect(rect.x + rect.width * 0.56f, rect.y + rect.height * 0.14f, rect.width * 0.48f * wingPulse, rect.height * 0.38f);
            GUI.color = new Color(0.58f, 0.88f, 1f, 0.30f * alpha);
            GUI.DrawTexture(wingLeft, GetPremiumTexture("panel-fill"), ScaleMode.StretchToFill, true);
            GUI.DrawTexture(wingRight, GetPremiumTexture("panel-fill"), ScaleMode.StretchToFill, true);

            GUI.color = new Color(1f, 0.78f, 0.18f, (productionReducedMotionForProof ? 0.22f : 0.40f) * alpha);
            GUI.DrawTexture(new Rect(rect.x - rect.width * 0.20f, rect.y - rect.height * 0.20f, rect.width * 1.40f, rect.height * 1.40f), GetPremiumTexture("selected-glow"), ScaleMode.ScaleToFit, true);

            GUI.color = new Color(1f, 1f, 1f, alpha);
            GUI.DrawTexture(IconSafeRect(rect), GetIconTexture(agent.IconId), ScaleMode.ScaleToFit, true);
            GUI.color = previous;
        }

        private static void DrawRuntimeWorkerBee(Rect rect, float phase, float alpha, float time, bool guardBee)
        {
            Color previousColor = GUI.color;
            Matrix4x4 previousMatrix = GUI.matrix;

            Vector2 pivot = rect.center;
            float angle = Mathf.Sin((time + phase) * 1.7f) * 14f + (guardBee ? 12f : -8f);
            GUIUtility.RotateAroundPivot(angle, pivot);

            float pulse = productionReducedMotionForProof ? 1f : 1f + Mathf.Sin((time + phase) * 6.5f) * 0.045f;
            Rect drawRect = new Rect(
                rect.center.x - rect.width * pulse * 0.5f,
                rect.center.y - rect.height * pulse * 0.5f,
                rect.width * pulse,
                rect.height * pulse);
            GUI.color = new Color(1f, guardBee ? 0.94f : 1f, guardBee ? 0.82f : 1f, alpha);
            GUI.DrawTexture(drawRect, GetRuntimeWorkerBeeTexture(), ScaleMode.ScaleToFit, true);

            GUI.matrix = previousMatrix;
            GUI.color = previousColor;
        }

        private static Texture2D GetRuntimeWorkerBeeTexture()
        {
            runtimeWorkerBeeArt = runtimeWorkerBeeArt != null
                ? runtimeWorkerBeeArt
                : Resources.Load<Texture2D>("PremiumBeeReference/worker-bee-premium-v2");
            runtimeWorkerBeeArt = runtimeWorkerBeeArt != null
                ? runtimeWorkerBeeArt
                : Resources.Load<Texture2D>("PremiumBeeReference/worker-bee-runtime");
            return runtimeWorkerBeeArt != null ? runtimeWorkerBeeArt : GetIconTexture("bee");
        }

        private static Texture2D GetRuntimeWaxMothThreatTexture()
        {
            runtimeWaxMothThreatArt = runtimeWaxMothThreatArt != null
                ? runtimeWaxMothThreatArt
                : Resources.Load<Texture2D>("PremiumBeeReference/wax_moth_threat");
            return runtimeWaxMothThreatArt != null ? runtimeWaxMothThreatArt : GetIconTexture("alert");
        }

        private static Vector2 ScreenToReferenceArtPoint(Rect artRect, Vector2 screenPoint)
        {
            return new Vector2(
                (screenPoint.x - artRect.x) / Mathf.Max(1f, artRect.width) * ReferenceArtWidth,
                (screenPoint.y - artRect.y) / Mathf.Max(1f, artRect.height) * ReferenceArtHeight);
        }

        private static void DrawReferenceHotspots(bool portrait, Rect artRect)
        {
            UpdateReferenceHover(artRect, portrait);
            HandleReferenceHotspotClick(artRect);
            DrawImportedReferenceContours(artRect, portrait);

            for (int i = 0; i < ReferenceHotspots.Length; i++)
            {
                ReferenceHiveHotspot hotspot = ReferenceHotspots[i];
                bool selected = referenceHotspotSelected && hotspot.HotspotId == focusedReferenceHotspotId;
                if (selected)
                {
                    DrawReferencePolygonHalo(artRect, hotspot, portrait);
                }
                else if (hotspot.HotspotId == hoveredReferenceHotspotId)
                {
                    DrawReferenceHoverHalo(artRect, hotspot, portrait);
                }
            }

            DrawReferenceFeedbackPulse(artRect, portrait);
            DrawManualCollectionReadyMarkers(artRect, portrait);
            DrawBuildingUpgradeReadyMarkers(artRect, portrait);
            DrawManualCollectionFeedback(artRect, portrait);
            DrawGuidedOpeningRouteFeedback(artRect, portrait);
            DrawNurseryVitalityLayer(artRect, portrait);
        }

        private static void UpdateReferenceHover(Rect artRect, bool portrait)
        {
            if (strategicPathPanelOpen || portrait || Event.current == null)
            {
                hoveredReferenceHotspotId = string.Empty;
                return;
            }

            Vector2 artPoint = ScreenToReferenceArtPoint(artRect, Event.current.mousePosition);
            ReferenceHiveHotspot hotspot = HitReferenceHotspot(artPoint);
            hoveredReferenceHotspotId = string.IsNullOrWhiteSpace(hotspot.HotspotId) ? string.Empty : hotspot.HotspotId;
        }

        private static void HandleReferenceHotspotClick(Rect artRect)
        {
            Event current = Event.current;
            if (current == null || strategicPathPanelOpen) return;
            if (PremiumUiBlocksWorldInput()) return;
            bool portrait = IsPortraitLayout();
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.Inactive && IsGuidedCollectionTutorialUiPoint(current.mousePosition, portrait)) return;
            if (ConsumeGuidedCollectionTutorialBlockedInput(current, artRect, portrait)) return;
            Rect hiveRect = ReferenceHiveInteractionRect(portrait);

            if (referenceCloseClickSuppressUntilMouseUp)
            {
                if (current.type == EventType.MouseUp && current.button == 0)
                {
                    referenceCloseClickSuppressUntilMouseUp = false;
                    referenceInputStartedInHive = false;
                    hoveredReferenceHotspotId = string.Empty;
                    current.Use();
                    return;
                }

                if (current.type == EventType.MouseDown && current.button == 0)
                {
                    referenceCloseClickSuppressUntilMouseUp = false;
                }
            }

            if (current.type == EventType.MouseDown && current.button == 0)
            {
                if (IsPointOnFixedHiveUi(current.mousePosition, portrait))
                {
                    referenceInputStartedInHive = false;
                    hoveredReferenceHotspotId = string.Empty;
                    return;
                }

                referenceInputStart = current.mousePosition;
                referenceInputDragging = false;
                if (!hiveRect.Contains(current.mousePosition))
                {
                    referenceInputStartedInHive = false;
                    hoveredReferenceHotspotId = string.Empty;
                    return;
                }

                referenceInputStartedInHive = true;
                ReferenceHiveHotspot pressed = HitReferenceHotspot(ScreenToReferenceArtPoint(artRect, current.mousePosition));
                hoveredReferenceHotspotId = string.IsNullOrWhiteSpace(pressed.HotspotId) ? string.Empty : pressed.HotspotId;
                return;
            }

            if (current.type == EventType.MouseDrag && current.button == 0)
            {
                if (Vector2.Distance(referenceInputStart, current.mousePosition) > ReferenceDragThresholdPixels)
                {
                    referenceInputDragging = true;
                }

                return;
            }

            if (current.type != EventType.MouseUp || current.button != 0) return;
            if (IsPointOnFixedHiveUi(current.mousePosition, portrait))
            {
                referenceInputStartedInHive = false;
                hoveredReferenceHotspotId = string.Empty;
                return;
            }

            if (!referenceInputStartedInHive || !hiveRect.Contains(current.mousePosition))
            {
                referenceInputStartedInHive = false;
                hoveredReferenceHotspotId = string.Empty;
                return;
            }

            if (referenceInputDragging)
            {
                referenceInputDragging = false;
                referenceInputStartedInHive = false;
                referenceSelectionSuppressed = false;
                hoveredReferenceHotspotId = string.Empty;
                return;
            }

            if (referenceSelectionSuppressed)
            {
                referenceInputStartedInHive = false;
                referenceSelectionSuppressed = false;
                hoveredReferenceHotspotId = string.Empty;
                return;
            }

            Vector2 artPoint = ScreenToReferenceArtPoint(artRect, current.mousePosition);
            ReferenceHiveHotspot hotspot = HitReferenceHotspot(artPoint);
            if (string.IsNullOrWhiteSpace(hotspot.CellId))
            {
                referenceInputStartedInHive = false;
                hoveredReferenceHotspotId = string.Empty;
                if (referenceHotspotSelected && !detailPanelClosed) ClearReferenceDetailPanelSelection();
                current.Use();
                return;
            }

            bool guidedCollectionClick = guidedCollectionTutorialStep != GuidedCollectionTutorialStep.Inactive
                && GuidedCollectionTutorialAllowsCollection(hotspot.HotspotId);
            float collected = TryCollectPendingProduction(hotspot.HotspotId);
            bool completedUpgrade = TryCompleteReadyBuildingUpgradeOnTap(hotspot.HotspotId);
            if (collected > 0f)
            {
                Vector2 anchor = GetReferenceVisualAnchor(hotspot) + ManualCollectionMarkerOffset(hotspot.HotspotId);
                Vector2 center = ReferencePoint(artRect, anchor.x, anchor.y);
                Vector2 hudPos = portrait ? new Vector2(Screen.width * 0.5f, 120f) : new Vector2(Screen.width * 0.5f, 80f);
                UIFeedbackSystem.ShowResourceCollected(ManualProductionIcon(hotspot.HotspotId), collected, center, hudPos);
            }
            if ((!guidedCollectionClick || collected <= 0f) && !completedUpgrade)
            {
                activeMainMenuId = string.Empty;
                activeHiveMenu = HiveMenuMode.Hive;
                SelectReferenceHotspot(hotspot);
            }
            else ClearReferenceDetailPanelSelection();
            TryAdvanceGuidedCollectionTutorialTarget(hotspot.HotspotId);
            BeginReferenceFeedbackPulse(FeedbackKindForHotspot(hotspot));
            hoveredReferenceHotspotId = string.Empty;
            referenceInputStartedInHive = false;
            current.Use();
        }

        private static void DrawManualCollectionReadyMarkers(Rect artRect, bool portrait)
        {
            HiveOfflineProductionScreenModel officialModel = OfficialOfflineProductionConfigured()
                ? OfficialOfflineProductionModel()
                : null;
            // "Collecting" ne concerne qu'un seul batiment a la fois mais c'est un etat
            // partage par les 3 ressources - le traiter comme Ready evite que les icones des
            // deux AUTRES batiments disparaissent le temps d'une collecte ailleurs.
            if (officialModel != null && officialModel.State != HiveOfflineProductionScreenState.Ready &&
                officialModel.State != HiveOfflineProductionScreenState.Collecting &&
                !(officialModel.State == HiveOfflineProductionScreenState.Error &&
                  string.Equals(officialModel.ErrorCode, "network_unavailable", StringComparison.Ordinal)))
                return;
            for (int i = 0; i < ReferenceHotspots.Length; i++)
            {
                ReferenceHiveHotspot hotspot = ReferenceHotspots[i];
                string icon = ManualProductionIcon(hotspot.HotspotId);
                // Cote serveur officiel, un tap collecte des qu'il y a 1 unite entiere prete
                // (voir TryCollectPendingProduction/CanCollect) - le marqueur doit apparaitre
                // au meme seuil, sinon la collecte se produit silencieusement sans icone visible.
                float readyThreshold = OfficialOfflineProductionConfigured() ? 1f : CollectionReadyThreshold;
                if (string.IsNullOrWhiteSpace(icon) || DisplayedPendingManualProduction(hotspot.HotspotId) < readyThreshold) continue;

                Vector2 anchor = GetReferenceVisualAnchor(hotspot) + ManualCollectionMarkerOffset(hotspot.HotspotId);
                Vector2 center = ReferencePoint(artRect, anchor.x, anchor.y);
                float baseSize = portrait ? 68f : 72f;
                float pulse = productionReducedMotionForProof ? 1f : 1f + Mathf.Sin(NowForUi() * 4.2f + i * 0.7f) * 0.055f;
                float size = baseSize * pulse;
                Rect iconRect = new Rect(center.x - size * 0.5f, center.y - size * 0.5f, size, size);
                if (!IsReferenceTokenVisible(iconRect) || !ReferenceOverlayClipRect().Overlaps(iconRect)) continue;

                Color previous = GUI.color;
                GUI.color = new Color(1f, 0.72f, 0.10f, productionReducedMotionForProof ? 0.52f : 0.68f);
                Rect glow = new Rect(iconRect.x - size * 0.36f, iconRect.y - size * 0.36f, size * 1.72f, size * 1.72f);
                GUI.DrawTexture(glow, GetPremiumTexture("selected-glow"), ScaleMode.ScaleToFit, true);
                GUI.color = Color.white;
                DrawGameIcon(iconRect, icon, Color.white);
                GUI.color = previous;
            }
        }

        // Demande explicite de Jeff : la fin d'une amelioration de batiment doit se voir
        // directement sur le batiment (comme les marqueurs de collecte), sans passer par
        // "Actualiser" - ce badge et le tap direct dans HandleReferenceHotspotClick couvrent
        // ensemble cette demande.
        private static void DrawBuildingUpgradeReadyMarkers(Rect artRect, bool portrait)
        {
            if (!OfficialBuildingUpgradeConfigured()) return;
            HiveBuildingUpgradeScreenModel model = OfficialBuildingUpgradeModel();
            if (model == null) return;

            for (int i = 0; i < ReferenceHotspots.Length; i++)
            {
                ReferenceHiveHotspot hotspot = ReferenceHotspots[i];
                if (!IsOfficialUpgradeBuilding(hotspot.HotspotId) || !model.CanComplete(hotspot.HotspotId)) continue;

                Vector2 anchor = GetReferenceVisualAnchor(hotspot) + new Vector2(portrait ? 36f : 42f, portrait ? -50f : -56f);
                Vector2 center = ReferencePoint(artRect, anchor.x, anchor.y);
                float baseSize = portrait ? 52f : 56f;
                float pulse = productionReducedMotionForProof ? 1f : 1f + Mathf.Sin(NowForUi() * 3.4f + i * 0.9f) * 0.08f;
                float size = baseSize * pulse;
                Rect iconRect = new Rect(center.x - size * 0.5f, center.y - size * 0.5f, size, size);
                if (!IsReferenceTokenVisible(iconRect) || !ReferenceOverlayClipRect().Overlaps(iconRect)) continue;

                Color previous = GUI.color;
                GUI.color = new Color(1f, 0.92f, 0.58f, productionReducedMotionForProof ? 0.60f : 0.78f);
                Rect glow = new Rect(iconRect.x - size * 0.4f, iconRect.y - size * 0.4f, size * 1.8f, size * 1.8f);
                GUI.DrawTexture(glow, GetPremiumTexture("selected-glow"), ScaleMode.ScaleToFit, true);
                GUI.color = Color.white;
                DrawGameIcon(iconRect, "upgrade-ready", Color.white);
                GUI.color = previous;
            }
        }

        private static void DrawManualCollectionFeedback(Rect artRect, bool portrait)
        {
            float elapsed = NowForUi() - localPreviewCollectionFeedbackStartedAt;
            if (elapsed < 0f || elapsed > CollectionFeedbackSeconds || string.IsNullOrWhiteSpace(localPreviewLastCollectedHotspotId)) return;

            ReferenceHiveHotspot hotspot = FindReferenceHotspot(localPreviewLastCollectedHotspotId);
            if (string.IsNullOrWhiteSpace(hotspot.HotspotId)) return;

            float t = Mathf.Clamp01(elapsed / CollectionFeedbackSeconds);
            float eased = 1f - Mathf.Pow(1f - t, 3f);
            Vector2 anchor = GetReferenceVisualAnchor(hotspot) + ManualCollectionMarkerOffset(hotspot.HotspotId);
            Vector2 start = ReferencePoint(artRect, anchor.x, anchor.y);
            Vector2 end = start + new Vector2(portrait ? 0f : -24f, portrait ? -92f : -118f);
            Vector2 center = productionReducedMotionForProof ? start + new Vector2(0f, -34f) : Vector2.Lerp(start, end, eased);
            center.x += productionReducedMotionForProof ? 0f : Mathf.Sin(t * Mathf.PI) * 18f;
            float alpha = 1f - Mathf.Clamp01((t - 0.58f) / 0.42f);
            float size = Mathf.Lerp(portrait ? 68f : 72f, portrait ? 40f : 44f, eased);
            Rect iconRect = new Rect(center.x - size * 0.5f, center.y - size * 0.5f, size, size);

            Color previous = GUI.color;
            GUI.color = new Color(1f, 1f, 1f, alpha);
            GUI.DrawTexture(new Rect(iconRect.x - 12f, iconRect.y - 12f, iconRect.width + 24f, iconRect.height + 24f), GetPremiumTexture("selected-glow"), ScaleMode.ScaleToFit, true);
            DrawGameIcon(iconRect, localPreviewLastCollectedResourceIcon, new Color(1f, 1f, 1f, alpha));
            GUI.color = previous;

            float carrierSize = portrait ? 34f : 38f;
            Vector2 carrierCenter = center + new Vector2(size * 0.58f, size * 0.10f);
            Rect carrierRect = new Rect(carrierCenter.x - carrierSize * 0.5f, carrierCenter.y - carrierSize * 0.5f, carrierSize, carrierSize);
            DrawRuntimeWorkerBee(carrierRect, 0.18f, alpha * 0.94f, NowForUi(), false);
        }

        private static bool GuidedOpeningRouteFeedbackActive()
        {
            float elapsed = NowForUi() - guidedOpeningRouteFeedbackStartedAt;
            return elapsed >= 0f
                && elapsed <= GuidedOpeningRouteFeedbackSeconds
                && (guidedOpeningRouteFeedbackPlan == "reserve_route" || guidedOpeningRouteFeedbackPlan == "nursery_relay");
        }

        private static void BeginGuidedOpeningRouteFeedback(string plan, float honey, float stability)
        {
            guidedOpeningRouteFeedbackPlan = plan == "nursery_relay" ? "nursery_relay" : "reserve_route";
            guidedOpeningRouteFeedbackHoney = Mathf.Max(0f, honey);
            guidedOpeningRouteFeedbackStability = Mathf.Max(0f, stability);
            guidedOpeningRouteFeedbackStartedAt = NowForUi();
            guidedOpeningRouteFeedbackSequence++;
        }

        private static void DrawGuidedOpeningRouteFeedback(Rect artRect, bool portrait)
        {
            if (!GuidedOpeningRouteFeedbackActive()) return;

            float elapsed = Mathf.Max(0f, NowForUi() - guidedOpeningRouteFeedbackStartedAt);
            float life = Mathf.Clamp01(elapsed / GuidedOpeningRouteFeedbackSeconds);
            float alpha = life < 0.72f ? 1f : 1f - Mathf.Clamp01((life - 0.72f) / 0.28f);
            float motion = productionReducedMotionForProof ? 0.35f : Mathf.Repeat(elapsed * 0.32f, 1f);
            ReferenceHiveHotspot reserveHotspot = FindReferenceHotspot("honey_storage");
            Vector2 reserve = ReferencePoint(artRect, GetReferenceVisualAnchor(reserveHotspot).x, GetReferenceVisualAnchor(reserveHotspot).y);
            Color routeColor = guidedOpeningRouteFeedbackPlan == "nursery_relay"
                ? new Color(0.70f, 0.94f, 0.30f, 0.94f * alpha)
                : new Color(1f, 0.72f, 0.10f, 0.96f * alpha);

            if (guidedOpeningRouteFeedbackPlan == "nursery_relay")
            {
                ReferenceHiveHotspot nurseryHotspot = FindReferenceHotspot("nursery_cluster");
                Vector2 nursery = ReferencePoint(artRect, GetReferenceVisualAnchor(nurseryHotspot).x, GetReferenceVisualAnchor(nurseryHotspot).y);
                Vector2 waypoint = reserve + new Vector2(portrait ? -140f : -300f, portrait ? 82f : 178f);
                DrawGuidedOpeningRouteSegment(reserve, waypoint, portrait, routeColor, alpha);
                DrawGuidedOpeningRouteSegment(waypoint, nursery, portrait, routeColor, alpha);

                DrawRouteEndpointGlow(reserve, portrait, routeColor, alpha);
                DrawRouteEndpointGlow(nursery, portrait, routeColor, alpha);
                for (int i = 0; i < 3; i++)
                {
                    float fraction = productionReducedMotionForProof
                        ? (i + 1f) / 4f
                        : Mathf.Repeat(motion + i / 3f, 1f);
                    Vector2 center = fraction < 0.5f
                        ? Vector2.Lerp(reserve, waypoint, fraction * 2f)
                        : Vector2.Lerp(waypoint, nursery, (fraction - 0.5f) * 2f);
                    float lift = Mathf.Sin(fraction * Mathf.PI) * (portrait ? 10f : 14f);
                    center.y -= lift;
                    float size = portrait ? 28f : 34f;
                    DrawRuntimeWorkerBee(new Rect(center.x - size * 0.5f, center.y - size * 0.5f, size, size), 0.18f, 0.96f * alpha, NowForUi() + i * 0.17f, false);
                }

                DrawGuidedOpeningRouteFeedbackLabel(
                    waypoint + new Vector2(0f, portrait ? -34f : -42f),
                    BeeLocalization.Text("tutorial.chapter_01.route_feedback.nursery", "Relais couvain · +3 stabilité"),
                    portrait,
                    routeColor,
                    alpha);
                return;
            }

            Vector2[] reserveContour = GetReferenceVisualContour(reserveHotspot);
            if (reserveContour.Length >= 3)
            {
                float pulse = productionReducedMotionForProof ? 1f : 0.82f + Mathf.Sin(elapsed * 5f) * 0.18f;
                DrawReferencePolygon(artRect, reserveContour, new Color(0.08f, 0.04f, 0f, 0.78f * alpha), portrait ? 7f : 9f);
                DrawReferencePolygon(artRect, reserveContour, routeColor, (portrait ? 3.2f : 4.2f) * pulse);
            }

            DrawRouteEndpointGlow(reserve, portrait, routeColor, alpha);
            for (int i = 0; i < 3; i++)
            {
                float angle = (productionReducedMotionForProof ? 0.35f : elapsed * 1.7f) + i * Mathf.PI * 2f / 3f;
                float radius = portrait ? 48f : 60f;
                Vector2 center = reserve + new Vector2(Mathf.Cos(angle) * radius, Mathf.Sin(angle) * radius * 0.58f);
                float size = portrait ? 28f : 34f;
                DrawRuntimeWorkerBee(new Rect(center.x - size * 0.5f, center.y - size * 0.5f, size, size), 0.18f, 0.96f * alpha, NowForUi() + i * 0.17f, false);
            }

            DrawGuidedOpeningRouteFeedbackLabel(
                reserve + new Vector2(0f, portrait ? 78f : -88f),
                BeeLocalization.Text("tutorial.chapter_01.route_feedback.reserve", "Réserve directe · +180 miel"),
                portrait,
                routeColor,
                alpha);
        }

        private static void DrawRouteEndpointGlow(Vector2 center, bool portrait, Color accent, float alpha)
        {
            float size = portrait ? 92f : 112f;
            Color previous = GUI.color;
            GUI.color = new Color(accent.r, accent.g, accent.b, 0.34f * alpha);
            GUI.DrawTexture(new Rect(center.x - size * 0.5f, center.y - size * 0.5f, size, size), GetPremiumTexture("selected-glow"), ScaleMode.ScaleToFit, true);
            GUI.color = previous;
        }

        private static void DrawGuidedOpeningRouteSegment(Vector2 from, Vector2 to, bool portrait, Color accent, float alpha)
        {
            DrawGuiLine(from, to, new Color(0.06f, 0.035f, 0.005f, 0.82f * alpha), portrait ? 8f : 10f);
            DrawGuiLine(from, to, accent, portrait ? 3f : 4f);
        }

        private static void DrawGuidedOpeningRouteFeedbackLabel(Vector2 center, string text, bool portrait, Color accent, float alpha)
        {
            float width = portrait ? 172f : 208f;
            float height = portrait ? 30f : 34f;
            Rect label = new Rect(center.x - width * 0.5f, center.y - height * 0.5f, width, height);
            Rect clip = ReferenceOverlayClipRect();
            label.x = Mathf.Clamp(label.x, clip.x + 4f, clip.xMax - label.width - 4f);
            label.y = Mathf.Clamp(label.y, clip.y + 4f, clip.yMax - label.height - 4f);
            DrawPremiumPanel(label, new Color(0.055f, 0.032f, 0.008f, 0.94f * alpha), new Color(accent.r, accent.g, accent.b, 0.92f * alpha));
            GUI.Label(label, text, new GUIStyle(centeredTinyLabelStyle) { fontSize = portrait ? 10 : 11 });
        }

        private static void DrawNurseryVitalityLayer(Rect artRect, bool portrait)
        {
            if (!ShouldDrawNurseryVitalityLayer()) return;

            ReferenceHiveHotspot nurseryHotspot = FindReferenceHotspot("nursery_cluster");
            Vector2 nurseryArtCenter = GetReferenceVisualAnchor(nurseryHotspot);
            Vector2 nurseryCenter = ReferencePoint(artRect, nurseryArtCenter.x, nurseryArtCenter.y);
            HiveBroodVitalityScreenModel official = OfficialBroodVitalityModel();
            bool useOfficial = OfficialBroodVitalityConfigured() &&
                official != null;
            bool officialInitialized = useOfficial && official.Initialized;
            float displayedNutrition = useOfficial
                ? officialInitialized ? official.Nutrition : 0f
                : localPreviewBroodNutrition;
            float displayedStability = useOfficial
                ? officialInitialized ? official.Stability : 0f
                : localPreviewBroodStability;
            string tierId = useOfficial && !officialInitialized
                ? "uninitialized"
                : BroodVitalityTierId(
                    displayedNutrition,
                    displayedStability);
            Color accent = BroodVitalityAccent(tierId);
            float quality = Mathf.Clamp01(
                Mathf.Min(displayedNutrition, displayedStability) / 100f);
            float time = NowForUi();

            DrawNurseryCellVitality(artRect, portrait, accent, quality, time);
            float remainingSeconds;
            bool operationActive;
            if (useOfficial)
            {
                operationActive = official.ActiveOperation != null;
                remainingSeconds = operationActive
                    ? (float)official.Remaining(
                        broodVitalityController.Elapsed).TotalSeconds
                    : 0f;
            }
            else
            {
                operationActive = TryGetBroodVitalityOperation(
                    out _,
                    out remainingSeconds);
            }
            if (operationActive) DrawNurseryCareFlow(nurseryCenter, portrait, accent, time);

            Rect card = NurseryVitalityCardRectForScreen(
                portrait,
                Screen.width,
                Screen.height,
                nurseryCenter);
            DrawPremiumPanel(card, new Color(0.045f, 0.032f, 0.016f, 0.94f), new Color(accent.r, accent.g, accent.b, 0.92f));

            string tier = LocalizedBroodVitalityTier(tierId);
            string title = BeeLocalization.Text("living_hive.brood_vitality.title", "Couvain") + " · " + tier;
            GUI.Label(
                new Rect(card.x + 10f, card.y + 7f, card.width - 20f, 18f),
                title,
                new GUIStyle(tinyLabelStyle)
                {
                    fontSize = portrait ? 11 : 12,
                    fontStyle = FontStyle.Bold,
                    normal = { textColor = Color.white }
                });

            string metrics = useOfficial && !officialInitialized
                ? BeeLocalization.Text(
                    "brood_care.status.uninitialized_short",
                    "Nutrition -- · Stabilité --")
                : BeeLocalization.Format(
                    "living_hive.brood_vitality.metrics",
                    Mathf.RoundToInt(displayedNutrition),
                    Mathf.RoundToInt(displayedStability));
            GUI.Label(
                new Rect(card.x + 10f, card.y + 27f, card.width - 20f, 17f),
                metrics,
                new GUIStyle(tinyLabelStyle) { fontSize = portrait ? 10 : 11 });

            if (operationActive)
            {
                string operation = BeeLocalization.Format(
                    "living_hive.brood_vitality.operation",
                    Mathf.CeilToInt(remainingSeconds));
                GUI.Label(
                    new Rect(card.x + 10f, card.y + 43f, card.width - 20f, 14f),
                    operation,
                    new GUIStyle(tinyLabelStyle)
                    {
                        fontSize = portrait ? 9 : 10,
                        normal = { textColor = new Color(accent.r, accent.g, accent.b, 1f) }
                    });
            }

            float meterY = card.yMax - 9f;
            float meterGap = 6f;
            float meterWidth = (card.width - 20f - meterGap) * 0.5f;
            DrawBroodVitalityMeter(
                new Rect(card.x + 10f, meterY, meterWidth, 4f),
                displayedNutrition / 100f,
                new Color(1f, 0.70f, 0.16f, 1f));
            DrawBroodVitalityMeter(
                new Rect(card.x + 10f + meterWidth + meterGap, meterY, meterWidth, 4f),
                displayedStability / 100f,
                new Color(0.54f, 0.92f, 0.42f, 1f));
        }

        private static bool ShouldDrawNurseryVitalityLayer()
        {
            bool broodChapter = guidedCollectionTutorialStep >= GuidedCollectionTutorialStep.BroodWelcome
                && guidedCollectionTutorialStep <= GuidedCollectionTutorialStep.BroodCompleted;
            bool nurserySelected = referenceHotspotSelected
                && !detailPanelClosed
                && string.Equals(focusedReferenceHotspotId, "nursery_cluster", StringComparison.Ordinal);
            bool nurseryTask = string.Equals(ActiveBeeTaskZoneId(), "nursery_cluster", StringComparison.Ordinal);
            bool recentFeeding = NowForUi() - localPreviewBroodFeedingFeedbackStartedAt <= BroodFeedingFeedbackSeconds;
            HiveBroodVitalityScreenModel official =
                OfficialBroodVitalityModel();
            bool officialCare = OfficialBroodVitalityConfigured() &&
                official != null &&
                official.ActiveOperation != null;
            return broodChapter ||
                nurserySelected ||
                nurseryTask ||
                recentFeeding ||
                officialCare;
        }

        private static void DrawNurseryCellVitality(Rect artRect, bool portrait, Color accent, float quality, float time)
        {
            Vector2[] cells =
            {
                new Vector2(548f, 202f),
                new Vector2(592f, 181f),
                new Vector2(638f, 205f),
                new Vector2(558f, 248f),
                new Vector2(611f, 244f),
                new Vector2(661f, 260f),
                new Vector2(589f, 290f)
            };
            float scale = Mathf.Clamp(artRect.width / ReferenceArtWidth, 0.80f, 1.45f);
            float size = Mathf.Clamp(34f * scale, portrait ? 24f : 26f, portrait ? 38f : 44f);
            Color previous = GUI.color;

            for (int i = 0; i < cells.Length; i++)
            {
                Vector2 center = ReferencePoint(artRect, cells[i].x, cells[i].y);
                float pulse = productionReducedMotionForProof
                    ? 1f
                    : 0.90f + Mathf.Sin(time * (2.2f + quality) + i * 0.82f) * 0.10f;
                float cellSize = size * pulse;
                float alpha = (0.16f + quality * 0.24f) * (i % 2 == 0 ? 1f : 0.82f);
                GUI.color = new Color(accent.r, accent.g, accent.b, alpha);
                GUI.DrawTexture(
                    new Rect(center.x - cellSize * 0.5f, center.y - cellSize * 0.5f, cellSize, cellSize),
                    GetPremiumTexture("selected-glow"),
                    ScaleMode.ScaleToFit,
                    true);
            }

            GUI.color = previous;
        }

        private static void DrawNurseryCareFlow(Vector2 nurseryCenter, bool portrait, Color accent, float time)
        {
            Vector2 source = nurseryCenter + new Vector2(portrait ? -68f : -92f, portrait ? 48f : 58f);
            DrawGuiLine(source, nurseryCenter, new Color(0.04f, 0.025f, 0.008f, 0.70f), portrait ? 5f : 6f);
            DrawGuiLine(source, nurseryCenter, new Color(accent.r, accent.g, accent.b, 0.64f), portrait ? 1.8f : 2.2f);

            Color previous = GUI.color;
            for (int i = 0; i < 3; i++)
            {
                float fraction = productionReducedMotionForProof
                    ? (i + 1f) / 4f
                    : Mathf.Repeat(time * 0.26f + i / 3f, 1f);
                Vector2 center = Vector2.Lerp(source, nurseryCenter, fraction);
                center.y -= productionReducedMotionForProof ? 0f : Mathf.Sin(fraction * Mathf.PI) * (portrait ? 5f : 7f);
                float size = portrait ? 9f : 11f;
                GUI.color = new Color(accent.r, accent.g, accent.b, 0.84f);
                GUI.DrawTexture(
                    new Rect(center.x - size * 0.5f, center.y - size * 0.5f, size, size),
                    GetPremiumTexture("selected-glow"),
                    ScaleMode.ScaleToFit,
                    true);
            }
            GUI.color = previous;
        }

        private static Rect NurseryVitalityCardRectForScreen(bool portrait, float screenWidth, float screenHeight, Vector2 nurseryCenter)
        {
            float left = portrait ? 8f : 156f;
            float top = portrait ? 126f : 84f;
            float right = portrait ? 8f : 24f;
            float bottom = portrait ? 270f : 140f;
            float availableWidth = Mathf.Max(1f, screenWidth - left - right);
            float availableHeight = Mathf.Max(1f, screenHeight - top - bottom);
            float width = Mathf.Min(portrait ? NurseryVitalityCardPortraitWidth : NurseryVitalityCardLandscapeWidth, availableWidth);
            float height = Mathf.Min(NurseryVitalityCardHeight, availableHeight);
            float desiredX = nurseryCenter.x + (portrait ? 58f : 88f);
            float desiredY = nurseryCenter.y - height * 0.50f;
            return new Rect(
                Mathf.Clamp(desiredX, left, left + availableWidth - width),
                Mathf.Clamp(desiredY, top, top + availableHeight - height),
                width,
                height);
        }

        private static void DrawBroodVitalityMeter(Rect rect, float progress, Color accent)
        {
            Color previous = GUI.color;
            GUI.color = new Color(0.015f, 0.012f, 0.008f, 0.92f);
            GUI.DrawTexture(rect, Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            GUI.color = accent;
            GUI.DrawTexture(
                new Rect(rect.x, rect.y, rect.width * Mathf.Clamp01(progress), rect.height),
                Texture2D.whiteTexture,
                ScaleMode.StretchToFill,
                true);
            GUI.color = previous;
        }

        private static string BroodVitalityTierId(float nutrition, float stability)
        {
            float quality = Mathf.Min(nutrition, stability);
            if (quality < 40f) return "care_required";
            if (quality < 65f) return "watch";
            if (quality < 85f) return "stable";
            return "thriving";
        }

        private static Color BroodVitalityAccent(string tierId)
        {
            if (tierId == "uninitialized") return new Color(0.62f, 0.66f, 0.70f, 1f);
            if (tierId == "care_required") return new Color(1f, 0.36f, 0.18f, 1f);
            if (tierId == "watch") return new Color(1f, 0.68f, 0.14f, 1f);
            if (tierId == "stable") return new Color(0.58f, 0.92f, 0.36f, 1f);
            return new Color(0.36f, 0.94f, 0.78f, 1f);
        }

        private static string LocalizedBroodVitalityTier(string tierId)
        {
            if (tierId == "uninitialized") return BeeLocalization.Text("brood_care.tier.uninitialized", "Non initialisé");
            if (tierId == "care_required") return BeeLocalization.Text("living_hive.brood_vitality.tier.care_required", "Soin requis");
            if (tierId == "watch") return BeeLocalization.Text("living_hive.brood_vitality.tier.watch", "À surveiller");
            if (tierId == "stable") return BeeLocalization.Text("living_hive.brood_vitality.tier.stable", "Stable");
            return BeeLocalization.Text("living_hive.brood_vitality.tier.thriving", "Florissant");
        }

        private static bool TryGetBroodVitalityOperation(out string operationId, out float remainingSeconds)
        {
            operationId = "none";
            float startedAt = -100f;
            float duration = 0f;
            switch (guidedCollectionTutorialStep)
            {
                case GuidedCollectionTutorialStep.BroodDiagnosisRunning:
                    operationId = "diagnosis";
                    startedAt = guidedBroodDiagnosisStartedAt;
                    duration = GuidedBroodDiagnosisDuration;
                    break;
                case GuidedCollectionTutorialStep.BroodPreparationRunning:
                    operationId = "preparation";
                    startedAt = guidedBroodPreparationStartedAt;
                    duration = guidedBroodPreparationDuration;
                    break;
                case GuidedCollectionTutorialStep.BroodNursesWorking:
                    operationId = "manual_care";
                    startedAt = guidedBroodCareStartedAt;
                    duration = guidedBroodCareDuration;
                    break;
                case GuidedCollectionTutorialStep.BroodCircuitTreatmentRunning:
                    operationId = "circuit_treatment";
                    startedAt = guidedBroodCircuitTreatmentStartedAt;
                    duration = guidedBroodCircuitTreatmentDuration;
                    break;
                case GuidedCollectionTutorialStep.BroodIncubationInspectionRunning:
                    operationId = "incubation_inspection";
                    startedAt = guidedBroodIncubationInspectionStartedAt;
                    duration = guidedBroodIncubationInspectionDuration;
                    break;
                case GuidedCollectionTutorialStep.BroodIncubationTreatmentRunning:
                    operationId = "incubation_treatment";
                    startedAt = guidedBroodIncubationTreatmentStartedAt;
                    duration = guidedBroodIncubationTreatmentDuration;
                    break;
                case GuidedCollectionTutorialStep.BroodIncubationDoctrineRunning:
                    operationId = "incubation_doctrine";
                    startedAt = guidedBroodIncubationDoctrineStartedAt;
                    duration = guidedBroodIncubationDoctrineDuration;
                    break;
            }

            if (duration <= 0f)
            {
                remainingSeconds = 0f;
                return false;
            }

            if (operationId == "incubation_inspection" && guidedBroodIncubationInspectionFrozenProgressForProof >= 0f)
            {
                remainingSeconds = duration * (1f - guidedBroodIncubationInspectionFrozenProgressForProof);
                return true;
            }

            remainingSeconds = Mathf.Max(0f, duration - Mathf.Max(0f, NowForUi() - startedAt));
            return true;
        }

