        private static void SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep step)
        {
            guidedCollectionTutorialStep = step;
            guidedCollectionTutorialStepStartedAt = NowForUi();
            SaveLocalPreviewTutorialCheckpoint(step);
            int chapterNumber = GuidedChapterNumberForWelcomeStep(step);
            if (chapterNumber > 0) PrepareGuidedChapterIntro(chapterNumber);
        }

        private static int TutorialChapterForStep(GuidedCollectionTutorialStep step)
        {
            if (step >= GuidedCollectionTutorialStep.Welcome && step <= GuidedCollectionTutorialStep.Completed) return 1;
            if (step >= GuidedCollectionTutorialStep.BroodWelcome && step <= GuidedCollectionTutorialStep.BroodCompleted) return 2;
            if (step >= GuidedCollectionTutorialStep.WorkerWelcome && step <= GuidedCollectionTutorialStep.WorkerCompleted) return 3;
            if (step >= GuidedCollectionTutorialStep.UpgradeWelcome && step <= GuidedCollectionTutorialStep.UpgradeCompleted) return 4;
            if (step >= GuidedCollectionTutorialStep.DefenseWelcome && step <= GuidedCollectionTutorialStep.DefenseCompleted) return 5;
            if (step >= GuidedCollectionTutorialStep.WorldWelcome && step <= GuidedCollectionTutorialStep.WorldReturned) return 6;
            if (step >= GuidedCollectionTutorialStep.ForageWelcome && step <= GuidedCollectionTutorialStep.ForageCompleted) return 7;
            return 0;
        }

        private static GuidedCollectionTutorialStep TutorialWelcomeForChapter(int chapter)
        {
            switch (chapter)
            {
                case 2: return GuidedCollectionTutorialStep.BroodWelcome;
                case 3: return GuidedCollectionTutorialStep.WorkerWelcome;
                case 4: return GuidedCollectionTutorialStep.UpgradeWelcome;
                case 5: return GuidedCollectionTutorialStep.DefenseWelcome;
                case 6: return GuidedCollectionTutorialStep.WorldWelcome;
                case 7: return GuidedCollectionTutorialStep.ForageWelcome;
                default: return GuidedCollectionTutorialStep.Welcome;
            }
        }

        private static void SaveLocalPreviewTutorialCheckpoint(GuidedCollectionTutorialStep step)
        {
            int chapter = TutorialChapterForStep(step);
            if (chapter == 0 || localPreviewTutorialCheckpointStore == null) return;
            if (localPreviewTutorialCheckpoint == null || localPreviewTutorialCheckpoint.chapter != chapter)
            {
                localPreviewTutorialCheckpoint = new LocalPreviewTutorialCheckpoint
                {
                    checkpointId = Guid.NewGuid().ToString("N"), chapter = chapter, completedChapters = Mathf.Clamp(chapter - 1, 0, 5),
                    chapterStartHoney = localPreviewHoney, chapterStartWax = localPreviewWax, chapterStartPollen = localPreviewPollen,
                    chapterStartCapacityUsed = localPreviewCapacityUsed, chapterStartCapacityMax = localPreviewCapacityMax,
                    chapterStartWorkers = localPreviewWorkers, chapterStartBroodNutrition = localPreviewBroodNutrition,
                    chapterStartBroodStability = localPreviewBroodStability, chapterStartSecurity = localPreviewHiveSecurity
                };
            }
            localPreviewTutorialCheckpoint.interruptedObjective = step.ToString();
            localPreviewTutorialCheckpoint.interruptedObjectiveIndex = TutorialObjectiveIndexForChapter(chapter);
            localPreviewTutorialCheckpointStore.Write(JsonUtility.ToJson(localPreviewTutorialCheckpoint));
        }

        private static int TutorialObjectiveIndexForChapter(int chapter)
        {
            switch (chapter)
            {
                case 1: return GuidedOpeningObjectiveIndex();
                case 2: return GuidedBroodObjectiveIndex();
                case 3: return GuidedWorkerObjectiveIndex();
                case 4: return GuidedUpgradeObjectiveIndex();
                case 5: return GuidedDefenseObjectiveIndex();
                default: return 1;
            }
        }

        private static bool TryRestoreLocalPreviewTutorialCheckpoint()
        {
            if (localPreviewTutorialRestoreAttempted) return localPreviewTutorialResumeNoticeVisible;
            localPreviewTutorialRestoreAttempted = true;
            string json = localPreviewTutorialCheckpointStore?.Read();
            if (string.IsNullOrWhiteSpace(json)) return false;
            try { localPreviewTutorialCheckpoint = JsonUtility.FromJson<LocalPreviewTutorialCheckpoint>(json); } catch { localPreviewTutorialCheckpoint = null; }
            if (localPreviewTutorialCheckpoint == null || localPreviewTutorialCheckpoint.version != 1 || localPreviewTutorialCheckpoint.chapter < 1 || localPreviewTutorialCheckpoint.chapter > 7) return false;
            localPreviewHoney = localPreviewTutorialCheckpoint.chapterStartHoney; localPreviewWax = localPreviewTutorialCheckpoint.chapterStartWax; localPreviewPollen = localPreviewTutorialCheckpoint.chapterStartPollen;
            localPreviewCapacityUsed = localPreviewTutorialCheckpoint.chapterStartCapacityUsed; localPreviewCapacityMax = localPreviewTutorialCheckpoint.chapterStartCapacityMax;
            localPreviewWorkers = localPreviewTutorialCheckpoint.chapterStartWorkers; localPreviewBroodNutrition = localPreviewTutorialCheckpoint.chapterStartBroodNutrition;
            localPreviewBroodStability = localPreviewTutorialCheckpoint.chapterStartBroodStability; localPreviewHiveSecurity = localPreviewTutorialCheckpoint.chapterStartSecurity;
            SeedGuidedOpeningActProgress(localPreviewTutorialCheckpoint.completedChapters);
            localPreviewTutorialInterruptedObjective = localPreviewTutorialCheckpoint.interruptedObjective;
            localPreviewTutorialInterruptedObjectiveLabel = BeeLocalization.Text("tutorial.resume.step", "Étape") + " "
                + Mathf.Max(1, localPreviewTutorialCheckpoint.interruptedObjectiveIndex).ToString(CultureInfo.InvariantCulture) + " · "
                + BeeLocalization.Text("tutorial.resume.chapter", "chapitre") + " " + localPreviewTutorialCheckpoint.chapter.ToString(CultureInfo.InvariantCulture);
            guidedCollectionTutorialStep = TutorialWelcomeForChapter(localPreviewTutorialCheckpoint.chapter);
            guidedCollectionTutorialStepStartedAt = NowForUi();
            PrepareGuidedChapterIntro(localPreviewTutorialCheckpoint.chapter);
            localPreviewTutorialResumeNoticeVisible = true;
            referenceSurfaceMode = ReferenceSurfaceMode.Hive;
            localPreviewSessionPrompt = "Reprise securisee du chapitre " + localPreviewTutorialCheckpoint.chapter.ToString(CultureInfo.InvariantCulture);
            return true;
        }

