        private static void SeedGuidedOpeningActProgress(int completedChapters)
        {
            ResetGuidedOpeningActRewards();
            guidedOpeningActMilestones = Mathf.Clamp(completedChapters, 0, 5);
            guidedChapterRewardClaimCount = guidedOpeningActMilestones;
            if (guidedOpeningActMilestones >= 1)
            {
                EnsureLocalPreviewStrategicProfileLoaded();
                if (localPreviewStrategicProfile != null && localPreviewStrategicProfile.openingReward == "mixed_foundation")
                {
                    guidedOpeningActRewardHoney += GuidedChapterOneMixedRewardHoney;
                    guidedOpeningActRewardPollen += GuidedChapterOneMixedRewardPollen;
                }
                else guidedOpeningActRewardHoney += GuidedChapterOneRewardHoney;
            }
            if (guidedOpeningActMilestones >= 2)
            {
                guidedOpeningActRewardHoney += GuidedChapterTwoRewardHoney;
                guidedOpeningActRewardWax += GuidedChapterTwoRewardWax;
            }
            if (guidedOpeningActMilestones >= 3)
            {
                guidedOpeningActRewardHoney += GuidedChapterThreeRewardHoney;
                guidedOpeningActRewardPollen += GuidedChapterThreeRewardPollen;
            }
            if (guidedOpeningActMilestones >= 4)
            {
                guidedOpeningActRewardHoney += GuidedChapterFourRewardHoney;
                guidedOpeningActRewardWax += GuidedChapterFourRewardWax;
            }
            if (guidedOpeningActMilestones >= 5)
            {
                guidedOpeningActRewardHoney += GuidedChapterFiveRewardHoney;
                guidedOpeningActRewardWax += GuidedChapterFiveRewardWax;
            }

            guidedLastChapterRewardId = guidedOpeningActMilestones > 0
                ? "chapter_" + guidedOpeningActMilestones.ToString(CultureInfo.InvariantCulture)
                : "none";
        }

        private sealed class LocalPreviewRewardInventory : IRewardInventory
        {
            public bool TryAdd(Reward reward)
            {
                if (reward.Type != RewardType.Resource || !localRewardWriters.TryGetValue(reward.Id, out Action<long> writer))
                    return false;
                writer(reward.Amount);
                return true;
            }
        }

        private static RewardPipeline CreateLocalRewardPipeline()
        {
            var pipeline = new RewardPipeline(new LocalPreviewRewardInventory());
            pipeline.RegisterHandler(RewardType.Resource, new InventoryRewardHandler());
            return pipeline;
        }

        private static bool ClaimGuidedChapterReward(int chapter, float honey, float wax, float pollen)
        {
            if (chapter <= guidedOpeningActMilestones || chapter < 1 || chapter > 5) return false;

            guidedLastChapterRewardHoney = Mathf.Max(0f, honey);
            guidedLastChapterRewardWax = Mathf.Max(0f, wax);
            guidedLastChapterRewardPollen = Mathf.Max(0f, pollen);
            float granted = guidedLastChapterRewardHoney + guidedLastChapterRewardWax + guidedLastChapterRewardPollen;

            var rewards = new RewardBundle("tutorial.chapter_" + chapter.ToString(CultureInfo.InvariantCulture));
            if (guidedLastChapterRewardHoney > 0f)
                rewards.Add(new Reward(RewardType.Resource, "honey", Mathf.RoundToInt(guidedLastChapterRewardHoney)));
            if (guidedLastChapterRewardWax > 0f)
                rewards.Add(new Reward(RewardType.Resource, "wax", Mathf.RoundToInt(guidedLastChapterRewardWax)));
            if (guidedLastChapterRewardPollen > 0f)
                rewards.Add(new Reward(RewardType.Resource, "pollen", Mathf.RoundToInt(guidedLastChapterRewardPollen)));
            if (!localRewardPipeline.TryDispatch(rewards)) return false;
            localPreviewCapacityUsed = Mathf.Min(localPreviewCapacityMax, localPreviewCapacityUsed + granted);
            guidedOpeningActRewardHoney += guidedLastChapterRewardHoney;
            guidedOpeningActRewardWax += guidedLastChapterRewardWax;
            guidedOpeningActRewardPollen += guidedLastChapterRewardPollen;
            guidedOpeningActMilestones = chapter;
            guidedChapterRewardClaimCount++;
            guidedLastChapterRewardId = "chapter_" + chapter.ToString(CultureInfo.InvariantCulture);
            localPreviewResourceFeedbackText = GuidedChapterRewardText();
            localPreviewResourceFeedbackStartedAt = NowForUi();
            BeginReferenceFeedbackPulse("preview");
            return true;
        }

        private static string GuidedChapterRewardText()
        {
            string text = string.Empty;
            if (guidedLastChapterRewardHoney > 0f) text = "+" + Mathf.RoundToInt(guidedLastChapterRewardHoney).ToString(CultureInfo.InvariantCulture) + " miel";
            if (guidedLastChapterRewardWax > 0f) text += (text.Length > 0 ? " · " : "+") + Mathf.RoundToInt(guidedLastChapterRewardWax).ToString(CultureInfo.InvariantCulture) + " cire";
            if (guidedLastChapterRewardPollen > 0f) text += (text.Length > 0 ? " · " : "+") + Mathf.RoundToInt(guidedLastChapterRewardPollen).ToString(CultureInfo.InvariantCulture) + " pollen";
            return string.IsNullOrWhiteSpace(text) ? "Réserve pleine" : text;
        }

        private static bool GuidedCollectionTutorialAllowsCollection(string hotspotId)
        {
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.Inactive) return true;
            bool guidedHoneyCollection = guidedCollectionTutorialStep == GuidedCollectionTutorialStep.CollectHoney
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.HoneySecondCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCircuitCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCommissioningCollect
                || (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningBroodSupplyCollect && guidedOpeningBroodSupplyPlan == "thermal_escort")
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCommissioningCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerTrialCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerFirstShiftCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCertificationCollect
                || (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodWorkerHandoffCollect && guidedBroodWorkerHandoffPlan == "emergence_ration")
                || (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerWorkshopHandoffCollect && guidedWorkerWorkshopHandoffPlan == "honey_logistics")
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitCollectHoney
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessCollectHoney
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseVigilanceCollect;
            if (guidedHoneyCollection) return string.Equals(hotspotId, "honey_storage", StringComparison.Ordinal);
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitCollectPollen
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessCollectPollen
                || (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningBroodSupplyCollect && guidedOpeningBroodSupplyPlan == "royal_jelly_cache"))
                return string.Equals(hotspotId, "warehouse_cells", StringComparison.Ordinal);
            return (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeCalibrationCollect
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsCollect
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkshopDefenseHandoffCollect
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningHygienePurgeCollect
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeStockCheckCollect
                    || (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodWorkerHandoffCollect && guidedBroodWorkerHandoffPlan == "reinforced_operculum")
                    || (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerWorkshopHandoffCollect && guidedWorkerWorkshopHandoffPlan == "wax_convoy")
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodWaxConsolidationCollect)
                && string.Equals(hotspotId, "wax_workshop", StringComparison.Ordinal);
        }

        private static void AdvanceGuidedCollectionTutorialOnCollection(string hotspotId, float collected)
        {
            if (collected <= 0f) return;

            if (string.Equals(hotspotId, "wax_workshop", StringComparison.Ordinal))
            {
                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeCalibrationCollect)
                {
                    guidedUpgradeCalibrationCollectedWax = Mathf.Min(collected, guidedUpgradeCalibrationPendingWax);
                    guidedUpgradeCalibrationPendingWax = 0f;
                    SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.UpgradeBatchQualificationChoice);
                    localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_04.batch_qualification.title");
                }

                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsCollect)
                {
                    guidedUpgradeOperationsCollectedWax += Mathf.Min(collected, guidedUpgradeOperationsPendingWax);
                    guidedUpgradeOperationsPendingWax = 0f;
                    SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.UpgradeOperationsDeploymentChoice);
                    localPreviewSessionPrompt = "Cire recoltee: choisis la chambre a renforcer";
                }

                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerWorkshopHandoffCollect)
                {
                    guidedWorkerWorkshopHandoffCollectedResource = Mathf.Min(collected, guidedWorkerWorkshopHandoffPendingResource);
                    guidedWorkerWorkshopHandoffPendingResource = 0f;
                    SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerWorkshopHandoffCheck);
                    localPreviewSessionPrompt = "Cire recoltee: controle la liaison vers l'atelier";
                }

                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkshopDefenseHandoffCollect)
                {
                    guidedWorkshopDefenseHandoffCollectedWax = Mathf.Min(collected, guidedWorkshopDefenseHandoffPendingWax);
                    guidedWorkshopDefenseHandoffPendingWax = 0f;
                    SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkshopDefenseHandoffCheck);
                    localPreviewSessionPrompt = "Livraison récoltée: contrôle le départ";
                }

                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodWorkerHandoffCollect)
                {
                    guidedBroodWorkerHandoffCollectedResource = Mathf.Min(collected, guidedBroodWorkerHandoffPendingResource);
                    guidedBroodWorkerHandoffPendingResource = 0f;
                    SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.BroodWorkerHandoffCheck);
                    localPreviewSessionPrompt = "Cire récupérée: contrôle l'opercule";
                }

                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningHygienePurgeCollect)
                {
                    guidedOpeningHygienePurgeCollectedWax = Mathf.Min(collected, guidedOpeningHygienePurgePendingWax);
                    guidedOpeningHygienePurgePendingWax = 0f;
                    SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.OpeningHygienePurgeCheck);
                    localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_01.hygiene_purge.check.title", "Contrôle de propreté");
                }

                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeStockCheckCollect)
                {
                    guidedUpgradeStockCheckCollectedWax = Mathf.Min(collected, guidedUpgradeStockCheckPendingWax);
                    guidedUpgradeStockCheckPendingWax = 0f;
                    SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.UpgradeStockCheckVerify);
                    localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_04.stock_check.check.title", "Contrôle d'étanchéité");
                }

                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodWaxConsolidationCollect)
                {
                    guidedBroodWaxConsolidationCollectedWax = Mathf.Min(collected, guidedBroodWaxConsolidationPendingWax);
                    guidedBroodWaxConsolidationPendingWax = 0f;
                    SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.BroodWaxConsolidationCheck);
                    localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_02.wax_consolidation.check.title", "Contrôle de tenue des cellules");
                }

                return;
            }

            if (string.Equals(hotspotId, "warehouse_cells", StringComparison.Ordinal))
            {
                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningBroodSupplyCollect)
                {
                    guidedOpeningBroodSupplyCollectedResource = Mathf.Min(collected, guidedOpeningBroodSupplyPendingResource);
                    guidedOpeningBroodSupplyPendingResource = 0f;
                    SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.OpeningBroodSupplyCheck);
                    localPreviewSessionPrompt = "Pollen récupéré: contrôle le ravitaillement";
                    return;
                }
                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitCollectPollen)
                {
                    guidedBroodCircuitCollectedPollen += Mathf.Min(collected, guidedBroodCircuitPendingPollen);
                    guidedBroodCircuitPendingPollen = 0f;
                    SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.BroodCircuitTreatmentChoice);
                    localPreviewSessionPrompt = "Ration recoltee: choisis le soin du couvain";
                    return;
                }

                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessCollectPollen)
                {
                    guidedReadinessCollectedPollen += Mathf.Min(collected, guidedReadinessPendingPollen);
                    guidedReadinessPendingPollen = 0f;
                    SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.ReadinessPopulationChoice);
                    localPreviewSessionPrompt = "Renouvelle une equipe pour poursuivre le circuit";
                }

                return;
            }

            if (!string.Equals(hotspotId, "honey_storage", StringComparison.Ordinal)) return;

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningBroodSupplyCollect)
            {
                guidedOpeningBroodSupplyCollectedResource = Mathf.Min(collected, guidedOpeningBroodSupplyPendingResource);
                guidedOpeningBroodSupplyPendingResource = 0f;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.OpeningBroodSupplyCheck);
                localPreviewSessionPrompt = "Miel récupéré: contrôle le ravitaillement";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodWorkerHandoffCollect)
            {
                guidedBroodWorkerHandoffCollectedResource = Mathf.Min(collected, guidedBroodWorkerHandoffPendingResource);
                guidedBroodWorkerHandoffPendingResource = 0f;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.BroodWorkerHandoffCheck);
                localPreviewSessionPrompt = "Miel récupéré: contrôle la ration d'émergence";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.CollectHoney)
            {
                guidedOpeningFirstCollectionAmount = collected;
                guidedCollectionTutorialCollectedAmount = collected;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.Collected);
                localPreviewSessionPrompt = "Premiere recolte: organiser la production";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.HoneySecondCollect)
            {
                guidedOpeningSecondCollectionAmount = collected;
                guidedCollectionTutorialCollectedAmount += collected;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.HoneySecondCollected);
                localPreviewSessionPrompt = "Cycle de miel accompli";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCircuitCollect)
            {
                float circuitCollection = Mathf.Min(collected, guidedOpeningCircuitPendingHoney);
                guidedOpeningCircuitCollectedHoney += circuitCollection;
                guidedOpeningCircuitPendingHoney = 0f;
                guidedCollectionTutorialCollectedAmount += circuitCollection;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.OpeningCircuitMaintenanceChoice);
                localPreviewSessionPrompt = "Lot range: choisis l'entretien du circuit";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCommissioningCollect)
            {
                float commissioningCollection = Mathf.Min(collected, guidedOpeningCommissioningPendingHoney);
                guidedOpeningCommissioningCollectedHoney += commissioningCollection;
                guidedOpeningCommissioningPendingHoney = 0f;
                guidedCollectionTutorialCollectedAmount += commissioningCollection;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.OpeningCommissioningValidation);
                localPreviewSessionPrompt = "Lot range: controle le circuit sous charge";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerTrialCollect)
            {
                guidedWorkerTrialCollectedHoney = Mathf.Min(collected, guidedWorkerTrialPendingHoney);
                guidedWorkerTrialPendingHoney = 0f;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerTrialResult);
                localPreviewSessionPrompt = "Essai reserve termine: choisis le poste permanent";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerFirstShiftCollect)
            {
                guidedWorkerFirstShiftCollectedHoney = Mathf.Min(collected, guidedWorkerFirstShiftPendingHoney);
                guidedWorkerFirstShiftPendingHoney = 0f;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerFirstShiftResult);
                localPreviewSessionPrompt = "Premier quart termine: valide l'integration";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCertificationCollect)
            {
                guidedWorkerCertificationCollectedHoney += Mathf.Min(collected, guidedWorkerCertificationPendingHoney);
                guidedWorkerCertificationPendingHoney = 0f;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerCertificationCheck);
                localPreviewSessionPrompt = "Lot recolte: verifie la qualite du travail";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerWorkshopHandoffCollect)
            {
                guidedWorkerWorkshopHandoffCollectedResource = Mathf.Min(collected, guidedWorkerWorkshopHandoffPendingResource);
                guidedWorkerWorkshopHandoffPendingResource = 0f;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerWorkshopHandoffCheck);
                localPreviewSessionPrompt = "Miel recolte: controle la liaison vers l'atelier";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitCollectHoney)
            {
                guidedBroodCircuitCollectedHoney += Mathf.Min(collected, guidedBroodCircuitPendingHoney);
                guidedBroodCircuitPendingHoney = 0f;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.BroodCircuitTreatmentChoice);
                localPreviewSessionPrompt = "Ration recoltee: choisis le soin du couvain";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessCollectHoney)
            {
                guidedReadinessCollectedHoney += Mathf.Min(collected, guidedReadinessPendingHoney);
                guidedReadinessPendingHoney = 0f;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.ReadinessCollectPollen);
                localPreviewSessionPrompt = "Le pollen du circuit attend dans l'entrepot";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseVigilanceCollect)
            {
                guidedDefenseVigilanceCollectedHoney = Mathf.Min(collected, guidedDefenseVigilancePendingHoney);
                guidedDefenseVigilancePendingHoney = 0f;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.DefenseVigilanceCheck);
                localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_05.vigilance.check.title", "Contrôle du périmètre");
            }

        }

        private static void HandleGuidedCollectionTutorialPrimaryAction()
        {
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.Welcome)
            {
                ClearReferenceDetailPanelSelection();
                referenceMobilePan = Vector2.zero;
                referenceHiveTargetZoom = IsPortraitLayout() ? 1.18f : 1.10f;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.CollectHoney);
                localPreviewSessionPrompt = "Objectif: securiser le miel";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.Collected)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.HoneyWorkersReady);
                localPreviewSessionPrompt = "Objectif: affecter une equipe a la reserve";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.HoneyWorkersReady)
            {
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.HoneySecondCollected)
            {
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.HoneyAllocationApplied)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.OpeningInstallationWelcome);
                localPreviewSessionPrompt = "Installer le premier circuit de la colonie";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningInstallationWelcome)
            {
                PrepareGuidedOpeningCircuitRound(1);
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCircuitRoundResult)
            {
                if (guidedOpeningCircuitCompletedRounds < GuidedOpeningCircuitRoundTarget)
                {
                    PrepareGuidedOpeningCircuitRound(guidedOpeningCircuitCompletedRounds + 1);
                }
                else
                {
                    SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.OpeningCommissioningCheck);
                    localPreviewSessionPrompt = "Deux tournees terminees: controle le circuit";
                }
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningBroodSupplyResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.OpeningHygienePurgeChoice);
                localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_01.hygiene_purge.choice.title", "Purge des alvéoles");
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningHygienePurgeResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.OpeningRewardChoice);
                localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_01.reward.choice.title", "Dotation fondatrice");
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningInstallationCompleted)
            {
                float honeyReward = guidedOpeningRewardPlan == "mixed_foundation" ? GuidedChapterOneMixedRewardHoney : GuidedChapterOneRewardHoney;
                float pollenReward = guidedOpeningRewardPlan == "mixed_foundation" ? GuidedChapterOneMixedRewardPollen : 0f;
                guidedCollectionTutorialRewardClaimed = ClaimGuidedChapterReward(1, honeyReward, 0f, pollenReward);
                guidedCollectionTutorialRewardAmount = guidedLastChapterRewardHoney;
                localPreviewSessionPrompt = "Chapitre 1 termine";
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.Completed);
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.Completed)
            {
                ClearReferenceDetailPanelSelection();
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.BroodWelcome);
                localPreviewSessionPrompt = "Chapitre 2: le couvain a faim";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodWelcome)
            {
                ClearReferenceDetailPanelSelection();
                referenceMobilePan = Vector2.zero;
                referenceHiveTargetZoom = IsPortraitLayout() ? 1.18f : 1.10f;
                CaptureGuidedBroodHandoff();
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.BroodHandoffReview);
                localPreviewSessionPrompt = "Heritage du chapitre 1: engager le circuit certifie";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodHandoffReview)
            {
                guidedBroodHandoffAcknowledged = true;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.InspectNursery);
                localPreviewSessionPrompt = "Objectif: trouver la nurserie";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodDiagnosisReady)
            {
                StartGuidedBroodDiagnosis();
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodPreparationResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.BroodReady);
                localPreviewSessionPrompt = "Objectif: choisir le soin du couvain";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodReady)
            {
                StartGuidedBroodCare(false);
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodFed)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.BroodVitalCheck);
                localPreviewSessionPrompt = "Objectif: verifier la reaction du couvain";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodDevelopmentApplied)
            {
                BeginGuidedBroodCircuit();
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitWelcome)
            {
                StartNextGuidedBroodCircuitRound();
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitRoundResult)
            {
                guidedBroodCircuitCompletedRounds++;
                if (guidedBroodCircuitCompletedRounds < GuidedBroodCircuitRoundTarget)
                {
                    StartNextGuidedBroodCircuitRound();
                }
                else
                {
                    guidedBroodCircuitRound = GuidedBroodCircuitRoundTarget;
                    SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.BroodCircuitCompleted);
                    localPreviewSessionPrompt = "Deux tournees accomplies: valide le couvain";
                }
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitCompleted)
            {
                BeginGuidedBroodIncubation();
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationWelcome)
            {
                StartNextGuidedBroodIncubationRound();
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationRoundResult)
            {
                guidedBroodIncubationCompletedRounds++;
                if (guidedBroodIncubationCompletedRounds < GuidedBroodIncubationRoundTarget)
                {
                    StartNextGuidedBroodIncubationRound();
                }
                else
                {
                    guidedBroodIncubationRound = GuidedBroodIncubationRoundTarget;
                    SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.BroodIncubationDoctrineChoice);
                    localPreviewSessionPrompt = "Deux cohortes stables: choisis le protocole final";
                }
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationCompleted)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.BroodWorkerHandoffChoice);
                localPreviewSessionPrompt = "Prépare l'émergence de la première ouvrière";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodWorkerHandoffResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.BroodWaxConsolidationChoice);
                localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_02.wax_consolidation.choice.body", "Avant de refermer le chapitre, renforce les cellules de la nurserie : un lot dense stabilise la capacité de stockage, un lot souple améliore durablement la production.");
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodWaxConsolidationResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.BroodCompleted);
                localPreviewSessionPrompt = "Chapitre 2 terminé: cellules consolidées";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCompleted)
            {
                ClaimGuidedChapterReward(2, GuidedChapterTwoRewardHoney, GuidedChapterTwoRewardWax, 0f);
                ClearReferenceDetailPanelSelection();
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerWelcome);
                localPreviewSessionPrompt = "Chapitre 3: une nouvelle ouvriere";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerWelcome)
            {
                ClearReferenceDetailPanelSelection();
                referenceMobilePan = Vector2.zero;
                referenceHiveTargetZoom = IsPortraitLayout() ? 1.18f : 1.10f;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerInspectNursery);
                localPreviewSessionPrompt = "Objectif: preparer le couvain";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerFeedReady)
            {
                StartGuidedWorkerCare(false);
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerFeedProgress)
            {
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerEmergenceResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerReadyToForm);
                localPreviewSessionPrompt = "Objectif: lancer l'eclosion";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerReadyToForm)
            {
                StartPreviewWorkerTraining();
                if (!IsWorkerTrainingRunning()) return;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerTraining);
                localPreviewSessionPrompt = "Eclosion de la premiere ouvriere";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerArrived)
            {
                ResetGuidedWorkerOrientationProgress();
                guidedWorkerOrientationRecommendation = guidedWorkerEmergencePlan == "reinforced" ? "honey" : "nursery";
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerOrientationCheck);
                localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_03.orientation.check.title", "Orientation de l'ouvrière");
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerTrialResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerAssignmentReady);
                localPreviewSessionPrompt = "Choisir le premier poste permanent de l'ouvriere";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerAssignmentApplied)
            {
                StartGuidedWorkerFirstShift();
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerFirstShiftResult)
            {
                BeginGuidedWorkerCertification();
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerIntegrationWelcome)
            {
                StartNextGuidedWorkerCertificationRound();
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCertificationRoundResult)
            {
                if (guidedWorkerCertificationCompletedRounds < GuidedWorkerCertificationRoundTarget)
                {
                    StartNextGuidedWorkerCertificationRound();
                }
                else
                {
                    guidedWorkerCertificationRound = GuidedWorkerCertificationRoundTarget;
                    SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerCertificationCompleted);
                    localPreviewSessionPrompt = "Certification terminee: valide l'integration";
                }
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCertificationCompleted)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerWorkshopHandoffChoice);
                localPreviewSessionPrompt = "Preparer le passage de relais vers l'atelier";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerWorkshopHandoffResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerWorkshopCommissionChoice);
                localPreviewSessionPrompt = "Choisir la passation technique de l'atelier";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerWorkshopCommissionResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerCompleted);
                localPreviewSessionPrompt = "Chapitre 3 termine: passation atelier certifiee";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCompleted)
            {
                ClaimGuidedChapterReward(3, GuidedChapterThreeRewardHoney, 0f, GuidedChapterThreeRewardPollen);
                ClearReferenceDetailPanelSelection();
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.UpgradeWelcome);
                localPreviewSessionPrompt = "Chapitre 4: une chambre plus efficace";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeWelcome)
            {
                ClearReferenceDetailPanelSelection();
                referenceMobilePan = Vector2.zero;
                referenceHiveTargetZoom = IsPortraitLayout() ? 1.18f : 1.10f;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.UpgradeInspectWorkshop);
                localPreviewSessionPrompt = "Objectif: trouver l'atelier de cire";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeAuditReady)
            {
                StartGuidedUpgradeAudit();
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeAuditResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.UpgradeReady);
                localPreviewSessionPrompt = "Choisir la specialisation de l'atelier";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeReady)
            {
                StartGuidedUpgradePlan(true);
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeResult)
            {
                StartGuidedUpgradeCalibration();
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeApplicationResult)
            {
                BeginGuidedUpgradeOperations();
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsWelcome)
            {
                StartNextGuidedUpgradeOperationsRound();
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsRoundResult)
            {
                if (guidedUpgradeOperationsCompletedRounds < GuidedUpgradeOperationsRoundTarget)
                {
                    StartNextGuidedUpgradeOperationsRound();
                }
                else
                {
                    SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.UpgradeCertificationChoice);
                    localPreviewSessionPrompt = "Deux commandes livrees: certifie l'atelier sous contrainte";
                }
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeCertificationResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.UpgradeOperationsDoctrineChoice);
                localPreviewSessionPrompt = "Certification reussie: choisis la doctrine d'atelier";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsCompleted)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkshopDefenseHandoffChoice);
                localPreviewSessionPrompt = "Prépare la défense avec l'atelier";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkshopDefenseHandoffResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.UpgradeStockCheckChoice);
                localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_04.stock_check.choice.body", "Avant de clore le chantier, vérifie l'étanchéité des réserves de cire restantes à l'atelier.");
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeStockCheckResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.UpgradeCompleted);
                localPreviewSessionPrompt = "Chapitre 4 terminé: matériel défensif prêt";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeCompleted)
            {
                ClaimGuidedChapterReward(4, GuidedChapterFourRewardHoney, GuidedChapterFourRewardWax, 0f);
                ClearReferenceDetailPanelSelection();
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.DefenseWelcome);
                localPreviewSessionPrompt = "Chapitre 5: une intruse dans la ruche";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseWelcome)
            {
                ClearReferenceDetailPanelSelection();
                referenceMobilePan = Vector2.zero;
                referenceHiveTargetZoom = IsPortraitLayout() ? 1.18f : 1.10f;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.DefenseInspectGuardPost);
                localPreviewSessionPrompt = "Objectif: mobiliser la caserne";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseReady)
            {
                StartGuidedDefenseScouting();
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseResolved)
            {
                ResetGuidedDefenseDebriefProgress();
                guidedDefenseDebriefRecommendation = guidedDefensePlan == "barrier" ? "cleanup" : "watch";
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.DefenseDebriefCheck);
                localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_05.debrief.check.title", "Débrief tactique");
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseRecoveryResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.DefenseDoctrineReady);
                localPreviewSessionPrompt = "Choisir une protection durable";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseDoctrineResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.ReadinessWelcome);
                localPreviewSessionPrompt = "Boucle de commandement: stabiliser la ruche";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessWelcome)
            {
                PrepareGuidedReadinessRound(1);
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessRoundResult)
            {
                if (guidedReadinessCompletedRounds < GuidedReadinessRoundTarget)
                {
                    PrepareGuidedReadinessRound(guidedReadinessCompletedRounds + 1);
                }
                else
                {
                    SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.ReadinessCompleted);
                    localPreviewSessionPrompt = "Deux circuits accomplis: la ruche est prete";
                }
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessCompleted)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.DefenseExpeditionMandateChoice);
                localPreviewSessionPrompt = "Choisir le mandat de la premiere expedition";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseExpeditionMandateResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.DefenseWorldBriefingChoice);
                localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_05.world_briefing.choice.title", "Briefing de sortie");
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseWorldBriefingResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.DefenseVigilanceChoice);
                localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_05.vigilance.choice.body", "Avant de clore l'Acte I, une dernière ronde vérifie le périmètre et ramène une réserve de miel pour la garnison.");
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseVigilanceResult)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.DefenseCompleted);
                localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_05.world_briefing.confirm", "Clore l'Acte I");
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseCompleted)
            {
                ClaimGuidedChapterReward(5, GuidedChapterFiveRewardHoney, GuidedChapterFiveRewardWax, 0f);
                ClearReferenceDetailPanelSelection();
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorldWelcome);
                localPreviewSessionPrompt = "Chapitre 6: au-dela de la ruche";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorldWelcome)
            {
                ClearReferenceDetailPanelSelection();
                referenceMobilePan = Vector2.zero;
                referenceHiveTargetZoom = IsPortraitLayout() ? 1.10f : 1.04f;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorldOpenMap);
                localPreviewSessionPrompt = "Objectif: ouvrir la carte mondiale";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorldMapArrival)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorldLocateHive);
                localPreviewSessionPrompt = "Objectif: reperer la ruche du joueur";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorldHiveLocated)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorldReturnHive);
                localPreviewSessionPrompt = "Objectif: retourner dans la ruche";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorldReturned)
            {
                ClearReferenceDetailPanelSelection();
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.ForageWelcome);
                localPreviewSessionPrompt = "Chapitre 7: le premier butinage";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageWelcome)
            {
                ClearReferenceDetailPanelSelection();
                referenceMobilePan = Vector2.zero;
                referenceHiveTargetZoom = IsPortraitLayout() ? 1.10f : 1.04f;
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.ForageOpenMap);
                localPreviewSessionPrompt = "Objectif: ouvrir la carte pour butiner";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageMapArrival)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.ForageSelectResource);
                localPreviewSessionPrompt = "Objectif: trouver le pollen exterieur";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageFlightComplete)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.ForageReturnHive);
                localPreviewSessionPrompt = "Objectif: rapporter le pollen a la ruche";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageClaim)
            {
                float availableCapacity = Mathf.Max(0f, localPreviewCapacityMax - localPreviewCapacityUsed);
                guidedForagingClaimedPollen = Mathf.Min(guidedForagingPendingPollen, availableCapacity);
                if (guidedForagingClaimedPollen <= 0f)
                {
                    localPreviewSessionPrompt = "Stockage plein: libere de la capacite";
                    return;
                }

                localPreviewPollen += guidedForagingClaimedPollen;
                localPreviewCapacityUsed = Mathf.Min(localPreviewCapacityMax, localPreviewCapacityUsed + guidedForagingClaimedPollen);
                guidedForagingPendingPollen -= guidedForagingClaimedPollen;
                guidedForagingRewardClaimed = true;
                localPreviewResourceFeedbackIndex = 2;
                localPreviewResourceFeedbackText = "+" + Mathf.FloorToInt(guidedForagingClaimedPollen).ToString(CultureInfo.InvariantCulture) + " pollen";
                localPreviewResourceFeedbackStartedAt = NowForUi();
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.ForageCompleted);
                localPreviewSessionPrompt = "Chapitre 7 termine";
                return;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageCompleted)
            {
                ClearReferenceDetailPanelSelection();
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.Inactive);
                localPreviewSessionPrompt = PendingProductionSummary();
            }
        }

