        private static string GuidedCollectionTutorialTargetHotspot()
        {
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.CollectHoney
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.HoneySecondCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCircuitCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerTrialCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerFirstShiftCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCertificationCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitCollectHoney
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessCollectHoney
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseVigilanceCollect) return "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningBroodSupplyCollect)
                return guidedOpeningBroodSupplyPlan == "royal_jelly_cache" ? "warehouse_cells" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningHygienePurgeCollect) return "wax_workshop";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerWorkshopHandoffCollect)
                return guidedWorkerWorkshopHandoffPlan == "wax_convoy" ? "wax_workshop" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodWorkerHandoffCollect)
                return guidedBroodWorkerHandoffPlan == "reinforced_operculum" ? "wax_workshop" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodWaxConsolidationCollect) return "wax_workshop";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitCollectPollen
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessCollectPollen) return "warehouse_cells";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeCalibrationCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkshopDefenseHandoffCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeStockCheckCollect) return "wax_workshop";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.InspectNursery) return "nursery_cluster";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerInspectNursery) return "nursery_cluster";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeInspectWorkshop) return "wax_workshop";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseInspectGuardPost) return "guard_post";
            return string.Empty;
        }

        private static string GuidedCollectionTutorialVisualHotspot()
        {
            string target = GuidedCollectionTutorialTargetHotspot();
            if (!string.IsNullOrWhiteSpace(target)) return target;
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.HoneyProduction) return "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCircuitRouteRunning)
                return guidedOpeningCircuitRoutePlan == "nursery_relay" ? "nursery_cluster" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCircuitMaintenanceRunning)
                return guidedOpeningCircuitMaintenancePlan == "ventilation_watch" ? "nursery_cluster" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCommissioningCheck) return "nursery_cluster";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCharterRunning)
                return guidedOpeningCharterPlan == "brood_bridge" ? "nursery_cluster" : "honey_storage";
