            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsDeploymentRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsCheck)
                return guidedUpgradeOperationsDeploymentPlan == "nursery" ? "nursery_cluster" : "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsDoctrineRunning
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeCertificationRunning) return "wax_workshop";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseScouting) return "guard_post";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseMobilizing) return "guard_post";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseRecoveryRunning) return "guard_post";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseDoctrineRunning) return "guard_post";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessProductionRunning) return "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessPopulationRunning)
                return guidedReadinessPopulationPlan == "nurses" ? "nursery_cluster" : "guard_post";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessDefenseRunning) return "guard_post";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseVigilanceRunning) return "honey_storage";
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseVigilanceCheck) return "honey_storage";
            return string.Empty;
        }

        private static bool GuidedCollectionTutorialTargetsSurfaceSwitch()
        {
            return guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorldOpenMap
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageOpenMap;
        }

        // M043T-CL STANDING CONVENTION - real production bug, not theoretical: when a screen draws
        // its OWN sub-overlay/modal/profile popup on top of its OWN other content, later in the SAME
        // draw function (e.g. Alliance Center's "Inviter un joueur" action panel drawn after its own
        // tab content), the underlying content must be wrapped in this helper. Without it, that
        // content stays fully interactive and visually opaque-less underneath the overlay - IMGUI
        // resolves an overlapping click to whichever control matches it FIRST in draw order, so a
        // click meant for the overlay can land on a hidden control behind it instead, and the CEO
        // saw this live as "my click passes through, I see icons/bees through the window."
        // ShouldBlockUnderlyingHiveChromeInput()/PremiumUiBlocksWorldInput() below already solve the
        // OUTER problem (disabling the hive chrome/3D world while ANY screen is open) - this solves
        // the INNER one (a screen's own content vs its own overlay). Any new screen with an internal
        // sub-overlay MUST wrap its main-content draw calls in this, passing whatever bool(s)
        // indicate that screen's own overlay/profile/popup is currently open.
        private static void DrawUnderOwnOverlayGate(bool ownOverlayOpen, Action drawUnderlyingContent)
        {
            bool previous = GUI.enabled;
            GUI.enabled = previous && !ownOverlayOpen;
            try { drawUnderlyingContent(); }
            finally { GUI.enabled = previous; }
        }

		private static bool ShouldBlockUnderlyingHiveChromeInput()
		{
			return resourceInventoryOpen
				|| colonyOverviewOpen
				|| championBeesPanelOpen
				|| missionsCenterOpen
				|| courierScreenOpen
				|| friendsScreenOpen
				|| chatScreenOpen
				|| activeHiveMenu == HiveMenuMode.Research
				|| activeHiveMenu == HiveMenuMode.Alliance
				|| strategicPathPanelOpen
				|| allianceMemberProfileOpen
				|| !string.IsNullOrEmpty(allianceActionPanelOpen)
				|| allianceChatDrawerOpen
				|| speedUpWindowOpen
				|| bestiaryCodexOverlayOpen
				|| milestoneEventOverlayOpen
				|| communicationPanelOpen
				|| !string.IsNullOrEmpty(activeMainMenuId)
				// M043T-CL: gap found during the click-through audit - the reference detail info
				// popup (over DrawDetailPanel) was missing from this outer gate too.
				|| referenceDetailInfoPopupOpen
				|| (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.Inactive
					&& !GuidedCollectionTutorialTargetsSurfaceSwitch());
        }

