        // Stabilisation UI/UX : fond assombri + blocage total des clics pour les modaux Premium
		// (Bestiaire, Defi/Milestone) afin qu'aucun clic ne traverse vers le monde. Les controles
		// de la ruche sont desactives avant le rendu des overlays pour conserver les boutons du modal.
		private static void DrawPremiumModalBackdrop()
		{
			Rect full = new Rect(0f, 0f, Screen.width, Screen.height);
			GUI.DrawTexture(full, Texture2D.blackTexture, ScaleMode.StretchToFill, true, 0f, new Color(0f, 0f, 0f, 0.55f), 0f, 0f);
		}

        // Stabilisation UI/UX : la touche Echap (et le bouton retour Android) doit fermer n'importe
        // quel ecran plein ecran Premium, quel qu'il soit, comme sur les ecrans Chat/Courrier/
        // Recherche qui le gerent deja dans leur propre rendu. Appelee au debut de Draw().
        private static void HandlePremiumScreensEscape()
        {
            if (Event.current == null || Event.current.type != EventType.KeyDown) return;
            if (Event.current.keyCode != KeyCode.Escape && Event.current.keyCode != KeyCode.Backspace) return;
            if (ClosePremiumScreensInPriorityOrderCore()) Event.current.Use();
        }

        private static bool ClosePremiumScreensInPriorityOrderCore()
        {
            if (allianceMemberProfileOpen) { CloseAllianceMemberProfile(); return true; }
            if (!string.IsNullOrEmpty(allianceActionPanelOpen)) { allianceActionPanelOpen = string.Empty; return true; }
            if (allianceChatDrawerOpen) { allianceChatDrawerOpen = false; return true; }
            if (missionsCenterOpen) { CloseMissionsCenter(); return true; }
            if (colonyOverviewOpen) { colonyOverviewOpen = false; return true; }
            if (championBeesPanelOpen) { championBeesPanelOpen = false; return true; }
            if (speedUpWindowOpen) { speedUpWindowOpen = false; SpeedUpDialog.Close(); return true; }
            if (friendsScreenOpen) { friendsScreenOpen = false; return true; }
            if (activeHiveMenu == HiveMenuMode.Alliance)
            {
                activeMainMenuId = string.Empty;
                activeHiveMenu = HiveMenuMode.Hive;
                allianceActionPanelOpen = string.Empty;
                return true;
            }
            if (activeHiveMenu == HiveMenuMode.Army)
            {
                CloseActiveMainMenuPanel();
                activeHiveMenu = HiveMenuMode.Hive;
                detailPanelClosed = true;
                return true;
            }
            if (milestoneEventOverlayOpen) { milestoneEventOverlayOpen = false; return true; }
            if (bestiaryCodexOverlayOpen) { bestiaryCodexOverlayOpen = false; return true; }
            if (!string.IsNullOrEmpty(activeMainMenuId))
            {
                CloseActiveMainMenuPanel();
                return true;
            }
            return false;
        }

