        private static bool TryAdvanceGuidedCollectionTutorialTarget(string hotspotId)
        {
            bool broodTarget = guidedCollectionTutorialStep == GuidedCollectionTutorialStep.InspectNursery;
            bool workerTarget = guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerInspectNursery;
            bool upgradeTarget = guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeInspectWorkshop;
            bool defenseTarget = guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseInspectGuardPost;
            if (!broodTarget && !workerTarget && !upgradeTarget && !defenseTarget) return false;
            string expectedHotspot = defenseTarget ? "guard_post" : upgradeTarget ? "wax_workshop" : "nursery_cluster";
            if (!string.Equals(hotspotId, expectedHotspot, StringComparison.Ordinal))
            {
                guidedCollectionTutorialBlockedClicks++;
                return false;
            }

            ClearReferenceDetailPanelSelection();
            SetGuidedCollectionTutorialStep(
                broodTarget
                    ? GuidedCollectionTutorialStep.BroodDiagnosisReady
                    : workerTarget
                        ? GuidedCollectionTutorialStep.WorkerFeedReady
                        : upgradeTarget
                            ? GuidedCollectionTutorialStep.UpgradeAuditReady
                            : GuidedCollectionTutorialStep.DefenseReady);
            localPreviewSessionPrompt = broodTarget
                ? "Nurserie trouvee: diagnostique le couvain"
                : workerTarget
                    ? "Nurserie trouvee: complete la nutrition"
                    : upgradeTarget
                        ? "Atelier trouve: lance l'audit de production"
                        : "Caserne trouvee: mobilise les gardiennes";
            return true;
        }

        private static void UpdateGuidedCollectionTutorialCamera(Rect artRect, bool portrait)
        {
            string targetHotspotId = GuidedCollectionTutorialVisualHotspot();
            if (string.IsNullOrWhiteSpace(targetHotspotId)) return;

            referenceHiveTargetZoom = portrait ? 1.18f : 1.10f;
            ReferenceHiveHotspot hotspot = FindReferenceHotspot(targetHotspotId);
            Vector2 anchor = GetReferenceVisualAnchor(hotspot) + ManualCollectionMarkerOffset(targetHotspotId);
            Vector2 current = ReferencePoint(artRect, anchor.x, anchor.y);
            Vector2 desired = new Vector2(Screen.width * 0.50f, Screen.height * (portrait ? 0.34f : 0.31f));
            float step = productionReducedMotionForProof ? 1f : Mathf.Clamp01(Mathf.Max(0.01f, Time.unscaledDeltaTime) * 4.8f);
            referenceMobilePan += (desired - current) * step;
        }

        private static bool ConsumeGuidedCollectionTutorialBlockedInput(Event current, Rect artRect, bool portrait)
        {
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.Inactive) return false;
            if (IsGuidedCollectionTutorialUiPoint(current.mousePosition, portrait)) return false;

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.CollectHoney
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.HoneySecondCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCircuitCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCommissioningCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerTrialCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerFirstShiftCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCertificationCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitCollectHoney
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessCollectHoney
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseVigilanceCollect)
            {
                ReferenceHiveHotspot hotspot = HitReferenceHotspot(ScreenToReferenceArtPoint(artRect, current.mousePosition));
                if (string.Equals(hotspot.HotspotId, "honey_storage", StringComparison.Ordinal)) return false;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitCollectPollen
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessCollectPollen)
            {
                ReferenceHiveHotspot hotspot = HitReferenceHotspot(ScreenToReferenceArtPoint(artRect, current.mousePosition));
                if (string.Equals(hotspot.HotspotId, "warehouse_cells", StringComparison.Ordinal)) return false;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.InspectNursery
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerInspectNursery)
            {
                ReferenceHiveHotspot hotspot = HitReferenceHotspot(ScreenToReferenceArtPoint(artRect, current.mousePosition));
                if (string.Equals(hotspot.HotspotId, "nursery_cluster", StringComparison.Ordinal)) return false;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeInspectWorkshop)
            {
                ReferenceHiveHotspot hotspot = HitReferenceHotspot(ScreenToReferenceArtPoint(artRect, current.mousePosition));
                if (string.Equals(hotspot.HotspotId, "wax_workshop", StringComparison.Ordinal)) return false;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeCalibrationCollect
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeOperationsCollect)
            {
                ReferenceHiveHotspot hotspot = HitReferenceHotspot(ScreenToReferenceArtPoint(artRect, current.mousePosition));
                if (string.Equals(hotspot.HotspotId, "wax_workshop", StringComparison.Ordinal)) return false;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseInspectGuardPost)
            {
                ReferenceHiveHotspot hotspot = HitReferenceHotspot(ScreenToReferenceArtPoint(artRect, current.mousePosition));
                if (string.Equals(hotspot.HotspotId, "guard_post", StringComparison.Ordinal)) return false;
            }

            if (current.type != EventType.MouseDown && current.type != EventType.MouseUp && current.type != EventType.MouseDrag && current.type != EventType.ScrollWheel) return false;
            if (current.type == EventType.MouseUp) guidedCollectionTutorialBlockedClicks++;
            referenceInputStartedInHive = false;
            referenceInputDragging = false;
            referenceSelectionSuppressed = false;
            current.Use();
            return true;
        }

