        private static Rect TutorialPanelRect(bool portrait)
        {
            float width = portrait ? Mathf.Min(Screen.width - 24f, 430f) : Mathf.Min(Screen.width - 48f, 520f);
            bool handoff = guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodHandoffReview;
            bool tallMobileChoice = guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningRewardChoice;
            float height = portrait ? (handoff ? 224f : tallMobileChoice ? 216f : 196f) : (handoff ? 198f : 174f);
            float y = portrait
                ? Mathf.Max(120f, Screen.height - 372f)
                : Mathf.Max(LandscapeTopHudHeight() + 18f, Screen.height - LandscapeBottomRailHeight() - height - 18f);
            return new Rect((Screen.width - width) * 0.5f, y, width, height);
        }

