        private static int GuidedChapterNumberForWelcomeStep(GuidedCollectionTutorialStep step)
        {
            switch (step)
            {
                case GuidedCollectionTutorialStep.Welcome: return 1;
                case GuidedCollectionTutorialStep.BroodWelcome: return 2;
                case GuidedCollectionTutorialStep.WorkerWelcome: return 3;
                case GuidedCollectionTutorialStep.UpgradeWelcome: return 4;
                case GuidedCollectionTutorialStep.DefenseWelcome: return 5;
                case GuidedCollectionTutorialStep.WorldWelcome: return 6;
                case GuidedCollectionTutorialStep.ForageWelcome: return 7;
                default: return 0;
            }
        }

