                    return CreateGuidedChapterIntroDefinition(2, "chapter_2_brood_care", "PremiumBeeReference/tutorial-chapter-2-brood-care-v1",
                        "pollen", new Color(0.68f, 0.82f, 0.32f, 1f), "nursery", new Color(0.44f, 0.82f, 0.86f, 1f), "wax", new Color(0.96f, 0.78f, 0.30f, 1f));
                case 3:
                    return CreateGuidedChapterIntroDefinition(3, "chapter_3_first_worker", "PremiumBeeReference/tutorial-chapter-3-first-worker-v1",
                        "nursery", new Color(0.90f, 0.72f, 0.30f, 1f), "worker", new Color(0.42f, 0.82f, 0.86f, 1f), "book", new Color(0.64f, 0.78f, 0.36f, 1f));
                case 4:
                    return CreateGuidedChapterIntroDefinition(4, "chapter_4_first_upgrade", "PremiumBeeReference/tutorial-chapter-4-wax-workshop-v1",
                        "honey", new Color(1f, 0.66f, 0.12f, 1f), "wax", new Color(0.96f, 0.86f, 0.54f, 1f), "pollen", new Color(0.68f, 0.82f, 0.32f, 1f));
                case 5:
                    return CreateGuidedChapterIntroDefinition(5, "chapter_5_first_defense", "PremiumBeeReference/tutorial-chapter-5-first-defense-v1",
                        "search", new Color(0.44f, 0.80f, 0.86f, 1f), "guard", new Color(0.96f, 0.56f, 0.18f, 1f), "defense", new Color(0.82f, 0.28f, 0.20f, 1f));
                case 6:
                    return CreateGuidedChapterIntroDefinition(6, "chapter_6_first_world_transition", "PremiumBeeReference/tutorial-chapter-6-world-v1",
                        "queen-core", new Color(0.96f, 0.70f, 0.18f, 1f), "map", new Color(0.38f, 0.78f, 0.84f, 1f), "home", new Color(0.64f, 0.80f, 0.34f, 1f));
                case 7:
                    return CreateGuidedChapterIntroDefinition(7, "chapter_7_first_foraging_flight", "PremiumBeeReference/tutorial-chapter-7-foraging-v1",
