        private static GuidedChapterIntroDefinition CreateGuidedChapterIntroDefinition(
            int chapterNumber,
            string introId,
            string bannerResourcePath,
            string firstIcon,
            Color firstAccent,
            string secondIcon,
            Color secondAccent,
            string thirdIcon,
            Color thirdAccent)
        {
            string prefix = "tutorial.chapter_" + chapterNumber.ToString("00", CultureInfo.InvariantCulture) + ".intro";
            return new GuidedChapterIntroDefinition(
                chapterNumber,
                introId,
                prefix,
                bannerResourcePath,
                BeeLocalization.Text(prefix + ".eyebrow"),
                BeeLocalization.Text(prefix + ".title"),
                BeeLocalization.Text(prefix + ".narration"),
                BeeLocalization.Text(prefix + ".continue"),
                LocalizedGuidedChapterIntroCard(firstIcon, prefix + ".card_1", firstAccent),
                LocalizedGuidedChapterIntroCard(secondIcon, prefix + ".card_2", secondAccent),
                LocalizedGuidedChapterIntroCard(thirdIcon, prefix + ".card_3", thirdAccent));
        }

        private static GuidedChapterIntroCard LocalizedGuidedChapterIntroCard(string iconId, string keyPrefix, Color accent)
        {
            return new GuidedChapterIntroCard(
                iconId,
                BeeLocalization.Text(keyPrefix + ".label"),
                BeeLocalization.Text(keyPrefix + ".title"),
                BeeLocalization.Text(keyPrefix + ".description"),
                accent);
        }

        private static void PrepareGuidedChapterIntro(int chapterNumber)
        {
            GuidedChapterIntroDefinition definition = GuidedChapterIntroDefinitionForNumber(chapterNumber);
            guidedChapterIntroActiveId = definition.IntroId;
            guidedChapterNarrationCueAnnounced = BeeLocalization.LocalizedAudioCue(definition.AudioCueId);
            guidedChapterIntroStartedAt = NowForUi();
            guidedChapterIntroClosingStartedAt = -10f;
            guidedChapterIntroRevealImmediately = productionReducedMotionForProof;
            guidedChapterIntroClosing = false;
        }

        private static bool GuidedChapterIntroDismissed(int chapterNumber)
        {
            int bit = 1 << Mathf.Clamp(chapterNumber - 1, 0, 30);
            return (guidedChapterIntroDismissedMask & bit) != 0;
        }

        private static void DismissGuidedChapterIntroImmediately(int chapterNumber)
        {
            int bit = 1 << Mathf.Clamp(chapterNumber - 1, 0, 30);
            guidedChapterIntroDismissedMask |= bit;
            guidedChapterIntroClosing = false;
            guidedChapterIntroClosingStartedAt = -10f;
        }

        private static bool ShouldShowGuidedChapterIntro()
        {
            int chapterNumber = GuidedChapterNumberForWelcomeStep(guidedCollectionTutorialStep);
            return chapterNumber > 0 && !GuidedChapterIntroDismissed(chapterNumber);
        }

        private static bool ShouldShowGuidedChapterFourResourcePrimer()
        {
            return GuidedChapterNumberForWelcomeStep(guidedCollectionTutorialStep) == 4
                && ShouldShowGuidedChapterIntro();
        }

        private static Rect TutorialResourcePrimerPanelRect(bool portrait)
        {
            float horizontalMargin = portrait ? 10f : Mathf.Max(28f, Screen.width * 0.065f);
            float verticalMargin = portrait ? 12f : 24f;
            return new Rect(
                horizontalMargin,
                verticalMargin,
                Screen.width - horizontalMargin * 2f,
                Screen.height - verticalMargin * 2f);
        }

        private static Rect TutorialResourcePrimerContinueButtonRect(bool portrait)
        {
            Rect panel = TutorialResourcePrimerPanelRect(portrait);
            float width = portrait ? panel.width - 28f : Mathf.Min(390f, panel.width * 0.42f);
            float height = portrait ? 48f : 46f;
            return new Rect(panel.center.x - width * 0.5f, panel.yMax - height - 16f, width, height);
        }

        private static int GuidedChapterIntroVisibleCharacterCount(GuidedChapterIntroDefinition definition)
        {
            if (guidedChapterIntroRevealImmediately || productionReducedMotionForProof) return definition.Narration.Length;
            float elapsed = Mathf.Max(0f, NowForUi() - guidedChapterIntroStartedAt - GuidedChapterIntroTypingDelaySeconds);
            return Mathf.Clamp(Mathf.FloorToInt(elapsed * GuidedChapterIntroCharactersPerSecond), 0, definition.Narration.Length);
        }

        private static float GuidedChapterIntroOpacity()
        {
            if (productionReducedMotionForProof) return guidedChapterIntroClosing ? 0f : 1f;
            if (guidedChapterIntroClosing)
            {
                float closeT = Mathf.Clamp01((NowForUi() - guidedChapterIntroClosingStartedAt) / GuidedChapterIntroFadeOutSeconds);
                return 1f - closeT * closeT * (3f - 2f * closeT);
            }

            float openT = Mathf.Clamp01((NowForUi() - guidedChapterIntroStartedAt) / GuidedChapterIntroFadeInSeconds);
            return openT * openT * (3f - 2f * openT);
        }

        private static void DrawGuidedChapterIntroPanel(Rect rect, Color fill, Color border, float opacity)
        {
            Color previous = GUI.color;
            GUI.color = new Color(1f, 1f, 1f, opacity * 0.44f);
            GUI.DrawTexture(new Rect(rect.x + 5f, rect.y + 8f, rect.width, rect.height), GetPremiumTexture("panel-shadow"), ScaleMode.StretchToFill, true);
            GUI.color = new Color(1f, 1f, 1f, opacity);
            GUI.DrawTexture(rect, GetPremiumTexture("panel-outer-grain"), ScaleMode.StretchToFill, true);
            Rect inner = new Rect(rect.x + 4f, rect.y + 4f, Mathf.Max(1f, rect.width - 8f), Mathf.Max(1f, rect.height - 8f));
            Color refinedFill = Color.Lerp(fill, new Color(0.014f, 0.012f, 0.009f, fill.a), 0.58f);
            GUI.color = new Color(refinedFill.r, refinedFill.g, refinedFill.b, refinedFill.a * opacity);
            GUI.DrawTexture(inner, GetPremiumTexture("panel-fill"), ScaleMode.StretchToFill, true);
            GUI.color = new Color(border.r, border.g, border.b, border.a * opacity * 0.46f);
            GUI.DrawTexture(new Rect(rect.x + 7f, rect.y + 1f, rect.width - 14f, 1f), GetPremiumTexture("etched-line"), ScaleMode.StretchToFill, true);
            GUI.DrawTexture(new Rect(rect.x + 7f, rect.yMax - 2f, rect.width - 14f, 1f), GetPremiumTexture("etched-line"), ScaleMode.StretchToFill, true);
            GUI.color = previous;
        }

        private static void DrawGuidedChapterIntroLabel(Rect rect, string text, GUIStyle style, float opacity)
        {
            Color previous = GUI.color;
            GUI.color = new Color(1f, 1f, 1f, opacity);
            GUI.Label(rect, text, style);
            GUI.color = previous;
        }

        private static void DrawGuidedChapterIntro(bool portrait)
        {
            int chapterNumber = GuidedChapterNumberForWelcomeStep(guidedCollectionTutorialStep);
            GuidedChapterIntroDefinition definition = GuidedChapterIntroDefinitionForNumber(chapterNumber);
            if (!string.Equals(guidedChapterIntroActiveId, definition.IntroId, StringComparison.Ordinal))
            {
                PrepareGuidedChapterIntro(chapterNumber);
            }

            if (guidedChapterIntroClosing && NowForUi() - guidedChapterIntroClosingStartedAt >= GuidedChapterIntroFadeOutSeconds)
            {
                DismissGuidedChapterIntroImmediately(chapterNumber);
                return;
            }

            float opacity = GuidedChapterIntroOpacity();
            Color previousColor = GUI.color;
            GUI.color = new Color(0.006f, 0.008f, 0.007f, 0.92f * opacity);
            GUI.DrawTexture(new Rect(0f, 0f, Screen.width, Screen.height), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            GUI.color = previousColor;

            Rect panel = TutorialResourcePrimerPanelRect(portrait);
            bool shortLandscape = !portrait && panel.height < 620f;
            DrawGuidedChapterIntroPanel(panel, new Color(0.025f, 0.030f, 0.024f, 0.995f), new Color(0.72f, 0.54f, 0.20f, 0.92f), opacity);
            GUI.color = new Color(1f, 1f, 1f, 0.28f * opacity);
            GUI.DrawTexture(new Rect(panel.x + 2f, panel.y + 2f, panel.width - 4f, panel.height - 4f), GetPremiumTexture("panel-grain"), ScaleMode.StretchToFill, true);
            GUI.color = previousColor;

            float bannerHeight = portrait
                ? Mathf.Clamp(panel.height * 0.27f, 170f, 280f)
                : shortLandscape
                    ? Mathf.Clamp(panel.height * 0.30f, 106f, 158f)
                    : Mathf.Clamp(panel.height * 0.34f, 178f, 320f);
            Rect banner = new Rect(panel.x + 2f, panel.y + 2f, panel.width - 4f, bannerHeight);
            if (guidedChapterIntroBannerArt == null || !string.Equals(guidedChapterIntroBannerPath, definition.BannerResourcePath, StringComparison.Ordinal))
            {
                guidedChapterIntroBannerPath = definition.BannerResourcePath;
                guidedChapterIntroBannerArt = Resources.Load<Texture2D>(definition.BannerResourcePath);
            }

            GUI.color = new Color(1f, 1f, 1f, opacity);
            if (guidedChapterIntroBannerArt != null)
            {
                GUI.DrawTexture(banner, guidedChapterIntroBannerArt, ScaleMode.ScaleAndCrop, true);
            }
            else
            {
                GUI.DrawTexture(banner, GetPremiumTexture("wax-field"), ScaleMode.StretchToFill, true);
            }
            GUI.color = previousColor;

            if (localPreviewTutorialResumeNoticeVisible)
            {
                Rect resume = new Rect(panel.x + 12f, panel.y + 12f, Mathf.Min(panel.width - 24f, portrait ? panel.width - 24f : 520f), portrait ? 50f : 44f);
                DrawGuidedChapterIntroPanel(resume, new Color(0.025f, 0.090f, 0.105f, 0.96f), new Color(0.42f, 0.86f, 1f, 0.96f), opacity);
                string resumeText = BeeLocalization.Text("tutorial.resume.safe", "REPRISE SÉCURISÉE") + " · " + BeeLocalization.Text("tutorial.resume.restart", "Chapitre repris depuis son début") + "\n" + BeeLocalization.Text("tutorial.resume.interrupted", "Objectif interrompu") + ": " + localPreviewTutorialInterruptedObjectiveLabel;
                DrawGuidedChapterIntroLabel(new Rect(resume.x + 10f, resume.y + 5f, resume.width - 20f, resume.height - 10f), resumeText, new GUIStyle(tinyLabelStyle) { fontSize = portrait ? 9 : 11, wordWrap = true }, opacity);
            }

            float eyebrowBandHeight = portrait ? 58f : shortLandscape ? 42f : 64f;
            GUI.color = new Color(0.01f, 0.012f, 0.010f, 0.70f * opacity);
            GUI.DrawTexture(new Rect(banner.x, banner.yMax - eyebrowBandHeight, banner.width, eyebrowBandHeight), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            GUI.color = previousColor;

            GUIStyle chapterStyle = new GUIStyle(tinyLabelStyle)
            {
                alignment = TextAnchor.MiddleLeft,
                fontSize = portrait ? 11 : shortLandscape ? 10 : 12,
                fontStyle = FontStyle.Bold
            };
            chapterStyle.normal.textColor = new Color(1f, 0.80f, 0.34f, 1f);
            DrawGuidedChapterIntroLabel(
                new Rect(banner.x + (portrait ? 16f : 24f), banner.yMax - (portrait ? 46f : shortLandscape ? 34f : 49f), banner.width - 40f, 24f),
                definition.Eyebrow,
                chapterStyle,
                opacity);

            float contentX = panel.x + (portrait ? 16f : 28f);
            float contentWidth = panel.width - (portrait ? 32f : 56f);
            float contentY = banner.yMax + (portrait ? 10f : shortLandscape ? 6f : 14f);
            float titleHeight = portrait ? 48f : shortLandscape ? 30f : 40f;
            DrawGuidedChapterIntroLabel(
                new Rect(contentX, contentY, contentWidth, titleHeight),
                definition.Title,
                new GUIStyle(titleStyle)
                {
                    fontSize = portrait ? 23 : shortLandscape ? 19 : 28,
                    alignment = TextAnchor.MiddleLeft,
                    wordWrap = true
                },
                opacity);

            float introY = contentY + titleHeight + (shortLandscape ? 0f : 2f);
            float introHeight = portrait ? 96f : shortLandscape ? 54f : 82f;
            int visibleCharacters = GuidedChapterIntroVisibleCharacterCount(definition);
            string visibleNarration = definition.Narration.Substring(0, visibleCharacters);
            if (visibleCharacters < definition.Narration.Length && visibleCharacters > 0 && ((int)(NowForUi() * 3f) & 1) == 0) visibleNarration += " |";
            DrawGuidedChapterIntroLabel(
                new Rect(contentX, introY, contentWidth, introHeight),
                visibleNarration,
                new GUIStyle(smallStyle)
                {
                    fontSize = portrait ? 14 : shortLandscape ? 12 : 15,
                    alignment = TextAnchor.UpperLeft,
                    wordWrap = true
                },
                opacity);

            Rect continueButton = TutorialResourcePrimerContinueButtonRect(portrait);
            float resourceY = introY + introHeight + (portrait ? 8f : shortLandscape ? 2f : 10f);
            float legendReserve = chapterNumber == 4 ? (portrait ? 34f : shortLandscape ? 20f : 26f) : 0f;
            float cardsBottom;
            if (portrait)
            {
                float gap = 7f;
                float available = Mathf.Max(174f, continueButton.y - resourceY - gap * 2f - 14f - legendReserve);
                float rowHeight = Mathf.Min(82f, available / 3f);
                DrawGuidedChapterIntroCard(new Rect(contentX, resourceY, contentWidth, rowHeight), definition.FirstCard, true, opacity);
                DrawGuidedChapterIntroCard(new Rect(contentX, resourceY + rowHeight + gap, contentWidth, rowHeight), definition.SecondCard, true, opacity);
                DrawGuidedChapterIntroCard(new Rect(contentX, resourceY + (rowHeight + gap) * 2f, contentWidth, rowHeight), definition.ThirdCard, true, opacity);
                cardsBottom = resourceY + rowHeight * 3f + gap * 2f;
            }
            else
            {
                float gap = shortLandscape ? 8f : 12f;
                float width = (contentWidth - gap * 2f) / 3f;
                float cardHeight = Mathf.Clamp(continueButton.y - resourceY - (shortLandscape ? 10f : 28f) - legendReserve, shortLandscape ? 72f : 90f, shortLandscape ? 86f : 132f);
                DrawGuidedChapterIntroCard(new Rect(contentX, resourceY, width, cardHeight), definition.FirstCard, shortLandscape, opacity);
                DrawGuidedChapterIntroCard(new Rect(contentX + width + gap, resourceY, width, cardHeight), definition.SecondCard, shortLandscape, opacity);
                DrawGuidedChapterIntroCard(new Rect(contentX + (width + gap) * 2f, resourceY, width, cardHeight), definition.ThirdCard, shortLandscape, opacity);
                cardsBottom = resourceY + cardHeight;
            }

            if (chapterNumber == 4)
            {
                float legendHeight = portrait ? 28f : shortLandscape ? 18f : 22f;
                float legendY = Mathf.Min(continueButton.y - legendHeight - 4f, cardsBottom + 3f);
                GUIStyle legendStyle = new GUIStyle(centeredTinyLabelStyle)
                {
                    fontSize = portrait ? 11 : shortLandscape ? 9 : 12,
                    fontStyle = FontStyle.Bold,
                    wordWrap = true
                };
                legendStyle.normal.textColor = new Color(0.92f, 0.90f, 0.78f, 1f);
                DrawGuidedChapterIntroLabel(new Rect(contentX, legendY, contentWidth, legendHeight), "- signifie DÉPENSÉ · + ou PRODUIT signifie REÇU", legendStyle, opacity);
            }

            DrawGuidedChapterIntroPanel(continueButton, new Color(0.46f, 0.27f, 0.055f, 0.99f), new Color(1f, 0.76f, 0.24f, 1f), opacity);
            string buttonLabel = visibleCharacters < definition.Narration.Length
                ? BeeLocalization.Text("common.reveal_story", "Révéler le récit")
                : definition.ContinueLabel;
            DrawGuidedChapterIntroLabel(continueButton, buttonLabel, new GUIStyle(centeredTinyLabelStyle) { fontSize = portrait ? 14 : shortLandscape ? 12 : 15, fontStyle = FontStyle.Bold }, opacity);
            if (!guidedChapterIntroClosing && GUI.Button(continueButton, string.Empty, GUIStyle.none))
            {
                if (visibleCharacters < definition.Narration.Length)
                {
                    guidedChapterIntroRevealImmediately = true;
                    localPreviewSessionPrompt = BeeLocalization.Format("ui.tutorial.story_revealed", chapterNumber);
                }
                else
                {
                    guidedChapterIntroClosing = true;
                    guidedChapterIntroClosingStartedAt = NowForUi();
                    localPreviewSessionPrompt = BeeLocalization.Format("ui.tutorial.chapter_ready", chapterNumber);
                    BeginReferenceFeedbackPulse("preview");
                }
            }
        }

        private static void DrawGuidedChapterIntroCard(Rect rect, GuidedChapterIntroCard card, bool compact, float opacity)
        {
            DrawGuidedChapterIntroPanel(rect, new Color(0.040f, 0.047f, 0.036f, 0.98f), new Color(card.Accent.r, card.Accent.g, card.Accent.b, 0.72f), opacity);
            float iconSize = compact ? Mathf.Min(44f, rect.height - 14f) : Mathf.Min(48f, rect.height - 20f);
            Rect iconRect = new Rect(rect.x + (compact ? 10f : 14f), rect.y + (rect.height - iconSize) * 0.5f, iconSize, iconSize);
            Texture2D iconTexture = GetIconTexture(card.IconId);
            Color previous = GUI.color;
            GUI.color = new Color(1f, 1f, 1f, opacity);
            GUI.DrawTexture(IconSafeRect(iconRect), iconTexture, ScaleMode.ScaleToFit, true);
            GUI.color = previous;

            float textX = iconRect.xMax + (compact ? 10f : 12f);
            GUIStyle roleStyle = new GUIStyle(tinyLabelStyle)
            {
                fontSize = compact ? 9 : 10,
                fontStyle = FontStyle.Bold,
                alignment = TextAnchor.MiddleLeft
            };
            roleStyle.normal.textColor = card.Accent;
            DrawGuidedChapterIntroLabel(new Rect(textX, rect.y + (compact ? 7f : 10f), rect.xMax - textX - 8f, 16f), card.Label, roleStyle, opacity);
            DrawGuidedChapterIntroLabel(new Rect(textX, rect.y + (compact ? 20f : 25f), rect.xMax - textX - 8f, 22f), card.Title, new GUIStyle(titleStyle) { fontSize = compact ? 15 : 18, alignment = TextAnchor.MiddleLeft }, opacity);
            DrawGuidedChapterIntroLabel(new Rect(textX, rect.y + (compact ? 38f : 48f), rect.xMax - textX - 9f, Mathf.Max(18f, rect.height - (compact ? 42f : 54f))), card.Description, new GUIStyle(smallStyle) { fontSize = compact ? 10 : 12, alignment = TextAnchor.UpperLeft, wordWrap = true }, opacity);
        }

        private static Rect TutorialTargetSpotlightRect(Rect artRect, bool portrait)
        {
            if (GuidedCollectionTutorialTargetsSurfaceSwitch())
            {
                Rect control = SurfaceSwitchButtonRect(portrait);
                return new Rect(control.x - 8f, control.y - 7f, control.width + 16f, control.height + 14f);
            }

            string targetHotspotId = GuidedCollectionTutorialVisualHotspot();
            ReferenceHiveHotspot hotspot = FindReferenceHotspot(targetHotspotId);
            Vector2 anchor = GetReferenceVisualAnchor(hotspot) + ManualCollectionMarkerOffset(targetHotspotId);
            Vector2 center = ReferencePoint(artRect, anchor.x, anchor.y);
            float size = targetHotspotId == "nursery_cluster" ? (portrait ? 152f : 168f) : (portrait ? 138f : 154f);
            return new Rect(center.x - size * 0.5f, center.y - size * 0.5f, size, size);
        }

        private static void DrawGuidedCollectionTutorial(Rect artRect, bool portrait)
        {
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.Inactive) return;
            if (ShouldShowGuidedChapterIntro())
            {
                DrawGuidedChapterIntro(portrait);
                return;
            }

            bool hasTarget = !string.IsNullOrWhiteSpace(GuidedCollectionTutorialTargetHotspot())
                || GuidedCollectionTutorialTargetsSurfaceSwitch();
            bool hasSpotlight = !string.IsNullOrWhiteSpace(GuidedCollectionTutorialVisualHotspot())
                || GuidedCollectionTutorialTargetsSurfaceSwitch();
            Rect spotlight = hasSpotlight
                ? TutorialTargetSpotlightRect(artRect, portrait)
                : new Rect(0f, 0f, 0f, 0f);
            DrawGuidedTutorialScrim(spotlight, 0.12f);
            if (hasSpotlight)
            {
                DrawGuidedTutorialSpotlight(spotlight, portrait);
            }
            DrawGuidedDefenseThreat(artRect, portrait);

            Rect panel = TutorialPanelRect(portrait);
            DrawPremiumPanel(panel, new Color(0.075f, 0.047f, 0.020f, 0.985f), new Color(1f, 0.70f, 0.16f, 0.98f));
            string chapterId = GuidedCollectionTutorialChapterId();
            bool broodChapter = chapterId == "chapter_2_brood_care";
            bool workerChapter = chapterId == "chapter_3_first_worker";
            bool upgradeChapter = chapterId == "chapter_4_first_upgrade";
            bool defenseChapter = chapterId == "chapter_5_first_defense";
            bool worldChapter = chapterId == "chapter_6_first_world_transition";
            bool forageChapter = chapterId == "chapter_7_first_foraging_flight";
            int chapterNumber = forageChapter ? 7 : worldChapter ? 6 : defenseChapter ? 5 : upgradeChapter ? 4 : workerChapter ? 3 : broodChapter ? 2 : 1;
            DrawGameIcon(new Rect(panel.x + 18f, panel.y + 18f, portrait ? 48f : 44f, portrait ? 48f : 44f), forageChapter ? "pollen" : worldChapter ? "world" : defenseChapter ? "guard-bee" : upgradeChapter ? "wax" : workerChapter ? "worker-bee" : broodChapter ? "nursery" : "honey", Color.white);
            GUI.Label(new Rect(panel.x + 76f, panel.y + 14f, panel.width - 242f, 20f), BeeLocalization.Format("tutorial.shell.chapter", chapterNumber), new GUIStyle(tinyLabelStyle) { fontSize = portrait ? 11 : 10 });
            GUI.Label(new Rect(panel.xMax - 162f, panel.y + 14f, 116f, 20f), BeeLocalization.Format("tutorial.shell.act_progress", guidedOpeningActMilestones), new GUIStyle(tinyLabelStyle) { fontSize = portrait ? 11 : 10, alignment = TextAnchor.MiddleRight });
            DrawTutorialSkipButton(panel, portrait);

            string title;
            string body;
            string action;
            switch (guidedCollectionTutorialStep)
            {
                case GuidedCollectionTutorialStep.Welcome:
                    title = BeeLocalization.Text("tutorial.chapter_01.welcome.title", "Le premier nectar");
                    body = BeeLocalization.Text("tutorial.chapter_01.welcome.body", "Le miel est la réserve d'énergie de la colonie: il nourrit, entraîne et met les équipes au travail. Les butineuses rapportent le premier lot.");
                    action = BeeLocalization.Text("tutorial.chapter_01.welcome.action", "Suivre les butineuses");
                    break;
                case GuidedCollectionTutorialStep.CollectHoney:
                    title = BeeLocalization.Text("tutorial.chapter_01.collect.title", "Le miel attend");
                    body = BeeLocalization.Text("tutorial.chapter_01.collect.body", "Les ouvrières ont rempli la réserve éclairée. Sécurise cette première récolte.");
                    action = string.Empty;
                    break;
                case GuidedCollectionTutorialStep.Collected:
                    title = BeeLocalization.Text("tutorial.chapter_01.first_collection.title", "Réserve alimentée");
                    body = BeeLocalization.Format("tutorial.chapter_01.first_collection.body", Mathf.FloorToInt(guidedOpeningFirstCollectionAmount));
                    action = BeeLocalization.Text("tutorial.chapter_01.first_collection.action", "Organiser la relève");
                    break;
                case GuidedCollectionTutorialStep.HoneyWorkersReady:
                    title = BeeLocalization.Text("tutorial.chapter_01.production.choice.title", "Organiser la relève");
                    body = BeeLocalization.Text("tutorial.chapter_01.production.choice.body", "Cadence douce: 3 ouvrières, 22 s, +360 miel et stabilité du couvain +4. Renfort: 5 ouvrières, 14 s et +480 miel.");
                    action = string.Empty;
                    break;
                case GuidedCollectionTutorialStep.HoneyProduction:
                    title = guidedOpeningProductionPlan == "steady"
                        ? BeeLocalization.Text("tutorial.chapter_01.production.steady.title", "Cadence douce")
                        : BeeLocalization.Text("tutorial.chapter_01.production.surge.title", "Renfort de la réserve");
                    body = guidedOpeningProductionPlan == "steady"
                        ? BeeLocalization.Text("tutorial.chapter_01.production.steady.body", "Trois ouvrières relancent la chambre sans délaisser le couvain. Leur travail prépare aussi la nurserie.")
                        : BeeLocalization.Text("tutorial.chapter_01.production.surge.body", "Cinq ouvrières concentrent leurs efforts sur une récolte plus rapide et plus abondante.");
                    action = string.Empty;
                    break;
