            {
                Rect steady = TutorialBroodChoiceButtonRect(portrait, true);
                Rect surge = TutorialBroodChoiceButtonRect(portrait, false);
                DrawPremiumPanel(steady, new Color(0.31f, 0.20f, 0.055f, 0.98f), new Color(0.94f, 0.67f, 0.20f, 1f));
                DrawPremiumPanel(surge, new Color(0.42f, 0.235f, 0.055f, 0.98f), new Color(1f, 0.76f, 0.24f, 1f));
                GUI.Label(steady, BeeLocalization.Text("tutorial.chapter_01.production.steady.button", "Cadence · 3 ouvrières"), new GUIStyle(centeredTinyLabelStyle) { fontSize = portrait ? 12 : 11 });
                GUI.Label(surge, BeeLocalization.Text("tutorial.chapter_01.production.surge.button", "Renfort · 5 ouvrières"), new GUIStyle(centeredTinyLabelStyle) { fontSize = portrait ? 12 : 11 });
