        public static void DrawGuidedWorldMapTutorialForRuntime(
            Rect playerHiveSpotlight,
            Rect resourceSpotlight,
            Rect returnHiveButtonSpotlight,
            float foragingProgress01,
            Func<bool> startForagingFlight)
        {
            if (!GuidedWorldMapTutorialActiveForRuntime()) return;
            EnsureStyles();
            bool portrait = IsPortraitLayout();
            bool locateHive = guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorldLocateHive;
            bool locateResource = guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageSelectResource;
            bool returnHive = guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorldReturnHive
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageReturnHive;
            bool foragingFlight = guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageFlying;
            bool forageChapter = GuidedCollectionTutorialChapterId() == "chapter_7_first_foraging_flight";
            Rect spotlight = locateHive
                ? playerHiveSpotlight
                : locateResource
                    ? resourceSpotlight
                : returnHive
                    ? returnHiveButtonSpotlight
                    : new Rect(0f, 0f, 0f, 0f);

            DrawGuidedTutorialScrim(spotlight, 0.28f);
            if (spotlight.width > 0f && spotlight.height > 0f) DrawGuidedTutorialSpotlight(spotlight, portrait);

            Rect panel = TutorialPanelRect(portrait);
            DrawPremiumPanel(panel, new Color(0.075f, 0.047f, 0.020f, 0.985f), new Color(1f, 0.70f, 0.16f, 0.98f));
            DrawGameIcon(new Rect(panel.x + 18f, panel.y + 18f, portrait ? 48f : 44f, portrait ? 48f : 44f), forageChapter ? "pollen" : "world", Color.white);
            GUI.Label(new Rect(panel.x + 76f, panel.y + 14f, panel.width - 124f, 20f), forageChapter ? "CHAPITRE 7" : "CHAPITRE 6", new GUIStyle(tinyLabelStyle) { fontSize = portrait ? 11 : 10 });

            string title;
            string body;
            string action;
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorldMapArrival)
            {
                title = "Le territoire extérieur";
                body = guidedWorldNavigationHintLevel > 0f
                    ? BeeLocalization.Text("tutorial.chapter_06.map_arrival.sun_beacon", "La carte réelle 50x50 reste intacte. Ta balise confirme le secteur C32_32; ruches, ressources et menaces restent des couches séparées.")
                    : guidedDefenseWorldBriefingPlan == "guarded_return"
                        ? BeeLocalization.Text("tutorial.chapter_06.map_arrival.guarded_return", "La carte réelle 50x50 reste intacte. Le couloir gardé relie la ruche JOUEUR au retour contextuel.")
                        : "Voici la carte réelle 50x50. Le terrain reste intact: ruches, ressources et menaces sont des couches de jeu séparées.";
                action = "Repérer ma ruche";
            }
            else if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorldLocateHive)
            {
                title = "Ta ruche dans le monde";
                body = guidedWorldNavigationHintLevel > 0f
                    ? BeeLocalization.Text("tutorial.chapter_06.locate.sun_beacon", "Balise active: touche la ruche JOUEUR éclairée dans C32_32. Elle sera l'origine des futures expéditions.")
                    : guidedDefenseWorldBriefingPlan == "guarded_return"
                        ? BeeLocalization.Text("tutorial.chapter_06.locate.guarded_return", "Touche la ruche JOUEUR éclairée, origine du couloir de retour protégé.")
                        : "Touche la ruche JOUEUR éclairée. C'est le point de départ des futures expéditions de butinage.";
                action = string.Empty;
            }
            else if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorldHiveLocated)
            {
                title = "Point de départ confirmé";
                body = "La ruche est repérée sans modifier l'image du terrain. Plus tard, les butineuses partiront d'ici vers les ressources extérieures.";
                action = "Préparer le retour";
            }
            else if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorldReturnHive)
            {
                title = "Retourner à la colonie";
                body = "Le même bouton contextuel affiche maintenant Ruche. Utilise-le pour revenir à l'intérieur.";
                action = string.Empty;
            }
            else if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageMapArrival)
            {
                title = "Trouver du pollen";
                body = "Le terrain 50x50 reste intact. Repère maintenant l'icône de pollen placée sur une zone terrestre valide près de ta ruche.";
                action = "Repérer le pollen";
            }
            else if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageSelectResource)
            {
                title = "Une source accessible";
                body = "Touche uniquement le pollen éclairé. Les autres ressources et le terrain ne peuvent pas lancer cette première mission.";
                action = string.Empty;
            }
            else if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageResourceSelected)
            {
                title = "Envoyer les butineuses";
                body = "Trois butineuses feront l'aller-retour par les airs. Le vol est gratuit, local et n'accordera sa récolte qu'après réclamation dans la ruche.";
                action = "Envoyer 3 butineuses";
            }
            else if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageFlying)
            {
                title = "Butinage en cours";
                body = "Suis les abeilles jusqu'au pollen puis vers la ruche. Aucun raccourci payant ni gain serveur n'est appliqué.";
                action = string.Empty;
            }
            else if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageFlightComplete)
            {
                title = "Récolte rapportée";
                body = Mathf.FloorToInt(guidedForagingPendingPollen).ToString(CultureInfo.InvariantCulture) + " pollen attendent à l'intérieur. Retourne à la colonie pour les réclamer manuellement.";
                action = "Préparer le retour";
            }
            else
            {
                title = "Ramener le pollen";
                body = "Le bouton contextuel affiche Ruche. La récolte restera en attente jusqu'à ton clic dans la colonie.";
                action = string.Empty;
            }

            GUI.Label(new Rect(panel.x + 76f, panel.y + 34f, panel.width - 116f, 34f), title, new GUIStyle(titleStyle) { fontSize = portrait ? 22 : 20, alignment = TextAnchor.MiddleLeft });
            GUI.Label(new Rect(panel.x + 22f, panel.y + 72f, panel.width - 44f, portrait ? 58f : 50f), body, new GUIStyle(smallStyle) { fontSize = portrait ? 14 : 13, wordWrap = true, alignment = TextAnchor.UpperLeft });

            Rect skip = TutorialSkipButtonRect(portrait);
            DrawPremiumPanel(skip, new Color(0.12f, 0.065f, 0.025f, 0.96f), new Color(0.78f, 0.52f, 0.16f, 0.88f));
            GUI.Label(skip, "X", centeredTinyLabelStyle);
            if (GUI.Button(skip, string.Empty, GUIStyle.none))
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.Inactive);
                localPreviewSessionPrompt = PendingProductionSummary();
                return;
            }

            if (locateHive || locateResource || returnHive)
            {
                GUI.Label(new Rect(panel.x + 22f, panel.yMax - 42f, panel.width - 44f, 24f), "OBJECTIF EN COURS", new GUIStyle(centeredTinyLabelStyle) { fontSize = portrait ? 12 : 11 });
                return;
            }

            if (foragingFlight)
            {
                GUI.Label(new Rect(panel.x + 22f, panel.yMax - 48f, panel.width - 44f, 18f), "VOL " + Mathf.RoundToInt(Mathf.Clamp01(foragingProgress01) * 100f).ToString(CultureInfo.InvariantCulture) + " %", new GUIStyle(centeredTinyLabelStyle) { fontSize = portrait ? 12 : 11 });
                DrawProgressBar(new Rect(panel.x + 24f, panel.yMax - 24f, panel.width - 48f, 8f), Mathf.Clamp01(foragingProgress01));
                return;
            }

            Rect button = TutorialActionButtonRect(portrait);
            DrawPremiumPanel(button, new Color(0.52f, 0.275f, 0.035f, 0.98f), new Color(1f, 0.78f, 0.22f, 1f));
            GUI.Label(button, action, new GUIStyle(centeredTinyLabelStyle) { fontSize = portrait ? 14 : 13 });
            if (GUI.Button(button, string.Empty, GUIStyle.none))
            {
                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageResourceSelected)
                {
                    if (startForagingFlight != null) startForagingFlight();
                }
                else
                {
                    HandleGuidedCollectionTutorialPrimaryAction();
                }
            }
        }

        private static void DrawGuidedDefenseThreat(Rect artRect, bool portrait)
        {
            bool visible = guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseWelcome
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseInspectGuardPost
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseReady
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseScouting
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseStrategyReady
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseMobilizing;
            if (!visible) return;

            float time = Application.isPlaying ? Time.realtimeSinceStartup : 1.6f;
            float pulse = productionReducedMotionForProof ? 0f : Mathf.Sin(time * 4.4f) * 0.045f;
            float retreat = guidedCollectionTutorialStep == GuidedCollectionTutorialStep.DefenseMobilizing ? DefenseProgress01() : 0f;
            Vector2 center = ReferencePoint(artRect, 1094f + retreat * 52f, 280f - retreat * 42f);
            center.y += productionReducedMotionForProof ? 0f : Mathf.Sin(time * 2.8f) * 5f;
            float size = (portrait ? 88f : 104f) * (1f + pulse) * Mathf.Lerp(1f, 0.58f, retreat);
            Rect glow = new Rect(center.x - size * 0.72f, center.y - size * 0.72f, size * 1.44f, size * 1.44f);
            Color previous = GUI.color;
            GUI.color = new Color(1f, 0.24f, 0.08f, Mathf.Lerp(0.42f, 0.12f, retreat));
            GUI.DrawTexture(glow, GetPremiumTexture("honey-glow-pool"), ScaleMode.StretchToFill, true);
            GUI.color = new Color(1f, 1f, 1f, Mathf.Lerp(1f, 0.35f, retreat));
            GUI.DrawTexture(new Rect(center.x - size * 0.5f, center.y - size * 0.5f, size, size), GetRuntimeWaxMothThreatTexture(), ScaleMode.ScaleToFit, true);
            GUI.color = previous;
        }

        private static void DrawGuidedTutorialScrim(Rect spotlight, float opacity)
        {
            Color previous = GUI.color;
            GUI.color = new Color(0.045f, 0.024f, 0.008f, Mathf.Clamp01(opacity));
            if (spotlight.width <= 0f || spotlight.height <= 0f)
            {
                GUI.DrawTexture(new Rect(0f, 0f, Screen.width, Screen.height), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            }
            else
            {
                GUI.DrawTexture(new Rect(0f, 0f, Screen.width, Mathf.Max(0f, spotlight.y)), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
                GUI.DrawTexture(new Rect(0f, spotlight.yMax, Screen.width, Mathf.Max(0f, Screen.height - spotlight.yMax)), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
                GUI.DrawTexture(new Rect(0f, spotlight.y, Mathf.Max(0f, spotlight.x), spotlight.height), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
                GUI.DrawTexture(new Rect(spotlight.xMax, spotlight.y, Mathf.Max(0f, Screen.width - spotlight.xMax), spotlight.height), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
                GUI.DrawTexture(spotlight, GetPremiumTexture("tutorial-spotlight-mask"), ScaleMode.StretchToFill, true);
            }

            GUI.color = previous;
        }

        private static void DrawGuidedTutorialSpotlight(Rect spotlight, bool portrait)
        {
            float pulse = productionReducedMotionForProof ? 1f : 1f + Mathf.Sin(NowForUi() * 4.4f) * 0.055f;
            Rect glow = new Rect(
                spotlight.center.x - spotlight.width * pulse * 0.58f,
                spotlight.center.y - spotlight.height * pulse * 0.58f,
                spotlight.width * pulse * 1.16f,
                spotlight.height * pulse * 1.16f);
            Color previous = GUI.color;
            GUI.color = new Color(1f, 0.68f, 0.10f, 0.92f);
            GUI.DrawTexture(glow, GetPremiumTexture("selected-glow"), ScaleMode.ScaleToFit, true);
            GUI.color = new Color(0.45f, 1f, 0.64f, 0.70f);
            Rect innerGlow = new Rect(
                spotlight.x + spotlight.width * 0.08f,
                spotlight.y + spotlight.height * 0.08f,
                spotlight.width * 0.84f,
                spotlight.height * 0.84f);
            GUI.DrawTexture(innerGlow, GetPremiumTexture("selected-glow"), ScaleMode.ScaleToFit, true);
            GUI.color = Color.white;
            float bob = productionReducedMotionForProof ? 0f : Mathf.Sin(NowForUi() * 5.2f) * 8f;
            Rect guideBee = new Rect(spotlight.center.x - 30f, spotlight.y - 64f + bob, 60f, 52f);
            GUI.DrawTexture(guideBee, GetRuntimeWorkerBeeTexture(), ScaleMode.ScaleToFit, true);
            GUI.color = previous;
        }

        private static Vector2 ManualCollectionMarkerOffset(string hotspotId)
        {
            // GetReferenceVisualAnchor already centers on the imported SVG contour's
            // bounding box (or the hand-authored token anchor as a fallback), both of
            // which sit within a few pixels of the true polygon centroid. These three
            // per-zone corrections predate that anchor and pushed the marker off the
            // visible building art once the real contour anchor took over.
            return Vector2.zero;
        }

        private static Rect SpeedUpWindowRect(bool compact, float screenWidth, float screenHeight)
        {
            float panelWidth = compact
                ? Mathf.Min(screenWidth - 24f, 420f)
                : Mathf.Min(screenWidth * 0.55f, 600f);
            panelWidth = compact ? panelWidth : Mathf.Max(480f, panelWidth);
            float panelHeight = compact ? Mathf.Min(screenHeight - 24f, 700f) : Mathf.Min(screenHeight - 72f, 650f);
            return new Rect(
                compact ? (screenWidth - panelWidth) * 0.5f : Mathf.Max(44f, screenWidth * 0.08f),
                compact ? 12f : (screenHeight - panelHeight) * 0.5f,
                panelWidth,
                panelHeight);
        }

        private static void OpenSpeedUpDialog(SpeedUpCategory category, string targetId, long remainingSeconds)
        {
            speedUpWindowOpen = true;
            speedUpSelectedCategory = category;
            speedUpTargetHotspotId = targetId ?? string.Empty;
            SpeedUpDialog.Open(new SpeedUpDialogContext(category, speedUpTargetHotspotId, remainingSeconds));
        }

        public static void OpenSpeedUpDialogForProof(SpeedUpCategory category, string targetId, long remainingSeconds)
        {
            OpenSpeedUpDialog(category, targetId, remainingSeconds);
        }

        private static float GetSpeedUpRemainingForHotspot(string hotspotId, SpeedUpCategory category)
        {
            if (string.IsNullOrEmpty(hotspotId)) return 0f;

            switch (category)
            {
                case SpeedUpCategory.Construction:
                    return GetBuildingUpgradeRemaining(hotspotId);
                case SpeedUpCategory.Research:
                    return GetResearchRemaining(hotspotId);
                case SpeedUpCategory.Training:
                    return GetTrainingRemaining(hotspotId);
                case SpeedUpCategory.Healing:
                    return GetHealingRemaining(hotspotId);
                case SpeedUpCategory.Manufacturing:
                    return GetManufacturingRemaining(hotspotId);
                case SpeedUpCategory.Universal:
                    return GetUniversalRemaining(hotspotId);
                default:
                    return 0f;
            }
        }

        private static float GetBuildingUpgradeRemaining(string hotspotId)
        {
            if (!OfficialBuildingUpgradeConfigured())
            {
                return IsUpgradeRunning() && string.Equals(localPreviewUpgradeHotspotId, hotspotId, StringComparison.Ordinal)
                    ? Mathf.Max(0f, localPreviewUpgradeDuration - (NowForUi() - localPreviewUpgradeStartedAt))
                    : 0f;
            }
            var model = OfficialBuildingUpgradeModel();
            if (model == null || model.ActiveOperation == null) return 0f;
            var op = model.ActiveOperation;
            if (!string.Equals(op.BuildingKey, hotspotId, StringComparison.Ordinal)) return 0f;
            return Mathf.Max(0f, (float)(op.CompletesAtUtc - DateTimeOffset.UtcNow).TotalSeconds);
        }

        private static float GetResearchRemaining(string hotspotId)
        {
            if (!OfficialResearchConfigured())
            {
                return IsResearchRunning() && string.Equals(localPreviewResearchId, hotspotId, StringComparison.Ordinal)
                    ? Mathf.Max(0f, localPreviewResearchDuration - (NowForUi() - localPreviewResearchStartedAt))
                    : 0f;
            }
            var model = OfficialResearchModel();
            if (model == null || model.ActiveOperation == null) return 0f;
            var op = model.ActiveOperation;
            if (!string.Equals(op.ResearchId, hotspotId, StringComparison.Ordinal)) return 0f;
            return Mathf.Max(0f, (float)(op.CompletesAtUtc - DateTimeOffset.UtcNow).TotalSeconds);
        }

        private static float GetTrainingRemaining(string hotspotId)
        {
            if (string.IsNullOrEmpty(localPreviewTrainingTroopType)) return 0f;
            if (!string.Equals(localPreviewTrainingTroopType, hotspotId, StringComparison.Ordinal)) return 0f;
            return IsTrainingRunning() ? Mathf.Max(0f, localPreviewTrainingDuration - (NowForUi() - localPreviewTrainingStartedAt)) : 0f;
        }

        private static float GetHealingRemaining(string hotspotId)
        {
            return 0f;
        }

        private static float GetManufacturingRemaining(string hotspotId)
        {
            if (!OfficialOfflineProductionConfigured()) return 0f;
            var model = OfficialOfflineProductionModel();
            if (model == null) return 0f;
            var line = model.FindLine(hotspotId);
            if (line == null || line.CollectableWholeUnits > 0L) return 0f;
            return 0f;
        }

        private static float GetUniversalRemaining(string hotspotId)
        {
            float max = 0f;
            max = Math.Max(max, GetBuildingUpgradeRemaining(hotspotId));
            max = Math.Max(max, GetResearchRemaining(hotspotId));
            max = Math.Max(max, GetTrainingRemaining(hotspotId));
            max = Math.Max(max, GetManufacturingRemaining(hotspotId));
            return max;
        }

        private static string FormatTimeRemaining(float seconds)
        {
            if (seconds <= 0f) return BeeLocalization.Text("speedup.ready", "Prêt");
            TimeSpan ts = TimeSpan.FromSeconds(seconds);
            if (ts.TotalDays >= 1) return $"{(int)ts.TotalDays}j {ts.Hours}h {ts.Minutes}min";
            if (ts.TotalHours >= 1) return $"{ts.Hours}h {ts.Minutes}min {ts.Seconds}s";
            if (ts.TotalMinutes >= 1) return $"{ts.Minutes}min {ts.Seconds}s";
            return $"{ts.Seconds}s";
        }

        private static void ApplySpeedUpToTarget(SpeedUpItem item, int count)
        {
            long reduction = item.DurationSeconds * count;

            if (string.IsNullOrEmpty(speedUpTargetHotspotId)) return;

            switch (item.Category)
            {
                case SpeedUpCategory.Construction:
                    ApplySpeedUpToBuilding(speedUpTargetHotspotId, reduction);
                    break;
                case SpeedUpCategory.Research:
                    ApplySpeedUpToResearch(speedUpTargetHotspotId, reduction);
                    break;
                case SpeedUpCategory.Training:
                    ApplySpeedUpToTraining(speedUpTargetHotspotId, reduction);
                    break;
                case SpeedUpCategory.Healing:
                    break;
                case SpeedUpCategory.Manufacturing:
                    ApplySpeedUpToManufacturing(speedUpTargetHotspotId, reduction);
                    break;
                case SpeedUpCategory.Universal:
                    // Try each category in order of priority
                    ApplySpeedUpToBuilding(speedUpTargetHotspotId, reduction);
                    if (GetBuildingUpgradeRemaining(speedUpTargetHotspotId) > 0f) break;
                    ApplySpeedUpToResearch(speedUpTargetHotspotId, reduction);
                    if (GetResearchRemaining(speedUpTargetHotspotId) > 0f) break;
                    ApplySpeedUpToTraining(speedUpTargetHotspotId, reduction);
                    if (GetTrainingRemaining(speedUpTargetHotspotId) > 0f) break;
                    ApplySpeedUpToManufacturing(speedUpTargetHotspotId, reduction);
                    break;
            }

            UIFeedbackSystem.ShowFloatingText("-" + item.FormattedDuration, Vector2.zero, new Color(1f, 0.85f, 0.25f));
            UIFeedbackSystem.ShowResourceCollected("speedup", 1f, Vector2.zero, Vector2.zero);
        }

        private static void ApplySpeedUpToBuilding(string hotspotId, long reductionSeconds)
        {
            if (!OfficialBuildingUpgradeConfigured())
            {
                if (IsUpgradeRunning() && string.Equals(localPreviewUpgradeHotspotId, hotspotId, StringComparison.Ordinal))
                {
                    localPreviewUpgradeStartedAt -= reductionSeconds;
                    CompletePreviewUpgradeIfReady();
                }
                return;
            }
            var model = OfficialBuildingUpgradeModel();
            if (model == null || model.ActiveOperation == null) return;
            var op = model.ActiveOperation;
            if (!string.Equals(op.BuildingKey, hotspotId, StringComparison.Ordinal)) return;
            // The actual reduction would be handled by the server/official system
            // For local preview, we just update the local state
            if (offlineProductionController != null && !offlineProductionController.IsBusy)
                offlineProductionController.Refresh();
        }

        private static void ApplySpeedUpToResearch(string hotspotId, long reductionSeconds)
        {
            if (!OfficialResearchConfigured())
            {
                if (IsResearchRunning() && string.Equals(localPreviewResearchId, hotspotId, StringComparison.Ordinal))
                {
                    localPreviewResearchStartedAt -= reductionSeconds;
                    CompletePreviewResearchIfReady();
                }
                return;
            }
            var model = OfficialResearchModel();
            if (model == null || model.ActiveOperation == null) return;
            var op = model.ActiveOperation;
            if (!string.Equals(op.ResearchId, speedUpTargetHotspotId, StringComparison.Ordinal)) return;
            // Actual reduction handled by server
        }

        private static void ApplySpeedUpToTraining(string hotspotId, long reductionSeconds)
        {
            if (!string.Equals(localPreviewTrainingTroopType, hotspotId, StringComparison.Ordinal)) return;
            localPreviewTrainingStartedAt -= reductionSeconds;
            CompletePreviewTrainingIfReady();
        }

        private static void ApplySpeedUpToManufacturing(string hotspotId, long reductionSeconds)
        {
            if (!OfficialOfflineProductionConfigured()) return;
            var model = OfficialOfflineProductionModel();
            if (model == null) return;
            var line = model.FindLine(hotspotId);
            if (line == null || line.CollectableWholeUnits > 0L) return;
            // Actual reduction handled by server
        }

        private static ReferenceHiveHotspot HitReferenceHotspot(Vector2 artPoint)
        {
            if (HiveVisualContourImportRuntime.TryHitVisualContour(artPoint, out string importedHotspotId))
            {
                for (int i = 0; i < ReferenceHotspots.Length; i++)
                {
                    if (ReferenceHotspots[i].HotspotId == importedHotspotId) return ReferenceHotspots[i];
                }
            }

            if (HivePixelPerfectContourCalibration.TryHit(artPoint, out HiveZoneContourDefinition calibrated))
            {
                for (int i = 0; i < ReferenceHotspots.Length; i++)
                {
                    if (ReferenceHotspots[i].HotspotId == calibrated.HotspotId) return ReferenceHotspots[i];
                }
            }

            ReferenceHiveHotspot best = default;
            int bestPriority = int.MinValue;

            for (int i = 0; i < ReferenceHotspots.Length; i++)
            {
                ReferenceHiveHotspot hotspot = ReferenceHotspots[i];
                if (hotspot.Priority < bestPriority || !PointInReferencePolygon(artPoint, hotspot.Polygon)) continue;
                best = hotspot;
                bestPriority = hotspot.Priority;
            }

            return best;
        }

        public static void SelectReferenceHotspotForProof(string cellId)
        {
            splashAuthGateState = SplashAuthGateState.EnteredHive;
            for (int i = 0; i < ReferenceHotspots.Length; i++)
            {
                if (ReferenceHotspots[i].CellId != cellId && ReferenceHotspots[i].HotspotId != cellId) continue;
                SelectReferenceHotspot(ReferenceHotspots[i]);
                return;
            }
        }

        public static bool TrySelectReferenceHotspotAtArtPointForProof(float x, float y)
        {
            ReferenceHiveHotspot hotspot = HitReferenceHotspot(new Vector2(x, y));
            if (string.IsNullOrWhiteSpace(hotspot.CellId)) return false;
            SelectReferenceHotspot(hotspot);
            return true;
        }

        public static string ReferenceHotspotAtArtPointForProof(float x, float y)
