            if (chapterNumber <= 0 || !ShouldShowGuidedChapterIntro())
            {
                cueId = string.Empty;
                narration = string.Empty;
                visibleCharacters = 0;
                opacity = 0f;
                return false;
            }

            GuidedChapterIntroDefinition definition = GuidedChapterIntroDefinitionForNumber(chapterNumber);
            cueId = BeeLocalization.LocalizedAudioCue(definition.AudioCueId);
            narration = definition.Narration;
            visibleCharacters = GuidedChapterIntroVisibleCharacterCount(definition);
            opacity = GuidedChapterIntroOpacity();
            return true;
        }

