                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorldHiveLocated
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorldReturnHive
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageMapArrival
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageSelectResource
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageResourceSelected
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageFlying
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageFlightComplete
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageReturnHive;
        }

        public static bool GuidedWorldMapTutorialSelectionStepForRuntime()
        {
            return GuidedWorldMapTutorialHiveSelectionStepForRuntime()
                || GuidedWorldMapTutorialResourceSelectionStepForRuntime();
        }

        public static bool GuidedWorldMapTutorialHiveSelectionStepForRuntime()
        {
            return guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorldLocateHive;
        }

        public static bool GuidedWorldMapTutorialResourceSelectionStepForRuntime()
        {
            return guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageSelectResource;
        }

        public static bool GuidedWorldMapForagingTutorialActiveForRuntime()
        {
            return guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageMapArrival
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageSelectResource
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageResourceSelected
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageFlying
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageFlightComplete
                || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageReturnHive;
        }

        public static void RegisterGuidedWorldMapBlockedInputForRuntime()
        {
            if (GuidedWorldMapTutorialActiveForRuntime()) guidedCollectionTutorialBlockedClicks++;
        }

        public static bool SelectGuidedWorldMapHiveForRuntime(string hiveId)
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.WorldLocateHive) return false;
            if (!string.Equals(hiveId, "hive_player_test", StringComparison.Ordinal))
            {
                guidedCollectionTutorialBlockedClicks++;
                return false;
            }

            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorldHiveLocated);
            localPreviewSessionPrompt = "Ruche reperee sur la carte 50x50";
            return true;
        }

        public static bool SelectGuidedWorldMapResourceForRuntime(string resourceId)
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.ForageSelectResource) return false;
            if (!string.Equals(resourceId, "res_pollen_core", StringComparison.Ordinal))
            {
                guidedCollectionTutorialBlockedClicks++;
                return false;
            }

            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.ForageResourceSelected);
            localPreviewSessionPrompt = "Pollen repere: butineuses pretes";
            return true;
        }

        public static bool RegisterGuidedForagingFlightStartedForRuntime(string hiveId, string resourceId)
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.ForageResourceSelected) return false;
            if (!string.Equals(hiveId, "hive_player_test", StringComparison.Ordinal)
                || !string.Equals(resourceId, "res_pollen_core", StringComparison.Ordinal)) return false;

            guidedForagingDispatchCount++;
            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.ForageFlying);
            localPreviewSessionPrompt = "Trois butineuses en vol";
            return true;
        }

        public static bool CompleteGuidedForagingFlightForRuntime(string resourceId, float pollenAmount)
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.ForageFlying) return false;
            if (!string.Equals(resourceId, "res_pollen_core", StringComparison.Ordinal) || pollenAmount <= 0f) return false;

            EnsureLocalPreviewStrategicProfileLoaded();
            guidedForagingPendingPollen = Mathf.Max(1f, pollenAmount + guidedDefenseExpeditionPollenBonus);
            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.ForageFlightComplete);
            localPreviewSessionPrompt = "Butineuses revenues au point de depart";
            return true;
        }

        public static bool TryBeginGuidedWorldMapReturnForRuntime()
        {
            if (!GuidedWorldMapTutorialActiveForRuntime()) return true;
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorldReturnHive)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorldReturningToHive);
                localPreviewSessionPrompt = "Retour vers la ruche";
                return true;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageReturnHive)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.ForageReturningToHive);
                localPreviewSessionPrompt = "Retour du pollen vers la ruche";
                return true;
            }

            {
                guidedCollectionTutorialBlockedClicks++;
                return false;
            }
        }

        public static bool ResumeGuidedWorldTransitionAfterHiveLoad()
        {
            referenceSurfaceMode = ReferenceSurfaceMode.Hive;
            activeMainMenuId = string.Empty;
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorldReturningToHive)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorldReturned);
                localPreviewSessionPrompt = "Chapitre 6 termine";
                return true;
            }

            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ForageReturningToHive)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.ForageClaim);
                localPreviewSessionPrompt = "Recolte de pollen a reclamer";
                return true;
            }

            return false;
        }

