        public static string[] GuidedOpeningActPacingForProof()
        {
            int chapterOneFast = Mathf.RoundToInt(
                GuidedOpeningSurgeDuration
                + GuidedOpeningCircuitRoundTarget * (GuidedOpeningReserveRouteDuration + GuidedOpeningVentilationDuration)
                + GuidedOpeningSecureReserveCharterDuration + GuidedOpeningCommissioningSurgeDuration + GuidedOpeningCommissioningReserveSealDuration + GuidedOpeningThermalEscortDuration
                + GuidedOpeningHygienePurgeEnzymaticDuration);
            int chapterOneSlow = Mathf.RoundToInt(
                GuidedOpeningSteadyDuration
                + GuidedOpeningCircuitRoundTarget * (GuidedOpeningNurseryRouteDuration + GuidedOpeningWaxSealDuration)
                + GuidedOpeningBroodBridgeCharterDuration + GuidedOpeningCommissioningMeasuredDuration + GuidedOpeningCommissioningBroodSealDuration + GuidedOpeningRoyalJellyCacheDuration
                + GuidedOpeningHygienePurgeManualDuration);
            int chapterTwoFast = Mathf.RoundToInt(
                GuidedBroodDiagnosisDuration + GuidedBroodVentilationDuration + GuidedBroodRapidDuration
                + GuidedBroodCircuitRoundTarget * (GuidedBroodCircuitNectarDuration + GuidedBroodCircuitThermalDuration)
                + GuidedBroodIncubationRoundTarget * (GuidedBroodIncubationSweepDuration + GuidedBroodIncubationHygieneDuration)
                + GuidedBroodIncubationFirstShiftDoctrineDuration + GuidedBroodEmergenceRationDuration
                + GuidedBroodWaxConsolidationQuickDuration);
            int chapterTwoSlow = Mathf.RoundToInt(
                GuidedBroodDiagnosisDuration + GuidedBroodWaxLiningDuration + GuidedBroodAttentiveDuration
                + GuidedBroodCircuitRoundTarget * (GuidedBroodCircuitPollenDuration + GuidedBroodCircuitNurseDuration)
                + GuidedBroodIncubationRoundTarget * (GuidedBroodIncubationPreciseDuration + GuidedBroodIncubationJellyDuration)
                + GuidedBroodIncubationResilienceDoctrineDuration + GuidedBroodReinforcedOperculumDuration
                + GuidedBroodWaxConsolidationThoroughDuration);
            int chapterThreeFast = Mathf.RoundToInt(
                GuidedWorkerUrgentCareDuration + GuidedWorkerReinforcedEmergenceDuration + localPreviewTrainingDuration
                + GuidedWorkerReserveTrialDuration + GuidedWorkerReserveFirstShiftDuration
                + GuidedWorkerCertificationRoundTarget * (GuidedWorkerCertificationReserveDuration + GuidedWorkerCertificationAutonomyDuration)
                + GuidedWorkerWorkshopHoneyDuration + GuidedWorkerCalibrationTemplateDuration);
            int chapterThreeSlow = Mathf.RoundToInt(
                GuidedWorkerMeasuredCareDuration + GuidedWorkerNaturalEmergenceDuration + localPreviewTrainingDuration
                + GuidedWorkerNurseryTrialDuration + GuidedWorkerNurseryFirstShiftDuration
                + GuidedWorkerCertificationRoundTarget * (GuidedWorkerCertificationNurseryDuration + GuidedWorkerCertificationMentorshipDuration)
                + GuidedWorkerWorkshopWaxDuration + GuidedWorkerApplicationToolkitDuration);
            int chapterFourFast = Mathf.RoundToInt(
                GuidedUpgradeAuditDuration + localPreviewUpgradeDuration + GuidedUpgradeCalibrationDuration + GuidedUpgradeReserveApplicationDuration
                + GuidedUpgradeOperationsRoundTarget * (GuidedUpgradeRecycledCombDuration + GuidedUpgradeReserveDeploymentDuration)
                + GuidedUpgradeLoadCertificationDuration + GuidedUpgradeCadenceDoctrineDuration + GuidedWorkshopDefenseShieldsDuration
                + GuidedUpgradeStockCheckQuickDuration);
            int chapterFourSlow = Mathf.RoundToInt(
                GuidedUpgradeAuditDuration + localPreviewUpgradeDuration + GuidedUpgradeCalibrationDuration + GuidedUpgradeNurseryApplicationDuration
                + GuidedUpgradeOperationsRoundTarget * (GuidedUpgradeFreshSheetDuration + GuidedUpgradeNurseryDeploymentDuration)
                + GuidedUpgradeThermalCertificationDuration + GuidedUpgradePrecisionDoctrineDuration + GuidedWorkshopDefenseLatticeDuration
                + GuidedUpgradeStockCheckThoroughDuration);
            int chapterFiveFast = Mathf.RoundToInt(
                GuidedDefenseScoutDuration + GuidedDefenseInterceptionDuration + GuidedDefenseCleanupDuration + GuidedDefensePatrolDuration
                + GuidedReadinessRoundTarget * (GuidedReadinessSurgeProductionDuration + GuidedReadinessNurseDuration + GuidedReadinessPatrolDuration)
                + GuidedDefenseScoutCorridorDuration + GuidedDefenseSunBeaconDuration
                + GuidedDefenseVigilanceQuickDuration);
            int chapterFiveSlow = Mathf.RoundToInt(
                GuidedDefenseScoutDuration + GuidedDefenseBarrierDuration + GuidedDefenseWatchDuration + GuidedDefensePropolisSealDuration
                + GuidedReadinessRoundTarget * (GuidedReadinessBalancedProductionDuration + GuidedReadinessGuardDuration + GuidedReadinessSealDuration)
                + GuidedDefenseGuardianEscortDuration + GuidedDefenseGuardedReturnDuration
                + GuidedDefenseVigilanceThoroughDuration);
            int actFast = chapterOneFast + chapterTwoFast + chapterThreeFast + chapterFourFast + chapterFiveFast;
            int actSlow = chapterOneSlow + chapterTwoSlow + chapterThreeSlow + chapterFourSlow + chapterFiveSlow;

            return new[]
            {
                "pacing_profile:opening_act_1",
                "pacing_measure:mandatory_timed_tasks_only",
                "pacing_excludes:reading_input_and_navigation_latency",
                "chapter_1_objectives:15",
                "chapter_1_decisions:12",
                "chapter_1_active_commissioning_checks:13",
                "chapter_1_manual_collections:7",
                "chapter_1_timed_seconds_fast:" + chapterOneFast.ToString(CultureInfo.InvariantCulture),
                "chapter_1_timed_seconds_slow:" + chapterOneSlow.ToString(CultureInfo.InvariantCulture),
                "chapter_2_objectives:16",
                "chapter_2_decisions:14",
                "chapter_2_active_vital_checks:3",
                "chapter_2_active_incubation_checks:6",
                "chapter_2_active_checks_total:13",
                "chapter_2_manual_collections:4",
                "chapter_2_timed_seconds_fast:" + chapterTwoFast.ToString(CultureInfo.InvariantCulture),
                "chapter_2_timed_seconds_slow:" + chapterTwoSlow.ToString(CultureInfo.InvariantCulture),
                "chapter_3_objectives:13",
                "chapter_3_decisions:10",
                "chapter_3_active_quality_checks:15",
                "chapter_3_manual_collections_max:5",
                "chapter_3_timed_seconds_fast:" + chapterThreeFast.ToString(CultureInfo.InvariantCulture),
                "chapter_3_timed_seconds_slow:" + chapterThreeSlow.ToString(CultureInfo.InvariantCulture),
                "chapter_4_objectives:14",
                "chapter_4_decisions:11",
                "chapter_4_active_structural_checks:16",
                "chapter_4_manual_collections:5",
                "chapter_4_timed_seconds_fast:" + chapterFourFast.ToString(CultureInfo.InvariantCulture),
