        public static string[] GetLiveHiveBeeMotionKindsForProof()
        {
            var motions = new HashSet<string>(StringComparer.Ordinal);
            for (int i = 0; i < LiveBeeAgents.Length; i++) motions.Add(LiveBeeAgents[i].Motion.ToString());
