        public static string[] StrategicPathTrialForProof(string token, int choiceIndex, bool portrait, float screenWidth, float screenHeight)
        {
            bool known = HiveStrategicPathCatalog.TryResolve(token, out HiveStrategicPathDefinition definition);
            Rect[] choices = StrategicPathTrialChoiceRectsForProof(portrait, screenWidth, screenHeight);
            float minimumTouch = choices.Length == 0 ? 0f : choices.Min(rect => Mathf.Min(rect.width, rect.height));
            bool choiceKnown = choiceIndex >= 0 && choiceIndex < 2;
            string result = !known || !choiceKnown
                ? "pending"
                : choiceIndex == definition.PreferredTrialChoice ? "identity_fit" : "tradeoff_exposed";
            return new[]
            {
                "strategic_path_trial_enabled:true",
                "strategic_path_trial_path:" + (known ? definition.Token : "none"),
                "strategic_path_trial_scenario:" + (known ? definition.TrialScenarioId : "none"),
                "strategic_path_trial_choice_count:2",
                "strategic_path_trial_preferred_choice:" + (known ? definition.PreferredTrialChoice.ToString(CultureInfo.InvariantCulture) : "none"),
                "strategic_path_trial_selected_choice:" + (choiceKnown ? choiceIndex.ToString(CultureInfo.InvariantCulture) : "none"),
                "strategic_path_trial_result:" + result,
                "strategic_path_trial_min_touch:" + minimumTouch.ToString("0", CultureInfo.InvariantCulture),
