        public static string[] CombatDoctrineForProof(string attackerToken, string defenderToken, bool portrait, float screenWidth, float screenHeight)
        {
            bool attackerKnown = HiveCombatDoctrineCatalog.TryResolve(attackerToken, out HiveCombatDoctrineDefinition attacker);
            bool defenderKnown = HiveCombatDoctrineCatalog.TryResolve(defenderToken, out HiveCombatDoctrineDefinition defender);
            HiveCombatDoctrineOutcome outcome = attackerKnown && defenderKnown
                ? HiveCombatDoctrineCatalog.Evaluate(attacker.Family, defender.Family)
                : HiveCombatDoctrineOutcome.Pending;
            Rect[] attackerRects = CombatDoctrineFamilyRectsForProof(true, portrait, screenWidth, screenHeight);
            Rect[] defenderRects = CombatDoctrineFamilyRectsForProof(false, portrait, screenWidth, screenHeight);
            float minimumTouch = attackerRects.Concat(defenderRects).Min(rect => Mathf.Min(rect.width, rect.height));
            return new[]
            {
                "combat_doctrine_enabled:true",
                "combat_doctrine_catalog_version:" + HiveCombatDoctrineCatalog.Version,
                "combat_doctrine_family_count:" + HiveCombatDoctrineCatalog.All.Count.ToString(CultureInfo.InvariantCulture),
                "combat_doctrine_tokens:" + string.Join(",", HiveCombatDoctrineCatalog.All.Select(item => item.Token)),
                "combat_doctrine_cycle:guardians>darters>wingrunners>guardians",
                "combat_doctrine_attacker:" + (attackerKnown ? attacker.Token : "none"),
                "combat_doctrine_defender:" + (defenderKnown ? defender.Token : "none"),
                "combat_doctrine_outcome:" + CombatDoctrineOutcomeId(outcome),
                "combat_doctrine_no_dominant_family:true",
                "combat_doctrine_numeric_coefficients_exposed:false",
                "combat_doctrine_battle_simulated:false",
                "combat_doctrine_result_guarantees_victory:false",
                "combat_doctrine_min_touch:" + minimumTouch.ToString("0", CultureInfo.InvariantCulture),
                "combat_doctrine_device_state:volatile_in_memory_only",
                "combat_doctrine_server_contract_status:http_catalog_feature_closed_not_connected",
                "combat_doctrine_official_selection_unchanged:true",
                "combat_doctrine_mutates_gameplay:false",
                "combat_doctrine_changes_protected_art:false"
            };
        }

        public static void OpenCombatDoctrineForProof(string attackerToken = "guardians", string defenderToken = null)
        {
            strategicPathPanelOpen = true;
            strategicPathTrialOpen = false;
            strategicPathTrialChoice = -1;
            combatDoctrineOpen = true;
            combatDoctrineAttackerIndex = CombatDoctrineIndex(attackerToken, 0);
            combatDoctrineDefenderIndex = string.IsNullOrEmpty(defenderToken) ? -1 : CombatDoctrineIndex(defenderToken, -1);
            playerMenuOpen = false;
        }

        public static void ChooseCombatDoctrineForProof(int attackerIndex, int defenderIndex)
        {
            if (!strategicPathPanelOpen || !combatDoctrineOpen) return;
            if (attackerIndex >= 0 && attackerIndex < HiveCombatDoctrineCatalog.All.Count)
                combatDoctrineAttackerIndex = attackerIndex;
            if (defenderIndex >= -1 && defenderIndex < HiveCombatDoctrineCatalog.All.Count)
