        private static RuntimeBridgePlayerFacingState BuildRuntimeBridgePlayerState()
        {
            switch (runtimeBridgeModeForProof)
            {
                case RuntimeBridgePlayerMode.OfflineFallback:
                    return new RuntimeBridgePlayerFacingState(RuntimeBridgePlayerMode.OfflineFallback, "Serveur indisponible", "Consulter demo", "Consultation seulement. Aucune progression, sauvegarde ou economie.", true, false, true);
                case RuntimeBridgePlayerMode.MaintenanceFuture:
                    return new RuntimeBridgePlayerFacingState(RuntimeBridgePlayerMode.MaintenanceFuture, "Maintenance future", "Consulter demo", "Connexion serveur requise pour jeu officiel.", true, false, true);
                case RuntimeBridgePlayerMode.ExpiredFuture:
                    return new RuntimeBridgePlayerFacingState(RuntimeBridgePlayerMode.ExpiredFuture, "Session future", "Consulter demo", "Compte non actif. Aucune sauvegarde officielle.", true, false, true);
                case RuntimeBridgePlayerMode.ServerPreparation:
                    return new RuntimeBridgePlayerFacingState(RuntimeBridgePlayerMode.ServerPreparation, "Serveur officiel futur", "Connexion serveur", "Voie officielle en preparation. Demo non officielle disponible.", true, false, true);
