        private static void EnsureMobileComfortPreferencesLoaded()
        {
            if (mobileComfortPreferencesLoaded) return;

            MobileComfortPreferencesReadResult result;
            try
            {
                result = MobileComfortPreferencesCodec.Read(mobileComfortPreferencesStore?.Read());
            }
            catch
            {
                result = new MobileComfortPreferencesReadResult(
                    MobileComfortPreferencesCodec.CreateDefault(),
                    MobileComfortPreferencesReadStatus.Corrupted);
            }

            mobileComfortPreferences = result.Preferences;
            productionReducedMotionForProof = mobileComfortPreferences.reducedMotion;
            mobileEconomyMode = mobileComfortPreferences.economyMode;
            miniChatWatchMode = MiniChatNormalizeWatchMode(mobileComfortPreferences.miniChatWatchMode);
            miniChatBlinkEnabled = mobileComfortPreferences.miniChatBlinkEnabled;
chatEmojiRecents = ChatEmojiParseRecents(mobileComfortPreferences.chatEmojiRecents);
            communicationPanelOpen = mobileComfortPreferences.miniChatOpen;
            missionsPinnedIds.Clear();
            missionsPinnedIds.AddRange(MissionParsePinnedIds(mobileComfortPreferences.pinnedMissionIds));
            missionsWidgetHidden = mobileComfortPreferences.pinnedMissionsWidgetHidden;
            mobileComfortPreferencesLoaded = true;
            mobileComfortPreferencesRestoreStatus = result.Status.ToString().ToLowerInvariant();
            BeeKingdom.Audio.AudioManager audio = BeeKingdom.Audio.AudioManager.EnsureInstance();
            audio.SetSoundEnabled(mobileComfortPreferences.soundEnabled);
            audio.SetMusicEnabled(mobileComfortPreferences.musicEnabled);

            if (result.Status != MobileComfortPreferencesReadStatus.Corrupted
                && result.Status != MobileComfortPreferencesReadStatus.UnsupportedVersion) return;

            try
            {
                mobileComfortPreferencesStore?.Delete();
                mobileComfortPreferencesStore?.Write(MobileComfortPreferencesCodec.Write(mobileComfortPreferences));
                mobileComfortPreferencesRestoreStatus += "_reset";
            }
            catch
            {
                mobileComfortPreferencesRestoreStatus += "_reset_failed";
            }
        }

