        // ---- Centre de Missions (Sprint-016) : persistance des missions echangees (jusqu'a 3)
        // et du caractere masque du widget. Meme mecanisme additif que le mini-chat : la version
        // du codec reste inchangee, les champs sont simplement initialises sur d'anciens JSON.
        private static string MissionJoinPinnedIds()
        {
            if (missionsPinnedIds.Count == 0) return string.Empty;
            return string.Join("|", missionsPinnedIds.ToArray());
        }

        private static string[] MissionParsePinnedIds(string raw)
        {
            if (string.IsNullOrWhiteSpace(raw)) return new string[0];
            string[] parts = raw.Split('|');
            string[] result = new string[parts.Length];
            int count = 0;
            for (int i = 0; i < parts.Length; i++)
            {
                string id = parts[i].Trim();
                if (string.IsNullOrWhiteSpace(id)) continue;
                if (MissionCatalog.Find(id) == null) continue;
                bool already = false;
                for (int j = 0; j < count; j++)
                {
                    if (string.Equals(result[j], id, StringComparison.Ordinal)) { already = true; break; }
                }
                if (already) continue;
                if (count >= MissionCatalog.MaxPinnedMissions) break;
                result[count++] = id;
            }
            string[] trimmed = new string[count];
            for (int i = 0; i < count; i++) trimmed[i] = result[i];
            return trimmed;
        }

        private static string MissionSerializePinnedIds()
        {
            EnsureMobileComfortPreferencesLoaded();
            return MissionJoinPinnedIds();
        }

