        private static string MiniChatLatestConversationId(string channelId)
        {
            EnsureChatData();
            string latestId = string.Empty;
            string latestTime = string.Empty;
            for (int i = 0; i < chatConversations.Count; i++)
            {
                ChatConversationData c = chatConversations[i];
                if (!string.Equals(c.Channel, channelId, StringComparison.Ordinal)) continue;
                if (string.IsNullOrEmpty(latestId)) latestId = c.Id;
                string time = ChatLastTimeFor(c.Id);
                if (!string.IsNullOrEmpty(time) && string.CompareOrdinal(time, latestTime) > 0)
                {
                    latestTime = time;
                    latestId = c.Id;
                }
            }
            return latestId;
        }

        private static List<ChatMessageData> MiniChatRecentMessages(string channelId, int max)
        {
            EnsureChatData();
            List<ChatMessageData> merged = new List<ChatMessageData>(max * 2);
            for (int i = 0; i < chatConversations.Count; i++)
            {
                ChatConversationData c = chatConversations[i];
                if (!string.Equals(c.Channel, channelId, StringComparison.Ordinal)) continue;
                List<ChatMessageData> messages = ChatMessagesFor(c.Id);
                int take = Mathf.Min(3, messages.Count);
                for (int m = messages.Count - take; m < messages.Count; m++) merged.Add(messages[m]);
            }
            if (merged.Count > 1)
            {
                merged.Sort(delegate (ChatMessageData a, ChatMessageData b)
                {
                    return string.CompareOrdinal(b.TimeLabel, a.TimeLabel);
                });
            }
            List<ChatMessageData> result = new List<ChatMessageData>(Mathf.Min(max, merged.Count));
            for (int i = 0; i < result.Capacity; i++) result.Add(merged[i]);
            return result;
        }

