        public static Vector2[] GetReferenceHotspotPolygonForProof(string hotspotId)
        {
            if (HiveVisualContourImportRuntime.TryGetVisualContour(hotspotId, out Vector2[] imported))
            {
                return imported;
            }

            if (HivePixelPerfectContourCalibration.TryGet(hotspotId, out HiveZoneContourDefinition calibrated))
            {
                return calibrated.VisualContour;
            }

            for (int i = 0; i < ReferenceHotspots.Length; i++)
            {
                if (ReferenceHotspots[i].HotspotId == hotspotId || ReferenceHotspots[i].CellId == hotspotId)
                {
                    return ReferenceHotspots[i].Polygon;
                }
            }

            return Array.Empty<Vector2>();
        }

        public static Vector2[] GetReferenceHotspotTactileHitboxForProof(string hotspotId)
        {
            if (HivePixelPerfectContourCalibration.TryGet(hotspotId, out HiveZoneContourDefinition calibrated))
            {
                return calibrated.TactileHitbox;
            }

            return GetReferenceHotspotPolygonForProof(hotspotId);
        }

        public static string[] PixelPerfectContourRuntimeForProof()
        {
            ReferenceHiveHotspot hotspot = FocusedReferenceHotspot();
            Vector2[] visual = GetReferenceVisualContour(hotspot);
            Vector2[] hitbox = GetReferenceTactileHitbox(hotspot);
            bool importedVisible = HiveVisualContourImportRuntime.TryGetVisualContour(hotspot.HotspotId, out _);
            bool separated = importedVisible && !ReferenceEquals(visual, hitbox) && visual.Length >= 3 && hitbox.Length >= 8;

            return new[]
            {
