        public static string[] VisualContourImportStatusForProof()
        {
            return HiveVisualContourImportRuntime.ImportStatusRows();
        }

        public static string[] PixelPerfectContourInventoryForProof()
        {
            return HivePixelPerfectContourCalibration.InventoryRows();
        }

        public static string PixelPerfectContourPriorityForProof(float x, float y)
        {
            return HivePixelPerfectContourCalibration.TryHit(new Vector2(x, y), out HiveZoneContourDefinition definition)
                ? definition.HotspotId + "|" + definition.PriorityBand + "|" + definition.Priority.ToString(CultureInfo.InvariantCulture)
                : "none";
        }

        public static void SetReferenceMobilePanForProof(float x, float y)
        {
            referenceMobilePan = new Vector2(x, y);
        }

        public static void SetReferenceHiveZoomForProof(float zoom)
        {
            referenceHiveZoom = Mathf.Clamp(zoom, IsPortraitLayout() ? 1.02f : 1.0f, IsPortraitLayout() ? 1.68f : 1.46f);
            referenceHiveTargetZoom = referenceHiveZoom;
        }

