            if (string.Equals(state, "stale_snapshot_conflict", StringComparison.OrdinalIgnoreCase))
            {
                localPreviewLoopMessage = "Conflit snapshot futur simule - aucun restore officiel";
                localPreviewLastActionStatus = "Conflit dev-only";
                localPreviewDisabledReason = "Conflit snapshot futur";
                ClearReservedCost();
                localPreviewRecoveryGuidance = "Recharger plus tard depuis l'autorite serveur future.";
                SetDevOnlyActionState("rejected", "stale_snapshot_conflict", "snapshot_restore", "T2_decision_rejected");
                localPreviewReconciliationStatus = "conflict_detected_dev_only_no_restore";
                return;
            }

            if (string.Equals(state, "gesture_pan_proof", StringComparison.OrdinalIgnoreCase))
            {
                SetReferenceHiveGestureTelemetryForProof("one-finger-pan", 1, 42f, -18f, 0f, 1.08f, 1.08f);
                referenceSelectionSuppressed = true;
                return;
            }

            if (string.Equals(state, "gesture_pinch_proof", StringComparison.OrdinalIgnoreCase))
            {
                SetReferenceHiveGestureTelemetryForProof("two-finger-pinch-zoom", 2, 0f, 0f, 0.038f, 1.22f, 1.18f);
                referenceSelectionSuppressed = true;
                return;
            }

            if (string.Equals(state, "ui_gesture_blocked", StringComparison.OrdinalIgnoreCase))
            {
                uiInputBlockedHiveGestureForProof = true;
                RecordReferenceGesture("ui-blocked-touch", 1, Vector2.zero, 0f);
                localPreviewLoopMessage = "Bouton UI: aucun pan/zoom ruche";
                localPreviewLastActionStatus = "UI fixe: geste bloque";
                localPreviewActionDecision = "accepted";
                localPreviewActionSource = "Simulation locale - UI fixe";
                localPreviewRecoveryGuidance = "Le bouton UI consomme le geste; la ruche ne pan/zoom pas.";
                referenceSelectionSuppressed = true;
                return;
            }

            if (string.Equals(state, "training_soldats_done", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(state, "training_gardiennes_done", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(state, "training_eclaireuses_done", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(state, "training_done", StringComparison.OrdinalIgnoreCase))
            {
                focusedReferenceHotspotId = "guard_post";
                focusedCellId = "cell--1-1";
                selectedLocalTroopType = TroopTypeFromProofState(state, "Eclaireuses");
                if (selectedLocalTroopType == "Gardiennes") localPreviewGuardians += 4;
                else if (selectedLocalTroopType == "Eclaireuses") localPreviewScouts += 6;
                else localPreviewSoldiers += 8;
                localPreviewHoney -= TrainingCost(selectedLocalTroopType).x;
                localPreviewPollen -= TrainingCost(selectedLocalTroopType).y;
                localPreviewLastCompletedTrainingType = selectedLocalTroopType;
                localPreviewArmyFeedbackText = "+" + TrainingBatchSize(selectedLocalTroopType) + " " + selectedLocalTroopType;
                localPreviewLoopMessage = "Troupes ajoutees en preview: " + selectedLocalTroopType;
                localPreviewLastActionStatus = "Completion locale: armee +";
                ReserveTrainingCost(selectedLocalTroopType);
                localPreviewRecoveryGuidance = "Troupes ajoutees localement; armee non persistante.";
                SetDevOnlyActionState("accepted", "none", "training", "T4_result_local");
            }
        }

        private static string TroopTypeFromProofState(string state, string fallback)
        {
            if (state != null && state.IndexOf("gardiennes", StringComparison.OrdinalIgnoreCase) >= 0) return "Gardiennes";
            if (state != null && state.IndexOf("eclaireuses", StringComparison.OrdinalIgnoreCase) >= 0) return "Eclaireuses";
            if (state != null && state.IndexOf("soldats", StringComparison.OrdinalIgnoreCase) >= 0) return "Soldats";
            return fallback;
        }

        private static void SetDevOnlyActionState(string decision, string rejectionCode, string commandKind, string timelineStep)
        {
            localPreviewActionDecision = string.IsNullOrWhiteSpace(decision) ? "idle" : decision;
            localPreviewActionRejectionCode = string.IsNullOrWhiteSpace(rejectionCode) ? "none" : rejectionCode;
            localPreviewActionTimelineStep = string.IsNullOrWhiteSpace(timelineStep) ? "T0_before_action" : timelineStep;
            localPreviewActionCommandId = "dev-only-" + (string.IsNullOrWhiteSpace(commandKind) ? "action" : commandKind) + "-" + localPreviewSnapshotRevision.ToString(CultureInfo.InvariantCulture);
            localPreviewSnapshotRevision++;
            localPreviewActionSource = ActionSourceForDecision(localPreviewActionDecision);
            if (!string.Equals(localPreviewActionRejectionCode, "none", StringComparison.OrdinalIgnoreCase))
            {
                localPreviewReconciliationStatus = "future_server_authority_required_for_" + localPreviewActionRejectionCode;
                localPreviewRecoveryGuidance = RecoveryGuidance(localPreviewActionRejectionCode);
            }
            else if (string.Equals(localPreviewActionDecision, "pending", StringComparison.OrdinalIgnoreCase))
            {
                localPreviewReconciliationStatus = "pending_local_preview_no_server_commit";
                localPreviewRecoveryGuidance = "Attends la fin du timer local.";
            }
            else
            {
                localPreviewReconciliationStatus = "local_preview_only_no_restore";
            }
        }

        private static void SetPlayerFacingActionState(string kind, string primary, string secondary)
        {
            localPreviewPlayerFacingKind = string.IsNullOrWhiteSpace(kind) ? "idle" : kind;
            localPreviewPlayerFacingPrimary = string.IsNullOrWhiteSpace(primary) ? "Pret - simulation locale" : primary;
            localPreviewPlayerFacingSecondary = string.IsNullOrWhiteSpace(secondary) ? "Choisis une action de preview." : secondary;
        }

        private static string ActionSourceForDecision(string decision)
        {
            if (string.Equals(decision, "pending", StringComparison.OrdinalIgnoreCase)) return "Pont dev-only local";
            if (string.Equals(decision, "accepted", StringComparison.OrdinalIgnoreCase)) return "Simulation locale acceptee";
            if (string.Equals(decision, "rejected", StringComparison.OrdinalIgnoreCase)) return "Refus local/dev-only";
            if (string.Equals(decision, "server_required", StringComparison.OrdinalIgnoreCase)) return "Serveur futur requis";
            return "Simulation locale";
        }

        private static void ClearReservedCost()
        {
            localPreviewReservedHoney = 0f;
            localPreviewReservedWax = 0f;
            localPreviewReservedPollen = 0f;
            localPreviewLastReservedCostText = "Aucun cout reserve";
        }

        private static void ReserveUpgradeCost(ReferenceHiveHotspot hotspot)
        {
            Vector2 cost = UpgradeCost(hotspot);
            localPreviewReservedHoney = cost.x;
            localPreviewReservedWax = cost.y;
            localPreviewReservedPollen = 0f;
            localPreviewLastReservedCostText = Mathf.RoundToInt(cost.x).ToString(CultureInfo.InvariantCulture)
                + " miel + " + Mathf.RoundToInt(cost.y).ToString(CultureInfo.InvariantCulture) + " cire reserves";
        }

        private static void ReserveTrainingCost(string troopType)
        {
            Vector2 cost = TrainingCost(troopType);
            localPreviewReservedHoney = cost.x;
            localPreviewReservedWax = 0f;
            localPreviewReservedPollen = cost.y;
            localPreviewLastReservedCostText = Mathf.RoundToInt(cost.x).ToString(CultureInfo.InvariantCulture)
                + " miel + " + Mathf.RoundToInt(cost.y).ToString(CultureInfo.InvariantCulture) + " pollen reserves";
        }

        private static string ActionDecisionMicrocopy()
        {
            if (string.Equals(localPreviewActionDecision, "accepted", StringComparison.OrdinalIgnoreCase)) return "Action acceptee - preview";
            if (string.Equals(localPreviewActionDecision, "rejected", StringComparison.OrdinalIgnoreCase)) return "Action refusee - " + RejectionMicrocopy(localPreviewActionRejectionCode);
            if (string.Equals(localPreviewActionDecision, "pending", StringComparison.OrdinalIgnoreCase)) return "En cours - timer local";
            if (string.Equals(localPreviewActionDecision, "server_required", StringComparison.OrdinalIgnoreCase)) return "Serveur requis - service futur";
            return "Pret - simulation locale";
        }

        private static string PlayerFacingActionHeader(string fallback)
        {
            return string.IsNullOrWhiteSpace(localPreviewPlayerFacingPrimary) ? fallback : localPreviewPlayerFacingPrimary;
        }

        private static string PlayerFacingActionSubline()
        {
            if (!string.IsNullOrWhiteSpace(localPreviewPlayerFacingSecondary))
            {
                return localPreviewPlayerFacingSecondary;
            }

            return ActionDecisionMicrocopy() + " | " + localPreviewActionSource;
        }

        private static string PlayerFacingActionFooter(string fallback)
        {
            if (string.Equals(localPreviewPlayerFacingKind, "refusal", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(localPreviewPlayerFacingKind, "disabled", StringComparison.OrdinalIgnoreCase))
            {
                return localPreviewRecoveryGuidance;
            }

            return string.IsNullOrWhiteSpace(fallback) ? ActionDecisionMicrocopy() : fallback;
        }

        private static string RejectionMicrocopy(string code)
        {
            if (string.Equals(code, "insufficient_resources", StringComparison.OrdinalIgnoreCase)) return "ressources insuffisantes";
            if (string.Equals(code, "already_running", StringComparison.OrdinalIgnoreCase)) return "deja en cours";
            if (string.Equals(code, "queue_busy", StringComparison.OrdinalIgnoreCase)) return "file occupee";
            if (string.Equals(code, "cap_reached", StringComparison.OrdinalIgnoreCase)) return "capacite atteinte";
            if (string.Equals(code, "stale_snapshot", StringComparison.OrdinalIgnoreCase)) return "snapshot obsolete";
            if (string.Equals(code, "stale_snapshot_conflict", StringComparison.OrdinalIgnoreCase)) return "conflit snapshot futur";
            if (string.Equals(code, "server_required", StringComparison.OrdinalIgnoreCase)) return "serveur requis";
            return "aucun refus";
        }

        private static string RecoveryGuidance(string code)
        {
            if (string.Equals(code, "insufficient_resources", StringComparison.OrdinalIgnoreCase)) return "Produis plus.";
            if (string.Equals(code, "already_running", StringComparison.OrdinalIgnoreCase)) return "Attends timer.";
            if (string.Equals(code, "queue_busy", StringComparison.OrdinalIgnoreCase)) return "Attends file.";
            if (string.Equals(code, "cap_reached", StringComparison.OrdinalIgnoreCase)) return "Monte capacite.";
            if (string.Equals(code, "stale_snapshot", StringComparison.OrdinalIgnoreCase)) return "Recharge futur.";
            if (string.Equals(code, "stale_snapshot_conflict", StringComparison.OrdinalIgnoreCase)) return "Relance plus tard.";
            if (string.Equals(code, "server_required", StringComparison.OrdinalIgnoreCase)) return "Serveur futur.";
            return "Autre action.";
        }

        private static string ActionFeedbackTimelineText()
        {
            return "T0 ressources > T1 tap > T2 decision > T3 cout reserve > T4 timer/file > T5 feedback > T6 completion > T7 armee/resultat > T8 refus/source > T9 non-claim/device";
        }

