        public static string[] PlayableHiveDeterministicChecksForProof()
        {
            SetPlayableHiveLoopProofState("idle");
            ReferenceHiveHotspot upgradeHotspot = FocusedReferenceHotspot();
            float honeyBeforeUpgrade = localPreviewHoney;
            float waxBeforeUpgrade = localPreviewWax;
            int levelBeforeUpgrade = EnsureLocalPreviewLevel(upgradeHotspot.HotspotId);
            Vector2 upgradeCost = UpgradeCost(upgradeHotspot);
            StartPreviewUpgrade(upgradeHotspot);
            StartPreviewUpgrade(upgradeHotspot);
            float honeyAfterDoubleUpgrade = localPreviewHoney;
            float waxAfterDoubleUpgrade = localPreviewWax;
            localPreviewBuildingLevels[upgradeHotspot.HotspotId] = levelBeforeUpgrade + 1;
            int levelAfterUpgrade = localPreviewBuildingLevels[upgradeHotspot.HotspotId];
            int upgradeCommits = localPreviewUpgradeCommitCount;
            int upgradeRepeatBlocks = localPreviewRepeatedUpgradeBlockedCount;

            SetPlayableHiveLoopProofState("idle");
            focusedReferenceHotspotId = "guard_post";
            focusedCellId = "cell--1-1";
            selectedLocalTroopType = "Soldats";
            float honeyBeforeTraining = localPreviewHoney;
            float pollenBeforeTraining = localPreviewPollen;
            int soldiersBefore = localPreviewSoldiers;
            Vector2 trainingCost = TrainingCost(selectedLocalTroopType);
            StartPreviewTraining(selectedLocalTroopType);
            StartPreviewTraining(selectedLocalTroopType);
            AddTroops(selectedLocalTroopType, 8);
            int soldiersAfter = localPreviewSoldiers;
            int trainingCommits = localPreviewTrainingCommitCount;
            int trainingRepeatBlocks = localPreviewRepeatedTrainingBlockedCount;

            return new[]
            {
                "deterministic_checks:true",
                "upgrade_cost_once:" + Approximately(honeyBeforeUpgrade - upgradeCost.x, honeyAfterDoubleUpgrade) + "," + Approximately(waxBeforeUpgrade - upgradeCost.y, waxAfterDoubleUpgrade),
                "upgrade_commit_count_after_double_input:" + upgradeCommits,
                "upgrade_repeat_blocked_count:" + upgradeRepeatBlocks,
                "upgrade_double_tap_guard:" + (upgradeCommits == 1 && upgradeRepeatBlocks >= 1),
                "level_increment_expected:" + (levelBeforeUpgrade + 1),
                "level_increment_applied:" + levelAfterUpgrade,
                "level_increment_once:" + (levelAfterUpgrade - levelBeforeUpgrade == 1),
                "training_cost_once:" + Approximately(honeyBeforeTraining - trainingCost.x, localPreviewHoney) + "," + Approximately(pollenBeforeTraining - trainingCost.y, localPreviewPollen),
                "training_commit_count_after_double_input:" + trainingCommits,
                "training_repeat_blocked_count:" + trainingRepeatBlocks,
                "training_double_tap_guard:" + (trainingCommits == 1 && trainingRepeatBlocks >= 1),
                "training_queue_delta:" + trainingCommits,
                "training_queue_consistent:" + (trainingCommits == 1 && !string.IsNullOrWhiteSpace(localPreviewTrainingTroopType)),
                "soldiers_before:" + soldiersBefore,
                "soldiers_after_preview_complete:" + soldiersAfter,
                "troop_increment_once:" + (soldiersAfter - soldiersBefore == 8),
                "resource_values_non_negative:" + (localPreviewHoney >= 0f && localPreviewWax >= 0f && localPreviewPollen >= 0f),
                "official_server_progression:false"
            };
        }

