        private static bool Approximately(float expected, float actual)
        {
            return Mathf.Abs(expected - actual) < 0.01f;
        }

        public static void SetReferenceHiveGestureTelemetryForProof(string mode, int touchCount, float panX, float panY, float pinchDelta, float targetZoom, float appliedZoom)
        {
            referenceHiveTargetZoom = Mathf.Clamp(targetZoom, IsPortraitLayout() ? 1.02f : 1.0f, IsPortraitLayout() ? 1.68f : 1.46f);
            referenceHiveZoom = Mathf.Clamp(appliedZoom, IsPortraitLayout() ? 1.02f : 1.0f, IsPortraitLayout() ? 1.68f : 1.46f);
            referenceSelectionSuppressed = mode != null && (mode.IndexOf("pan", StringComparison.OrdinalIgnoreCase) >= 0 || mode.IndexOf("pinch", StringComparison.OrdinalIgnoreCase) >= 0);
            RecordReferenceGesture(string.IsNullOrWhiteSpace(mode) ? "proof" : mode, touchCount, new Vector2(panX, panY), pinchDelta);
        }

