            splashAuthGateState = SplashAuthGateState.EnteredHive;
            referenceSurfaceMode = string.Equals(mode, "world", StringComparison.OrdinalIgnoreCase) ? ReferenceSurfaceMode.WorldBoundary : ReferenceSurfaceMode.Hive;
            if (referenceSurfaceMode == ReferenceSurfaceMode.Hive) activeMainMenuId = string.Empty;
        }

