        public static void SetSplashAuthGateForProof(string state)
        {
            string normalized = string.IsNullOrWhiteSpace(state) ? "splash" : state.Trim().ToLowerInvariant();
            accountSessionGate.ResetForLogoutOrPlayerChange();
            splashAuthUserName = BeeLocalization.Text("splash.create.demo_player_default", "Apiculteur");
            splashAuthLastRoute = "proof_" + normalized;
            SetSplashAuthMessage("splash.message.choose_entry", false);

            if (normalized == "login")
            {
                splashAuthGateState = SplashAuthGateState.Login;
                SetSplashAuthMessage("splash.message.official_unavailable", false);
            }
            else if (normalized == "login_empty")
            {
                splashAuthGateState = SplashAuthGateState.Login;
                splashAuthUserName = string.Empty;
                SetSplashAuthMessage("splash.message.official_unavailable", false);
            }
            else if (normalized == "create" || normalized == "create_account")
            {
                splashAuthGateState = SplashAuthGateState.CreateAccount;
                SetSplashAuthMessage("splash.message.local_profile", false);
            }
            else if (normalized == "created_local" || normalized == "account_created")
            {
                splashAuthGateState = SplashAuthGateState.CreateAccount;
                SetSplashAuthMessage("splash.message.local_profile_created", false, splashAuthUserName);
            }
            else if (normalized == "invalid_login")
            {
                splashAuthGateState = SplashAuthGateState.Login;
                splashAuthUserName = "Ab";
                SetSplashAuthMessage("splash.message.official_unavailable", true);
            }
            else if (normalized == "invalid_create")
            {
                splashAuthGateState = SplashAuthGateState.CreateAccount;
                splashAuthUserName = "Ab";
                SetSplashAuthMessage("splash.message.local_profile_name_required", true);
            }
            else if (normalized == "hive" || normalized == "entered_hive")
            {
                splashAuthGateState = SplashAuthGateState.EnteredHive;
                splashAuthLastRoute = "demo_local_proof_transition";
                SetSplashAuthMessage("splash.message.entered", false, splashAuthLastRoute);
                referenceSurfaceMode = ReferenceSurfaceMode.Hive;
            }
            else
            {
                splashAuthGateState = SplashAuthGateState.Splash;
            }
        }

        public static void SetAccountSessionReadinessForProof(string state)
        {
            string normalized = string.IsNullOrWhiteSpace(state) ? "not_configured" : state.Trim().ToLowerInvariant();
            accountSessionGate.ResetForLogoutOrPlayerChange();
            if (normalized == "checking")
            {
                accountSessionGate.Apply(AccountSessionReadinessSnapshot.Checking());
            }
            else if (normalized == "preparation" || normalized == "preparation_only")
            {
                accountSessionGate.Apply(AccountSessionReadinessSnapshot.FromServer(false, false, false, false, false));
            }
            else if (normalized == "server_ready" || normalized == "client_missing")
            {
                accountSessionGate.Apply(AccountSessionReadinessSnapshot.FromServer(true, true, true, true, true));
            }
            else if (normalized == "ready")
            {
                accountSessionGate.ConfigureTransport(true);
                accountSessionGate.Apply(AccountSessionReadinessSnapshot.FromServer(true, true, true, true, true));
            }
            else if (normalized == "unavailable")
            {
                accountSessionGate.Apply(AccountSessionReadinessSnapshot.Unavailable("auth.unavailable"));
            }
        }

