        public static void ConfigureMobileAccountSessionForRuntime(
            MobileAccountSessionClient client,
            Func<string, string, MobileAccountLoginRequest> loginRequestFactory,
            Func<string, string, string, GoogleLoginRequest> googleLoginRequestFactory = null,
            string googleOAuthClientId = null)
        {
            if (client == null) throw new ArgumentNullException(nameof(client));
            if (loginRequestFactory == null) throw new ArgumentNullException(nameof(loginRequestFactory));
            if (!ReferenceEquals(client.Gate, accountSessionGate))
                throw new ArgumentException("The mobile session client must use the presenter account gate.", nameof(client));

            mobileAccountSessionClient = client;
            mobileAccountLoginRequestFactory = loginRequestFactory;
            mobileGoogleLoginRequestFactory = googleLoginRequestFactory;
            mobileGoogleOAuthClientId = googleOAuthClientId ?? string.Empty;
            mobileAccountLoginTask = null;
            mobileAccountLogoutTask = null;
            mobileAccountPassword = string.Empty;
            mobileAccountQaPreview = false;
        }

