        public static void ResetMobileAccountSessionForProof()
        {
            MobileAccountSessionRuntimeBootstrap.CloseGameplayForSignedOutSession();
            mobileAccountSessionClient = null;
            mobileAccountLoginRequestFactory = null;
            mobileAccountLoginTask = null;
            mobileAccountLogoutTask = null;
            mobileAccountEmail = string.Empty;
            mobileAccountPassword = string.Empty;
            mobileAccountQaPreview = false;
            accountSessionGate.ResetForLogoutOrPlayerChange();
        }

        public static async Task CloseMobileAccountSessionForPlayerChangeAsync()
        {
            MobileAccountSessionClient client = mobileAccountSessionClient;
            mobileAccountEmail = string.Empty;
            mobileAccountPassword = string.Empty;
            mobileAccountLoginTask = null;
            mobileAccountLogoutTask = null;
            if (client == null) return;
            try
            {
                await LogoutMobileAccountAndPurgeGameplayAsync(client);
            }
            catch (MobileAccountSessionException)
            {
            }
            finally
            {
                MobileAccountSessionRuntimeBootstrap.CloseGameplayForSignedOutSession();
            }
        }

