        private static void SelectReferenceHotspot(string cellId, string label)
        {
            focusedCellId = cellId;
            referenceHotspotSelected = true;
            detailPanelClosed = false;
            referenceDetailInfoPopupOpen = false;
            lastTouchFeedback = "Selection ruche: " + label;
            referencePanelAnimationStartedAt = NowForUi();
            RefreshSelectionRims();
            // Le modele officiel (production, amelioration de batiment) n'est jamais
            // rafraichi tout seul avec le temps - sans ceci, un joueur qui rouvre le
            // meme panneau des minutes plus tard voit encore les valeurs figees de la
            // derniere lecture au lieu de la vraie quantite accumulee cote serveur.
            if (OfficialOfflineProductionConfigured()) offlineProductionController.Refresh();
            if (OfficialBuildingUpgradeConfigured()) buildingUpgradeController.Refresh();
        }

        private static void SelectReferenceHotspot(ReferenceHiveHotspot hotspot)
        {
            focusedReferenceHotspotId = hotspot.HotspotId;
            SelectReferenceHotspot(hotspot.CellId, LocalizedHotspotLabel(hotspot));
        }

        private static ReferenceHiveHotspot FocusedReferenceHotspot()
        {
            for (int i = 0; i < ReferenceHotspots.Length; i++)
            {
                if (ReferenceHotspots[i].HotspotId == focusedReferenceHotspotId) return ReferenceHotspots[i];
            }

            for (int i = 0; i < ReferenceHotspots.Length; i++)
            {
                if (ReferenceHotspots[i].CellId == focusedCellId) return ReferenceHotspots[i];
            }

            return ReferenceHotspots[0];
        }

        private static ReferenceHiveHotspot FindReferenceHotspot(string hotspotId)
        {
            for (int i = 0; i < ReferenceHotspots.Length; i++)
            {
                if (string.Equals(ReferenceHotspots[i].HotspotId, hotspotId, StringComparison.Ordinal)) return ReferenceHotspots[i];
            }

            return default;
        }

