        private static readonly HashSet<string> OfficialUpgradeBuildingIds = new HashSet<string>(StringComparer.Ordinal)
        {
            "nursery_cluster", "honey_storage", "guard_post", "defense_growth", "genetics_garden",
            "research_node", "warehouse_cells", "wax_workshop", "infirmary_grove", "academy_canopy",
            "hive_bank", "administration_core", "alliance_future_hall", "archives_honeyfall"
        };

        private static bool IsOfficialUpgradeBuilding(string hotspotId)
        {
            return OfficialUpgradeBuildingIds.Contains(hotspotId ?? string.Empty);
        }

        private static bool OfficialBuildingUpgradeActionEnabled(string hotspotId)
        {
            if (!IsOfficialUpgradeBuilding(hotspotId) || !OfficialBuildingUpgradeConfigured() ||
                buildingUpgradeController == null || buildingUpgradeController.IsBusy) return false;
            HiveBuildingUpgradeScreenModel model = OfficialBuildingUpgradeModel();
            if (model == null || model.State == HiveBuildingUpgradeScreenState.NotConfigured ||
                model.State == HiveBuildingUpgradeScreenState.Loading ||
                model.State == HiveBuildingUpgradeScreenState.Starting ||
                model.State == HiveBuildingUpgradeScreenState.Completing || model.IsReadOnly) return false;
            if (model.CanStart(hotspotId) || model.CanComplete(hotspotId)) return true;
            if (model.State == HiveBuildingUpgradeScreenState.Error) return true;
            return model.ActiveOperation != null &&
                string.Equals(model.ActiveOperation.BuildingKey, hotspotId, StringComparison.Ordinal) &&
                model.Remaining(buildingUpgradeController.Elapsed) <= TimeSpan.Zero;
        }

        private static string OfficialBuildingUpgradeActionLabel(string hotspotId)
        {
            HiveBuildingUpgradeScreenModel model = OfficialBuildingUpgradeModel();
            if (model == null || model.State == HiveBuildingUpgradeScreenState.NotConfigured)
                return BeeLocalization.Text("building_upgrade.action.unavailable", "Serveur requis");
            if (model.State == HiveBuildingUpgradeScreenState.Loading)
                return BeeLocalization.Text("building_upgrade.action.loading", "Synchronisation");
            if (model.State == HiveBuildingUpgradeScreenState.Starting)
                return BeeLocalization.Text("building_upgrade.action.starting", "Démarrage…");
            if (model.State == HiveBuildingUpgradeScreenState.Completing)
                return BeeLocalization.Text("building_upgrade.action.completing", "Validation…");
            if (model.IsReadOnly)
                return BeeLocalization.Text("building_upgrade.action.offline", "Lecture hors ligne");
            if (model.CanComplete(hotspotId))
                return model.State == HiveBuildingUpgradeScreenState.Error
                    ? BeeLocalization.Text("building_upgrade.action.retry", "Réessayer")
                    : BeeLocalization.Text("building_upgrade.action.complete", "Terminer");
            if (model.CanStart(hotspotId))
                return model.State == HiveBuildingUpgradeScreenState.Error
                    ? BeeLocalization.Text("building_upgrade.action.retry", "Réessayer")
                    : BeeLocalization.Text("common.upgrade", "Améliorer");
            if (model.State == HiveBuildingUpgradeScreenState.Error)
                return BeeLocalization.Text("building_upgrade.action.refresh", "Actualiser");
            if (model.ActiveOperation != null && string.Equals(model.ActiveOperation.BuildingKey, hotspotId, StringComparison.Ordinal))
            {
                TimeSpan remaining = model.Remaining(buildingUpgradeController.Elapsed);
                return remaining <= TimeSpan.Zero
                    ? BeeLocalization.Text("building_upgrade.action.refresh", "Actualiser")
                    : Mathf.RoundToInt((float)(model.Progress01(buildingUpgradeController.Elapsed) * 100.0)).ToString(CultureInfo.InvariantCulture) + " %";
            }
            if (model.ActiveOperation != null)
                return BeeLocalization.Text("building_upgrade.action.busy", "Occupé ailleurs");
            return model.OfferFor(hotspotId) == null
                ? BeeLocalization.Text("building_upgrade.action.unavailable", "Indisponible")
                : BeeLocalization.Text("common.upgrade", "Améliorer");
        }

        private static string OfficialBuildingUpgradeStatusText(string hotspotId)
        {
            HiveBuildingUpgradeScreenModel model = OfficialBuildingUpgradeModel();
            if (model == null || model.State == HiveBuildingUpgradeScreenState.NotConfigured)
                return BeeLocalization.Text("building_upgrade.status.not_configured", "Construction officielle non configurée");
            if (model.State == HiveBuildingUpgradeScreenState.Loading)
                return BeeLocalization.Text("building_upgrade.status.loading", "Synchronisation de la file de construction…");
            // Client optimiste (demande de Jeff) : Starting/Completing ne concernent qu'UN
            // batiment (celui que MutatingBuildingKey designe), meme si State est partage par les
            // 3 lignes - les deux autres batiments doivent continuer plus bas vers leur propre
            // etat (file d'attente / offre) au lieu d'afficher ce message generique.
            bool thisBuildingMutating = string.Equals(model.MutatingBuildingKey, hotspotId, StringComparison.Ordinal);
            if (model.State == HiveBuildingUpgradeScreenState.Starting && thisBuildingMutating)
                return BeeLocalization.Text("building_upgrade.status.starting", "Le serveur réserve les ressources et le créneau…");
            if (model.State == HiveBuildingUpgradeScreenState.Completing && thisBuildingMutating)
                return BeeLocalization.Text("building_upgrade.status.completing", "Le serveur valide le nouveau niveau…");
            if (model.IsReadOnly)
                return BeeLocalization.Text("building_upgrade.status.offline", "Hors ligne · dernière lecture protégée · actions bloquées");
            if (model.State == HiveBuildingUpgradeScreenState.Error)
                return OfficialBuildingUpgradeErrorText(model.ErrorCode);
            HiveBuildingUpgradeOperationModel operation = model.ActiveOperation;
            if (operation != null)
            {
                if (!string.Equals(operation.BuildingKey, hotspotId, StringComparison.Ordinal))
                    return BeeLocalization.Text("building_upgrade.status.busy", "Un autre bâtiment occupe la file de construction");
                if (operation.IsAwaitingCompletion)
                    return BeeLocalization.Text("building_upgrade.status.awaiting", "Travaux terminés · validation serveur requise");
                return string.Format(
                    CultureInfo.CurrentCulture,
                    BeeLocalization.Text("building_upgrade.status.running", "Niv. {0} → {1} · {2} restantes"),
                    operation.FromLevel,
                    operation.ToLevel,
                    FormatBuildingUpgradeDuration(model.Remaining(buildingUpgradeController.Elapsed)));
            }
            HiveBuildingUpgradeOfferModel offer = model.OfferFor(hotspotId);
            if (offer == null)
                return BeeLocalization.Text("building_upgrade.status.no_offer", "Aucune amélioration officielle disponible");
            string offerText = string.Format(
                CultureInfo.CurrentCulture,
                BeeLocalization.Text("building_upgrade.status.offer", "Niv. {0} → {1} · {2} · {3}"),
                offer.FromLevel,
                offer.ToLevel,
                OfficialBuildingUpgradeCostText(offer),
                FormatBuildingUpgradeDuration(offer.Duration));
            // Le bouton se desactive silencieusement quand les ressources manquent - sans ce
            // message, rien n'indique au joueur pourquoi il ne peut pas cliquer "Ameliorer".
            if (!model.CanStart(hotspotId))
                return BeeLocalization.Text("building_upgrade.status.insufficient", "Ressources insuffisantes · ") + offerText;
            return offerText;
        }

        private static string OfficialBuildingUpgradeCostText(HiveBuildingUpgradeOfferModel offer)
        {
            if (offer == null || offer.Costs.Count == 0)
                return BeeLocalization.Text("building_upgrade.cost.none", "Aucun coût communiqué");
            return string.Join(", ", offer.Costs.OrderBy(entry => entry.Key).Select(entry =>
                entry.Value.ToString(CultureInfo.CurrentCulture) + " " + OfficialBuildingUpgradeResourceLabel(entry.Key)).ToArray());
        }

        private static string OfficialBuildingUpgradeResourceLabel(string resourceKey)
        {
            if (string.Equals(resourceKey, "honey", StringComparison.Ordinal))
                return BeeLocalization.Text("resource.honey", "miel");
            if (string.Equals(resourceKey, "wax", StringComparison.Ordinal))
                return BeeLocalization.Text("resource.wax", "cire");
            if (string.Equals(resourceKey, "pollen", StringComparison.Ordinal))
                return BeeLocalization.Text("resource.pollen", "pollen");
            return resourceKey;
        }

        private static string FormatBuildingUpgradeDuration(TimeSpan duration)
        {
            double seconds = Math.Max(0d, duration.TotalSeconds);
            if (seconds >= 3600d)
                return string.Format(CultureInfo.CurrentCulture,
                    BeeLocalization.Text("building_upgrade.duration.hours", "{0} h {1} min"),
                    Math.Floor(seconds / 3600d), Math.Ceiling(seconds % 3600d / 60d));
            if (seconds >= 60d)
                return string.Format(CultureInfo.CurrentCulture,
                    BeeLocalization.Text("building_upgrade.duration.minutes", "{0} min {1} s"),
                    Math.Floor(seconds / 60d), Math.Ceiling(seconds % 60d));
            return string.Format(CultureInfo.CurrentCulture,
                BeeLocalization.Text("building_upgrade.duration.seconds", "{0} s"), Math.Ceiling(seconds));
        }

        private static string OfficialBuildingUpgradeErrorText(string errorCode)
        {
            if (string.Equals(errorCode, "network_unavailable", StringComparison.Ordinal))
                return BeeLocalization.Text("building_upgrade.error.network", "Réseau indisponible · réessaie avec la même demande sûre");
            if (string.Equals(errorCode, "session_required", StringComparison.Ordinal))
                return BeeLocalization.Text("building_upgrade.error.session", "Session officielle expirée · reconnecte-toi");
            if (string.Equals(errorCode, "invalid_response", StringComparison.Ordinal))
                return BeeLocalization.Text("building_upgrade.error.response", "Réponse serveur refusée · aucune progression locale appliquée");
            if (string.Equals(errorCode, "insufficient_resources", StringComparison.Ordinal))
                return BeeLocalization.Text("building_upgrade.error.resources", "Ressources insuffisantes · aucune dépense appliquée");
            if (string.Equals(errorCode, "construction_busy", StringComparison.Ordinal))
                return BeeLocalization.Text("building_upgrade.error.busy", "La file de construction est déjà occupée");
            if (string.Equals(errorCode, "revision_conflict", StringComparison.Ordinal) ||
                string.Equals(errorCode, "level_conflict", StringComparison.Ordinal))
                return BeeLocalization.Text("building_upgrade.error.conflict", "État modifié ailleurs · actualisation requise");
            if (string.Equals(errorCode, "not_ready", StringComparison.Ordinal))
                return BeeLocalization.Text("building_upgrade.error.not_ready", "Travaux encore en cours selon l’heure du serveur");
            if (string.Equals(errorCode, "idempotency_conflict", StringComparison.Ordinal))
                return BeeLocalization.Text("building_upgrade.error.idempotency", "Demande déjà utilisée pour une autre action · actualisation requise");
            if (string.Equals(errorCode, "server_unavailable", StringComparison.Ordinal))
                return BeeLocalization.Text("building_upgrade.error.unavailable", "Construction officielle fermée sur ce serveur");
            return BeeLocalization.Text("building_upgrade.error.generic", "Construction serveur indisponible · actualise avant de continuer");
        }

        private static void RunOfficialBuildingUpgradeAction(string hotspotId)
        {
            if (!OfficialBuildingUpgradeActionEnabled(hotspotId)) return;
            HiveBuildingUpgradeScreenModel model = OfficialBuildingUpgradeModel();
            if (model == null) return;
            if (model.CanComplete(hotspotId))
            {
                buildingUpgradeController.Complete();
                // M040-CL: real FTUE wiring, mirrors NotifyUpgradeStarted below - the tutorial now
                // requires the player to actually claim a finished upgrade, not just start one.
                try { BeeKingdom.Tutorial.TutorialGameplayNotifier.NotifyUpgradeCompleted(hotspotId); } catch {}
            }
            else if (model.CanStart(hotspotId))
            {
                buildingUpgradeController.Start(hotspotId);
                ChampionVoiceBarkController.BarkForBuildingLaunch(localPreviewAssignedChampionBeeIds);
                // M037B — real FTUE wiring: notify tutorial that a building upgrade was started (guard_post etc.)
                try { BeeKingdom.Tutorial.TutorialGameplayNotifier.NotifyUpgradeStarted(hotspotId); } catch {}
            }
            else buildingUpgradeController.Refresh();
            localPreviewLastActionStatus = OfficialBuildingUpgradeStatusText(hotspotId);
            BeginReferenceFeedbackPulse("preview");
        }

        // Valide directement une amelioration terminee quand le joueur tape sur le batiment
        // lui-meme (voir le badge dessine par DrawBuildingUpgradeReadyMarkers) - reutilise le
        // meme chemin que le bouton "Terminer" du panneau de detail, donc la meme resilience
        // aux conflits de revision (retry automatique deja gere par le controller).
        private static bool TryCompleteReadyBuildingUpgradeOnTap(string hotspotId)
        {
            if (!IsOfficialUpgradeBuilding(hotspotId) || !OfficialBuildingUpgradeConfigured()) return false;
            HiveBuildingUpgradeScreenModel model = OfficialBuildingUpgradeModel();
            if (model == null || !model.CanComplete(hotspotId)) return false;
            RunOfficialBuildingUpgradeAction(hotspotId);
            return true;
        }

        // Same "tap the building directly instead of opening its window" pattern as
        // TryCompleteReadyBuildingUpgradeOnTap, for the Barrack specifically (Jeff's
        // request) - a click on the Barrack claims ready troops immediately when there's
        // something to claim, only falling through to opening the full panel otherwise.
        public static bool TryClaimReadyTrainingOnTapForExternalHost()
        {
            if (!OfficialDoctrineRecruitmentConfigured()) return false;
            HiveDoctrineRecruitmentScreenModel model = OfficialDoctrineRecruitmentModel();
            if (model?.ActiveOperation == null || !model.CanClaim()) return false;
            RunOfficialDoctrineRecruitmentAction(model.ActiveOperation.Family);
            barrackClaimFeedbackStartedAt = NowForUi();
            return true;
        }

        // Pulsing "ready to claim" badge drawn directly on the Barrack building in HiveMap's
        // 3D world (caller projects world->screen, same as DrawPrerequisiteGlowForExternalHost/
        // the building-upgrade visual state bootstrap) - visual cue that a tap will claim
        // directly, matching TryClaimReadyTrainingOnTapForExternalHost's behavior.
        // glowSize is in screen pixels, computed by the caller from the camera's zoom - same
        // shared sizing approach as DrawManualProductionBeesForExternalHost (see its comment
        // for why), so the troop badge matches the resource badges' size/zoom behavior
        // exactly, per Jeff's request (2026-08-19).
        public static void DrawTrainingReadyBadgeForExternalHost(Rect buildingRect, float time, float glowSize)
        {
            if (!OfficialDoctrineRecruitmentConfigured()) return;
            HiveDoctrineRecruitmentScreenModel model = OfficialDoctrineRecruitmentModel();
            if (!IsTrainingReadyToClaimNow(model)) return;
            EnsureStyles();

            float pulse = 1f + Mathf.Sin(time * 3.4f) * 0.08f;
            float pulsedGlowSize = glowSize * pulse;
            // Icon is a fraction of the glow, not the full glow size - same 0.64 ratio as
            // DrawManualProductionBeesForExternalHost's icon/glow split. Missing this was why
            // the troop badge rendered much larger than the resource badges (Jeff, 2026-08-19).
            float size = pulsedGlowSize * 0.64f;
            Rect iconRect = new Rect(buildingRect.center.x - size * 0.5f, buildingRect.center.y - size * 0.5f, size, size);

            Color previous = GUI.color;
            GUI.color = new Color(1f, 0.92f, 0.58f, 0.78f);
            Rect glow = new Rect(buildingRect.center.x - pulsedGlowSize * 0.5f, buildingRect.center.y - pulsedGlowSize * 0.5f, pulsedGlowSize, pulsedGlowSize);
            GUI.DrawTexture(glow, GetPremiumTexture("selected-glow"), ScaleMode.ScaleToFit, true);
            GUI.color = Color.white;
            DrawGameIcon(iconRect, "troops-ready", Color.white);
            GUI.color = previous;
        }

        // Real-state query for "is the Barrack currently training" (running, not yet ready
        // to claim) - same condition DrawTrainingInProgressAnimationForExternalHost already
        // gates on, exposed separately so a bootstrap can drive a building-silhouette tint
        // (BuildingSelectionHighlight) without duplicating the model lookup. Mirrors
        // ActiveOfficialUpgradeHotspotIdForExternalHost's role for building upgrades.
        public static bool IsBarrackTrainingInProgressForExternalHost()
        {
            if (!OfficialDoctrineRecruitmentConfigured()) return false;
            HiveDoctrineRecruitmentScreenModel model = OfficialDoctrineRecruitmentModel();
            return model?.ActiveOperation != null && !IsTrainingReadyToClaimNow(model);
        }

        // Restrained blue/gold tint the Barrack breathes while training is running -
        // deliberately calmer than the gold "selected" or blue "upgrading" tints (lower
        // peak alpha, slower pulse) so it reads as ambient activity, not a UI alert.
        private static readonly Color TrainingTintColor = new Color(0.55f, 0.72f, 0.95f, 1f);

        public static Color TrainingHighlightTintColor
        {
            get { return TrainingTintColor; }
        }

        public static float TrainingHighlightPulseAlpha(float time)
        {
            if (productionReducedMotionForProof) return 0.24f;
            return 0.20f + (0.5f + 0.5f * Mathf.Sin(time * 1.05f)) * 0.16f; // breathes between ~0.20 and ~0.36
        }

        // Ambient "training in progress" animation on the Barrack itself - worker bees
        // circling the training area, a slower bee occasionally passing through the main
        // entrance, and a restrained glow at the entrance point. Same DrawRuntimeWorkerBee/
        // GetPremiumTexture primitives as the idle/ready swirl on the 3 production buildings
        // (DrawManualProductionBeesForExternalHost) and the ready badge - no new art or
        // particle systems, just the existing IMGUI toolkit reused. Jeff (2026-08-19): wanted
        // visible-but-subtle feedback that the Barrack is actively working while a troop
        // trains, distinct from (and not overlapping with) the ready-to-claim badge.
        public static void DrawTrainingInProgressAnimationForExternalHost(Rect buildingRect, float time)
        {
            if (buildingRect.width <= 0f || buildingRect.height <= 0f) return;
            if (!IsBarrackTrainingInProgressForExternalHost()) return;
            EnsureStyles();

            // Entrance point: bottom-center of the building's own rect - the buildings are
            // single ground-anchored quads (BuildingRuntimeViewBootstrap contact point), so
            // the bottom edge is where foot traffic visually reads as "coming and going."
            Vector2 entrance = new Vector2(buildingRect.center.x, buildingRect.yMax - buildingRect.height * 0.08f);

            float glowSize = Mathf.Clamp(buildingRect.width * 0.34f, 26f, 90f);
            float glowPulse = productionReducedMotionForProof ? 1f : 1f + Mathf.Sin(time * 1.6f) * 0.10f;
            Rect glowRect = new Rect(entrance.x - glowSize * glowPulse * 0.5f, entrance.y - glowSize * glowPulse * 0.5f, glowSize * glowPulse, glowSize * glowPulse);
            Color previousColor = GUI.color;
            // Restrained - roughly half the alpha of the "ready" badge glow, blue/gold blend
            // instead of pure amber so it never gets mistaken for "tap to collect."
            GUI.color = new Color(0.72f, 0.78f, 0.98f, 0.34f);
            GUI.DrawTexture(glowRect, GetPremiumTexture("selected-glow"), ScaleMode.ScaleToFit, true);
            GUI.color = previousColor;

            float radiusX = buildingRect.width * 0.50f;
            float radiusY = buildingRect.height * 0.22f;
            float beeSize = Mathf.Clamp(buildingRect.width * 0.16f, 18f, 46f);
            int beeCount = mobileEconomyMode ? 2 : 3;
            for (int i = 0; i < beeCount; i++)
            {
                float phase = i * (Mathf.PI * 2f / beeCount);
                float t = time * 1.15f + phase;
                Vector2 center = new Vector2(
                    buildingRect.center.x + Mathf.Cos(t) * radiusX,
                    buildingRect.y + buildingRect.height * 0.15f + Mathf.Sin(t) * radiusY);
                Rect beeRect = new Rect(center.x - beeSize * 0.5f, center.y - beeSize * 0.5f, beeSize, beeSize);
                DrawRuntimeWorkerBee(beeRect, phase, 0.80f, time, false);
            }

            DrawTrainingEntranceBeePass(buildingRect, entrance, time);
        }

        // One bee making an occasional pass through the entrance (outside the rect -> the
        // entrance point -> back out), separate from the training-area orbit above - reads
        // as "someone just went in/out" rather than constant circling. Active for roughly a
        // third of a 6-second cycle so it stays occasional, not continuous; skipped entirely
        // under reduced motion (same flag DrawTrainingClaimFeedbackForExternalHost respects).
        private static void DrawTrainingEntranceBeePass(Rect buildingRect, Vector2 entrance, float time)
        {
            if (productionReducedMotionForProof) return;

            const float cycle = 6f;
            float cycleT = Mathf.Repeat(time, cycle) / cycle;
            const float activeFraction = 0.34f;
            if (cycleT >= activeFraction) return;

            float passT = cycleT / activeFraction; // 0..1 across the visible portion of the cycle
            float eased = Mathf.Sin(passT * Mathf.PI); // 0 -> 1 -> 0, so it eases in and back out
            Vector2 outside = entrance + new Vector2(buildingRect.width * 0.62f, buildingRect.height * 0.05f);
            Vector2 pos = Vector2.Lerp(outside, entrance, passT);

            float beeSize = Mathf.Clamp(buildingRect.width * 0.13f, 14f, 36f);
            Rect beeRect = new Rect(pos.x - beeSize * 0.5f, pos.y - beeSize * 0.5f, beeSize, beeSize);
            DrawRuntimeWorkerBee(beeRect, 0.4f, eased * 0.75f, time, false);
        }

        // "+N" floating claim feedback (icon rising + tiny bee carrier, fading out) for the
        // Barrack, mirroring DrawManualCollectionFeedbackForExternalHost - see
        // barrackClaimFeedbackStartedAt for why this is set optimistically on tap rather than
        // waiting on the server response.
        public static void DrawTrainingClaimFeedbackForExternalHost(Rect buildingRect)
        {
            if (buildingRect.width <= 0f || buildingRect.height <= 0f) return;
            float elapsed = NowForUi() - barrackClaimFeedbackStartedAt;
            if (elapsed < 0f || elapsed > CollectionFeedbackSeconds) return;
            EnsureStyles();

            float t = Mathf.Clamp01(elapsed / CollectionFeedbackSeconds);
            float eased = 1f - Mathf.Pow(1f - t, 3f);
            Vector2 start = buildingRect.center;
            Vector2 end = start + new Vector2(0f, -Mathf.Max(90f, buildingRect.height * 0.6f));
            Vector2 center = productionReducedMotionForProof ? start + new Vector2(0f, -34f) : Vector2.Lerp(start, end, eased);
            center.x += productionReducedMotionForProof ? 0f : Mathf.Sin(t * Mathf.PI) * 18f;
            float alpha = 1f - Mathf.Clamp01((t - 0.58f) / 0.42f);
            float size = Mathf.Lerp(64f, 38f, eased);
            Rect iconRect = new Rect(center.x - size * 0.5f, center.y - size * 0.5f, size, size);

            Color previous = GUI.color;
            GUI.color = new Color(1f, 1f, 1f, alpha);
            GUI.DrawTexture(new Rect(iconRect.x - 12f, iconRect.y - 12f, iconRect.width + 24f, iconRect.height + 24f), GetPremiumTexture("selected-glow"), ScaleMode.ScaleToFit, true);
            DrawGameIcon(iconRect, "troops-ready", new Color(1f, 1f, 1f, alpha));
            GUI.color = previous;

            float carrierSize = 34f;
            Vector2 carrierCenter = center + new Vector2(size * 0.58f, size * 0.10f);
            Rect carrierRect = new Rect(carrierCenter.x - carrierSize * 0.5f, carrierCenter.y - carrierSize * 0.5f, carrierSize, carrierSize);
            DrawRuntimeWorkerBee(carrierRect, 0.18f, alpha * 0.94f, NowForUi(), false);
        }

        // M016E-CL: the official Research overlay freezes the Unity Editor on open, so
        // LivingHiveResearchHost.OnBuildingClicked routes unconditionally to the local-preview
        // window regardless of session availability. Every other Official*Research* consumer
        // (queue sidebar, ready markers, hotspot badges) must agree with that, or they show
        // stale/empty official state while the player is actually using the local-preview
        // queue. Force this false until the official overlay is re-enabled.
        private static bool OfficialResearchConfigured()
        {
            // M040-CL: this was hardcoded to false (real check commented out below), which
            // silently forced every Research panel render through the local-preview fallback
            // branch inside DrawResearchMenuPanel - never reaching DrawOfficialResearchMenuPanel,
            // which is where the real FTUE target registration (TargetResearchStartButton) and
            // the real catalog display names ("Rayons tempérés", not the fallback's own naming)
            // live. Restored to the real check now that the M016E freeze workaround has been
            // lifted and the official Research controller is confirmed reachable.
            return researchController != null && researchController.IsConfigured;
        }

        private static bool OfficialHiveStockConfigured()
        {
            return hiveStockController != null && hiveStockController.IsConfigured;
        }

        private static HiveStockScreenModel OfficialHiveStockModel()
        {
            return hiveStockController == null ? null : hiveStockController.Model;
        }

        private static bool OfficialDailyRoundConfigured()
        {
            return dailyRoundController != null && dailyRoundController.IsConfigured;
        }

        private static HiveDailyRoundScreenModel OfficialDailyRoundModel()
        {
            return dailyRoundController == null ? null : dailyRoundController.Model;
        }

        private static HiveResearchScreenModel OfficialResearchModel()
        {
            return researchController == null ? null : researchController.Model;
        }

        private static bool OfficialResearchActionEnabled(string researchId)
        {
            if (!OfficialResearchConfigured() || researchController == null || researchController.IsBusy) return false;
            HiveResearchScreenModel model = OfficialResearchModel();
            if (model == null || model.State == HiveResearchScreenState.NotConfigured ||
                model.State == HiveResearchScreenState.Loading ||
                model.State == HiveResearchScreenState.Starting || model.State == HiveResearchScreenState.Completing ||
                model.IsReadOnly) return false;
            if (!string.IsNullOrWhiteSpace(OfficialResearchShortageResource(researchId))) return true;
            if (model.CanStart(researchId) || model.CanComplete(researchId)) return true;
            if (model.State == HiveResearchScreenState.Error) return true;
            return model.ActiveOperation != null &&
                string.Equals(model.ActiveOperation.ResearchId, researchId, StringComparison.Ordinal) &&
                model.Remaining(researchController.Elapsed) <= TimeSpan.Zero;
        }

        private static string OfficialResearchActionLabel(string researchId)
        {
            HiveResearchScreenModel model = OfficialResearchModel();
            if (model == null || model.State == HiveResearchScreenState.NotConfigured)
                return BeeLocalization.Text("research.official.action.unavailable", "Serveur requis");
            if (model.State == HiveResearchScreenState.Loading)
                return BeeLocalization.Text("research.official.action.loading", "Synchronisation");
            // Ne montrer "Démarrage…"/"Validation…" que sur l'étude reellement en train de
            // muter (demande de Jeff, 2026-07-31) : les autres offres gardent leur libelle
            // habituel pendant qu'une seule etude est en vol vers le serveur.
            if (model.IsMutating(researchId))
                return model.State == HiveResearchScreenState.Starting
                    ? BeeLocalization.Text("research.official.action.starting", "Démarrage…")
                    : BeeLocalization.Text("research.official.action.completing", "Validation…");
            if (model.IsReadOnly)
                return BeeLocalization.Text("research.official.action.offline", "Lecture hors ligne");
            if (!string.IsNullOrWhiteSpace(OfficialResearchShortageResource(researchId)))
                return BeeLocalization.Text("research.source.button", "Source");
            if (model.IsCompleted(researchId))
                return BeeLocalization.Text("research.button.completed", "Terminée");
            if (model.CanComplete(researchId))
                return model.State == HiveResearchScreenState.Error
                    ? BeeLocalization.Text("research.official.action.retry", "Réessayer")
                    : BeeLocalization.Text("research.official.action.complete", "Terminer");
            if (model.CanStart(researchId))
                return model.State == HiveResearchScreenState.Error
                    ? BeeLocalization.Text("research.official.action.retry", "Réessayer")
                    : BeeLocalization.Text("research.button.start", "Lancer");
            if (model.State == HiveResearchScreenState.Error)
                return BeeLocalization.Text("research.official.action.refresh", "Actualiser");
            if (model.ActiveOperation != null &&
                string.Equals(model.ActiveOperation.ResearchId, researchId, StringComparison.Ordinal))
            {
                TimeSpan remaining = model.Remaining(researchController.Elapsed);
                return remaining <= TimeSpan.Zero
                    ? BeeLocalization.Text("research.official.action.refresh", "Actualiser")
                    : FormatBuildingUpgradeDuration(remaining);
            }
            return model.OfferFor(researchId) == null
                ? BeeLocalization.Text("research.official.action.unavailable", "Indisponible")
                : BeeLocalization.Text("research.button.start", "Lancer");
        }

        private static string OfficialResearchStatusText(string researchId)
        {
            HiveResearchScreenModel model = OfficialResearchModel();
            if (model == null || model.State == HiveResearchScreenState.NotConfigured)
                return BeeLocalization.Text("research.official.status.not_configured", "Recherche officielle non configurée");
            if (model.State == HiveResearchScreenState.Loading)
                return BeeLocalization.Text("research.official.status.loading", "Synchronisation de la file de recherche…");
            // Meme principe que le libelle du bouton : seule l'etude ciblee affiche le texte de
            // mutation, les autres offres restent lisibles (cout, prerequis, effet) pendant ce temps.
            if (model.IsMutating(researchId))
                return model.State == HiveResearchScreenState.Starting
                    ? BeeLocalization.Text("research.official.status.starting", "Le serveur réserve les ressources et la file…")
                    : BeeLocalization.Text("research.official.status.completing", "Le serveur applique l'effet persistant…");
            if (model.IsReadOnly)
                return BeeLocalization.Text("research.official.status.offline", "Hors ligne · dernière lecture protégée · actions bloquées");
            if (model.State == HiveResearchScreenState.Error)
                return OfficialResearchErrorText(model.ErrorCode);
            if (model.IsCompleted(researchId))
                return string.Format(
                    CultureInfo.CurrentCulture,
                    BeeLocalization.Text("research.official.status.completed", "Terminée · {0}"),
                    OfficialResearchEffectText(researchId));

            HiveResearchOperationModel operation = model.ActiveOperation;
            if (operation != null)
            {
                if (!string.Equals(operation.ResearchId, researchId, StringComparison.Ordinal))
                    return BeeLocalization.Text("research.official.status.busy", "Une autre étude occupe la file de recherche");
                if (operation.IsAwaitingCompletion)
                    return BeeLocalization.Text("research.official.status.awaiting", "Étude terminée · validation serveur requise");
                return string.Format(
                    CultureInfo.CurrentCulture,
                    BeeLocalization.Text("research.official.status.running", "En cours · {0} restantes"),
                    FormatBuildingUpgradeDuration(model.Remaining(researchController.Elapsed)));
            }

            HiveResearchOfferModel offer = model.OfferFor(researchId);
            if (offer == null)
                return BeeLocalization.Text("research.official.status.no_offer", "Aucune offre officielle disponible");
            if (!model.PrerequisitesMet(researchId))
                return string.Format(CultureInfo.CurrentCulture,
                    BeeLocalization.Text("research.official.status.prerequisite", "Prérequis manquant · {0}"),
                    model.MissingPrerequisite(researchId));
            string shortage = OfficialResearchShortageResource(researchId);
            if (!string.IsNullOrWhiteSpace(shortage))
                return OfficialResearchShortageText(researchId, shortage);
            return string.Format(
                CultureInfo.CurrentCulture,
                BeeLocalization.Text("research.official.status.offer", "{0} · {1} · {2}"),
                OfficialResearchCostText(offer),
                FormatBuildingUpgradeDuration(offer.Duration),
                OfficialResearchEffectText(researchId));
        }

        private static string OfficialResearchShortageResource(string researchId)
        {
            HiveResearchScreenModel model = OfficialResearchModel();
            if (model == null || model.State != HiveResearchScreenState.Ready || model.IsReadOnly)
                return string.Empty;
            string resource = model.ShortageResource(researchId);
            return string.Equals(resource, "honey", StringComparison.Ordinal) ||
                string.Equals(resource, "pollen", StringComparison.Ordinal) ? resource : string.Empty;
        }

        private static string OfficialResearchShortageText(string researchId, string resource)
        {
            HiveResearchScreenModel model = OfficialResearchModel();
            long missing = model == null ? 0L : model.MissingAmount(researchId, resource);
            string key = string.Equals(resource, "pollen", StringComparison.Ordinal)
                ? "research.reason.pollen_missing"
                : "research.reason.honey_missing";
            string fallback = string.Equals(resource, "pollen", StringComparison.Ordinal)
                ? "Pollen manquant : {0}"
                : "Miel manquant : {0}";
            return string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text(key, fallback), missing);
        }

        private static string OfficialResearchCostText(HiveResearchOfferModel offer)
        {
            if (offer == null || offer.Costs.Count == 0)
                return BeeLocalization.Text("research.official.cost.none", "Aucun coût communiqué");
            return string.Join(", ", offer.Costs.OrderBy(item => item.Key, StringComparer.Ordinal).Select(item =>
                item.Value.ToString(CultureInfo.CurrentCulture) + " " + OfficialBuildingUpgradeResourceLabel(item.Key)).ToArray());
        }

        private static string OfficialResearchEffectText(string researchId)
        {
            HiveResearchScreenModel model = OfficialResearchModel();
            HiveResearchOfferModel offer = model == null ? null : model.OfferFor(researchId);
            HiveResearchCompletionModel completed = model == null ? null : model.Completed.SingleOrDefault(item =>
                string.Equals(item.ResearchId, researchId, StringComparison.Ordinal));
            List<string> parts = new List<string>(6);
            AppendResearchEffectPart(parts, "research.official.effect.honey", "+{0}% production miel",
                offer?.HoneyProductionBonusBps ?? completed?.HoneyProductionBonusBps ?? 0);
            AppendResearchEffectPart(parts, "research.official.effect.wax_production", "+{0}% production cire",
                offer?.WaxProductionBonusBps ?? completed?.WaxProductionBonusBps ?? 0);
            AppendResearchEffectPart(parts, "research.official.effect.wax", "+{0}% capacité cire",
                offer?.WaxCapacityBonusBps ?? completed?.WaxCapacityBonusBps ?? 0);
            AppendResearchEffectPart(parts, "research.official.effect.pollen_production", "+{0}% production pollen",
                offer?.PollenProductionBonusBps ?? completed?.PollenProductionBonusBps ?? 0);
            AppendResearchEffectPart(parts, "research.official.effect.pollen_capacity", "+{0}% capacité pollen",
                offer?.PollenCapacityBonusBps ?? completed?.PollenCapacityBonusBps ?? 0);
            AppendResearchEffectPart(parts, "research.official.effect.global_capacity", "+{0}% capacité globale",
                offer?.GlobalCapacityBonusBps ?? completed?.GlobalCapacityBonusBps ?? 0);
            return parts.Count == 0
                ? BeeLocalization.Text("research.official.effect.pending", "Effet confirmé par le serveur à la complétion")
                : string.Join(" · ", parts) + " · serveur";
        }

        private static void AppendResearchEffectPart(List<string> parts, string key, string fallback, int bps)
        {
            if (bps <= 0) return;
            parts.Add(string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text(key, fallback),
                (bps / 100d).ToString("0.##", CultureInfo.CurrentCulture)));
        }

        private static string OfficialResearchErrorText(string errorCode)
        {
            if (string.Equals(errorCode, "network_unavailable", StringComparison.Ordinal))
                return BeeLocalization.Text("research.official.error.network", "Réseau indisponible · réessaie avec la même demande sûre");
            if (string.Equals(errorCode, "session_required", StringComparison.Ordinal))
                return BeeLocalization.Text("research.official.error.session", "Session officielle expirée · reconnecte-toi");
            if (string.Equals(errorCode, "invalid_response", StringComparison.Ordinal))
                return BeeLocalization.Text("research.official.error.response", "Réponse serveur refusée · aucun effet local appliqué");
            if (string.Equals(errorCode, "insufficient_resources", StringComparison.Ordinal))
                return BeeLocalization.Text("research.official.error.resources", "Ressources insuffisantes · aucune dépense appliquée");
            if (string.Equals(errorCode, "research_busy", StringComparison.Ordinal))
                return BeeLocalization.Text("research.official.error.busy", "La file de recherche est déjà occupée");
            if (string.Equals(errorCode, "prerequisite_missing", StringComparison.Ordinal))
                return BeeLocalization.Text("research.official.error.prerequisite", "Prérequis manquant · termine d'abord l'étude précédente");
            if (string.Equals(errorCode, "already_completed", StringComparison.Ordinal))
                return BeeLocalization.Text("research.official.error.completed", "Cette étude est déjà terminée");
            if (string.Equals(errorCode, "revision_conflict", StringComparison.Ordinal))
                return BeeLocalization.Text("research.official.error.conflict", "État modifié ailleurs · actualisation requise");
            if (string.Equals(errorCode, "not_ready", StringComparison.Ordinal))
                return BeeLocalization.Text("research.official.error.not_ready", "Étude encore en cours selon l'heure du serveur");
            if (string.Equals(errorCode, "idempotency_conflict", StringComparison.Ordinal))
                return BeeLocalization.Text("research.official.error.idempotency", "Demande déjà utilisée pour une autre action · actualisation requise");
            if (string.Equals(errorCode, "server_unavailable", StringComparison.Ordinal))
                return BeeLocalization.Text("research.official.error.unavailable", "Recherche officielle fermée sur ce serveur");
            return BeeLocalization.Text("research.official.error.generic", "Recherche serveur indisponible · actualise avant de continuer");
        }

        private static void RunOfficialResearchAction(string researchId)
        {
            if (!OfficialResearchActionEnabled(researchId)) return;
            string source = OfficialResearchShortageResource(researchId);
            if (!string.IsNullOrWhiteSpace(source))
            {
                NavigateToResearchResourceSource(source);
                return;
            }
            HiveResearchScreenModel model = OfficialResearchModel();
            if (model == null) return;
            if (model.CanComplete(researchId)) researchController.Complete();
            else if (model.CanStart(researchId)) researchController.Start(researchId);
            else researchController.Refresh();
            localPreviewLastActionStatus = OfficialResearchStatusText(researchId);
            BeginReferenceFeedbackPulse("preview");
        }

        // M040-CL: the queue sidebar's periodic researchController.Refresh() (see
        // DrawQueueSidebarForExternalHost) deliberately stops while the Research overlay
        // itself is open (it's part of "any overlay open" there) - which meant the one poll
        // that flips a finished operation's ActiveOperation.Status from "running" to
        // "awaiting_completion" never ran while a player was actually looking at the window
        // watching the timer hit zero, leaving the button stuck on "Actualiser" forever
        // instead of switching to "Terminer" like the building upgrade card does. Reuses the
        // same 5s cadence/field as the sidebar poll (safe - only one of the two ever runs at
        // a time, since the sidebar skips itself whenever this overlay is open).
        public static void RefreshResearchIfOverlayOpenAndDue()
        {
            if (!ResearchOverlayOpenForExternalHost) return;
            if (!OfficialResearchConfigured() || researchController == null || researchController.IsBusy) return;
            if (NowForUi() - officialResearchQueueLastLiveRefreshAt <= 5f) return;
            officialResearchQueueLastLiveRefreshAt = NowForUi();
            researchController.RefreshQuietly();
        }

