        private static string OfficialProductionStatusText(string hotspotId = null)
        {
            HiveOfflineProductionScreenModel model = OfficialOfflineProductionModel();
            if (model == null || model.State == HiveOfflineProductionScreenState.NotConfigured)
                return BeeLocalization.Text("production.official.not_configured", "Production officielle non configurée");
            if (model.State == HiveOfflineProductionScreenState.Loading)
                return BeeLocalization.Text("production.official.loading", "Synchronisation de la production…");
            if (model.State == HiveOfflineProductionScreenState.Collecting)
                return BeeLocalization.Text("production.official.collecting", "Collecte serveur en cours…");
            if (model.State == HiveOfflineProductionScreenState.OfflineReadOnly)
                return BeeLocalization.Text("production.official.offline_read_only", "Hors ligne · dernière lecture protégée · collecte indisponible");
            if (model.State == HiveOfflineProductionScreenState.Error)
                return OfficialProductionErrorText(model.ErrorCode);
            // Sans ce controle, le panneau affichait "Production synchronisee" meme quand la
            // reserve du batiment courant etait deja pleine - le joueur cliquait "Collecter" sans
            // jamais comprendre pourquoi rien ne se passait.
            HiveOfflineProductionLineModel line = hotspotId == null ? null : model.FindLine(hotspotId);
            if (line != null && line.IsResourceCapacityFull)
                return BeeLocalization.Text("production.official.error.capacity", "Réserve pleine · dépense avant de collecter");
            return BeeLocalization.Text("production.official.ready", "Production synchronisée avec le serveur");
        }

