        private static float PendingManualProduction(string hotspotId)
        {
            if (string.Equals(hotspotId, "honey_storage", StringComparison.Ordinal)) return localPreviewPendingHoney;
            if (string.Equals(hotspotId, "wax_workshop", StringComparison.Ordinal)) return localPreviewPendingWax;
            if (string.Equals(hotspotId, "warehouse_cells", StringComparison.Ordinal)) return localPreviewPendingPollen;
            return 0f;
        }

        private static float PendingManualProductionCapacity(string hotspotId)
        {
            if (string.Equals(hotspotId, "honey_storage", StringComparison.Ordinal)) return PendingHoneyCapacity;
            if (string.Equals(hotspotId, "wax_workshop", StringComparison.Ordinal)) return PendingWaxCapacity * (1f + localPreviewWaxCapacityBonus + localPreviewResearchWaxCapacityBonus);
            if (string.Equals(hotspotId, "warehouse_cells", StringComparison.Ordinal)) return PendingPollenCapacity;
            return 0f;
        }

        private static float ManualProductionPerHour(string hotspotId)
        {
            float championBeeBonus = ChampionBeeProductionBonusPercent() / 100f;

            if (string.Equals(hotspotId, "honey_storage", StringComparison.Ordinal))
            {
                int levelDelta = Mathf.Max(0, EnsureLocalPreviewLevel(hotspotId) - 25);
                return 2540f * (1f + levelDelta * 0.04f + localPreviewHoneyProductionBonus + localPreviewResearchHoneyProductionBonus + championBeeBonus);
            }

            if (string.Equals(hotspotId, "wax_workshop", StringComparison.Ordinal))
            {
                int levelDelta = Mathf.Max(0, EnsureLocalPreviewLevel(hotspotId) - 22);
                return 1180f * (1f + levelDelta * 0.04f + localPreviewWaxProductionBonus + championBeeBonus);
            }

            if (string.Equals(hotspotId, "warehouse_cells", StringComparison.Ordinal))
            {
                int levelDelta = Mathf.Max(0, EnsureLocalPreviewLevel(hotspotId) - 22);
                return 1680f * (1f + levelDelta * 0.04f + championBeeBonus);
            }

            return 0f;
        }

        private static ManualProductionForecast ManualProductionForecastFor(string hotspotId)
        {
            return ManualProductionForecast.Calculate(
                DisplayedPendingManualProduction(hotspotId),
                DisplayedManualProductionCapacity(hotspotId),
                DisplayedManualProductionPerHour(hotspotId));
        }

        private static string FormatManualProductionForecastDuration(double seconds)
        {
            int totalMinutes = Math.Max(1, (int)Math.Ceiling(Math.Max(0d, seconds) / 60d));
            if (totalMinutes >= 1440)
            {
                int days = totalMinutes / 1440;
                int hours = (totalMinutes % 1440) / 60;
                return string.Format(
                    CultureInfo.CurrentCulture,
                    BeeLocalization.Text("ledger.forecast.duration.day_hour", "{0} j {1} h"),
                    days,
                    hours);
            }
            if (totalMinutes >= 60)
            {
                int hours = totalMinutes / 60;
                int minutes = totalMinutes % 60;
                return string.Format(
                    CultureInfo.CurrentCulture,
                    BeeLocalization.Text("ledger.forecast.duration.hour_minute", "{0} h {1} min"),
                    hours,
                    minutes);
            }
            return string.Format(
                CultureInfo.CurrentCulture,
                BeeLocalization.Text("ledger.forecast.duration.minute", "{0} min"),
                totalMinutes);
        }

        private static string ManualProductionForecastStatus(ManualProductionForecast forecast)
        {
            if (forecast == null || forecast.State == ManualProductionForecastState.Unavailable)
                return BeeLocalization.Text("ledger.forecast.unavailable", "Prévision indisponible");
            if (forecast.State == ManualProductionForecastState.Full)
                return BeeLocalization.Text("ledger.forecast.full", "Plein");
            return string.Format(
                CultureInfo.CurrentCulture,
                BeeLocalization.Text("ledger.forecast.full_in", "Plein dans {0}"),
                FormatManualProductionForecastDuration(forecast.SecondsUntilFull));
        }

        private static string EarliestManualProductionForecastSummary()
        {
            ManualProductionForecast[] forecasts =
            {
                ManualProductionForecastFor("honey_storage"),
                ManualProductionForecastFor("wax_workshop"),
                ManualProductionForecastFor("warehouse_cells")
            };
            if (!ManualProductionForecast.TryEarliestSecondsUntilFull(forecasts, out double seconds))
                return BeeLocalization.Text("ledger.forecast.unavailable", "Prévision indisponible");
            if (seconds <= 0d)
                return BeeLocalization.Text("ledger.forecast.full_now", "Une production est pleine · récolte manuelle disponible");
            return string.Format(
                CultureInfo.CurrentCulture,
                BeeLocalization.Text("ledger.forecast.next_full", "Premier stock plein dans {0}"),
                FormatManualProductionForecastDuration(seconds));
        }

        private static void SetPendingManualProduction(string hotspotId, float amount)
        {
            float clamped = Mathf.Clamp(amount, 0f, PendingManualProductionCapacity(hotspotId));
            if (string.Equals(hotspotId, "honey_storage", StringComparison.Ordinal)) localPreviewPendingHoney = clamped;
            else if (string.Equals(hotspotId, "wax_workshop", StringComparison.Ordinal)) localPreviewPendingWax = clamped;
            else if (string.Equals(hotspotId, "warehouse_cells", StringComparison.Ordinal)) localPreviewPendingPollen = clamped;
        }

        private static float TryCollectPendingProduction(string hotspotId)
        {
            if (OfficialOfflineProductionConfigured())
            {
                HiveOfflineProductionScreenModel model = OfficialOfflineProductionModel();
                HiveOfflineProductionLineModel line = model == null ? null : model.FindLine(hotspotId);
                if (model == null || line == null)
                {
                    if (offlineProductionController != null && !offlineProductionController.IsBusy)
                        offlineProductionController.Refresh();
                    localPreviewLastActionStatus = OfficialProductionStatusText(hotspotId);
                    return 0f;
                }
                if (model.IsReadOnly || model.State == HiveOfflineProductionScreenState.Loading ||
                    model.State == HiveOfflineProductionScreenState.Collecting)
                {
                    localPreviewLastActionStatus = OfficialProductionStatusText(hotspotId);
                    BeginReferenceFeedbackPulse(model.IsReadOnly ? "disabled" : "preview");
                    return 0f;
                }
                if (model.CanCollect(hotspotId))
                {
                    float estimatedCredited = line.CollectableWholeUnits;
                    offlineProductionController.Collect(hotspotId);
                    AudioManager.Instance?.PlayResourceGain();
                    localPreviewLastActionStatus = BeeLocalization.Text(
                        "production.official.collecting",
                        "Collecte serveur en cours…");
                    SetPlayerFacingActionState(
                        "pending",
                        BeeLocalization.Text("production.official.collecting.short", "Collecte en cours"),
                        BeeLocalization.Text("production.official.collecting.disclosure", "Validation et crédit par le serveur."));
                    BeginReferenceFeedbackPulse("preview");
                    // Meme animation "+N" flottante que la collecte locale, ancree sur ce seul
                    // hotspot - sans ceci, collecter via le serveur officiel ne montrait plus
                    // aucun retour visuel de collecte.
                    localPreviewLastCollectedHotspotId = hotspotId;
                    localPreviewLastCollectedAmount = estimatedCredited;
                    localPreviewCollectionFeedbackStartedAt = NowForUi();
                    // Sans cet appel, le tutoriel guide restait bloque sur "Objectif en cours"
                    // pour tout joueur reellement connecte au serveur : AdvanceGuidedCollectionTutorialOnCollection
                    // n'etait jusqu'ici declenche que par la collecte locale/demo (branche plus bas),
                    // jamais par une vraie collecte officielle (PREMIUM_PLAYTEST_REPORT.md, PB-006).
                    AdvanceGuidedCollectionTutorialOnCollection(hotspotId, estimatedCredited);
                    return estimatedCredited;
                }
                if (model.State == HiveOfflineProductionScreenState.Error && !offlineProductionController.IsBusy)
                    offlineProductionController.Refresh();
                localPreviewLastActionStatus = line.IsResourceCapacityFull
                    ? BeeLocalization.Text("production.official.error.capacity", "Réserve pleine · dépense avant de collecter")
                    : OfficialProductionStatusText(hotspotId);
                BeginReferenceFeedbackPulse("disabled");
                return 0f;
            }

            string icon = ManualProductionIcon(hotspotId);
            float pending = PendingManualProduction(hotspotId);
            if (string.IsNullOrWhiteSpace(icon) || pending < CollectionReadyThreshold) return 0f;
            if (!GuidedCollectionTutorialAllowsCollection(hotspotId))
            {
                guidedCollectionTutorialBlockedClicks++;
                localPreviewLastActionStatus = "Suis la cible du tutoriel";
                return 0f;
            }

            float availableCapacity = Mathf.Max(0f, localPreviewCapacityMax - localPreviewCapacityUsed);
            float collected = Mathf.Min(pending, availableCapacity);
            if (collected <= 0.01f)
            {
                localPreviewOverflowFeedback = "Capacite pleine: depense ou ameliore la reserve.";
                localPreviewLastActionStatus = "Collecte bloquee: capacite pleine";
                localPreviewRecoveryGuidance = "Depense des ressources ou augmente la capacite.";
                BeginReferenceFeedbackPulse("disabled");
                return 0f;
            }

            if (icon == "honey") localPreviewHoney += collected;
            else if (icon == "wax") localPreviewWax += collected;
            else if (icon == "pollen") localPreviewPollen += collected;

            AudioManager.Instance?.PlayResourceGain();
            SetPendingManualProduction(hotspotId, pending - collected);
            PersistLocalPreviewManualProduction(true);
            localPreviewCapacityUsed = Mathf.Min(localPreviewCapacityMax, localPreviewCapacityUsed + collected);
            localPreviewLastCollectedHotspotId = hotspotId;
            localPreviewLastCollectedResourceIcon = icon;
            localPreviewLastCollectedAmount = collected;
            localPreviewCollectionFeedbackStartedAt = NowForUi();
            localPreviewManualCollectionCount++;
            localPreviewResourceFeedbackText = "+" + Mathf.FloorToInt(collected).ToString(CultureInfo.InvariantCulture) + " " + ManualProductionLabel(hotspotId);
            localPreviewResourceFeedbackStartedAt = NowForUi();
            localPreviewDailyStep = "collecte";
            localPreviewDailyFeedback = "Ressource recoltee; choisis une amelioration";
            localPreviewSessionPrompt = "Collecte recue. Ameliore un batiment.";
            localPreviewLoopMessage = "Collecte manuelle: " + localPreviewResourceFeedbackText;
            localPreviewLastActionStatus = "Collecte recue";
            localPreviewOverflowFeedback = availableCapacity - collected <= 0.01f ? "Capacite atteinte." : "Capacite disponible.";
            localPreviewRecoveryGuidance = "Depense la ressource ou recolte un autre batiment.";
            SetDevOnlyActionState("accepted", "none", "manual_collect", "T4_collection_result");
            SetPlayerFacingActionState("confirmation", "Collecte recue", localPreviewResourceFeedbackText + ".");
            BeginReferenceFeedbackPulse("preview");
            RecordDailyRoundTask(DailyRoundCollectTask);
            AdvanceGuidedCollectionTutorialOnCollection(hotspotId, collected);
            return collected;
        }

        private static IReadOnlyList<ReferenceHiveHotspotDefinition> BuildHotspotDefinitions()
        {
            ReferenceHiveHotspotDefinition[] definitions = new ReferenceHiveHotspotDefinition[ReferenceHotspots.Length];
            for (int i = 0; i < ReferenceHotspots.Length; i++)
            {
                ReferenceHiveHotspot hotspot = ReferenceHotspots[i];
                definitions[i] = new ReferenceHiveHotspotDefinition(hotspot.HotspotId, hotspot.CellId, hotspot.ZoneNumber, LocalizedHotspotLabel(hotspot), LocalizedHotspotRole(hotspot), hotspot.IconId, hotspot.StateIcon, GetReferenceTactileHitbox(hotspot), GetReferenceVisualAnchor(hotspot), hotspot.Priority);
            }

            return definitions;
        }

        private static Vector2[] GetReferenceVisualContour(ReferenceHiveHotspot hotspot)
        {
            return HiveVisualContourImportRuntime.TryGetVisualContour(hotspot.HotspotId, out Vector2[] imported)
                ? imported
                : Array.Empty<Vector2>();
        }

        private static Vector2 GetReferenceVisualAnchor(ReferenceHiveHotspot hotspot)
        {
            return HiveVisualContourImportRuntime.TryGetVisualAnchor(hotspot.HotspotId, out Vector2 importedAnchor)
                ? importedAnchor
                : hotspot.TokenAnchor;
        }

        private static Vector2[] GetReferenceTactileHitbox(ReferenceHiveHotspot hotspot)
        {
            return HivePixelPerfectContourCalibration.TryGet(hotspot.HotspotId, out HiveZoneContourDefinition calibrated)
                ? calibrated.TactileHitbox
                : hotspot.Polygon;
        }

        private static bool PointInReferencePolygon(Vector2 point, Vector2[] polygon)
        {
            bool inside = false;
            for (int i = 0, j = polygon.Length - 1; i < polygon.Length; j = i++)
            {
                Vector2 a = polygon[i];
                Vector2 b = polygon[j];
                bool crosses = (a.y > point.y) != (b.y > point.y);
                float denominator = b.y - a.y;
                if (Mathf.Abs(denominator) < 0.0001f) denominator = denominator < 0f ? -0.0001f : 0.0001f;
                if (crosses && point.x < (b.x - a.x) * (point.y - a.y) / denominator + a.x)
                {
                    inside = !inside;
                }
            }

            return inside || IsPointNearReferencePolygon(point, polygon, 6f);
        }

        private static bool IsPointNearReferencePolygon(Vector2 point, Vector2[] polygon, float tolerance)
        {
            for (int i = 0; i < polygon.Length; i++)
            {
                if (DistanceToReferenceSegment(point, polygon[i], polygon[(i + 1) % polygon.Length]) <= tolerance) return true;
            }

            return false;
        }

        private static void DrawImportedReferenceContours(Rect artRect, bool portrait)
        {
            if (!HiveVisualContourImportRuntime.HasImportedContours) return;
            if (!showReferenceContoursDebug) return;

            for (int i = 0; i < ReferenceHotspots.Length; i++)
            {
                ReferenceHiveHotspot hotspot = ReferenceHotspots[i];
                if (!HiveVisualContourImportRuntime.TryGetVisualContour(hotspot.HotspotId, out Vector2[] contour) || contour.Length < 3) continue;

                bool selected = hotspot.HotspotId == focusedReferenceHotspotId;
                Color shadow = new Color(0.02f, 0.015f, 0f, selected ? 0.82f : 0.58f);
                Color main = ImportedReferenceContourColor(hotspot.HotspotId, selected ? 0.98f : 0.82f);
                Color inner = ImportedReferenceContourColor(hotspot.HotspotId, selected ? 0.42f : 0.26f);
                DrawReferencePolygon(artRect, contour, shadow, portrait ? 4.2f : 5.0f);
                DrawReferencePolygon(artRect, contour, main, portrait ? 2.2f : 2.8f);
                DrawReferencePolygon(artRect, contour, inner, portrait ? 0.8f : 1.1f);
            }
        }

        private static Color ImportedReferenceContourColor(string hotspotId, float alpha)
        {
            if (string.Equals(hotspotId, "honey_storage", StringComparison.Ordinal))
            {
                return new Color(1f, 0.86f, 0.16f, alpha);
            }

            return new Color(1f, 0.72f, 0.18f, alpha);
        }

        private static float DistanceToReferenceSegment(Vector2 point, Vector2 a, Vector2 b)
        {
            Vector2 ab = b - a;
            float t = Vector2.Dot(point - a, ab) / Mathf.Max(0.0001f, Vector2.Dot(ab, ab));
            t = Mathf.Clamp01(t);
            return Vector2.Distance(point, a + ab * t);
        }

        private static void DrawReferencePolygonHalo(Rect artRect, ReferenceHiveHotspot hotspot, bool portrait)
        {
            Vector2[] contour = GetReferenceVisualContour(hotspot);
            if (contour.Length < 3) return;
            float pulse = productionReducedMotionForProof ? 1f : 1f + Mathf.Sin(NowForUi() * 5.5f) * 0.12f;
            Color shadow = new Color(0.06f, 0.035f, 0.00f, 0.82f);
            Color amber = hotspot.StateIcon == "server" ? new Color(0.20f, 0.76f, 1f, 0.94f) : new Color(1f, 0.57f, 0.05f, 0.96f);
            Color gold = hotspot.StateIcon == "server" ? new Color(0.72f, 0.95f, 1f, 0.74f) : new Color(1f, 0.94f, 0.36f, portrait ? 0.78f : 0.86f);
            Color spark = new Color(1f, 1f, 0.82f, portrait ? 0.42f : 0.52f);
            DrawReferencePolygon(artRect, contour, shadow, portrait ? 4.8f : 5.6f);
            DrawReferencePolygon(artRect, contour, amber, (portrait ? 2.9f : 3.5f) * pulse);
            DrawReferencePolygon(artRect, contour, gold, portrait ? 1.6f : 2.1f);
            DrawReferencePolygon(artRect, contour, spark, portrait ? 0.7f : 0.9f);
        }

        private static void DrawReferenceHoverHalo(Rect artRect, ReferenceHiveHotspot hotspot, bool portrait)
        {
            Vector2[] contour = GetReferenceVisualContour(hotspot);
            if (contour.Length < 3) return;
            DrawReferencePolygon(artRect, contour, new Color(0.04f, 0.025f, 0f, 0.62f), portrait ? 3.4f : 4.2f);
            DrawReferencePolygon(artRect, contour, new Color(1f, 0.86f, 0.32f, 0.58f), portrait ? 1.7f : 2.2f);
        }

        private static void DrawReferenceFeedbackPulse(Rect artRect, bool portrait)
        {
            float elapsed = NowForUi() - referenceFeedbackPulseStartedAt;
            if (elapsed < 0f || elapsed > FeedbackPulseSeconds) return;

            ReferenceHiveHotspot hotspot = FocusedReferenceHotspot();
            Vector2[] contour = GetReferenceVisualContour(hotspot);
            if (contour.Length < 3) return;
            if (productionReducedMotionForProof)
            {
                DrawReferencePolygon(artRect, contour, PulseColor(referenceFeedbackKind, 0.74f), portrait ? 4f : 5.5f);
                return;
            }

            float t = Mathf.Clamp01(elapsed / FeedbackPulseSeconds);
            float eased = Mathf.Sin(t * Mathf.PI);
            Color previous = GUI.color;
            GUI.color = PulseColor(referenceFeedbackKind, 0.80f * eased);
            DrawReferencePolygon(artRect, contour, GUI.color, Mathf.Lerp(1.2f, portrait ? 2.6f : 3.2f, eased));
            GUI.color = previous;
        }

        private static Color PulseColor(string kind, float alpha)
        {
            switch (kind)
            {
                case "server": return new Color(0.28f, 0.72f, 1f, alpha);
                case "locked": return new Color(0.72f, 0.72f, 0.68f, alpha);
                case "future": return new Color(0.82f, 0.62f, 1f, alpha);
                case "disabled": return new Color(0.70f, 0.70f, 0.70f, alpha);
                default: return new Color(1f, 0.78f, 0.12f, alpha);
            }
        }

        private static float NowForUi()
        {
            return Application.isPlaying ? Time.realtimeSinceStartup : 1.6f;
        }

        private static void UpdateAnimationStates()
        {
            if (prevPlayerMenuOpen != playerMenuOpen)
            {
                if (playerMenuOpen) UIAnimationLibrary.BeginWindowOpen("player_menu", 0.2f);
                else UIAnimationLibrary.BeginWindowClose("player_menu", 0.18f);
                prevPlayerMenuOpen = playerMenuOpen;
            }
            if (prevVipMenuOpen != vipMenuOpen)
            {
                if (vipMenuOpen) UIAnimationLibrary.BeginWindowOpen("vip_menu", 0.2f);
                else UIAnimationLibrary.BeginWindowClose("vip_menu", 0.18f);
                prevVipMenuOpen = vipMenuOpen;
            }
            if (prevPowerMenuOpen != powerMenuOpen)
            {
                if (powerMenuOpen) UIAnimationLibrary.BeginWindowOpen("power_menu", 0.2f);
                else UIAnimationLibrary.BeginWindowClose("power_menu", 0.18f);
                prevPowerMenuOpen = powerMenuOpen;
            }
            if (prevChampionBeesPanelOpen != championBeesPanelOpen)
            {
                if (championBeesPanelOpen) UIAnimationLibrary.BeginWindowOpen("champion_bees", 0.2f);
                else UIAnimationLibrary.BeginWindowClose("champion_bees", 0.18f);
                prevChampionBeesPanelOpen = championBeesPanelOpen;
            }
            if (prevStrategicPathPanelOpen != strategicPathPanelOpen)
            {
                if (strategicPathPanelOpen) UIAnimationLibrary.BeginWindowOpen("strategic_path", 0.2f);
                else UIAnimationLibrary.BeginWindowClose("strategic_path", 0.18f);
                prevStrategicPathPanelOpen = strategicPathPanelOpen;
            }
            if (prevCombatDoctrineOpen != combatDoctrineOpen)
            {
                if (combatDoctrineOpen) UIAnimationLibrary.BeginWindowOpen("combat_doctrine", 0.2f);
                else UIAnimationLibrary.BeginWindowClose("combat_doctrine", 0.18f);
                prevCombatDoctrineOpen = combatDoctrineOpen;
            }
            if (prevCommunicationPanelOpen != communicationPanelOpen)
            {
                if (communicationPanelOpen) UIAnimationLibrary.BeginWindowOpen("communication", 0.18f);
                else UIAnimationLibrary.BeginWindowClose("communication", 0.15f);
                prevCommunicationPanelOpen = communicationPanelOpen;
            }
            if (prevResourceInventoryOpen != resourceInventoryOpen)
            {
                if (resourceInventoryOpen)
                {
                    UIAnimationLibrary.BeginWindowOpen("resource_inventory", 0.16f);
                    resourceInventoryOpenedAt = NowForUi();
                }
                else
                {
                    UIAnimationLibrary.BeginWindowClose("resource_inventory", 0.12f);
                }
                prevResourceInventoryOpen = resourceInventoryOpen;
            }
            if (prevSpeedUpWindowOpen != speedUpWindowOpen)
            {
                if (speedUpWindowOpen)
                {
                    UIAnimationLibrary.BeginWindowOpen("speedup_window", 0.2f);
                }
                else
                {
                    UIAnimationLibrary.BeginWindowClose("speedup_window", 0.18f);
                }
                prevSpeedUpWindowOpen = speedUpWindowOpen;
            }
            bool moreMenuOpen = activeMainMenuId == "More";
            if (prevActiveMainMenuId != (moreMenuOpen ? "More" : string.Empty))
            {
                if (moreMenuOpen) UIAnimationLibrary.BeginWindowOpen("more_menu", 0.18f);
                else UIAnimationLibrary.BeginWindowClose("more_menu", 0.15f);
                prevActiveMainMenuId = moreMenuOpen ? "More" : string.Empty;
            }
        }

        private static string FeedbackKindForHotspot(ReferenceHiveHotspot hotspot)
        {
            if (hotspot.StateIcon == "server") return "server";
            if (hotspot.StateIcon == "locked") return "locked";
            if (hotspot.StateIcon == "future") return "future";
            if (hotspot.StateIcon == "disabled") return "disabled";
            return "preview";
        }

        private static void BeginReferenceFeedbackPulse(string kind)
        {
            referenceFeedbackKind = string.IsNullOrWhiteSpace(kind) ? "preview" : kind;
            referenceFeedbackPulseStartedAt = NowForUi();
        }

        private static void EnsureLocalPreviewStrategicProfileLoaded()
        {
            if (localPreviewStrategicProfileLoaded) return;
            localPreviewStrategicProfileLoaded = true;
            string json = localPreviewStrategicProfileStore?.Read();
            try { localPreviewStrategicProfile = string.IsNullOrWhiteSpace(json) ? null : JsonUtility.FromJson<LocalPreviewStrategicProfile>(json); } catch { localPreviewStrategicProfile = null; }
            if (localPreviewStrategicProfile != null && localPreviewStrategicProfile.version >= 1 && localPreviewStrategicProfile.version <= 11)
            {
                localPreviewStrategicProfile.version = 12;
                if (string.IsNullOrWhiteSpace(localPreviewStrategicProfile.workerWorkshopCommission))
                    localPreviewStrategicProfile.workerWorkshopCommission = "none";
                if (string.IsNullOrWhiteSpace(localPreviewStrategicProfile.defenseWorldBriefing))
                    localPreviewStrategicProfile.defenseWorldBriefing = "none";
                if (string.IsNullOrWhiteSpace(localPreviewStrategicProfile.openingReward))
                    localPreviewStrategicProfile.openingReward = "none";
                localPreviewStrategicProfile.revision++;
                localPreviewStrategicProfileStore?.Write(JsonUtility.ToJson(localPreviewStrategicProfile));
            }
            bool strategicProfileCreated = localPreviewStrategicProfile == null || localPreviewStrategicProfile.version != 12;
            if (strategicProfileCreated)
                localPreviewStrategicProfile = new LocalPreviewStrategicProfile { profileId = Guid.NewGuid().ToString("N") };
            else if (string.IsNullOrWhiteSpace(localPreviewStrategicProfile.profileId))
            {
                localPreviewStrategicProfile.profileId = Guid.NewGuid().ToString("N");
                localPreviewStrategicProfile.revision++;
                strategicProfileCreated = true;
            }
            if (strategicProfileCreated)
                localPreviewStrategicProfileStore?.Write(JsonUtility.ToJson(localPreviewStrategicProfile));
            ApplyLocalPreviewStrategicProfile();
        }

        private static void SaveLocalPreviewStrategicChoice(string domain, string choice)
        {
            EnsureLocalPreviewStrategicProfileLoaded();
            switch (domain)
            {
                case "opening_charter": localPreviewStrategicProfile.openingCharter = choice; break;
                case "opening_commissioning": localPreviewStrategicProfile.openingCommissioning = choice; break;
                case "opening_brood_supply": localPreviewStrategicProfile.openingBroodSupply = choice; break;
                case "opening_reward": localPreviewStrategicProfile.openingReward = choice; break;
                case "brood_development": localPreviewStrategicProfile.broodDevelopment = choice; break;
                case "brood_doctrine": localPreviewStrategicProfile.broodDoctrine = choice; break;
                case "brood_worker_handoff": localPreviewStrategicProfile.broodWorkerHandoff = choice; break;
                case "brood_wax_consolidation": localPreviewStrategicProfile.broodWaxConsolidation = choice; break;
                case "worker_assignment": localPreviewStrategicProfile.workerAssignment = choice; break;
                case "worker_workshop_handoff": localPreviewStrategicProfile.workerWorkshopHandoff = choice; break;
                case "worker_workshop_commission": localPreviewStrategicProfile.workerWorkshopCommission = choice; break;
                case "workshop_specialization": localPreviewStrategicProfile.workshopSpecialization = choice; break;
                case "workshop_doctrine": localPreviewStrategicProfile.workshopDoctrine = choice; break;
                case "workshop_certification": localPreviewStrategicProfile.workshopCertification = choice; break;
                case "workshop_defense_handoff": localPreviewStrategicProfile.workshopDefenseHandoff = choice; break;
                case "defense_expedition_mandate": localPreviewStrategicProfile.defenseExpeditionMandate = choice; break;
                case "defense_world_briefing": localPreviewStrategicProfile.defenseWorldBriefing = choice; break;
            }
            localPreviewStrategicProfile.operationalHoneyProductionBonus = guidedWorkerCertificationHoneyProductionGain;
            localPreviewStrategicProfile.operationalBroodCareBonus = guidedWorkerCertificationBroodCareGain;
            localPreviewStrategicProfile.operationalBroodStabilityBonus = guidedWorkerCertificationStabilityGain;
            localPreviewStrategicProfile.operationalWaxProductionBonus = guidedBroodWaxConsolidationProductionGain;
            localPreviewStrategicProfile.operationalWaxCapacityBonus = guidedBroodWaxConsolidationCapacityGain;
            localPreviewStrategicProfile.revision++;
            localPreviewStrategicProfileStore?.Write(JsonUtility.ToJson(localPreviewStrategicProfile));
            appliedLocalPreviewStrategicEffects = LocalPreviewStrategicProfileRules.Derive(localPreviewStrategicProfile);
            localPreviewStrategicEffectsApplied = true;
        }

        private static void ApplyLocalPreviewStrategicProfile()
        {
            LocalPreviewStrategicEffects effects = LocalPreviewStrategicProfileRules.Derive(localPreviewStrategicProfile);
            LocalPreviewStrategicEffects previous = localPreviewStrategicEffectsApplied
                ? appliedLocalPreviewStrategicEffects
                : default;
            guidedBroodDevelopmentPlan = localPreviewStrategicProfile.broodDevelopment;
            guidedOpeningCommissioningSealPlan = localPreviewStrategicProfile.openingCommissioning;
            guidedOpeningBroodSupplyPlan = localPreviewStrategicProfile.openingBroodSupply;
            guidedOpeningRewardPlan = localPreviewStrategicProfile.openingReward;
            guidedBroodIncubationDoctrinePlan = localPreviewStrategicProfile.broodDoctrine;
            guidedBroodWorkerHandoffPlan = localPreviewStrategicProfile.broodWorkerHandoff;
            guidedBroodWaxConsolidationPlan = localPreviewStrategicProfile.broodWaxConsolidation;
            guidedWorkerAssignment = localPreviewStrategicProfile.workerAssignment;
            guidedWorkerWorkshopHandoffPlan = localPreviewStrategicProfile.workerWorkshopHandoff;
            guidedWorkerWorkshopCommissionPlan = localPreviewStrategicProfile.workerWorkshopCommission;
            guidedUpgradePlan = localPreviewStrategicProfile.workshopSpecialization;
            guidedUpgradeOperationsDoctrinePlan = localPreviewStrategicProfile.workshopDoctrine;
            guidedUpgradeCertificationPlan = localPreviewStrategicProfile.workshopCertification;
            guidedWorkshopDefenseHandoffPlan = localPreviewStrategicProfile.workshopDefenseHandoff;
            guidedDefenseExpeditionMandate = localPreviewStrategicProfile.defenseExpeditionMandate;
            guidedDefenseWorldBriefingPlan = localPreviewStrategicProfile.defenseWorldBriefing;
            localPreviewHoneyProductionBonus += effects.HoneyProductionBonus - previous.HoneyProductionBonus;
            localPreviewWaxProductionBonus += effects.WaxProductionBonus - previous.WaxProductionBonus;
            localPreviewWaxCapacityBonus += effects.WaxCapacityBonus - previous.WaxCapacityBonus;
            localPreviewBroodCareBonus += effects.BroodCareBonus - previous.BroodCareBonus;
            localPreviewBroodStability = Mathf.Clamp(localPreviewBroodStability + effects.BroodStabilityBonus - previous.BroodStabilityBonus, 0f, 100f);
            localPreviewCapacityMax += effects.CapacityFlatBonus - previous.CapacityFlatBonus;
            guidedWorkerCareHoneyDiscount = effects.WorkerRationHoneyDiscount;
            guidedWorkerEmergenceWaxDiscount = effects.WorkerEmergenceWaxDiscount;
            guidedWorkerWorkshopHoneyDiscount = effects.WorkshopHoneyDiscount;
            guidedWorkerWorkshopWaxDiscount = effects.WorkshopWaxDiscount;
            guidedWorkshopCalibrationWaxBonus = effects.WorkshopCalibrationWaxBonus;
            guidedWorkshopApplicationWaxDiscount = effects.WorkshopApplicationWaxDiscount;
            guidedDefenseExpeditionPollenBonus = effects.ForagingPollenBonus;
            guidedWorldNavigationHintLevel = effects.WorldNavigationHintLevel;
            guidedDefenseBarrierWaxDiscount = effects.DefenseBarrierWaxDiscount;
            localPreviewHiveSecurity = Mathf.Clamp(Mathf.RoundToInt(localPreviewHiveSecurity + effects.ExpeditionSecurityBonus + effects.DefenseStartingSecurityBonus + effects.WorldBriefingSecurityBonus - previous.ExpeditionSecurityBonus - previous.DefenseStartingSecurityBonus - previous.WorldBriefingSecurityBonus), 0, 100);
            appliedLocalPreviewStrategicEffects = effects;
            localPreviewStrategicEffectsApplied = true;
        }

        private static long UtcNowTicks()
        {
            return DateTime.UtcNow.Ticks;
        }

        private static void EnsureLocalPreviewHiveProgressLoaded()
        {
            if (localPreviewHiveProgressLoaded) return;
            EnsureLocalPreviewStrategicProfileLoaded();
            localPreviewHiveProgressLoaded = true;
            string profileId = localPreviewStrategicProfile?.profileId ?? string.Empty;
            LocalPreviewHiveProgressReadResult result = LocalPreviewHiveProgressCodec.Read(localPreviewHiveProgressStore, profileId);
            localPreviewHiveProgress = result.Progress ?? LocalPreviewHiveProgressCodec.CreateDefault(profileId);
            localPreviewHiveProgressRestoreStatus = result.Status.ToString().ToLowerInvariant();

            localPreviewBuildingLevels.Clear();
            if (localPreviewHiveProgress.buildings != null)
            {
                for (int i = 0; i < localPreviewHiveProgress.buildings.Count; i++)
                {
                    LocalPreviewBuildingProgress building = localPreviewHiveProgress.buildings[i];
                    if (building == null || string.IsNullOrWhiteSpace(building.hotspotId)) continue;
                    localPreviewBuildingLevels[building.hotspotId] = Mathf.Clamp(
                        building.level,
                        1,
                        LocalPreviewHiveProgressCodec.MaxBuildingLevel);
                }
            }

            localPreviewWorkers = localPreviewHiveProgress.workers;
            localPreviewSoldiers = localPreviewHiveProgress.soldiers;
            localPreviewGuardians = localPreviewHiveProgress.guardians;
            localPreviewScouts = localPreviewHiveProgress.scouts;
            localPreviewWingrunners = localPreviewHiveProgress.wingrunners;
            localPreviewDarters = localPreviewHiveProgress.darters;

            localPreviewChampionBeeLevels.Clear();
            if (localPreviewHiveProgress.championBees != null)
            {
                for (int i = 0; i < localPreviewHiveProgress.championBees.Count; i++)
                {
                    LocalPreviewChampionBeeProgress bee = localPreviewHiveProgress.championBees[i];
                    if (bee == null || string.IsNullOrWhiteSpace(bee.beeId)) continue;
                    localPreviewChampionBeeLevels[bee.beeId] = Mathf.Clamp(
                        bee.level,
                        1,
                        LocalPreviewHiveProgressCodec.MaxChampionBeeLevel);
                }
            }

            localPreviewAssignedChampionBeeIds = localPreviewHiveProgress.assignedChampionBeeIds != null
                ? new List<string>(localPreviewHiveProgress.assignedChampionBeeIds)
                : new List<string>();

            localPreviewTroopTiers.Clear();
            if (localPreviewHiveProgress.troopTiers != null)
            {
                for (int i = 0; i < localPreviewHiveProgress.troopTiers.Count; i++)
                {
                    LocalPreviewTroopTierProgress entry = localPreviewHiveProgress.troopTiers[i];
                    if (entry == null || string.IsNullOrWhiteSpace(entry.populationId)) continue;
                    localPreviewTroopTiers[entry.populationId] = Mathf.Clamp(entry.tier, 1, LocalPreviewHiveProgressCodec.MaxTroopTier);
                }
            }
        }

        private static void PersistLocalPreviewBuildingLevel(string hotspotId, int level)
        {
            EnsureLocalPreviewHiveProgressLoaded();
            if (!LocalPreviewHiveProgressCodec.MergeBuildingLevel(localPreviewHiveProgress, hotspotId, level)) return;
            LocalPreviewHiveProgressCodec.Write(localPreviewHiveProgressStore, localPreviewHiveProgress);
            localPreviewHiveProgressRestoreStatus = "saved_device_preview";
        }

        private static void PersistLocalPreviewPopulationCount(string populationId, int count)
        {
            EnsureLocalPreviewHiveProgressLoaded();
            if (!LocalPreviewHiveProgressCodec.MergePopulationCount(localPreviewHiveProgress, populationId, count)) return;
            LocalPreviewHiveProgressCodec.Write(localPreviewHiveProgressStore, localPreviewHiveProgress);
            localPreviewHiveProgressRestoreStatus = "saved_device_preview";
        }

        private static void PersistLocalPreviewChampionBeeLevel(string beeId, int level)
        {
            EnsureLocalPreviewHiveProgressLoaded();
            if (!LocalPreviewHiveProgressCodec.MergeChampionBeeLevel(localPreviewHiveProgress, beeId, level)) return;
            localPreviewChampionBeeLevels[beeId] = level;
            LocalPreviewHiveProgressCodec.Write(localPreviewHiveProgressStore, localPreviewHiveProgress);
