        // Etat serveur officiel pour les abeilles championnes et paliers de troupe - charge une
        // fois par session authentifiee (EnsureOfficialChampionBeeAndTroopTierStateLoaded) et mis
        // a jour a chaque mutation reussie. Reste null tant que non authentifie ou non charge :
        // toutes les fonctions de lecture/ecriture ci-dessous se replient sur l'apercu local dans
        // ce cas, exactement comme les autres systemes officiels (production, batiments...).
        private static Dictionary<string, int> officialChampionBeeLevels;
        private static List<string> officialAssignedChampionBeeIds;
        private static int officialChampionBeeMaxAssigned = 1;
        private static long officialChampionBeeRevision = -1;
        private static bool officialChampionBeeStateLoaded;
        private static Dictionary<string, int> officialTroopTiers;
        private static long officialTroopTierRevision = -1;
        private static bool officialTroopTierStateLoaded;
        private static long officialVipLifetimePoints;
        private static int officialVipLevel;
        private static long? officialVipNextThreshold;
        private static int officialVipCapacityBonusBps;
        private static long officialVipRevision = -1;
        private static bool officialVipStateLoaded;
        private static bool officialVipGrantPending;

        private static bool OfficialVipProgressionConfigured()
        {
            return MobileAccountSessionRuntimeBootstrap.VipClient != null;
        }

        private static void EnsureOfficialVipStateLoaded()
        {
            if (!OfficialVipProgressionConfigured() || officialVipStateLoaded) return;
            officialVipStateLoaded = true;
            _ = RefreshOfficialVipStateAsync();
        }

        private static async Task RefreshOfficialVipStateAsync()
        {
            try
            {
                IHiveVipClient client = MobileAccountSessionRuntimeBootstrap.VipClient;
                if (client == null) return;
                RemoteVipSnapshot snapshot = await client.ReadAsync(MobileAccountSessionRuntimeBootstrap.GameplayHiveId);
                officialVipLifetimePoints = snapshot.LifetimePoints;
                officialVipLevel = snapshot.Level;
                officialVipNextThreshold = snapshot.NextThreshold;
                officialVipCapacityBonusBps = snapshot.CapacityBonusBps;
                officialVipRevision = snapshot.Revision;
            }
            catch (Exception exception)
            {
                // Ne PAS remettre officialVipStateLoaded a false ici : ce drapeau est verifie a
                // chaque frame par plusieurs elements du HUD, et le remettre a false en cas
                // d'echec relance immediatement une nouvelle tentative reseau chaque frame -
                // boucle infinie confirmee (des centaines de tentatives/seconde) qui bloquait
                // toute l'interface. Un seul essai par session tant qu'un vrai bouton "reessayer"
                // n'existe pas.
                Debug.LogWarning("Bee Kingdom VIP state refresh failed (" + exception.GetType().Name + ")");
            }
        }

        // Bouton de test reserve au developpement (memes conditions que
        // SkipActOneTutorialForDevelopment) : credite des points VIP de test en attendant les
        // vrais achats integres. Le serveur refuse cette route hors environnement de dev.
        private static void GrantTestVipPointsForDevelopment()
        {
            if (!OfficialVipProgressionConfigured() || officialVipGrantPending) return;
            officialVipGrantPending = true;
            _ = GrantTestVipPointsAsync();
        }

        private static async Task GrantTestVipPointsAsync()
        {
            try
            {
                IHiveVipClient client = MobileAccountSessionRuntimeBootstrap.VipClient;
                if (client == null) return;
                RemoteVipSnapshot snapshot = await client.GrantTestPointsAsync(
                    MobileAccountSessionRuntimeBootstrap.GameplayHiveId, 100, officialVipRevision, Guid.NewGuid().ToString("N"));
                officialVipLifetimePoints = snapshot.LifetimePoints;
                officialVipLevel = snapshot.Level;
                officialVipNextThreshold = snapshot.NextThreshold;
                officialVipCapacityBonusBps = snapshot.CapacityBonusBps;
                officialVipRevision = snapshot.Revision;
            }
            catch (Exception exception)
            {
                Debug.LogWarning("Bee Kingdom VIP test grant failed (" + exception.GetType().Name + ")");
            }
            finally
            {
                officialVipGrantPending = false;
            }
        }

        private static bool OfficialChampionBeeProgressionConfigured()
        {
            return MobileAccountSessionRuntimeBootstrap.ChampionBeeClient != null;
        }

        private static bool OfficialTroopTierProgressionConfigured()
        {
            return MobileAccountSessionRuntimeBootstrap.TroopTierClient != null;
        }

        private static void EnsureOfficialChampionBeeAndTroopTierStateLoaded()
        {
            bool needsChampionBees = OfficialChampionBeeProgressionConfigured() && !officialChampionBeeStateLoaded;
            bool needsTroopTiers = OfficialTroopTierProgressionConfigured() && !officialTroopTierStateLoaded;
            if (!needsChampionBees && !needsTroopTiers) return;
            officialChampionBeeStateLoaded = officialChampionBeeStateLoaded || needsChampionBees;
            officialTroopTierStateLoaded = officialTroopTierStateLoaded || needsTroopTiers;
            _ = RefreshOfficialChampionBeeAndTroopTierStateAsync(needsChampionBees, needsTroopTiers);
        }

        private static async Task RefreshOfficialChampionBeeAndTroopTierStateAsync(bool championBees, bool troopTiers)
        {
            Guid hiveId = MobileAccountSessionRuntimeBootstrap.GameplayHiveId;
            try
            {
                if (championBees)
                {
                    IHiveChampionBeeClient client = MobileAccountSessionRuntimeBootstrap.ChampionBeeClient;
                    if (client != null)
                    {
                        RemoteChampionBeeSnapshot snapshot = await client.ReadAsync(hiveId);
                        officialChampionBeeLevels = snapshot.Levels;
                        officialAssignedChampionBeeIds = snapshot.AssignedBeeIds;
                        officialChampionBeeMaxAssigned = Mathf.Max(1, snapshot.MaxAssigned);
                        officialChampionBeeRevision = snapshot.Revision;
                    }
                }
                if (troopTiers)
                {
                    IHiveTroopTierClient client = MobileAccountSessionRuntimeBootstrap.TroopTierClient;
                    if (client != null)
                    {
                        RemoteTroopTierSnapshot snapshot = await client.ReadAsync(hiveId);
                        officialTroopTiers = snapshot.Tiers;
                        officialTroopTierRevision = snapshot.Revision;
                    }
                }
            }
            catch (Exception exception)
            {
                Debug.LogWarning("Bee Kingdom champion bee/troop tier state refresh failed (" + exception.GetType().Name + ")");
            }
        }

        // Palier de puissance (T1/T2/T3) par type de troupe - v1, applique seulement aux 3 types
        // deja visibles dans le selecteur de la Caserne (soldiers/guardians/scouts). Chaque
        // palier au-dela de T1 ajoute +25% a la contribution de puissance de ce type (bucket
        // "Abeilles spec." du panneau Puissance) et, pour les Gardiennes specifiquement, a
        // l'apercu local de bonus de combat (meme famille que Combat Patrol/Abeilles championnes).
        private static int TroopTier(string populationId)
        {
            if (OfficialTroopTierProgressionConfigured())
            {
                EnsureOfficialChampionBeeAndTroopTierStateLoaded();
                if (officialTroopTiers != null) return officialTroopTiers.TryGetValue(populationId, out int officialTier) ? officialTier : 1;
            }
            EnsureLocalPreviewHiveProgressLoaded();
            return localPreviewTroopTiers.TryGetValue(populationId, out int tier) ? tier : 1;
        }

        private static float TroopTierMultiplier(string populationId)
        {
            return 1f + 0.25f * (TroopTier(populationId) - 1);
        }

        private static Vector2 TroopTierPromotionCost(int currentTier)
        {
            float honey = 200f * currentTier;
            float pollen = 80f * currentTier;
            return new Vector2(honey, pollen);
        }

        private static void PersistLocalPreviewTroopTier(string populationId, int tier)
        {
            EnsureLocalPreviewHiveProgressLoaded();
            if (!LocalPreviewHiveProgressCodec.MergeTroopTier(localPreviewHiveProgress, populationId, tier)) return;
            localPreviewTroopTiers[populationId] = tier;
            LocalPreviewHiveProgressCodec.Write(localPreviewHiveProgressStore, localPreviewHiveProgress);
            localPreviewHiveProgressRestoreStatus = "saved_device_preview";
        }

        private static void PromoteTroopTier(string populationId)
        {
            int tier = TroopTier(populationId);
            if (tier >= LocalPreviewHiveProgressCodec.MaxTroopTier) return;
            Vector2 cost = TroopTierPromotionCost(tier);
            if (localPreviewHoney < cost.x || localPreviewPollen < cost.y) return;
            if (OfficialTroopTierProgressionConfigured())
            {
                _ = PromoteTroopTierOfficialAsync(populationId);
                return;
            }
            localPreviewHoney -= cost.x;
            localPreviewPollen -= cost.y;
            PersistLocalPreviewTroopTier(populationId, tier + 1);
            localPreviewLoopMessage = "Troupe promue: " + populationId + " -> T" + (tier + 1);
            BeginReferenceFeedbackPulse("preview");
        }

        private static async Task PromoteTroopTierOfficialAsync(string populationId)
        {
            try
            {
                IHiveTroopTierClient client = MobileAccountSessionRuntimeBootstrap.TroopTierClient;
                if (client == null) return;
                RemoteTroopTierMutationResult result = await client.PromoteAsync(
                    MobileAccountSessionRuntimeBootstrap.GameplayHiveId, populationId, officialTroopTierRevision, Guid.NewGuid().ToString("N"));
                if (result.Succeeded)
                {
                    officialTroopTiers ??= new Dictionary<string, int>(StringComparer.Ordinal);
                    officialTroopTiers[populationId] = result.Tier;
                    officialTroopTierRevision = result.Revision;
                    localPreviewLoopMessage = "Troupe promue: " + populationId + " -> T" + result.Tier;
                    BeginReferenceFeedbackPulse("preview");
                }
                else
                {
                    localPreviewLoopMessage = "Promotion refusee (" + result.Code + ")";
                }
            }
            catch (Exception exception)
            {
                Debug.LogWarning("Bee Kingdom troop tier promotion failed (" + exception.GetType().Name + ")");
            }
        }

        private static int CoeurRoyalLevel()
        {
            if (IsOfficialUpgradeBuilding("administration_core") && OfficialBuildingUpgradeConfigured())
            {
                HiveBuildingUpgradeScreenModel model = OfficialBuildingUpgradeModel();
                int officialLevel = model == null ? 0 : model.LevelFor("administration_core");
                if (officialLevel > 0) return officialLevel;
            }
            EnsureLocalPreviewHiveProgressLoaded();
            return EnsureLocalPreviewLevel("administration_core");
        }

        private static bool IsChampionBeeUnlocked(ChampionBeeDefinition definition)
        {
            return CoeurRoyalLevel() >= ChampionBeeCatalog.UnlockCoeurRoyalLevel(definition.Rarity);
        }

        // On commence avec 1 seule abeille championne en mission ; ce plafond grandit avec le
        // niveau du Coeur royal jusqu'au plafond structurel absolu (5) - v1, ajustable avec Jeff.
        private static int CurrentMaxAssignedChampionBees()
        {
            if (OfficialChampionBeeProgressionConfigured())
            {
                EnsureOfficialChampionBeeAndTroopTierStateLoaded();
                if (officialChampionBeeLevels != null) return officialChampionBeeMaxAssigned;
            }
            return Mathf.Clamp(1 + CoeurRoyalLevel() / 8, 1, LocalPreviewHiveProgressCodec.MaxAssignedChampionBees);
        }

        private static bool IsChampionBeeOwned(string beeId)
        {
            if (OfficialChampionBeeProgressionConfigured())
            {
                EnsureOfficialChampionBeeAndTroopTierStateLoaded();
                if (officialChampionBeeLevels != null) return officialChampionBeeLevels.ContainsKey(beeId);
            }
            EnsureLocalPreviewHiveProgressLoaded();
            return localPreviewChampionBeeLevels.ContainsKey(beeId);
        }

        private static int ChampionBeeLevel(string beeId)
        {
            if (OfficialChampionBeeProgressionConfigured())
            {
                EnsureOfficialChampionBeeAndTroopTierStateLoaded();
                if (officialChampionBeeLevels != null) return officialChampionBeeLevels.TryGetValue(beeId, out int officialLevel) ? officialLevel : 0;
            }
            EnsureLocalPreviewHiveProgressLoaded();
            return localPreviewChampionBeeLevels.TryGetValue(beeId, out int level) ? level : 0;
        }

        private static void GrantChampionBee(ChampionBeeDefinition definition)
        {
            if (IsChampionBeeOwned(definition.Id) || !IsChampionBeeUnlocked(definition)) return;
            if (OfficialChampionBeeProgressionConfigured())
            {
                _ = GrantChampionBeeOfficialAsync(definition);
                return;
            }
            PersistLocalPreviewChampionBeeLevel(definition.Id, 1);
            championBeesLastActionStatus = BeeLocalization.Text("champion_bees.status.obtained", "Abeille championne obtenue !");
            BeginReferenceFeedbackPulse("preview");
        }

        private static async Task GrantChampionBeeOfficialAsync(ChampionBeeDefinition definition)
        {
            try
            {
                IHiveChampionBeeClient client = MobileAccountSessionRuntimeBootstrap.ChampionBeeClient;
                if (client == null) return;
                RemoteChampionBeeMutationResult result = await client.GrantAsync(
                    MobileAccountSessionRuntimeBootstrap.GameplayHiveId, definition.Id, officialChampionBeeRevision, Guid.NewGuid().ToString("N"));
                if (result.Succeeded)
                {
                    officialChampionBeeLevels ??= new Dictionary<string, int>(StringComparer.Ordinal);
                    officialChampionBeeLevels[definition.Id] = result.Level;
                    officialAssignedChampionBeeIds = result.AssignedBeeIds;
                    officialChampionBeeRevision = result.Revision;
                    championBeesLastActionStatus = BeeLocalization.Text("champion_bees.status.obtained", "Abeille championne obtenue !");
                    BeginReferenceFeedbackPulse("preview");
                }
                else
                {
                    championBeesLastActionStatus = "Echec (" + result.Code + ")";
                }
            }
            catch (Exception exception)
            {
                Debug.LogWarning("Bee Kingdom champion bee grant failed (" + exception.GetType().Name + ")");
            }
        }

        private static void LevelUpChampionBee(ChampionBeeDefinition definition)
        {
            int level = ChampionBeeLevel(definition.Id);
            if (level <= 0 || level >= LocalPreviewHiveProgressCodec.MaxChampionBeeLevel) return;
            Vector2 cost = ChampionBeeCatalog.LevelUpCost(definition, level);
            if (localPreviewHoney < cost.x || localPreviewPollen < cost.y) return;
            if (OfficialChampionBeeProgressionConfigured())
            {
                _ = LevelUpChampionBeeOfficialAsync(definition);
                return;
            }
            localPreviewHoney -= cost.x;
            localPreviewPollen -= cost.y;
            PersistLocalPreviewChampionBeeLevel(definition.Id, level + 1);
            championBeesLastActionStatus = BeeLocalization.Text("champion_bees.status.leveled_up", "Abeille championne amelioree.");
            BeginReferenceFeedbackPulse("preview");
        }

