        private static bool IsChampionBeeAssigned(string beeId)
        {
            if (OfficialChampionBeeProgressionConfigured())
            {
                EnsureOfficialChampionBeeAndTroopTierStateLoaded();
                if (officialAssignedChampionBeeIds != null) return officialAssignedChampionBeeIds.Contains(beeId);
            }
            return localPreviewAssignedChampionBeeIds.Contains(beeId);
        }

        private static void ToggleAssignChampionBee(string beeId)
        {
            if (OfficialChampionBeeProgressionConfigured())
            {
                List<string> current = officialAssignedChampionBeeIds != null
                    ? new List<string>(officialAssignedChampionBeeIds)
                    : new List<string>();
                if (current.Contains(beeId)) current.Remove(beeId);
                else
                {
                    if (current.Count >= CurrentMaxAssignedChampionBees()) return;
                    current.Add(beeId);
                }
                _ = SetChampionBeeAssignmentOfficialAsync(current);
                return;
            }

            if (localPreviewAssignedChampionBeeIds.Contains(beeId))
            {
                localPreviewAssignedChampionBeeIds.Remove(beeId);
            }
            else
            {
                if (localPreviewAssignedChampionBeeIds.Count >= CurrentMaxAssignedChampionBees()) return;
                localPreviewAssignedChampionBeeIds.Add(beeId);
            }

            PersistLocalPreviewAssignedChampionBees();
        }

        private static async Task SetChampionBeeAssignmentOfficialAsync(List<string> beeIds)
        {
            try
            {
                IHiveChampionBeeClient client = MobileAccountSessionRuntimeBootstrap.ChampionBeeClient;
                if (client == null) return;
                RemoteChampionBeeMutationResult result = await client.SetAssignmentAsync(
                    MobileAccountSessionRuntimeBootstrap.GameplayHiveId, beeIds, officialChampionBeeRevision, Guid.NewGuid().ToString("N"));
                if (result.Succeeded)
                {
                    officialAssignedChampionBeeIds = result.AssignedBeeIds;
                    officialChampionBeeRevision = result.Revision;
                }
            }
            catch (Exception exception)
            {
                Debug.LogWarning("Bee Kingdom champion bee assignment failed (" + exception.GetType().Name + ")");
            }
        }

        private static int ChampionBeeCombatArmyBonus(string combatFamilyId)
        {
            int bonus = 0;
            for (int i = 0; i < localPreviewAssignedChampionBeeIds.Count; i++)
            {
                if (!ChampionBeeCatalog.TryResolve(localPreviewAssignedChampionBeeIds[i], out ChampionBeeDefinition definition)) continue;
                if (!string.Equals(ChampionBeeCatalog.CombatFamilyId(definition.Role), combatFamilyId, StringComparison.Ordinal)) continue;
                bonus += definition.ArmyBonusPerLevel * ChampionBeeLevel(definition.Id);
            }

            return bonus;
        }

        private static float ChampionBeeCombatStatBonusPercent(string combatFamilyId)
        {
            float percent = 0f;
            for (int i = 0; i < localPreviewAssignedChampionBeeIds.Count; i++)
            {
                if (!ChampionBeeCatalog.TryResolve(localPreviewAssignedChampionBeeIds[i], out ChampionBeeDefinition definition)) continue;
                if (definition.Role == ChampionBeeRole.Civilian) continue;
                int level = ChampionBeeLevel(definition.Id);
                if (string.Equals(ChampionBeeCatalog.CombatFamilyId(definition.Role), combatFamilyId, StringComparison.Ordinal))
                    percent += definition.RoleStatBonusPercentPerLevel * level;
                percent += definition.GlobalStatBonusPercentPerLevel * level;
            }

            return percent;
        }

        private static float ChampionBeeProductionBonusPercent()
        {
            float percent = 0f;
            for (int i = 0; i < localPreviewAssignedChampionBeeIds.Count; i++)
            {
                if (!ChampionBeeCatalog.TryResolve(localPreviewAssignedChampionBeeIds[i], out ChampionBeeDefinition definition)) continue;
                if (definition.Role != ChampionBeeRole.Civilian) continue;
                percent += definition.ProductionBonusPercentPerLevel * ChampionBeeLevel(definition.Id);
            }

            return percent;
        }

        // Seules les Gardiennes ont a la fois un palier de troupe (Caserne) et une famille de
        // combat partagee avec Combat Patrol/Abeilles championnes - Soldats/Eclaireuses ne
        // participent pas au Combat Patrol, Voltigeuses/Lanceuses ne sont pas encore paliers.
        private static float TroopTierStatBonusPercent(string combatFamilyId)
        {
            return string.Equals(combatFamilyId, "guardians", StringComparison.Ordinal)
                ? (TroopTier("guardians") - 1) * 25f
                : 0f;
        }

        private static string ChampionBeeCombatSummaryLine()
        {
            string[] families = { "guardians", "wingrunners", "darters" };
            string[] labels =
            {
                BeeLocalization.Text("champion_bees.role.guardians", "Gardiennes"),
                BeeLocalization.Text("champion_bees.role.wingrunners", "Voltigeuses"),
                BeeLocalization.Text("champion_bees.role.darters", "Lanceuses")
            };
            var parts = new List<string>();
            for (int i = 0; i < families.Length; i++)
            {
                int army = ChampionBeeCombatArmyBonus(families[i]);
                float stat = ChampionBeeCombatStatBonusPercent(families[i]) + TroopTierStatBonusPercent(families[i]);
                if (army <= 0 && stat <= 0f) continue;
                parts.Add(labels[i] + " +" + army.ToString(CultureInfo.InvariantCulture) + "/+" + stat.ToString("0.#", CultureInfo.InvariantCulture) + "%");
            }

            return parts.Count == 0
                ? BeeLocalization.Text("champion_bees.combat_summary_none", "Aucune abeille championne assignee")
                : string.Join(" - ", parts);
        }

        private static string PopulationIdForTroopType(string troopType)
        {
            if (IsWorkerTrainingType(troopType)) return "workers";
            if (HiveDoctrineRecruitmentCatalog.TryResolveTroopType(troopType, out HiveDoctrineRecruitmentDefinition recruitment))
                return recruitment.PopulationId;
            if (string.Equals(troopType, "Gardiennes", StringComparison.Ordinal)) return "guardians";
            if (string.Equals(troopType, "Eclaireuses", StringComparison.Ordinal)) return "scouts";
            return "soldiers";
        }

        private static void EnsureLocalPreviewQueueJournalLoaded()
        {
            EnsureLocalPreviewHiveProgressLoaded();
            if (localPreviewQueueJournalLoaded) return;
            localPreviewQueueJournalLoaded = true;
            localPreviewQueueJournal = LocalPreviewQueueJournalCodec.Read(localPreviewQueueJournalStore);
            localPreviewQueueReturnItems = LocalPreviewQueueReturnSummary.Build(localPreviewQueueJournal, UtcNowTicks());
            localPreviewQueueReturnLastRoute = "none";
            RestoreLocalPreviewQueue(localPreviewQueueJournal.upgrade, true);
            RestoreLocalPreviewQueue(localPreviewQueueJournal.training, false);
            RestoreLocalPreviewResearch(localPreviewQueueJournal.research);
            ApplyLocalPreviewResearchEffects();
            localPreviewQueueRestoreStatus = localPreviewQueueJournal.upgrade.Exists || localPreviewQueueJournal.training.Exists || localPreviewQueueJournal.research.Exists
                ? "restored_local_preview"
                : "empty_local_preview";
            localPreviewQueueResumeNoticeVisible = localPreviewQueueReturnItems.Count > 0;
            if (localPreviewQueueResumeNoticeVisible) localPreviewQueueResumeHistory = BuildQueueResumeHistory();
        }

        private static IReadOnlyList<LocalPreviewManualProductionRule> BuildLocalPreviewManualProductionRules()
        {
            return new[]
            {
                new LocalPreviewManualProductionRule(
                    "honey_storage",
                    ManualProductionPerHour("honey_storage"),
                    PendingManualProductionCapacity("honey_storage")),
                new LocalPreviewManualProductionRule(
                    "wax_workshop",
                    ManualProductionPerHour("wax_workshop"),
                    PendingManualProductionCapacity("wax_workshop")),
                new LocalPreviewManualProductionRule(
                    "warehouse_cells",
                    ManualProductionPerHour("warehouse_cells"),
                    PendingManualProductionCapacity("warehouse_cells"))
            };
        }

        private static void EnsureLocalPreviewManualProductionLoaded()
        {
            if (localPreviewManualProductionLoaded) return;
            RestoreLocalPreviewManualProduction(UtcNowTicks());
        }

        private static void RestoreLocalPreviewManualProduction(long utcNowTicks)
        {
            EnsureLocalPreviewQueueJournalLoaded();
            localPreviewManualProductionLoaded = true;
            IReadOnlyList<LocalPreviewManualProductionRule> rules = BuildLocalPreviewManualProductionRules();
            string profileId = localPreviewStrategicProfile?.profileId ?? string.Empty;
            LocalPreviewManualProductionReadResult read = LocalPreviewManualProductionJournalCodec.Read(
                localPreviewManualProductionStore,
                profileId,
                utcNowTicks,
                rules);
            localPreviewManualProductionJournal = read.Journal
                ?? LocalPreviewManualProductionJournalCodec.CreateDefault(profileId, utcNowTicks, rules);
            localPreviewManualProductionRestoreStatus = read.Status.ToString().ToLowerInvariant();
            localPreviewManualProductionReturnNoticeVisible = false;
            localPreviewManualProductionReturnHoney = 0f;
            localPreviewManualProductionReturnWax = 0f;
            localPreviewManualProductionReturnPollen = 0f;
            localPreviewManualProductionReturnSeconds = 0d;
            localPreviewManualProductionReturnLastRoute = "none";

            if (read.Status == LocalPreviewManualProductionReadStatus.Empty)
            {
                LocalPreviewManualProductionJournalCodec.SetPending(localPreviewManualProductionJournal, "honey_storage", localPreviewPendingHoney, rules);
                LocalPreviewManualProductionJournalCodec.SetPending(localPreviewManualProductionJournal, "wax_workshop", localPreviewPendingWax, rules);
                LocalPreviewManualProductionJournalCodec.SetPending(localPreviewManualProductionJournal, "warehouse_cells", localPreviewPendingPollen, rules);
                localPreviewManualProductionJournal.revision++;
                localPreviewManualProductionAccrualStatus = "initialized_device_preview";
                LocalPreviewManualProductionJournalCodec.Write(localPreviewManualProductionStore, localPreviewManualProductionJournal, rules);
            }
            else if (read.Status == LocalPreviewManualProductionReadStatus.Restored
                     || read.Status == LocalPreviewManualProductionReadStatus.Sanitized)
            {
                LocalPreviewManualProductionAccrualResult accrual = LocalPreviewManualProductionJournalCodec.Accrue(
                    localPreviewManualProductionJournal,
                    utcNowTicks,
                    rules);
                localPreviewManualProductionAccrualStatus = accrual.Status.ToString().ToLowerInvariant();
                localPreviewManualProductionReturnHoney = accrual.AccruedFor("honey_storage");
                localPreviewManualProductionReturnWax = accrual.AccruedFor("wax_workshop");
                localPreviewManualProductionReturnPollen = accrual.AccruedFor("warehouse_cells");
                localPreviewManualProductionReturnSeconds = accrual.RecognizedSeconds;
                localPreviewManualProductionReturnNoticeVisible = accrual.TotalAccrued >= 1f;
                LocalPreviewManualProductionJournalCodec.Write(localPreviewManualProductionStore, localPreviewManualProductionJournal, rules);
            }
            else
            {
                localPreviewManualProductionAccrualStatus = "reset_" + localPreviewManualProductionRestoreStatus;
                LocalPreviewManualProductionJournalCodec.Write(localPreviewManualProductionStore, localPreviewManualProductionJournal, rules);
            }

            localPreviewPendingHoney = LocalPreviewManualProductionJournalCodec.PendingFor(localPreviewManualProductionJournal, "honey_storage");
            localPreviewPendingWax = LocalPreviewManualProductionJournalCodec.PendingFor(localPreviewManualProductionJournal, "wax_workshop");
            localPreviewPendingPollen = LocalPreviewManualProductionJournalCodec.PendingFor(localPreviewManualProductionJournal, "warehouse_cells");
            localPreviewManualProductionLastPersistedAt = NowForUi();
            localPreviewLastTickAt = NowForUi();
        }

        private static void PersistLocalPreviewManualProduction(bool force)
        {
            EnsureLocalPreviewManualProductionLoaded();
            float nowForUi = NowForUi();
            if (!force && nowForUi - localPreviewManualProductionLastPersistedAt < ManualProductionPersistIntervalSeconds) return;

            IReadOnlyList<LocalPreviewManualProductionRule> rules = BuildLocalPreviewManualProductionRules();
            LocalPreviewManualProductionJournalCodec.SetPending(localPreviewManualProductionJournal, "honey_storage", localPreviewPendingHoney, rules);
            LocalPreviewManualProductionJournalCodec.SetPending(localPreviewManualProductionJournal, "wax_workshop", localPreviewPendingWax, rules);
            LocalPreviewManualProductionJournalCodec.SetPending(localPreviewManualProductionJournal, "warehouse_cells", localPreviewPendingPollen, rules);
            localPreviewManualProductionJournal.lastAccrualUtcTicks = Math.Max(
                localPreviewManualProductionJournal.lastAccrualUtcTicks,
                UtcNowTicks());
            localPreviewManualProductionJournal.revision++;
            LocalPreviewManualProductionJournalCodec.Write(localPreviewManualProductionStore, localPreviewManualProductionJournal, rules);
            localPreviewManualProductionLastPersistedAt = nowForUi;
            localPreviewManualProductionRestoreStatus = "saved_device_preview";
        }

        public static void FlushLocalPreviewManualProductionForRuntime()
        {
            PersistLocalPreviewManualProduction(true);
        }

        public static void ResumeLocalPreviewManualProductionForRuntime()
        {
            localPreviewManualProductionLoaded = false;
            RestoreLocalPreviewManualProduction(UtcNowTicks());
        }

        private static string BuildQueueResumeHistory()
        {
            string history = string.Empty;
            for (int i = 0; i < localPreviewQueueReturnItems.Count; i++)
            {
                LocalPreviewQueueReturnItem item = localPreviewQueueReturnItems[i];
                if (history.Length > 0) history += "\n";
                history += QueueReturnKindLabel(item) + " · " + QueueReturnTargetLabel(item) + " · " + QueueReturnStatusLabel(item);
            }

            return history;
        }

        private static string QueueReturnKindLabel(LocalPreviewQueueReturnItem item)
        {
            if (string.Equals(item.Kind, "upgrade", StringComparison.Ordinal))
                return item.Status == LocalPreviewQueueReturnStatus.Active
                    ? BeeLocalization.Text("ui.queue.resume.build", "Amélioration reprise")
                    : BeeLocalization.Text("ui.queue.return.build", "Amélioration");
            if (string.Equals(item.Kind, "training", StringComparison.Ordinal))
                return item.Status == LocalPreviewQueueReturnStatus.Active
                    ? BeeLocalization.Text("ui.queue.resume.train", "Formation reprise")
                    : BeeLocalization.Text("ui.queue.return.train", "Formation");
            return item.Status == LocalPreviewQueueReturnStatus.Active
                ? BeeLocalization.Text("ui.queue.resume.research", "Recherche reprise")
                : BeeLocalization.Text("ui.queue.return.research", "Recherche");
        }

        private static string QueueReturnTargetLabel(LocalPreviewQueueReturnItem item)
        {
            if (string.Equals(item.Kind, "upgrade", StringComparison.Ordinal))
            {
                ReferenceHiveHotspot hotspot = FindReferenceHotspot(item.TargetId);
                return string.IsNullOrWhiteSpace(hotspot.HotspotId) ? item.TargetId : LocalizedHotspotLabel(hotspot);
            }
            if (string.Equals(item.Kind, "training", StringComparison.Ordinal)) return LocalizedTroopType(item.TargetId);
            return ResearchTitle(item.TargetId);
        }

        private static string QueueReturnStatusLabel(LocalPreviewQueueReturnItem item)
        {
            if (item.Status == LocalPreviewQueueReturnStatus.CompletedWhileAway)
                return BeeLocalization.Text("ui.queue.return.completed", "Terminée pendant l’absence");

            double remainingSeconds = Math.Max(0d, new TimeSpan(item.EndsUtcTicks - UtcNowTicks()).TotalSeconds);
            return string.Format(
                CultureInfo.CurrentCulture,
                BeeLocalization.Text("ui.queue.return.active", "{0}s restantes"),
                Math.Ceiling(remainingSeconds).ToString("0", CultureInfo.CurrentCulture));
        }

        private static bool QueueReturnHasCompletedItem()
        {
            for (int i = 0; i < localPreviewQueueReturnItems.Count; i++)
            {
                if (localPreviewQueueReturnItems[i].Status == LocalPreviewQueueReturnStatus.CompletedWhileAway) return true;
            }

            return false;
        }

        private static Rect QueueReturnPanelRect(bool portrait, float screenWidth, float screenHeight)
        {
            float width = portrait ? screenWidth - 24f : Mathf.Min(470f, screenWidth - 290f);
            int count = Mathf.Clamp(localPreviewQueueReturnItems.Count, 1, 3);
            float height = 116f + count * 22f;
            return portrait
                ? new Rect(12f, 126f, width, Mathf.Min(height, screenHeight - 222f))
                : new Rect(142f, 88f, width, Mathf.Min(height, screenHeight - 184f));
        }

