                + " " + BeeLocalization.Text("resource.honey", "miel")
                + " · +" + Mathf.FloorToInt(localPreviewManualProductionReturnWax).ToString(CultureInfo.InvariantCulture)
                + " " + BeeLocalization.Text("resource.wax", "cire")
