        private static void NavigateToManualProductionReturnBuilding()
        {
            string hotspotId = localPreviewManualProductionReturnHoney > 0f
                ? "honey_storage"
                : localPreviewManualProductionReturnWax > 0f
                    ? "wax_workshop"
                    : localPreviewManualProductionReturnPollen > 0f
                        ? "warehouse_cells"
                        : PendingManualProduction("honey_storage") > 0f
                            ? "honey_storage"
                            : PendingManualProduction("wax_workshop") > 0f ? "wax_workshop" : "warehouse_cells";
            ReferenceHiveHotspot hotspot = FindReferenceHotspot(hotspotId);
            if (string.IsNullOrWhiteSpace(hotspot.HotspotId)) return;

            activeMainMenuId = string.Empty;
            activeHiveMenu = HiveMenuMode.Hive;
            detailPanelClosed = false;
            SelectReferenceHotspot(hotspot);
            localPreviewManualProductionReturnLastRoute = hotspotId;
            localPreviewManualProductionReturnNoticeVisible = false;
            localPreviewLastActionStatus = BeeLocalization.Text("ui.production.return.opened", "Bâtiment de récolte ouvert");
        }

        private static void NavigateToQueueReturnItem()
        {
            if (localPreviewQueueReturnItems.Count == 0) return;
            LocalPreviewQueueReturnItem item = localPreviewQueueReturnItems[0];
            activeMainMenuId = string.Empty;
            detailPanelClosed = true;
            if (string.Equals(item.Kind, "upgrade", StringComparison.Ordinal))
            {
                ReferenceHiveHotspot hotspot = FindReferenceHotspot(item.TargetId);
                if (!string.IsNullOrWhiteSpace(hotspot.HotspotId))
                {
                    activeHiveMenu = HiveMenuMode.Hive;
                    detailPanelClosed = false;
                    SelectReferenceHotspot(hotspot);
                    localPreviewQueueReturnLastRoute = item.TargetId;
                }
            }
            else if (string.Equals(item.Kind, "training", StringComparison.Ordinal))
            {
                selectedLocalTroopType = item.TargetId;
                activeHiveMenu = HiveMenuMode.Army;
                localPreviewQueueReturnLastRoute = "army";
            }
            else
            {
                activeHiveMenu = HiveMenuMode.Research;
                localPreviewQueueReturnLastRoute = "research";
            }

            localPreviewQueueResumeNoticeVisible = false;
            localPreviewLastActionStatus = BeeLocalization.Text("ui.queue.return.opened", "Destination ouverte");
        }

        private static void RestoreLocalPreviewQueue(LocalPreviewQueueOperation operation, bool upgrade)
        {
            if (operation == null || !operation.Exists) return;
            float duration = Mathf.Max(0.1f, (float)new TimeSpan(Math.Max(1L, operation.endsUtcTicks - operation.startedUtcTicks)).TotalSeconds);
            float elapsed = Mathf.Max(0f, (float)new TimeSpan(Math.Max(0L, UtcNowTicks() - operation.startedUtcTicks)).TotalSeconds);

            if (upgrade)
            {
                localPreviewUpgradeHotspotId = operation.targetId;
                localPreviewUpgradeDuration = duration;
                localPreviewUpgradeStartedAt = NowForUi() - elapsed;
                localPreviewUpgradeApplied = operation.completionClaimed;
                if (operation.completionClaimed)
                {
                    int restoredLevel = Mathf.Max(EnsureLocalPreviewLevel(operation.targetId), operation.resultValue);
                    localPreviewBuildingLevels[operation.targetId] = restoredLevel;
                    PersistLocalPreviewBuildingLevel(operation.targetId, restoredLevel);
                    localPreviewLastCompletedUpgradeHotspotId = operation.targetId;
                }
            }
            else
            {
                localPreviewTrainingTroopType = operation.targetId;
                localPreviewTrainingDuration = duration;
                localPreviewTrainingStartedAt = NowForUi() - elapsed;
                localPreviewTrainingApplied = operation.completionClaimed;
                if (operation.completionClaimed)
                {
                    int restoredCount = Mathf.Max(TroopCount(operation.targetId), operation.resultValue);
                    SetTroopCount(operation.targetId, restoredCount);
                    PersistLocalPreviewPopulationCount(PopulationIdForTroopType(operation.targetId), restoredCount);
                    localPreviewLastCompletedTrainingType = operation.targetId;
                }
            }

            localPreviewReservedHoney = operation.honeyCost;
            localPreviewReservedWax = operation.waxCost;
            localPreviewReservedPollen = operation.pollenCost;
            localPreviewLastReservedCostText = QueueOperationCostText(operation);
        }

        private static void RestoreLocalPreviewResearch(LocalPreviewQueueOperation operation)
        {
            if (operation == null || !operation.Exists) return;
            LocalPreviewResearchDefinition definition = LocalPreviewResearchCatalog.Find(operation.targetId);
            if (definition == null) return;

            localPreviewResearchId = operation.targetId;
            localPreviewResearchDuration = Mathf.Max(0.1f, (float)new TimeSpan(Math.Max(1L, operation.endsUtcTicks - operation.startedUtcTicks)).TotalSeconds);
            float elapsed = Mathf.Max(0f, (float)new TimeSpan(Math.Max(0L, UtcNowTicks() - operation.startedUtcTicks)).TotalSeconds);
            localPreviewResearchStartedAt = NowForUi() - elapsed;
            localPreviewResearchApplied = operation.completionClaimed;
            if (operation.completionClaimed) localPreviewLastCompletedResearchId = operation.targetId;
            localPreviewReservedHoney = operation.honeyCost;
            localPreviewReservedWax = operation.waxCost;
            localPreviewReservedPollen = operation.pollenCost;
            localPreviewLastReservedCostText = QueueOperationCostText(operation);
        }

        private static void ApplyLocalPreviewResearchEffects()
        {
            LocalPreviewResearchEffects effects = LocalPreviewResearchCatalog.Derive(localPreviewQueueJournal?.completedResearchIds);
            localPreviewResearchHoneyProductionBonus = effects.HoneyProductionBonus;
            localPreviewResearchWaxCapacityBonus = effects.WaxCapacityBonus;
        }

        private static string QueueOperationCostText(LocalPreviewQueueOperation operation)
        {
            string text = string.Empty;
            if (operation.honeyCost > 0f) text = Mathf.RoundToInt(operation.honeyCost).ToString(CultureInfo.InvariantCulture) + " miel";
            if (operation.waxCost > 0f) text += (text.Length > 0 ? ", " : string.Empty) + Mathf.RoundToInt(operation.waxCost).ToString(CultureInfo.InvariantCulture) + " cire";
            if (operation.pollenCost > 0f) text += (text.Length > 0 ? ", " : string.Empty) + Mathf.RoundToInt(operation.pollenCost).ToString(CultureInfo.InvariantCulture) + " pollen";
            return string.IsNullOrWhiteSpace(text) ? "Aucune ressource engagee" : text + " engages";
        }

        private static LocalPreviewQueueOperation NewQueueOperation(string targetId, float duration, Vector2 primaryCost, bool upgrade)
        {
            long started = UtcNowTicks();
            return new LocalPreviewQueueOperation
            {
                operationId = Guid.NewGuid().ToString("N"),
                targetId = targetId,
                startedUtcTicks = started,
                endsUtcTicks = started + TimeSpan.FromSeconds(Mathf.Max(0.1f, duration)).Ticks,
                honeyCost = primaryCost.x,
                waxCost = upgrade ? primaryCost.y : 0f,
                pollenCost = upgrade ? 0f : primaryCost.y,
                completionClaimed = false,
                resultValue = upgrade
                    ? EnsureLocalPreviewLevel(targetId) + 1
                    : TroopCount(targetId) + TrainingBatchSize(targetId)
            };
        }

        private static LocalPreviewQueueOperation NewResearchQueueOperation(LocalPreviewResearchDefinition definition)
        {
            long started = UtcNowTicks();
            return new LocalPreviewQueueOperation
            {
                operationId = Guid.NewGuid().ToString("N"),
                targetId = definition.ResearchId,
                startedUtcTicks = started,
                endsUtcTicks = started + TimeSpan.FromSeconds(definition.DurationSeconds).Ticks,
                honeyCost = definition.HoneyCost,
                waxCost = 0f,
                pollenCost = definition.PollenCost,
                completionClaimed = false,
                resultValue = 1
            };
        }

