        {
            LocalPreviewQueueJournalCodec.Write(localPreviewQueueJournalStore, localPreviewQueueJournal);
        }

        private static void DrawReferencePolygon(Rect artRect, Vector2[] polygon, Color color, float thickness)
        {
            for (int i = 0; i < polygon.Length; i++)
            {
                Vector2 a = ReferencePoint(artRect, polygon[i].x, polygon[i].y);
                Vector2 b = ReferencePoint(artRect, polygon[(i + 1) % polygon.Length].x, polygon[(i + 1) % polygon.Length].y);
                if (!ClipReferenceOverlayLine(ref a, ref b)) continue;
                DrawGuiLine(a, b, color, thickness);
            }
        }

        private static bool ClipReferenceOverlayLine(ref Vector2 from, ref Vector2 to)
        {
            Rect clip = ReferenceOverlayClipRect();
            float x0 = from.x;
            float y0 = from.y;
            float x1 = to.x;
            float y1 = to.y;
            float dx = x1 - x0;
            float dy = y1 - y0;
            float u0 = 0f;
            float u1 = 1f;

            if (!ClipLineTest(-dx, x0 - clip.xMin, ref u0, ref u1)) return false;
            if (!ClipLineTest(dx, clip.xMax - x0, ref u0, ref u1)) return false;
            if (!ClipLineTest(-dy, y0 - clip.yMin, ref u0, ref u1)) return false;
            if (!ClipLineTest(dy, clip.yMax - y0, ref u0, ref u1)) return false;

            if (u1 < 1f) to = new Vector2(x0 + u1 * dx, y0 + u1 * dy);
            if (u0 > 0f) from = new Vector2(x0 + u0 * dx, y0 + u0 * dy);
            return true;
        }

        private static bool ClipLineTest(float p, float q, ref float u0, ref float u1)
        {
            if (Mathf.Approximately(p, 0f)) return q >= 0f;
            float r = q / p;
            if (p < 0f)
            {
                if (r > u1) return false;
                if (r > u0) u0 = r;
            }
            else
            {
                if (r < u0) return false;
                if (r < u1) u1 = r;
            }

            return true;
        }

        private static Rect ReferenceOverlayClipRect()
        {
            bool portrait = IsPortraitLayout();
            if (portrait)
            {
                float top = 100f;
                float bottom = 270f;
                return new Rect(0f, top, Screen.width, Mathf.Max(1f, Screen.height - top - bottom));
            }

            float left = 156f;
            float topHud = LandscapeTopHudHeight();
            float rightPanel = (referenceHotspotSelected && !detailPanelClosed ? LandscapeContextPanelWidth() + 36f : 24f);
            float bottomRail = LandscapeBottomRailHeight() + 20f;
            return new Rect(left, topHud, Mathf.Max(1f, Screen.width - left - rightPanel), Mathf.Max(1f, Screen.height - topHud - bottomRail));
        }

        private static void DrawGuiLine(Vector2 from, Vector2 to, Color color, float thickness)
        {
            Color previousColor = GUI.color;
            Matrix4x4 previousMatrix = GUI.matrix;
            GUI.color = color;
            float angle = Mathf.Atan2(to.y - from.y, to.x - from.x) * Mathf.Rad2Deg;
            float length = Vector2.Distance(from, to);
            GUIUtility.RotateAroundPivot(angle, from);
            GUI.DrawTexture(new Rect(from.x, from.y - thickness * 0.5f, length, thickness), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            GUI.matrix = previousMatrix;
            GUI.color = previousColor;
        }

        private static void DrawReferenceToken(Rect rect, string icon, Color tint)
        {
            if (!IsReferenceTokenVisible(rect)) return;

            GUI.DrawTexture(new Rect(rect.x - rect.width * 0.18f, rect.y - rect.height * 0.18f, rect.width * 1.36f, rect.height * 1.36f), GetPremiumTexture(icon == "selected" ? "selected-glow" : "soft-shadow"), ScaleMode.ScaleToFit, true);
            DrawGameIcon(rect, icon, tint);
        }

        private static bool IsReferenceTokenVisible(Rect rect)
        {
            const float margin = 8f;
            return rect.x >= margin
                && rect.y >= margin
                && rect.xMax <= Screen.width - margin
                && rect.yMax <= Screen.height - margin;
        }

