        private static void DrawPremiumHiveSurface(bool compact)
        {
            BuildCells();
            bool portrait = IsPortraitLayout();
            GUI.DrawTexture(new Rect(0f, 0f, Screen.width, Screen.height), GetPremiumTexture("cave-background"), ScaleMode.StretchToFill, true);
            float boardW = portrait ? Screen.width + 96f : Mathf.Min(760f, Screen.width - 420f);
            float boardH = portrait ? 392f : 488f;
            float boardX = portrait ? -48f : 190f;
            float boardY = portrait ? 150f : 128f;
            Rect board = new Rect(boardX, boardY, boardW, boardH);
            GUI.DrawTexture(new Rect(board.x - 84f, board.y - 42f, board.width + 168f, board.height + 88f), GetPremiumTexture("cave-vignette"), ScaleMode.StretchToFill, true);
            Rect field = new Rect(board.x + 14f, board.y + 12f, board.width - 28f, board.height - 24f);
            GUI.DrawTexture(field, GetPremiumTexture("wax-field"), ScaleMode.StretchToFill, true);
            GUI.DrawTexture(new Rect(centerless(field).x - field.width * 0.35f, centerless(field).y - field.height * 0.34f, field.width * 0.70f, field.height * 0.68f), GetPremiumTexture("honey-glow-pool"), ScaleMode.StretchToFill, true);
            DrawHiveAmbienceProps(field, portrait);

            float size = portrait ? 112f : 154f;
            Vector2 center = new Vector2(board.x + board.width * 0.51f, board.y + board.height * 0.52f);
            Vector2[] offsets =
            {
                new Vector2(0f, -1.18f),
                new Vector2(-1.06f, -0.48f),
                new Vector2(1.06f, -0.48f),
                new Vector2(-1.08f, 0.62f),
                new Vector2(1.08f, 0.62f),
                new Vector2(0f, 1.06f),
                new Vector2(0f, 0f)
            };
            string[] ids = { "cell-0--1", "cell--1-0", "cell-1--1", "cell--1-1", "cell-1-0", "cell-0-1", "cell-0-0" };
            Rect[] rects = new Rect[ids.Length];
            for (int i = 0; i < ids.Length; i++)
            {
                Vector2 c = center + new Vector2(offsets[i].x * size * 0.92f, offsets[i].y * size * 0.64f);
                rects[i] = new Rect(c.x - size * 0.5f, c.y - size * 0.5f, size, size);
            }

            for (int i = 0; i < rects.Length - 1; i++)
            {
                DrawWaxBridge(rects[6].center, rects[i].center, portrait ? 28f : 42f);
            }

            for (int i = 0; i < ids.Length; i++)
            {
                HiveHexCell cell = CellById(ids[i]) ?? Cells[Mathf.Min(i, Cells.Count - 1)];
                DrawPremiumCell(rects[i], cell, cell.CellId == focusedCellId || ids[i] == "cell-0-0");
            }

            Rect queen = new Rect(center.x - size * 0.46f, center.y - size * 0.73f, size * 0.92f, size * 0.92f);
            GUI.DrawTexture(new Rect(queen.x + 8f, queen.y + 12f, queen.width, queen.height), GetPremiumTexture("soft-shadow"), ScaleMode.StretchToFill, true);
            GUI.DrawTexture(queen, GetPremiumTexture("queen-hive"), ScaleMode.ScaleToFit, true);
        }

        private static void DrawHiveAmbienceProps(Rect field, bool portrait)
        {
            float scale = portrait ? 0.72f : 1f;
            Rect[] wax =
            {
                new Rect(field.x + field.width * 0.10f, field.y + field.height * 0.70f, 92f * scale, 64f * scale),
                new Rect(field.x + field.width * 0.77f, field.y + field.height * 0.18f, 78f * scale, 56f * scale),
                new Rect(field.x + field.width * 0.75f, field.y + field.height * 0.73f, 108f * scale, 62f * scale),
                new Rect(field.x + field.width * 0.14f, field.y + field.height * 0.22f, 76f * scale, 54f * scale)
            };
            for (int i = 0; i < wax.Length; i++) GUI.DrawTexture(wax[i], GetPremiumTexture("wax-blob"), ScaleMode.StretchToFill, true);

            Rect[] moss =
            {
                new Rect(field.x + field.width * 0.07f, field.y + field.height * 0.47f, 94f * scale, 50f * scale),
                new Rect(field.x + field.width * 0.82f, field.y + field.height * 0.50f, 90f * scale, 48f * scale),
                new Rect(field.x + field.width * 0.45f, field.y + field.height * 0.14f, 84f * scale, 46f * scale)
            };
            for (int i = 0; i < moss.Length; i++) GUI.DrawTexture(moss[i], GetPremiumTexture("moss-patch"), ScaleMode.StretchToFill, true);

            if (!portrait)
            {
                DrawGameIcon(new Rect(field.x + 88f, field.y + 72f, 46f, 46f), "bees", Color.white);
                DrawGameIcon(new Rect(field.x + field.width - 136f, field.y + field.height - 92f, 42f, 42f), "worker-bee", Color.white);
                DrawGameIcon(new Rect(field.x + 132f, field.y + field.height - 116f, 40f, 40f), "pollen", Color.white);
                DrawGameIcon(new Rect(field.x + field.width - 176f, field.y + 82f, 38f, 38f), "honey", Color.white);
            }
        }

        private static Vector2 centerless(Rect rect)
        {
            return new Vector2(rect.x + rect.width * 0.5f, rect.y + rect.height * 0.5f);
        }

        private static void DrawPremiumCell(Rect rect, HiveHexCell cell, bool selected)
        {
            GUI.DrawTexture(new Rect(rect.x + 9f, rect.y + 13f, rect.width, rect.height), GetPremiumTexture("cell-shadow"), ScaleMode.ScaleToFit, true);
            if (selected)
            {
                GUI.DrawTexture(new Rect(rect.x - 11f, rect.y - 12f, rect.width + 22f, rect.height + 22f), GetPremiumTexture("selected-glow"), ScaleMode.ScaleToFit, true);
            }

            GUI.DrawTexture(rect, GetPremiumTexture(selected ? "cell-selected" : StateCellTexture(cell.State)), ScaleMode.ScaleToFit, true);
            Rect icon = new Rect(rect.x + rect.width * 0.22f, rect.y + rect.height * 0.15f, rect.width * 0.56f, rect.height * 0.58f);
            DrawCellIllustration(icon, PremiumCellIcon(cell));
            if (cell.State != HiveCellStateKind.Locked && cell.State != HiveCellStateKind.EmptyPreview)
            {
                Rect level = new Rect(rect.center.x - rect.width * 0.17f, rect.yMax - rect.height * 0.30f, rect.width * 0.34f, rect.height * 0.21f);
                DrawPremiumPanel(level, new Color(0.055f, 0.045f, 0.030f, 0.92f), new Color(1f, 0.72f, 0.18f, 0.86f));
                GUI.Label(level, cell.ZoneId == "Storage" ? "25" : "24", centeredTinyLabelStyle);
            }

            if (cell.State == HiveCellStateKind.Locked)
            {
                DrawGameIcon(new Rect(rect.x + rect.width * 0.58f, rect.y + rect.height * 0.06f, rect.width * 0.34f, rect.height * 0.34f), "locked", Color.white);
            }
            else if (cell.State == HiveCellStateKind.ServerRequired)
            {
                DrawGameIcon(new Rect(rect.x + rect.width * 0.56f, rect.y + rect.height * 0.08f, rect.width * 0.34f, rect.height * 0.34f), "server", Color.white);
            }
            else if (cell.State == HiveCellStateKind.EmptyPreview)
            {
                DrawGameIcon(new Rect(rect.x + rect.width * 0.60f, rect.y + rect.height * 0.10f, rect.width * 0.30f, rect.height * 0.30f), "future", Color.white);
            }
            else if (cell.State == HiveCellStateKind.UpgradeCandidate)
            {
                DrawGameIcon(new Rect(rect.x + rect.width * 0.60f, rect.y + rect.height * 0.10f, rect.width * 0.30f, rect.height * 0.30f), "preview", Color.white);
            }
        }

        private static HiveHexCell CellById(string id)
        {
            for (int i = 0; i < Cells.Count; i++)
            {
                if (Cells[i].CellId == id) return Cells[i];
            }

            return null;
        }

        private static void DrawWaxBridge(Vector2 from, Vector2 to, float thickness)
        {
            Vector2 direction = to - from;
            float length = direction.magnitude;
            if (length <= 1f) return;
            float angle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg;
            Rect bridge = new Rect(from.x, from.y - thickness * 0.5f, length, thickness);
            Matrix4x4 previousMatrix = GUI.matrix;
            GUIUtility.RotateAroundPivot(angle, from);
            GUI.DrawTexture(new Rect(bridge.x + 6f, bridge.y + 7f, bridge.width, bridge.height), GetPremiumTexture("wax-bridge-shadow"), ScaleMode.StretchToFill, true);
            GUI.DrawTexture(bridge, GetPremiumTexture("wax-bridge"), ScaleMode.StretchToFill, true);
            GUI.matrix = previousMatrix;
        }

        private static string StateCellTexture(HiveCellStateKind state)
        {
            if (state == HiveCellStateKind.Locked) return "cell-locked";
            if (state == HiveCellStateKind.ServerRequired) return "cell-server";
            if (state == HiveCellStateKind.EmptyPreview) return "cell-future";
            if (state == HiveCellStateKind.UpgradeCandidate) return "cell-preview";
            return "cell-normal";
        }

        private static string PremiumCellIcon(HiveHexCell cell)
        {
            if (cell.ZoneId == "Storage") return "honey";
            if (cell.ZoneId == "Nursery") return "flower";
            if (cell.ZoneId == "Defense") return "sword";
            if (cell.ZoneId == "Research") return "book";
            if (cell.ZoneId == "Production") return "wax";
            return "alliance";
        }

		private static void DrawTopHud(float fps)
		{
			bool previousGuiEnabled = GUI.enabled;
			GUI.enabled = previousGuiEnabled && !ShouldBlockUnderlyingHiveChromeInput();
			try
			{
				SimulateLocalPreviewLoop();
				bool portrait = IsPortraitLayout();
				if (portrait)
				{
					DrawPortraitTopHud();
					return;
				}

				DrawStrategyTopHud(fps);
			}
			finally
			{
				GUI.enabled = previousGuiEnabled;
			}
		}

private static void DrawResourceInventoryOverlay(bool portrait)
        {
            float progress = UIAnimationLibrary.GetFadeProgress("resource_inventory", 1f);
            Rect full = new Rect(0f, 0f, Screen.width, Screen.height);
            GUI.color = new Color(0f, 0f, 0f, 0.78f * progress);
            GUI.DrawTexture(full, Texture2D.blackTexture, ScaleMode.StretchToFill, false);
            GUI.color = Color.white;

            float margin = portrait ? 10f : Mathf.Clamp(Screen.width * 0.035f, 18f, 48f);
            Rect panel = new Rect(margin, portrait ? 12f : 22f, Screen.width - margin * 2f, Screen.height - (portrait ? 24f : 44f));
            panel = UIAnimationLibrary.ApplyWindowAnimation(panel, "resource_inventory");
            float fade = UIAnimationLibrary.GetFadeProgress("resource_inventory", 1f);
            DrawPremiumPanel(panel, new Color(0.018f, 0.014f, 0.009f, 0.985f * fade), new Color(0.94f, 0.64f, 0.16f, 0.96f * fade));

			Rect header = new Rect(panel.x + 12f, panel.y + 12f, panel.width - 24f, portrait ? 52f : 64f);
			DrawPremiumHeaderBand(header);
			if (DrawPremiumBackButton(new Rect(header.x + 2f, header.y + (portrait ? 2f : 8f), portrait ? 44f : 48f, portrait ? 44f : 48f)))
			{
				resourceInventoryOpen = false;
				AudioManager.Instance?.PlayMenuClose();
				return;
			}
			float titleX = portrait ? 56f : 62f;
			GUI.Label(new Rect(header.x + titleX, header.y + 8f, header.width - titleX - 8f, 24f), "RÉSERVES DE LA RUCHE", new GUIStyle(titleStyle) { fontSize = portrait ? 16 : 23 });
			GUI.Label(new Rect(header.x + titleX, header.y + 33f, header.width - titleX - 8f, 18f), "Stocks actuels et capacité suivie", tinyLabelStyle);

            string[] values = DynamicResourceValues(false);
            string[] icons = { "honey", "pollen", "wax", "capacity", "bees" };
            string[] labels = { "MIEL", "POLLEN", "CIRE", "CAPACITÉ", "ABEILLES" };
            string[] subtitles = { "Stock local", "Stock local", "Stock local", "Capacité globale", "Population active" };
            if (!portrait)
            {
                float gap = 10f;
                float cardWidth = (panel.width - 36f - gap * 4f) / 5f;
                float cardTop = header.yMax + 14f;
                float cardHeight = Mathf.Min(282f, panel.height * 0.48f);
                for (int i = 0; i < 5; i++)
                {
                    string value = i == 3 ? values[4] : values[i == 4 ? 3 : i == 1 ? 2 : i == 2 ? 1 : i];
                    DrawResourceReserveCard(new Rect(panel.x + 12f + i * (cardWidth + gap), cardTop, cardWidth, cardHeight), icons[i], labels[i], value, subtitles[i], i);
                }
                DrawResourceReserveSummary(new Rect(panel.x + 12f, cardTop + cardHeight + 14f, panel.width - 24f, panel.height - cardHeight - (header.height + 52f)), portrait);
            }
            else
            {
                float gap = 8f;
                float cardWidth = (panel.width - 24f - gap) / 2f;
                float cardTop = header.yMax + 10f;
                float cardHeight = 182f;
                for (int i = 0; i < 5; i++)
                {
                    string value = i == 3 ? values[4] : values[i == 4 ? 3 : i == 1 ? 2 : i == 2 ? 1 : i];
                    int row = i / 2;
                    int column = i % 2;
                    DrawResourceReserveCard(new Rect(panel.x + 12f + column * (cardWidth + gap), cardTop + row * (cardHeight + gap), cardWidth, cardHeight), icons[i], labels[i], value, subtitles[i], i);
                }
                DrawResourceReserveSummary(new Rect(panel.x + 12f, panel.yMax - 82f, panel.width - 24f, 66f), true);
            }
        }

        private static void DrawResourceReserveCard(Rect rect, string icon, string label, string value, string subtitle, int index)
        {
            Color accent = ResourceAccentColor(index == 3 ? "capacity" : icon);
            DrawPremiumPanel(rect, new Color(0.035f, 0.025f, 0.012f, 0.98f), new Color(accent.r, accent.g, accent.b, 0.90f));
            Rect iconWell = new Rect(rect.x + 10f, rect.y + 12f, Mathf.Min(rect.width - 20f, 96f), Mathf.Min(rect.width - 20f, 96f));
            DrawPremiumPanel(iconWell, new Color(accent.r * 0.12f, accent.g * 0.10f, accent.b * 0.06f, 0.96f), new Color(accent.r, accent.g, accent.b, 0.68f));
            DrawGameIcon(new Rect(iconWell.x + 12f, iconWell.y + 12f, iconWell.width - 24f, iconWell.height - 24f), icon, Color.white);
            GUI.Label(new Rect(rect.x + 10f, iconWell.yMax + 10f, rect.width - 20f, 20f), label, new GUIStyle(badgeStyle) { alignment = TextAnchor.MiddleCenter, fontSize = rect.width < 130f ? 10 : 13 });
            GUI.Label(new Rect(rect.x + 8f, iconWell.yMax + 34f, rect.width - 16f, 30f), value, new GUIStyle(titleStyle) { alignment = TextAnchor.MiddleCenter, fontSize = rect.width < 130f ? 18 : 23 });
            GUI.Label(new Rect(rect.x + 8f, iconWell.yMax + 66f, rect.width - 16f, 18f), subtitle, new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter });
            GUI.Label(new Rect(rect.x + 8f, rect.yMax - 32f, rect.width - 16f, 18f), ResourceRateLabel(index), new GUIStyle(smallStyle) { alignment = TextAnchor.MiddleCenter, normal = { textColor = new Color(0.58f, 0.88f, 0.26f) } });
        }

        private static string ResourceRateLabel(int index)
        {
            if (!OfficialOfflineProductionConfigured() || index > 2) return "Aperçu local";
            string buildingKey = index == 0 ? "honey_storage" : index == 1 ? "warehouse_cells" : "wax_workshop";
            HiveOfflineProductionLineModel line = OfficialOfflineProductionLine(buildingKey);
            if (line == null || line.HourlyRate <= 0m) return "Aperçu local";
            return "+" + FormatResource((float)(line.HourlyRate / 3600m)) + "/s";
        }

