            {
                bool panelOpening = !playerMenuOpen;
                playerMenuOpen = !playerMenuOpen;
                vipMenuOpen = false;
                powerMenuOpen = false;
                if (panelOpening) AudioManager.Instance?.PlayMenuOpen();
                else AudioManager.Instance?.PlayMenuClose();
                localPreviewLoopMessage = playerMenuOpen ? "Profil joueur ouvert" : "Profil joueur ferme";
            }

            Rect vip = new Rect(player.xMax + 8f, 12f, 84f, 32f);
            DrawPremiumPanel(vip, vipMenuOpen ? new Color(0.060f, 0.052f, 0.036f, 0.98f) : new Color(0.050f, 0.045f, 0.032f, 0.88f), new Color(1f, 0.78f, 0.18f, 0.96f));
            bool vipHudOfficial = OfficialVipProgressionConfigured();
            if (vipHudOfficial) EnsureOfficialVipStateLoaded();
            GUI.Label(new Rect(vip.x, vip.y + 2f, vip.width, 16f), vipHudOfficial ? "VIP " + officialVipLevel.ToString(CultureInfo.InvariantCulture) : "VIP —", centeredTinyLabelStyle);
            float vipHudProgress = vipHudOfficial && officialVipNextThreshold.HasValue && officialVipNextThreshold.Value > 0
                ? Mathf.Clamp01((float)officialVipLifetimePoints / officialVipNextThreshold.Value)
                : vipHudOfficial ? 1f : 0f;
            DrawProgressBar(new Rect(vip.x + 10f, vip.yMax - 8f, vip.width - 20f, 4f), vipHudProgress);
            if (GUI.Button(vip, string.Empty, GUIStyle.none))
            {
                bool panelOpening = !vipMenuOpen;
                vipMenuOpen = !vipMenuOpen;
                playerMenuOpen = false;
                powerMenuOpen = false;
                if (panelOpening) AudioManager.Instance?.PlayMenuOpen();
                else AudioManager.Instance?.PlayMenuClose();
                localPreviewLoopMessage = vipMenuOpen ? "Menu VIP ouvert" : "Menu VIP ferme";
                BeginReferenceFeedbackPulse("preview");
            }

            Rect power = new Rect(vip.xMax + 8f, 12f, 150f, 32f);
            DrawPremiumPanel(power, powerMenuOpen ? new Color(0.052f, 0.046f, 0.032f, 0.96f) : new Color(0.032f, 0.030f, 0.024f, 0.86f), powerMenuOpen ? new Color(1f, 0.72f, 0.16f, 0.92f) : new Color(0.72f, 0.54f, 0.20f, 0.82f));
            DrawGameIcon(new Rect(power.x + 8f, power.y + 5f, 22f, 22f), "sword", Color.white);
            GUI.Label(new Rect(power.x + 34f, power.y + 7f, power.width - 42f, 18f), FormatRealPowerNumber(ComputeRealTotalPower()), smallStyle);
            if (GUI.Button(power, string.Empty, GUIStyle.none))
            {
                bool panelOpening = !powerMenuOpen;
                powerMenuOpen = !powerMenuOpen;
                playerMenuOpen = false;
                vipMenuOpen = false;
                if (panelOpening) AudioManager.Instance?.PlayMenuOpen();
                else AudioManager.Instance?.PlayMenuClose();
                localPreviewLoopMessage = powerMenuOpen ? "Detail puissance ouvert" : "Detail puissance ferme";
            }

            Rect champions = new Rect(power.xMax + 8f, 12f, 110f, 32f);
            DrawPremiumPanel(champions, new Color(0.032f, 0.030f, 0.024f, 0.86f), new Color(0.72f, 0.54f, 0.20f, 0.82f));
            DrawGameIcon(new Rect(champions.x + 8f, champions.y + 5f, 22f, 22f), "bees", Color.white);
            GUI.Label(new Rect(champions.x + 34f, champions.y + 7f, champions.width - 42f, 18f), localPreviewAssignedChampionBeeIds.Count + "/" + CurrentMaxAssignedChampionBees(), smallStyle);
            if (GUI.Button(champions, string.Empty, GUIStyle.none))
            {
                championBeesPanelOpen = true;
                championBeesPanelAnimationStartedAt = NowForUi();
                AudioManager.Instance?.PlayMenuOpen();
                playerMenuOpen = false;
                vipMenuOpen = false;
                powerMenuOpen = false;
                localPreviewLoopMessage = "Abeilles championnes ouvert";
            }

            float resourceX = champions.xMax + 12f;
            float resourceAddWidth = 42f;
            float resourceGap = 5f;
            float resourceW = Mathf.Max(82f, (Screen.width - resourceX - resourceAddWidth - 18f - resourceGap * 5f) / 5f);
            string[] values = DynamicResourceValues(false);
            string[] icons = { "honey", "wax", "pollen", "bees", "capacity" };
            string[] labels = { "Miel", "Cire", "Pollen", "Abeilles", "Cap." };
            Rect shelf = new Rect(resourceX - 6f, 4f, Screen.width - resourceX - 4f, 46f);
            DrawTopResourceShelf(shelf);
            for (int i = 0; i < 5; i++)
            {
                Rect chip = new Rect(resourceX + i * (resourceW + resourceGap), 7f, resourceW, 38f);
                DrawStrategyResourcePill(chip, icons[i], labels[i], values[i]);
            }
            Rect addResources = new Rect(resourceX + 5f * (resourceW + resourceGap) + 2f, 8f, resourceAddWidth, 34f);
            DrawPremiumPanel(addResources, new Color(0.055f, 0.043f, 0.024f, 0.94f), new Color(0.96f, 0.68f, 0.18f, 0.92f));
            GUI.Label(addResources, "+", new GUIStyle(titleStyle) { alignment = TextAnchor.MiddleCenter, fontSize = 22 });
            if (GUI.Button(addResources, string.Empty, GUIStyle.none))
            {
                AudioManager.Instance?.PlayUIClick();
                resourceInventoryOpen = true;
                resourceInventoryOpenedAt = NowForUi();
                AudioManager.Instance?.PlayMenuOpen();
                localPreviewLoopMessage = "Réserves de la ruche ouvertes";
            }

            DrawTopSystemButtons(new Rect(Screen.width - 72f, 54f, 60f, 28f));

        }

