        private static void DrawTopSystemButtons(Rect rect)
        {
            if (Screen.width < 1120f) return;
            Rect mail = new Rect(rect.x, rect.y, 26f, 26f);
            Rect alert = new Rect(rect.x + 34f, rect.y, 26f, 26f);
            DrawTopSystemButton(mail, "inbox", "Mail");
            DrawTopSystemButton(alert, "alert", "Alerte");
        }

        private static void DrawTopSystemButton(Rect rect, string icon, string label)
        {
            DrawPremiumPanel(rect, new Color(0.020f, 0.020f, 0.017f, 0.72f), new Color(0.60f, 0.45f, 0.18f, 0.54f));
            DrawGameIcon(new Rect(rect.x + 4f, rect.y + 4f, rect.width - 8f, rect.height - 8f), icon, Color.white);
            if (label == "Mail" && CourierNotificationCount() > 0)
            {
                Rect badge = new Rect(rect.xMax - 10f, rect.y - 5f, 16f, 16f);
                GUI.color = new Color(0.95f, 0.28f, 0.20f, 1f);
                GUI.DrawTexture(badge, Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
                GUI.color = Color.white;
                GUI.Label(badge, CourierNotificationCount() > 9 ? "9+" : CourierNotificationCount().ToString(CultureInfo.InvariantCulture), new GUIStyle(centeredTinyLabelStyle) { fontSize = 7, normal = { textColor = Color.white } });
            }
            if (GUI.Button(rect, string.Empty, GUIStyle.none))
            {
                AudioManager.Instance?.PlayUIClick();
                if (label == "Mail") OpenCourierScreen();
                else
                {
                    localPreviewLoopMessage = label + " - raccourci premium preview";
                    localPreviewLastActionStatus = label;
                    BeginReferenceFeedbackPulse("future");
                }
            }
        }

        private static void DrawConnectionStateBadge(Rect rect, bool portrait = false)
        {
            string label = ConnectionTruthShortLabel(CurrentConnectionTruthState());
            if (string.IsNullOrWhiteSpace(label)) return;

            Color accent;
            switch (CurrentConnectionTruthState())
            {
                case ConnectionTruthState.Offline:
                case ConnectionTruthState.Unavailable:
                    accent = new Color(0.86f, 0.30f, 0.22f, 0.86f);
                    break;
                case ConnectionTruthState.AuthenticatedLive:
                case ConnectionTruthState.AuthenticatedLocal:
                    accent = new Color(0.42f, 0.82f, 0.46f, 0.86f);
                    break;
                case ConnectionTruthState.Authenticating:
                case ConnectionTruthState.Checking:
                    accent = new Color(1f, 0.78f, 0.18f, 0.86f);
                    break;
                default:
                    accent = new Color(0.72f, 0.72f, 0.70f, 0.72f);
                    break;
            }

            DrawPremiumPanel(rect, new Color(0.020f, 0.020f, 0.017f, 0.80f), accent);
            GUIStyle style = new GUIStyle(centeredTinyLabelStyle) { fontSize = portrait ? 8 : 7 };
            GUI.Label(rect, label, style);
        }

        private static Color ResourceAccentColor(string icon)
        {
            switch (icon)
            {
                case "honey": return new Color(1f, 0.68f, 0.12f, 1f);
                case "wax": return new Color(1f, 0.82f, 0.28f, 1f);
                case "pollen": return new Color(0.78f, 0.90f, 0.32f, 1f);
                case "bees": return new Color(0.56f, 0.82f, 1f, 1f);
                case "capacity": return new Color(0.84f, 0.76f, 0.60f, 1f);
                default: return new Color(0.86f, 0.62f, 0.18f, 1f);
            }
        }

        private static int ResourceIndexForIcon(string icon)
        {
            switch (icon)
            {
                case "honey": return 0;
                case "wax": return 1;
                case "pollen": return 2;
                case "bees": return 3;
                case "capacity": return 4;
                default: return -1;
            }
        }

