        private static void DrawPlayerPanelRow(Rect rect, string icon, string label, string value)
        {
            DrawPremiumPanel(rect, new Color(0.020f, 0.021f, 0.018f, 0.58f), new Color(0.58f, 0.44f, 0.18f, 0.40f));
            DrawGameIcon(new Rect(rect.x + 8f, rect.y + 10f, 24f, 24f), icon, Color.white);
