        public static bool PlayerProfileRowsDoNotOverlapForProof()
        {
            Rect level = new Rect(14f, 48f, 272f, 48f);
            Rect statistics = new Rect(14f, 104f, 272f, 44f);
            Rect skills = new Rect(14f, 156f, 272f, 44f);
            Rect charter = new Rect(14f, 232f, 272f, 40f);
            Rect brood = new Rect(14f, 278f, 272f, 40f);
            Rect workers = new Rect(14f, 324f, 272f, 40f);
            Rect workshop = new Rect(14f, 370f, 272f, 40f);
            Rect defense = new Rect(14f, 416f, 272f, 40f);
            return level.yMax <= statistics.y
                && statistics.yMax <= skills.y
                && skills.yMax <= charter.y
                && charter.yMax <= brood.y
                && brood.yMax <= workers.y
                && workers.yMax <= workshop.y
                && workshop.yMax <= defense.y
                && defense.yMax <= PlayerProfilePanelHeight;
        }

private static void DrawStrategicPathPreviewPanel(bool portrait)
        {
            if (!strategicPathPanelOpen) return;

            Rect panel = StrategicPathPanelRectForProof(portrait, Screen.width, Screen.height);
            panel = UIAnimationLibrary.ApplyWindowAnimation(panel, "strategic_path");
            HandleStrategicPathDismissInput(panel);
            if (!strategicPathPanelOpen) return;

            float fade = UIAnimationLibrary.GetFadeProgress("strategic_path", 1f);
            Color previous = GUI.color;
            GUI.color = new Color(0.006f, 0.008f, 0.007f, 0.72f * UIAnimationLibrary.GetFadeProgress("strategic_path", 1f));
            GUI.DrawTexture(new Rect(0f, 0f, Screen.width, Screen.height), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            GUI.color = previous;

			DrawPremiumPanel(panel, new Color(0.025f, 0.024f, 0.020f, 0.99f * fade), new Color(0.92f, 0.64f, 0.18f, 0.94f * fade));
			DrawPremiumHeaderBand(new Rect(panel.x + 10f, panel.y + 8f, panel.width - 20f, 46f));
			if (DrawPremiumBackButton(new Rect(panel.x + 12f, panel.y + 9f, 44f, 44f)))
			{
				CloseStrategicPathPreview();
				return;
			}
            string headerTitle = combatDoctrineOpen
                ? BeeLocalization.Text("combat_doctrine.title", "Doctrine de combat")
                : BeeLocalization.Text("strategic_path.title", "Voie stratégique");
            string headerSubtitle = combatDoctrineOpen
                ? BeeLocalization.Text("combat_doctrine.subtitle", "Trois familles · avantage sans victoire automatique")
                : BeeLocalization.Text("strategic_path.subtitle", "Cinq identités de colonie · aperçu niveau 10+");
            GUI.Label(
                new Rect(panel.x + 56f, panel.y + 11f, panel.width - (portrait ? 202f : 520f), 22f),
                headerTitle,
                new GUIStyle(titleStyle) { fontSize = portrait ? 16 : titleStyle.fontSize });
            GUI.Label(
                new Rect(panel.x + 56f, panel.y + 34f, panel.width - (portrait ? 202f : 520f), 16f),
                headerSubtitle,
                new GUIStyle(tinyLabelStyle) { fontSize = portrait ? 8 : tinyLabelStyle.fontSize });

            Rect mode = CombatDoctrineEntryRectForProof(portrait, Screen.width, Screen.height);
            DrawPremiumPanel(
                mode,
                combatDoctrineOpen ? new Color(0.10f, 0.065f, 0.018f, 0.98f) : new Color(0.030f, 0.034f, 0.032f, 0.96f),
                combatDoctrineOpen ? new Color(1f, 0.72f, 0.18f, 0.92f) : new Color(0.52f, 0.68f, 0.76f, 0.72f));
            GUI.Label(
                new Rect(mode.x + 4f, mode.y + 3f, mode.width - 8f, mode.height - 6f),
                BeeLocalization.Text(combatDoctrineOpen ? "combat_doctrine.entry.back" : "combat_doctrine.entry.open", combatDoctrineOpen ? "VOIES" : "CONTRES"),
                new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter, wordWrap = false, fontSize = portrait ? 9 : 10 });
            if (GUI.Button(mode, string.Empty, GUIStyle.none))
            {
                bool panelOpening = !combatDoctrineOpen;
                combatDoctrineOpen = !combatDoctrineOpen;
                strategicPathTrialOpen = false;
                strategicPathTrialChoice = -1;
                combatDoctrineAttackerIndex = 0;
                combatDoctrineDefenderIndex = -1;
                if (panelOpening) AudioManager.Instance?.PlayMenuOpen();
                else AudioManager.Instance?.PlayMenuClose();
                localPreviewLoopMessage = BeeLocalization.Text(
                    combatDoctrineOpen ? "combat_doctrine.opened" : "combat_doctrine.closed",
                    combatDoctrineOpen ? "Doctrine de combat ouverte" : "Retour aux voies stratégiques");
            }

			Rect authority = portrait
                ? new Rect(panel.x + 14f, panel.y + 62f, panel.width - 28f, 42f)
                : new Rect(panel.xMax - 440f, panel.y + 13f, 294f, 36f);
            DrawPremiumPanel(authority, new Color(0.025f, 0.040f, 0.052f, 0.94f), new Color(0.38f, 0.76f, 1f, 0.80f));
            DrawGameIcon(new Rect(authority.x + 8f, authority.y + 8f, authority.height - 16f, authority.height - 16f), "server", Color.white);
            GUI.Label(
                new Rect(authority.x + authority.height, authority.y + 4f, authority.width - authority.height - 8f, authority.height - 8f),
                BeeLocalization.Text(
                    combatDoctrineOpen ? "combat_doctrine.local_disclosure" : "strategic_path.local_disclosure",
                    combatDoctrineOpen ? "LAB LOCAL · aucun combat simulé" : "APERÇU LOCAL · aucun bonus appliqué"),
                new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleLeft, wordWrap = true });

            if (combatDoctrineOpen)
            {
                DrawCombatDoctrinePanel(panel, portrait);
                ConsumeStrategicPathOverlayInput(panel);
                return;
            }

            Rect[] cards = StrategicPathCardRectsForProof(portrait, Screen.width, Screen.height);
            for (int index = 0; index < HiveStrategicPathCatalog.All.Count; index++)
            {
                HiveStrategicPathDefinition definition = HiveStrategicPathCatalog.All[index];
                DrawStrategicPathCard(cards[index], definition, definition.ClassId == strategicPathPreviewClass, portrait);
            }

            Rect details = StrategicPathDetailRectForProof(portrait, Screen.width, Screen.height);
            if (strategicPathTrialOpen) DrawStrategicPathTrial(details, portrait);
            else DrawStrategicPathDetails(details, portrait);
            ConsumeStrategicPathOverlayInput(panel);
        }

        private static void DrawCombatDoctrinePanel(Rect panel, bool portrait)
        {
            Rect content = CombatDoctrineContentRectForProof(portrait, Screen.width, Screen.height);
            Rect intro = CombatDoctrineIntroRectForProof(portrait, Screen.width, Screen.height);
            DrawPremiumPanel(intro, new Color(0.020f, 0.026f, 0.030f, 0.96f), new Color(0.42f, 0.70f, 0.86f, 0.76f));
            DrawGameIcon(new Rect(intro.x + 10f, intro.y + 10f, portrait ? 30f : 42f, portrait ? 30f : 42f), "sword", Color.white);
            GUI.Label(
                new Rect(intro.x + (portrait ? 50f : 64f), intro.y + 6f, intro.width - (portrait ? 60f : 76f), 20f),
                BeeLocalization.Text("combat_doctrine.intro_title", "Comprendre avant d’engager"),
                badgeStyle);
            GUI.Label(
                new Rect(intro.x + (portrait ? 50f : 64f), intro.y + 26f, intro.width - (portrait ? 60f : 76f), intro.height - 30f),
                BeeLocalization.Text("combat_doctrine.intro_body", "Choisis notre famille puis la menace. Le laboratoire explique le rapport sans calculer un combat."),
                new GUIStyle(tinyLabelStyle) { wordWrap = true, fontSize = portrait ? 9 : 11 });

            Rect[] attackers = CombatDoctrineFamilyRectsForProof(true, portrait, Screen.width, Screen.height);
            Rect[] defenders = CombatDoctrineFamilyRectsForProof(false, portrait, Screen.width, Screen.height);
            GUI.Label(
                new Rect(content.x + 2f, attackers[0].y - (portrait ? 20f : 24f), content.width - 4f, portrait ? 18f : 20f),
                BeeLocalization.Text("combat_doctrine.attacker_label", "NOTRE ESSAIM"),
                badgeStyle);
            GUI.Label(
                new Rect(content.x + 2f, defenders[0].y - (portrait ? 20f : 24f), content.width - 4f, portrait ? 18f : 20f),
                BeeLocalization.Text("combat_doctrine.defender_label", "MENACE OBSERVÉE"),
                badgeStyle);

            for (int index = 0; index < HiveCombatDoctrineCatalog.All.Count; index++)
            {
                HiveCombatDoctrineDefinition definition = HiveCombatDoctrineCatalog.All[index];
                DrawCombatDoctrineFamilyCard(attackers[index], definition, combatDoctrineAttackerIndex == index, portrait, () =>
                {
                    combatDoctrineAttackerIndex = index;
                    localPreviewLoopMessage = BeeLocalization.Text("combat_doctrine.attacker_changed", "Famille alliée observée");
                });
                DrawCombatDoctrineFamilyCard(defenders[index], definition, combatDoctrineDefenderIndex == index, portrait, () =>
                {
                    combatDoctrineDefenderIndex = index;
                    localPreviewLoopMessage = BeeLocalization.Text("combat_doctrine.defender_changed", "Menace observée");
                });
            }

            DrawCombatDoctrineResult(portrait);
            DrawCombatDoctrineCycle(portrait);

            Rect server = CombatDoctrineServerRectForProof(portrait, Screen.width, Screen.height);
            DrawPremiumPanel(server, new Color(0.026f, 0.034f, 0.040f, 0.96f), new Color(0.36f, 0.66f, 0.82f, 0.70f));
            DrawGameIcon(new Rect(server.x + 8f, server.y + 8f, server.height - 16f, server.height - 16f), "server", Color.white);
            GUI.Label(
                new Rect(server.x + server.height, server.y + 3f, server.width - server.height - 8f, server.height - 6f),
                BeeLocalization.Text("combat_doctrine.server_disclosure", "CATALOGUE LOCAL · serveur requis avant combat officiel"),
                new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleLeft, wordWrap = true, fontSize = portrait ? 8 : 10 });
        }

        private static void DrawCombatDoctrineFamilyCard(Rect rect, HiveCombatDoctrineDefinition definition, bool selected, bool portrait, Action onClick)
        {
            Color accent = definition.Accent;
            DrawPremiumPanel(
                rect,
                selected ? new Color(accent.r * 0.16f, accent.g * 0.16f, accent.b * 0.16f, 0.98f) : new Color(0.020f, 0.021f, 0.019f, 0.94f),
                selected ? new Color(accent.r, accent.g, accent.b, 0.94f) : new Color(0.50f, 0.44f, 0.28f, 0.58f));
            float iconSize = portrait ? 26f : 34f;
            Rect icon = new Rect(rect.x + 8f, rect.y + (rect.height - iconSize) * 0.5f, iconSize, iconSize);
            DrawGameIcon(icon, definition.IconId, Color.white);
            GUI.Label(
                new Rect(icon.xMax + 6f, rect.y + 5f, rect.width - iconSize - 20f, portrait ? 16f : 20f),
                BeeLocalization.Text(definition.NameKey, CombatDoctrineFallbackName(definition.Family)),
                new GUIStyle(badgeStyle) { fontSize = portrait ? 9 : 12, normal = { textColor = selected ? accent : badgeStyle.normal.textColor } });
            GUI.Label(
                new Rect(icon.xMax + 6f, rect.y + (portrait ? 21f : 27f), rect.width - iconSize - 20f, rect.height - (portrait ? 24f : 30f)),
                BeeLocalization.Text(definition.RoleKey, CombatDoctrineFallbackRole(definition.Family)),
                new GUIStyle(tinyLabelStyle) { wordWrap = true, fontSize = portrait ? 8 : 10 });
            if (GUI.Button(rect, string.Empty, GUIStyle.none)) onClick?.Invoke();
        }

        private static void DrawCombatDoctrineResult(bool portrait)
        {
            Rect rect = CombatDoctrineResultRectForProof(portrait, Screen.width, Screen.height);
            bool attackerKnown = combatDoctrineAttackerIndex >= 0 && combatDoctrineAttackerIndex < HiveCombatDoctrineCatalog.All.Count;
            bool defenderKnown = combatDoctrineDefenderIndex >= 0 && combatDoctrineDefenderIndex < HiveCombatDoctrineCatalog.All.Count;
            HiveCombatDoctrineDefinition attacker = attackerKnown ? HiveCombatDoctrineCatalog.All[combatDoctrineAttackerIndex] : null;
            HiveCombatDoctrineDefinition defender = defenderKnown ? HiveCombatDoctrineCatalog.All[combatDoctrineDefenderIndex] : null;
            HiveCombatDoctrineOutcome outcome = attackerKnown && defenderKnown
                ? HiveCombatDoctrineCatalog.Evaluate(attacker.Family, defender.Family)
                : HiveCombatDoctrineOutcome.Pending;
            Color accent = outcome == HiveCombatDoctrineOutcome.Advantage
                ? new Color(0.38f, 0.92f, 0.58f, 0.94f)
                : outcome == HiveCombatDoctrineOutcome.Vulnerable
                    ? new Color(1f, 0.48f, 0.30f, 0.94f)
                    : outcome == HiveCombatDoctrineOutcome.Even
                        ? new Color(0.96f, 0.76f, 0.26f, 0.94f)
                        : new Color(0.58f, 0.62f, 0.62f, 0.82f);
            DrawPremiumPanel(rect, new Color(accent.r * 0.08f, accent.g * 0.08f, accent.b * 0.08f, 0.96f), new Color(accent.r, accent.g, accent.b, 0.76f));

            string title;
            string body;
            if (outcome == HiveCombatDoctrineOutcome.Pending)
            {
                title = BeeLocalization.Text("combat_doctrine.outcome.pending.title", "Choisis la menace");
                body = BeeLocalization.Text("combat_doctrine.outcome.pending.body", "Le laboratoire attend les deux familles avant d’expliquer le rapport.");
            }
            else
            {
                string attackerName = BeeLocalization.Text(attacker.NameKey, CombatDoctrineFallbackName(attacker.Family));
                string defenderName = BeeLocalization.Text(defender.NameKey, CombatDoctrineFallbackName(defender.Family));
                string outcomeKey = CombatDoctrineOutcomeId(outcome);
                title = BeeLocalization.Text("combat_doctrine.outcome." + outcomeKey + ".title", "Lecture doctrinale");
                body = BeeLocalization.Format("combat_doctrine.outcome." + outcomeKey + ".body", attackerName, defenderName);
            }

            GUI.Label(new Rect(rect.x + 10f, rect.y + 5f, rect.width - 20f, portrait ? 18f : 22f), title, new GUIStyle(badgeStyle) { normal = { textColor = accent } });
            GUI.Label(
                new Rect(rect.x + 10f, rect.y + (portrait ? 24f : 30f), rect.width - 20f, rect.height - (portrait ? 44f : 52f)),
                body,
                new GUIStyle(tinyLabelStyle) { wordWrap = true, fontSize = portrait ? 9 : 11 });
            GUI.Label(
                new Rect(rect.x + 10f, rect.yMax - (portrait ? 20f : 24f), rect.width - 20f, portrait ? 16f : 18f),
                BeeLocalization.Text("combat_doctrine.balance_rule", "Un contre compte sans décider seul du résultat."),
                new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.LowerLeft, fontStyle = FontStyle.Bold, fontSize = portrait ? 8 : 10 });
        }

        private static void DrawCombatDoctrineCycle(bool portrait)
        {
            Rect rect = CombatDoctrineCycleRectForProof(portrait, Screen.width, Screen.height);
            DrawPremiumPanel(rect, new Color(0.022f, 0.022f, 0.019f, 0.94f), new Color(0.66f, 0.52f, 0.22f, 0.62f));
            GUI.Label(new Rect(rect.x + 10f, rect.y + 4f, rect.width - 20f, 18f), BeeLocalization.Text("combat_doctrine.cycle_title", "CYCLE LISIBLE"), badgeStyle);
            GUI.Label(
                new Rect(rect.x + 10f, rect.y + 22f, rect.width - 20f, 16f),
                BeeLocalization.Text("combat_doctrine.cycle_hint", "Chaque famille a une force et une faiblesse."),
                new GUIStyle(tinyLabelStyle) { fontSize = portrait ? 8 : 10 });

            string[] relations =
            {
                CombatDoctrineRelationLabel(HiveCombatDoctrineFamily.Guardians, HiveCombatDoctrineFamily.Darters),
                CombatDoctrineRelationLabel(HiveCombatDoctrineFamily.Darters, HiveCombatDoctrineFamily.Wingrunners),
                CombatDoctrineRelationLabel(HiveCombatDoctrineFamily.Wingrunners, HiveCombatDoctrineFamily.Guardians)
            };
            if (portrait)
            {
                for (int index = 0; index < relations.Length; index++)
                    GUI.Label(new Rect(rect.x + 12f, rect.y + 39f + index * 15f, rect.width - 24f, 15f), relations[index], new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter, fontSize = 8 });
            }
            else
            {
                float width = (rect.width - 24f) / 3f;
                for (int index = 0; index < relations.Length; index++)
                    GUI.Label(new Rect(rect.x + 12f + index * width, rect.y + 48f, width, rect.height - 56f), relations[index], new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter, wordWrap = true, fontSize = 11 });
            }
        }

        private static string CombatDoctrineRelationLabel(HiveCombatDoctrineFamily stronger, HiveCombatDoctrineFamily weaker)
        {
            HiveCombatDoctrineCatalog.TryResolve(stronger, out HiveCombatDoctrineDefinition strong);
