        // Remplace l'ancien panneau fige "Selection officielle indisponible" par le vrai appel
        // serveur (StrategicPathService.ChooseAsync, deja persiste et verrouille pour toujours -
        // seul manquait le branchement client). Demande explicite de Jeff : chaque voie donne un
        // bonus reel et permanent (puissance de combat, production ou capacite selon la classe).
        private static void DrawStrategicPathOfficialAction(Rect rect, HiveStrategicPathDefinition definition, Color accent)
        {
            if (!OfficialStrategicPathConfigured())
            {
                DrawPremiumPanel(rect, new Color(0.032f, 0.030f, 0.026f, 0.96f), new Color(0.48f, 0.58f, 0.66f, 0.66f));
                DrawGameIcon(new Rect(rect.x + 8f, rect.y + 8f, rect.height - 16f, rect.height - 16f), "locked", Color.white);
                GUI.Label(
                    new Rect(rect.x + rect.height, rect.y + 4f, rect.width - rect.height - 8f, rect.height - 8f),
                    BeeLocalization.Text("strategic_path.official_unavailable", "Sélection officielle indisponible · serveur requis"),
                    new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleLeft, wordWrap = true });
                return;
            }

            StrategicPathScreenModel model = OfficialStrategicPathModel();
            string selected = model?.SelectedPath;
            if (!string.IsNullOrEmpty(selected))
            {
                bool thisOne = string.Equals(selected, definition.Token, StringComparison.Ordinal);
                Color doneAccent = thisOne ? accent : new Color(0.5f, 0.5f, 0.5f, 0.6f);
                DrawPremiumPanel(rect, new Color(doneAccent.r * 0.14f, doneAccent.g * 0.14f, doneAccent.b * 0.14f, 0.98f), doneAccent);
                DrawGameIcon(new Rect(rect.x + 8f, rect.y + 8f, rect.height - 16f, rect.height - 16f), thisOne ? "shield" : "locked", Color.white);
                GUI.Label(
                    new Rect(rect.x + rect.height, rect.y + 4f, rect.width - rect.height - 8f, rect.height - 8f),
                    thisOne
                        ? BeeLocalization.Text("strategic_path.official_selected_this", "Choix définitif de ta ruche")
                        : BeeLocalization.Text("strategic_path.official_selected_other", "Une autre voie a déjà été choisie définitivement"),
                    new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleLeft, wordWrap = true });
                return;
            }

            bool busy = strategicPathController.IsBusy;
            bool hasError = model != null && model.State == StrategicPathScreenState.Error;
            string label = busy
                ? BeeLocalization.Text("strategic_path.official_confirming", "Confirmation en cours…")
                : hasError
                    ? StrategicPathErrorText(model.ErrorCode) + " · " + BeeLocalization.Text("strategic_path.official_retry", "Réessayer")
                    : BeeLocalization.Text("strategic_path.official_confirm", "Choisir définitivement cette voie");
            bool canChoose = !busy && model != null && model.CanChoose(definition.Token);
            if (DrawPreviewActionButton(rect, label, canChoose))
                strategicPathController.Choose(definition.Token);

            if (!string.IsNullOrEmpty(model?.SelectedPath) && string.Equals(model.SelectedPath, definition.Token, StringComparison.Ordinal))
            {
                GUI.Label(new Rect(rect.x, rect.yMax + 4f, rect.width, 20f), StrategicPathBonusSummaryText(definition.Token),
                    new GUIStyle(tinyLabelStyle) { wordWrap = true, normal = { textColor = new Color(1f, 0.82f, 0.42f, 1f) } });
            }
        }

        // Miroir client (affichage uniquement) de StrategicPathBonusCatalog cote serveur - le
        // bonus reel est calcule et applique par le serveur (combat/production/capacite), ceci ne
        // sert qu'a ce que le joueur voie concretement ce que son choix lui apporte.
        private static string StrategicPathBonusSummaryText(string pathToken)
        {
            const string bonusText = "+6%";
            if (pathToken is "royal_guard" or "striker")
                return string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("strategic_path.bonus.combat", "Bonus actif : {0} de puissance de combat"), bonusText);
            if (pathToken is "nurturer" or "alchemist")
                return string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("strategic_path.bonus.production", "Bonus actif : {0} de production"), bonusText);
            if (pathToken == "scout")
                return string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("strategic_path.bonus.capacity", "Bonus actif : {0} de capacité de stockage"), bonusText);
            return string.Empty;
        }

        private static string StrategicPathErrorText(string errorCode)
        {
            if (string.Equals(errorCode, "strategic_path_ineligible", StringComparison.Ordinal))
                return BeeLocalization.Text("strategic_path.error.ineligible", "Niveau de bâtiment insuffisant (niveau 10 requis)");
            if (string.Equals(errorCode, "strategic_path_locked", StringComparison.Ordinal))
                return BeeLocalization.Text("strategic_path.error.locked", "Une voie est déjà choisie définitivement");
            if (string.Equals(errorCode, "revision_conflict", StringComparison.Ordinal))
                return BeeLocalization.Text("strategic_path.error.conflict", "État modifié ailleurs, actualisation requise");
            if (string.Equals(errorCode, "idempotency_conflict", StringComparison.Ordinal))
                return BeeLocalization.Text("strategic_path.error.idempotency", "Demande déjà utilisée pour une autre action");
            if (string.Equals(errorCode, "server_unavailable", StringComparison.Ordinal))
                return BeeLocalization.Text("strategic_path.error.unavailable", "Chemin stratégique fermé sur ce serveur");
            return BeeLocalization.Text("strategic_path.error.generic", "Action indisponible, actualise avant de continuer");
        }

        private static void DrawStrategicPathTrial(Rect rect, bool portrait)
        {
            if (!HiveStrategicPathCatalog.TryResolve(strategicPathPreviewClass, out HiveStrategicPathDefinition definition)) return;
            Color accent = definition.Accent;
            DrawPremiumPanel(rect, new Color(0.018f, 0.020f, 0.019f, 0.96f), new Color(accent.r, accent.g, accent.b, 0.82f));
            DrawGameIcon(new Rect(rect.x + 12f, rect.y + 12f, portrait ? 34f : 44f, portrait ? 34f : 44f), definition.IconId, Color.white);
            GUI.Label(
                new Rect(rect.x + (portrait ? 54f : 66f), rect.y + 8f, rect.width - (portrait ? 118f : 130f), 22f),
                BeeLocalization.Text("strategic_path.trial.title", "Mise en situation"),
                titleStyle);
            GUI.Label(
                new Rect(rect.x + (portrait ? 54f : 66f), rect.y + 31f, rect.width - (portrait ? 118f : 130f), 18f),
                BeeLocalization.Text(definition.NameKey, StrategicPathFallbackName(definition.ClassId)),
                new GUIStyle(badgeStyle) { normal = { textColor = accent } });

            Rect back = StrategicPathTrialBackRectForProof(portrait, Screen.width, Screen.height);
            DrawPremiumPanel(back, new Color(0.040f, 0.035f, 0.026f, 0.96f), new Color(0.76f, 0.60f, 0.26f, 0.72f));
            DrawGameIcon(new Rect(back.x + 10f, back.y + 10f, 24f, 24f), "back", Color.white);
            if (GUI.Button(back, string.Empty, GUIStyle.none))
            {
                strategicPathTrialOpen = false;
                strategicPathTrialChoice = -1;
                localPreviewLoopMessage = BeeLocalization.Text("strategic_path.trial.back", "Retour au profil");
            }

            Rect disclosure = new Rect(rect.x + 12f, rect.y + 56f, rect.width - 24f, portrait ? 24f : 30f);
            DrawPremiumPanel(disclosure, new Color(0.025f, 0.040f, 0.052f, 0.94f), new Color(0.38f, 0.76f, 1f, 0.74f));
            GUI.Label(
                new Rect(disclosure.x + 8f, disclosure.y + 2f, disclosure.width - 16f, disclosure.height - 4f),
                BeeLocalization.Text("strategic_path.trial.local_disclosure", "ESSAI LOCAL · aucun effet de jeu"),
                new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter, wordWrap = true, fontSize = portrait ? 9 : 11 });

            GUIStyle wrap = new GUIStyle(tinyLabelStyle) { wordWrap = true, fontSize = portrait ? 9 : 12 };
            Rect scenario = new Rect(rect.x + 12f, rect.y + (portrait ? 84f : 92f), rect.width - 24f, portrait ? 42f : 48f);
            GUI.Label(
                scenario,
                BeeLocalization.Text(definition.TrialScenarioKey, "Une décision courte révèle le rythme de cette voie."),
                wrap);

            Rect[] choices = StrategicPathTrialChoiceRectsForProof(portrait, Screen.width, Screen.height);
            DrawStrategicPathTrialChoice(choices[0], 0, BeeLocalization.Text(definition.TrialChoiceOneKey, "Première réaction"), accent, strategicPathTrialChoice == 0, portrait);
            DrawStrategicPathTrialChoice(choices[1], 1, BeeLocalization.Text(definition.TrialChoiceTwoKey, "Seconde réaction"), accent, strategicPathTrialChoice == 1, portrait);

            Rect result = StrategicPathTrialResultRectForProof(portrait, Screen.width, Screen.height);
            bool selected = strategicPathTrialChoice >= 0 && strategicPathTrialChoice < 2;
            bool identityFit = selected && strategicPathTrialChoice == definition.PreferredTrialChoice;
            DrawPremiumPanel(
                result,
                selected ? new Color(accent.r * 0.10f, accent.g * 0.10f, accent.b * 0.10f, 0.96f) : new Color(0.030f, 0.030f, 0.026f, 0.88f),
                selected ? new Color(accent.r, accent.g, accent.b, 0.70f) : new Color(0.48f, 0.44f, 0.32f, 0.56f));
            string resultTitle = selected
                ? BeeLocalization.Text(identityFit ? "strategic_path.trial.fit_label" : "strategic_path.trial.tradeoff_label", identityFit ? "Lecture du style" : "Compromis exposé")
                : BeeLocalization.Text("strategic_path.trial.choose", "Choisis une réaction");
            string resultBody = selected
                ? BeeLocalization.Text(identityFit ? definition.TrialFitKey : definition.TrialTradeoffKey, "Le résultat explique cette identité sans modifier la partie.")
                : BeeLocalization.Text("strategic_path.trial.choose_hint", "Les deux réponses restent réversibles dans cet essai.");
            GUI.Label(new Rect(result.x + 8f, result.y + 3f, result.width - 16f, portrait ? 14f : 20f), resultTitle, new GUIStyle(badgeStyle) { normal = { textColor = selected ? accent : badgeStyle.normal.textColor } });
            GUI.Label(new Rect(result.x + 8f, result.y + (portrait ? 17f : 24f), result.width - 16f, result.height - (portrait ? 19f : 28f)), resultBody, new GUIStyle(wrap) { alignment = TextAnchor.UpperLeft });
        }

        private static void DrawStrategicPathTrialChoice(Rect rect, int choiceIndex, string label, Color accent, bool selected, bool portrait)
        {
            DrawPremiumPanel(
                rect,
                selected ? new Color(accent.r * 0.15f, accent.g * 0.15f, accent.b * 0.15f, 0.98f) : new Color(0.026f, 0.027f, 0.024f, 0.96f),
                selected ? new Color(accent.r, accent.g, accent.b, 0.92f) : new Color(0.58f, 0.48f, 0.24f, 0.58f));
            GUI.Label(rect, label, new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter, wordWrap = true, fontSize = portrait ? 9 : 11 });
            if (GUI.Button(rect, string.Empty, GUIStyle.none))
            {
                strategicPathTrialChoice = choiceIndex;
                localPreviewLoopMessage = BeeLocalization.Text("strategic_path.trial.choice_made", "Réaction observée dans l’essai");
            }
        }

