        private static void HandleStrategicPathDismissInput(Rect panel)
        {
            Event current = Event.current;
            if (current == null) return;
            if (current.type == EventType.KeyDown && current.keyCode == KeyCode.Escape)
            {
                CloseStrategicPathPreview();
                current.Use();
                return;
            }
            if (current.type == EventType.MouseUp && current.button == 0 && !panel.Contains(current.mousePosition))
            {
                CloseStrategicPathPreview();
                current.Use();
            }
        }

        private static void ConsumeStrategicPathOverlayInput(Rect panel)
        {
            Event current = Event.current;
            if (current == null || current.type == EventType.Used) return;
            if (current.type == EventType.MouseDown || current.type == EventType.MouseUp || current.type == EventType.ScrollWheel)
            {
                current.Use();
            }
        }

        private static void CloseStrategicPathPreview()
        {
            if (strategicPathPanelOpen) AudioManager.Instance?.PlayMenuClose();
            strategicPathPanelOpen = false;
            strategicPathTrialOpen = false;
            strategicPathTrialChoice = -1;
            combatDoctrineOpen = false;
            combatDoctrineAttackerIndex = 0;
            combatDoctrineDefenderIndex = -1;
            localPreviewLoopMessage = BeeLocalization.Text("strategic_path.closed", "Aperçu des voies fermé");
        }

        private static int CombatDoctrineIndex(string token, int fallback)
        {
            for (int index = 0; index < HiveCombatDoctrineCatalog.All.Count; index++)
            {
                if (string.Equals(HiveCombatDoctrineCatalog.All[index].Token, token, StringComparison.OrdinalIgnoreCase))
                    return index;
            }
            return fallback;
        }

