private static void DrawVipPanel(Rect rect, string animKey = null)
        {
            float fade = animKey != null ? UIAnimationLibrary.GetFadeProgress(animKey, 1f) : 1f;
            bool officialVip = OfficialVipProgressionConfigured();
            if (officialVip) EnsureOfficialVipStateLoaded();

			DrawPremiumPanel(rect, new Color(0.040f, 0.034f, 0.026f, 0.96f * fade), new Color(1f, 0.76f, 0.18f, 0.94f * fade));
			DrawPremiumHeaderBand(new Rect(rect.x + 10f, rect.y + 8f, rect.width - 20f, 30f));
			if (DrawPremiumBackButton(new Rect(rect.x + 4f, rect.y + 2f, 44f, 44f)))
			{
				vipMenuOpen = false;
				localPreviewLoopMessage = "Menu VIP ferme";
				return;
			}
			GUI.Label(new Rect(rect.x + 56f, rect.y + 10f, rect.width - 68f, 22f), "Avantages VIP", titleStyle);

            Rect badge = new Rect(rect.x + 14f, rect.y + 48f, 86f, 66f);
            DrawPremiumPanel(badge, new Color(0.026f, 0.024f, 0.020f, 0.78f), new Color(1f, 0.78f, 0.18f, 0.70f));
            Rect perks = new Rect(rect.x + 108f, rect.y + 48f, rect.width - 122f, 66f);
            DrawPremiumPanel(perks, new Color(0.020f, 0.021f, 0.018f, 0.58f), new Color(0.58f, 0.44f, 0.18f, 0.42f));

            if (!officialVip)
            {
                GUI.Label(new Rect(badge.x, badge.y + 10f, badge.width, 22f), "VIP —", titleStyle);
                GUI.Label(new Rect(badge.x, badge.y + 35f, badge.width, 18f), "—", centeredTinyLabelStyle);
                GUI.Label(new Rect(perks.x + 10f, perks.y + 6f, perks.width - 20f, 14f), "Compte officiel requis", tinyLabelStyle);
                GUI.Label(new Rect(perks.x + 10f, perks.y + 23f, perks.width - 20f, 14f), "Connecte-toi pour voir ta progression VIP.", tinyLabelStyle);
                DrawProgressBar(new Rect(perks.x + 10f, perks.y + 48f, perks.width - 20f, 7f), 0f);
            }
            else
            {
                GUI.Label(new Rect(badge.x, badge.y + 10f, badge.width, 22f), "VIP " + officialVipLevel.ToString(CultureInfo.InvariantCulture), titleStyle);
                GUI.Label(new Rect(badge.x, badge.y + 35f, badge.width, 18f), officialVipLifetimePoints.ToString(CultureInfo.InvariantCulture) + " pts", centeredTinyLabelStyle);

                string perkLine = officialVipCapacityBonusBps > 0
                    ? "Capacite de stockage +" + (officialVipCapacityBonusBps / 100f).ToString("0.#", CultureInfo.InvariantCulture) + "%"
                    : "Aucun bonus actif";
                GUI.Label(new Rect(perks.x + 10f, perks.y + 6f, perks.width - 20f, 14f), perkLine, tinyLabelStyle);
                string progressLine = officialVipNextThreshold.HasValue
                    ? officialVipLifetimePoints + " / " + officialVipNextThreshold.Value + " pts (niveau " + (officialVipLevel + 1) + ")"
                    : "Niveau maximal atteint";
                GUI.Label(new Rect(perks.x + 10f, perks.y + 23f, perks.width - 20f, 14f), progressLine, tinyLabelStyle);
                float progress01 = officialVipNextThreshold.HasValue && officialVipNextThreshold.Value > 0
                    ? Mathf.Clamp01((float)officialVipLifetimePoints / officialVipNextThreshold.Value)
                    : 1f;
                DrawProgressBar(new Rect(perks.x + 10f, perks.y + 48f, perks.width - 20f, 7f), progress01);
            }

            Rect action = new Rect(rect.x + 14f, rect.yMax - 34f, rect.width - 28f, 26f);
            if (officialVip && SplashDevelopmentSceneConfig.IsDevelopmentMenuVisible())
            {
                if (DrawPreviewActionButton(action, officialVipGrantPending ? "Octroi en cours..." : "Test: +100 points VIP", true) && !officialVipGrantPending)
                {
                    GrantTestVipPointsForDevelopment();
                }
            }
            else if (DrawPreviewActionButton(action, "Voir progression VIP", true, true))
            {
                localPreviewLoopMessage = "Progression VIP - menu premium preview";
                localPreviewLastActionStatus = "VIP";
            }
        }

        // Niveau reine et VIP restent hors du score : aucun systeme reel ne les alimente
        // (voir Docs/Claude/Claude_Continuation.md, jalon "Puissance branchee sur l'etat reel").
        private const int PowerWeightPerBuildingLevel = 2000;
        private const int PowerWeightWorker = 500;
        private const int PowerWeightSoldier = 1500;
        private const int PowerWeightGuardian = 2000;
        private const int PowerWeightScout = 1000;
        private const int PowerWeightWingrunner = 1500;
        private const int PowerWeightDarter = 1500;
        private const int PowerWeightResearch = 80000;

        private static int RealPowerFromBuildings()
        {
            EnsureLocalPreviewQueueJournalLoaded();
            int totalLevels = 0;
            foreach (int level in localPreviewBuildingLevels.Values) totalLevels += level;
            return totalLevels * PowerWeightPerBuildingLevel;
        }

        private static int RealPowerFromBees()
        {
            EnsureLocalPreviewQueueJournalLoaded();
            return Mathf.RoundToInt(localPreviewWorkers * PowerWeightWorker
                + localPreviewSoldiers * PowerWeightSoldier * TroopTierMultiplier("soldiers")
                + localPreviewGuardians * PowerWeightGuardian * TroopTierMultiplier("guardians")
                + localPreviewScouts * PowerWeightScout * TroopTierMultiplier("scouts")
                + localPreviewWingrunners * PowerWeightWingrunner
                + localPreviewDarters * PowerWeightDarter);
        }

        private static int RealPowerFromResearch()
        {
            EnsureLocalPreviewQueueJournalLoaded();
            return localPreviewQueueJournal.completedResearchIds.Count * PowerWeightResearch;
        }

        private static int ComputeRealTotalPower()
        {
            return RealPowerFromBuildings() + RealPowerFromBees() + RealPowerFromResearch();
        }

        private static string FormatRealPowerNumber(int value)
        {
            return value.ToString("N0", CultureInfo.InvariantCulture);
        }

private static void DrawPowerPanel(Rect rect, string animKey = null)
        {
            float fade = animKey != null ? UIAnimationLibrary.GetFadeProgress(animKey, 1f) : 1f;
            int equipmentPower = RealPowerFromBuildings();
            int beesPower = RealPowerFromBees();
            int researchPower = RealPowerFromResearch();
            int totalPower = equipmentPower + beesPower + researchPower;
            float equipmentShare = totalPower > 0 ? (float)equipmentPower / totalPower : 0f;
            float beesShare = totalPower > 0 ? (float)beesPower / totalPower : 0f;
            float researchShare = totalPower > 0 ? (float)researchPower / totalPower : 0f;

			DrawPremiumPanel(rect, new Color(0.034f, 0.030f, 0.023f, 0.96f * fade), new Color(0.92f, 0.64f, 0.18f, 0.88f * fade));
			DrawPremiumHeaderBand(new Rect(rect.x + 10f, rect.y + 8f, rect.width - 20f, 30f));
			if (DrawPremiumBackButton(new Rect(rect.x + 4f, rect.y + 2f, 44f, 44f)))
			{
				powerMenuOpen = false;
				localPreviewLoopMessage = "Detail puissance ferme";
				return;
			}
			GUI.Label(new Rect(rect.x + 56f, rect.y + 10f, rect.width - 68f, 22f), "Puissance", titleStyle);
			GUI.Label(new Rect(rect.xMax - 116f, rect.y + 12f, 100f, 18f), FormatRealPowerNumber(totalPower), badgeStyle);

            DrawPowerBreakdownRow(new Rect(rect.x + 14f, rect.y + 48f, rect.width - 28f, 25f), "sword", "Equipement", FormatRealPowerNumber(equipmentPower), equipmentShare);
            DrawPowerBreakdownRow(new Rect(rect.x + 14f, rect.y + 77f, rect.width - 28f, 25f), "queen", "Niveau reine", "—", 0f);
            DrawPowerBreakdownRow(new Rect(rect.x + 14f, rect.y + 106f, rect.width - 28f, 25f), "bees", "Abeilles spec.", FormatRealPowerNumber(beesPower), beesShare);
            DrawPowerBreakdownRow(new Rect(rect.x + 14f, rect.y + 135f, rect.width - 28f, 25f), "research", "Competences", FormatRealPowerNumber(researchPower), researchShare);
        }

		private static Texture2D LeftNavigationTexture()
		{
			if (leftNavigationTexture != null) return leftNavigationTexture;
#if UNITY_EDITOR
			leftNavigationTexture = UnityEditor.AssetDatabase.LoadAssetAtPath<Texture2D>(LeftNavigationAssetPath);
#endif
if (leftNavigationTexture == null)
				leftNavigationTexture = Resources.Load<Texture2D>("UI/Navigation/closing_arrow");
			return leftNavigationTexture;
		}

		private static bool DrawPremiumBackButton(Rect visual)
		{
			Texture2D texture = LeftNavigationTexture();
			if (texture != null)
			{
				Color previous = GUI.color;
				GUI.color = Color.white;
				GUI.DrawTexture(visual, texture, ScaleMode.ScaleToFit, true);
				GUI.color = previous;
			}
			else
			{
				GUI.Label(visual, "\u2190", new GUIStyle(centeredTinyLabelStyle) { fontSize = 22 });
			}

			float width = Mathf.Max(52f, visual.width);
			float height = Mathf.Max(52f, visual.height);
			Rect hit = new Rect(
				visual.x - (width - visual.width) * 0.5f,
				visual.y - (height - visual.height) * 0.5f,
				width,
				height);
			return GUI.Button(hit, string.Empty, GUIStyle.none);
		}

        public static bool DrawPremiumBackButtonForExternalHost(Rect visual)
        {
            return DrawPremiumBackButton(visual);
        }

		// Zone de clic confortable pour les petits controles du mini-chat.
		private static bool DrawPremiumHitButton(Rect visual, string label = "", int fontSize = 14)
        {
            GUI.Label(visual, label, new GUIStyle(centeredTinyLabelStyle) { fontSize = fontSize });
            float w = Mathf.Max(44f, visual.width);
            float h = Mathf.Max(44f, visual.height);
            Rect hit = new Rect(visual.x - (w - visual.width) * 0.5f, visual.y - (h - visual.height) * 0.5f, w, h);
            return GUI.Button(hit, string.Empty, GUIStyle.none);
        }

