        // Portrait fourni par Jeff (dossier externe imagesA copier dans
        // Resources/PremiumBeeReference/ChampionBees/<id>.png) ; retombe sur null si absent, l'appelant
        // dessine alors l'icone couronne teintee par rarete a la place.
        private static Texture2D ChampionBeePortraitTexture(string beeId)
        {
            if (string.IsNullOrWhiteSpace(beeId)) return null;
            if (championBeePortraitCache.TryGetValue(beeId, out Texture2D cached)) return cached;
            Texture2D loaded = Resources.Load<Texture2D>("PremiumBeeReference/ChampionBees/" + beeId);
            championBeePortraitCache[beeId] = loaded;
            return loaded;
        }

        private static void DrawChampionBeePortrait(Rect rect, ChampionBeeDefinition definition)
        {
            Texture2D portrait = ChampionBeePortraitTexture(definition.Id);
            if (portrait != null)
            {
                GUI.DrawTexture(rect, portrait, ScaleMode.ScaleAndCrop, true);
                return;
            }

            DrawPremiumPanel(rect, new Color(0.020f, 0.019f, 0.016f, 0.70f), ChampionBeeRarityColor(definition.Rarity) * new Color(1f, 1f, 1f, 0.6f));
            DrawGameIcon(new Rect(rect.x + rect.width * 0.2f, rect.y + rect.height * 0.2f, rect.width * 0.6f, rect.height * 0.6f), "bees", ChampionBeeRarityColor(definition.Rarity));
        }

