        private const float ChampionBeesOverlayAnimationSeconds = 0.22f;

        private static float ChampionBeesOverlayAnimationProgress01()
        {
            if (productionReducedMotionForProof) return 1f;
            float elapsed = NowForUi() - championBeesPanelAnimationStartedAt;
            if (elapsed <= 0f) return 0f;
            if (elapsed >= ChampionBeesOverlayAnimationSeconds) return 1f;
            float t = elapsed / ChampionBeesOverlayAnimationSeconds;
            return 1f - Mathf.Pow(1f - t, 3f);
        }

        private static Rect ScaledAroundCenter(Rect rect, float scale)
        {
            float width = rect.width * scale;
            float height = rect.height * scale;
            return new Rect(rect.center.x - width * 0.5f, rect.center.y - height * 0.5f, width, height);
        }

        private static void DrawChampionBeesOverlay(bool compact)
        {
            float animT = ChampionBeesOverlayAnimationProgress01();

            Color previousColor = GUI.color;
            GUI.color = new Color(0f, 0f, 0f, 0.72f * animT);
            GUI.DrawTexture(new Rect(0f, 0f, Screen.width, Screen.height), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            GUI.color = previousColor;

            float panelWidth = compact ? Screen.width - 24f : 520f;
            float panelHeight = compact ? Screen.height - 40f : 560f;
            Rect panel = new Rect((Screen.width - panelWidth) * 0.5f, (Screen.height - panelHeight) * 0.5f, panelWidth, panelHeight);
			panel = ScaledAroundCenter(panel, Mathf.Lerp(0.94f, 1f, animT));
			DrawPremiumPanel(panel, new Color(0.034f, 0.030f, 0.023f, 0.98f), new Color(0.92f, 0.64f, 0.18f, 0.90f));
			DrawPremiumHeaderBand(new Rect(panel.x + 10f, panel.y + 8f, panel.width - 20f, 34f));
			if (DrawPremiumBackButton(new Rect(panel.x + 12f, panel.y + 2f, 44f, 44f)))
			{
				championBeesPanelOpen = false;
				championBeesDetailBeeId = string.Empty;
				AudioManager.Instance?.PlayMenuClose();
				return;
			}
			GUI.Label(new Rect(panel.x + 58f, panel.y + 10f, panel.width - 70f, 24f), BeeLocalization.Text("champion_bees.title", "Abeilles championnes"), titleStyle);

            if (!string.IsNullOrWhiteSpace(championBeesDetailBeeId) && ChampionBeeCatalog.TryResolve(championBeesDetailBeeId, out ChampionBeeDefinition detail))
            {
                DrawChampionBeeDetail(panel, detail);
                return;
            }

            bool championVoiceDebugPanelVisible = SplashDevelopmentSceneConfig.IsDevelopmentMenuVisible();
            float championVoiceDebugPanelHeight = championVoiceDebugPanelVisible ? 64f : 0f;
            if (championVoiceDebugPanelVisible)
            {
                DrawChampionVoiceDebugPanel(new Rect(panel.x + 14f, panel.y + 44f, panel.width - 28f, championVoiceDebugPanelHeight - 4f));
            }

            int currentMaxAssigned = CurrentMaxAssignedChampionBees();
            GUI.Label(
                new Rect(panel.x + 16f, panel.y + 46f + championVoiceDebugPanelHeight, panel.width - 32f, 34f),
                BeeLocalization.Text("champion_bees.subtitle", "Assigne des abeilles championnes pour accompagner tes troupes en recolte et en combat. Une troupe commune ne part jamais seule.")
                    + " (" + localPreviewAssignedChampionBeeIds.Count + "/" + currentMaxAssigned + ")",
                new GUIStyle(tinyLabelStyle) { wordWrap = true });

            float tabBarHeight = 30f;
            float listY = panel.y + 84f + championVoiceDebugPanelHeight;
            float listHeight = panel.height - 84f - championVoiceDebugPanelHeight - tabBarHeight - 44f;
            Rect listRect = new Rect(panel.x + 14f, listY, panel.width - 28f, listHeight);

            IReadOnlyList<ChampionBeeDefinition> all = ChampionBeeCatalog.All;
            var filtered = new List<ChampionBeeDefinition>();
            for (int i = 0; i < all.Count; i++)
            {
                if (string.IsNullOrEmpty(championBeesRoleFilter) || string.Equals(ChampionBeeFilterId(all[i].Role), championBeesRoleFilter, StringComparison.Ordinal))
                    filtered.Add(all[i]);
            }

            float rowHeight = 68f;
            Rect viewRect = new Rect(0f, 0f, listRect.width - 18f, filtered.Count * (rowHeight + 6f));
            championBeesScroll = GUI.BeginScrollView(listRect, championBeesScroll, viewRect);
            float rowY = 0f;
            for (int i = 0; i < filtered.Count; i++)
            {
                DrawChampionBeeListRow(new Rect(0f, rowY, viewRect.width, rowHeight), filtered[i]);
                rowY += rowHeight + 6f;
            }
            GUI.EndScrollView();

            Rect tabBar = new Rect(panel.x + 14f, listRect.yMax + 6f, panel.width - 28f, tabBarHeight);
            float tabW = tabBar.width / ChampionBeeTabs.Length;
            for (int i = 0; i < ChampionBeeTabs.Length; i++)
            {
                (string filter, string labelKey, string fallback) = ChampionBeeTabs[i];
                bool selected = string.Equals(championBeesRoleFilter, filter, StringComparison.Ordinal);
                Rect tabRect = new Rect(tabBar.x + i * tabW, tabBar.y, tabW - 3f, tabBar.height);
                DrawPremiumPanel(tabRect, selected ? new Color(0.052f, 0.046f, 0.032f, 0.96f) : new Color(0.024f, 0.023f, 0.020f, 0.62f), selected ? new Color(1f, 0.72f, 0.16f, 0.92f) : new Color(0.52f, 0.42f, 0.22f, 0.5f));
                GUI.Label(tabRect, BeeLocalization.Text(labelKey, fallback), centeredTinyLabelStyle);
                if (GUI.Button(tabRect, string.Empty, GUIStyle.none)) { AudioManager.Instance?.PlayUIClick(); championBeesRoleFilter = filter; championBeesScroll = Vector2.zero; }
            }

            GUI.Label(
                new Rect(panel.x + 16f, tabBar.yMax + 6f, panel.width - 32f, 30f),
                BeeLocalization.Text("champion_bees.bonus_summary_prefix", "Bonus de recolte actif") + ": +"
                    + ChampionBeeProductionBonusPercent().ToString("0.#", CultureInfo.InvariantCulture) + "%",
                new GUIStyle(tinyLabelStyle) { wordWrap = true });
        }

        // Panneau de diagnostic temporaire (demande de Jeff, 2026-08-05) pour determiner par execution
        // reelle si le silence des voix des Championnes vient des fichiers audio eux-memes ou des
        // evenements qui doivent les declencher. Visible uniquement en Editeur/Development build (meme
        // garde que le reste du menu Developpement) - a retirer ou conserver en mode dev uniquement une
        // fois le diagnostic termine.
        private static readonly string[] ChampionVoiceDebugBeeIds = { "striga", "zephyra", "ambra" };

        private static void DrawChampionVoiceDebugPanel(Rect rect)
        {
            GUI.Label(new Rect(rect.x, rect.y, rect.width, 14f), "DEBUG VOIX CHAMPIONNES (dev uniquement)", new GUIStyle(tinyLabelStyle) { normal = { textColor = new Color(1f, 0.55f, 0.2f, 1f) } });

            float buttonHeight = 22f;
            float gap = 4f;
            float buttonWidth = (rect.width - gap * 2f) / 3f;
            float row1Y = rect.y + 16f;
            float row2Y = row1Y + buttonHeight + gap;

            for (int i = 0; i < ChampionVoiceDebugBeeIds.Length; i++)
            {
                string beeId = ChampionVoiceDebugBeeIds[i];
                string displayName = ChampionBeeCatalog.TryResolve(beeId, out ChampionBeeDefinition definition) ? ChampionBeeName(definition) : beeId;

                Rect spawnRect = new Rect(rect.x + i * (buttonWidth + gap), row1Y, buttonWidth, buttonHeight);
                if (GUI.Button(spawnRect, "Spawn " + displayName))
                {
                    TriggerChampionVoiceDebugSpawn(beeId);
                }

                Rect selectRect = new Rect(rect.x + i * (buttonWidth + gap), row2Y, buttonWidth, buttonHeight);
                if (GUI.Button(selectRect, "Select " + displayName))
                {
                    TriggerChampionVoiceDebugSelect(beeId);
                }
            }
        }

        private static void TriggerChampionVoiceDebugSelect(string beeId)
        {
            LogChampionVoiceDebugState("AVANT Select", beeId, "select");
            ChampionVoiceBarkController.BarkForSelection(beeId);
            LogChampionVoiceDebugState("APRES Select", beeId, "select");
        }

        private static void TriggerChampionVoiceDebugSpawn(string beeId)
        {
            var committedTroops = new Dictionary<string, long>(StringComparer.Ordinal);
            if (ChampionBeeCatalog.TryResolve(beeId, out ChampionBeeDefinition definition))
            {
                committedTroops[ChampionBeeCatalog.CombatFamilyId(definition.Role)] = 1L;
            }

            LogChampionVoiceDebugState("AVANT Spawn", beeId, "patrol_launch");
            ChampionVoiceBarkController.BarkForPatrolLaunch(new[] { beeId }, committedTroops);
            LogChampionVoiceDebugState("APRES Spawn", beeId, "patrol_launch");
        }

        private static void LogChampionVoiceDebugState(string label, string beeId, string eventKey)
        {
            try
            {
                var staticFlags = System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static;
                Type barkType = typeof(ChampionVoiceBarkController);
                float busyUntil = (float)barkType.GetField("busyUntilUnscaledTime", staticFlags).GetValue(null);
                var lastBarkTimeByEvent = barkType.GetField("lastBarkTimeByEvent", staticFlags).GetValue(null) as System.Collections.Generic.IDictionary<string, float>;
                float lastBarkTime = lastBarkTimeByEvent != null && lastBarkTimeByEvent.TryGetValue(eventKey, out float t) ? t : -1f;

                AudioClip[] selectClips = Resources.LoadAll<AudioClip>("PremiumBeeReference/ChampionVoices/" + beeId + "/select");
                AudioClip[] spawnClips = Resources.LoadAll<AudioClip>("PremiumBeeReference/ChampionVoices/" + beeId + "/spawn");

                BeeKingdom.Audio.AudioManager audioManager = BeeKingdom.Audio.AudioManager.Instance;
                string audioManagerState;
                if (audioManager == null)
                {
                    audioManagerState = "AudioManager.Instance=null (jamais cree encore)";
                }
                else
                {
                    var instanceFlags = System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance;
                    var sfxSource = typeof(BeeKingdom.Audio.AudioManager).GetField("sfxSource", instanceFlags)?.GetValue(audioManager) as AudioSource;
                    audioManagerState = "sfxSource=" + (sfxSource == null ? "NULL (Start() pas encore execute)" : ("clip=" + (sfxSource.clip != null ? sfxSource.clip.name : "aucun") + " isPlaying=" + sfxSource.isPlaying))
                        + " soundEnabled=" + audioManager.IsSoundEnabled;
                }

                Debug.Log("[ChampionVoiceDebug] " + label + " beeId=" + beeId + " eventKey=" + eventKey
                    + " | Time.unscaledTime=" + Time.unscaledTime.ToString("0.00", CultureInfo.InvariantCulture)
                    + " busyUntilUnscaledTime=" + busyUntil.ToString("0.00", CultureInfo.InvariantCulture)
                    + " lastBarkTime[" + eventKey + "]=" + lastBarkTime.ToString("0.00", CultureInfo.InvariantCulture)
                    + " | clips select=" + selectClips.Length + " spawn=" + spawnClips.Length
                    + " | " + audioManagerState);
            }
            catch (Exception ex)
            {
                Debug.LogWarning("[ChampionVoiceDebug] Erreur de diagnostic: " + ex.Message);
            }
        }

        private static void DrawChampionBeeListRow(Rect rect, ChampionBeeDefinition definition)
        {
            bool unlocked = IsChampionBeeUnlocked(definition);
            bool owned = IsChampionBeeOwned(definition.Id);
            int level = ChampionBeeLevel(definition.Id);

            DrawPremiumPanel(rect, new Color(0.022f, 0.021f, 0.018f, 0.62f), ChampionBeeRarityColor(definition.Rarity) * new Color(1f, 1f, 1f, 0.55f));
            DrawChampionBeePortrait(new Rect(rect.x + 6f, rect.y + 6f, rect.height - 12f, rect.height - 12f), definition);

            float textX = rect.x + rect.height + 4f;
            string nameLine = ChampionBeeRarityLabel(definition.Rarity) + " - " + ChampionBeeRoleLabel(definition.Role);
            GUI.Label(new Rect(textX, rect.y + 6f, rect.xMax - textX - 90f, 20f), ChampionBeeName(definition), new GUIStyle(badgeStyle) { fontSize = IsPortraitLayout() ? 12 : 13, alignment = TextAnchor.MiddleLeft });
            GUI.Label(new Rect(textX, rect.y + 26f, rect.xMax - textX - 90f, 16f), nameLine, new GUIStyle(tinyLabelStyle) { fontSize = IsPortraitLayout() ? 8 : 9 });

            string stateLine;
            if (!unlocked)
                stateLine = BeeLocalization.Text("champion_bees.locked_short", "Verrouille - niveau") + " " + ChampionBeeCatalog.UnlockCoeurRoyalLevel(definition.Rarity);
            else if (!owned)
                stateLine = BeeLocalization.Text("champion_bees.not_owned", "Non obtenue");
            else
                stateLine = BeeLocalization.Text("champion_bees.level_label", "Niv.") + " " + level + "/" + LocalPreviewHiveProgressCodec.MaxChampionBeeLevel
                    + (IsChampionBeeAssigned(definition.Id) ? " - " + BeeLocalization.Text("champion_bees.in_mission", "En mission") : string.Empty);
            GUI.Label(new Rect(textX, rect.y + 46f, rect.xMax - textX - 90f, 18f), stateLine, tinyLabelStyle);

            Rect chevron = new Rect(rect.xMax - 74f, rect.y + rect.height * 0.5f - 14f, 68f, 28f);
            if (DrawPreviewActionButton(chevron, BeeLocalization.Text("champion_bees.view", "Voir"), true, true))
            {
                championBeesDetailBeeId = definition.Id;
                ChampionVoiceBarkController.BarkForSelection(definition.Id);
            }
        }

        private static void DrawChampionBeeDetail(Rect panel, ChampionBeeDefinition definition)
        {
            bool unlocked = IsChampionBeeUnlocked(definition);
            bool owned = IsChampionBeeOwned(definition.Id);
            int level = ChampionBeeLevel(definition.Id);

            if (DrawPreviewActionButton(new Rect(panel.x + 14f, panel.y + 46f, 90f, 26f), BeeLocalization.Text("champion_bees.back", "Retour"), true, true))
            {
                championBeesDetailBeeId = string.Empty;
                return;
            }

            float portraitSize = Mathf.Min(168f, panel.width - 40f);
            Rect portraitRect = new Rect(panel.x + (panel.width - portraitSize) * 0.5f, panel.y + 80f, portraitSize, portraitSize);
            DrawChampionBeePortrait(portraitRect, definition);

            float centerX = panel.x + 14f;
            float centerWidth = panel.width - 28f;
            float textY = portraitRect.yMax + 8f;
            GUI.Label(new Rect(centerX, textY, centerWidth, 24f), ChampionBeeName(definition), new GUIStyle(titleStyle) { alignment = TextAnchor.UpperCenter });
            textY += 24f;
            GUI.Label(new Rect(centerX, textY, centerWidth, 18f), ChampionBeeRarityLabel(definition.Rarity) + " - " + ChampionBeeRoleLabel(definition.Role), centeredTinyLabelStyle);
            textY += 18f;
            if (owned)
            {
                GUI.Label(new Rect(centerX, textY, centerWidth, 18f), BeeLocalization.Text("champion_bees.level_label", "Niv.") + " " + level + "/" + LocalPreviewHiveProgressCodec.MaxChampionBeeLevel, new GUIStyle(badgeStyle) { alignment = TextAnchor.UpperCenter });
                textY += 18f;
            }

            int effectLevel = Mathf.Max(1, level);
            string effectLine = definition.Role == ChampionBeeRole.Civilian
                ? "+" + (definition.ProductionBonusPercentPerLevel * effectLevel).ToString("0.#", CultureInfo.InvariantCulture) + "% " + BeeLocalization.Text("champion_bees.effect.production", "production recolte")
                : "+" + (definition.ArmyBonusPerLevel * effectLevel) + " " + BeeLocalization.Text("champion_bees.effect.army", "capacite") + ", +"
                    + (definition.RoleStatBonusPercentPerLevel * effectLevel).ToString("0.#", CultureInfo.InvariantCulture) + "% " + ChampionBeeRoleLabel(definition.Role);
            GUI.Label(new Rect(centerX, textY, centerWidth, 18f), effectLine, new GUIStyle(tinyLabelStyle) { fontSize = 11, alignment = TextAnchor.UpperCenter });
            textY += 26f;

            GUI.Label(new Rect(centerX, textY, centerWidth, 20f), BeeLocalization.Text("champion_bees.lore_title", "Hauts faits"), badgeStyle);
            textY += 22f;
            GUIStyle loreStyle = new GUIStyle(smallStyle) { wordWrap = true, alignment = TextAnchor.UpperLeft };
            float loreHeight = loreStyle.CalcHeight(new GUIContent(ChampionBeeLore(definition)), centerWidth);
            GUI.Label(new Rect(centerX, textY, centerWidth, loreHeight), ChampionBeeLore(definition), loreStyle);

            Rect actionRect = new Rect(panel.x + 14f, panel.yMax - 44f, panel.width - 28f, 32f);
            if (!unlocked)
            {
                GUI.Label(
                    actionRect,
                    BeeLocalization.Text("champion_bees.locked", "Verrouille - Coeur royal niveau") + " " + ChampionBeeCatalog.UnlockCoeurRoyalLevel(definition.Rarity) + " requis",
                    new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter });
                return;
            }

            if (!owned)
            {
                Rect eventButton = new Rect(actionRect.x, actionRect.y, actionRect.width * 0.5f - 4f, actionRect.height);
                Rect buyButton = new Rect(eventButton.xMax + 8f, actionRect.y, actionRect.width * 0.5f - 4f, actionRect.height);
                if (DrawPreviewActionButton(eventButton, BeeLocalization.Text("champion_bees.obtain_event", "Obtenir (evenement)"), true))
                    GrantChampionBee(definition);
                if (DrawPreviewActionButton(buyButton, BeeLocalization.Text("champion_bees.obtain_purchase", "Acheter (demo)"), true))
                    GrantChampionBee(definition);
                return;
            }

            bool maxed = level >= LocalPreviewHiveProgressCodec.MaxChampionBeeLevel;
            Vector2 cost = ChampionBeeCatalog.LevelUpCost(definition, level);
            bool canAfford = localPreviewHoney >= cost.x && localPreviewPollen >= cost.y;
            Rect upgradeButton = new Rect(actionRect.x, actionRect.y, actionRect.width * 0.55f - 4f, actionRect.height);
            Rect assignButton = new Rect(upgradeButton.xMax + 8f, actionRect.y, actionRect.width * 0.45f - 4f, actionRect.height);

            string upgradeLabel = maxed
                ? BeeLocalization.Text("champion_bees.max_level", "Niveau max")
                : BeeLocalization.Text("champion_bees.upgrade_action", "Ameliorer") + " (" + Mathf.RoundToInt(cost.x) + " m, " + Mathf.RoundToInt(cost.y) + " p)";
            if (DrawPreviewActionButton(upgradeButton, upgradeLabel, !maxed && canAfford))
                LevelUpChampionBee(definition);

            bool assigned = IsChampionBeeAssigned(definition.Id);
            string assignLabel = assigned
                ? BeeLocalization.Text("champion_bees.unassign", "Retirer de la mission")
                : BeeLocalization.Text("champion_bees.assign", "Envoyer en mission");
            bool canAssign = assigned || localPreviewAssignedChampionBeeIds.Count < CurrentMaxAssignedChampionBees();
            if (DrawPreviewActionButton(assignButton, assignLabel, canAssign))
                ToggleAssignChampionBee(definition.Id);
        }

        private static void DrawRuntimeBridgeShell(bool portrait)
        {
            RuntimeBridgePlayerFacingState state = RuntimeBridgePlayerState;
            Rect panel = portrait
                ? new Rect(10f, 132f, Screen.width - 20f, 58f)
                : new Rect(150f, 130f, 306f, 126f);

            Color border = state.Mode == RuntimeBridgePlayerMode.OfflineFallback
                ? new Color(0.48f, 0.78f, 1f, 0.92f)
                : new Color(0.86f, 0.58f, 0.16f, 0.88f);
            DrawPremiumPanel(panel, new Color(0.035f, 0.030f, 0.024f, portrait ? 0.78f : 0.92f), border);

            if (portrait)
            {
                DrawGameIcon(new Rect(panel.x + 10f, panel.y + 10f, 34f, 34f), state.Mode == RuntimeBridgePlayerMode.OfflineFallback ? "server" : "hive", Color.white);
                GUI.Label(new Rect(panel.x + 52f, panel.y + 8f, panel.width - 150f, 20f), state.StatusTitle, smallStyle);
                GUI.Label(new Rect(panel.x + 52f, panel.y + 30f, panel.width - 150f, 18f), ShortBridgeDisclosure(state), tinyLabelStyle);
                Rect action = new Rect(panel.xMax - 90f, panel.y + 12f, 76f, 34f);
                if (DrawBridgeMiniButton(action, state.PrimaryAction, true)) lastTouchFeedback = "Consultation demo non officielle";
                return;
            }

            DrawGameIcon(new Rect(panel.x + 14f, panel.y + 14f, 44f, 44f), state.Mode == RuntimeBridgePlayerMode.OfflineFallback ? "server" : "hive", Color.white);
            GUI.Label(new Rect(panel.x + 68f, panel.y + 13f, panel.width - 84f, 30f), "Pont runtime", titleStyle);
            GUI.Label(new Rect(panel.x + 68f, panel.y + 45f, panel.width - 84f, 22f), state.StatusTitle, smallStyle);
            GUI.Label(new Rect(panel.x + 16f, panel.y + 72f, panel.width - 32f, 18f), state.Disclosure, tinyLabelStyle);

            Rect local = new Rect(panel.x + 16f, panel.yMax - 34f, 122f, 24f);
            Rect server = new Rect(panel.x + 146f, panel.yMax - 34f, 144f, 24f);
            if (DrawBridgeMiniButton(local, state.PrimaryAction, true)) lastTouchFeedback = "Consultation demo non officielle";
            DrawBridgeMiniButton(server, "Voie officielle", false);
        }

        private static bool DrawBridgeMiniButton(Rect rect, string label, bool active)
        {
            DrawPremiumPanel(rect, active ? new Color(0.055f, 0.046f, 0.030f, 0.96f) : new Color(0.035f, 0.060f, 0.080f, 0.86f), active ? new Color(1f, 0.72f, 0.16f, 0.78f) : new Color(0.36f, 0.70f, 1f, 0.72f));
            bool clicked = GUI.Button(rect, string.Empty, GUIStyle.none);
            if (clicked) AudioManager.Instance?.PlayUIClick();
            GUI.Label(rect, label, new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter });
            return clicked;
        }

        private static string ShortBridgeDisclosure(RuntimeBridgePlayerFacingState state)
        {
            if (state.Mode == RuntimeBridgePlayerMode.OfflineFallback) return "Consultation seulement";
            if (state.Mode == RuntimeBridgePlayerMode.MaintenanceFuture) return "Maintenance future";
            if (state.Mode == RuntimeBridgePlayerMode.ExpiredFuture) return "Session future";
            if (state.Mode == RuntimeBridgePlayerMode.ServerPreparation) return "Connexion serveur future";
            return "Consultation demo";
        }

        private static void SimulateLocalPreviewLoop()
        {
            float now = NowForUi();
            if (localPreviewLastTickAt < 0f)
            {
                localPreviewLastTickAt = now;
                EnsureLocalPreviewLevel(FocusedReferenceHotspot().HotspotId);
                return;
            }

            float delta = Mathf.Clamp(now - localPreviewLastTickAt, 0f, 1.5f);
            localPreviewLastTickAt = now;
            if (delta <= 0f) return;

            AccumulatePendingProduction(delta);
            if (now - localPreviewResourceFeedbackStartedAt > 1.15f)
            {
                localPreviewResourceFeedbackIndex = (localPreviewResourceFeedbackIndex + 1) % 5;
                localPreviewResourceFeedbackText = PendingProductionSummary();
                localPreviewResourceFeedbackStartedAt = now;
            }

            CompletePreviewUpgradeIfReady();
            CompletePreviewTrainingIfReady();
            CompletePreviewResearchIfReady();
            CompletePreviewDefenseIfReady();
            CompleteGuidedOpeningProductionIfReady();
            CompleteGuidedOpeningCircuitRouteIfReady();
            CompleteGuidedOpeningCircuitMaintenanceIfReady();
            CompleteGuidedOpeningCharterIfReady();
            CompleteGuidedOpeningCommissioningLoadIfReady();
            CompleteGuidedOpeningCommissioningSealIfReady();
            CompleteGuidedOpeningBroodSupplyIfReady();
            CompleteGuidedOpeningHygienePurgeIfReady();
            CompleteGuidedBroodDiagnosisIfReady();
            CompleteGuidedBroodPreparationIfReady();
            CompleteGuidedBroodCareIfReady();
            CompleteGuidedBroodCircuitSupplyIfReady();
            CompleteGuidedBroodCircuitTreatmentIfReady();
