            CompleteGuidedBroodIncubationTreatmentIfReady();
            CompleteGuidedBroodIncubationDoctrineIfReady();
            CompleteGuidedBroodWorkerHandoffIfReady();
            CompleteGuidedBroodWaxConsolidationIfReady();
            CompleteGuidedWorkerCareIfReady();
            CompleteGuidedWorkerEmergenceIfReady();
            CompleteGuidedWorkerTrialIfReady();
            CompleteGuidedWorkerFirstShiftIfReady();
            CompleteGuidedWorkerCertificationTaskIfReady();
            CompleteGuidedWorkerCertificationMentorshipIfReady();
            CompleteGuidedWorkerWorkshopHandoffIfReady();
            CompleteGuidedWorkerWorkshopCommissionIfReady();
            CompleteGuidedUpgradeAuditIfReady();
