        private static float GuidedOpeningProductionProgress01()
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.HoneyProduction) return 0f;
            return Mathf.Clamp01((NowForUi() - guidedOpeningProductionStartedAt) / Mathf.Max(0.1f, guidedOpeningProductionDuration));
        }

        private static void CompleteGuidedOpeningProductionIfReady()
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.HoneyProduction
                || GuidedOpeningProductionProgress01() < 1f) return;

            localPreviewPendingHoney = Mathf.Max(localPreviewPendingHoney, guidedOpeningProductionYield);
            localPreviewBroodStability = Mathf.Min(100f, localPreviewBroodStability + guidedOpeningProductionBroodStabilityGain);
            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.HoneySecondCollect);
            localPreviewSessionPrompt = "Objectif: recolter le nouveau miel";
            BeginReferenceFeedbackPulse("preview");
        }

        private static float GuidedOpeningCircuitRouteProgress01()
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.OpeningCircuitRouteRunning) return 0f;
            return Mathf.Clamp01((NowForUi() - guidedOpeningCircuitRouteStartedAt) / Mathf.Max(0.1f, guidedOpeningCircuitRouteDuration));
        }

        private static void CompleteGuidedOpeningCircuitRouteIfReady()
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.OpeningCircuitRouteRunning
                || GuidedOpeningCircuitRouteProgress01() < 1f) return;

            localPreviewPendingHoney = Mathf.Max(localPreviewPendingHoney, guidedOpeningCircuitPendingHoney);
            float before = localPreviewBroodStability;
            localPreviewBroodStability = Mathf.Min(100f, before + guidedOpeningCircuitPendingRouteStability);
            float appliedStability = localPreviewBroodStability - before;
            guidedOpeningCircuitStabilityGain += appliedStability;
            BeginGuidedOpeningRouteFeedback(guidedOpeningCircuitRoutePlan, guidedOpeningCircuitPendingHoney, appliedStability);
            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.OpeningCircuitCollect);
            localPreviewSessionPrompt = "Objectif: recolter le lot du circuit";
            BeginReferenceFeedbackPulse("preview");
        }

        private static float GuidedOpeningCircuitMaintenanceProgress01()
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.OpeningCircuitMaintenanceRunning) return 0f;
            return Mathf.Clamp01((NowForUi() - guidedOpeningCircuitMaintenanceStartedAt) / Mathf.Max(0.1f, guidedOpeningCircuitMaintenanceDuration));
        }

        private static void CompleteGuidedOpeningCircuitMaintenanceIfReady()
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.OpeningCircuitMaintenanceRunning
                || GuidedOpeningCircuitMaintenanceProgress01() < 1f) return;

            float before = localPreviewBroodStability;
            localPreviewBroodStability = Mathf.Min(100f, before + guidedOpeningCircuitPendingMaintenanceStability);
            guidedOpeningCircuitStabilityGain += localPreviewBroodStability - before;
            localPreviewHoneyProductionBonus += guidedOpeningCircuitPendingHoneyProductionGain;
            guidedOpeningCircuitHoneyProductionGain += guidedOpeningCircuitPendingHoneyProductionGain;
            guidedOpeningCircuitCompletedRounds++;
            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.OpeningCircuitRoundResult);
            localPreviewSessionPrompt = "Tournee " + guidedOpeningCircuitCompletedRounds.ToString(CultureInfo.InvariantCulture) + "/" + GuidedOpeningCircuitRoundTarget.ToString(CultureInfo.InvariantCulture) + " terminee";
            BeginReferenceFeedbackPulse("preview");
        }

        private static float GuidedOpeningCharterProgress01()
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.OpeningCharterRunning) return 0f;
            return Mathf.Clamp01((NowForUi() - guidedOpeningCharterStartedAt) / Mathf.Max(0.1f, guidedOpeningCharterDuration));
        }

        private static void CompleteGuidedOpeningCharterIfReady()
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.OpeningCharterRunning
                || GuidedOpeningCharterProgress01() < 1f) return;

            guidedOpeningCharterAssignedBees = 0;
            localPreviewReservedHoney = 0f;
            guidedOpeningCharterChecksMask = 0;
            guidedOpeningCharterCheckCount = 0;
            guidedOpeningCharterLastCheck = "none";
            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.OpeningCharterCheck);
            localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_01.charter.check.title", "Ratification de la charte");
            BeginReferenceFeedbackPulse("preview");
        }

        private static void RegisterGuidedOpeningCharterCheck(int index)
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.OpeningCharterCheck) return;
            int clamped = Mathf.Clamp(index, 0, 2);
            int bit = 1 << clamped;
            if ((guidedOpeningCharterChecksMask & bit) != 0) return;
            guidedOpeningCharterChecksMask |= bit;
            guidedOpeningCharterCheckCount++;
            guidedOpeningCharterLastCheck = clamped == 0 ? "ledger" : clamped == 1 ? "nursery_priority" : "alert_signal";
            BeginReferenceFeedbackPulse("preview");
            if (guidedOpeningCharterCheckCount < 3)
            {
                localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_01.charter.check.title", "Ratification de la charte") + " " + guidedOpeningCharterCheckCount.ToString(CultureInfo.InvariantCulture) + "/3";
                return;
            }

            guidedOpeningCharterCapacityGain = guidedOpeningCharterPendingCapacityGain;
            localPreviewCapacityMax += guidedOpeningCharterCapacityGain;
            float before = localPreviewBroodStability;
            localPreviewBroodStability = Mathf.Min(100f, before + guidedOpeningCharterPendingStabilityGain);
            guidedOpeningCharterStabilityGain = localPreviewBroodStability - before;
            guidedOpeningCharterCareGain = guidedOpeningCharterPendingCareGain;
            localPreviewBroodCareBonus += guidedOpeningCharterCareGain;
            SaveLocalPreviewStrategicChoice("opening_charter", guidedOpeningCharterPlan);
            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.OpeningCommissioningLoadChoice);
            localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_01.charter.result.prompt", "Charte adoptée: éprouve le circuit sous charge");
            BeginReferenceFeedbackPulse("preview");
        }

        private static void StartGuidedOpeningCommissioningLoad(bool surge)
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.OpeningCommissioningLoadChoice) return;
            guidedOpeningCommissioningLoadPlan = surge ? "surge" : "measured";
            guidedOpeningCommissioningLoadDuration = surge ? GuidedOpeningCommissioningSurgeDuration : GuidedOpeningCommissioningMeasuredDuration;
            guidedOpeningCommissioningAssignedBees = surge ? 4 : 3;
            guidedOpeningCommissioningPendingHoney = surge ? GuidedOpeningCommissioningSurgeHoney : GuidedOpeningCommissioningMeasuredHoney;
            guidedOpeningCommissioningLoadStartedAt = NowForUi();
            guidedOpeningCommissioningLoadCommitCount++;
            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.OpeningCommissioningLoadRunning);
        }

        private static float GuidedOpeningCommissioningLoadProgress01()
        {
            return guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCommissioningLoadRunning
                ? Mathf.Clamp01((NowForUi() - guidedOpeningCommissioningLoadStartedAt) / Mathf.Max(0.1f, guidedOpeningCommissioningLoadDuration))
                : 0f;
        }

        private static void CompleteGuidedOpeningCommissioningLoadIfReady()
        {
