        private static void ChooseGuidedBroodIncubationVitalityPriority(bool nutrition)
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.BroodIncubationVitalityChoice) return;

            guidedBroodIncubationVitalityChoice = nutrition ? "nutrition" : "stability";
            guidedBroodIncubationVitalityAttemptCount++;
            if (!string.Equals(
                    guidedBroodIncubationVitalityChoice,
                    guidedBroodIncubationVitalityPriority,
                    StringComparison.Ordinal))
            {
                guidedBroodIncubationVitalityMistakeCount++;
                localPreviewDisabledReason = BeeLocalization.Text(
                    "tutorial.chapter_02.incubation.vitality.retry.title",
                    "Relis les deux mesures");
                localPreviewRecoveryGuidance = BeeLocalization.Text(
                    "tutorial.chapter_02.incubation.vitality.retry.body",
                    "La priorité est la mesure la plus basse. Aucun coût ni temps n'est perdu: essaie encore.");
                localPreviewSessionPrompt = BeeLocalization.Text(
                    "tutorial.chapter_02.incubation.vitality.retry.prompt",
                    "Aucune pénalité · choisis la mesure la plus basse");
                BeginReferenceFeedbackPulse("locked");
                return;
            }

            guidedBroodIncubationVitalityResolved = true;
            guidedBroodIncubationVitalitySuccessCount++;
            localPreviewDisabledReason = string.Empty;
            localPreviewRecoveryGuidance = string.Empty;
            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.BroodIncubationCheck);
            localPreviewSessionPrompt = BeeLocalization.Text(
                "tutorial.chapter_02.incubation.vitality.confirmed.prompt",
                "Priorité comprise · contrôle les trois signes");
            BeginReferenceFeedbackPulse("preview");
        }

