        private static void RegisterGuidedBroodWorkerHandoffCheck(int index)
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.BroodWorkerHandoffCheck) return;
            int bit = 1 << Mathf.Clamp(index, 0, 2);
            if ((guidedBroodWorkerHandoffChecksMask & bit) != 0) return;
            guidedBroodWorkerHandoffChecksMask |= bit;
            guidedBroodWorkerHandoffCheckCount++;
            BeginReferenceFeedbackPulse("preview");
            if (guidedBroodWorkerHandoffCheckCount < 3)
            {
                localPreviewSessionPrompt = "Contrôle d'émergence " + guidedBroodWorkerHandoffCheckCount.ToString(CultureInfo.InvariantCulture) + "/3";
                return;
