        private static void StartGuidedBroodWaxConsolidation(bool thorough)
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.BroodWaxConsolidationChoice) return;
            if (thorough)
            {
                localPreviewPendingPollen = Mathf.Max(0f, localPreviewPendingPollen - GuidedBroodWaxConsolidationThoroughPollenCost);
            }
            guidedBroodWaxConsolidationPlan = thorough ? "thorough" : "quick";
            guidedBroodWaxConsolidationDuration = thorough ? GuidedBroodWaxConsolidationThoroughDuration : GuidedBroodWaxConsolidationQuickDuration;
