        private static void RegisterGuidedUpgradeOperationsDoctrineCheck(int index)
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.UpgradeOperationsDoctrineCheck) return;
            int clamped = Mathf.Clamp(index, 0, 2);
            int bit = 1 << clamped;
            if ((guidedUpgradeOperationsDoctrineChecksMask & bit) != 0) return;
            guidedUpgradeOperationsDoctrineChecksMask |= bit;
            guidedUpgradeOperationsDoctrineCheckCount++;
            guidedUpgradeOperationsDoctrineLastCheck = clamped == 0 ? "template" : clamped == 1 ? "relay" : "traceability";
            BeginReferenceFeedbackPulse("preview");
            if (guidedUpgradeOperationsDoctrineCheckCount < 3)
            {
                localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_04.doctrine.check.title", "Validation de la doctrine") + " " + guidedUpgradeOperationsDoctrineCheckCount.ToString(CultureInfo.InvariantCulture) + "/3";
                return;
            }

            if (guidedUpgradeOperationsDoctrinePlan == "precision")
            {
                localPreviewWaxProductionBonus += GuidedUpgradePrecisionProductionGain;
                guidedUpgradeOperationsDoctrineProductionGain = GuidedUpgradePrecisionProductionGain;
            }
            else
            {
                localPreviewWaxCapacityBonus += GuidedUpgradeCadenceCapacityGain;
                guidedUpgradeOperationsDoctrineCapacityGain = GuidedUpgradeCadenceCapacityGain;
            }
            SaveLocalPreviewStrategicChoice("workshop_doctrine", guidedUpgradeOperationsDoctrinePlan);

            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.UpgradeOperationsCompleted);
            localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_04.doctrine.result.title", "Doctrine inscrite");
            BeginReferenceFeedbackPulse("preview");
        }

        private static void CompletePreviewUpgradeIfReady()
        {
            if (!IsUpgradeRunning() || UpgradeProgress01() < 1f || localPreviewUpgradeApplied) return;

            string id = localPreviewUpgradeHotspotId;
            EnsureLocalPreviewQueueJournalLoaded();
            LocalPreviewQueueOperation operation = localPreviewQueueJournal.upgrade;
            int queuedResultLevel = operation.Exists && string.Equals(operation.targetId, id, StringComparison.Ordinal)
                ? operation.resultValue
                : EnsureLocalPreviewLevel(id) + 1;
            int resultLevel = Mathf.Max(EnsureLocalPreviewLevel(id), queuedResultLevel);
            localPreviewBuildingLevels[id] = resultLevel;
            PersistLocalPreviewBuildingLevel(id, resultLevel);
            if (operation.Exists)
            {
                operation.completionClaimed = true;
                operation.resultValue = resultLevel;
                SaveLocalPreviewQueueJournal();
            }
            localPreviewUpgradeApplied = true;
            GameEventBus.Shared.Publish(new RewardGranted("building_completion", 1L, "speedup"), "speedup");
            localPreviewLastCompletedUpgradeHotspotId = id;
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeRunning
                && string.Equals(id, "wax_workshop", StringComparison.Ordinal))
            {
                localPreviewWaxProductionBonus = guidedUpgradePlan == "production" ? GuidedUpgradeWaxProductionBonus : 0f;
                localPreviewWaxCapacityBonus = guidedUpgradePlan == "capacity" ? GuidedUpgradeWaxCapacityBonus : 0f;
                SaveLocalPreviewStrategicChoice("workshop_specialization", guidedUpgradePlan);
            }
            localPreviewLoopMessage = "Amelioration terminee en preview: " + HotspotLabel(id);
            localPreviewLastActionStatus = "Succes local: niveau +1";
            localPreviewUpgradeRewardText = string.Equals(id, "wax_workshop", StringComparison.Ordinal)
                ? guidedUpgradePlan == "production"
                    ? "+1 niveau, production de cire +6 %"
                    : "+1 niveau, stockage de cire +20 %"
                : "+1 niveau, reward local visible";
            SetDevOnlyActionState("accepted", "none", "upgrade", "T4_result_local");
            SetPlayerFacingActionState("completion", "Amelioration terminee", HotspotLabel(id) + " gagne +1 niveau en preview locale.");
            if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.UpgradeRunning
                && string.Equals(id, "wax_workshop", StringComparison.Ordinal))
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.UpgradeResult);
                localPreviewSessionPrompt = "Atelier de cire ameliore";
            }
            BeginReferenceFeedbackPulse("preview");
        }

        private static void CompletePreviewTrainingIfReady()
        {
            if (!IsTrainingRunning() || TrainingProgress01() < 1f || localPreviewTrainingApplied) return;

            int completedBatch = TrainingBatchSize(localPreviewTrainingTroopType);
            bool workerFormation = IsWorkerTrainingType(localPreviewTrainingTroopType);
            EnsureLocalPreviewQueueJournalLoaded();
            LocalPreviewQueueOperation operation = localPreviewQueueJournal.training;
            int queuedResultCount = operation.Exists && string.Equals(operation.targetId, localPreviewTrainingTroopType, StringComparison.Ordinal)
                ? operation.resultValue
                : TroopCount(localPreviewTrainingTroopType) + completedBatch;
            int resultCount = Mathf.Max(TroopCount(localPreviewTrainingTroopType), queuedResultCount);
            SetTroopCount(localPreviewTrainingTroopType, resultCount);
            PersistLocalPreviewPopulationCount(PopulationIdForTroopType(localPreviewTrainingTroopType), resultCount);
            if (operation.Exists)
            {
                operation.completionClaimed = true;
                operation.resultValue = resultCount;
                SaveLocalPreviewQueueJournal();
            }
            if (workerFormation)
            {
                localPreviewBroodNutrition = Mathf.Max(0f, localPreviewBroodNutrition - WorkerTrainingNutritionCost);
                localPreviewBroodFeedingFeedbackStartedAt = NowForUi();
            }

            localPreviewTrainingApplied = true;
            GameEventBus.Shared.Publish(new RewardGranted("training_completion", completedBatch, "speedup"), "speedup");
            localPreviewLastCompletedTrainingType = localPreviewTrainingTroopType;
            localPreviewArmyFeedbackText = "+" + completedBatch + " " + localPreviewTrainingTroopType;
            localPreviewLoopMessage = workerFormation
                ? "Une ouvriere a rejoint la ruche"
                : "Entrainement termine en preview: +" + completedBatch + " " + localPreviewTrainingTroopType;
            localPreviewLastActionStatus = workerFormation ? "Ouvriere arrivee" : "Succes local: troupe ajoutee";
            localPreviewTrainingNextAction = workerFormation
                ? "Nourris le couvain avant la prochaine formation."
                : "Inspecter armee locale ou former un nouveau groupe.";
            localPreviewSessionPrompt = workerFormation
                ? "Le couvain doit etre nourri pour former une nouvelle ouvriere."
                : localPreviewSessionPrompt;
            SetDevOnlyActionState("accepted", "none", workerFormation ? "worker_training" : "training", "T4_result_local");
            SetPlayerFacingActionState(
                "completion",
                workerFormation ? "Ouvriere arrivee" : "Troupes arrivees",
                workerFormation ? "Une nouvelle ouvriere rejoint la colonie." : "+" + completedBatch + " " + localPreviewTrainingTroopType + " ajoutees au compteur local.");
            if (workerFormation && guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerTraining)
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerArrived);
                localPreviewSessionPrompt = "Premiere ouvriere arrivee";
            }
            BeginReferenceFeedbackPulse("preview");
        }

        private static void CompletePreviewResearchIfReady()
        {
            if (!IsResearchRunning() || ResearchProgress01() < 1f || localPreviewResearchApplied) return;

            EnsureLocalPreviewQueueJournalLoaded();
            LocalPreviewQueueOperation operation = localPreviewQueueJournal.research;
            if (!operation.Exists || !string.Equals(operation.targetId, localPreviewResearchId, StringComparison.Ordinal)) return;

            operation.completionClaimed = true;
            if (!LocalPreviewResearchCatalog.Contains(localPreviewQueueJournal.completedResearchIds, localPreviewResearchId))
            {
                localPreviewQueueJournal.completedResearchIds.Add(localPreviewResearchId);
            }
            SaveLocalPreviewQueueJournal();
            localPreviewResearchApplied = true;
            GameEventBus.Shared.Publish(new RewardGranted("research_completion", 1L, "speedup"), "speedup");
            localPreviewLastCompletedResearchId = localPreviewResearchId;
            ApplyLocalPreviewResearchEffects();
            localPreviewLoopMessage = string.Format(
                CultureInfo.CurrentCulture,
                BeeLocalization.Text("research.message.completed", "Étude terminée : {0}"),
                ResearchTitle(localPreviewResearchId));
            localPreviewLastActionStatus = BeeLocalization.Text("research.status.completed", "Terminée");
            SetDevOnlyActionState("accepted", "none", "research", "T4_result_local");
            SetPlayerFacingActionState(
                "completion",
                BeeLocalization.Text("research.message.completed_title", "Recherche terminée"),
                string.Format(
                    CultureInfo.CurrentCulture,
                    BeeLocalization.Text("research.message.completed_detail", "{0} est active dans cet aperçu local."),
                    ResearchResult(localPreviewResearchId)));
            BeginReferenceFeedbackPulse("preview");
        }

