        private static void ResolveGuidedDefenseWorldBriefingSimulation(bool leftChoice)
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.DefenseWorldBriefingSimulation) return;
            bool correct = guidedDefenseWorldBriefingSimulationStage == 0 ? leftChoice : !leftChoice;
            guidedDefenseWorldBriefingLastDecision = guidedDefenseWorldBriefingSimulationStage == 0
                ? (leftChoice ? "recalibrate_course" : "force_route")
                : (leftChoice ? "scatter_team" : "hold_formation");
            BeginReferenceFeedbackPulse(correct ? "preview" : "disabled");
            if (!correct)
            {
                guidedDefenseWorldBriefingMistakeCount++;
                localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_05.world_briefing.simulation.retry", "Réponse sans coût: utilise l'indice et réessaie");
                return;
            }

            guidedDefenseWorldBriefingSuccessCount++;
            guidedDefenseWorldBriefingSimulationStage++;
            if (guidedDefenseWorldBriefingSimulationStage < 2)
            {
                localPreviewSessionPrompt = BeeLocalization.Text("tutorial.chapter_05.world_briefing.simulation.signal.title", "Simulation 2/2: le signal disparaît");
                return;
            }

            guidedWorldNavigationHintLevel = guidedDefenseWorldBriefingPlan == "sun_beacon" ? 1f : 0f;
            if (guidedDefenseWorldBriefingPlan == "guarded_return")
                localPreviewHiveSecurity = Mathf.Min(100, localPreviewHiveSecurity + GuidedDefenseGuardedReturnSecurityGain);
            SaveLocalPreviewStrategicChoice("defense_world_briefing", guidedDefenseWorldBriefingPlan);
            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.DefenseWorldBriefingResult);
            localPreviewSessionPrompt = guidedDefenseWorldBriefingPlan == "sun_beacon"
                ? BeeLocalization.Text("tutorial.chapter_05.world_briefing.sun.result.title", "Balise C32_32 enregistrée")
                : BeeLocalization.Text("tutorial.chapter_05.world_briefing.guard.result.title", "Couloir de retour protégé");
        }

