                _ = before;
            }
            guidedDefenseVigilancePlan = thorough ? "thorough" : "quick";
            guidedDefenseVigilanceDuration = thorough ? GuidedDefenseVigilanceThoroughDuration : GuidedDefenseVigilanceQuickDuration;
            guidedDefenseVigilanceAssignedBees = thorough ? 3 : 2;
            guidedDefenseVigilanceStartedAt = NowForUi();
            guidedDefenseVigilancePendingHoney = 0f;
            guidedDefenseVigilanceCollectedHoney = 0f;
            guidedDefenseVigilanceCheckDone = false;
            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.DefenseVigilanceRunning);
            localPreviewSessionPrompt = thorough
                ? BeeLocalization.Text("tutorial.chapter_05.vigilance.running.thorough", "Ronde minutieuse au périmètre en cours")
                : BeeLocalization.Text("tutorial.chapter_05.vigilance.running.quick", "Ronde rapide au périmètre en cours");
