        private static void AccumulatePendingProduction(float delta)
        {
            if (OfficialOfflineProductionConfigured()) return;
            localPreviewPendingHoney = Mathf.Min(PendingManualProductionCapacity("honey_storage"), localPreviewPendingHoney + (ManualProductionPerHour("honey_storage") / 3600f) * delta);
            localPreviewPendingWax = Mathf.Min(PendingManualProductionCapacity("wax_workshop"), localPreviewPendingWax + (ManualProductionPerHour("wax_workshop") / 3600f) * delta);
            localPreviewPendingPollen = Mathf.Min(PendingManualProductionCapacity("warehouse_cells"), localPreviewPendingPollen + (ManualProductionPerHour("warehouse_cells") / 3600f) * delta);
            PersistLocalPreviewManualProduction(false);
        }

        private static string PendingProductionSummary()
        {
            if (OfficialOfflineProductionConfigured())
            {
                HiveOfflineProductionScreenModel model = OfficialOfflineProductionModel();
                if (model == null || model.Lines.Count == 0 || model.State != HiveOfflineProductionScreenState.Ready)
                    return OfficialProductionStatusText();
                int officialReady = model.Lines.Count(line => line.CollectableWholeUnits > 0 && !line.IsResourceCapacityFull);
                if (officialReady == 0)
                    return BeeLocalization.Text("production.official.in_progress", "Production serveur en cours");
                return officialReady == 1
                    ? BeeLocalization.Text("production.official.one_ready", "1 collecte serveur prête")
                    : string.Format(
                        CultureInfo.CurrentCulture,
                        BeeLocalization.Text("production.official.many_ready", "{0} collectes serveur prêtes"),
                        officialReady);
            }
            int ready = 0;
            if (localPreviewPendingHoney >= CollectionReadyThreshold) ready++;
            if (localPreviewPendingWax >= CollectionReadyThreshold) ready++;
            if (localPreviewPendingPollen >= CollectionReadyThreshold) ready++;
            if (ready == 0) return "Production en cours";
            return ready == 1 ? "1 collecte prete" : ready.ToString(CultureInfo.InvariantCulture) + " collectes pretes";
        }

        private static string[] DynamicResourceValues(bool compact)
        {
            if (OfficialOfflineProductionConfigured())
            {
                HiveOfflineProductionLineModel honey = OfficialOfflineProductionLine("honey_storage");
                HiveOfflineProductionLineModel wax = OfficialOfflineProductionLine("wax_workshop");
                HiveOfflineProductionLineModel pollen = OfficialOfflineProductionLine("warehouse_cells");
                if (honey == null || wax == null || pollen == null)
                    return new[] { "—", "—", "—", "—", "—" };
                decimal used = honey.BalanceAmount + (decimal)wax.BalanceAmount + pollen.BalanceAmount;
                decimal capacity = honey.ProductionCapacity + (decimal)wax.ProductionCapacity + pollen.ProductionCapacity;
                string combinedCapacity = compact
                    ? (capacity <= 0m ? "0%" : Math.Round(used / capacity * 100m, 0).ToString(CultureInfo.InvariantCulture) + "%")
                    : FormatResource(used) + "/" + FormatResource(capacity);
                return new[]
                {
                    FormatResource(honey.BalanceAmount),
                    FormatResource(wax.BalanceAmount),
                    FormatResource(pollen.BalanceAmount),
                    "—",
                    combinedCapacity
                };
            }
            return new[]
            {
                FormatResource(localPreviewHoney),
                FormatResource(localPreviewWax),
                FormatResource(localPreviewPollen),
                FormatResource(localPreviewBees),
                compact ? CapacityPercent() : FormatResource(localPreviewCapacityUsed) + "/" + FormatResource(localPreviewCapacityMax)
            };
        }

        private static string FormatResource(float value)
        {
            if (value >= 1000000f) return (value / 1000000f).ToString("0.0", CultureInfo.InvariantCulture) + "M";
            if (value >= 1000f) return (value / 1000f).ToString("0.0", CultureInfo.InvariantCulture) + "K";
            return Mathf.FloorToInt(value).ToString(CultureInfo.InvariantCulture);
        }

        private static string FormatResource(long value)
        {
            return FormatResource((decimal)Math.Max(0L, value));
        }

        private static string FormatResource(decimal value)
        {
            decimal safe = Math.Max(0m, value);
            if (safe >= 1000000m) return (safe / 1000000m).ToString("0.0", CultureInfo.InvariantCulture) + "M";
            if (safe >= 1000m) return (safe / 1000m).ToString("0.0", CultureInfo.InvariantCulture) + "K";
            return decimal.Floor(safe).ToString(CultureInfo.InvariantCulture);
        }

        private static string CapacityPercent()
        {
            return Mathf.RoundToInt(localPreviewCapacityUsed / Mathf.Max(1f, localPreviewCapacityMax) * 100f).ToString(CultureInfo.InvariantCulture) + "%";
        }

