        }

        private static string FindProofValue(string[] rows, string key)
        {
            string prefix = key + ":";
            for (int i = 0; i < rows.Length; i++)
            {
                if (rows[i].StartsWith(prefix, StringComparison.Ordinal)) return rows[i].Substring(prefix.Length);
            }

            return "missing";
        }

        private static int EnsureLocalPreviewLevel(string hotspotId)
        {
            if (localPreviewBuildingLevels.TryGetValue(hotspotId, out int level)) return level;
            level = hotspotId == "administration_core" ? 27 : hotspotId == "honey_storage" ? 25 : hotspotId == "guard_post" ? 24 : 22;
            localPreviewBuildingLevels[hotspotId] = level;
            return level;
        }

