        private static int TroopCount(string type)
        {
            if (IsWorkerTrainingType(type)) return localPreviewWorkers;
            if (type == "Gardiennes") return localPreviewGuardians;
            if (type == "Voltigeuses") return localPreviewWingrunners;
            if (type == "Lanceuses") return localPreviewDarters;
            if (type == "Eclaireuses") return localPreviewScouts;
            return localPreviewSoldiers;
        }

        private static void SetTroopCount(string type, int value)
        {
            int safeValue = Mathf.Max(0, value);
            if (IsWorkerTrainingType(type)) localPreviewWorkers = safeValue;
            else if (type == "Gardiennes") localPreviewGuardians = safeValue;
            else if (type == "Voltigeuses") localPreviewWingrunners = safeValue;
            else if (type == "Lanceuses") localPreviewDarters = safeValue;
            else if (type == "Eclaireuses") localPreviewScouts = safeValue;
            else localPreviewSoldiers = safeValue;
        }

