        private static void AddTroops(string type, int amount)
        {
            if (IsWorkerTrainingType(type)) localPreviewWorkers += amount;
            else if (type == "Gardiennes") localPreviewGuardians += amount;
            else if (type == "Voltigeuses") localPreviewWingrunners += amount;
            else if (type == "Lanceuses") localPreviewDarters += amount;
            else if (type == "Eclaireuses") localPreviewScouts += amount;
            else localPreviewSoldiers += amount;
