        private static int TrainingBatchSize(string type)
        {
            if (IsWorkerTrainingType(type)) return 1;
            if (HiveDoctrineRecruitmentCatalog.TryResolveTroopType(type, out HiveDoctrineRecruitmentDefinition recruitment))
                return recruitment.BatchSize;
            if (type == "Gardiennes") return 4;
            if (type == "Eclaireuses") return 6;
            return 8;
        }

        private static void DrawActiveHiveMenuPanel(bool compact)
        {
            if (activeMainMenuId == "Quests")
            {
                Rect questPanel = GuidedQuestMenuPanelRect(compact);
                DrawPremiumPanel(questPanel, new Color(0.040f, 0.032f, 0.022f, 0.985f), new Color(0.92f, 0.62f, 0.16f, 0.84f));
                DrawGuidedQuestMenuPanel(questPanel, compact);
                return;
            }

            if (activeMainMenuId == "Bag")
            {
                Rect ledgerPanel = HiveLedgerPanelRect(compact, Screen.width, Screen.height);
                DrawPremiumPanel(ledgerPanel, new Color(0.040f, 0.032f, 0.022f, 0.985f), new Color(0.92f, 0.62f, 0.16f, 0.84f));
                DrawHiveLedgerPanel(ledgerPanel, compact);
                return;
            }

            if (activeMainMenuId == "More")
            {
                DrawMoreMenuPanel(compact);
                return;
            }

            if (activeMainMenuId == "Settings")
            {
                DrawMobileComfortSettingsPanel(compact);
                return;
            }

            if (activeHiveMenu == HiveMenuMode.Hive || activeHiveMenu == HiveMenuMode.Actions)
            {
                // M043T-CL: DrawReferenceDetailInfoPopup is this screen's own sub-modal (opened by
                // an "i" button inside DrawDetailPanel itself) drawn on top of that same panel's
                // upgrade/train/close buttons - see DrawUnderOwnOverlayGate's standing convention.
                DrawUnderOwnOverlayGate(referenceDetailInfoPopupOpen, () => DrawDetailPanel(compact));
                DrawReferenceDetailInfoPopup(compact);
                return;
            }

            Rect panel;
            if (activeHiveMenu == HiveMenuMode.Army)
            {
                panel = ArmyMenuPanelRectForProof(compact, Screen.width, Screen.height, formationReadinessOpen);
            }
            else
            {
                float compactPanelHeight = activeHiveMenu == HiveMenuMode.Research ? 310f : 190f;
                float landscapePanelHeight = activeHiveMenu == HiveMenuMode.Research
                    ? Mathf.Min(348f, Screen.height - (LandscapeTopHudHeight() + 108f))
                    : Mathf.Min(500f, Screen.height - (LandscapeTopHudHeight() + 108f));
                panel = compact
                    ? new Rect(10f, Screen.height - 78f - compactPanelHeight - 12f, Screen.width - 20f, compactPanelHeight)
                    : new Rect(Screen.width - LandscapeRightPanelWidth() - 24f, 118f, LandscapeRightPanelWidth(), landscapePanelHeight);
            }
            DrawPremiumPanel(panel, new Color(0.050f, 0.040f, 0.028f, 0.98f), new Color(0.92f, 0.62f, 0.16f, 0.84f));

            if (activeHiveMenu == HiveMenuMode.Army) DrawArmyMenuPanel(panel, compact);
            else if (activeHiveMenu == HiveMenuMode.Research) DrawResearchMenuPanel(panel, compact);
			else if (activeHiveMenu == HiveMenuMode.Alliance) DrawAllianceHeadquartersScreen(compact);
        }

        private static Rect GuidedQuestMenuPanelRect(bool compact)
        {
            return GuidedQuestMenuPanelRect(compact, Screen.width, Screen.height);
        }

        private static Rect GuidedQuestMenuPanelRect(bool compact, float screenWidth, float screenHeight)
        {
            if (compact)
            {
                float availableHeight = Mathf.Max(300f, screenHeight - 126f - 78f - 24f);
                float height = Mathf.Min(500f, availableHeight);
                float y = Mathf.Max(134f, screenHeight - 78f - height - 12f);
                return new Rect(10f, y, screenWidth - 20f, height);
            }

            bool tablet = screenWidth >= 1600f && screenHeight >= 900f;
            float width = tablet ? 430f : 360f;
            float topHud = tablet ? 132f : 112f;
            return new Rect(screenWidth - width - 24f, 118f, width, Mathf.Min(560f, screenHeight - (topHud + 108f)));
        }

        public static Rect GuidedQuestMenuPanelRectForProof(bool portrait, float screenWidth, float screenHeight)
        {
            return GuidedQuestMenuPanelRect(portrait, screenWidth, screenHeight);
        }

