                case GuidedCollectionTutorialStep.DefenseDebriefCheck:
                case GuidedCollectionTutorialStep.DefenseRecoveryReady:
                case GuidedCollectionTutorialStep.DefenseRecoveryRunning:
                    return 5;
                case GuidedCollectionTutorialStep.DefenseRecoveryResult:
                case GuidedCollectionTutorialStep.DefenseDoctrineReady:
                case GuidedCollectionTutorialStep.DefenseDoctrineRunning:
                    return 6;
                case GuidedCollectionTutorialStep.DefenseDoctrineResult:
                    return 6;
                case GuidedCollectionTutorialStep.ReadinessWelcome:
                    return 7;
                case GuidedCollectionTutorialStep.ReadinessProductionChoice:
                case GuidedCollectionTutorialStep.ReadinessProductionRunning:
                case GuidedCollectionTutorialStep.ReadinessCollectHoney:
                case GuidedCollectionTutorialStep.ReadinessCollectPollen:
                case GuidedCollectionTutorialStep.ReadinessPopulationChoice:
                case GuidedCollectionTutorialStep.ReadinessPopulationRunning:
                case GuidedCollectionTutorialStep.ReadinessDefenseChoice:
                case GuidedCollectionTutorialStep.ReadinessDefenseRunning:
                case GuidedCollectionTutorialStep.ReadinessCheck:
                case GuidedCollectionTutorialStep.ReadinessRoundResult:
                    return guidedReadinessRound <= 1 ? 7 : 8;
                case GuidedCollectionTutorialStep.ReadinessCompleted:
                    return 9;
                case GuidedCollectionTutorialStep.DefenseExpeditionMandateChoice:
                case GuidedCollectionTutorialStep.DefenseExpeditionMandateRunning:
                case GuidedCollectionTutorialStep.DefenseExpeditionMandateCheck:
                    return 10;
                case GuidedCollectionTutorialStep.DefenseExpeditionMandateResult:
                    return 11;
                case GuidedCollectionTutorialStep.DefenseWorldBriefingChoice:
                case GuidedCollectionTutorialStep.DefenseWorldBriefingRunning:
                case GuidedCollectionTutorialStep.DefenseWorldBriefingSimulation:
                case GuidedCollectionTutorialStep.DefenseWorldBriefingResult:
                    return 12;
                case GuidedCollectionTutorialStep.DefenseVigilanceChoice:
                case GuidedCollectionTutorialStep.DefenseVigilanceRunning:
                case GuidedCollectionTutorialStep.DefenseVigilanceCollect:
                case GuidedCollectionTutorialStep.DefenseVigilanceCheck:
                case GuidedCollectionTutorialStep.DefenseVigilanceResult:
                    return 13;
                case GuidedCollectionTutorialStep.DefenseCompleted:
                    return 14;
                default:
                    return 0;
            }
        }

        private static string GuidedOpeningActCurrentObjectiveText()
        {
            if (guidedOpeningActMilestones == 1)
            {
                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitSupplyChoice
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitSupplyRunning
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitCollectHoney
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitCollectPollen)
                {
                    string prefix = guidedBroodCircuitRound <= 1 ? "7/13" : "8/13";
                    return prefix + " Produire puis récolter la ration";
                }
                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitTreatmentChoice
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitTreatmentRunning
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodCircuitRoundResult)
                {
                    string prefix = guidedBroodCircuitRound <= 1 ? "7/13" : "8/13";
                    return prefix + " Traiter le couvain";
                }
                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationInspectionChoice
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationInspectionRunning
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationVitalityChoice
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationCheck
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationTreatmentChoice
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationTreatmentRunning
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.BroodIncubationRoundResult)
                {
                    string prefix = guidedBroodIncubationRound <= 1 ? "10/13" : "11/13";
                    return prefix + " Stabiliser la cohorte";
                }

                switch (GuidedBroodObjectiveIndex())
                {
                    case 1: return "1/13 Trouver la nurserie";
                    case 2: return "2/13 Diagnostiquer le couvain";
                    case 3: return "3/13 Stabiliser la chambre";
                    case 4: return "4/13 Nourrir le couvain";
                    case 5: return "5/13 Contrôler les larves";
                    case 6: return "6/13 Orienter la croissance";
                    case 7: return "7/13 Accomplir la première tournée";
                    case 8: return "8/13 Accomplir la seconde tournée";
                    case 9: return "9/13 Préparer l'incubation";
                    case 10: return "10/13 Stabiliser la première cohorte";
                    case 11: return "11/13 Stabiliser la seconde cohorte";
                    case 12: return "12/13 Choisir le protocole du couvain";
                    case 13: return "13/13 Certifier l'incubation";
                    default: return "Trouver et stabiliser la nurserie";
                }
            }

            if (guidedOpeningActMilestones == 0)
            {
                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCircuitRouteChoice
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCircuitRouteRunning
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCircuitCollect)
                {
                    string prefix = guidedOpeningCircuitRound <= 1 ? "6/10" : "7/10";
                    return prefix + " Acheminer puis récolter le miel";
                }
                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCircuitMaintenanceChoice
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCircuitMaintenanceRunning
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.OpeningCircuitRoundResult)
                {
                    string prefix = guidedOpeningCircuitRound <= 1 ? "6/10" : "7/10";
                    return prefix + " Entretenir le circuit";
                }

                switch (GuidedOpeningObjectiveIndex())
                {
                    case 1: return "1/10 Sécuriser le premier miel";
                    case 2: return "2/10 Organiser la relève";
                    case 3: return "3/10 Produire un nouveau lot";
                    case 4: return "4/10 Récolter le nouveau miel";
                    case 5: return "5/10 Répartir la récolte";
                    case 6: return "6/10 Installer la première tournée";
                    case 7: return "7/10 Répéter la tournée";
                    case 8: return "8/10 Contrôler le circuit";
                    case 9: return "9/10 Choisir la charte";
                    case 10: return "10/10 Certifier la colonie";
                    default: return "Relancer la réserve de miel";
                }
            }
            if (guidedOpeningActMilestones == 2)
            {
                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCertificationTaskChoice
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCertificationTaskRunning
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCertificationCollect)
                {
                    string prefix = guidedWorkerCertificationRound <= 1 ? "8/10" : "9/10";
                    return prefix + " Accomplir une tâche certifiée";
                }
                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCertificationCheck
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCertificationMentorshipChoice
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCertificationMentorshipRunning
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.WorkerCertificationRoundResult)
                {
                    string prefix = guidedWorkerCertificationRound <= 1 ? "8/10" : "9/10";
                    return prefix + " Contrôler puis encadrer";
                }

                switch (GuidedWorkerObjectiveIndex())
                {
                    case 1: return "1/13 Terminer la nutrition";
                    case 2: return "2/13 Préparer l'éclosion";
                    case 3: return "3/13 Former l'ouvrière";
                    case 4: return "4/13 Choisir un essai";
                    case 5: return "5/13 Réaliser l'apprentissage";
                    case 6: return "6/13 Affecter l'ouvrière";
                    case 7: return "7/13 Valider son premier quart";
                    case 8: return "8/13 Accomplir la première certification";
                    case 9: return "9/13 Répéter la certification";
                    case 10: return "10/13 Valider son intégration";
                    case 11: return "11/13 Préparer l'atelier";
                    case 12: return "12/13 Certifier la passation";
                    case 13: return "13/13 Réclamer la récompense";
                    default: return "Former puis affecter l'ouvrière";
                }
            }
            if (guidedOpeningActMilestones == 3)
            {
                switch (GuidedUpgradeObjectiveIndex())
                {
                    case 1: return "1/11 Trouver l'atelier";
                    case 2: return "2/11 Auditer les canaux";
                    case 3: return "3/11 Choisir la spécialisation";
                    case 4: return "4/11 Améliorer l'atelier";
                    case 5: return "5/11 Calibrer et récolter";
                    case 6: return "6/11 Affecter le lot témoin";
                    case 7: return "7/11 Livrer la première commande";
                    case 8: return "8/11 Livrer la seconde commande";
                    case 9: return "9/11 Eprouver l'atelier";
                    case 10: return "10/11 Choisir la doctrine";
                    case 11: return "11/11 Certifier l'atelier";
                    default: return "Choisir la spécialisation de cire";
                }
            }
            if (guidedOpeningActMilestones == 4)
            {
                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessProductionChoice
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessProductionRunning
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessCollectHoney
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessCollectPollen)
                {
                    string prefix = guidedReadinessRound <= 1 ? "7/13" : "8/13";
                    return prefix + " Produire puis récolter";
                }
                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessPopulationChoice
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessPopulationRunning)
                {
                    string prefix = guidedReadinessRound <= 1 ? "7/13" : "8/13";
                    return prefix + " Renouveler une équipe";
                }
                if (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessDefenseChoice
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessDefenseRunning
                    || guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessCheck)
                {
                    string prefix = guidedReadinessRound <= 1 ? "7/13" : "8/13";
                    return prefix + (guidedCollectionTutorialStep == GuidedCollectionTutorialStep.ReadinessCheck
                        ? " Certifier le commandement"
                        : " Vérifier le périmètre");
                }

                switch (GuidedDefenseObjectiveIndex())
                {
                    case 1: return "1/14 Inspecter la caserne";
                    case 2: return "2/14 Reconnaître la menace";
                    case 3: return "3/14 Choisir la riposte";
                    case 4: return "4/14 Repousser l'intruse";
                    case 5: return "5/14 Gérer l'après-combat";
                    case 6: return "6/14 Installer une protection";
                    case 7: return "7/14 Accomplir le circuit guidé";
                    case 8: return "8/14 Répéter le circuit";
                    case 9: return "9/14 Évaluer la préparation";
                    case 10: return "10/14 Préparer l'expédition";
                    case 11: return "11/14 Autoriser le mandat";
                    case 12: return "12/14 Simuler la sortie";
                    case 13: return "13/14 Faire la ronde de vigilance";
                    case 14: return "14/14 Valider la défense";
                    default: return "Reconnaître puis sécuriser la ruche";
                }
            }
            return "Acte terminé";
        }

        private static void DrawGuidedQuestMenuPanel(Rect panel, bool compact)
        {
            if (!OfficialDailyRoundConfigured())
                EnsureLocalPreviewDailyRoundLoaded();
			if (DrawMenuHeader(
				panel,
				"quests",
				BeeLocalization.Text("quest_journal.title", "Journal de la ruche"),
				BeeLocalization.Text("quest_journal.subtitle", "Acte fondateur et ronde quotidienne"),
				true))
			{
				AudioManager.Instance?.PlayUIClick();
				AudioManager.Instance?.PlayMenuClose();
				activeMainMenuId = string.Empty;
				localPreviewLastActionStatus = "Journal des quêtes fermé";
				return;
            }

            Rect actTab = new Rect(panel.x + 18f, panel.y + 56f, (panel.width - 42f) * 0.5f, 44f);
            Rect dailyTab = new Rect(actTab.xMax + 6f, actTab.y, actTab.width, 44f);
            bool actMode = string.Equals(localPreviewQuestJournalMode, "act", StringComparison.Ordinal);
            if (GUI.Toggle(actTab, actMode, BeeLocalization.Text("daily_round.tab.act", "Acte I"), "Button") && !actMode)
                localPreviewQuestJournalMode = "act";
            if (GUI.Toggle(dailyTab, !actMode, BeeLocalization.Text("daily_round.tab.daily", "Ronde"), "Button") && actMode)
                localPreviewQuestJournalMode = "daily";

            if (string.Equals(localPreviewQuestJournalMode, "daily", StringComparison.Ordinal))
            {
                DrawDailyRoundContent(panel, compact, panel.y + 110f);
                return;
            }

            float contentX = panel.x + 18f;
            float contentWidth = panel.width - 36f;
            float progressTop = panel.y + 110f;
            GUI.Label(new Rect(contentX, progressTop, contentWidth * 0.62f, 18f), "PROGRESSION DE L'ACTE", tinyLabelStyle);
            GUI.Label(new Rect(contentX + contentWidth * 0.62f, progressTop, contentWidth * 0.38f, 18f), guidedOpeningActMilestones.ToString(CultureInfo.InvariantCulture) + " / 5", new GUIStyle(badgeStyle) { alignment = TextAnchor.MiddleRight });
            DrawProgressBar(new Rect(contentX, progressTop + 23f, contentWidth, 8f), guidedOpeningActMilestones / 5f);

            string[] titles =
            {
                "Relancer la réserve de miel",
                "Stabiliser le couvain",
                "Former et affecter une ouvrière",
                "Spécialiser l'atelier de cire",
                "Repousser la fausse-teigne"
            };
            string[] rewards =
            {
                "+250 miel",
                "+180 miel · +40 cire",
                "+300 miel · +120 pollen",
                "+120 miel · +160 cire",
                "+200 miel · +80 cire"
            };
            string[] icons = { "honey", "nursery", "worker-bee", "wax", "guard-bee" };
            float rowsTop = progressTop + 43f;
            float footerHeight = compact ? 48f : 54f;
            float rowHeight = Mathf.Clamp((panel.yMax - footerHeight - rowsTop) / titles.Length, 43f, compact ? 52f : 58f);
            for (int i = 0; i < titles.Length; i++)
            {
                Rect row = new Rect(contentX, rowsTop + i * rowHeight, contentWidth, rowHeight);
                bool completed = i < guidedOpeningActMilestones;
                bool current = i == guidedOpeningActMilestones && guidedOpeningActMilestones < titles.Length;
                Color accent = completed
                    ? new Color(0.52f, 0.82f, 0.38f, 0.90f)
                    : current ? new Color(1f, 0.72f, 0.18f, 0.96f) : new Color(0.48f, 0.43f, 0.34f, 0.58f);
                if (current)
                {
                    Color previous = GUI.color;
                    GUI.color = new Color(1f, 0.64f, 0.16f, 0.11f);
                    GUI.DrawTexture(row, GetPremiumTexture("amber-veil"), ScaleMode.StretchToFill, true);
                    GUI.color = previous;
                }

                Color oldColor = GUI.color;
                GUI.color = accent;
                GUI.DrawTexture(new Rect(row.x, row.y + 7f, 3f, row.height - 14f), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
                GUI.color = oldColor;
                float iconSize = Mathf.Min(34f, row.height - 12f);
                DrawGameIcon(new Rect(row.x + 10f, row.y + (row.height - iconSize) * 0.5f, iconSize, iconSize), icons[i], completed || current ? Color.white : new Color(0.62f, 0.58f, 0.50f, 0.76f));
                float textX = row.x + 54f;
                GUI.Label(new Rect(textX, row.y + 5f, row.width - 146f, 19f), titles[i], new GUIStyle(smallStyle) { fontSize = compact ? 12 : 13 });
                if (current)
                {
                    GUI.Label(new Rect(textX, row.y + 22f, row.width - 146f, 14f), GuidedOpeningActCurrentObjectiveText(), new GUIStyle(tinyLabelStyle) { fontSize = compact ? 9 : 10, normal = { textColor = accent } });
                    GUI.Label(new Rect(textX, row.y + 36f, row.width - 146f, 14f), rewards[i], new GUIStyle(tinyLabelStyle) { fontSize = compact ? 9 : 10 });
                }
                else
                {
                    GUI.Label(new Rect(textX, row.y + 24f, row.width - 146f, 16f), rewards[i], tinyLabelStyle);
                }
                GUI.Label(new Rect(row.xMax - 88f, row.y + (row.height - 18f) * 0.5f, 82f, 18f), completed ? "Réclamé" : current ? "En cours" : "À venir", new GUIStyle(badgeStyle) { alignment = TextAnchor.MiddleRight, normal = { textColor = accent } });
                GUI.color = new Color(0.78f, 0.58f, 0.24f, 0.24f);
                GUI.DrawTexture(new Rect(row.x + 6f, row.yMax - 1f, row.width - 12f, 1f), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
                GUI.color = Color.white;
            }

            Rect footer = new Rect(contentX, panel.yMax - footerHeight + 8f, contentWidth, footerHeight - 14f);
            GUI.Label(new Rect(footer.x, footer.y, footer.width, 17f), "RÉCOMPENSES RÉCLAMÉES", tinyLabelStyle);
            string totals = Mathf.RoundToInt(guidedOpeningActRewardHoney).ToString(CultureInfo.InvariantCulture) + " miel · "
                + Mathf.RoundToInt(guidedOpeningActRewardWax).ToString(CultureInfo.InvariantCulture) + " cire · "
                + Mathf.RoundToInt(guidedOpeningActRewardPollen).ToString(CultureInfo.InvariantCulture) + " pollen";
            GUI.Label(new Rect(footer.x, footer.y + 18f, footer.width, 19f), totals, smallStyle);
        }

        private static void DrawDailyRoundContent(Rect panel, bool compact, float top)
        {
            if (OfficialDailyRoundConfigured())
            {
                DrawOfficialDailyRoundContent(panel, compact, top);
                return;
            }

            float contentX = panel.x + 18f;
            float contentWidth = panel.width - 36f;
            int completed = DailyRoundCompletedTaskCount();
            GUI.Label(
                new Rect(contentX, top, contentWidth - 58f, 20f),
                BeeLocalization.Text("daily_round.title", "Ronde de la ruche"),
                smallStyle);
            GUI.Label(
                new Rect(contentX + contentWidth - 58f, top, 58f, 20f),
                completed.ToString(CultureInfo.InvariantCulture) + " / 3",
                new GUIStyle(badgeStyle) { alignment = TextAnchor.MiddleRight });
            GUI.Label(
                new Rect(contentX, top + 21f, contentWidth, 30f),
                BeeLocalization.Text("daily_round.utc_disclosure", "Aperçu local · journée et validation officielles côté serveur UTC"),
                new GUIStyle(tinyLabelStyle) { fontSize = compact ? 9 : 10, wordWrap = true });
            DrawProgressBar(new Rect(contentX, top + 55f, contentWidth, 8f), completed / 3f);

            string[] titles =
            {
                BeeLocalization.Text("daily_round.task.collect.title", "Récolte manuelle"),
                BeeLocalization.Text("daily_round.task.operation.title", "Lancer une opération"),
                BeeLocalization.Text("daily_round.task.ledger.title", "Vérifier les stocks")
            };
            string[] bodies =
            {
                BeeLocalization.Text("daily_round.task.collect.body", "Collecte une production dans son bâtiment."),
                BeeLocalization.Text("daily_round.task.operation.body", "Construction, formation ou recherche."),
                BeeLocalization.Text("daily_round.task.ledger.body", "Depuis Sac, ouvre un bâtiment avec Voir.")
            };
            string[] icons = { "honey", "research", "inventory" };
            int[] taskBits = { DailyRoundCollectTask, DailyRoundOperationTask, DailyRoundLedgerTask };
            float rowsTop = top + 72f;
            float rowHeight = 62f;
            for (int i = 0; i < taskBits.Length; i++)
            {
                bool done = DailyRoundTaskCompleted(taskBits[i]);
                bool current = !done && i == completed;
                Color accent = done
                    ? new Color(0.48f, 0.84f, 0.42f, 0.92f)
                    : current ? new Color(1f, 0.72f, 0.18f, 0.96f) : new Color(0.48f, 0.43f, 0.34f, 0.64f);
                Rect row = new Rect(contentX, rowsTop + i * (rowHeight + 4f), contentWidth, rowHeight);
                DrawPremiumPanel(row, new Color(0.034f, 0.030f, 0.024f, 0.92f), accent);
                DrawGameIcon(new Rect(row.x + 10f, row.y + 15f, 32f, 32f), icons[i], done || current ? Color.white : new Color(0.62f, 0.58f, 0.50f, 0.78f));
                float statusWidth = compact ? 62f : 72f;
                float textX = row.x + 50f;
                float textWidth = row.width - 58f - statusWidth;
                GUI.Label(new Rect(textX, row.y + 8f, textWidth, 20f), titles[i], new GUIStyle(smallStyle) { fontSize = compact ? 11 : 12 });
                GUI.Label(new Rect(textX, row.y + 29f, textWidth, 28f), bodies[i], new GUIStyle(tinyLabelStyle) { fontSize = compact ? 9 : 10, wordWrap = true });
                string status = done
                    ? BeeLocalization.Text("daily_round.status.done", "Fait")
                    : current ? BeeLocalization.Text("daily_round.status.current", "À faire") : BeeLocalization.Text("daily_round.status.todo", "Ensuite");
                Rect routeAction = new Rect(row.xMax - statusWidth - 6f, row.y + 9f, statusWidth, 44f);
                if (done)
                {
                    GUI.Label(
                        routeAction,
                        status,
                        new GUIStyle(badgeStyle) { alignment = TextAnchor.MiddleRight, normal = { textColor = accent } });
                }
                else if (DrawPreviewActionButton(routeAction, BeeLocalization.Text("daily_round.action.go", "Aller"), true, true))
                {
                    NavigateToDailyRoundTask(taskBits[i]);
                }
            }

            float rewardY = rowsTop + 3f * (rowHeight + 4f) + 5f;
            Rect reward = new Rect(contentX, rewardY, contentWidth, Mathf.Max(76f, panel.yMax - rewardY - 12f));
            DrawPremiumPanel(reward, new Color(0.055f, 0.042f, 0.022f, 0.96f), new Color(1f, 0.70f, 0.16f, 0.88f));
            float actionWidth = compact ? 104f : 118f;
            float rewardTextWidth = reward.width - actionWidth - 28f;
            GUI.Label(new Rect(reward.x + 10f, reward.y + 7f, rewardTextWidth, 18f), BeeLocalization.Text("daily_round.reward.title", "Récompense de ronde"), smallStyle);
            GUI.Label(new Rect(reward.x + 10f, reward.y + 27f, rewardTextWidth, 18f), BeeLocalization.Text("daily_round.reward.body", "+120 miel · +60 pollen"), badgeStyle);
            GUI.Label(new Rect(reward.x + 10f, reward.y + 47f, rewardTextWidth, 28f), BeeLocalization.Text("daily_round.reward.disclosure", "Aucun gain automatique · aperçu non officiel"), new GUIStyle(tinyLabelStyle) { fontSize = compact ? 8 : 9, wordWrap = true });

            string reason = DailyRoundClaimDisabledReason();
            localPreviewDisabledReason = reason;
            Rect claim = new Rect(reward.xMax - actionWidth - 10f, reward.y + Mathf.Max(8f, (reward.height - 44f) * 0.5f), actionWidth, 44f);
            string claimLabel = localPreviewDailyRound.rewardClaimed
                ? BeeLocalization.Text("daily_round.reward.claimed", "Réclamée")
                : BeeLocalization.Text("daily_round.reward.claim", "Réclamer");
            if (DrawPreviewActionButton(claim, claimLabel, string.IsNullOrWhiteSpace(reason))) ClaimLocalPreviewDailyRound();
        }

        private static void DrawOfficialDailyRoundContent(Rect panel, bool compact, float top)
        {
            HiveDailyRoundScreenModel model = OfficialDailyRoundModel();
            float contentX = panel.x + 18f;
            float contentWidth = panel.width - 36f;
            float refreshWidth = compact ? 82f : 96f;
            GUI.Label(
                new Rect(contentX, top, contentWidth - refreshWidth - 8f, 20f),
                BeeLocalization.Text("daily_round.title", "Ronde de la ruche"),
                smallStyle);
            Rect refresh = new Rect(
                contentX + contentWidth - refreshWidth,
                top,
                refreshWidth,
                44f);
            if (DrawPreviewActionButton(
                    refresh,
                    BeeLocalization.Text("daily_round.official.refresh", "Actualiser"),
                    dailyRoundController != null && !dailyRoundController.IsBusy,
                    true))
                dailyRoundController.Refresh();

            GUI.Label(
                new Rect(contentX, top + 23f, contentWidth - refreshWidth - 8f, 34f),
                OfficialDailyRoundDisclosure(model),
                new GUIStyle(tinyLabelStyle)
                {
                    fontSize = compact ? 9 : 10,
                    wordWrap = true
                });

            if (model == null || !model.HasSnapshot)
            {
                Rect unavailable = new Rect(
                    contentX,
                    top + 66f,
                    contentWidth,
                    Mathf.Max(112f, panel.yMax - top - 80f));
                DrawPremiumPanel(
                    unavailable,
                    new Color(0.034f, 0.030f, 0.024f, 0.94f),
                    new Color(0.62f, 0.48f, 0.22f, 0.74f));
                DrawGameIcon(
                    new Rect(unavailable.x + 14f, unavailable.y + 18f, 38f, 38f),
                    "quests",
                    new Color(1f, 0.82f, 0.36f, 0.92f));
                GUI.Label(
                    new Rect(unavailable.x + 62f, unavailable.y + 16f, unavailable.width - 76f, 22f),
                    BeeLocalization.Text(
                        "daily_round.official.authority.title",
                        "Progression officielle indisponible"),
                    smallStyle);
                GUI.Label(
                    new Rect(unavailable.x + 62f, unavailable.y + 42f, unavailable.width - 76f, 54f),
                    BeeLocalization.Text(
                        "daily_round.official.authority.body",
                        "Connecte une session de jeu autorisée. Aucun geste ni gain local n’est simulé."),
                    new GUIStyle(tinyLabelStyle) { wordWrap = true });
                return;
            }

            GUI.Label(
                new Rect(contentX, top + 61f, contentWidth - 92f, 18f),
                BeeLocalization.Format(
                    "daily_round.official.day",
                    model.DayUtc.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture),
                    model.NextResetUtc.ToUniversalTime().ToString("HH:mm", CultureInfo.InvariantCulture)),
                tinyLabelStyle);
            GUI.Label(
                new Rect(contentX + contentWidth - 82f, top + 59f, 82f, 20f),
                model.CompletedCount.ToString(CultureInfo.InvariantCulture) + " / 3",
                new GUIStyle(badgeStyle) { alignment = TextAnchor.MiddleRight });
            DrawProgressBar(
                new Rect(contentX, top + 82f, contentWidth, 8f),
                model.CompletedCount / 3f);

            string[] factKeys =
            {
                HiveDailyRoundClient.CollectionFact,
                HiveDailyRoundClient.OperationFact,
                HiveDailyRoundClient.SnapshotFact
            };
            string[] titles =
            {
                BeeLocalization.Text("daily_round.task.collect.title", "Récolte manuelle"),
                BeeLocalization.Text("daily_round.task.operation.title", "Lancer une opération"),
                BeeLocalization.Text("daily_round.task.ledger.title", "Vérifier les stocks")
            };
            string[] bodies =
            {
                BeeLocalization.Text("daily_round.official.task.collect.body", "Une collecte confirmée par le serveur."),
                BeeLocalization.Text("daily_round.official.task.operation.body", "Une construction ou recherche réellement démarrée."),
                BeeLocalization.Text("daily_round.official.task.ledger.body", "Un instantané officiel des stocks consulté.")
            };
            string[] icons = { "honey", "research", "inventory" };
            int[] taskBits =
            {
                DailyRoundCollectTask,
                DailyRoundOperationTask,
                DailyRoundLedgerTask
            };
            float rowsTop = top + 99f;
            float rowHeight = compact ? 58f : 62f;
            for (int i = 0; i < factKeys.Length; i++)
            {
                bool done = model.IsFactComplete(factKeys[i]);
                Color accent = done
                    ? new Color(0.48f, 0.84f, 0.42f, 0.92f)
                    : new Color(1f, 0.72f, 0.18f, 0.88f);
                Rect row = new Rect(
                    contentX,
                    rowsTop + i * (rowHeight + 4f),
                    contentWidth,
                    rowHeight);
                DrawPremiumPanel(
                    row,
                    new Color(0.034f, 0.030f, 0.024f, 0.92f),
                    accent);
                DrawGameIcon(
                    new Rect(row.x + 10f, row.y + (row.height - 32f) * 0.5f, 32f, 32f),
                    icons[i],
                    done ? Color.white : new Color(0.86f, 0.76f, 0.56f, 0.88f));
                float statusWidth = compact ? 66f : 78f;
                float textX = row.x + 50f;
                float textWidth = row.width - 58f - statusWidth;
                GUI.Label(
                    new Rect(textX, row.y + 6f, textWidth, 19f),
                    titles[i],
                    new GUIStyle(smallStyle) { fontSize = compact ? 10 : 12 });
                GUI.Label(
                    new Rect(textX, row.y + 27f, textWidth, row.height - 29f),
                    bodies[i],
                    new GUIStyle(tinyLabelStyle)
                    {
                        fontSize = compact ? 8 : 9,
                        wordWrap = true
                    });
                Rect action = new Rect(
                    row.xMax - statusWidth - 6f,
                    row.y + (row.height - 44f) * 0.5f,
                    statusWidth,
                    44f);
                if (done)
                {
                    GUI.Label(
                        action,
                        BeeLocalization.Text("daily_round.status.done", "Fait"),
                        new GUIStyle(badgeStyle)
                        {
                            alignment = TextAnchor.MiddleRight,
                            normal = { textColor = accent }
                        });
                }
                else if (DrawPreviewActionButton(
                    action,
                    BeeLocalization.Text("daily_round.action.go", "Aller"),
                    true,
                    true))
                {
                    NavigateToDailyRoundTask(taskBits[i]);
                }
            }

            float rewardY = rowsTop + 3f * (rowHeight + 4f) + 5f;
            Rect reward = new Rect(
                contentX,
                rewardY,
                contentWidth,
                Mathf.Max(82f, panel.yMax - rewardY - 12f));
            DrawPremiumPanel(
                reward,
                new Color(0.055f, 0.042f, 0.022f, 0.96f),
                new Color(1f, 0.70f, 0.16f, 0.88f));
            float actionWidth = compact ? 106f : 126f;
            float rewardTextWidth = reward.width - actionWidth - 28f;
            GUI.Label(
                new Rect(reward.x + 10f, reward.y + 7f, rewardTextWidth, 18f),
                BeeLocalization.Text("daily_round.reward.title", "Récompense de ronde"),
                smallStyle);
            GUI.Label(
                new Rect(reward.x + 10f, reward.y + 27f, rewardTextWidth, 18f),
                BeeLocalization.Format(
                    "daily_round.official.reward",
                    model.HoneyReward,
                    model.PollenReward),
                badgeStyle);
            GUI.Label(
                new Rect(reward.x + 10f, reward.y + 47f, rewardTextWidth, 32f),
                OfficialDailyRoundClaimDisclosure(model),
                new GUIStyle(tinyLabelStyle)
                {
                    fontSize = compact ? 8 : 9,
                    wordWrap = true
                });

            Rect claim = new Rect(
                reward.xMax - actionWidth - 10f,
                reward.y + Mathf.Max(8f, (reward.height - 44f) * 0.5f),
                actionWidth,
                44f);
            bool retry = model.CanRetryClaim;
            string claimLabel = model.IsClaimed
                ? BeeLocalization.Text("daily_round.reward.claimed", "Réclamée")
                : retry
                    ? BeeLocalization.Text(
                        "daily_round.official.retry",
                        "Vérifier le reçu")
                    : model.State == HiveDailyRoundScreenState.Claiming ||
                      model.State == HiveDailyRoundScreenState.PreparingClaim
                        ? BeeLocalization.Text(
                            "daily_round.official.claiming",
                            "Envoi…")
                        : BeeLocalization.Text(
                            "daily_round.reward.claim",
                            "Réclamer");
            if (DrawPreviewActionButton(
                    claim,
                    claimLabel,
                    model.CanClaim || retry))
            {
                if (retry) dailyRoundController.RetryClaim();
                else dailyRoundController.Claim();
            }
        }

        private static string OfficialDailyRoundDisclosure(
            HiveDailyRoundScreenModel model)
        {
            if (model == null || model.State == HiveDailyRoundScreenState.NotConfigured)
                return BeeLocalization.Text(
                    "daily_round.official.not_configured",
                    "Session officielle requise · aucune progression locale affichée");
            if (model.State == HiveDailyRoundScreenState.Loading)
                return model.HasSnapshot
                    ? BeeLocalization.Text(
                        "daily_round.official.loading.previous",
                        "Synchronisation · dernier état serveur conservé")
                    : BeeLocalization.Text(
                        "daily_round.official.loading",
                        "Synchronisation de la journée serveur UTC");
            if (model.State == HiveDailyRoundScreenState.OfflineReadOnly)
                return BeeLocalization.Text(
                    "daily_round.official.offline",
                    "Hors ligne · dernier état protégé en lecture seule");
            if (model.State == HiveDailyRoundScreenState.PreparingClaim ||
                model.State == HiveDailyRoundScreenState.Claiming)
                return BeeLocalization.Text(
                    "daily_round.official.claiming_disclosure",
                    "Réclamation sécurisée en cours · ne ferme pas l’application");
            if (model.State == HiveDailyRoundScreenState.ClaimPendingConfirmation)
                return BeeLocalization.Text(
                    "daily_round.official.pending",
                    "Réponse incertaine · vérifie le même reçu, sans doubler le gain");
            if (model.State == HiveDailyRoundScreenState.Error)
                return BeeLocalization.Text(
                    "daily_round.official.error",
                    "État serveur indisponible · actualise avant de continuer");
            return BeeLocalization.Text(
                "daily_round.official.ready",
                "Serveur UTC · seuls les gestes confirmés comptent");
        }

        private static string OfficialDailyRoundClaimDisclosure(
            HiveDailyRoundScreenModel model)
        {
            if (model == null)
                return BeeLocalization.Text(
                    "daily_round.official.claim.unavailable",
                    "Réclamation indisponible");
            if (model.IsClaimed)
                return BeeLocalization.Text(
                    "daily_round.official.claim.credited",
                    "Crédit serveur confirmé · reçu idempotent conservé");
            if (model.IsReadOnly)
                return BeeLocalization.Text(
                    "daily_round.official.claim.offline",
                    "Lecture seule hors ligne · aucun envoi automatique");
            if (!model.ProtectedOutboxAvailable)
                return BeeLocalization.Text(
                    "daily_round.official.claim.protection",
                    "Stockage protégé requis avant tout envoi");
            if (model.CanRetryClaim)
                return BeeLocalization.Text(
                    "daily_round.official.claim.retry",
                    "Réutilise exactement la même clé sécurisée");
            if (!model.ClaimAvailable)
                return BeeLocalization.Text(
                    "daily_round.official.claim.tasks",
                    "Termine les trois gestes confirmés par le serveur");
            return BeeLocalization.Text(
                "daily_round.official.claim.ready",
                "Le serveur crédite le miel et le pollen atomiquement");
        }

		private static bool DrawMenuHeader(Rect panel, string icon, string title, string subtitle, bool backButton = false)
		{
			DrawPremiumHeaderBand(new Rect(panel.x + 10f, panel.y + 10f, panel.width - 20f, 42f));
			bool backClicked = false;
			if (backButton)
				backClicked = DrawPremiumBackButton(new Rect(panel.x + 10f, panel.y + 9f, 44f, 44f));
			else
				DrawGameIcon(new Rect(panel.x + 22f, panel.y + 15f, 34f, 34f), icon, Color.white);
			float contentX = backButton ? 60f : 66f;
			GUI.Label(new Rect(panel.x + contentX, panel.y + 14f, panel.width - contentX - 50f, 22f), title, titleStyle);
			GUI.Label(new Rect(panel.x + contentX, panel.y + 36f, panel.width - contentX - 50f, 15f), subtitle, tinyLabelStyle);
			return backClicked;
		}

        private static void DrawArmyMenuPanel(Rect panel, bool compact)
        {
            EnsureLocalPreviewHiveProgressLoaded();
            if (perimeterSortieOpen)
            {
                DrawPerimeterSortiePanel(panel, compact);
                return;
            }
            if (formationReadinessOpen)
            {
                DrawFormationReadinessPanel(panel, compact);
                return;
            }

            if (DrawMenuHeader(
                panel,
                "sword",
                BeeLocalization.Text("hive_progress.army.title", "Armée de la ruche"),
                BeeLocalization.Text("hive_progress.army.subtitle", "Persistée sur cet appareil · autorité officielle serveur"),
                true))
            {
                AudioManager.Instance?.PlayUIClick();
                AudioManager.Instance?.PlayMenuClose();
                CloseActiveMainMenuPanel();
                activeHiveMenu = HiveMenuMode.Hive;
                detailPanelClosed = true;
                return;
            }
            Rect summary = new Rect(panel.x + 18f, panel.y + 66f, panel.width - 36f, compact ? 38f : 52f);
            DrawLocalArmySection(summary);

            string[] troops = { "Soldats", "Gardiennes", "Eclaireuses" };
            float y = summary.yMax + 12f;
            float gap = 8f;
            float width = (panel.width - 36f - gap * 2f) / 3f;
            for (int i = 0; i < troops.Length; i++)
            {
                Rect troop = new Rect(panel.x + 18f + i * (width + gap), y, width, compact ? 42f : 54f);
                bool selected = troops[i] == selectedLocalTroopType;
                DrawPremiumPanel(troop, selected ? new Color(0.060f, 0.050f, 0.034f, 0.98f) : new Color(0.045f, 0.050f, 0.040f, 0.90f), selected ? new Color(1f, 0.78f, 0.18f, 0.78f) : new Color(0.66f, 0.46f, 0.16f, 0.74f));
                if (GUI.Button(troop, string.Empty, GUIStyle.none) && !IsTrainingRunning())
                {
                    selectedLocalTroopType = troops[i];
                    SetPlayerFacingActionState("confirmation", "Troupe selectionnee", troops[i] + " pret a entrainer en preview.");
                    localPreviewLoopMessage = "Troupe choisie: " + troops[i];
                    BeginReferenceFeedbackPulse("preview");
                }

                DrawGameIcon(new Rect(troop.x + 8f, troop.y + 9f, 26f, 26f), i == 1 ? "guard-bee" : i == 2 ? "bee" : "worker-bee", Color.white);
                GUI.Label(new Rect(troop.x + 38f, troop.y + 7f, troop.width - 44f, 18f), TroopShortLabel(troops[i]), smallStyle);
                GUI.Label(new Rect(troop.x + 38f, troop.y + 27f, troop.width - 44f, 18f), TroopCount(troops[i]).ToString(CultureInfo.InvariantCulture), badgeStyle);
            }

            Rect actionRow = new Rect(panel.x + 18f, y + (compact ? 48f : 62f), panel.width - 36f, 44f);
            float prepareWidth = compact ? 108f : 118f;
            Rect action = new Rect(actionRow.x, actionRow.y, actionRow.width - prepareWidth - 8f, actionRow.height);
            Rect prepare = new Rect(action.xMax + 8f, actionRow.y, prepareWidth, actionRow.height);
            string reason = EffectiveActionDisabledReason(TrainingDisabledReason(selectedLocalTroopType));
            if (DrawPreviewActionButton(action, IsTrainingRunning() ? "Formation en cours" : "Entrainer " + selectedLocalTroopType, string.IsNullOrWhiteSpace(reason)))
            {
                StartPreviewTraining(selectedLocalTroopType);
            }
            if (DrawPreviewActionButton(prepare, BeeLocalization.Text("formation_readiness.entry", "Préparer"), true, true))
                OpenFormationReadiness();

            DrawDisabledReason(new Rect(panel.x + 18f, actionRow.yMax + 8f, panel.width - 36f, 20f), reason);
            DrawProgressBar(new Rect(panel.x + 18f, actionRow.yMax + 34f, panel.width - 36f, 9f), TrainingProgress01());
            DrawLocalContextualSpeedUpButton(panel, FindReferenceHotspot("guard_post"), compact, true);
        }

        public static Rect ArmyMenuPanelRectForProof(bool portrait, float screenWidth, float screenHeight, bool preparation)
        {
            if (portrait)
            {
                float availableHeight = Mathf.Max(270f, screenHeight - 134f - 78f - 24f);
                float portraitHeight = Mathf.Min(preparation ? 590f : 270f, availableHeight);
                return new Rect(10f, screenHeight - 78f - portraitHeight - 12f, screenWidth - 20f, portraitHeight);
            }

            bool tablet = screenWidth >= 1600f && screenHeight >= 900f;
            float width = tablet ? 430f : 360f;
            float topHud = tablet ? 132f : 112f;
            float landscapeHeight = Mathf.Min(preparation ? 650f : 500f, screenHeight - (topHud + 108f));
            return new Rect(screenWidth - width - 24f, 118f, width, landscapeHeight);
        }

