        public static string[] PerimeterSortieForProof(
            HivePerimeterSortieScreenModel model,
            bool portrait,
            float screenWidth,
            float screenHeight,
            float elapsedSeconds)
        {
            HivePerimeterSortieScreenModel safe = model ?? HivePerimeterSortiePresentation.NotConfigured();
            HivePerimeterReturnDebrief debrief = safe.ReturnDebrief;
            Rect panel = ArmyMenuPanelRectForProof(portrait, screenWidth, screenHeight, true);
            Rect back = PerimeterSortieBackRectForProof(portrait, screenWidth, screenHeight);
            Rect status = PerimeterSortieStatusRectForProof(portrait, screenWidth, screenHeight);
            Rect reservation = PerimeterSortieReservationRectForProof(portrait, screenWidth, screenHeight);
            Rect[] signals = PerimeterSortieSignalRectsForProof(portrait, screenWidth, screenHeight);
            Rect detail = PerimeterSortieDetailRectForProof(portrait, screenWidth, screenHeight);
            Rect primary = PerimeterSortiePrimaryRectForProof(portrait, screenWidth, screenHeight);
            Rect secondary = PerimeterSortieSecondaryRectForProof(portrait, screenWidth, screenHeight);
            float minimumTouch = signals.Concat(new[] { back, primary, secondary }).Min(rect => Mathf.Min(rect.width, rect.height));
            TimeSpan remaining = safe.EstimateRemaining(TimeSpan.FromSeconds(Mathf.Max(0f, elapsedSeconds)));
            return new[]
            {
                "perimeter_sortie_enabled:true",
                "perimeter_sortie_contract:" + HivePerimeterSortieClient.SortieContractVersion,
                "perimeter_sortie_state:" + PerimeterSortieStateToken(safe.State),
                "perimeter_sortie_primary_action:" + PerimeterSortieActionToken(safe.PrimaryAction),
                "perimeter_sortie_secondary_action:" + PerimeterSortieActionToken(safe.SecondaryAction),
                "perimeter_sortie_revision:" + safe.Revision.ToString(CultureInfo.InvariantCulture),
                "perimeter_sortie_signal_count:" + safe.Signals.Count.ToString(CultureInfo.InvariantCulture),
                "perimeter_sortie_reserved_total:" + safe.ReservedTotal.ToString(CultureInfo.InvariantCulture),
                "perimeter_sortie_active_signal:" + (string.IsNullOrWhiteSpace(safe.ActiveSignalKey) ? "none" : safe.ActiveSignalKey),
                "perimeter_sortie_remaining_seconds:" + Math.Ceiling(remaining.TotalSeconds).ToString("0", CultureInfo.InvariantCulture),
                "perimeter_sortie_debrief_visible:" + BoolProof(debrief != null),
                "perimeter_sortie_debrief_honey_credited:" + (debrief == null ? "0" : debrief.HoneyCredited.ToString(CultureInfo.InvariantCulture)),
                "perimeter_sortie_debrief_pollen_credited:" + (debrief == null ? "0" : debrief.PollenCredited.ToString(CultureInfo.InvariantCulture)),
                "perimeter_sortie_debrief_capacity_limited:" + BoolProof(debrief != null && debrief.AnyCapacityLimited),
                "perimeter_sortie_debrief_receipt_bound:" + BoolProof(debrief != null && debrief.SortieId != Guid.Empty && debrief.Revision > 0),
                "perimeter_sortie_debrief_device_lifetime:panel_session_only",
                "perimeter_sortie_read_only_offline:" + BoolProof(safe.ReadOnlyOffline),
                "perimeter_sortie_cached_at_utc:" + (safe.CachedAtUtc == default(DateTimeOffset) ? "none" : safe.CachedAtUtc.ToString("O", CultureInfo.InvariantCulture)),
                "perimeter_sortie_min_touch:" + minimumTouch.ToString("0", CultureInfo.InvariantCulture),
                "perimeter_sortie_panel_contains_status:" + BoolProof(RectContainsRect(panel, status)),
                "perimeter_sortie_panel_contains_reservation:" + BoolProof(RectContainsRect(panel, reservation)),
                "perimeter_sortie_panel_contains_signals:" + BoolProof(signals.All(rect => RectContainsRect(panel, rect))),
