        public static string[] FormationReadinessForProof(
            int guardians,
            int wingrunners,
            int darters,
            int legacySoldiers,
            int legacyScouts,
            string selectedFamilyToken,
            string threatToken,
            bool portrait,
            float screenWidth,
            float screenHeight)
        {
            int draftGuardians = string.Equals(selectedFamilyToken, "guardians", StringComparison.OrdinalIgnoreCase) ? Mathf.Min(guardians, HiveSquadCompositionPlanner.InitialCapacity) : 0;
            int draftWingrunners = string.Equals(selectedFamilyToken, "wingrunners", StringComparison.OrdinalIgnoreCase) ? Mathf.Min(wingrunners, HiveSquadCompositionPlanner.InitialCapacity) : 0;
            int draftDarters = string.Equals(selectedFamilyToken, "darters", StringComparison.OrdinalIgnoreCase) ? Mathf.Min(darters, HiveSquadCompositionPlanner.InitialCapacity) : 0;
            return FormationReadinessForProof(
                guardians,
                wingrunners,
                darters,
                legacySoldiers,
                legacyScouts,
                draftGuardians,
                draftWingrunners,
                draftDarters,
                selectedFamilyToken,
                threatToken,
                portrait,
                screenWidth,
                screenHeight);
        }

        public static string[] FormationReadinessForProof(
            int guardians,
            int wingrunners,
            int darters,
            int legacySoldiers,
            int legacyScouts,
            int draftGuardians,
            int draftWingrunners,
            int draftDarters,
            string selectedFamilyToken,
            string threatToken,
            bool portrait,
            float screenWidth,
            float screenHeight)
        {
            HiveFormationReadinessSnapshot snapshot = HiveFormationReadinessProjection.Project(guardians, wingrunners, darters, legacySoldiers, legacyScouts);
            HiveFormationRosterEntry selected = snapshot.Find(selectedFamilyToken);
            bool threatKnown = HiveCombatDoctrineCatalog.TryResolve(threatToken, out HiveCombatDoctrineDefinition threat);
            HiveSquadCompositionSnapshot composition = HiveSquadCompositionPlanner.Normalize(
                snapshot,
                HiveSquadCompositionPlanner.InitialCapacity,
                draftGuardians,
                draftWingrunners,
                draftDarters);
            HiveSquadDoctrineAssessment assessment = HiveSquadCompositionPlanner.Assess(composition, threatKnown ? threat.Token : string.Empty);
            Rect[] familyRects = FormationReadinessFamilyRectsForProof(portrait, screenWidth, screenHeight);
            Rect[] threatRects = FormationReadinessThreatRectsForProof(portrait, screenWidth, screenHeight);
            Rect back = FormationReadinessBackRectForProof(portrait, screenWidth, screenHeight);
            Rect recruit = FormationReadinessRecruitRectForProof(portrait, screenWidth, screenHeight);
            Rect decrease = FormationReadinessDecreaseRectForProof(portrait, screenWidth, screenHeight);
            Rect increase = FormationReadinessIncreaseRectForProof(portrait, screenWidth, screenHeight);
            Rect recommend = FormationReadinessRecommendRectForProof(portrait, screenWidth, screenHeight);
            Rect commit = FormationReadinessCommitRectForProof(portrait, screenWidth, screenHeight);
            Rect secondary =
                FormationReadinessSecondaryActionRectForProof(
                    portrait,
                    screenWidth,
                    screenHeight);
            float minimumTouch = familyRects.Concat(threatRects).Concat(new[] { back, recruit, decrease, increase, recommend, commit, secondary }).Min(rect => Mathf.Min(rect.width, rect.height));
            HiveFormationRosterEntry guardian = snapshot.Find("guardians");
            HiveFormationRosterEntry wingrunner = snapshot.Find("wingrunners");
            HiveFormationRosterEntry darter = snapshot.Find("darters");
            return new[]
            {
                "formation_readiness_enabled:true",
                "formation_readiness_catalog_version:" + HiveCombatDoctrineCatalog.Version,
                "formation_readiness_family_count:" + snapshot.Families.Count.ToString(CultureInfo.InvariantCulture),
                "formation_readiness_guardians_mapped:" + BoolProof(guardian != null && guardian.HasTrustedLocalMapping),
                "formation_readiness_guardians_count:" + (guardian == null ? "not_recorded" : guardian.EligibleCount.ToString(CultureInfo.InvariantCulture)),
                "formation_readiness_wingrunners_mapped:" + BoolProof(wingrunner != null && wingrunner.HasTrustedLocalMapping),
                "formation_readiness_wingrunners_count:" + (wingrunner == null ? "not_recorded" : wingrunner.EligibleCount.ToString(CultureInfo.InvariantCulture)),
                "formation_readiness_darters_mapped:" + BoolProof(darter != null && darter.HasTrustedLocalMapping),
                "formation_readiness_darters_count:" + (darter == null ? "not_recorded" : darter.EligibleCount.ToString(CultureInfo.InvariantCulture)),
                "formation_readiness_legacy_soldiers_unclassified:" + snapshot.UnclassifiedSoldiers.ToString(CultureInfo.InvariantCulture),
                "formation_readiness_legacy_scouts_unclassified:" + snapshot.UnclassifiedScouts.ToString(CultureInfo.InvariantCulture),
                "formation_readiness_auto_maps_soldiers_to_darters:false",
                "formation_readiness_auto_maps_scouts_to_wingrunners:false",
                "formation_readiness_selected_family:" + (selected == null ? "none" : selected.Doctrine.Token),
                "formation_readiness_selected_family_available:" + BoolProof(selected != null && selected.CanPrefillDraft),
                "formation_readiness_prefill_count:" + (selected == null ? "0" : composition.Count(selected.Doctrine.Token).ToString(CultureInfo.InvariantCulture)),
                "formation_readiness_composition_contract_version:" + HiveSquadCompositionPlanner.ContractVersion,
                "formation_readiness_composition_capacity:" + composition.Capacity.ToString(CultureInfo.InvariantCulture),
                "formation_readiness_composition_guardians:" + composition.Guardians.ToString(CultureInfo.InvariantCulture),
                "formation_readiness_composition_wingrunners:" + composition.Wingrunners.ToString(CultureInfo.InvariantCulture),
                "formation_readiness_composition_darters:" + composition.Darters.ToString(CultureInfo.InvariantCulture),
                "formation_readiness_composition_total:" + composition.Total.ToString(CultureInfo.InvariantCulture),
                "formation_readiness_composition_remaining:" + composition.Remaining.ToString(CultureInfo.InvariantCulture),
                "formation_readiness_threat:" + (threatKnown ? threat.Token : "none"),
                "formation_readiness_responsive_count:" + assessment.ResponsiveCount.ToString(CultureInfo.InvariantCulture),
                "formation_readiness_exposed_count:" + assessment.ExposedCount.ToString(CultureInfo.InvariantCulture),
                "formation_readiness_neutral_count:" + assessment.NeutralCount.ToString(CultureInfo.InvariantCulture),
                "formation_readiness_outcome:" + CombatDoctrineOutcomeId(assessment.Outcome),
                "formation_readiness_min_touch:" + minimumTouch.ToString("0", CultureInfo.InvariantCulture),
                "formation_readiness_proof_roster_source:local_preview_fixture",
                "formation_readiness_runtime_official_roster_source:server",
                "formation_readiness_recruitment_catalog_version:" + HiveDoctrineRecruitmentCatalog.Version,
                "formation_readiness_recruitment_source:guard_post",
                "formation_readiness_recruitment_queue:shared_local_training_queue",
                "formation_readiness_legacy_counts_converted:false",
                "formation_readiness_device_draft:volatile_in_memory_only",
                "formation_readiness_server_contract_status:mobile_connected_flags_closed",
                "formation_readiness_official_commit_path:protected_outbox",
                "formation_readiness_official_commit_enabled_in_fixture:false",
                "formation_readiness_units_reserved_locally:false",
                "formation_readiness_battle_simulated:false",
                "formation_readiness_mutates_gameplay:false",
                "formation_readiness_changes_protected_art:false"
            };
        }

