        public static void ChooseFormationReadinessForProof(int familyIndex, int threatIndex)
        {
            if (!formationReadinessOpen) return;
            HiveFormationReadinessSnapshot snapshot = CurrentFormationReadinessSnapshot();
            if (familyIndex >= 0 && familyIndex < snapshot.Families.Count && snapshot.Families[familyIndex].HasTrustedLocalMapping)
                formationReadinessFamilyIndex = familyIndex;
            if (threatIndex >= -1 && threatIndex < HiveCombatDoctrineCatalog.All.Count)
                formationReadinessThreatIndex = threatIndex;
        }

