        public static void PrepareFormationReadinessCaptureForProof(bool portrait)
        {
            SetPlayableHiveLoopProofState("idle");
            SetLocaleForRuntime(portrait ? "fr-CA" : "en-US");
            SetReferenceSurfaceModeForProof("hive");
            communicationPanelOpen = false;
            playerMenuOpen = false;
            vipMenuOpen = false;
            powerMenuOpen = false;
            activeMainMenuId = string.Empty;
            activeHiveMenu = HiveMenuMode.Army;
            detailPanelClosed = true;
            referenceHotspotSelected = false;
            EnsureLocalPreviewHiveProgressLoaded();
            localPreviewSoldiers = 18;
            localPreviewGuardians = 8;
            localPreviewScouts = 5;
            localPreviewWingrunners = 0;
            localPreviewDarters = 0;
            formationReadinessOpen = true;
            formationReadinessFamilyIndex = 0;
            formationReadinessThreatIndex = portrait ? 2 : 1;
            localPreviewArmyPanelMode = "formation_readiness";
            ApplyFormationDraft(HiveSquadCompositionPlanner.CreateInitial(CurrentFormationReadinessSnapshot()));
            SetMobileComfortPreferencesForProof(portrait, false, false);
        }

        public static void PrepareSquadCompositionCaptureForProof(bool portrait)
        {
            PrepareFormationReadinessCaptureForProof(portrait);
            localPreviewGuardians = 8;
            localPreviewWingrunners = 6;
            localPreviewDarters = 8;
            formationReadinessThreatIndex = portrait ? 0 : 1;
            HiveSquadCompositionSnapshot composition = portrait
                ? HiveSquadCompositionPlanner.Normalize(CurrentFormationReadinessSnapshot(), HiveSquadCompositionPlanner.InitialCapacity, 3, 6, 3)
                : HiveSquadCompositionPlanner.Normalize(CurrentFormationReadinessSnapshot(), HiveSquadCompositionPlanner.InitialCapacity, 4, 2, 6);
