        public static bool StartDoctrineRecruitmentForProof(string doctrineToken)
        {
            if (!HiveDoctrineRecruitmentCatalog.TryResolveDoctrine(doctrineToken, out HiveDoctrineRecruitmentDefinition recruitment)) return false;
            int before = localPreviewTrainingCommitCount;
            selectedLocalTroopType = recruitment.TroopType;
            StartPreviewTraining(recruitment.TroopType);
            return localPreviewTrainingCommitCount > before;
        }

        public static void CompleteDoctrineRecruitmentForProof()
        {
            if (!IsTrainingRunning()) return;
            localPreviewTrainingStartedAt = NowForUi() - localPreviewTrainingDuration - 0.1f;
            CompletePreviewTrainingIfReady();
        }

