        private static Rect[] FormationReadinessFamilyRects(Rect panel, bool compact)
        {
            float gap = compact ? 6f : 8f;
            float width = (panel.width - 36f - gap * 2f) / 3f;
            float y = panel.y + 118f;
            float height = compact ? 64f : 76f;
            return new[]
            {
                new Rect(panel.x + 18f, y, width, height),
                new Rect(panel.x + 18f + width + gap, y, width, height),
                new Rect(panel.x + 18f + (width + gap) * 2f, y, width, height)
            };
        }

        private static HiveFormationReadinessSnapshot CurrentFormationReadinessSnapshot()
        {
            HiveDoctrineRecruitmentScreenModel official =
                OfficialDoctrineRecruitmentConfigured()
                    ? OfficialDoctrineRecruitmentModel()
                    : null;
            if (official != null)
                return official.FormationRoster;
            return HiveFormationReadinessProjection.Project(
                localPreviewGuardians,
                localPreviewWingrunners,
                localPreviewDarters,
                localPreviewSoldiers,
                localPreviewScouts);
        }

        private static HiveSquadCompositionSnapshot CurrentFormationCompositionSnapshot()
        {
            HiveSquadCompositionSnapshot composition = HiveSquadCompositionPlanner.Normalize(
                CurrentFormationReadinessSnapshot(),
                HiveSquadCompositionPlanner.InitialCapacity,
                formationDraftGuardians,
                formationDraftWingrunners,
                formationDraftDarters);
            ApplyFormationDraft(composition);
            return composition;
        }

        private static void ApplyFormationDraft(HiveSquadCompositionSnapshot composition)
        {
            if (composition == null) return;
            formationDraftGuardians = composition.Guardians;
            formationDraftWingrunners = composition.Wingrunners;
            formationDraftDarters = composition.Darters;
        }

        private static void AdjustFormationComposition(string doctrineToken, int delta)
        {
            HiveSquadCompositionSnapshot before = CurrentFormationCompositionSnapshot();
            HiveSquadCompositionSnapshot after = HiveSquadCompositionPlanner.Adjust(before, CurrentFormationReadinessSnapshot(), doctrineToken, delta);
            ApplyFormationDraft(after);
            if (after.Count(doctrineToken) == before.Count(doctrineToken))
            {
                localPreviewLoopMessage = after.IsFull
                    ? BeeLocalization.Text("formation_readiness.composition.full", "Capacité atteinte")
                    : BeeLocalization.Text("formation_readiness.composition.bound", "Effectif disponible atteint");
                BeginReferenceFeedbackPulse("locked");
                return;
            }

            localPreviewLoopMessage = delta > 0
                ? BeeLocalization.Text("formation_readiness.composition.added", "Unité ajoutée au brouillon")
                : BeeLocalization.Text("formation_readiness.composition.removed", "Unité retirée du brouillon");
            BeginReferenceFeedbackPulse("preview");
        }

        private static void RecommendFormationComposition()
        {
            if (formationReadinessThreatIndex < 0 || formationReadinessThreatIndex >= HiveCombatDoctrineCatalog.All.Count)
            {
                localPreviewLoopMessage = BeeLocalization.Text("formation_readiness.composition.need_threat", "Choisis d’abord une menace");
                BeginReferenceFeedbackPulse("locked");
                return;
            }

            HiveCombatDoctrineDefinition threat = HiveCombatDoctrineCatalog.All[formationReadinessThreatIndex];
            ApplyFormationDraft(HiveSquadCompositionPlanner.Recommend(CurrentFormationReadinessSnapshot(), threat.Token));
            localPreviewLoopMessage = BeeLocalization.Text("formation_readiness.composition.recommended", "Suggestion doctrinale appliquée");
            BeginReferenceFeedbackPulse("preview");
        }

        private static HivePerimeterSortieScreenModel CurrentPerimeterSortieModel()
        {
            return perimeterSortieController == null || perimeterSortieController.Model == null
                ? HivePerimeterSortiePresentation.NotConfigured()
                : perimeterSortieController.Model;
        }

        private static void ObservePerimeterSortieModel()
        {
            HivePerimeterSortieScreenModel model = CurrentPerimeterSortieModel();
            string fingerprint = ((int)model.State).ToString(CultureInfo.InvariantCulture) + "|" +
                model.Revision.ToString(CultureInfo.InvariantCulture) + "|" +
                model.ServerTimeUtc.UtcDateTime.Ticks.ToString(CultureInfo.InvariantCulture) + "|" +
                model.ActiveSortieId.ToString("N") + "|" + model.Signals.Count.ToString(CultureInfo.InvariantCulture);
            if (!string.Equals(perimeterSortieObservationFingerprint, fingerprint, StringComparison.Ordinal))
            {
                perimeterSortieObservationFingerprint = fingerprint;
                perimeterSortieObservedAtRealtime = Time.realtimeSinceStartup;
            }

            if (model.Signals.Count == 0)
            {
                perimeterSortieSignalIndex = 0;
                return;
            }

            perimeterSortieSignalIndex = Mathf.Clamp(perimeterSortieSignalIndex, 0, model.Signals.Count - 1);
            if (!model.Signals[perimeterSortieSignalIndex].CanLaunch)
            {
                for (int index = 0; index < model.Signals.Count; index++)
                {
                    if (!model.Signals[index].CanLaunch) continue;
                    perimeterSortieSignalIndex = index;
                    break;
                }
            }
        }

        private static TimeSpan CurrentPerimeterSortieRemaining()
        {
            ObservePerimeterSortieModel();
            float elapsed = Mathf.Max(0f, Time.realtimeSinceStartup - perimeterSortieObservedAtRealtime);
            return CurrentPerimeterSortieModel().EstimateRemaining(TimeSpan.FromSeconds(elapsed));
        }

        private static void OpenPerimeterSortie()
        {
            perimeterSortieOpen = true;
            perimeterSortieSignalIndex = 0;
            perimeterSortieObservationFingerprint = string.Empty;
            perimeterSortieController.Refresh();
            ObservePerimeterSortieModel();
            localPreviewArmyPanelMode = "perimeter_sortie";
            localPreviewLoopMessage = BeeLocalization.Text("perimeter_sortie.opened", "Tableau des sorties ouvert");
            BeginReferenceFeedbackPulse("preview");
        }

        private static void ClosePerimeterSortie()
        {
            perimeterSortieOpen = false;
            localPreviewArmyPanelMode = "formation_readiness";
            localPreviewLoopMessage = BeeLocalization.Text("perimeter_sortie.closed", "Retour à l’escouade");
        }

        private static void SelectPerimeterSortieSignal(int index)
        {
            HivePerimeterSortieScreenModel model = CurrentPerimeterSortieModel();
            if (index < 0 || index >= model.Signals.Count || !model.Signals[index].CanLaunch) return;
            perimeterSortieSignalIndex = index;
            localPreviewLoopMessage = BeeLocalization.Text("perimeter_sortie.signal_selected", "Signal sélectionné");
            BeginReferenceFeedbackPulse("preview");
        }

        private static void InvokePerimeterSortiePrimary()
        {
            HivePerimeterSortieScreenModel model = CurrentPerimeterSortieModel();
            if (perimeterSortieController == null || !perimeterSortieController.IsConfigured || perimeterSortieController.IsBusy) return;
            if (model.PrimaryAction == HivePerimeterSortieAction.ReserveSquad)
            {
                ClosePerimeterSortie();
                return;
            }
            else if (model.PrimaryAction == HivePerimeterSortieAction.LaunchSignal)
            {
                if (model.Signals.Count == 0) return;
                int index = Mathf.Clamp(perimeterSortieSignalIndex, 0, model.Signals.Count - 1);
                if (!model.Signals[index].CanLaunch) return;
                perimeterSortieController.Launch(model.Signals[index].SignalKey);
            }
            else if (model.PrimaryAction == HivePerimeterSortieAction.Claim)
            {
                perimeterSortieController.Claim();
            }
            else if (model.PrimaryAction == HivePerimeterSortieAction.Retry)
            {
                perimeterSortieController.Retry();
            }
            else if (model.PrimaryAction == HivePerimeterSortieAction.DismissDebrief)
            {
                perimeterSortieController.DismissDebrief();
            }
            else
            {
                return;
            }

            perimeterSortieObservationFingerprint = string.Empty;
            ObservePerimeterSortieModel();
        }

        private static void InvokePerimeterSortieSecondary()
        {
            HivePerimeterSortieScreenModel model = CurrentPerimeterSortieModel();
            if (perimeterSortieController == null || !perimeterSortieController.IsConfigured || perimeterSortieController.IsBusy ||
                model.SecondaryAction != HivePerimeterSortieAction.Recall) return;
            perimeterSortieController.Recall();
            perimeterSortieObservationFingerprint = string.Empty;
            ObservePerimeterSortieModel();
        }

        private static void OpenFormationReadiness()
        {
            EnsureLocalPreviewHiveProgressLoaded();
            if (OfficialDoctrineRecruitmentConfigured() &&
                doctrineRecruitmentController != null &&
                !doctrineRecruitmentController.IsBusy)
                doctrineRecruitmentController.Refresh();
            if (OfficialSquadReservationConfigured() &&
                squadReservationController != null &&
                !squadReservationController.IsBusy)
                squadReservationController.Refresh();
            formationReadinessOpen = true;
            formationReadinessFamilyIndex = 0;
            formationReadinessThreatIndex = -1;
            HiveSquadReservationScreenModel reservation =
                OfficialSquadReservationModel();
            ApplyFormationDraft(
                reservation != null && reservation.HasReservation
                    ? reservation.ReservedComposition()
                    : HiveSquadCompositionPlanner.CreateInitial(
                        CurrentFormationReadinessSnapshot()));
            localPreviewArmyPanelMode = "formation_readiness";
            localPreviewLoopMessage = BeeLocalization.Text("formation_readiness.opened", "Préparation d’escouade ouverte");
            BeginReferenceFeedbackPulse("preview");
        }

        private static void CloseFormationReadiness()
        {
            ResetFormationReadinessDraft();
            localPreviewLoopMessage = BeeLocalization.Text("formation_readiness.closed", "Retour à l’entraînement");
        }

