        private static string FormationReadinessDisclosure()
        {
            if (!OfficialDoctrineRecruitmentConfigured())
                return BeeLocalization.Text(
                    "formation_readiness.local_disclosure",
                    "BROUILLON LOCAL · aucun effectif réservé");
            if (OfficialSquadReservationConfigured())
            {
                HiveSquadReservationScreenModel reservation =
                    OfficialSquadReservationModel();
                if (reservation != null)
                {
                    switch (reservation.State)
                    {
                        case HiveSquadReservationScreenState.NotConfigured:
                            return BeeLocalization.Text(
                                "formation_readiness.reservation.not_configured",
                                "SESSION SERVEUR REQUISE · AUCUNE RÉSERVATION INVENTÉE");
                        case HiveSquadReservationScreenState.Loading:
                            return BeeLocalization.Text(
                                "formation_readiness.reservation.loading",
                                "LECTURE DE LA RÉSERVATION SERVEUR");
                        case HiveSquadReservationScreenState.OfflineReadOnly:
                            return BeeLocalization.Text(
                                "formation_readiness.reservation.offline",
                                "HORS LIGNE · RÉSERVATION EN LECTURE SEULE");
                        case HiveSquadReservationScreenState.Mutating:
                            return BeeLocalization.Text(
                                "formation_readiness.reservation.mutating",
                                "RÉSERVATION SERVEUR EN COURS");
                        case HiveSquadReservationScreenState.PendingConfirmation:
                            return BeeLocalization.Text(
                                "formation_readiness.reservation.pending",
                                "RÉSULTAT INCERTAIN · VÉRIFICATION EXPLICITE");
                        case HiveSquadReservationScreenState.Error:
                            return BeeLocalization.Text(
                                "formation_readiness.reservation.error",
                                "RÉSERVATION INDISPONIBLE · ACTUALISER");
                        case HiveSquadReservationScreenState.Ready:
                            return reservation.HasReservation
                                ? string.Format(
                                    CultureInfo.CurrentCulture,
                                    BeeLocalization.Text(
                                        "formation_readiness.reservation.active",
                                        "ESCOUADE RÉSERVÉE SERVEUR · {0}/{1}"),
                                    reservation.ReservedTotal,
                                    reservation.Capacity)
                                : BeeLocalization.Text(
                                    "formation_readiness.reservation.ready",
                                    "ROSTER SERVEUR · BROUILLON À RÉSERVER");
                    }
                }
            }
            HiveDoctrineRecruitmentScreenModel model =
                OfficialDoctrineRecruitmentModel();
            if (model == null)
                return BeeLocalization.Text(
                    "formation_readiness.official.not_configured",
                    "SERVEUR REQUIS · aucun effectif inventé");
            switch (model.State)
            {
                case HiveDoctrineRecruitmentScreenState.Loading:
                    return BeeLocalization.Text(
                        "formation_readiness.official.loading",
                        "LECTURE DU ROSTER SERVEUR");
                case HiveDoctrineRecruitmentScreenState.OfflineReadOnly:
                    return BeeLocalization.Text(
                        "formation_readiness.official.offline",
                        "CONSULTATION HORS LIGNE · aucune formation");
                case HiveDoctrineRecruitmentScreenState.Mutating:
                    return BeeLocalization.Text(
                        "formation_readiness.official.mutating",
                        "COMMANDE SERVEUR EN COURS");
                case HiveDoctrineRecruitmentScreenState.PendingConfirmation:
                    return BeeLocalization.Text(
                        "formation_readiness.official.pending",
                        "RÉSULTAT INCERTAIN · vérifier sans nouvelle commande");
                case HiveDoctrineRecruitmentScreenState.Error:
                    return BeeLocalization.Text(
                        "formation_readiness.official.error",
                        "ROSTER SERVEUR INDISPONIBLE · actualiser");
                default:
                    return BeeLocalization.Text(
                        "formation_readiness.official.ready",
                        "ROSTER SERVEUR · brouillon non réservé");
            }
        }

        private static string OfficialDoctrineRecruitmentActionLabel(
            string family)
        {
            HiveDoctrineRecruitmentScreenModel model =
                OfficialDoctrineRecruitmentModel();
            if (model == null)
                return BeeLocalization.Text(
                    "formation_readiness.official.server_required",
                    "Serveur requis");
            HiveDoctrineRecruitmentOfferModel offer =
                model.FindOffer(family);
            if (offer == null)
                return BeeLocalization.Text(
                    "formation_readiness.official.unavailable",
                    "Indisponible");
            if (model.IsPending &&
                model.CanRetry(family))
                return BeeLocalization.Text(
                    "formation_readiness.official.verify",
                    "Vérifier");
            if (model.State ==
                    HiveDoctrineRecruitmentScreenState.Loading ||
                model.State ==
                    HiveDoctrineRecruitmentScreenState.Mutating)
                return BeeLocalization.Text(
                    "formation_readiness.official.loading_short",
                    "Chargement");
            if (model.State ==
                HiveDoctrineRecruitmentScreenState.OfflineReadOnly)
                return BeeLocalization.Text(
                    "formation_readiness.official.offline_short",
                    "Hors ligne");
            if (model.State ==
                    HiveDoctrineRecruitmentScreenState.Error ||
                model.State ==
                    HiveDoctrineRecruitmentScreenState.NotConfigured)
                return BeeLocalization.Text(
                    "formation_readiness.official.refresh",
                    "Actualiser");
            HiveDoctrineRecruitmentOperationModel active =
                model.ActiveOperation;
            if (active != null)
            {
                if (!string.Equals(
                        active.Family,
                        family,
                        StringComparison.Ordinal))
                    return BeeLocalization.Text(
                        "formation_readiness.official.queue_busy",
                        "File occupée");
                if (active.AwaitingCompletion)
                    return string.Format(
                        CultureInfo.CurrentCulture,
                        BeeLocalization.Text(
                            "formation_readiness.official.claim",
                            "Réclamer +{0}"),
                        active.BatchSize);
                TimeSpan remaining = model.Remaining(
                    doctrineRecruitmentController.Elapsed);
                if (remaining <= TimeSpan.Zero)
                    return BeeLocalization.Text(
                        "formation_readiness.official.refresh",
                        "Actualiser");
                return string.Format(
                    CultureInfo.CurrentCulture,
                    BeeLocalization.Text(
                        "formation_readiness.official.running",
                        "En cours {0}s"),
                    Math.Max(1, (int)Math.Ceiling(
                        remaining.TotalSeconds)));
            }
            if (model.CanStart(family))
                return string.Format(
                    CultureInfo.CurrentCulture,
                    BeeLocalization.Text(
                        "formation_readiness.recruitment.start",
                        "Former +{0}"),
                    offer.BatchSize);
            if (!model.ProtectedOutboxAvailable)
                return BeeLocalization.Text(
                    "formation_readiness.official.protected_store_required",
                    "Coffre requis");
            return BeeLocalization.Text(
                "formation_readiness.official.insufficient",
                "Stocks insuffisants");
        }

        private static bool OfficialDoctrineRecruitmentActionEnabled(
            string family)
        {
            if (!OfficialDoctrineRecruitmentConfigured() ||
                doctrineRecruitmentController == null ||
                doctrineRecruitmentController.IsBusy)
                return false;
            HiveDoctrineRecruitmentScreenModel model =
                OfficialDoctrineRecruitmentModel();
            if (model == null) return false;
            if (model.IsPending) return model.CanRetry(family);
            if (model.State ==
                    HiveDoctrineRecruitmentScreenState.Error ||
                model.State ==
                    HiveDoctrineRecruitmentScreenState.NotConfigured)
                return true;
            HiveDoctrineRecruitmentOperationModel active =
                model.ActiveOperation;
            if (active != null &&
                string.Equals(
                    active.Family,
                    family,
                    StringComparison.Ordinal))
                return active.AwaitingCompletion ||
                    model.Remaining(
                        doctrineRecruitmentController.Elapsed) <=
                    TimeSpan.Zero;
            return model.CanStart(family);
        }

        private static void RunOfficialDoctrineRecruitmentAction(
            string family)
        {
            if (!OfficialDoctrineRecruitmentActionEnabled(family))
                return;
            HiveDoctrineRecruitmentScreenModel model =
                OfficialDoctrineRecruitmentModel();
            if (model == null) return;
            if (model.IsPending)
            {
                doctrineRecruitmentController.Retry();
                return;
            }
            if (model.State ==
                    HiveDoctrineRecruitmentScreenState.Error ||
                model.State ==
                    HiveDoctrineRecruitmentScreenState.NotConfigured)
            {
                doctrineRecruitmentController.Refresh();
                return;
            }
            HiveDoctrineRecruitmentOperationModel active =
                model.ActiveOperation;
            if (active != null &&
                string.Equals(
                    active.Family,
                    family,
                    StringComparison.Ordinal))
            {
                if (active.AwaitingCompletion)
                {
                    AudioManager.Instance?.PlayCollectTroop();
                    doctrineRecruitmentController.Claim();
                }
                else
                    doctrineRecruitmentController.Refresh();
                return;
            }
            doctrineRecruitmentController.Start(family);
        }

