        private static void DrawPerimeterSortiePanel(Rect panel, bool compact)
        {
            ObservePerimeterSortieModel();
            HivePerimeterSortieScreenModel model = CurrentPerimeterSortieModel();
            DrawPremiumHeaderBand(new Rect(panel.x + 10f, panel.y + 10f, panel.width - 20f, 42f));
            DrawGameIcon(new Rect(panel.x + 22f, panel.y + 15f, 34f, 34f), "map", Color.white);
            GUI.Label(new Rect(panel.x + 66f, panel.y + 14f, panel.width - 190f, 22f), BeeLocalization.Text("perimeter_sortie.title", "Sorties au périmètre"), titleStyle);
            string subtitle = compact
                ? BeeLocalization.Text("perimeter_sortie.subtitle.compact", "Signaux non-combat")
                : BeeLocalization.Text("perimeter_sortie.subtitle", "Signaux non-combat · autorité serveur");
            GUI.Label(new Rect(panel.x + 66f, panel.y + 36f, panel.width - 190f, 15f), subtitle, tinyLabelStyle);
            Rect back = PerimeterSortieBackRectForProof(compact, Screen.width, Screen.height);
            if (DrawPreviewActionButton(back, BeeLocalization.Text("perimeter_sortie.back", "Escouade"), true, true))
            {
                ClosePerimeterSortie();
                return;
            }

            if (model.State == HivePerimeterSortieScreenState.ReturnDebrief && model.ReturnDebrief != null)
            {
                DrawPerimeterReturnDebrief(panel, model.ReturnDebrief, compact);
                return;
            }

            Rect status = PerimeterSortieStatusRectForProof(compact, Screen.width, Screen.height);
            Color statusAccent = PerimeterSortieStateAccent(model.State);
            DrawPremiumPanel(status, new Color(statusAccent.r * 0.10f, statusAccent.g * 0.10f, statusAccent.b * 0.10f, 0.97f), new Color(statusAccent.r, statusAccent.g, statusAccent.b, 0.76f));
            PerimeterSortieStateCopy(model.State, out string statusTitle, out string statusBody);
            if (model.State ==
                HivePerimeterSortieScreenState.PendingConfirmation)
                statusBody = PerimeterSortiePendingCopy(
                    model.PendingKind);
            if (model.ReadOnlyOffline)
            {
                statusTitle = BeeLocalization.Text("perimeter_sortie.offline.title", "CONSULTATION HORS LIGNE");
                statusBody = BeeLocalization.Text(
                    "perimeter_sortie.offline.body",
                    "Dernier état protégé de cet appareil · aucune action, récompense ou progression.");
            }
            GUI.Label(new Rect(status.x + 10f, status.y + 6f, status.width - 20f, 18f), statusTitle, badgeStyle);
            GUI.Label(new Rect(status.x + 10f, status.y + 25f, status.width - 20f, 27f), statusBody, new GUIStyle(tinyLabelStyle) { wordWrap = true, fontSize = compact ? 8 : 10 });
            if (perimeterSortieProofDisclosure)
                GUI.Label(new Rect(status.xMax - 114f, status.y + 5f, 104f, 16f), BeeLocalization.Text("perimeter_sortie.proof_disclosure", "APERÇU QA"), new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleRight, fontSize = compact ? 8 : 9 });

            Rect reservation = PerimeterSortieReservationRectForProof(compact, Screen.width, Screen.height);
            DrawPremiumPanel(reservation, new Color(0.032f, 0.038f, 0.040f, 0.96f), new Color(0.38f, 0.62f, 0.68f, 0.62f));
            DrawGameIcon(new Rect(reservation.x + 8f, reservation.y + 9f, 28f, 28f), "guard-bee", Color.white);
            GUI.Label(new Rect(reservation.x + 44f, reservation.y + 5f, reservation.width - 52f, 18f), BeeLocalization.Text("perimeter_sortie.reservation.title", "RÉSERVATION D’ESCOUADE"), tinyLabelStyle);
            string reservationBody = model.ReservedTotal > 0
                ? string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("perimeter_sortie.reservation.ready", "{0} abeilles réservées · libérées après retour"), model.ReservedTotal)
                : BeeLocalization.Text("perimeter_sortie.reservation.empty", "Aucune réservation officielle · le brouillon local reste intact");
            GUI.Label(new Rect(reservation.x + 44f, reservation.y + 23f, reservation.width - 52f, 19f), reservationBody, new GUIStyle(tinyLabelStyle) { wordWrap = true, fontSize = compact ? 8 : 10 });

            Rect[] signalRects = PerimeterSortieSignalRectsForProof(compact, Screen.width, Screen.height);
            GUI.Label(new Rect(signalRects[0].x, signalRects[0].y - 22f, signalRects[signalRects.Length - 1].xMax - signalRects[0].x, 18f), BeeLocalization.Text("perimeter_sortie.signals.label", "SIGNAUX DU CYCLE"), tinyLabelStyle);
            for (int index = 0; index < signalRects.Length; index++)
            {
                HivePerimeterSignalCard signal = index < model.Signals.Count ? model.Signals[index] : null;
                DrawPerimeterSortieSignalCard(signalRects[index], signal, index, model, compact);
            }

            Rect detail = PerimeterSortieDetailRectForProof(compact, Screen.width, Screen.height);
            DrawPremiumPanel(detail, new Color(0.026f, 0.030f, 0.034f, 0.97f), new Color(0.52f, 0.42f, 0.22f, 0.60f));
            DrawPerimeterSortieDetail(detail, model, compact);

            Rect primary = PerimeterSortiePrimaryRectForProof(compact, Screen.width, Screen.height);
            Rect secondary = PerimeterSortieSecondaryRectForProof(compact, Screen.width, Screen.height);
            bool configured = perimeterSortieController != null && perimeterSortieController.IsConfigured;
            bool busy = perimeterSortieController != null && perimeterSortieController.IsBusy;
            HiveSquadCompositionSnapshot composition = CurrentFormationCompositionSnapshot();
            HivePerimeterSignalCard selected = SelectedPerimeterSortieSignal(model);
            bool primaryEnabled = configured && !busy &&
                (model.PrimaryAction == HivePerimeterSortieAction.ReserveSquad ||
                 (model.PrimaryAction == HivePerimeterSortieAction.LaunchSignal && selected != null && selected.CanLaunch) ||
                 model.PrimaryAction == HivePerimeterSortieAction.Claim ||
                 (model.PrimaryAction == HivePerimeterSortieAction.Retry && model.CanRetry) ||
                 model.PrimaryAction == HivePerimeterSortieAction.DismissDebrief);
            string primaryLabel = PerimeterSortiePrimaryLabel(model, composition, busy);
            if (DrawPreviewActionButton(primary, primaryLabel, primaryEnabled)) InvokePerimeterSortiePrimary();

            bool recallEnabled = configured && !busy && model.SecondaryAction == HivePerimeterSortieAction.Recall;
            string secondaryLabel = model.SecondaryAction == HivePerimeterSortieAction.Recall
                ? BeeLocalization.Text("perimeter_sortie.action.recall", "Rappeler")
                : BeeLocalization.Text("perimeter_sortie.action.no_recall", "Aucun rappel");
            if (DrawPreviewActionButton(secondary, secondaryLabel, recallEnabled)) InvokePerimeterSortieSecondary();
        }

        private static void DrawPerimeterReturnDebrief(
            Rect panel,
            HivePerimeterReturnDebrief debrief,
            bool compact)
        {
            Rect status = PerimeterSortieStatusRectForProof(compact, Screen.width, Screen.height);
            Color accent = new Color(0.40f, 0.86f, 0.50f, 1f);
            DrawPremiumPanel(status, new Color(0.035f, 0.085f, 0.045f, 0.98f), new Color(accent.r, accent.g, accent.b, 0.84f));
            string signalName = BeeLocalization.Text("perimeter_sortie.signal." + debrief.SignalKey + ".name", debrief.SignalKey);
            GUI.Label(new Rect(status.x + 10f, status.y + 6f, status.width - 20f, 18f), BeeLocalization.Text("perimeter_sortie.debrief.title", "RETOUR CONFIRMÉ"), badgeStyle);
            GUI.Label(
                new Rect(status.x + 10f, status.y + 25f, status.width - 20f, 27f),
                string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("perimeter_sortie.debrief.subtitle", "{0} · reçu serveur vérifié"), signalName),
                new GUIStyle(tinyLabelStyle) { wordWrap = true, fontSize = compact ? 8 : 10 });
            if (perimeterSortieProofDisclosure)
                GUI.Label(new Rect(status.xMax - 114f, status.y + 5f, 104f, 16f), BeeLocalization.Text("perimeter_sortie.proof_disclosure", "APERÇU QA"), new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleRight, fontSize = compact ? 8 : 9 });

            Rect receipt = PerimeterSortieReservationRectForProof(compact, Screen.width, Screen.height);
            DrawPremiumPanel(receipt, new Color(0.026f, 0.038f, 0.044f, 0.97f), new Color(0.38f, 0.68f, 0.82f, 0.68f));
            DrawGameIcon(new Rect(receipt.x + 8f, receipt.y + 9f, 28f, 28f), "server", Color.white);
            GUI.Label(new Rect(receipt.x + 44f, receipt.y + 5f, receipt.width - 52f, 18f), BeeLocalization.Text("perimeter_sortie.debrief.receipt", "PREUVE DURABLE DU SERVEUR"), tinyLabelStyle);
            GUI.Label(
                new Rect(receipt.x + 44f, receipt.y + 23f, receipt.width - 52f, 19f),
                string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("perimeter_sortie.debrief.revision", "Révision {0} · aucun crédit créé sur l’appareil"), debrief.Revision),
                new GUIStyle(tinyLabelStyle) { wordWrap = true, fontSize = compact ? 8 : 10 });

            Rect[] resources = PerimeterSortieSignalRectsForProof(compact, Screen.width, Screen.height);
            GUI.Label(new Rect(resources[0].x, resources[0].y - 22f, resources[resources.Length - 1].xMax - resources[0].x, 18f), BeeLocalization.Text("perimeter_sortie.debrief.resources", "CRÉDIT RÉEL"), tinyLabelStyle);
            DrawPerimeterDebriefResource(resources[0], "honey", debrief.HoneyCredited, debrief.HoneyExpected, debrief.HoneyBalance, debrief.HoneyCapacity, compact);
            DrawPerimeterDebriefResource(resources[1], "pollen", debrief.PollenCredited, debrief.PollenExpected, debrief.PollenBalance, debrief.PollenCapacity, compact);

            Rect detail = PerimeterSortieDetailRectForProof(compact, Screen.width, Screen.height);
            DrawPremiumPanel(detail, new Color(0.030f, 0.034f, 0.030f, 0.98f), new Color(0.64f, 0.54f, 0.26f, 0.68f));
            GUI.Label(new Rect(detail.x + 10f, detail.y + 7f, detail.width - 20f, 18f), BeeLocalization.Text("perimeter_sortie.debrief.result", "RÉSULTAT EXACT"), badgeStyle);
            string result = debrief.AnyCapacityLimited
                ? BeeLocalization.Text("perimeter_sortie.debrief.capacity_limited", "Une réserve était pleine : le serveur a seulement crédité l’espace disponible.")
                : BeeLocalization.Text("perimeter_sortie.debrief.full_credit", "La totalité de la récompense annoncée a été créditée par le serveur.");
            GUI.Label(new Rect(detail.x + 10f, detail.y + 29f, detail.width - 20f, Mathf.Max(22f, detail.height - 58f)), result, new GUIStyle(smallStyle) { wordWrap = true, fontSize = compact ? 9 : 11 });
            GUI.Label(new Rect(detail.x + 10f, detail.yMax - 26f, detail.width - 20f, 20f), BeeLocalization.Text("perimeter_sortie.debrief.disclosure", "Reçu conservé seulement pendant cette consultation."), new GUIStyle(tinyLabelStyle) { wordWrap = true, fontSize = compact ? 8 : 9 });

            Rect primary = PerimeterSortiePrimaryRectForProof(compact, Screen.width, Screen.height);
            Rect secondary = PerimeterSortieSecondaryRectForProof(compact, Screen.width, Screen.height);
            bool enabled = perimeterSortieController != null && perimeterSortieController.IsConfigured && !perimeterSortieController.IsBusy;
            if (DrawPreviewActionButton(primary, BeeLocalization.Text("perimeter_sortie.debrief.continue", "Continuer"), enabled, true))
                InvokePerimeterSortiePrimary();
            DrawPreviewActionButton(secondary, BeeLocalization.Text("perimeter_sortie.debrief.verified", "Reçu vérifié"), false);
        }

        private static void DrawPerimeterDebriefResource(
            Rect rect,
            string resourceKey,
            long credited,
            long expected,
            long balance,
            long capacity,
            bool compact)
        {
            bool limited = credited < expected;
            Color accent = limited ? new Color(0.96f, 0.62f, 0.18f, 1f) : new Color(0.42f, 0.82f, 0.48f, 1f);
            DrawPremiumPanel(rect, new Color(accent.r * 0.10f, accent.g * 0.10f, accent.b * 0.10f, 0.98f), new Color(accent.r, accent.g, accent.b, 0.76f));
            DrawGameIcon(new Rect(rect.x + 8f, rect.y + 8f, compact ? 26f : 30f, compact ? 26f : 30f), resourceKey, Color.white);
            string name = BeeLocalization.Text("perimeter_sortie.debrief.resource." + resourceKey, resourceKey);
            GUI.Label(new Rect(rect.x + 42f, rect.y + 7f, rect.width - 50f, 18f), name, new GUIStyle(smallStyle) { fontSize = compact ? 10 : 12 });
            float creditY = compact ? rect.y + 23f : rect.y + 34f;
            float stockY = compact ? rect.y + 48f : rect.yMax - 39f;
            float stateY = compact ? rect.y + 64f : rect.yMax - 21f;
            GUI.Label(new Rect(rect.x + 8f, creditY, rect.width - 16f, 24f), "+" + credited.ToString(CultureInfo.CurrentCulture), new GUIStyle(titleStyle) { fontSize = compact ? 18 : 22, alignment = TextAnchor.MiddleCenter });
            string stock = string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("perimeter_sortie.debrief.stock", "Stock {0}/{1}"), balance, capacity);
            GUI.Label(new Rect(rect.x + 8f, stockY, rect.width - 16f, compact ? 14f : 17f), stock, new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter, fontSize = compact ? 8 : 9 });
            string state = limited
                ? BeeLocalization.Text("perimeter_sortie.debrief.limited", "Capacité atteinte")
                : BeeLocalization.Text("perimeter_sortie.debrief.complete", "Crédit complet");
            GUI.Label(new Rect(rect.x + 8f, stateY, rect.width - 16f, compact ? 14f : 16f), state, new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter, normal = { textColor = accent }, fontSize = compact ? 8 : 9 });
        }

        private static void DrawPerimeterSortieSignalCard(Rect rect, HivePerimeterSignalCard signal, int index, HivePerimeterSortieScreenModel model, bool compact)
        {
            if (signal == null)
            {
                DrawPremiumPanel(rect, new Color(0.025f, 0.028f, 0.030f, 0.94f), new Color(0.34f, 0.36f, 0.38f, 0.46f));
                GUI.Label(new Rect(rect.x + 8f, rect.y + 8f, rect.width - 16f, rect.height - 16f), BeeLocalization.Text("perimeter_sortie.signal.waiting", "En attente du serveur"), new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter, wordWrap = true });
                return;
            }

            bool selected = perimeterSortieSignalIndex == index && signal.CanLaunch && model.State == HivePerimeterSortieScreenState.ReadyToLaunch;
            Color accent = signal.Completed ? new Color(0.42f, 0.70f, 0.48f, 1f) : selected ? new Color(0.96f, 0.70f, 0.18f, 1f) : new Color(0.40f, 0.62f, 0.72f, 1f);
            DrawPremiumPanel(rect, new Color(accent.r * 0.10f, accent.g * 0.10f, accent.b * 0.10f, 0.97f), new Color(accent.r, accent.g, accent.b, selected ? 0.90f : 0.58f));
            if (GUI.Button(rect, string.Empty, GUIStyle.none) && signal.CanLaunch && model.State == HivePerimeterSortieScreenState.ReadyToLaunch)
                SelectPerimeterSortieSignal(index);

            string name = BeeLocalization.Text("perimeter_sortie.signal." + signal.SignalKey + ".name", signal.SignalKey);
            string state = signal.Completed
                ? BeeLocalization.Text("perimeter_sortie.signal.completed", "Terminé")
                : signal.CanLaunch ? BeeLocalization.Text("perimeter_sortie.signal.available", "Disponible") : BeeLocalization.Text("perimeter_sortie.signal.locked", "Indisponible");
            GUI.Label(new Rect(rect.x + 8f, rect.y + 6f, Mathf.Max(52f, rect.width - 104f), 18f), name, new GUIStyle(smallStyle) { fontSize = compact ? 10 : 12 });
            GUI.Label(new Rect(rect.xMax - 88f, rect.y + 6f, 80f, 18f), state, new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleRight, fontSize = compact ? 8 : 9 });
            string hazardName = BeeLocalization.Text("combat_doctrine.family." + signal.HazardDoctrine + ".name", signal.HazardDoctrine);
            GUI.Label(new Rect(rect.x + 8f, rect.y + 28f, rect.width - 16f, 17f), string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("perimeter_sortie.signal.hazard", "Risque · {0}"), hazardName), tinyLabelStyle);
            GUI.Label(new Rect(rect.x + 8f, rect.y + 47f, rect.width - 16f, 17f), string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("perimeter_sortie.signal.requirement", "{0} abeille(s) min · {1}s"), signal.MinimumSquad, Math.Ceiling(signal.Duration.TotalSeconds)), tinyLabelStyle);
            GUI.Label(new Rect(rect.x + 8f, rect.yMax - 22f, rect.width - 16f, 17f), string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("perimeter_sortie.signal.reward", "+{0} miel · +{1} pollen"), signal.HoneyReward, signal.PollenReward), badgeStyle);
        }

        private static void DrawPerimeterSortieDetail(Rect rect, HivePerimeterSortieScreenModel model, bool compact)
        {
            if (model.State == HivePerimeterSortieScreenState.Active || model.State == HivePerimeterSortieScreenState.ClaimReady)
            {
                TimeSpan remaining = CurrentPerimeterSortieRemaining();
                string activeName = BeeLocalization.Text("perimeter_sortie.signal." + model.ActiveSignalKey + ".name", model.ActiveSignalKey);
                GUI.Label(new Rect(rect.x + 10f, rect.y + 7f, rect.width - 20f, 18f), string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("perimeter_sortie.active.title", "SORTIE ACTIVE · {0}"), activeName), badgeStyle);
                string timer = model.State == HivePerimeterSortieScreenState.ClaimReady
                    ? BeeLocalization.Text("perimeter_sortie.active.ready", "Retour confirmé par l’heure serveur · récompense réclamable")
                    : string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("perimeter_sortie.active.remaining", "Retour estimé dans {0}s · référence serveur"), Math.Ceiling(remaining.TotalSeconds));
                GUI.Label(new Rect(rect.x + 10f, rect.y + 28f, rect.width - 20f, 30f), timer, new GUIStyle(smallStyle) { wordWrap = true, fontSize = compact ? 9 : 11 });
                GUI.Label(new Rect(rect.x + 10f, rect.yMax - 28f, rect.width - 20f, 22f), BeeLocalization.Text("perimeter_sortie.active.disclosure", "Rappeler libère l’escouade sans récompense. Le mobile ne crédite rien."), new GUIStyle(tinyLabelStyle) { wordWrap = true, fontSize = compact ? 8 : 9 });
                return;
            }

            HivePerimeterSignalCard selected = SelectedPerimeterSortieSignal(model);
            string title = selected == null
                ? BeeLocalization.Text("perimeter_sortie.detail.title", "AUCUN ORDRE LOCAL")
                : BeeLocalization.Text("perimeter_sortie.signal." + selected.SignalKey + ".name", selected.SignalKey);
            GUI.Label(new Rect(rect.x + 10f, rect.y + 7f, rect.width - 20f, 18f), title, badgeStyle);
            string body = selected == null
                ? BeeLocalization.Text("perimeter_sortie.detail.body", "Connecte une session officielle pour lire les signaux. Aucun statut n’est simulé.")
                : BeeLocalization.Text("perimeter_sortie.signal." + selected.SignalKey + ".body", "Signal non-combat du périmètre.");
            GUI.Label(new Rect(rect.x + 10f, rect.y + 28f, rect.width - 20f, Mathf.Max(22f, rect.height - 58f)), body, new GUIStyle(smallStyle) { wordWrap = true, fontSize = compact ? 9 : 11 });
            GUI.Label(new Rect(rect.x + 10f, rect.yMax - 26f, rect.width - 20f, 20f), BeeLocalization.Text("perimeter_sortie.server_disclosure", "Cycle, heure, réservation et récompense restent serveur."), new GUIStyle(tinyLabelStyle) { wordWrap = true, fontSize = compact ? 8 : 9 });
        }

        private static HivePerimeterSignalCard SelectedPerimeterSortieSignal(HivePerimeterSortieScreenModel model)
        {
            if (model == null || model.Signals.Count == 0) return null;
            int index = Mathf.Clamp(perimeterSortieSignalIndex, 0, model.Signals.Count - 1);
            return model.Signals[index];
        }

        private static string PerimeterSortiePrimaryLabel(HivePerimeterSortieScreenModel model, HiveSquadCompositionSnapshot composition, bool busy)
        {
            if (busy) return BeeLocalization.Text("perimeter_sortie.action.syncing", "Synchronisation…");
            if (model.PrimaryAction == HivePerimeterSortieAction.ReserveSquad)
                return BeeLocalization.Text(
                    "formation_readiness.reservation.back_to_composition",
                    "Retour à la composition");
            if (model.PrimaryAction == HivePerimeterSortieAction.LaunchSignal)
            {
                HivePerimeterSignalCard signal = SelectedPerimeterSortieSignal(model);
                string name = signal == null ? string.Empty : BeeLocalization.Text("perimeter_sortie.signal." + signal.SignalKey + ".name", signal.SignalKey);
                return string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("perimeter_sortie.action.launch", "Lancer · {0}"), name);
            }
            if (model.PrimaryAction == HivePerimeterSortieAction.Claim)
                return BeeLocalization.Text("perimeter_sortie.action.claim", "Réclamer");
            if (model.PrimaryAction == HivePerimeterSortieAction.DismissDebrief)
                return BeeLocalization.Text("perimeter_sortie.debrief.continue", "Continuer");
            if (model.State == HivePerimeterSortieScreenState.CycleComplete)
                return BeeLocalization.Text("perimeter_sortie.action.complete", "Cycle terminé");
            if (model.State == HivePerimeterSortieScreenState.NotConfigured)
                return BeeLocalization.Text("perimeter_sortie.action.session_required", "Session requise");
            return BeeLocalization.Text("perimeter_sortie.action.wait", "Attendre le serveur");
        }

        private static void PerimeterSortieStateCopy(HivePerimeterSortieScreenState state, out string title, out string body)
        {
            if (state == HivePerimeterSortieScreenState.Loading)
            {
                title = BeeLocalization.Text("perimeter_sortie.status.loading.title", "Lecture du périmètre");
                body = BeeLocalization.Text("perimeter_sortie.status.loading.body", "Le serveur prépare un snapshot lié à cette ruche.");
            }
            else if (state == HivePerimeterSortieScreenState.NeedsReservation)
            {
                title = BeeLocalization.Text("perimeter_sortie.status.reserve.title", "Escouade à réserver");
                body = BeeLocalization.Text("perimeter_sortie.status.reserve.body", "Le brouillon reste local jusqu’à la confirmation atomique du serveur.");
            }
            else if (state == HivePerimeterSortieScreenState.ReadyToLaunch)
            {
                title = BeeLocalization.Text("perimeter_sortie.status.ready.title", "Périmètre lisible");
                body = BeeLocalization.Text("perimeter_sortie.status.ready.body", "Choisis un signal. Il ne s’agit ni d’un combat ni d’une victoire garantie.");
            }
            else if (state == HivePerimeterSortieScreenState.Active)
            {
                title = BeeLocalization.Text("perimeter_sortie.status.active.title", "Escouade en sortie");
                body = BeeLocalization.Text("perimeter_sortie.status.active.body", "La réservation reste occupée jusqu’au retour ou au rappel.");
            }
            else if (state == HivePerimeterSortieScreenState.ClaimReady)
            {
                title = BeeLocalization.Text("perimeter_sortie.status.claim.title", "Retour confirmé");
                body = BeeLocalization.Text("perimeter_sortie.status.claim.body", "Le serveur autorise la réclamation exacte de ce signal.");
            }
            else if (state == HivePerimeterSortieScreenState.CycleComplete)
            {
                title = BeeLocalization.Text("perimeter_sortie.status.complete.title", "Cycle accompli");
                body = BeeLocalization.Text("perimeter_sortie.status.complete.body", "Aucun autre gain n’est disponible avant le prochain cycle serveur.");
            }
            else if (state == HivePerimeterSortieScreenState.ReturnDebrief)
            {
                title = BeeLocalization.Text("perimeter_sortie.debrief.title", "RETOUR CONFIRMÉ");
                body = BeeLocalization.Text("perimeter_sortie.debrief.full_credit", "La totalité de la récompense annoncée a été créditée par le serveur.");
            }
            else if (state == HivePerimeterSortieScreenState.Error)
            {
                title = BeeLocalization.Text("perimeter_sortie.status.error.title", "Périmètre indisponible");
                body = BeeLocalization.Text("perimeter_sortie.status.error.body", "Aucun état ancien n’est utilisé comme autorité. Réessaie plus tard.");
            }
            else
            {
                title = BeeLocalization.Text("perimeter_sortie.status.not_configured.title", "Session officielle requise");
                body = BeeLocalization.Text("perimeter_sortie.status.not_configured.body", "Aucun signal, statut ou gain n’est simulé tant que le transport mobile est fermé.");
            }
        }

        private static string PerimeterSortiePendingCopy(string pendingKind)
        {
            if (string.Equals(pendingKind, "launch", StringComparison.Ordinal))
                return BeeLocalization.Text(
                    "perimeter_sortie.status.pending.launch",
                    "Réponse réseau incertaine · le lancement du signal sera renvoyé avec la même clé.");
            if (string.Equals(pendingKind, "claim", StringComparison.Ordinal))
                return BeeLocalization.Text(
                    "perimeter_sortie.status.pending.claim",
                    "Réponse réseau incertaine · la réclamation sera renvoyée avec la même clé.");
            if (string.Equals(pendingKind, "recall", StringComparison.Ordinal))
                return BeeLocalization.Text(
                    "perimeter_sortie.status.pending.recall",
                    "Réponse réseau incertaine · le rappel de l’escouade sera renvoyé avec la même clé.");
            return BeeLocalization.Text(
                "perimeter_sortie.status.pending.unknown",
                "Réponse réseau incertaine · renvoi manuel avec la même clé.");
        }

        private static Color PerimeterSortieStateAccent(HivePerimeterSortieScreenState state)
        {
            if (state == HivePerimeterSortieScreenState.ClaimReady || state == HivePerimeterSortieScreenState.CycleComplete ||
                state == HivePerimeterSortieScreenState.ReturnDebrief)
                return new Color(0.38f, 0.82f, 0.50f, 1f);
            if (state == HivePerimeterSortieScreenState.Active)
                return new Color(0.38f, 0.72f, 0.94f, 1f);
            if (state == HivePerimeterSortieScreenState.Error)
                return new Color(0.90f, 0.38f, 0.28f, 1f);
            if (state == HivePerimeterSortieScreenState.NotConfigured)
                return new Color(0.62f, 0.64f, 0.68f, 1f);
            return new Color(0.96f, 0.68f, 0.18f, 1f);
        }

        private static string PerimeterSortieStateToken(HivePerimeterSortieScreenState state)
        {
            if (state == HivePerimeterSortieScreenState.Loading) return "loading";
            if (state == HivePerimeterSortieScreenState.NeedsReservation) return "needs_reservation";
            if (state == HivePerimeterSortieScreenState.ReadyToLaunch) return "ready_to_launch";
            if (state == HivePerimeterSortieScreenState.Active) return "active";
            if (state == HivePerimeterSortieScreenState.ClaimReady) return "claim_ready";
            if (state == HivePerimeterSortieScreenState.CycleComplete) return "cycle_complete";
            if (state == HivePerimeterSortieScreenState.ReturnDebrief) return "return_debrief";
            if (state == HivePerimeterSortieScreenState.Error) return "error";
            return "not_configured";
        }

        private static string PerimeterSortieActionToken(HivePerimeterSortieAction action)
        {
            if (action == HivePerimeterSortieAction.ReserveSquad) return "reserve_squad";
            if (action == HivePerimeterSortieAction.LaunchSignal) return "launch_signal";
            if (action == HivePerimeterSortieAction.Claim) return "claim";
            if (action == HivePerimeterSortieAction.Recall) return "recall";
            if (action == HivePerimeterSortieAction.DismissDebrief) return "dismiss_debrief";
            return "none";
        }

        private static bool RectContainsRect(Rect outer, Rect inner)
        {
            return outer.Contains(inner.min) && outer.Contains(new Vector2(inner.xMax - 0.01f, inner.yMax - 0.01f));
        }

        private static void DrawFormationRosterCard(Rect rect, HiveFormationRosterEntry entry, HiveSquadCompositionSnapshot composition, int index, bool compact)
        {
            bool selected = formationReadinessFamilyIndex == index && entry.HasTrustedLocalMapping;
            Color accent = entry.Doctrine.Accent;
            DrawPremiumPanel(
                rect,
                selected ? new Color(accent.r * 0.15f, accent.g * 0.15f, accent.b * 0.15f, 0.98f) : new Color(0.030f, 0.032f, 0.030f, 0.95f),
                selected ? new Color(accent.r, accent.g, accent.b, 0.90f) : entry.CanPrefillDraft ? new Color(accent.r, accent.g, accent.b, 0.56f) : new Color(0.42f, 0.40f, 0.36f, 0.56f));
            if (GUI.Button(rect, string.Empty, GUIStyle.none))
            {
                if (entry.HasTrustedLocalMapping)
                {
                    formationReadinessFamilyIndex = index;
                    localPreviewLoopMessage = BeeLocalization.Text("formation_readiness.family_selected", "Famille de formation sélectionnée");
                }
                else
                {
                    localPreviewLoopMessage = BeeLocalization.Text(
                        entry.State == HiveFormationRosterState.Empty ? "formation_readiness.family_empty" : "formation_readiness.family_not_mapped",
                        entry.State == HiveFormationRosterState.Empty ? "Aucune unité admissible" : "Catalogue officiel absent");
                    BeginReferenceFeedbackPulse("locked");
                }
            }

            float iconSize = compact ? 22f : 26f;
            DrawGameIcon(new Rect(rect.x + 6f, rect.y + 6f, iconSize, iconSize), entry.HasTrustedLocalMapping ? entry.Doctrine.IconId : "locked", Color.white);
            GUI.Label(new Rect(rect.x + 5f, rect.y + 31f, rect.width - 10f, 17f), BeeLocalization.Text(entry.Doctrine.NameKey, CombatDoctrineFallbackName(entry.Doctrine.Family)), new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter, fontSize = compact ? 9 : 11 });
            string status = entry.State == HiveFormationRosterState.Available
                ? string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("formation_readiness.composition.family_count", "{0}/{1} retenues"), composition.Count(entry.Doctrine.Token), entry.EligibleCount)
                : BeeLocalization.Text(entry.State == HiveFormationRosterState.Empty ? "formation_readiness.family_empty_short" : "formation_readiness.family_not_recorded", entry.State == HiveFormationRosterState.Empty ? "Aucune" : "Non reconnue");
            GUI.Label(new Rect(rect.x + 5f, rect.yMax - 18f, rect.width - 10f, 15f), status, new GUIStyle(badgeStyle) { alignment = TextAnchor.MiddleCenter, fontSize = compact ? 9 : 10, normal = { textColor = entry.CanPrefillDraft ? accent : new Color(0.68f, 0.66f, 0.60f, 1f) } });
        }

        private static void DrawFormationComposer(Rect rect, HiveFormationReadinessSnapshot roster, HiveSquadCompositionSnapshot composition, bool compact)
        {
            HiveFormationRosterEntry selected = roster.Families[Mathf.Clamp(formationReadinessFamilyIndex, 0, roster.Families.Count - 1)];
            Rect decrease = FormationReadinessDecreaseRectForProof(compact, Screen.width, Screen.height);
            Rect increase = FormationReadinessIncreaseRectForProof(compact, Screen.width, Screen.height);
            Rect recommend = FormationReadinessRecommendRectForProof(compact, Screen.width, Screen.height);
            Rect summary = new Rect(decrease.xMax + 6f, rect.y + 5f, increase.x - decrease.xMax - 12f, 44f);
            DrawPremiumPanel(rect, new Color(0.030f, 0.046f, 0.052f, 0.98f), new Color(0.34f, 0.72f, 0.82f, 0.74f));

            int selectedCount = composition.Count(selected.Doctrine.Token);
            HiveSquadReservationScreenModel officialReservation =
                OfficialSquadReservationModel();
            bool reservationLocked =
                officialReservation != null &&
                officialReservation.HasReservation;
            bool canDecrease = !reservationLocked && selectedCount > 0;
            bool canIncrease = !reservationLocked &&
                selected.HasTrustedLocalMapping &&
                selectedCount < selected.EligibleCount &&
                !composition.IsFull;
            if (DrawPreviewActionButton(decrease, "−", canDecrease)) AdjustFormationComposition(selected.Doctrine.Token, -1);
            if (DrawPreviewActionButton(increase, "+", canIncrease)) AdjustFormationComposition(selected.Doctrine.Token, 1);
            if (DrawPreviewActionButton(
                    recommend,
                    reservationLocked
                        ? BeeLocalization.Text(
                            "formation_readiness.reservation.locked",
                            "Réservée")
                        : BeeLocalization.Text(
                            "formation_readiness.composition.recommend",
                            "Suggérer"),
                    !reservationLocked &&
                    formationReadinessThreatIndex >= 0))
                RecommendFormationComposition();

            DrawPremiumPanel(summary, new Color(0.018f, 0.028f, 0.034f, 0.96f), new Color(0.42f, 0.72f, 0.80f, 0.48f));
            GUI.Label(
                new Rect(summary.x + 4f, summary.y + 3f, summary.width - 8f, 17f),
                BeeLocalization.Text(selected.Doctrine.NameKey, CombatDoctrineFallbackName(selected.Doctrine.Family)),
                new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter, fontSize = compact ? 8 : 10 });
            GUI.Label(
                new Rect(summary.x + 4f, summary.y + 21f, summary.width - 8f, 18f),
                string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("formation_readiness.composition.total", "{0}/{1} · escouade {2}/{3}"), selectedCount, selected.EligibleCount, composition.Total, composition.Capacity),
                new GUIStyle(badgeStyle) { alignment = TextAnchor.MiddleCenter, fontSize = compact ? 8 : 10 });
        }

        private static void DrawFormationThreatCard(Rect rect, HiveCombatDoctrineDefinition definition, int index, bool compact)
        {
            bool selected = formationReadinessThreatIndex == index;
            Color accent = definition.Accent;
            DrawPremiumPanel(
                rect,
                selected ? new Color(accent.r * 0.14f, accent.g * 0.14f, accent.b * 0.14f, 0.98f) : new Color(0.032f, 0.030f, 0.026f, 0.95f),
                selected ? new Color(accent.r, accent.g, accent.b, 0.90f) : new Color(0.58f, 0.48f, 0.24f, 0.58f));
            if (GUI.Button(rect, string.Empty, GUIStyle.none))
            {
                formationReadinessThreatIndex = index;
                localPreviewLoopMessage = BeeLocalization.Text("formation_readiness.threat_selected", "Menace observée sélectionnée");
            }
            DrawGameIcon(new Rect(rect.x + 6f, rect.y + 8f, 24f, 24f), definition.IconId, Color.white);
            GUI.Label(new Rect(rect.x + 32f, rect.y + 4f, rect.width - 36f, 22f), BeeLocalization.Text(definition.NameKey, CombatDoctrineFallbackName(definition.Family)), new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleLeft, wordWrap = true, fontSize = compact ? 9 : 10 });
            GUI.Label(
                new Rect(rect.x + 32f, rect.y + 28f, rect.width - 36f, 18f),
                BeeLocalization.Text("formation_readiness.role." + definition.Token + ".short", CombatDoctrineFallbackRole(definition.Family)),
                new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleLeft, fontSize = compact ? 8 : 9 });
        }

        private static void DrawFormationReadinessResult(Rect rect, HiveFormationReadinessSnapshot snapshot, HiveSquadCompositionSnapshot composition, bool compact)
        {
            HiveFormationRosterEntry selected = snapshot.Families[Mathf.Clamp(formationReadinessFamilyIndex, 0, snapshot.Families.Count - 1)];
            bool threatKnown = formationReadinessThreatIndex >= 0 && formationReadinessThreatIndex < HiveCombatDoctrineCatalog.All.Count;
            HiveCombatDoctrineDefinition threat = threatKnown ? HiveCombatDoctrineCatalog.All[formationReadinessThreatIndex] : null;
            HiveSquadDoctrineAssessment assessment = HiveSquadCompositionPlanner.Assess(composition, threatKnown ? threat.Token : string.Empty);
            Color accent = composition.IsEmpty ? new Color(0.58f, 0.56f, 0.50f, 1f) : selected.Doctrine.Accent;
            DrawPremiumPanel(rect, new Color(accent.r * 0.10f, accent.g * 0.10f, accent.b * 0.10f, 0.96f), new Color(accent.r, accent.g, accent.b, 0.72f));

            HiveDoctrineRecruitmentCatalog.TryResolveDoctrine(selected.Doctrine.Token, out HiveDoctrineRecruitmentDefinition recruitment);
            Rect recruit = FormationReadinessRecruitRectForProof(compact, Screen.width, Screen.height);
            float textWidth = Mathf.Max(100f, recruit.x - rect.x - 16f);

            string title;
            string body;
            if (composition.IsEmpty)
            {
                title = BeeLocalization.Text("formation_readiness.result.unavailable.title", "Escouade vide");
                body = BeeLocalization.Text("formation_readiness.result.unavailable.body", "Ajoute une famille disponible ou forme un nouveau lot à la Caserne.");
            }
            else if (!threatKnown)
            {
                title = string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("formation_readiness.result.ready.title", "Escouade {0}/{1} prête à étudier"), composition.Total, composition.Capacity);
                body = BeeLocalization.Text("formation_readiness.result.ready.body", "Choisis une menace ou ajuste le mélange. Aucun ordre n’est envoyé.");
            }
            else
            {
                string outcomeId = CombatDoctrineOutcomeId(assessment.Outcome);
                title = BeeLocalization.Text("formation_readiness.result." + outcomeId + ".title", "Lecture de doctrine");
                body = string.Format(
                    CultureInfo.CurrentCulture,
                    BeeLocalization.Text("formation_readiness.result." + outcomeId + ".body", "{0} répondent à la menace, {1} sont exposées et {2} restent neutres face à {3}. Lecture seulement."),
                    assessment.ResponsiveCount,
                    assessment.ExposedCount,
                    assessment.NeutralCount,
                    BeeLocalization.Text(threat.NameKey, CombatDoctrineFallbackName(threat.Family)));
            }

            GUI.Label(new Rect(rect.x + 10f, rect.y + 5f, textWidth, 19f), title, new GUIStyle(badgeStyle) { normal = { textColor = accent } });
            GUI.Label(new Rect(rect.x + 10f, rect.y + 26f, textWidth, rect.height - 30f), body, new GUIStyle(tinyLabelStyle) { wordWrap = true, fontSize = compact ? 9 : 10 });

            if (recruitment == null) return;
            if (OfficialDoctrineRecruitmentConfigured())
            {
                HiveDoctrineRecruitmentScreenModel official =
                    OfficialDoctrineRecruitmentModel();
                HiveDoctrineRecruitmentOfferModel offer =
                    official == null
                        ? null
                        : official.FindOffer(selected.Doctrine.Token);
                string officialLabel =
                    OfficialDoctrineRecruitmentActionLabel(
                        selected.Doctrine.Token);
                if (DrawPreviewActionButton(
                        recruit,
                        officialLabel,
                        OfficialDoctrineRecruitmentActionEnabled(
                            selected.Doctrine.Token)))
                    RunOfficialDoctrineRecruitmentAction(
                        selected.Doctrine.Token);
                string officialCost = offer == null
                    ? BeeLocalization.Text(
                        "formation_readiness.official.no_values",
                        "Aucune valeur serveur")
                    : string.Format(
                        CultureInfo.CurrentCulture,
                        BeeLocalization.Text(
                            "formation_readiness.recruitment.cost",
                            "{0} M · {1} P · {2}s"),
                        offer.HoneyCost,
                        offer.PollenCost,
                        Math.Max(
                            1,
                            (int)Math.Round(
                                offer.Duration.TotalSeconds)));
                GUI.Label(
                    new Rect(
                        recruit.x - 4f,
                        recruit.yMax + 2f,
                        recruit.width + 8f,
                        16f),
                    officialCost,
                    new GUIStyle(tinyLabelStyle)
                    {
                        alignment = TextAnchor.MiddleCenter,
                        fontSize = compact ? 8 : 9
                    });
                return;
            }
            bool sameTraining = IsTrainingRunning() && string.Equals(localPreviewTrainingTroopType, recruitment.TroopType, StringComparison.Ordinal);
            string reason = TrainingDisabledReason(recruitment.TroopType);
            string label = sameTraining
                ? string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("formation_readiness.recruitment.running", "En cours {0}%"), Mathf.RoundToInt(TrainingProgress01() * 100f))
                : string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("formation_readiness.recruitment.start", "Former +{0}"), recruitment.BatchSize);
            if (DrawPreviewActionButton(recruit, label, string.IsNullOrWhiteSpace(reason)))
            {
                selectedLocalTroopType = recruitment.TroopType;
                StartPreviewTraining(recruitment.TroopType);
            }
            GUI.Label(
                new Rect(recruit.x - 4f, recruit.yMax + 2f, recruit.width + 8f, 16f),
                string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("formation_readiness.recruitment.cost", "{0} M · {1} P · {2}s"), recruitment.HoneyCost, recruitment.PollenCost, Mathf.RoundToInt(recruitment.DurationSeconds)),
                new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter, fontSize = compact ? 8 : 9 });
        }

        private static void DrawResearchMenuPanel(Rect panel, bool compact)
        {
            if (OfficialResearchConfigured())
            {
                DrawOfficialResearchMenuPanel(panel, compact);
                return;
            }
            EnsureLocalPreviewQueueJournalLoaded();
            if (DrawMenuHeader(
                panel,
                "research",
                BeeLocalization.Text("research.menu.title", "Recherche"),
                BeeLocalization.Text("research.menu.subtitle", "Deux études complémentaires de la colonie"),
                true))
            {
                AudioManager.Instance?.PlayUIClick();
                AudioManager.Instance?.PlayMenuClose();
                CloseResearchOverlayForExternalHost();
                return;
            }

            float disclosureY = panel.y + 58f;
            GUI.Label(
                new Rect(panel.x + 18f, disclosureY, panel.width - 36f, 30f),
                BeeLocalization.Text("research.local_disclosure", "Aperçu local persistant · progression officielle côté serveur"),
                tinyLabelStyle);

            IReadOnlyList<LocalPreviewResearchDefinition> definitions = LocalPreviewResearchCatalog.All;
            float cardHeight = compact ? 92f : 112f;
            float cardGap = compact ? 6f : 10f;
            float cardY = disclosureY + 31f;
            Rect scrollViewport = new Rect(panel.x, cardY, panel.width, Mathf.Max(0f, panel.yMax - cardY - 8f));
            float contentHeight = definitions.Count * (cardHeight + cardGap);
            researchMenuScroll = GUI.BeginScrollView(scrollViewport, researchMenuScroll,
                new Rect(0f, 0f, scrollViewport.width - 16f, Mathf.Max(scrollViewport.height, contentHeight)), false, true);
            for (int i = 0; i < definitions.Count; i++)
            {
                LocalPreviewResearchDefinition definition = definitions[i];
                Rect card = new Rect(14f, i * (cardHeight + cardGap), scrollViewport.width - 28f, cardHeight);
                bool completed = LocalPreviewResearchCatalog.Contains(localPreviewQueueJournal.completedResearchIds, definition.ResearchId);
                bool running = IsResearchRunning() && string.Equals(localPreviewResearchId, definition.ResearchId, StringComparison.Ordinal);
                Color accent = completed ? new Color(0.42f, 0.82f, 0.48f, 0.88f) : running ? new Color(0.70f, 0.62f, 1f, 0.92f) : new Color(0.38f, 0.72f, 1f, 0.76f);
                DrawPremiumPanel(card, new Color(0.035f, 0.052f, 0.070f, 0.94f), accent);
                DrawGameIcon(new Rect(card.x + 10f, card.y + 12f, 36f, 36f), definition.IconId, Color.white);
                float actionWidth = compact ? 92f : 112f;
                float textWidth = card.width - actionWidth - 66f;
                GUI.Label(new Rect(card.x + 54f, card.y + 8f, textWidth, 20f), BeeLocalization.Text(definition.TitleKey, definition.ResearchId), smallStyle);
                GUI.Label(new Rect(card.x + 54f, card.y + 29f, textWidth, compact ? 34f : 38f), BeeLocalization.Text(definition.SummaryKey, definition.ResearchId), tinyLabelStyle);
                GUI.Label(new Rect(card.x + 12f, card.yMax - 24f, card.width - actionWidth - 24f, 18f), ResearchCostText(definition), tinyLabelStyle);
                if (!compact)
                    GUI.Label(new Rect(card.x + 54f, card.y + 67f, textWidth, 18f), BeeLocalization.Text(definition.ResultKey + "_short", BeeLocalization.Text(definition.ResultKey, definition.ResearchId)), tinyLabelStyle);

                string reason = ResearchDisabledReason(definition);
                string sourceResource = ResearchShortageResource(definition);
                Rect action = new Rect(card.xMax - actionWidth - 10f, card.y + 12f, actionWidth, 44f);
                string actionLabel = !string.IsNullOrWhiteSpace(sourceResource)
                    ? BeeLocalization.Text("research.source.button", "Source")
                    : completed
                    ? BeeLocalization.Text("research.button.completed", "Terminée")
                    : running ? BeeLocalization.Text("research.button.running", "En cours") : BeeLocalization.Text("research.button.start", "Lancer");
                if (!string.IsNullOrWhiteSpace(sourceResource))
                {
                    if (DrawPreviewActionButton(action, actionLabel, true, true)) NavigateToResearchResourceSource(sourceResource);
                }
                else if (DrawPreviewActionButton(action, actionLabel, string.IsNullOrWhiteSpace(reason))) StartPreviewResearch(definition.ResearchId);
                if (running) DrawProgressBar(new Rect(action.x, action.yMax + 8f, action.width, 7f), ResearchProgress01());
                else if (!string.IsNullOrWhiteSpace(reason)) GUI.Label(new Rect(action.x, action.yMax + 5f, action.width, 26f), reason, centeredTinyLabelStyle);
            }
            GUI.EndScrollView();
        }

        private static void DrawOfficialResearchMenuPanel(Rect panel, bool compact)
        {
            if (DrawMenuHeader(
                panel,
                "research",
                BeeLocalization.Text("research.menu.title", "Recherche"),
                BeeLocalization.Text("research.official.menu.subtitle", "Études persistantes de la colonie"),
                true))
            {
                AudioManager.Instance?.PlayUIClick();
                AudioManager.Instance?.PlayMenuClose();
                CloseResearchOverlayForExternalHost();
                return;
            }

            float disclosureY = panel.y + 58f;
            GUI.Label(
                new Rect(panel.x + 18f, disclosureY, panel.width - 36f, 30f),
                BeeLocalization.Text("research.official.disclosure", "Coût, durée et effets validés par le serveur · cache hors ligne en lecture seule"),
                tinyLabelStyle);

            HiveResearchScreenModel model = OfficialResearchModel();
            IReadOnlyList<LocalPreviewResearchDefinition> definitions = LocalPreviewResearchCatalog.All;
            float cardHeight = compact ? 100f : 118f;
            float cardGap = compact ? 6f : 10f;
            float cardY = disclosureY + 31f;
            Rect scrollViewport = new Rect(panel.x, cardY, panel.width, Mathf.Max(0f, panel.yMax - cardY - 8f));
            float contentHeight = definitions.Count * (cardHeight + cardGap);
            researchMenuScroll = GUI.BeginScrollView(scrollViewport, researchMenuScroll,
                new Rect(0f, 0f, scrollViewport.width - 16f, Mathf.Max(scrollViewport.height, contentHeight)), false, true);
            for (int i = 0; i < definitions.Count; i++)
            {
                LocalPreviewResearchDefinition definition = definitions[i];
                string researchId = definition.ResearchId;
                Rect card = new Rect(14f, i * (cardHeight + cardGap), scrollViewport.width - 28f, cardHeight);
                bool completed = model != null && model.IsCompleted(researchId);
                bool running = model != null && model.ActiveOperation != null &&
                    string.Equals(model.ActiveOperation.ResearchId, researchId, StringComparison.Ordinal);
                Color accent = completed
                    ? new Color(0.42f, 0.82f, 0.48f, 0.88f)
                    : running ? new Color(0.70f, 0.62f, 1f, 0.92f) : new Color(0.38f, 0.72f, 1f, 0.76f);
                DrawPremiumPanel(card, new Color(0.035f, 0.052f, 0.070f, 0.94f), accent);
                DrawGameIcon(new Rect(card.x + 10f, card.y + 12f, 36f, 36f), definition.IconId, Color.white);

                float actionWidth = compact ? 96f : 118f;
                float textWidth = card.width - actionWidth - 66f;
                GUI.Label(new Rect(card.x + 54f, card.y + 8f, textWidth, 20f),
                    BeeLocalization.Text(definition.TitleKey, researchId), smallStyle);
                GUI.Label(new Rect(card.x + 54f, card.y + 29f, textWidth, compact ? 31f : 38f),
                    BeeLocalization.Text(definition.SummaryKey, researchId), tinyLabelStyle);

                HiveResearchOfferModel offer = model == null ? null : model.OfferFor(researchId);
                string detail = offer == null
                    ? OfficialResearchEffectText(researchId)
                    : OfficialResearchCostText(offer) + " · " + OfficialResearchEffectText(researchId);
                GUI.Label(new Rect(card.x + 12f, card.yMax - 29f, card.width - actionWidth - 24f, 24f),
                    detail, new GUIStyle(tinyLabelStyle) { wordWrap = true, fontSize = compact ? 8 : 9 });

                Rect action = new Rect(card.xMax - actionWidth - 10f, card.y + 12f, actionWidth, 44f);
                // M038C-CL: publish the real geometry of THIS SPECIFIC research card's action
                // button, only for the FTUE's chosen research (tempered_combs_i) - other cards'
                // buttons share the same visual shape but are not the FTUE's target.
                // M040-CL: this Rect is in scroll-content-local coordinates now that the list is
                // clipped - convert to the real on-screen Rect before publishing, or the FTUE
                // arrow ends up pointing at the wrong place whenever the list is scrolled.
                if (string.Equals(researchId, BeeKingdom.Tutorial.FtueTutorialRegistry.FirstResearchId, StringComparison.Ordinal))
                {
                    Rect actionOnScreen = new Rect(
                        scrollViewport.x + action.x - researchMenuScroll.x,
                        scrollViewport.y + action.y - researchMenuScroll.y,
                        action.width, action.height);
                    try { BeeKingdom.Tutorial.TutorialTargetRegistry.Instance.RegisterScreenRect(BeeKingdom.Tutorial.FtueTutorialRegistry.TargetResearchStartButton, actionOnScreen); } catch {}
                }
                if (DrawPreviewActionButton(action, OfficialResearchActionLabel(researchId),
                    OfficialResearchActionEnabled(researchId)))
                    RunOfficialResearchAction(researchId);

                if (running && model != null)
                    DrawProgressBar(new Rect(action.x, action.yMax + 8f, action.width, 7f),
                        (float)model.Progress01(researchController.Elapsed));
                GUI.Label(
                    new Rect(action.x - 3f, action.yMax + (running ? 16f : 5f), action.width + 6f,
                        card.yMax - action.yMax - (running ? 18f : 7f)),
                    OfficialResearchStatusText(researchId),
                    new GUIStyle(centeredTinyLabelStyle) { wordWrap = true, fontSize = compact ? 8 : 9 });
            }
            GUI.EndScrollView();
        }

        // M040-CL: the real panel (DrawResearchMenuPanel/DrawOfficialResearchMenuPanel) now
        // scrolls its card list inside a fixed-height GUI.BeginScrollView viewport (added this
        // session to fix cards overflowing past the screen on portrait/mobile) - this proof
        // helper must mirror that same clipping, or it wrongly asserts unbounded, unscrolled
        // positions for catalogs too long to fit (10 research items today). Only cards that
        // are actually visible without scrolling (scroll position 0, matching a fresh open) are
        // returned, in real absolute screen coordinates - the same conversion already used by
        // RegisterScreenRect in the real draw methods.
        public static Rect[] OfficialResearchActionRectsForProof(
            bool portrait,
            float screenWidth,
            float screenHeight)
        {
            Rect panel = ResearchMenuPanelRectForProof(portrait, screenWidth, screenHeight);
            float disclosureY = panel.y + 58f;
            float cardHeight = portrait ? 100f : 118f;
            float cardGap = portrait ? 6f : 10f;
            float cardY = disclosureY + 31f;
            float actionWidth = portrait ? 96f : 118f;
            Rect scrollViewport = new Rect(panel.x, cardY, panel.width, Mathf.Max(0f, panel.yMax - cardY - 8f));

            var visible = new List<Rect>(LocalPreviewResearchCatalog.All.Count);
            for (int i = 0; i < LocalPreviewResearchCatalog.All.Count; i++)
            {
                float localCardY = i * (cardHeight + cardGap);
                if (localCardY + cardHeight > scrollViewport.height) break; // scrolled out of view at scroll=0
                float localActionX = (scrollViewport.width - 28f) - actionWidth - 10f + 14f;
                float localActionY = localCardY + 12f;
                visible.Add(new Rect(
                    scrollViewport.x + localActionX,
                    scrollViewport.y + localActionY,
                    actionWidth, 44f));
            }
            return visible.ToArray();
        }

        public static Rect ResearchMenuPanelRectForProof(bool portrait, float screenWidth, float screenHeight)
        {
            if (portrait) return new Rect(10f, screenHeight - 400f, screenWidth - 20f, 310f);
            bool tablet = screenWidth >= 1600f && screenHeight >= 900f;
            float width = tablet ? 430f : 360f;
            float topHud = tablet ? 132f : 112f;
            return new Rect(screenWidth - width - 24f, 118f, width,
                Mathf.Min(348f, screenHeight - (topHud + 108f)));
        }

        public static string[] OfficialResearchForProof(string researchId)
        {
            HiveResearchScreenModel model = OfficialResearchModel();
            HiveResearchOfferModel offer = model == null ? null : model.OfferFor(researchId);
            return new[]
            {
                "research_official_configured:" + BoolProof(OfficialResearchConfigured()),
                "research_official_state:" + (model == null ? "none" : model.State.ToString()),
                "research_official_id:" + (researchId ?? string.Empty),
                "research_official_completed:" + BoolProof(model != null && model.IsCompleted(researchId)),
                "research_official_offer:" + BoolProof(offer != null),
                "research_official_active:" + BoolProof(model != null && model.ActiveOperation != null),
                "research_official_action_enabled:" + BoolProof(OfficialResearchActionEnabled(researchId)),
                "research_official_shortage:" + (OfficialResearchShortageResource(researchId) ?? string.Empty),
                "research_official_local_debit:false",
                "research_official_local_completion:false",
                "research_official_local_effect:false",
                "research_official_cache_read_only:true"
            };
        }

        private static Rect HiveLedgerPanelRect(bool compact, float screenWidth, float screenHeight)
        {
            if (compact)
            {
                float height = Mathf.Min(470f, screenHeight - 222f);
                return new Rect(10f, screenHeight - 78f - height - 12f, screenWidth - 20f, height);
            }

            return new Rect(screenWidth - LandscapeRightPanelWidth() - 24f, 118f, LandscapeRightPanelWidth(), Mathf.Min(470f, screenHeight - 226f));
        }

        public static Rect HiveLedgerPanelRectForProof(bool portrait, float screenWidth, float screenHeight)
        {
            return HiveLedgerPanelRect(portrait, screenWidth, screenHeight);
        }

        public static Rect[] OfficialHiveStockActionRectsForProof(
            bool portrait,
            float screenWidth,
            float screenHeight)
        {
            Rect panel = HiveLedgerPanelRect(portrait, screenWidth, screenHeight);
            const float rowHeight = 76f;
            const float actionWidth = 84f;
            float rowsTop = panel.y + 108f;
            var result = new Rect[3];
            for (int index = 0; index < result.Length; index++)
            {
                Rect row = new Rect(
                    panel.x + 12f,
                    rowsTop + index * (rowHeight + 5f),
                    panel.width - 24f,
                    rowHeight);
                result[index] = new Rect(
                    row.xMax - actionWidth - 10f,
                    row.y + 16f,
                    actionWidth,
                    44f);
            }
            return result;
        }

        private static void DrawHiveLedgerPanel(Rect panel, bool compact)
        {
            if (OfficialHiveStockConfigured())
            {
                DrawOfficialHiveLedgerPanel(panel, compact);
                return;
            }

            EnsureLocalPreviewQueueJournalLoaded();
			if (DrawMenuHeader(
				panel,
				"inventory",
				BeeLocalization.Text("ledger.title", "Sac & stocks"),
				BeeLocalization.Text("ledger.subtitle", "Lire les réserves avant d’agir"),
