        private static string OfficialHiveStockDisclosure(HiveStockScreenModel model)
        {
            if (model == null || model.State == HiveStockScreenState.NotConfigured)
                return BeeLocalization.Text(
                    "stock.official.not_configured",
                    "Session officielle requise · aucune donnée locale affichée");
            if (model.State == HiveStockScreenState.Loading)
                return model.HasSnapshot
                    ? BeeLocalization.Text(
                        "stock.official.loading.previous",
                        "Synchronisation · dernier instantané validé conservé")
                    : BeeLocalization.Text(
                        "stock.official.loading",
                        "Synchronisation avec le serveur");
            if (model.State == HiveStockScreenState.OfflineReadOnly)
                return BeeLocalization.Text(
                    "stock.official.offline",
                    "Hors ligne · cache protégé en lecture seule");
            if (model.State == HiveStockScreenState.Error)
                return model.HasSnapshot
                    ? BeeLocalization.Text(
                        "stock.official.error.previous",
                        "Serveur indisponible · dernier instantané validé conservé")
                    : BeeLocalization.Text(
                        "stock.official.error",
                        "Instantané serveur indisponible · aucune valeur inventée");
            return BeeLocalization.Text(
                "stock.official.ready",
                "Serveur · lecture seule · collecte toujours manuelle");
        }

        private static string OfficialHiveStockPopulationText(HiveStockScreenModel model)
        {
            if (model == null || !model.HasSnapshot ||
                !model.Population.HasValue ||
                !model.PopulationCapacity.HasValue)
                return BeeLocalization.Text(
                    "stock.official.population.unavailable",
                    "Non disponible dans le contrat actuel");
            return FormatResource(model.Population.Value) + " / " +
                FormatResource(model.PopulationCapacity.Value);
        }

        private static int ActiveQueueReservationCount()
        {
            EnsureLocalPreviewQueueJournalLoaded();
            int count = 0;
            if (localPreviewQueueJournal.upgrade.Exists && !localPreviewQueueJournal.upgrade.completionClaimed) count++;
            if (localPreviewQueueJournal.training.Exists && !localPreviewQueueJournal.training.completionClaimed) count++;
            if (localPreviewQueueJournal.research.Exists && !localPreviewQueueJournal.research.completionClaimed) count++;
            return count;
        }

        private static float ActiveQueueReservation(string resourceIcon)
        {
            EnsureLocalPreviewQueueJournalLoaded();
            float total = 0f;
            LocalPreviewQueueOperation[] operations = { localPreviewQueueJournal.upgrade, localPreviewQueueJournal.training, localPreviewQueueJournal.research };
            for (int i = 0; i < operations.Length; i++)
            {
                LocalPreviewQueueOperation operation = operations[i];
                if (operation == null || !operation.Exists || operation.completionClaimed) continue;
                if (string.Equals(resourceIcon, "honey", StringComparison.Ordinal)) total += operation.honeyCost;
                else if (string.Equals(resourceIcon, "wax", StringComparison.Ordinal)) total += operation.waxCost;
                else if (string.Equals(resourceIcon, "pollen", StringComparison.Ordinal)) total += operation.pollenCost;
            }
            return total;
        }

        private static void OpenHiveLedgerResource(string hotspotId)
        {
            ReferenceHiveHotspot hotspot = FindReferenceHotspot(hotspotId);
            if (string.IsNullOrWhiteSpace(hotspot.HotspotId)) return;
            localPreviewLedgerLastNavigationId = hotspotId;
            if (!OfficialHiveStockConfigured())
                RecordDailyRoundTask(DailyRoundLedgerTask);
            activeMainMenuId = string.Empty;
            activeHiveMenu = HiveMenuMode.Hive;
            SelectReferenceHotspot(hotspot);
            localPreviewLoopMessage = string.Format(
                CultureInfo.CurrentCulture,
                BeeLocalization.Text("ledger.navigation", "{0} ouverte · collecte toujours manuelle"),
                LocalizedHotspotLabel(hotspot));
            localPreviewLastActionStatus = BeeLocalization.Text("ledger.navigation_status", "Bâtiment ouvert");
        }

        public static void OpenHiveLedgerResourceForProof(string hotspotId)
        {
            OpenHiveLedgerResource(hotspotId);
        }

        public static string[] HiveLedgerForProof()
        {
            if (OfficialHiveStockConfigured())
                return OfficialHiveStockForProof();

            EnsureLocalPreviewQueueJournalLoaded();
            ManualProductionForecast honeyForecast = ManualProductionForecastFor("honey_storage");
            ManualProductionForecast waxForecast = ManualProductionForecastFor("wax_workshop");
            ManualProductionForecast pollenForecast = ManualProductionForecastFor("warehouse_cells");
            ManualProductionForecast.TryEarliestSecondsUntilFull(
                new[] { honeyForecast, waxForecast, pollenForecast },
                out double earliestSeconds);
            return new[]
            {
                "ledger_authority:local_preview_non_official",
                "ledger_official_authority:server",
                "ledger_forecast_display_authority:device_derived",
                "ledger_forecast_official_source:server_snapshot_required",
                "ledger_direct_collection:false",
                "ledger_navigation_targets:honey_storage,wax_workshop,warehouse_cells",
                "ledger_min_touch_size:44",
                "ledger_honey_available:" + Mathf.RoundToInt(localPreviewHoney).ToString(CultureInfo.InvariantCulture),
                "ledger_honey_pending:" + Mathf.RoundToInt(localPreviewPendingHoney).ToString(CultureInfo.InvariantCulture),
                "ledger_honey_engaged:" + Mathf.RoundToInt(ActiveQueueReservation("honey")).ToString(CultureInfo.InvariantCulture),
                "ledger_wax_available:" + Mathf.RoundToInt(localPreviewWax).ToString(CultureInfo.InvariantCulture),
                "ledger_wax_pending:" + Mathf.RoundToInt(localPreviewPendingWax).ToString(CultureInfo.InvariantCulture),
                "ledger_wax_engaged:" + Mathf.RoundToInt(ActiveQueueReservation("wax")).ToString(CultureInfo.InvariantCulture),
                "ledger_pollen_available:" + Mathf.RoundToInt(localPreviewPollen).ToString(CultureInfo.InvariantCulture),
                "ledger_pollen_pending:" + Mathf.RoundToInt(localPreviewPendingPollen).ToString(CultureInfo.InvariantCulture),
                "ledger_pollen_engaged:" + Mathf.RoundToInt(ActiveQueueReservation("pollen")).ToString(CultureInfo.InvariantCulture),
                "ledger_honey_capacity:" + Mathf.RoundToInt((float)honeyForecast.Capacity).ToString(CultureInfo.InvariantCulture),
                "ledger_honey_rate_per_hour:" + Mathf.RoundToInt((float)honeyForecast.RatePerHour).ToString(CultureInfo.InvariantCulture),
                "ledger_honey_forecast_state:" + honeyForecast.State.ToString().ToLowerInvariant(),
                "ledger_honey_seconds_until_full:" + Math.Round(honeyForecast.SecondsUntilFull, 3).ToString("0.###", CultureInfo.InvariantCulture),
                "ledger_wax_capacity:" + Mathf.RoundToInt((float)waxForecast.Capacity).ToString(CultureInfo.InvariantCulture),
                "ledger_wax_rate_per_hour:" + Mathf.RoundToInt((float)waxForecast.RatePerHour).ToString(CultureInfo.InvariantCulture),
                "ledger_wax_forecast_state:" + waxForecast.State.ToString().ToLowerInvariant(),
                "ledger_wax_seconds_until_full:" + Math.Round(waxForecast.SecondsUntilFull, 3).ToString("0.###", CultureInfo.InvariantCulture),
                "ledger_pollen_capacity:" + Mathf.RoundToInt((float)pollenForecast.Capacity).ToString(CultureInfo.InvariantCulture),
                "ledger_pollen_rate_per_hour:" + Mathf.RoundToInt((float)pollenForecast.RatePerHour).ToString(CultureInfo.InvariantCulture),
                "ledger_pollen_forecast_state:" + pollenForecast.State.ToString().ToLowerInvariant(),
                "ledger_pollen_seconds_until_full:" + Math.Round(pollenForecast.SecondsUntilFull, 3).ToString("0.###", CultureInfo.InvariantCulture),
                "ledger_earliest_seconds_until_full:" + Math.Round(earliestSeconds, 3).ToString("0.###", CultureInfo.InvariantCulture),
                "ledger_active_commitments:" + ActiveQueueReservationCount().ToString(CultureInfo.InvariantCulture),
                "ledger_capacity_used:" + Mathf.RoundToInt(localPreviewCapacityUsed).ToString(CultureInfo.InvariantCulture),
                "ledger_capacity_max:" + Mathf.RoundToInt(localPreviewCapacityMax).ToString(CultureInfo.InvariantCulture),
                "ledger_last_navigation:" + (string.IsNullOrWhiteSpace(localPreviewLedgerLastNavigationId) ? "none" : localPreviewLedgerLastNavigationId)
            };
        }

        private static string CurrentUtcDayKey()
        {
            return DateTime.UtcNow.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
        }

        private static void EnsureLocalPreviewDailyRoundLoaded()
        {
            if (localPreviewDailyRoundLoaded) return;
            localPreviewDailyRoundLoaded = true;
            localPreviewDailyRound = LocalPreviewDailyRoundCodec.Read(localPreviewDailyRoundStore);
            string today = CurrentUtcDayKey();
            if (!string.Equals(localPreviewDailyRound.utcDay, today, StringComparison.Ordinal))
            {
                localPreviewDailyRound = new LocalPreviewDailyRound { utcDay = today };
                localPreviewDailyRoundRewardAppliedInSession = false;
                SaveLocalPreviewDailyRound();
                return;
            }

            if (localPreviewDailyRound.rewardClaimed && !localPreviewDailyRoundRewardAppliedInSession)
            {
                localPreviewHoney += localPreviewDailyRound.rewardHoney;
                localPreviewPollen += localPreviewDailyRound.rewardPollen;
                localPreviewCapacityUsed = Mathf.Min(localPreviewCapacityMax, localPreviewCapacityUsed + localPreviewDailyRound.rewardHoney + localPreviewDailyRound.rewardPollen);
                localPreviewDailyRoundRewardAppliedInSession = true;
            }
        }

        private static void SaveLocalPreviewDailyRound()
        {
            LocalPreviewDailyRoundCodec.Write(localPreviewDailyRoundStore, localPreviewDailyRound);
        }

        private static void RecordDailyRoundTask(int taskBit)
        {
            EnsureLocalPreviewDailyRoundLoaded();
            int normalized = taskBit & DailyRoundAllTasks;
            if (normalized == 0 || (localPreviewDailyRound.tasksMask & normalized) == normalized) return;
            localPreviewDailyRound.tasksMask |= normalized;
            SaveLocalPreviewDailyRound();
        }

        private static int DailyRoundCompletedTaskCount()
        {
            EnsureLocalPreviewDailyRoundLoaded();
            int count = 0;
            if ((localPreviewDailyRound.tasksMask & DailyRoundCollectTask) != 0) count++;
            if ((localPreviewDailyRound.tasksMask & DailyRoundOperationTask) != 0) count++;
            if ((localPreviewDailyRound.tasksMask & DailyRoundLedgerTask) != 0) count++;
            return count;
        }

        private static bool DailyRoundTaskCompleted(int taskBit)
        {
            EnsureLocalPreviewDailyRoundLoaded();
            return (localPreviewDailyRound.tasksMask & taskBit) == taskBit;
        }

        private static void NavigateToDailyRoundTask(int taskBit)
        {
            if (taskBit == DailyRoundCollectTask)
            {
                string targetId = PendingManualProduction("honey_storage") > 0f
                    ? "honey_storage"
                    : PendingManualProduction("wax_workshop") > 0f ? "wax_workshop"
                    : PendingManualProduction("warehouse_cells") > 0f ? "warehouse_cells" : "honey_storage";
                ReferenceHiveHotspot target = FindReferenceHotspot(targetId);
                activeMainMenuId = string.Empty;
                activeHiveMenu = HiveMenuMode.Hive;
                detailPanelClosed = false;
                if (!string.IsNullOrWhiteSpace(target.HotspotId)) SelectReferenceHotspot(target);
                localPreviewDailyRoundLastRoute = targetId;
                localPreviewLastActionStatus = BeeLocalization.Text("daily_round.route.collect", "Bâtiment de collecte ouvert");
            }
            else if (taskBit == DailyRoundOperationTask)
            {
                activeMainMenuId = string.Empty;
                activeHiveMenu = HiveMenuMode.Research;
                detailPanelClosed = true;
                localPreviewDailyRoundLastRoute = "research";
                localPreviewLastActionStatus = BeeLocalization.Text("daily_round.route.operation", "Recherche ouverte");
            }
            else if (taskBit == DailyRoundLedgerTask)
            {
                activeMainMenuId = "Bag";
                activeHiveMenu = HiveMenuMode.Hive;
                detailPanelClosed = true;
                localPreviewDailyRoundLastRoute = "ledger";
                localPreviewLastActionStatus = BeeLocalization.Text("daily_round.route.ledger", "Sac & stocks ouvert");
            }
            else
            {
                return;
            }

            BeginReferenceFeedbackPulse("preview");
        }

        private static string DailyRoundClaimDisabledReason()
        {
            EnsureLocalPreviewDailyRoundLoaded();
            if (localPreviewDailyRound.rewardClaimed) return BeeLocalization.Text("daily_round.reason.claimed", "Récompense déjà réclamée");
            if ((localPreviewDailyRound.tasksMask & DailyRoundAllTasks) != DailyRoundAllTasks) return BeeLocalization.Text("daily_round.reason.tasks", "Termine les trois gestes de la ronde");
            float rewardTotal = localPreviewDailyRound.rewardHoney + localPreviewDailyRound.rewardPollen;
            if (localPreviewCapacityMax - localPreviewCapacityUsed < rewardTotal) return BeeLocalization.Text("daily_round.reason.capacity", "Capacité insuffisante");
            return string.Empty;
        }

        private static bool ClaimLocalPreviewDailyRound()
        {
            string reason = DailyRoundClaimDisabledReason();
            if (!string.IsNullOrWhiteSpace(reason))
            {
                localPreviewDisabledReason = reason;
                localPreviewLoopMessage = reason;
                BeginReferenceFeedbackPulse("locked");
                return false;
            }

            localPreviewDailyRound.rewardClaimed = true;
            localPreviewDailyRound.claimOperationId = Guid.NewGuid().ToString("N");
            SaveLocalPreviewDailyRound();
            localPreviewHoney += localPreviewDailyRound.rewardHoney;
            localPreviewPollen += localPreviewDailyRound.rewardPollen;
            localPreviewCapacityUsed += localPreviewDailyRound.rewardHoney + localPreviewDailyRound.rewardPollen;
            localPreviewDailyRoundRewardAppliedInSession = true;
            localPreviewDailyRoundClaimCommitCount++;
            localPreviewLastActionStatus = BeeLocalization.Text("daily_round.feedback.title", "Ronde terminée");
            localPreviewLoopMessage = BeeLocalization.Text("daily_round.feedback.detail", "+120 miel et +60 pollen crédités dans l’aperçu local.");
            SetPlayerFacingActionState("completion", BeeLocalization.Text("daily_round.feedback.title", "Ronde terminée"), localPreviewLoopMessage);
            BeginReferenceFeedbackPulse("preview");
            return true;
        }

        public static void UseLocalPreviewDailyRoundStoreForProof(ILocalPreviewDailyRoundStore store)
        {
            localPreviewDailyRoundStore = store ?? new PlayerPrefsLocalPreviewDailyRoundStore();
            localPreviewDailyRound = new LocalPreviewDailyRound();
            localPreviewDailyRoundLoaded = false;
            localPreviewDailyRoundRewardAppliedInSession = false;
            localPreviewDailyRoundClaimCommitCount = 0;
            localPreviewDailyRoundLastRoute = "none";
        }

        public static void RecordDailyRoundTaskForProof(string task)
        {
            if (string.Equals(task, "collect", StringComparison.Ordinal)) RecordDailyRoundTask(DailyRoundCollectTask);
            else if (string.Equals(task, "operation", StringComparison.Ordinal)) RecordDailyRoundTask(DailyRoundOperationTask);
            else if (string.Equals(task, "ledger", StringComparison.Ordinal)) RecordDailyRoundTask(DailyRoundLedgerTask);
        }

        public static void NavigateToDailyRoundTaskForProof(string task)
        {
            if (string.Equals(task, "collect", StringComparison.Ordinal)) NavigateToDailyRoundTask(DailyRoundCollectTask);
            else if (string.Equals(task, "operation", StringComparison.Ordinal)) NavigateToDailyRoundTask(DailyRoundOperationTask);
            else if (string.Equals(task, "ledger", StringComparison.Ordinal)) NavigateToDailyRoundTask(DailyRoundLedgerTask);
        }

        public static bool ClaimLocalPreviewDailyRoundForProof()
        {
            return ClaimLocalPreviewDailyRound();
        }

        public static void SimulateLocalPreviewDailyRoundRestartForProof()
        {
            localPreviewDailyRound = new LocalPreviewDailyRound();
            localPreviewDailyRoundLoaded = false;
            EnsureLocalPreviewDailyRoundLoaded();
        }

        public static string[] LocalPreviewDailyRoundForProof()
        {
            EnsureLocalPreviewDailyRoundLoaded();
            return new[]
            {
                "daily_round_version:" + localPreviewDailyRound.version.ToString(CultureInfo.InvariantCulture),
                "daily_round_utc_day:" + localPreviewDailyRound.utcDay,
                "daily_round_tasks_mask:" + localPreviewDailyRound.tasksMask.ToString(CultureInfo.InvariantCulture),
                "daily_round_completed_tasks:" + DailyRoundCompletedTaskCount().ToString(CultureInfo.InvariantCulture),
                "daily_round_collect_complete:" + BoolProof(DailyRoundTaskCompleted(DailyRoundCollectTask)),
                "daily_round_operation_complete:" + BoolProof(DailyRoundTaskCompleted(DailyRoundOperationTask)),
                "daily_round_ledger_complete:" + BoolProof(DailyRoundTaskCompleted(DailyRoundLedgerTask)),
                "daily_round_reward_ready:" + BoolProof((localPreviewDailyRound.tasksMask & DailyRoundAllTasks) == DailyRoundAllTasks && !localPreviewDailyRound.rewardClaimed),
                "daily_round_reward_claimed:" + BoolProof(localPreviewDailyRound.rewardClaimed),
                "daily_round_claim_operation_id:" + (string.IsNullOrWhiteSpace(localPreviewDailyRound.claimOperationId) ? "none" : localPreviewDailyRound.claimOperationId),
                "daily_round_claim_commit_count:" + localPreviewDailyRoundClaimCommitCount.ToString(CultureInfo.InvariantCulture),
                "daily_round_last_route:" + localPreviewDailyRoundLastRoute,
                "daily_round_min_touch_size:44",
                "daily_round_reward_honey:" + Mathf.RoundToInt(localPreviewDailyRound.rewardHoney).ToString(CultureInfo.InvariantCulture),
                "daily_round_reward_pollen:" + Mathf.RoundToInt(localPreviewDailyRound.rewardPollen).ToString(CultureInfo.InvariantCulture),
                "daily_round_authority:local_preview_non_official",
                "daily_round_official_authority:server_utc"
            };
        }

