        private sealed class AllianceActivityEntry
        {
            public string Type;
            public string Player;
            public string Message;
            public float CreatedAt;
        }

        private static readonly string[] AllianceActivityPlayerNames = { "Jeff", "Marie", "Alex", "Sophie", "Lucas", "Nora", "Idriss", "Chloé", "Maxime", "Yasmine", "Karim", "Léa" };

        private static readonly string[] AllianceActivityBuildings = { "Caserne", "Ruche d'élite", "Entrepôt", "Atelier de cire", "Chambre royale", "Tour de garde", "Ferme de pollen", "Laboratoire", "Réserve de miel" };

        private static readonly string[] AllianceActivityResearches = { "Récolte II", "Production III", "Défense I", "Navigation II", "Réserves II", "Élevage II", "Tactique I", "Recyclage II", "Combat III" };

        private static void TickAllianceActivityFeed()
        {
            if (!allianceActivitySeeded)
            {
                allianceActivitySeeded = true;
                SeedAllianceActivityFeed();
                return;
            }
            float now = NowForUi();
            if (now - allianceActivityLastTickAt < 6.5f) return;
            allianceActivityLastTickAt = now;
            PushAllianceActivityEntry(CreateSimulatedAllianceActivityEntry());
        }

        private static void SeedAllianceActivityFeed()
        {
            PushAllianceActivityEntry(new AllianceActivityEntry { Type = "join", Player = "Sophie", Message = "Sophie a rejoint l'Alliance.", CreatedAt = NowForUi() - 4f });
            PushAllianceActivityEntry(new AllianceActivityEntry { Type = "login", Player = "Jeff", Message = "Jeff s'est connecté.", CreatedAt = NowForUi() - 22f });
            PushAllianceActivityEntry(new AllianceActivityEntry { Type = "research_end", Player = "Alex", Message = "Alex a terminé la Recherche « Récolte II ».", CreatedAt = NowForUi() - 41f });
            PushAllianceActivityEntry(new AllianceActivityEntry { Type = "build_start", Player = "Marie", Message = "Marie améliore la Caserne niveau 4.", CreatedAt = NowForUi() - 67f });
            PushAllianceActivityEntry(new AllianceActivityEntry { Type = "login", Player = "Nora", Message = "Nora s'est connectée.", CreatedAt = NowForUi() - 88f });
            PushAllianceActivityEntry(new AllianceActivityEntry { Type = "build_end", Player = "Lucas", Message = "Lucas a terminé l'Atelier de cire niveau 3.", CreatedAt = NowForUi() - 112f });
            PushAllianceActivityEntry(new AllianceActivityEntry { Type = "research_start", Player = "Idriss", Message = "Idriss lance la Recherche « Défense I ».", CreatedAt = NowForUi() - 141f });
            PushAllianceActivityEntry(new AllianceActivityEntry { Type = "logout", Player = "Chloé", Message = "Chloé s'est déconnectée.", CreatedAt = NowForUi() - 173f });
            PushAllianceActivityEntry(new AllianceActivityEntry { Type = "login", Player = "Maxime", Message = "Maxime s'est connecté.", CreatedAt = NowForUi() - 201f });
            PushAllianceActivityEntry(new AllianceActivityEntry { Type = "leave", Player = "Yasmine", Message = "Yasmine a quitté l'Alliance.", CreatedAt = NowForUi() - 236f });
            allianceActivityLastTickAt = NowForUi();
        }

        private static AllianceActivityEntry CreateSimulatedAllianceActivityEntry()
        {
            string[] types = { "login", "logout", "build_start", "build_end", "research_start", "research_end", "join", "leave" };
            string type = types[UnityEngine.Random.Range(0, types.Length)];
            string player = AllianceActivityPlayerNames[UnityEngine.Random.Range(0, AllianceActivityPlayerNames.Length)];
            string message = string.Empty;
            switch (type)
            {
                case "login": message = player + " s'est connecté" + (player.EndsWith("e", StringComparison.Ordinal) ? "e" : "") + "."; break;
                case "logout": message = player + " s'est déconnecté" + (player.EndsWith("e", StringComparison.Ordinal) ? "e" : "") + "."; break;
                case "build_start":
                {
                    string building = AllianceActivityBuildings[UnityEngine.Random.Range(0, AllianceActivityBuildings.Length)];
                    int level = UnityEngine.Random.Range(2, 7);
                    message = player + " améliore " + building + " niveau " + level.ToString(CultureInfo.InvariantCulture) + ".";
                    break;
                }
                case "build_end":
                {
                    string building = AllianceActivityBuildings[UnityEngine.Random.Range(0, AllianceActivityBuildings.Length)];
                    int level = UnityEngine.Random.Range(2, 7);
                    message = player + " a terminé " + building + " niveau " + level.ToString(CultureInfo.InvariantCulture) + ".";
                    break;
                }
                case "research_start":
                {
                    string research = AllianceActivityResearches[UnityEngine.Random.Range(0, AllianceActivityResearches.Length)];
                    message = player + " lance la Recherche « " + research + " ».";
                    break;
                }
                case "research_end":
                {
                    string research = AllianceActivityResearches[UnityEngine.Random.Range(0, AllianceActivityResearches.Length)];
                    message = player + " a terminé la Recherche « " + research + " ».";
                    break;
                }
                case "join": message = player + " a rejoint l'Alliance."; break;
                case "leave": message = player + " a quitté l'Alliance."; break;
            }
            return new AllianceActivityEntry { Type = type, Player = player, Message = message, CreatedAt = NowForUi() };
        }

        private static void PushAllianceActivityEntry(AllianceActivityEntry entry)
        {
            allianceActivityFeed.Insert(0, entry);
            while (allianceActivityFeed.Count > 50)
                allianceActivityFeed.RemoveAt(allianceActivityFeed.Count - 1);
        }

        private static bool AllianceActivityMatchesFilter(AllianceActivityEntry entry)
        {
            switch (allianceActivityFilter)
            {
                case "activity": return entry.Type == "login" || entry.Type == "logout";
                case "construction": return entry.Type == "build_start" || entry.Type == "build_end";
                case "research": return entry.Type == "research_start" || entry.Type == "research_end";
                case "members": return entry.Type == "join" || entry.Type == "leave";
                default: return true;
            }
        }

