            string[] labels = { "Niveau", "Puissance", "Entré(e) le", "Dernière connexion", "Devise" };
            string[] values =
            {
                member.Level.ToString(),
                AllianceFullNumberLabel(member.Power),
                member.JoinedOn,
                member.LastSeen,
                "« " + member.Motto + " »"
            };
            float rowH = rect.height / (float)labels.Length;
            for (int i = 0; i < labels.Length; i++)
            {
                DrawAllianceProfileInfoRow(new Rect(rect.x, rect.y + i * rowH, rect.width, rowH), labels[i], values[i], compact);
            }
        }

