        private static void OpenFriendsScreen()
        {
            friendsScreenOpen = true;
            friendsScreenOpenedAt = NowForUi();
            friendsToast = string.Empty;
            friendsToastAt = -10f;
            AudioManager.Instance?.PlayMenuOpen();
        }

        private static void ShowFriendsToast(string message)
        {
            friendsToast = message;
            friendsToastAt = NowForUi();
        }

        private static bool HasSentOrReceivedFriendRequest(string name)
        {
            for (int i = 0; i < socialReceivedRequests.Count; i++)
            {
                if (string.Equals(socialReceivedRequests[i].Name, name, StringComparison.Ordinal)) return true;
            }
            for (int i = 0; i < socialSentRequests.Count; i++)
            {
                if (string.Equals(socialSentRequests[i].Name, name, StringComparison.Ordinal)) return true;
            }
            return false;
        }

        private static void SendFriendRequest(string name, string allianceTag, string alliance)
        {
            if (HasSentOrReceivedFriendRequest(name))
            {
                ShowFriendsToast("Demande déjà en cours pour " + name + ".");
                return;
            }
            int level = (name.Length * 7) % 12 + 1;
            socialSentRequests.Add(Friend(name, level, string.IsNullOrWhiteSpace(allianceTag) ? "—" : allianceTag, string.IsNullOrWhiteSpace(alliance) ? "Sans alliance" : alliance, "offline", "à l'instant"));
            ShowFriendsToast("Demande envoyée à " + name + ".");
        }

        private static void DrawFriendsScreen(bool compact)
        {
            if (!friendsScreenOpen) return;
            float anim = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((NowForUi() - friendsScreenOpenedAt) / 0.18f));
            float zoom = Mathf.Lerp(0.97f, 1f, anim);
            Rect full = new Rect(0f, 0f, Screen.width, Screen.height);
            GUI.matrix = Matrix4x4.TRS(full.center, Quaternion.identity, new Vector3(zoom, zoom, 1f)) * Matrix4x4.Translate(-full.center);
            GUI.color = new Color(0.006f, 0.005f, 0.004f, 0.99f * anim);
            GUI.DrawTexture(full, Texture2D.blackTexture, ScaleMode.StretchToFill, false);
            GUI.color = Color.white;
            float bannerHeight = compact
                ? Mathf.Min(150f, Screen.height * 0.20f)
                : Mathf.Clamp(Screen.height * 0.20f, 150f, 190f);
            DrawFriendsBanner(bannerHeight, compact);
            DrawFriendsTopBar(bannerHeight);
            float quickBarY = bannerHeight + 6f;
            float quickBarHeight = compact ? 60f : 64f;
            DrawFriendsQuickActionsBar(new Rect(10f, quickBarY, Screen.width - 20f, quickBarHeight), compact);
            float tabsY = quickBarY + quickBarHeight + 6f;
            DrawFriendsTabs(compact, tabsY);
            float contentTop = tabsY + 44f;
            Rect content = new Rect(0f, contentTop, Screen.width, Mathf.Max(1f, Screen.height - contentTop));
            DrawFriendsTabContent(content, compact);
            DrawFriendsToast();
            GUI.matrix = Matrix4x4.identity;
        }

        private static void DrawFriendsBanner(float height, bool compact)
        {
            Rect banner = new Rect(0f, 0f, Screen.width, height);
            Texture2D bannerTexture = Resources.Load<Texture2D>("PremiumBeeReference/BuildingBanners/friends_hall");
            if (bannerTexture == null)
                bannerTexture = Resources.Load<Texture2D>("PremiumBeeReference/BuildingBanners/alliance_future_hall");
            if (bannerTexture != null)
            {
                GUI.color = Color.white;
                GUI.DrawTexture(banner, bannerTexture, ScaleMode.ScaleAndCrop, true);
            }
            else
            {
                DrawPremiumPanel(banner, new Color(0.14f, 0.085f, 0.025f, 0.98f), new Color(1f, 0.68f, 0.16f, 0.90f));
            }
            GUI.color = new Color(0.01f, 0.008f, 0.004f, 0.48f);
            GUI.DrawTexture(banner, Texture2D.blackTexture, ScaleMode.StretchToFill, true);
            GUI.color = Color.white;
            GUI.Label(new Rect(28f, height - (compact ? 42f : 48f), Screen.width * 0.62f, 26f), "RÉSEAU SOCIAL", new GUIStyle(titleStyle) { fontSize = compact ? 20 : 28, fontStyle = FontStyle.Bold });
            GUI.Label(new Rect(30f, height - (compact ? 20f : 23f), Screen.width * 0.68f, 16f), "Les relations qui font grandir votre royaume", new GUIStyle(smallStyle) { fontSize = compact ? 9 : 12 });
        }

        private static void DrawFriendsTopBar(float bannerHeight)
        {
            Color previous = GUI.color;
            GUI.color = new Color(1f, 0.60f, 0.14f, 0.95f);
            GUI.DrawTexture(new Rect(0f, bannerHeight - 1f, Screen.width, 1f), Texture2D.whiteTexture, ScaleMode.StretchToFill, false);
            GUI.color = previous;
			if (DrawPremiumBackButton(new Rect(4f, 2f, 48f, 46f)))
            {
                AudioManager.Instance?.PlayUIClick();
                AudioManager.Instance?.PlayMenuClose();
                friendsScreenOpen = false;
                return;
            }
            GUI.Label(new Rect(54f, 12f, Screen.width - 170f, 24f), "MES AMIS", new GUIStyle(badgeStyle) { fontSize = 11 });
            Rect count = new Rect(Screen.width - 108f, 10f, 96f, 28f);
            DrawPremiumPanel(count, new Color(0.05f, 0.04f, 0.025f, 0.96f), new Color(0.86f, 0.58f, 0.16f, 0.85f));
            GUI.Label(count, socialFriends.Count.ToString(CultureInfo.InvariantCulture) + " AMIS", new GUIStyle(centeredTinyLabelStyle) { fontSize = 9, normal = { textColor = new Color(1f, 0.88f, 0.60f, 1f) } });
        }

        private static void DrawFriendsQuickActionsBar(Rect rect, bool compact)
        {
            string[] ids = { "add", "search", "requests", "messages", "gifts" };
            string[] labels = { "Ajouter", "Rechercher", "Invitations", "Messages", "Cadeaux" };
            float gap = 6f;
            float itemWidth = compact ? 112f : Mathf.Max(112f, (rect.width - gap * 4f) / ids.Length);
            float contentWidth = ids.Length * itemWidth + (ids.Length - 1) * gap + 8f;
            DrawPremiumPanel(rect, new Color(0.025f, 0.022f, 0.017f, 0.98f), new Color(0.82f, 0.54f, 0.14f, 0.84f));
            friendsQuickActionsScroll = GUI.BeginScrollView(rect, friendsQuickActionsScroll, new Rect(0f, 0f, contentWidth, rect.height - 2f), false, false);
            string[] icons = { "members", "search", "mail", "messages", "gift" };
            for (int i = 0; i < ids.Length; i++)
            {
                Rect button = new Rect(4f + i * (itemWidth + gap), 6f, itemWidth, rect.height - 12f);
                DrawPremiumPanel(button, new Color(0.06f, 0.045f, 0.025f, 0.94f), new Color(0.64f, 0.44f, 0.14f, 0.64f));
                DrawGameIcon(new Rect(button.x + 8f, button.y + 8f, 24f, 24f), icons[i], Color.white);
                GUI.Label(new Rect(button.x + 38f, button.y + 7f, button.width - 44f, 28f), labels[i], new GUIStyle(smallStyle) { fontSize = compact ? 9 : 10, alignment = TextAnchor.MiddleLeft });
                if (GUI.Button(button, string.Empty, GUIStyle.none))
                {
                    AudioManager.Instance?.PlayUIClick();
                    if (ids[i] == "add" || ids[i] == "search")
                    {
                        friendsTab = "search";
                        friendsTabChangedAt = NowForUi();
                    }
                    else if (ids[i] == "requests")
                    {
                        friendsTab = "received";
                        friendsTabChangedAt = NowForUi();
                    }
                    else
                    {
                        ShowFriendsToast(ids[i] == "messages"
                            ? "Les messages privés arrivent à un prochain sprint."
                            : "Les cadeaux arrivent à un prochain sprint.");
                    }
                }
            }
            GUI.EndScrollView();
        }

        private static void DrawFriendsTabs(bool compact, float y)
        {
            string[] ids = { "friends", "received", "sent", "search" };
            string[] labels =
            {
                "Mes amis · " + socialFriends.Count.ToString(CultureInfo.InvariantCulture),
                "Reçues · " + socialReceivedRequests.Count.ToString(CultureInfo.InvariantCulture),
                "Envoyées · " + socialSentRequests.Count.ToString(CultureInfo.InvariantCulture),
                "Recherche"
            };
            float inset = 10f;
            float gap = 6f;
            float chipW = (Screen.width - inset * 2f - gap * 3f) / 4f;
            for (int i = 0; i < ids.Length; i++)
            {
                bool selected = friendsTab == ids[i];
                Rect chip = new Rect(inset + i * (chipW + gap), y, chipW, 38f);
                bool hovered = chip.Contains(Event.current != null ? Event.current.mousePosition : Vector2.zero);
                Color fill = selected ? new Color(0.38f, 0.22f, 0.05f, 0.98f) : hovered ? new Color(0.16f, 0.11f, 0.035f, 0.96f) : new Color(0.035f, 0.030f, 0.022f, 0.90f);
                Color border = selected ? new Color(1f, 0.72f, 0.18f, 0.96f) : new Color(0.54f, 0.38f, 0.14f, 0.60f);
                DrawPremiumPanel(chip, fill, border);
                bool badge = ids[i] == "received" && socialReceivedRequests.Count > 0;
                GUI.Label(chip, labels[i], new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 8 : 9, fontStyle = selected ? FontStyle.Bold : FontStyle.Normal, normal = { textColor = selected ? new Color(1f, 0.92f, 0.70f, 1f) : badge ? new Color(1f, 0.75f, 0.35f, 1f) : Color.white } });
                if (GUI.Button(chip, string.Empty, GUIStyle.none))
                {
                    AudioManager.Instance?.PlayUIClick();
                    if (friendsTab != ids[i])
                    {
                        friendsTab = ids[i];
                        friendsTabChangedAt = NowForUi();
                    }
                }
            }
        }

        private static void DrawFriendsTabContent(Rect rect, bool compact)
        {
            float fade = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((NowForUi() - friendsTabChangedAt) / 0.14f));
            float slide = Mathf.Lerp(12f, 0f, fade);
            GUI.color = new Color(1f, 1f, 1f, fade);
            Rect area = new Rect(rect.x + slide, rect.y, rect.width, rect.height);
            switch (friendsTab)
            {
                case "received": DrawFriendsReceivedTab(area, compact); break;
                case "sent": DrawFriendsSentTab(area, compact); break;
                case "search": DrawFriendsSearchTab(area, compact); break;
                default: DrawFriendsFriendsTab(area, compact); break;
            }
            GUI.color = Color.white;
        }

        private static void DrawFriendsFriendsTab(Rect area, bool compact)
        {
            float inset = 10f;
            float headerH = 26f;
            float listTop = area.y + inset + headerH;
            Rect viewport = new Rect(area.x + inset, listTop, area.width - inset * 2f, area.yMax - listTop - inset);
            if (viewport.width < 40f || viewport.height < 40f) return;
            int columns = compact ? 1 : 2;
            float gap = compact ? 6f : 10f;
            float cardH = compact ? 78f : 132f;
            float cardW = (viewport.width - gap) / columns;
            float friendH = (Mathf.CeilToInt(socialFriends.Count / (float)columns) * (cardH + gap));
            float recentHeaderH = compact ? 30f : 34f;
            float recentRowH = compact ? 62f : 70f;
            float contentH = headerH + friendH + recentHeaderH + 12f + socialRecentlyMet.Count * (recentRowH + gap) + 12f;
            friendsListScroll = GUI.BeginScrollView(viewport, friendsListScroll, new Rect(0f, 0f, viewport.width, Mathf.Max(viewport.height, contentH)), false, true);

            GUI.Label(new Rect(0f, 0f, viewport.width, headerH), "VOS AMIS", new GUIStyle(badgeStyle) { fontSize = compact ? 10 : 12 });
            float y = headerH;
            for (int i = 0; i < socialFriends.Count; i++)
            {
                int col = i % columns;
                int rowIdx = i / columns;
                DrawFriendCard(new Rect(col * (cardW + gap), y + rowIdx * (cardH + gap), cardW, cardH), socialFriends[i], compact);
            }
            float afterFriends = y + friendH + 12f;
            GUI.Label(new Rect(0f, afterFriends, viewport.width, recentHeaderH), "JOUEURS RÉCEMMENT RENCONTRÉS", new GUIStyle(badgeStyle) { fontSize = compact ? 10 : 12 });
            float ry = afterFriends + recentHeaderH;
            for (int i = 0; i < socialRecentlyMet.Count; i++)
            {
                DrawFriendRecentRow(new Rect(0f, ry, viewport.width, recentRowH), socialRecentlyMet[i], compact);
                ry += recentRowH + gap;
            }
            GUI.EndScrollView();
        }

        private static void DrawFriendAvatar(Rect rect, FriendProfileData friend)
        {
            DrawPremiumPanel(rect, new Color(0.10f, 0.07f, 0.03f, 0.98f), new Color(1f, 0.72f, 0.18f, 0.90f));
