        private static void DrawFriendCard(Rect rect, FriendProfileData friend, bool compact)
        {
            DrawPremiumPanel(rect, new Color(0.040f, 0.033f, 0.021f, 0.95f), new Color(0.70f, 0.48f, 0.14f, 0.62f));
            bool landscape = !compact;
            float avatarSize = landscape ? 56f : 44f;
            DrawFriendAvatar(new Rect(rect.x + 8f, rect.y + (rect.height - avatarSize) * 0.5f, avatarSize, avatarSize), friend);
            float textX = rect.x + 8f + avatarSize + 10f;
            float actionsW = landscape ? 158f : 94f;
            float textW = rect.width - textX - actionsW - 8f;
            GUI.Label(new Rect(textX, rect.y + (landscape ? 8f : 6f), textW, 18f), friend.Name, new GUIStyle(badgeStyle) { fontSize = landscape ? 14 : 12, alignment = TextAnchor.MiddleLeft });
            GUI.Label(new Rect(textX, rect.y + (landscape ? 30f : 25f), textW, 14f), "Niv. " + friend.Level.ToString(CultureInfo.InvariantCulture) + "  ·  " + friend.AllianceTag, new GUIStyle(smallStyle) { fontSize = landscape ? 10 : 9, alignment = TextAnchor.MiddleLeft, normal = { textColor = new Color(1f, 0.82f, 0.40f, 1f) } });
            Color presence = AlliancePresenceColor(friend.Presence);
            string presenceText = AlliancePresenceLabel(friend.Presence);
            if (landscape)
            {
                GUI.Label(new Rect(textX, rect.y + 50f, textW, 16f), presenceText + "  ·  " + friend.LastSeen, new GUIStyle(tinyLabelStyle) { fontSize = 9, alignment = TextAnchor.MiddleLeft, normal = { textColor = presence } });
                float ax = rect.xMax - 8f - 150f;
                if (FriendActionButton(new Rect(ax, rect.y + 14f, 26f, 26f), "message", "messages")) HandleFriendAction("message", friend);
                if (FriendActionButton(new Rect(ax + 30f, rect.y + 14f, 26f, 26f), "invite", "mail")) HandleFriendAction("invite", friend);
                if (FriendActionButton(new Rect(ax + 60f, rect.y + 14f, 26f, 26f), "gift", "gift")) HandleFriendAction("gift", friend);
                if (FriendActionButton(new Rect(ax + 90f, rect.y + 14f, 26f, 26f), "visit", "hive")) HandleFriendAction("visit", friend);
                if (FriendActionButton(new Rect(ax + 120f, rect.y + 14f, 26f, 26f), "remove", "locked")) HandleFriendAction("remove", friend);
            }
            else
            {
                GUI.Label(new Rect(textX, rect.y + 43f, textW, 14f), presenceText + "  ·  " + friend.LastSeen, new GUIStyle(tinyLabelStyle) { fontSize = 8, alignment = TextAnchor.MiddleLeft, normal = { textColor = presence } });
                float ax = rect.xMax - 90f;
                if (FriendActionButton(new Rect(ax, rect.y + 8f, 26f, 26f), "message", "messages")) HandleFriendAction("message", friend);
                if (FriendActionButton(new Rect(ax + 30f, rect.y + 8f, 26f, 26f), "invite", "mail")) HandleFriendAction("invite", friend);
                if (FriendActionButton(new Rect(ax + 60f, rect.y + 8f, 26f, 26f), "gift", "gift")) HandleFriendAction("gift", friend);
                if (FriendActionButton(new Rect(ax, rect.y + 38f, 26f, 26f), "visit", "hive")) HandleFriendAction("visit", friend);
                if (FriendActionButton(new Rect(ax + 30f, rect.y + 38f, 26f, 26f), "remove", "locked")) HandleFriendAction("remove", friend);
            }
        }

