        private static void DrawFriendsReceivedTab(Rect area, bool compact)
        {
            float inset = 10f;
            float headerH = 26f;
            Rect viewport = new Rect(area.x + inset, area.y + inset, area.width - inset * 2f, area.yMax - area.y - inset * 2f);
            if (viewport.width < 40f || viewport.height < 40f) return;
            float rowH = compact ? 66f : 76f;
            float gap = compact ? 6f : 10f;
            float contentH = Mathf.Max(viewport.height, headerH + 8f + Mathf.Max(1, socialReceivedRequests.Count) * (rowH + gap));
            friendsReceivedScroll = GUI.BeginScrollView(viewport, friendsReceivedScroll, new Rect(0f, 0f, viewport.width, contentH), false, true);
            GUI.Label(new Rect(0f, 0f, viewport.width, headerH), "INVITATIONS REÇUES · " + socialReceivedRequests.Count.ToString(CultureInfo.InvariantCulture), new GUIStyle(badgeStyle) { fontSize = compact ? 10 : 12 });
            float y = headerH + 8f;
            if (socialReceivedRequests.Count == 0)
            {
                GUI.Label(new Rect(0f, y, viewport.width, 26f), "Aucune invitation en attente.", new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter });
            }
            else
            {
                for (int i = 0; i < socialReceivedRequests.Count; i++)
                {
                    DrawFriendRequestRow(new Rect(0f, y, viewport.width, rowH), socialReceivedRequests[i], compact, true);
                    y += rowH + gap;
                }
            }
            GUI.EndScrollView();
        }

