        private static void DrawFriendRequestRow(Rect rect, FriendProfileData friend, bool compact, bool received)
        {
            DrawPremiumPanel(rect, new Color(0.035f, 0.030f, 0.020f, 0.95f), new Color(0.68f, 0.48f, 0.14f, 0.60f));
            DrawFriendAvatar(new Rect(rect.x + 8f, rect.y + (rect.height - 40f) * 0.5f, 40f, 40f), friend);
            float textX = rect.x + 58f;
            float buttonsW = received ? 144f : 80f;
            float textW = rect.width - 58f - buttonsW - 10f;
            GUI.Label(new Rect(textX, rect.y + 8f, textW, 18f), friend.Name, new GUIStyle(badgeStyle) { fontSize = compact ? 12 : 13, alignment = TextAnchor.MiddleLeft });
            GUI.Label(new Rect(textX, rect.y + 28f, textW, 14f), "Niv. " + friend.Level.ToString(CultureInfo.InvariantCulture) + "  ·  " + friend.AllianceTag, new GUIStyle(tinyLabelStyle) { fontSize = compact ? 8 : 9, alignment = TextAnchor.MiddleLeft, normal = { textColor = new Color(1f, 0.82f, 0.40f, 1f) } });
            if (received)
            {
                Rect accept = new Rect(rect.xMax - 152f, rect.y + (rect.height - 30f) * 0.5f, 70f, 30f);
                DrawPremiumPanel(accept, new Color(0.10f, 0.22f, 0.08f, 0.96f), new Color(0.50f, 0.90f, 0.40f, 0.90f));
                GUI.Label(accept, "Accepter", new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 8 : 9 });
                if (GUI.Button(accept, string.Empty, GUIStyle.none))
                {
                    AudioManager.Instance?.PlayUIClick();
                    socialFriends.Add(friend);
                    socialReceivedRequests.Remove(friend);
                    ShowFriendsToast(friend.Name + " est maintenant votre ami.");
                }
                Rect decline = new Rect(rect.xMax - 78f, rect.y + (rect.height - 30f) * 0.5f, 70f, 30f);
                DrawPremiumPanel(decline, new Color(0.22f, 0.08f, 0.06f, 0.96f), new Color(0.92f, 0.40f, 0.30f, 0.90f));
                GUI.Label(decline, "Refuser", new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 8 : 9 });
                if (GUI.Button(decline, string.Empty, GUIStyle.none))
                {
                    AudioManager.Instance?.PlayUIClick();
                    socialReceivedRequests.Remove(friend);
                    ShowFriendsToast("Invitation de " + friend.Name + " refusée.");
                }
            }
            else
            {
                Rect cancel = new Rect(rect.xMax - 82f, rect.y + (rect.height - 30f) * 0.5f, 74f, 30f);
                DrawPremiumPanel(cancel, new Color(0.22f, 0.12f, 0.05f, 0.96f), new Color(1f, 0.70f, 0.22f, 0.90f));
                GUI.Label(cancel, "Annuler", new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 8 : 9 });
                if (GUI.Button(cancel, string.Empty, GUIStyle.none))
                {
                    AudioManager.Instance?.PlayUIClick();
                    socialSentRequests.Remove(friend);
                    ShowFriendsToast("Demande envoyée à " + friend.Name + " annulée.");
                }
            }
        }

        private static void DrawFriendsSearchTab(Rect area, bool compact)
        {
            float inset = 10f;
            float headerH = 26f;
            float fieldH = 40f;
            Rect fieldRect = new Rect(area.x + inset, area.y + inset + headerH, area.width - inset * 2f, fieldH);
            DrawPremiumPanel(fieldRect, new Color(0.04f, 0.032f, 0.02f, 0.96f), new Color(0.86f, 0.58f, 0.16f, 0.80f));
            GUIStyle fieldStyle = new GUIStyle(GUI.skin.textField)
            {
                fontSize = compact ? 12 : 14,
                alignment = TextAnchor.MiddleLeft,
                padding = new RectOffset(10, 10, 4, 4)
            };
            fieldStyle.normal = new GUIStyleState { textColor = Color.white, background = null };
            fieldStyle.active = fieldStyle.normal;
            fieldStyle.hover = fieldStyle.normal;
            fieldStyle.focused = fieldStyle.normal;
            friendsSearchQuery = GUI.TextField(new Rect(fieldRect.x + 6f, fieldRect.y + 4f, fieldRect.width - 12f, fieldRect.height - 8f), friendsSearchQuery, fieldStyle);

            float listTop = fieldRect.yMax + 10f;
            Rect viewport = new Rect(area.x + inset, listTop, area.width - inset * 2f, area.yMax - listTop - inset);
            if (viewport.width < 40f || viewport.height < 40f) return;

            List<FriendProfileData> results = new List<FriendProfileData>(12);
            string query = friendsSearchQuery == null ? string.Empty : friendsSearchQuery.Trim();
            if (query.Length > 0)
            {
                for (int i = 0; i < socialSearchPool.Count; i++)
                {
                    FriendProfileData candidate = socialSearchPool[i];
                    if (candidate.Name.IndexOf(query, StringComparison.OrdinalIgnoreCase) < 0) continue;
                    bool already = IsAlreadyRelated(candidate.Name);
                    if (already) continue;
                    results.Add(candidate);
                }
            }

            float rowH = compact ? 66f : 76f;
            float gap = compact ? 6f : 10f;
            float contentH = Mathf.Max(viewport.height, 26f + Mathf.Max(1, results.Count) * (rowH + gap));
            friendsSearchScroll = GUI.BeginScrollView(viewport, friendsSearchScroll, new Rect(0f, 0f, viewport.width, contentH), false, true);
            GUI.Label(new Rect(0f, 0f, viewport.width, 26f), results.Count.ToString(CultureInfo.InvariantCulture) + " résultat(s)", new GUIStyle(badgeStyle) { fontSize = compact ? 10 : 12 });
            float y = 32f;
            if (query.Length == 0)
            {
                GUI.Label(new Rect(0f, y, viewport.width, 26f), "Tapez un nom de joueur pour chercher.", new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter });
            }
            else if (results.Count == 0)
            {
                GUI.Label(new Rect(0f, y, viewport.width, 26f), "Aucun joueur trouvé pour « " + query + " ».", new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter });
            }
            else
            {
                for (int i = 0; i < results.Count; i++)
                {
                    DrawFriendSearchRow(new Rect(0f, y, viewport.width, rowH), results[i], compact);
                    y += rowH + gap;
                }
            }
            GUI.EndScrollView();
        }

        private static bool IsAlreadyRelated(string name)
        {
            for (int i = 0; i < socialFriends.Count; i++)
            {
                if (string.Equals(socialFriends[i].Name, name, StringComparison.Ordinal)) return true;
            }
            return HasSentOrReceivedFriendRequest(name);
        }

