        private static bool FriendActionButton(Rect rect, string id, string icon)
        {
            bool hovered = rect.Contains(Event.current != null ? Event.current.mousePosition : Vector2.zero);
            DrawPremiumPanel(rect, hovered ? new Color(0.22f, 0.13f, 0.03f, 0.98f) : new Color(0.045f, 0.036f, 0.024f, 0.94f), new Color(0.82f, 0.54f, 0.14f, 0.85f));
            DrawGameIcon(new Rect(rect.x + 5f, rect.y + 5f, rect.width - 10f, rect.height - 10f), icon, Color.white);
            return GUI.Button(rect, string.Empty, GUIStyle.none);
        }

        private static void HandleFriendAction(string id, FriendProfileData friend)
        {
            switch (id)
            {
                case "message": ShowFriendsToast("La messagerie privée arrive à un prochain sprint."); break;
                case "invite": ShowFriendsToast("L'invitation dans l'alliance est en préparation."); break;
                case "gift": ShowFriendsToast("Les cadeaux arrivent à un prochain sprint."); break;
                case "visit": ShowFriendsToast("La visite de ruche arrive à un prochain sprint."); break;
                case "remove":
                    socialFriends.Remove(friend);
                    ShowFriendsToast(friend.Name + " retiré(e) de vos amis.");
                    break;
                default: ShowFriendsToast("Action en préparation."); break;
            }
        }

        private static void DrawFriendsToast()
        {
            if (friendsToastAt < 0f) return;
            float age = NowForUi() - friendsToastAt;
            float fade = 1f - Mathf.Clamp01((age - 1.2f) / 0.8f);
            if (fade <= 0f) return;
            float tw = Mathf.Min(Screen.width - 24f, 380f);
            Rect toast = new Rect((Screen.width - tw) * 0.5f, Screen.height - 72f, tw, 40f);
            Color previous = GUI.color;
            GUI.color = new Color(1f, 1f, 1f, fade);
            DrawPremiumPanel(toast, new Color(0.05f, 0.04f, 0.025f, 0.98f), new Color(0.86f, 0.58f, 0.16f, 0.90f));
            GUI.Label(new Rect(toast.x + 10f, toast.y + 8f, toast.width - 20f, 24f), friendsToast, new GUIStyle(smallStyle) { fontSize = 10, alignment = TextAnchor.MiddleCenter });
            GUI.color = previous;
        }

        private sealed class CourierRewardData
        {
            public string Type;
            public string ItemId;
            public int Amount;
            public bool Collected;
        }

        private sealed class CourierMessageData
        {
            public int Id;
            public string Category;
            public string Title;
            public string Preview;
            public string Body;
            public string DateLabel;
            public bool Read;
            public bool Favorite;
            public List<CourierRewardData> Rewards = new List<CourierRewardData>();
        }

        private static readonly List<CourierMessageData> courierMessages = BuildCourierMessages();

        // M043T-CL: a real pending Alliance invitation used to be invisible unless the player
        // explicitly opened Alliance Center -> Invitations. Reuses two systems that already exist
        // and are already drawn every frame regardless of which screen is open (UIFeedbackSystem,
        // drawn last in DrawInternal; the Courrier/Mail list) instead of building a new alert or
        // inbox system. No new network calls - reads the Model that allianceCenterController.Refresh()
        // (called once at hive load, see MobileAccountSessionRuntimeBootstrap) already fetched.
        private static readonly HashSet<Guid> allianceInvitationAlertsShown = new HashSet<Guid>();

        private static void CheckForNewAllianceInvitationAlerts()
        {
            AllianceCenterScreenModel model = allianceCenterController.Model;
            if (model?.MyInvitations == null) return;
            for (int i = 0; i < model.MyInvitations.Count; i++)
            {
                AllianceInvitationModel invite = model.MyInvitations[i];
                if (invite.Status != RemoteAllianceInvitationStatus.Pending) continue;
                if (!allianceInvitationAlertsShown.Add(invite.InvitationId)) continue;

                UIFeedbackSystem.ShowFloatingText(
                    "Nouvelle invitation d'Alliance en attente — voir Courrier",
                    new Vector2(Screen.width * 0.5f, Screen.height * 0.16f),
                    new Color(0.82f, 0.60f, 0.95f, 1f),
                    5f);

                courierMessages.Insert(0, new CourierMessageData
                {
                    Id = -Math.Abs(invite.InvitationId.GetHashCode()),
                    Category = "alliance",
                    Title = "Invitation d'Alliance",
                    Preview = "Vous avez reçu une invitation à rejoindre une alliance.",
                    Body = "Ouvrez Alliance Center pour accepter ou refuser cette invitation.",
                    DateLabel = "à l'instant",
                    Read = false,
                    Favorite = false
                });
            }
        }

        private static List<CourierMessageData> BuildCourierMessages()
        {
            List<CourierMessageData> messages = new List<CourierMessageData>(240);
            string[] categories = { "system", "reward", "report", "alliance", "system", "reward" };
            string[] titles = { "Bienvenue dans BeeKingdom", "Récompense de récolte", "Rapport de combat", "Message de l'Alliance", "Maintenance du royaume", "Cadeau reçu" };
            string[] previews = { "Votre ruche poursuit sa progression.", "Une récompense attend votre collecte.", "Votre dernier affrontement est terminé.", "Votre Alliance vous transmet une nouvelle.", "Une amélioration du royaume est disponible.", "Un joueur vous a envoyé un cadeau." };
            for (int i = 0; i < 240; i++)
            {
                int typeIndex = i % categories.Length;
                CourierMessageData message = new CourierMessageData
                {
                    Id = i,
                    Category = categories[typeIndex],
                    Title = titles[typeIndex],
                    Preview = previews[typeIndex],
                    Body = previews[typeIndex] + " Cette notification simulée prépare le futur courrier serveur et conservera son historique, son état de lecture et ses récompenses.",
                    DateLabel = i < 2 ? "à l'instant" : i < 60 ? "il y a " + (i + 1).ToString() + " min" : "06 août 2026",
                    Read = i % 7 != 0,
                    Favorite = i % 31 == 0
                };
                if (message.Category == "reward" || i % 23 == 0)
                {
                    message.Rewards.Add(new CourierRewardData
                    {
                        Type = i % 2 == 0 ? "resource" : "item",
                        ItemId = i % 2 == 0 ? "honey" : "event_chest",
                        Amount = i % 2 == 0 ? 250 + i : 1
                    });
                }
                messages.Add(message);
            }
            return messages;
        }

        private static string CourierCategoryLabel(string category)
        {
            switch (category)
            {
                case "reward": return "Récompenses";
                case "report": return "Rapports";
                case "alliance": return "Alliance";
                case "system": return "Système";
                default: return "Tous";
            }
        }

        private static string CourierCategoryIcon(string category)
        {
            switch (category)
            {
                case "reward": return "gift";
                case "report": return "sword";
                case "alliance": return "members";
                case "system": return "preview";
                default: return "inbox";
            }
        }

        private static Color CourierCategoryColor(string category)
        {
            switch (category)
            {
                case "reward": return new Color(1f, 0.72f, 0.18f, 1f);
                case "report": return new Color(0.92f, 0.36f, 0.30f, 1f);
                case "alliance": return new Color(0.82f, 0.60f, 0.95f, 1f);
                case "system": return new Color(0.40f, 0.65f, 0.95f, 1f);
                default: return new Color(0.86f, 0.62f, 0.18f, 1f);
            }
        }

        private static bool CourierHasUncollectedReward(CourierMessageData message)
        {
            for (int i = 0; i < message.Rewards.Count; i++)
                if (!message.Rewards[i].Collected) return true;
            return false;
        }

        private static int CourierNotificationCount()
        {
            int count = 0;
            for (int i = 0; i < courierMessages.Count; i++)
            {
                if (!courierMessages[i].Read || CourierHasUncollectedReward(courierMessages[i])) count++;
            }
            return count;
        }

        private static CourierMessageData CourierSelectedMessage()
        {
            for (int i = 0; i < courierMessages.Count; i++)
                if (courierMessages[i].Id == courierSelectedId) return courierMessages[i];
            return null;
        }

        private static void OpenCourierScreen()
        {
            courierScreenOpen = true;
            courierReaderOpen = false;
            courierScreenOpenedAt = NowForUi();
            courierToast = string.Empty;
            courierToastAt = -10f;
            AudioManager.Instance?.PlayMenuOpen();
        }

        // Closes ONLY the member profile overlay - returns to whatever Alliance Center screen was
        // underneath (member list, overview, etc.), never exits the Alliance menu itself. Previously
        // this also reset activeHiveMenu to Hive, so backing out of a profile silently exited the
        // entire Alliance Center with no way back in (re-opening the Alliance building would just
        // show the stuck profile again, since allianceMemberProfileOpen was the only thing this
        // method actually cleared correctly). Exiting Alliance itself is a separate, deliberate
        // action - see ClosePremiumScreensInPriorityOrderCore's own Alliance-menu-close branch.
        private static void CloseAllianceMemberProfile()
        {
            allianceMemberProfileOpen = false;
            allianceMemberProfileName = string.Empty;
            allianceActionPanelOpen = string.Empty;
            allianceChatDrawerOpen = false;
            GUIUtility.hotControl = 0;
            GUIUtility.keyboardControl = 0;
        }

        private static void ShowCourierToast(string message)
        {
            courierToast = message;
            courierToastAt = NowForUi();
        }

        private static void DrawCourierScreen(bool compact)
        {
            if (!courierScreenOpen) return;
            if (Event.current != null && Event.current.type == EventType.KeyDown && Event.current.keyCode == KeyCode.Escape)
            {
                courierScreenOpen = false;
                AudioManager.Instance?.PlayMenuClose();
                Event.current.Use();
                return;
            }
            float anim = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((NowForUi() - courierScreenOpenedAt) / 0.18f));
            float zoom = Mathf.Lerp(0.97f, 1f, anim);
            Rect full = new Rect(0f, 0f, Screen.width, Screen.height);
            GUI.matrix = Matrix4x4.TRS(full.center, Quaternion.identity, new Vector3(zoom, zoom, 1f)) * Matrix4x4.Translate(-full.center);
            GUI.color = new Color(0.006f, 0.005f, 0.004f, 0.99f * anim);
            GUI.DrawTexture(full, Texture2D.blackTexture, ScaleMode.StretchToFill, false);
            GUI.color = Color.white;
            float bannerHeight = compact ? Mathf.Min(150f, Screen.height * 0.20f) : Mathf.Clamp(Screen.height * 0.20f, 150f, 190f);
            DrawCourierBanner(bannerHeight, compact);
            DrawCourierTopBar(bannerHeight);
            if (!courierScreenOpen)
            {
                GUI.matrix = Matrix4x4.identity;
                GUI.color = Color.white;
                return;
            }
            float quickY = bannerHeight + 6f;
            float quickH = compact ? 60f : 64f;
            DrawCourierQuickActions(new Rect(10f, quickY, Screen.width - 20f, quickH), compact);
            float tabsY = quickY + quickH + 6f;
            DrawCourierTabs(tabsY, compact);
            float contentTop = tabsY + 44f;
            DrawCourierContent(new Rect(0f, contentTop, Screen.width, Mathf.Max(1f, Screen.height - contentTop)), compact);
            DrawCourierToast();
            GUI.matrix = Matrix4x4.identity;
        }

        private static void DrawCourierBanner(float height, bool compact)
        {
            Rect banner = new Rect(0f, 0f, Screen.width, height);
            Texture2D texture = Resources.Load<Texture2D>("PremiumBeeReference/BuildingBanners/courier_hall");
            if (texture == null) texture = Resources.Load<Texture2D>("PremiumBeeReference/BuildingBanners/friends_hall");
            if (texture == null) texture = Resources.Load<Texture2D>("PremiumBeeReference/BuildingBanners/alliance_future_hall");
            if (texture != null) GUI.DrawTexture(banner, texture, ScaleMode.ScaleAndCrop, true);
            else DrawPremiumPanel(banner, new Color(0.14f, 0.085f, 0.025f, 0.98f), new Color(1f, 0.68f, 0.16f, 0.90f));
            GUI.color = new Color(0.01f, 0.008f, 0.004f, 0.50f);
            GUI.DrawTexture(banner, Texture2D.blackTexture, ScaleMode.StretchToFill, true);
            GUI.color = Color.white;
            GUI.Label(new Rect(28f, height - (compact ? 42f : 48f), Screen.width * 0.68f, 26f), "COURRIER", new GUIStyle(titleStyle) { fontSize = compact ? 20 : 28, fontStyle = FontStyle.Bold });
            GUI.Label(new Rect(30f, height - (compact ? 20f : 23f), Screen.width * 0.70f, 16f), "Le point d'entrée de vos récompenses", new GUIStyle(smallStyle) { fontSize = compact ? 9 : 12 });
        }

        private static void DrawCourierTopBar(float bannerHeight)
        {
            GUI.color = new Color(1f, 0.60f, 0.14f, 0.95f);
            GUI.DrawTexture(new Rect(0f, bannerHeight - 1f, Screen.width, 1f), Texture2D.whiteTexture, ScaleMode.StretchToFill, false);
            GUI.color = Color.white;
			if (DrawPremiumBackButton(new Rect(4f, 2f, 48f, 46f)))
			{
				AudioManager.Instance?.PlayUIClick();
				AudioManager.Instance?.PlayMenuClose();
				courierScreenOpen = false;
				return;
			}
            GUI.Label(new Rect(54f, 12f, Screen.width - 218f, 24f), "BOÎTE DE RÉCEPTION", new GUIStyle(badgeStyle) { fontSize = 11 });
            Rect badge = new Rect(Screen.width - 158f, 10f, 96f, 28f);
            DrawPremiumPanel(badge, new Color(0.05f, 0.04f, 0.025f, 0.96f), new Color(0.86f, 0.58f, 0.16f, 0.85f));
            GUI.Label(badge, CourierNotificationCount().ToString(CultureInfo.InvariantCulture) + " À TRAITER", new GUIStyle(centeredTinyLabelStyle) { fontSize = 8 });
		}

        private static void DrawCourierQuickActions(Rect rect, bool compact)
        {
            string[] ids = { "collect", "read", "favorite", "delete", "search" };
            string[] labels = { "Tout récupérer", "Tout lire", "Favoris", "Supprimer lus", "Rechercher" };
            string[] icons = { "gift", "messages", "star", "locked", "search" };
            float gap = 6f;
            float itemWidth = compact ? 122f : Mathf.Max(122f, (rect.width - gap * 4f) / 5f);
            DrawPremiumPanel(rect, new Color(0.025f, 0.022f, 0.017f, 0.98f), new Color(0.82f, 0.54f, 0.14f, 0.84f));
            courierQuickActionsScroll = GUI.BeginScrollView(rect, courierQuickActionsScroll, new Rect(0f, 0f, itemWidth * 5f + gap * 4f + 8f, rect.height - 2f), false, false);
            for (int i = 0; i < ids.Length; i++)
            {
                Rect button = new Rect(4f + i * (itemWidth + gap), 6f, itemWidth, rect.height - 12f);
                DrawPremiumPanel(button, new Color(0.06f, 0.045f, 0.025f, 0.94f), new Color(0.64f, 0.44f, 0.14f, 0.64f));
                DrawGameIcon(new Rect(button.x + 8f, button.y + 8f, 24f, 24f), icons[i], Color.white);
                GUI.Label(new Rect(button.x + 38f, button.y + 7f, button.width - 44f, 28f), labels[i], new GUIStyle(smallStyle) { fontSize = compact ? 8 : 9, alignment = TextAnchor.MiddleLeft });
                if (GUI.Button(button, string.Empty, GUIStyle.none))
                {
                    AudioManager.Instance?.PlayUIClick();
                    if (ids[i] == "collect")
                    {
                        for (int m = 0; m < courierMessages.Count; m++)
                            for (int r = 0; r < courierMessages[m].Rewards.Count; r++) courierMessages[m].Rewards[r].Collected = true;
                        ShowCourierToast("Toutes les récompenses disponibles ont été récupérées.");
                    }
                    else if (ids[i] == "read")
                    {
                        for (int m = 0; m < courierMessages.Count; m++) courierMessages[m].Read = true;
                        ShowCourierToast("Tous les courriers sont marqués comme lus.");
                    }
                    else if (ids[i] == "favorite") courierTab = "favorite";
                    else if (ids[i] == "delete")
                    {
                        courierMessages.RemoveAll(message => message.Read && !message.Favorite);
                        ShowCourierToast("Les courriers lus ont été supprimés.");
                    }
                    else courierSearchQuery = string.Empty;
                }
            }
            GUI.EndScrollView();
        }

        private static void DrawCourierTabs(float y, bool compact)
        {
            string[] ids = { "all", "reward", "report", "alliance", "system", "favorite" };
            string[] labels = { "Tous", "Récompenses", "Rapports", "Alliance", "Système", "Favoris" };
            float inset = 10f;
            float gap = 5f;
            float width = compact ? 104f : (Screen.width - inset * 2f - gap * 5f) / 6f;
            DrawPremiumPanel(new Rect(0f, y, Screen.width, 38f), new Color(0.018f, 0.016f, 0.013f, 0.98f), new Color(0.70f, 0.46f, 0.13f, 0.68f));
            courierTabsScroll = GUI.BeginScrollView(new Rect(0f, y, Screen.width, 38f), courierTabsScroll, new Rect(0f, 0f, inset * 2f + ids.Length * width + gap * 5f, 36f), false, false);
            for (int i = 0; i < ids.Length; i++)
            {
                Rect tab = new Rect(inset + i * (width + gap), 2f, width, 32f);
                bool selected = courierTab == ids[i];
                DrawPremiumPanel(tab, selected ? new Color(0.38f, 0.22f, 0.05f, 0.98f) : new Color(0.04f, 0.032f, 0.022f, 0.90f), selected ? new Color(1f, 0.72f, 0.18f, 0.96f) : new Color(0.54f, 0.38f, 0.14f, 0.60f));
                GUI.Label(tab, labels[i], new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 8 : 9, fontStyle = selected ? FontStyle.Bold : FontStyle.Normal });
                if (GUI.Button(tab, string.Empty, GUIStyle.none))
                {
                    courierTab = ids[i];
                    courierTabChangedAt = NowForUi();
                    courierReaderOpen = false;
                }
            }
            GUI.EndScrollView();
        }

        private static bool CourierMatches(CourierMessageData message)
        {
            if (courierTab == "favorite" && !message.Favorite) return false;
            if (courierTab != "all" && courierTab != "favorite" && message.Category != courierTab) return false;
            if (!string.IsNullOrWhiteSpace(courierSearchQuery) && message.Title.IndexOf(courierSearchQuery, StringComparison.OrdinalIgnoreCase) < 0 && message.Preview.IndexOf(courierSearchQuery, StringComparison.OrdinalIgnoreCase) < 0) return false;
            return true;
        }

        private static void DrawCourierContent(Rect area, bool compact)
        {
            float fade = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((NowForUi() - courierTabChangedAt) / 0.14f));
            GUI.color = new Color(1f, 1f, 1f, fade);
            if (compact && courierReaderOpen)
            {
                DrawCourierReader(area, true);
                GUI.color = Color.white;
                return;
            }
            if (compact) DrawCourierList(area, true);
            else
            {
                float split = Mathf.Clamp(area.width * 0.42f, 360f, 560f);
                DrawCourierList(new Rect(area.x + 10f, area.y + 8f, split, area.height - 16f), false);
                DrawCourierReader(new Rect(area.x + split + 18f, area.y + 8f, area.width - split - 28f, area.height - 16f), false);
            }
            GUI.color = Color.white;
        }

        private static void DrawCourierList(Rect area, bool compact)
        {
            DrawPremiumPanel(area, new Color(0.030f, 0.025f, 0.017f, 0.97f), new Color(0.78f, 0.52f, 0.15f, 0.72f));
            float inset = 8f;
            Rect search = new Rect(area.x + inset, area.y + inset, area.width - inset * 2f, 32f);
            DrawPremiumPanel(search, new Color(0.045f, 0.035f, 0.022f, 0.96f), new Color(0.62f, 0.44f, 0.16f, 0.62f));
            GUIStyle searchStyle = new GUIStyle(GUI.skin.textField) { fontSize = compact ? 11 : 12, padding = new RectOffset(8, 8, 3, 3) };
            searchStyle.normal = new GUIStyleState { textColor = Color.white, background = null };
            searchStyle.focused = searchStyle.normal;
            courierSearchQuery = GUI.TextField(new Rect(search.x + 4f, search.y + 3f, search.width - 8f, search.height - 6f), courierSearchQuery, searchStyle);
            Rect viewport = new Rect(area.x + inset, search.yMax + 6f, area.width - inset * 2f, area.height - search.height - inset * 2f - 6f);
            List<CourierMessageData> visible = new List<CourierMessageData>(courierMessages.Count);
            for (int i = 0; i < courierMessages.Count; i++) if (CourierMatches(courierMessages[i])) visible.Add(courierMessages[i]);
            float rowH = compact ? 68f : 76f;
            float gap = 5f;
            courierListScroll = GUI.BeginScrollView(viewport, courierListScroll, new Rect(0f, 0f, viewport.width, Mathf.Max(viewport.height, visible.Count * (rowH + gap))), false, true);
            for (int i = 0; i < visible.Count; i++) DrawCourierRow(new Rect(0f, i * (rowH + gap), viewport.width, rowH), visible[i], compact);
            if (visible.Count == 0) GUI.Label(new Rect(0f, 12f, viewport.width, 26f), "Aucun courrier pour ce filtre.", new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleCenter });
            GUI.EndScrollView();
        }

        private static void DrawCourierRow(Rect rect, CourierMessageData message, bool compact)
        {
            Color accent = CourierCategoryColor(message.Category);
            DrawPremiumPanel(rect, message.Read ? new Color(0.040f, 0.033f, 0.022f, 0.90f) : new Color(0.095f, 0.060f, 0.020f, 0.98f), new Color(accent.r, accent.g, accent.b, message.Read ? 0.45f : 0.90f));
            Rect icon = new Rect(rect.x + 8f, rect.y + (rect.height - 38f) * 0.5f, 38f, 38f);
            DrawPremiumPanel(icon, new Color(accent.r * 0.16f, accent.g * 0.16f, accent.b * 0.16f, 0.96f), new Color(accent.r, accent.g, accent.b, 0.80f));
            DrawGameIcon(new Rect(icon.x + 6f, icon.y + 6f, 26f, 26f), CourierCategoryIcon(message.Category), Color.white);
            float textX = icon.xMax + 10f;
            float textW = rect.width - textX - 72f;
            GUI.Label(new Rect(textX, rect.y + 7f, textW, 18f), message.Title, new GUIStyle(badgeStyle) { fontSize = compact ? 10 : 12, normal = { textColor = accent } });
            GUI.Label(new Rect(textX, rect.y + 27f, textW, 28f), message.Preview, new GUIStyle(smallStyle) { fontSize = compact ? 8 : 10, wordWrap = true });
            GUI.Label(new Rect(rect.xMax - 66f, rect.y + 7f, 58f, 16f), message.DateLabel, new GUIStyle(tinyLabelStyle) { fontSize = 8, alignment = TextAnchor.MiddleRight });
            if (!message.Read) GUI.Label(new Rect(rect.xMax - 18f, rect.yMax - 22f, 12f, 12f), "•", new GUIStyle(centeredTinyLabelStyle) { fontSize = 16, normal = { textColor = new Color(1f, 0.72f, 0.18f, 1f) } });
            if (CourierHasUncollectedReward(message)) DrawGameIcon(new Rect(rect.xMax - 42f, rect.yMax - 22f, 16f, 16f), "gift", new Color(1f, 0.72f, 0.18f, 1f));
            if (GUI.Button(rect, string.Empty, GUIStyle.none))
            {
                message.Read = true;
                courierSelectedId = message.Id;
                courierReaderOpen = true;
                AudioManager.Instance?.PlayUIClick();
            }
        }

        private static void DrawCourierReader(Rect area, bool compact)
        {
            CourierMessageData message = CourierSelectedMessage();
            DrawPremiumPanel(area, new Color(0.030f, 0.025f, 0.017f, 0.98f), new Color(0.82f, 0.54f, 0.14f, 0.76f));
            if (message == null)
            {
                GUI.Label(new Rect(area.x + 20f, area.y + 28f, area.width - 40f, 24f), "Sélectionnez un courrier", new GUIStyle(badgeStyle) { alignment = TextAnchor.MiddleCenter });
                return;
            }
            if (compact && GUI.Button(new Rect(area.x + 10f, area.y + 8f, 70f, 28f), "← Liste"))
            {
                courierReaderOpen = false;
                AudioManager.Instance?.PlayUIClick();
                return;
            }
            float top = compact ? 46f : 14f;
            Color accent = CourierCategoryColor(message.Category);
            DrawGameIcon(new Rect(area.x + 14f, area.y + top, 34f, 34f), CourierCategoryIcon(message.Category), Color.white);
            GUI.Label(new Rect(area.x + 58f, area.y + top, area.width - 150f, 24f), message.Title, new GUIStyle(titleStyle) { fontSize = compact ? 17 : 22 });
            GUI.Label(new Rect(area.x + 58f, area.y + top + 27f, area.width - 80f, 16f), CourierCategoryLabel(message.Category) + "  ·  " + message.DateLabel, new GUIStyle(tinyLabelStyle) { fontSize = 9, normal = { textColor = accent } });
            Rect favorite = new Rect(area.xMax - 54f, area.y + top, 34f, 34f);
            DrawPremiumPanel(favorite, message.Favorite ? new Color(0.35f, 0.22f, 0.05f, 0.98f) : new Color(0.05f, 0.04f, 0.025f, 0.96f), new Color(1f, 0.72f, 0.18f, 0.85f));
            DrawGameIcon(new Rect(favorite.x + 6f, favorite.y + 6f, 22f, 22f), "star", Color.white);
            if (GUI.Button(favorite, string.Empty, GUIStyle.none)) message.Favorite = !message.Favorite;
            Rect viewport = new Rect(area.x + 14f, area.y + top + 54f, area.width - 28f, area.height - top - 62f);
            courierReaderScroll = GUI.BeginScrollView(viewport, courierReaderScroll, new Rect(0f, 0f, viewport.width - 16f, Mathf.Max(viewport.height, 330f)), false, true);
            GUI.Label(new Rect(0f, 0f, viewport.width - 16f, 72f), message.Body, new GUIStyle(smallStyle) { fontSize = compact ? 11 : 13, wordWrap = true });
            float y = 88f;
            if (message.Rewards.Count > 0)
            {
                GUI.Label(new Rect(0f, y, viewport.width - 16f, 22f), "RÉCOMPENSES", new GUIStyle(badgeStyle) { fontSize = 11 });
                y += 28f;
                for (int i = 0; i < message.Rewards.Count; i++)
                {
                    CourierRewardData reward = message.Rewards[i];
                    Rect rewardRect = new Rect(0f, y, viewport.width - 16f, 58f);
                    DrawPremiumPanel(rewardRect, new Color(0.06f, 0.045f, 0.025f, 0.96f), new Color(1f, 0.72f, 0.18f, 0.72f));
                    DrawGameIcon(new Rect(rewardRect.x + 10f, rewardRect.y + 10f, 34f, 34f), reward.ItemId == "honey" ? "honey" : "gift", Color.white);
                    GUI.Label(new Rect(rewardRect.x + 54f, rewardRect.y + 18f, rewardRect.width - 170f, 20f), reward.ItemId == "honey" ? "Miel" : "Coffre événement", new GUIStyle(badgeStyle) { fontSize = 11 });
                    if (!reward.Collected)
                    {
                        Rect collect = new Rect(rewardRect.xMax - 102f, rewardRect.y + 14f, 92f, 30f);
                        GUI.Label(collect, "Récupérer", new GUIStyle(centeredTinyLabelStyle) { fontSize = 9 });
                        if (GUI.Button(collect, string.Empty, GUIStyle.none)) { reward.Collected = true; ShowCourierToast("Récompense récupérée."); }
                    }
                    else GUI.Label(new Rect(rewardRect.xMax - 104f, rewardRect.y + 18f, 94f, 20f), "Récupérée", new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleRight });
                    y += 66f;
                }
            }
            GUI.EndScrollView();
        }

        private static void DrawCourierToast()
        {
            if (courierToastAt < 0f) return;
            float age = NowForUi() - courierToastAt;
            float alpha = 1f - Mathf.Clamp01((age - 1.2f) / 0.8f);
            if (alpha <= 0f) return;
            float width = Mathf.Min(Screen.width - 24f, 390f);
            Rect toast = new Rect((Screen.width - width) * 0.5f, Screen.height - 72f, width, 40f);
            GUI.color = new Color(1f, 1f, 1f, alpha);
            DrawPremiumPanel(toast, new Color(0.05f, 0.04f, 0.025f, 0.98f), new Color(0.86f, 0.58f, 0.16f, 0.90f));
            GUI.Label(new Rect(toast.x + 10f, toast.y + 8f, toast.width - 20f, 24f), courierToast, new GUIStyle(smallStyle) { fontSize = 10, alignment = TextAnchor.MiddleCenter });
            GUI.color = Color.white;
        }

        private static bool ResearchMatchesFullscreenFilter(string researchId)
        {
            if (researchFullscreenFilter == "all") return true;
            string id = researchId ?? string.Empty;
            if (researchFullscreenFilter == "forage") return id.IndexOf("foraging", StringComparison.OrdinalIgnoreCase) >= 0;
            if (researchFullscreenFilter == "resources") return id.IndexOf("pollen", StringComparison.OrdinalIgnoreCase) >= 0 || id.IndexOf("tempered", StringComparison.OrdinalIgnoreCase) >= 0 || id.IndexOf("sealed", StringComparison.OrdinalIgnoreCase) >= 0;
            if (researchFullscreenFilter == "defense") return id.IndexOf("defense", StringComparison.OrdinalIgnoreCase) >= 0 || id.IndexOf("reserve", StringComparison.OrdinalIgnoreCase) >= 0;
            return true;
        }

        private static void CloseResearchFullscreen()
        {
            activeHiveMenu = HiveMenuMode.Hive;
            activeMainMenuId = string.Empty;
            detailPanelClosed = true;
            AudioManager.Instance?.PlayMenuClose();
        }

