		private static void EnsureChatData()
		{
			if (chatDataInitialized) return;
			chatDataInitialized = true;
			chatChannels = BuildChatChannels();
			chatConversations = BuildChatConversations();
			chatMessagesByConversation = BuildChatMessages();
		}

