		private static Dictionary<string, List<ChatMessageData>> BuildChatMessages()
		{
			Dictionary<string, List<ChatMessageData>> result = new Dictionary<string, List<ChatMessageData>>();
			System.Random rng = new System.Random(1412);
			ChatSeedConversation(result, rng, "alliance-general", ChatAllianceNames, ChatAlliancePresences, ChatGeneralLines, 480, 0.28f);
			ChatSeedConversation(result, rng, "alliance-strategy", ChatAllianceNames, ChatAlliancePresences, ChatStrategyLines, 160, 0.22f);
			ChatSeedConversation(result, rng, "alliance-recruitment", ChatAllianceNames, ChatAlliancePresences, ChatRecruitmentLines, 90, 0.25f);
			ChatSeedConversation(result, rng, "world-1", ChatWorldNames, ChatWorldPresences, ChatWorldLines, 260, 0.18f);
			ChatSeedConversation(result, rng, "world-help", ChatWorldNames, ChatWorldPresences, ChatHelpLines, 130, 0.16f);
			ChatSeedPrivate(result, rng, "pv-marie", "Marie", "hive", 220);
			ChatSeedPrivate(result, rng, "pv-clara", "Clara", "online", 140);
			ChatSeedPrivate(result, rng, "pv-nora", "Nora", "combat", 110);
			ChatSeedPrivate(result, rng, "pv-alex", "Alex", "world", 90);
			ChatSeedPrivate(result, rng, "pv-sophie", "Sophie", "alliance", 70);
			ChatSeedReadOnly(result, rng, "system-news", ChatSystemLines, 180);
			ChatSeedReadOnly(result, rng, "events-activities", ChatEventLines, 140);
			return result;
		}

		private static string ChatSelfName()
		{
			return "Vous";
		}

		private static string ChatSeedTimeLabel(int index, int count)
		{
			int total = index + 1;
			int minute = (total * 13) % 60;
			int hour = 7 + (total * 3) % 14;
			if (hour >= 24) hour -= 24;
			return hour.ToString("00", CultureInfo.InvariantCulture) + ":" + minute.ToString("00", CultureInfo.InvariantCulture);
		}

		private static int ChatSeedState(System.Random rng)
		{
			int roll = rng.Next(100);
			if (roll < 55) return 3;
			if (roll < 80) return 2;
			return 1;
		}

		private static void ChatSeedConversation(Dictionary<string, List<ChatMessageData>> result, System.Random rng, string conversationId, string[] authors, string[] presences, string[] lines, int count, float selfRate)
		{
			List<ChatMessageData> list = new List<ChatMessageData>(count);
			for (int i = 0; i < count; i++)
			{
				bool fromSelf = rng.NextDouble() < selfRate;
				string author = fromSelf ? ChatSelfName() : authors[rng.Next(authors.Length)];
				string presence = fromSelf ? string.Empty : presences[rng.Next(presences.Length)];
				bool pinned = i > 0 && i % 97 == 0;
				list.Add(new ChatMessageData
				{
					Id = "chat-" + conversationId + "-" + i.ToString(CultureInfo.InvariantCulture),
					ConversationId = conversationId,
					FromSelf = fromSelf,
					Author = author,
					Presence = presence,
					AuthorSeed = rng.Next(1000),
					Text = lines[rng.Next(lines.Length)],
					TimeLabel = ChatSeedTimeLabel(i, count),
					State = fromSelf ? ChatSeedState(rng) : 3,
					Pinned = pinned,
					ReactionCount = i % 11 == 0 ? 1 + rng.Next(4) : 0,
					ReactionSelf = false
				});
			}
			result[conversationId] = list;
		}

		private static void ChatSeedPrivate(Dictionary<string, List<ChatMessageData>> result, System.Random rng, string conversationId, string peer, string peerPresence, int count)
		{
			List<ChatMessageData> list = new List<ChatMessageData>(count);
			for (int i = 0; i < count; i++)
			{
				bool fromSelf = i % 3 == 0;
				string author = fromSelf ? ChatSelfName() : peer;
				string presence = fromSelf ? string.Empty : peerPresence;
				list.Add(new ChatMessageData
				{
					Id = "chat-" + conversationId + "-" + i.ToString(CultureInfo.InvariantCulture),
					ConversationId = conversationId,
					FromSelf = fromSelf,
					Author = author,
					Presence = presence,
					AuthorSeed = rng.Next(1000),
					Text = ChatPrivateLines[rng.Next(ChatPrivateLines.Length)],
					TimeLabel = ChatSeedTimeLabel(i, count),
					State = fromSelf ? ChatSeedState(rng) : 3,
					Pinned = false,
					ReactionCount = i % 9 == 0 ? 1 + rng.Next(3) : 0,
					ReactionSelf = false
				});
			}
			result[conversationId] = list;
		}

		private static void ChatSeedReadOnly(Dictionary<string, List<ChatMessageData>> result, System.Random rng, string conversationId, string[] lines, int count)
		{
			List<ChatMessageData> list = new List<ChatMessageData>(count);
			for (int i = 0; i < count; i++)
			{
				list.Add(new ChatMessageData
				{
					Id = "chat-" + conversationId + "-" + i.ToString(CultureInfo.InvariantCulture),
					ConversationId = conversationId,
					FromSelf = false,
					Author = string.Equals(conversationId, "system-news", StringComparison.Ordinal) ? "Système" : "Événements",
					Presence = string.Empty,
					AuthorSeed = 1,
					Text = lines[rng.Next(lines.Length)],
					TimeLabel = ChatSeedTimeLabel(i, count),
					State = 3,
					Pinned = i % 41 == 0,
					ReactionCount = 0,
					ReactionSelf = false
				});
			}
			result[conversationId] = list;
		}

		private static void OpenChatScreen()
		{
			OpenChatScreenTargeted("alliance", "alliance-general", false);
		}

		// Ouverture depuis le mini-chat : le Chat Premium s'ouvre directement sur le canal
		// surveillé (conversation la plus active), directement sur la liste des messages.
		private static void OpenChatScreenForMiniChat()
		{
			string channel = MiniChatResolvedChannel();
			string conversation = MiniChatLatestConversationId(channel);
			OpenChatScreenTargeted(channel, conversation, true);
		}

		private static void OpenChatScreenTargeted(string channelId, string conversationId, bool jumpToMessages)
		{
			EnsureChatData();
			chatScreenOpen = true;
			chatScreenOpenedAt = NowForUi();
			chatSelectedChannel = channelId;
			chatSelectedConversation = conversationId;
			chatMobilePane = jumpToMessages ? "messages" : "channels";
			chatChannelScroll = Vector2.zero;
			chatConversationScroll = Vector2.zero;
			chatMessagesScroll = Vector2.zero;
			chatActionBarScroll = Vector2.zero;
			chatToast = string.Empty;
			chatToastAt = -10f;
			chatSearchActive = false;
			chatSearchQuery = string.Empty;
			chatFavoritesOnly = false;
			chatActionMessageIndex = -1;
			chatEmojiPanelOpen = false;
			chatEmojiCategory = ChatEmojiCatalog.RecentCategoryId;
			ChatMarkRead(chatSelectedConversation);
			AudioManager.Instance?.PlayMenuOpen();
		}

		private static void CloseChatScreen()
		{
			chatScreenOpen = false;
			chatActionMessageIndex = -1;
			chatEmojiPanelOpen = false;
			AudioManager.Instance?.PlayMenuClose();
		}

		private static void ShowChatToast(string message)
		{
			chatToast = message;
			chatToastAt = NowForUi();
		}

		private static int ChatUnreadTotal()
		{
			EnsureChatData();
			int count = 0;
			for (int i = 0; i < chatConversations.Count; i++) count += chatConversations[i].Unread;
			return count;
		}

		private static void ChatMarkRead(string conversationId)
		{
			if (string.IsNullOrEmpty(conversationId)) return;
			for (int i = 0; i < chatConversations.Count; i++)
				if (string.Equals(chatConversations[i].Id, conversationId, StringComparison.Ordinal))
					chatConversations[i].Unread = 0;
		}

		private static List<ChatMessageData> ChatMessagesFor(string conversationId)
		{
			EnsureChatData();
			if (string.IsNullOrEmpty(conversationId)) return new List<ChatMessageData>();
			List<ChatMessageData> list;
			if (chatMessagesByConversation.TryGetValue(conversationId, out list)) return list;
			return new List<ChatMessageData>();
		}

		private static List<ChatConversationData> ChatConversationsFor(string channelId)
		{
			EnsureChatData();
			List<ChatConversationData> result = new List<ChatConversationData>();
			for (int i = 0; i < chatConversations.Count; i++)
			{
				ChatConversationData c = chatConversations[i];
				if (!string.Equals(c.Channel, channelId, StringComparison.Ordinal)) continue;
				if (chatFavoritesOnly && !c.Favorite) continue;
				if (chatSearchActive && !string.IsNullOrWhiteSpace(chatSearchQuery) &&
					c.Title.IndexOf(chatSearchQuery, StringComparison.OrdinalIgnoreCase) < 0) continue;
				result.Add(c);
			}
			return result;
		}

		private static int ChatChannelUnread(string channelId)
		{
			EnsureChatData();
			int count = 0;
			for (int i = 0; i < chatConversations.Count; i++)
				if (string.Equals(chatConversations[i].Channel, channelId, StringComparison.Ordinal))
					count += chatConversations[i].Unread;
			return count;
		}

		private static ChatChannelData ChatChannelById(string channelId)
		{
			EnsureChatData();
			for (int i = 0; i < chatChannels.Count; i++)
				if (string.Equals(chatChannels[i].Id, channelId, StringComparison.Ordinal)) return chatChannels[i];
			return null;
		}

		private static ChatConversationData ChatConversationById(string conversationId)
		{
			EnsureChatData();
			for (int i = 0; i < chatConversations.Count; i++)
				if (string.Equals(chatConversations[i].Id, conversationId, StringComparison.Ordinal)) return chatConversations[i];
			return null;
		}

		private static string ChatPreviewFor(string conversationId)
		{
			List<ChatMessageData> messages = ChatMessagesFor(conversationId);
			if (messages.Count == 0) return string.Empty;
			string text = messages[messages.Count - 1].Text;
			return text.Length <= 34 ? text : text.Substring(0, 34) + "…";
		}

		private static string ChatLastTimeFor(string conversationId)
		{
			List<ChatMessageData> messages = ChatMessagesFor(conversationId);
			return messages.Count == 0 ? string.Empty : messages[messages.Count - 1].TimeLabel;
		}

		private static void ChatSelectChannel(string channelId)
		{
			chatSelectedChannel = channelId;
			List<ChatConversationData> convs = ChatConversationsFor(channelId);
			bool keep = false;
			for (int i = 0; i < convs.Count; i++)
				if (string.Equals(convs[i].Id, chatSelectedConversation, StringComparison.Ordinal)) keep = true;
			chatSelectedConversation = keep ? chatSelectedConversation : (convs.Count > 0 ? convs[0].Id : string.Empty);
			chatConversationScroll = Vector2.zero;
			chatMessagesScroll = Vector2.zero;
			chatActionMessageIndex = -1;
			if (!IsPortraitLayout() || chatMobilePane != "conversations") chatMobilePane = "conversations";
			ChatMarkRead(chatSelectedConversation);
		}

		private static void ChatSelectConversation(string conversationId, bool mobile)
		{
			chatSelectedConversation = conversationId;
			chatMessagesScroll = Vector2.zero;
			chatActionMessageIndex = -1;
			ChatMarkRead(conversationId);
			if (mobile) chatMobilePane = "messages";
		}

		private static void ChatBackOrClose(bool compact)
		{
			if (compact)
			{
				if (string.Equals(chatMobilePane, "messages", StringComparison.Ordinal))
				{
					chatMobilePane = "conversations";
					chatConversationScroll = Vector2.zero;
					return;
				}
				if (string.Equals(chatMobilePane, "conversations", StringComparison.Ordinal))
				{
					chatMobilePane = "channels";
					chatChannelScroll = Vector2.zero;
					return;
				}
			}
			CloseChatScreen();
		}

		private static Rect ChatBackButtonRect()
		{
			return new Rect(4f, 2f, 48f, 48f);
		}

		private static void DrawChatScreen(bool compact)
		{
			if (!chatScreenOpen) return;
			EnsureChatData();
			if (Input.GetKeyDown(KeyCode.Escape))
			{
				CloseChatScreen();
				return;
			}
			Vector2 inputMouse = new Vector2(Input.mousePosition.x, Screen.height - Input.mousePosition.y);
			Rect backHit = ChatBackButtonRect();
			if (Input.GetMouseButtonDown(0) && backHit.Contains(inputMouse))
			{
				ChatBackOrClose(compact);
				return;
			}
			if (Event.current != null && Event.current.type == EventType.MouseDown && backHit.Contains(Event.current.mousePosition))
			{
				ChatBackOrClose(compact);
				Event.current.Use();
				return;
			}
			if (Event.current != null && Event.current.type == EventType.KeyDown && Event.current.keyCode == KeyCode.Escape)
			{
				CloseChatScreen();
				Event.current.Use();
				return;
			}
			ChatSimulationTick();

			float anim = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((NowForUi() - chatScreenOpenedAt) / 0.18f));
			float zoom = Mathf.Lerp(0.97f, 1f, anim);
			Rect full = new Rect(0f, 0f, Screen.width, Screen.height);
			GUI.matrix = Matrix4x4.TRS(full.center, Quaternion.identity, new Vector3(zoom, zoom, 1f)) * Matrix4x4.Translate(-full.center);
			GUI.color = new Color(0.006f, 0.005f, 0.004f, 0.99f * anim);
			GUI.DrawTexture(full, Texture2D.blackTexture, ScaleMode.StretchToFill, false);
			GUI.color = Color.white;

			float bannerHeight = compact ? Mathf.Min(150f, Screen.height * 0.20f) : Mathf.Clamp(Screen.height * 0.20f, 150f, 190f);
			DrawChatBanner(bannerHeight, compact);
			DrawChatTopBar(bannerHeight, compact);
			if (!chatScreenOpen)
			{
				GUI.matrix = Matrix4x4.identity;
				return;
			}

			float quickY = bannerHeight + 6f;
			float quickH = compact ? 56f : 60f;
			float searchH = chatSearchActive ? (compact ? 40f : 42f) : 0f;
			DrawChatActionBar(new Rect(10f, quickY, Screen.width - 20f, quickH), compact);
			float mainTop = quickY + quickH + 6f + searchH;
			Rect main = new Rect(0f, mainTop, Screen.width, Mathf.Max(1f, Screen.height - mainTop));
			DrawChatMainLayout(main, compact);
			DrawChatToast();
			GUI.matrix = Matrix4x4.identity;
		}

		private static void DrawChatBanner(float height, bool compact)
		{
			Rect banner = new Rect(0f, 0f, Screen.width, height);
			Texture2D texture = Resources.Load<Texture2D>("PremiumBeeReference/BuildingBanners/alliance_future_hall");
			if (texture != null) GUI.DrawTexture(banner, texture, ScaleMode.ScaleAndCrop, true);
			else DrawPremiumPanel(banner, new Color(0.14f, 0.085f, 0.025f, 0.98f), new Color(1f, 0.68f, 0.16f, 0.90f));
			GUI.color = new Color(0.01f, 0.008f, 0.004f, 0.50f);
			GUI.DrawTexture(banner, Texture2D.blackTexture, ScaleMode.StretchToFill, true);
			GUI.color = Color.white;
			GUI.Label(new Rect(28f, height - (compact ? 42f : 48f), Screen.width * 0.66f, 26f), "CHAT ROYAL", new GUIStyle(titleStyle) { fontSize = compact ? 20 : 28, fontStyle = FontStyle.Bold });
			GUI.Label(new Rect(30f, height - (compact ? 20f : 23f), Screen.width * 0.72f, 16f), "Le centre de communication de votre royaume", new GUIStyle(smallStyle) { fontSize = compact ? 9 : 12 });
		}

		private static void DrawChatTopBar(float bannerHeight, bool compact)
		{
			GUI.color = new Color(1f, 0.60f, 0.14f, 0.95f);
			GUI.DrawTexture(new Rect(0f, bannerHeight - 1f, Screen.width, 1f), Texture2D.whiteTexture, ScaleMode.StretchToFill, false);
			GUI.color = Color.white;
			if (DrawPremiumBackButton(ChatBackButtonRect()))
			{
				AudioManager.Instance?.PlayUIClick();
				ChatBackOrClose(compact);
			}
			GUI.Label(new Rect(54f, 12f, Screen.width - 220f, 24f), "CHAT", new GUIStyle(badgeStyle) { fontSize = 11 });
			Rect badge = new Rect(Screen.width - 158f, 10f, 96f, 28f);
			DrawPremiumPanel(badge, new Color(0.05f, 0.04f, 0.025f, 0.96f), new Color(0.86f, 0.58f, 0.16f, 0.85f));
			int unread = ChatUnreadTotal();
			GUI.Label(badge, unread > 0 ? unread.ToString(CultureInfo.InvariantCulture) + " NON LUS" : "À JOUR", new GUIStyle(centeredTinyLabelStyle) { fontSize = 8 });
		}

		private static void DrawChatActionBar(Rect rect, bool compact)
		{
			string[] ids = { "new", "group", "search", "favorites", "settings" };
			string[] labels = { "➕ Nouvelle discussion", "👥 Nouveau groupe", "🔍 Recherche", "⭐ Favoris", "⚙ Paramètres" };
			string[] icons = { "messages", "members", "search", "star", "locked" };
			float gap = 6f;
			float itemWidth = compact ? 122f : Mathf.Max(122f, (rect.width - gap * 4f) / 5f);
			DrawPremiumPanel(rect, new Color(0.025f, 0.022f, 0.017f, 0.98f), new Color(0.82f, 0.54f, 0.14f, 0.84f));
			chatActionBarScroll = GUI.BeginScrollView(rect, chatActionBarScroll, new Rect(0f, 0f, itemWidth * 5f + gap * 4f + 8f, rect.height - 2f), false, false);
			for (int i = 0; i < ids.Length; i++)
			{
				Rect button = new Rect(4f + i * (itemWidth + gap), 6f, itemWidth, rect.height - 12f);
				bool on = (string.Equals(ids[i], "search", StringComparison.Ordinal) && chatSearchActive)
					|| (string.Equals(ids[i], "favorites", StringComparison.Ordinal) && chatFavoritesOnly);
				DrawPremiumPanel(button, on ? new Color(0.30f, 0.20f, 0.06f, 0.96f) : new Color(0.06f, 0.045f, 0.025f, 0.94f), on ? new Color(1f, 0.70f, 0.18f, 0.92f) : new Color(0.64f, 0.44f, 0.14f, 0.64f));
				DrawGameIcon(new Rect(button.x + 8f, button.y + 8f, 24f, 24f), icons[i], Color.white);
				GUI.Label(new Rect(button.x + 38f, button.y + 7f, button.width - 44f, 28f), labels[i], new GUIStyle(smallStyle) { fontSize = compact ? 8 : 9, alignment = TextAnchor.MiddleLeft });
				if (GUI.Button(button, string.Empty, GUIStyle.none))
				{
					AudioManager.Instance?.PlayUIClick();
					if (string.Equals(ids[i], "new", StringComparison.Ordinal))
					{
						chatSelectedChannel = "private";
						chatFavoritesOnly = false;
						chatSearchActive = true;
						chatSearchQuery = string.Empty;
						if (compact) chatMobilePane = "conversations";
						ShowChatToast("Nouvelle discussion : utilisez la recherche pour trouver un joueur (placeholder).");
					}
					else if (string.Equals(ids[i], "group", StringComparison.Ordinal)) ShowChatToast("La création de groupes arrive à un prochain sprint.");
					else if (string.Equals(ids[i], "search", StringComparison.Ordinal))
					{
						chatSearchActive = !chatSearchActive;
						if (!chatSearchActive) chatSearchQuery = string.Empty;
					}
					else if (string.Equals(ids[i], "favorites", StringComparison.Ordinal)) chatFavoritesOnly = !chatFavoritesOnly;
					else ShowChatToast("Les paramètres du chat arrivent à un prochain sprint.");
				}
			}
			GUI.EndScrollView();
			if (chatSearchActive)
			{
				Rect searchRect = new Rect(rect.x + 4f, rect.y + rect.height + 4f, rect.width - 8f, compact ? 34f : 36f);
				DrawPremiumPanel(searchRect, new Color(0.04f, 0.032f, 0.022f, 0.96f), new Color(0.70f, 0.46f, 0.14f, 0.70f));
				GUI.SetNextControlName("chatSearch");
				chatSearchQuery = GUI.TextField(new Rect(searchRect.x + 10f, searchRect.y + 5f, searchRect.width - 66f, searchRect.height - 10f), chatSearchQuery, new GUIStyle(smallStyle) { fontSize = compact ? 10 : 12, normal = { textColor = new Color(1f, 0.92f, 0.74f, 1f) } });
				if (GUI.Button(new Rect(searchRect.xMax - 54f, searchRect.y + 4f, 46f, searchRect.height - 8f), "Effacer"))
				{
					chatSearchQuery = string.Empty;
				}
			}
		}

		private static void DrawChatMainLayout(Rect main, bool compact)
		{
			if (compact)
			{
				if (string.Equals(chatMobilePane, "channels", StringComparison.Ordinal)) DrawChatChannelsPane(new Rect(0f, main.y, Screen.width, main.height), true);
				else if (string.Equals(chatMobilePane, "conversations", StringComparison.Ordinal)) DrawChatConversationsPane(new Rect(0f, main.y, Screen.width, main.height), true);
				else DrawChatMessagesPane(new Rect(0f, main.y, Screen.width, main.height), true);
				return;
			}

			float gap = 8f;
			float channelW = 216f;
			float convW = 284f;
			float x = main.x + 10f;
			float totalW = main.width - 20f - gap * 2f;
			DrawChatChannelsPane(new Rect(x, main.y + 6f, channelW, main.height - 12f), false);
			DrawChatConversationsPane(new Rect(x + channelW + gap, main.y + 6f, convW, main.height - 12f), false);
			DrawChatMessagesPane(new Rect(x + channelW + gap + convW + gap, main.y + 6f, totalW - channelW - convW - gap * 2f, main.height - 12f), false);
		}

		private static void DrawChatChannelsPane(Rect area, bool mobile)
		{
			EnsureChatData();
			DrawPremiumPanel(area, new Color(0.024f, 0.021f, 0.017f, 0.97f), new Color(0.78f, 0.52f, 0.15f, 0.70f));
			float headerH = 40f;
			GUI.Label(new Rect(area.x + 10f, area.y + 8f, area.width - 20f, 26f), mobile ? "Canaux" : "CANAUX", new GUIStyle(badgeStyle) { fontSize = 11 });
			GUI.color = new Color(1f, 0.60f, 0.14f, 0.80f);
			GUI.DrawTexture(new Rect(area.x + 10f, area.y + headerH - 2f, area.width - 20f, 1f), Texture2D.whiteTexture, ScaleMode.StretchToFill, false);
			GUI.color = Color.white;
			Rect viewport = new Rect(area.x + 8f, area.y + headerH + 2f, area.width - 16f, area.height - headerH - 10f);
			float rowH = 58f;
			float contentH = chatChannels.Count * rowH + (chatChannels.Count - 1) * ChatMessageGap;
			chatChannelScroll = GUI.BeginScrollView(viewport, chatChannelScroll, new Rect(0f, 0f, viewport.width, Mathf.Max(viewport.height, contentH)), false, true);
			for (int i = 0; i < chatChannels.Count; i++)
			{
				ChatChannelData channel = chatChannels[i];
				Rect row = new Rect(0f, i * (rowH + ChatMessageGap), viewport.width, rowH);
				bool selected = string.Equals(channel.Id, chatSelectedChannel, StringComparison.Ordinal);
				DrawPremiumPanel(row, selected ? new Color(0.30f, 0.20f, 0.06f, 0.96f) : new Color(0.05f, 0.040f, 0.026f, 0.90f), selected ? new Color(1f, 0.70f, 0.18f, 0.90f) : new Color(0.55f, 0.40f, 0.15f, 0.55f));
				DrawGameIcon(new Rect(row.x + 10f, row.y + 12f, 34f, 34f), channel.Icon, Color.white);
				GUI.Label(new Rect(row.x + 52f, row.y + 9f, row.width - 112f, 22f), channel.Name, new GUIStyle(badgeStyle) { fontSize = mobile ? 13 : 12, alignment = TextAnchor.MiddleLeft });
				GUI.Label(new Rect(row.x + 52f, row.y + 33f, row.width - 112f, 14f), channel.ReadOnly ? "Lecture seule" : "Discussion", new GUIStyle(tinyLabelStyle) { fontSize = 8, alignment = TextAnchor.MiddleLeft, normal = { textColor = new Color(1f, 0.82f, 0.42f, 1f) } });
				int chUnread = ChatChannelUnread(channel.Id);
				if (chUnread > 0)
				{
					Rect badge = new Rect(row.xMax - 44f, row.y + 17f, 34f, 22f);
					DrawPremiumPanel(badge, new Color(0.72f, 0.12f, 0.06f, 0.96f), new Color(1f, 0.62f, 0.20f, 0.92f));
					GUI.Label(badge, chUnread > 9 ? "9+" : chUnread.ToString(CultureInfo.InvariantCulture), centeredTinyLabelStyle);
				}
				if (GUI.Button(row, string.Empty, GUIStyle.none))
				{
					AudioManager.Instance?.PlayUIClick();
					ChatSelectChannel(channel.Id);
				}
			}
			GUI.EndScrollView();
		}

		private static void DrawChatConversationsPane(Rect area, bool mobile)
		{
			EnsureChatData();
			DrawPremiumPanel(area, new Color(0.024f, 0.021f, 0.017f, 0.97f), new Color(0.78f, 0.52f, 0.15f, 0.70f));
			ChatChannelData channel = ChatChannelById(chatSelectedChannel);
			float headerH = 40f;
			GUI.Label(new Rect(area.x + 10f, area.y + 6f, area.width - 20f, 22f), mobile ? "Discussions" : "DISCUSSIONS", new GUIStyle(badgeStyle) { fontSize = 11 });
			GUI.Label(new Rect(area.x + 10f, area.y + 26f, area.width - 20f, 14f), channel != null ? channel.Name : string.Empty, new GUIStyle(tinyLabelStyle) { fontSize = 8, normal = { textColor = new Color(1f, 0.82f, 0.42f, 1f) } });
			GUI.color = new Color(1f, 0.60f, 0.14f, 0.80f);
			GUI.DrawTexture(new Rect(area.x + 10f, area.y + headerH - 2f, area.width - 20f, 1f), Texture2D.whiteTexture, ScaleMode.StretchToFill, false);
			GUI.color = Color.white;
			List<ChatConversationData> convs = ChatConversationsFor(chatSelectedChannel);
			Rect viewport = new Rect(area.x + 8f, area.y + headerH + 2f, area.width - 16f, area.height - headerH - 10f);
			float rowH = 64f;
			float contentH = convs.Count * rowH + (convs.Count - 1) * ChatMessageGap;
			chatConversationScroll = GUI.BeginScrollView(viewport, chatConversationScroll, new Rect(0f, 0f, viewport.width, Mathf.Max(viewport.height, contentH)), false, true);
			for (int i = 0; i < convs.Count; i++)
			{
				ChatConversationData conv = convs[i];
				Rect row = new Rect(0f, i * (rowH + ChatMessageGap), viewport.width, rowH);
				bool selected = string.Equals(conv.Id, chatSelectedConversation, StringComparison.Ordinal);
				DrawPremiumPanel(row, selected ? new Color(0.30f, 0.20f, 0.06f, 0.96f) : new Color(0.05f, 0.040f, 0.026f, 0.90f), selected ? new Color(1f, 0.70f, 0.18f, 0.90f) : new Color(0.55f, 0.40f, 0.15f, 0.55f));
				float avatarSize = mobile ? 44f : 42f;
				Rect avatarRect = new Rect(row.x + 8f, row.y + (rowH - avatarSize) * 0.5f, avatarSize, avatarSize);
				DrawChatAvatar(avatarRect, conv);
				float textX = avatarRect.xMax + 10f;
				float rightW = 70f;
				float textW = row.width - textX - rightW - 8f;
				GUI.Label(new Rect(textX, row.y + 7f, textW, 18f), conv.Title + (conv.Favorite ? "  ★" : string.Empty), new GUIStyle(badgeStyle) { fontSize = mobile ? 13 : 12, alignment = TextAnchor.MiddleLeft });
				GUI.Label(new Rect(textX, row.y + 28f, textW, 14f), ChatPreviewFor(conv.Id), new GUIStyle(tinyLabelStyle) { fontSize = 8, alignment = TextAnchor.MiddleLeft, clipping = TextClipping.Clip });
				GUI.Label(new Rect(row.x + row.width - rightW + 6f, row.y + 8f, rightW - 12f, 14f), ChatLastTimeFor(conv.Id), new GUIStyle(tinyLabelStyle) { fontSize = 7, alignment = TextAnchor.MiddleRight, normal = { textColor = new Color(1f, 0.82f, 0.42f, 1f) } });
				if (conv.Unread > 0)
				{
					Rect badge = new Rect(row.x + row.width - rightW + 12f, row.y + 25f, 34f, 20f);
					DrawPremiumPanel(badge, new Color(0.72f, 0.12f, 0.06f, 0.96f), new Color(1f, 0.62f, 0.20f, 0.92f));
					GUI.Label(badge, conv.Unread > 9 ? "9+" : conv.Unread.ToString(CultureInfo.InvariantCulture), centeredTinyLabelStyle);
				}
				if (GUI.Button(row, string.Empty, GUIStyle.none))
				{
					AudioManager.Instance?.PlayUIClick();
					ChatSelectConversation(conv.Id, mobile);
				}
			}
			GUI.EndScrollView();
		}

		private static string ChatConversationSubtitle(ChatConversationData conv)
		{
			if (conv.ReadOnly) return "Lecture seule · messages automatiques";
			if (!string.IsNullOrEmpty(conv.Presence)) return AlliancePresenceLabel(conv.Presence);
			return "Discussion de groupe";
		}

		private static void DrawChatMessagesPane(Rect area, bool compact)
		{
			EnsureChatData();
			DrawPremiumPanel(area, new Color(0.020f, 0.017f, 0.014f, 0.98f), new Color(0.72f, 0.48f, 0.14f, 0.70f));
			ChatConversationData conv = ChatConversationById(chatSelectedConversation);
			string title = conv != null ? conv.Title : "Discussion";
			string subtitle = conv != null ? ChatConversationSubtitle(conv) : string.Empty;
			float headerH = compact ? 44f : 40f;
			GUI.Label(new Rect(area.x + 10f, area.y + 6f, area.width - 20f, 22f), title, new GUIStyle(badgeStyle) { fontSize = compact ? 14 : 13, alignment = TextAnchor.MiddleLeft });
			GUI.Label(new Rect(area.x + 10f, area.y + 27f, area.width - 20f, 14f), subtitle, new GUIStyle(tinyLabelStyle) { fontSize = 8, alignment = TextAnchor.MiddleLeft, normal = { textColor = new Color(1f, 0.82f, 0.42f, 1f) } });
			GUI.color = new Color(1f, 0.60f, 0.14f, 0.80f);
			GUI.DrawTexture(new Rect(area.x + 10f, area.y + headerH - 2f, area.width - 20f, 1f), Texture2D.whiteTexture, ScaleMode.StretchToFill, false);
			GUI.color = Color.white;

			bool readOnly = conv == null || conv.ReadOnly;
			float composerH = readOnly ? 30f : (compact ? 58f : 54f);
			Rect viewport = new Rect(area.x + 8f, area.y + headerH + 2f, area.width - 16f, Mathf.Max(1f, area.height - headerH - 6f - composerH));
			// M043T-CL: the emoji panel (opened from inside DrawChatComposer below) is drawn
			// directly above the composer, overlapping the tail of this message scroll view - its
			// message-action buttons (react/copy/pin/report) must not stay clickable underneath.
			// The composer itself stays outside this gate so its own emoji toggle keeps working.
			DrawUnderOwnOverlayGate(chatEmojiPanelOpen, () => DrawVirtualChatMessages(viewport, chatSelectedConversation, compact));
			if (readOnly)
			{
				chatEmojiPanelOpen = false;
				GUI.Label(new Rect(area.x + 10f, area.y + area.height - composerH + 5f, area.width - 20f, 20f), conv == null ? "Sélectionnez une discussion." : "Cette conversation est en lecture seule.", new GUIStyle(centeredTinyLabelStyle) { fontSize = 9, normal = { textColor = new Color(1f, 0.82f, 0.42f, 1f) } });
			}
			else
			{
				DrawChatComposer(new Rect(area.x + 8f, area.y + area.height - composerH, area.width - 16f, composerH - 4f), compact);
			}
		}

		private static void DrawChatComposer(Rect rect, bool compact)
		{
			DrawPremiumPanel(rect, new Color(0.028f, 0.024f, 0.018f, 0.98f), new Color(0.78f, 0.52f, 0.15f, 0.75f));
			if (Event.current != null && Event.current.type == EventType.KeyDown && !Event.current.alt && !Event.current.shift && (Event.current.control || Event.current.command) && Event.current.keyCode == KeyCode.E)
			{
				ChatEmojiToggle();
				Event.current.Use();
				return;
			}
			GUIStyle fieldStyle = new GUIStyle(smallStyle) { fontSize = compact ? 11 : 13, alignment = TextAnchor.MiddleLeft, normal = { textColor = new Color(1f, 0.92f, 0.74f, 1f) } };
			float emojiW = compact ? 40f : 36f;
			Rect textRect = new Rect(rect.x + 10f, rect.y + 6f, rect.width - 96f - emojiW - 8f, rect.height - 12f);
			GUI.SetNextControlName("chatComposer");
			chatComposerText = GUI.TextField(textRect, chatComposerText, fieldStyle);
			Rect emojiButton = new Rect(rect.xMax - 82f - emojiW - 8f, rect.y + 6f, emojiW, rect.height - 12f);
			DrawPremiumPanel(emojiButton, chatEmojiPanelOpen ? new Color(0.30f, 0.20f, 0.06f, 0.96f) : new Color(0.06f, 0.045f, 0.025f, 0.94f), new Color(0.64f, 0.44f, 0.14f, 0.64f));
			GUI.Label(emojiButton, "😊", new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 17 : 15 });
			if (GUI.Button(emojiButton, string.Empty, GUIStyle.none))
			{
				AudioManager.Instance?.PlayUIClick();
				ChatEmojiToggle();
			}
			if (GUI.Button(new Rect(rect.xMax - 82f, rect.y + 6f, 72f, rect.height - 12f), "Envoyer"))
			{
				ChatSendCurrent();
			}
			if (Event.current != null && Event.current.isKey && Event.current.type == EventType.KeyDown && (Event.current.keyCode == KeyCode.Return || Event.current.keyCode == KeyCode.KeypadEnter) && string.Equals(GUI.GetNameOfFocusedControl(), "chatComposer", StringComparison.Ordinal))
			{
				ChatSendCurrent();
				Event.current.Use();
			}
			ChatEmojiPanelUpdate(rect, compact, emojiButton);
		}

		// Panneau d'emoticones (Sprint-014) : composant UI du jeu, aucune fenêtre système.
		// S'ouvre via le bouton 😊 ou Ctrl+E (PC), se ferme a la selection d'une emoticone
		// ou au clic hors du panneau. La grille reste utilisable au pouce en compact.
		private static void ChatEmojiToggle()
		{
			chatEmojiPanelOpen = !chatEmojiPanelOpen;
			if (chatEmojiPanelOpen) chatEmojiCategory = ChatEmojiCatalog.RecentCategoryId;
		}

		private static void ChatEmojiPanelUpdate(Rect composer, bool compact, Rect toggleButton)
		{
			if (!chatEmojiPanelOpen) return;
			Rect panel = ChatEmojiPanelRect(composer);
			if (Input.GetMouseButtonDown(0))
			{
				Vector2 mouse = new Vector2(Input.mousePosition.x, Screen.height - Input.mousePosition.y);
				if (!panel.Contains(mouse) && !toggleButton.Contains(mouse))
				{
					chatEmojiPanelOpen = false;
					return;
				}
			}
			DrawChatEmojiPanel(panel, compact);
		}

		private static Rect ChatEmojiPanelRect(Rect composer)
		{
			float height = Mathf.Clamp(Screen.height * 0.30f, 150f, 236f);
			return new Rect(composer.x, composer.y - height - 6f, composer.width, height);
		}

		private static void DrawChatEmojiPanel(Rect panel, bool compact)
		{
			DrawPremiumPanel(panel, new Color(0.024f, 0.021f, 0.017f, 0.99f), new Color(0.82f, 0.54f, 0.14f, 0.84f));
			string[] tabIds = ChatEmojiTabOrder();
			float tabH = compact ? 40f : 34f;
			float tabW = panel.width / tabIds.Length;
			for (int i = 0; i < tabIds.Length; i++)
			{
				bool selected = string.Equals(chatEmojiCategory, tabIds[i], StringComparison.Ordinal);
				Rect tab = new Rect(panel.x + i * tabW, panel.y, tabW, tabH);
				DrawPremiumPanel(tab, selected ? new Color(0.30f, 0.20f, 0.06f, 0.96f) : new Color(0.05f, 0.040f, 0.026f, 0.92f), selected ? new Color(1f, 0.70f, 0.18f, 0.90f) : new Color(0.55f, 0.40f, 0.15f, 0.55f));
				GUI.Label(new Rect(tab.x + 2f, tab.y, tabW - 4f, tabH), compact ? ChatEmojiTabLabelCompact(tabIds[i]) : ChatEmojiTabLabel(tabIds[i]), new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 14 : 10 });
				if (GUI.Button(tab, string.Empty, GUIStyle.none))
				{
					AudioManager.Instance?.PlayUIClick();
					chatEmojiCategory = tabIds[i];
				}
			}
			List<string> emojis = ChatEmojiEmojisFor(chatEmojiCategory);
			if (emojis.Count == 0)
			{
				GUI.Label(
					new Rect(panel.x + 12f, panel.y + tabH + 14f, panel.width - 24f, 40f),
					ChatEmojiEmptyText(chatEmojiCategory),
					new GUIStyle(centeredTinyLabelStyle) { fontSize = 10, normal = { textColor = new Color(1f, 0.82f, 0.42f, 1f) } });
				return;
			}
			Rect grid = new Rect(panel.x + 6f, panel.y + tabH + 6f, panel.width - 12f, panel.height - tabH - 12f);
			float targetCell = compact ? 40f : 36f;
			int cols = Mathf.Max(1, Mathf.FloorToInt(grid.width / targetCell));
			int rows = Mathf.Max(1, Mathf.FloorToInt(grid.height / targetCell));
			float cellW = grid.width / cols;
			float cellH = grid.height / rows;
			int visible = cols * rows;
			for (int i = 0; i < emojis.Count && i < visible; i++)
			{
				Rect cellRect = new Rect(grid.x + (i % cols) * cellW, grid.y + (i / cols) * cellH, cellW, cellH);
				DrawPremiumPanel(new Rect(cellRect.x + 3f, cellRect.y + 3f, cellRect.width - 6f, cellRect.height - 6f), new Color(0.06f, 0.045f, 0.026f, 0.92f), new Color(0.55f, 0.40f, 0.15f, 0.40f));
				if (GUI.Button(cellRect, emojis[i], new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 20 : 18 }))
				{
					ChatEmojiInsert(emojis[i]);
					return;
				}
			}
		}

