		private static string ChatEmojiEmptyText(string categoryId)
		{
			if (string.Equals(categoryId, ChatEmojiCatalog.RecentCategoryId, StringComparison.Ordinal))
				return BeeLocalization.Text("chat.emoji.recents.empty", "Vos émoticônes récentes apparaîtront ici.");
			return BeeLocalization.Text("chat.emoji.beekingdom.empty", "Les émoticônes exclusives BeeKingdom arrivent bientôt.");
		}

		private static List<string> ChatEmojiEmojisFor(string categoryId)
		{
			if (string.Equals(categoryId, ChatEmojiCatalog.RecentCategoryId, StringComparison.Ordinal)) return new List<string>(chatEmojiRecents);
			ChatEmojiCategory category = ChatEmojiCatalog.CategoryById(categoryId);
			if (category == null) return new List<string>();
			List<string> values = new List<string>(category.Items.Count);
			for (int i = 0; i < category.Items.Count; i++)
				if (category.Items[i].Kind == ChatEmojiKind.Emoji) values.Add(category.Items[i].Value);
			return values;
		}

		// Insertion a la position du curseur : le champ de texte conserve son focus (les
		// boutons IMGUI sont passifs) et le caret passe juste apres l'emoticone inseree.
		private static void ChatEmojiInsert(string emoji)
		{
			int caret = chatComposerText.Length;
			TextEditor editor = null;
			if (string.Equals(GUI.GetNameOfFocusedControl(), "chatComposer", StringComparison.Ordinal) && GUIUtility.keyboardControl != 0)
			{
				editor = (TextEditor)GUIUtility.GetStateObject(typeof(TextEditor), GUIUtility.keyboardControl);
				if (editor != null && editor.cursorIndex >= 0 && editor.cursorIndex <= chatComposerText.Length) caret = editor.cursorIndex;
			}
			chatComposerText = ChatEmojiBuildDraft(chatComposerText, caret, emoji);
			if (editor != null)
			{
				editor.cursorIndex = Mathf.Min(chatComposerText.Length, caret + emoji.Length);
				editor.selectIndex = editor.cursorIndex;
			}
			ChatEmojiPushRecent(emoji);
			chatEmojiPanelOpen = false;
			AudioManager.Instance?.PlayUIClick();
		}

		private static string ChatEmojiBuildDraft(string draft, int caret, string emoji)
		{
			if (string.IsNullOrEmpty(emoji)) return draft ?? string.Empty;
			string text = draft ?? string.Empty;
			int index = Mathf.Clamp(caret, 0, text.Length);
			return text.Substring(0, index) + emoji + text.Substring(index);
		}

		private static void ChatEmojiPushRecent(string emoji)
		{
			if (string.IsNullOrEmpty(emoji)) return;
			List<string> updated = ChatEmojiWithRecent(chatEmojiRecents, emoji, ChatEmojiCatalog.RecentMax);
			bool changed = updated.Count != chatEmojiRecents.Count || !ChatEmojiListsEqual(updated, chatEmojiRecents);
			chatEmojiRecents = updated;
			if (changed) ChatEmojiPersistRecents();
		}

		private static List<string> ChatEmojiWithRecent(List<string> current, string emoji, int max)
		{
			List<string> result = new List<string>(current);
			result.RemoveAll(delegate (string e) { return string.Equals(e, emoji, StringComparison.Ordinal); });
			result.Insert(0, emoji);
			if (result.Count > max) result.RemoveRange(max, result.Count - max);
			return result;
		}

		private static bool ChatEmojiListsEqual(List<string> a, List<string> b)
		{
			if (a.Count != b.Count) return false;
			for (int i = 0; i < a.Count; i++)
				if (!string.Equals(a[i], b[i], StringComparison.Ordinal)) return false;
			return true;
		}

		private static void ChatEmojiPersistRecents()
		{
			EnsureMobileComfortPreferencesLoaded();
			string joined = string.Join("|", chatEmojiRecents.ToArray());
			if (string.Equals(mobileComfortPreferences.chatEmojiRecents, joined, StringComparison.Ordinal)) return;
			mobileComfortPreferences.chatEmojiRecents = joined;
			mobileComfortPreferences.revision = Math.Max(0, mobileComfortPreferences.revision) + 1;
			PersistMobileComfortPreferences();
		}

		private static List<string> ChatEmojiParseRecents(string joined)
		{
			List<string> result = new List<string>();
			if (string.IsNullOrEmpty(joined)) return result;
			string[] parts = joined.Split('|');
			for (int i = 0; i < parts.Length && result.Count < ChatEmojiCatalog.RecentMax; i++)
			{
				string entry = parts[i].Trim();
				if (string.IsNullOrEmpty(entry)) continue;
				bool duplicate = false;
				for (int j = 0; j < result.Count; j++)
					if (string.Equals(result[j], entry, StringComparison.Ordinal)) { duplicate = true; break; }
				if (!duplicate) result.Add(entry);
			}
			return result;
		}

		private static string ChatNowTimeLabel()
		{
			return DateTime.Now.ToString("HH:mm", CultureInfo.InvariantCulture);
		}

		private static void ChatSendCurrent()
		{
			string text = chatComposerText.Trim();
			if (string.IsNullOrEmpty(text)) return;
			List<ChatMessageData> list = ChatMessagesFor(chatSelectedConversation);
			ChatMessageData msg = new ChatMessageData
			{
				Id = "chat-user-" + NowForUi().ToString(CultureInfo.InvariantCulture),
				ConversationId = chatSelectedConversation,
				FromSelf = true,
				Author = ChatSelfName(),
				Presence = string.Empty,
				AuthorSeed = 0,
				Text = text,
				TimeLabel = ChatNowTimeLabel(),
				State = 1,
				Pinned = false,
				ReactionCount = 0,
				ReactionSelf = false
			};
			list.Add(msg);
			chatComposerText = string.Empty;
			chatMessagesScroll.y = float.MaxValue;
		}

		private static void ChatSimulationTick(bool allowWhileChatClosed = false)
		{
			if (!chatScreenOpen && !allowWhileChatClosed) return;
			float now = NowForUi();
			if (now < chatSimulationNextAt) return;
			chatSimulationNextAt = now + 16f + (float)(now % 11f);
			EnsureChatData();
			List<ChatConversationData> candidates = new List<ChatConversationData>();
			for (int i = 0; i < chatConversations.Count; i++)
			{
				ChatConversationData c = chatConversations[i];
				if (c.ReadOnly) continue;
				if (string.Equals(c.Id, chatSelectedConversation, StringComparison.Ordinal)) continue;
				candidates.Add(c);
			}
			if (candidates.Count == 0) return;
			ChatConversationData target = candidates[chatSimulationRng.Next(candidates.Count)];
			List<ChatMessageData> list = ChatMessagesFor(target.Id);
			string[] authors = string.Equals(target.Channel, "world", StringComparison.Ordinal) ? ChatWorldNames : ChatAllianceNames;
			string[] presences = string.Equals(target.Channel, "world", StringComparison.Ordinal) ? ChatWorldPresences : ChatAlliancePresences;
			string author = string.Equals(target.Channel, "private", StringComparison.Ordinal) ? target.Peer : authors[chatSimulationRng.Next(authors.Length)];
			string presence = string.Equals(target.Channel, "private", StringComparison.Ordinal) ? target.Presence : presences[chatSimulationRng.Next(presences.Length)];
			string[] pool = string.Equals(target.Channel, "private", StringComparison.Ordinal) ? ChatPrivateLines : (string.Equals(target.Channel, "world", StringComparison.Ordinal) ? ChatWorldLines : ChatGeneralLines);
			ChatMessageData msg = new ChatMessageData
			{
				Id = "chat-live-" + now.ToString(CultureInfo.InvariantCulture),
				ConversationId = target.Id,
				FromSelf = false,
				Author = author,
				Presence = presence,
				AuthorSeed = chatSimulationRng.Next(1000),
				Text = pool[chatSimulationRng.Next(pool.Length)],
				TimeLabel = ChatNowTimeLabel(),
				State = 3,
				Pinned = false,
				ReactionCount = 0,
				ReactionSelf = false
			};
			list.Add(msg);
			target.Unread += 1;
		}

		private static void DrawVirtualChatMessages(Rect viewport, string conversationId, bool compact)
		{
			List<ChatMessageData> messages = ChatMessagesFor(conversationId);
			int count = messages.Count;
			if (count == 0)
			{
				GUI.Label(new Rect(viewport.x + 20f, viewport.y + 20f, viewport.width - 40f, 60f), "Aucun message pour le moment.", new GUIStyle(centeredTinyLabelStyle) { fontSize = 10 });
				return;
			}
			EnsureChatHeights(conversationId, viewport.width, compact);
			float total = ChatTotalHeight(count);
			chatMessagesScroll = GUI.BeginScrollView(viewport, chatMessagesScroll, new Rect(0f, 0f, viewport.width, Mathf.Max(viewport.height, total)), false, true);

			int start;
			int end;
			ChatComputeVisibleRange(chatMessagesScroll.y, viewport.height, count, out start, out end);
			float y = ChatCumulativeHeight(start);
			for (int i = start; i < end; i++)
			{
				ChatMessageData msg = messages[i];
				float rowH = ChatRowHeight(i);
				Rect row = new Rect(4f, y, viewport.width - 8f, rowH);
				Rect screenRow = new Rect(viewport.x + 4f, viewport.y + y - chatMessagesScroll.y, viewport.width - 8f, rowH);
				bool hovered = screenRow.Contains(Event.current.mousePosition);
				if (Event.current != null && Event.current.type == EventType.MouseDown && Event.current.button == 0 && hovered)
				{
					chatActionMessageIndex = chatActionMessageIndex == i ? -1 : i;
				}
				bool actionsVisible = hovered || chatActionMessageIndex == i;
				DrawChatMessageRow(row, msg, i, compact, actionsVisible);
				y += rowH + ChatMessageGap;
			}
			GUI.EndScrollView();
		}

		private static void DrawChatMessageRow(Rect row, ChatMessageData msg, int index, bool compact, bool actionsVisible)
		{
			float bubbleH = row.height - (actionsVisible ? ChatActionStripHeight : 0f);
			Rect bubbleArea = new Rect(row.x, row.y, row.width, Mathf.Max(1f, bubbleH));
			bool isSelf = msg.FromSelf;
			float avatarSize = compact ? 34f : 38f;
			float pad = compact ? 8f : 10f;

			if (msg.Pinned)
			{
				GUI.Label(new Rect(row.x + (isSelf ? row.xMax - row.x - 26f : 4f), row.y, 22f, 16f), "📌", ChatPinnedStyle());
			}

			if (isSelf)
			{
				float textW = row.width - 2f * pad;
				float bubbleW = Mathf.Min(textW, row.width * 0.78f);
				Rect bubbleRect = new Rect(row.xMax - bubbleW - pad, bubbleArea.y + 2f, bubbleW, bubbleArea.height - 4f);
				DrawChatBubble(bubbleRect, true);
				float innerW = bubbleRect.width - 16f;
				float textH = ChatBubbleTextHeight(msg.Text, innerW, compact);
				GUI.Label(new Rect(bubbleRect.x + 8f, bubbleRect.y + 4f, innerW, textH), msg.Text, ChatBubbleTextStyle(compact));
				GUI.Label(new Rect(bubbleRect.xMax - 48f, bubbleRect.yMax - 16f, 42f, 13f), ChatStateText(msg.State), ChatStateStyle(msg.State));
			}
			else
			{
				Rect avatarRect = new Rect(row.x + pad, bubbleArea.y + 2f, avatarSize, avatarSize);
				DrawChatAvatar(avatarRect, msg);
				float textX = avatarRect.xMax + pad;
				float bubbleW = Mathf.Min(row.xMax - textX - 4f, row.width * 0.78f);
				Rect bubbleRect = new Rect(textX, bubbleArea.y + 2f, bubbleW, bubbleArea.height - 4f);
				DrawChatBubble(bubbleRect, false);
				float innerW = bubbleRect.width - 20f;
				float nameH = compact ? 13f : 15f;
				float textH = ChatBubbleTextHeight(msg.Text, innerW, compact);
				GUI.Label(new Rect(bubbleRect.x + 10f, bubbleRect.y + 3f, innerW, nameH), msg.Author, ChatAuthorStyle(compact));
				GUI.Label(new Rect(bubbleRect.x + 10f, bubbleRect.y + 3f + nameH, innerW, textH), msg.Text, ChatBubbleTextStyle(compact));
				GUI.Label(new Rect(bubbleRect.x + 10f, bubbleRect.yMax - 15f, innerW, 12f), msg.TimeLabel, ChatTimeStyle());
			}

			if (actionsVisible)
			{
				DrawChatMessageActions(new Rect(row.x, row.yMax - ChatActionStripHeight, row.width, ChatActionStripHeight), msg, index, compact);
			}
		}

		private static void DrawChatMessageActions(Rect strip, ChatMessageData msg, int index, bool compact)
		{
			string[] ids = ChatActionIds;
			string[] labels = chatActionLabelsCache;
			labels[0] = msg.ReactionSelf ? "❤️ Réagir" : "🤍 Réagir";
			labels[1] = "📋 Copier";
			labels[2] = msg.Pinned ? "📌 Dépinner" : "📌 Épingler";
			labels[3] = "🚩 Signaler";
			float gap = 6f;
			float width = (strip.width - gap * 3f) / 4f;
			for (int i = 0; i < ids.Length; i++)
			{
				Rect button = new Rect(strip.x + i * (width + gap), strip.y, width, strip.height);
				DrawPremiumPanel(button, new Color(0.06f, 0.048f, 0.028f, 0.96f), new Color(0.70f, 0.50f, 0.16f, 0.70f));
				GUI.Label(button, labels[i], ChatActionLabelStyle(compact));
				if (GUI.Button(button, string.Empty, GUIStyle.none))
				{
					AudioManager.Instance?.PlayUIClick();
					if (string.Equals(ids[i], "react", StringComparison.Ordinal))
					{
						msg.ReactionSelf = !msg.ReactionSelf;
						msg.ReactionCount = Mathf.Max(0, msg.ReactionCount + (msg.ReactionSelf ? 1 : -1));
						ShowChatToast("Réaction mise à jour (placeholder).");
					}
					else if (string.Equals(ids[i], "copy", StringComparison.Ordinal))
					{
						GUIUtility.systemCopyBuffer = msg.Text;
						ShowChatToast("Message copié dans le presse-papiers.");
					}
					else if (string.Equals(ids[i], "pin", StringComparison.Ordinal))
					{
						msg.Pinned = !msg.Pinned;
						ShowChatToast(msg.Pinned ? "Message épinglé (placeholder)." : "Message dépinné (placeholder).");
					}
					else ShowChatToast("Signalement envoyé (placeholder).");
				}
			}
		}

		private static void DrawChatBubble(Rect rect, bool self)
		{
			Color fill = self ? new Color(0.16f, 0.11f, 0.05f, 0.98f) : new Color(0.045f, 0.038f, 0.026f, 0.98f);
			Color border = self ? new Color(1f, 0.70f, 0.18f, 0.85f) : new Color(0.70f, 0.50f, 0.18f, 0.60f);
			DrawPremiumPanel(rect, fill, border);
		}

