		private static float ChatBubbleTextHeight(string text, float width, bool compact)
		{
			if (chatCalcContentCache == null) chatCalcContentCache = new GUIContent();
			chatCalcContentCache.text = text ?? string.Empty;
			return ChatBubbleTextStyle(compact).CalcHeight(chatCalcContentCache, Mathf.Max(1f, width));
		}

		private static float ChatMessageBaseHeight(ChatMessageData msg, float width, bool compact)
		{
			float avatarSize = compact ? 34f : 38f;
			float pad = compact ? 8f : 10f;
			float textW = msg.FromSelf ? width - 2f * pad : width - avatarSize - 3f * pad;
			float bubbleW = Mathf.Min(textW, width * 0.78f);
			float innerW = bubbleW - (msg.FromSelf ? 16f : 20f);
			float nameH = msg.FromSelf ? 0f : (compact ? 13f : 15f);
			float textH = ChatBubbleTextHeight(msg.Text, innerW, compact);
			float timeH = 14f;
			float bubbleH = nameH + textH + timeH + 8f;
			return Mathf.Max(avatarSize + 8f, bubbleH + 4f);
		}

		private static float ChatRowHeight(int index)
		{
			if (chatHeights == null || index < 0 || index >= chatHeights.Length) return 48f;
			return chatHeights[index] + (index == chatActionMessageIndex ? ChatActionStripHeight : 0f);
		}

		private static void EnsureChatHeights(string conversationId, float width, bool compact)
		{
			List<ChatMessageData> messages = ChatMessagesFor(conversationId);
			int count = messages.Count;
			if (string.Equals(chatHeightConversation, conversationId, StringComparison.Ordinal) && Mathf.Approximately(chatHeightWidth, width) && chatHeightCount == count)
				return;
			if (chatHeights == null || chatHeights.Length != count) chatHeights = new float[count];
			for (int i = 0; i < count; i++) chatHeights[i] = ChatMessageBaseHeight(messages[i], width, compact);
			chatHeightConversation = conversationId;
			chatHeightWidth = width;
			chatHeightCount = count;
		}

		private static float ChatTotalHeight(int count)
		{
			float sum = 0f;
			for (int i = 0; i < count; i++) sum += ChatRowHeight(i) + ChatMessageGap;
			return Mathf.Max(1f, sum);
		}

		private static float ChatCumulativeHeight(int index)
		{
			float sum = 0f;
			for (int i = 0; i < index; i++) sum += ChatRowHeight(i) + ChatMessageGap;
			return sum;
		}

		private static void ChatComputeVisibleRange(float scrollY, float viewportH, int count, out int start, out int end)
		{
			start = -1;
			end = count;
			float cursor = 0f;
			for (int i = 0; i < count; i++)
			{
				float h = ChatRowHeight(i) + ChatMessageGap;
				if (start < 0 && cursor + h > scrollY) start = i;
				if (cursor >= scrollY + viewportH)
				{
					end = i;
					break;
				}
				cursor += h;
			}
			if (start < 0) start = 0;
			if (end < start) end = count;
		}

		private static void DrawChatToast()
		{
			if (chatToastAt < 0f) return;
			float age = NowForUi() - chatToastAt;
			float alpha = 1f - Mathf.Clamp01((age - 1.2f) / 0.8f);
			if (alpha <= 0f) return;
			float width = Mathf.Min(Screen.width - 24f, 390f);
			Rect toast = new Rect((Screen.width - width) * 0.5f, Screen.height - 72f, width, 40f);
			GUI.color = new Color(1f, 1f, 1f, alpha);
			DrawPremiumPanel(toast, new Color(0.05f, 0.04f, 0.025f, 0.98f), new Color(0.86f, 0.58f, 0.16f, 0.90f));
			GUI.Label(new Rect(toast.x + 10f, toast.y + 8f, toast.width - 20f, 24f), chatToast, new GUIStyle(smallStyle) { fontSize = 10, alignment = TextAnchor.MiddleCenter });
			GUI.color = Color.white;
		}

        private static void DrawResearchFullscreen(bool compact)
        {
            if (activeHiveMenu != HiveMenuMode.Research) return;
            if (Input.GetKeyDown(KeyCode.Escape))
            {
                CloseResearchFullscreen();
                return;
            }
            Vector2 inputMouse = new Vector2(Input.mousePosition.x, Screen.height - Input.mousePosition.y);
            if (Input.GetMouseButtonDown(0) && (new Rect(10f, 8f, 42f, 34f).Contains(inputMouse) || new Rect(Screen.width - 54f, 6f, 46f, 38f).Contains(inputMouse)))
            {
                CloseResearchFullscreen();
                return;
            }
            Rect backHit = new Rect(10f, 8f, 42f, 34f);
            Rect closeHit = new Rect(Screen.width - 54f, 6f, 46f, 38f);
            if (Event.current != null && Event.current.type == EventType.MouseDown && (backHit.Contains(Event.current.mousePosition) || closeHit.Contains(Event.current.mousePosition)))
            {
                CloseResearchFullscreen();
                Event.current.Use();
                return;
            }
            if (Event.current != null && Event.current.type == EventType.KeyDown && Event.current.keyCode == KeyCode.Escape)
            {
                CloseResearchFullscreen();
                Event.current.Use();
                return;
            }
            float anim = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((NowForUi() - researchFullscreenOpenedAt) / 0.18f));
            float zoom = Mathf.Lerp(0.975f, 1f, anim);
            Rect full = new Rect(0f, 0f, Screen.width, Screen.height);
            GUI.matrix = Matrix4x4.TRS(full.center, Quaternion.identity, new Vector3(zoom, zoom, 1f)) * Matrix4x4.Translate(-full.center);
            GUI.color = new Color(0.006f, 0.005f, 0.004f, 0.99f * anim);
            GUI.DrawTexture(full, Texture2D.blackTexture, ScaleMode.StretchToFill, false);
            GUI.color = Color.white;

            float bannerHeight = compact ? Mathf.Min(150f, Screen.height * 0.20f) : Mathf.Clamp(Screen.height * 0.20f, 150f, 190f);
            Rect banner = new Rect(0f, 0f, Screen.width, bannerHeight);
            Texture2D bannerTexture = Resources.Load<Texture2D>("PremiumBeeReference/BuildingBanners/research_node");
            if (bannerTexture != null) GUI.DrawTexture(banner, bannerTexture, ScaleMode.ScaleAndCrop, true);
            else DrawPremiumPanel(banner, new Color(0.12f, 0.07f, 0.025f, 0.98f), new Color(1f, 0.68f, 0.16f, 0.90f));
            GUI.color = new Color(0.01f, 0.008f, 0.004f, 0.52f);
            GUI.DrawTexture(banner, Texture2D.blackTexture, ScaleMode.StretchToFill, true);
            GUI.color = Color.white;
            GUI.Label(new Rect(28f, bannerHeight - (compact ? 42f : 48f), Screen.width * 0.62f, 26f), "RECHERCHE", new GUIStyle(titleStyle) { fontSize = compact ? 20 : 28, fontStyle = FontStyle.Bold });
            GUI.Label(new Rect(30f, bannerHeight - (compact ? 20f : 23f), Screen.width * 0.72f, 16f), "Études persistantes de la colonie", new GUIStyle(smallStyle) { fontSize = compact ? 9 : 12 });

            GUI.color = new Color(1f, 0.60f, 0.14f, 0.95f);
            GUI.DrawTexture(new Rect(0f, bannerHeight - 1f, Screen.width, 1f), Texture2D.whiteTexture, ScaleMode.StretchToFill, false);
            GUI.color = Color.white;
			if (DrawPremiumBackButton(new Rect(4f, 2f, 48f, 46f)))
            {
                CloseResearchFullscreen();
                GUI.matrix = Matrix4x4.identity;
                return;
            }
			float actionY = bannerHeight + 6f;
            Rect actionRail = new Rect(10f, actionY, Screen.width - 20f, compact ? 54f : 58f);
            DrawPremiumPanel(actionRail, new Color(0.025f, 0.022f, 0.017f, 0.98f), new Color(0.82f, 0.54f, 0.14f, 0.84f));
            string[] filters = { "all", "forage", "resources", "defense" };
            string[] labels = { "Toutes les études", "Forage", "Ressources", "Défense" };
            float gap = 6f;
            float itemWidth = compact ? 132f : (actionRail.width - 24f - gap * 3f) / 4f;
            researchFullscreenFilterScroll = GUI.BeginScrollView(actionRail, researchFullscreenFilterScroll, new Rect(0f, 0f, itemWidth * filters.Length + gap * 3f + 18f, actionRail.height - 2f), false, false);
            for (int i = 0; i < filters.Length; i++)
            {
                Rect filter = new Rect(6f + i * (itemWidth + gap), 8f, itemWidth, actionRail.height - 16f);
                bool selected = researchFullscreenFilter == filters[i];
                DrawPremiumPanel(filter, selected ? new Color(0.38f, 0.22f, 0.05f, 0.98f) : new Color(0.05f, 0.04f, 0.025f, 0.94f), selected ? new Color(1f, 0.72f, 0.18f, 0.96f) : new Color(0.58f, 0.42f, 0.16f, 0.62f));
                GUI.Label(filter, labels[i], new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 8 : 10 });
                if (GUI.Button(filter, string.Empty, GUIStyle.none))
                {
                    researchFullscreenFilter = filters[i];
                    researchFullscreenScroll = Vector2.zero;
                    AudioManager.Instance?.PlayUIClick();
                }
            }
            GUI.EndScrollView();

            float contentTop = actionRail.yMax + 8f;
            Rect content = new Rect(10f, contentTop, Screen.width - 20f, Screen.height - contentTop - 10f);
            DrawPremiumPanel(content, new Color(0.025f, 0.022f, 0.017f, 0.985f), new Color(0.86f, 0.58f, 0.16f, 0.80f));
            IReadOnlyList<LocalPreviewResearchDefinition> definitions = LocalPreviewResearchCatalog.All;
            List<LocalPreviewResearchDefinition> visible = new List<LocalPreviewResearchDefinition>(definitions.Count);
            for (int i = 0; i < definitions.Count; i++) if (ResearchMatchesFullscreenFilter(definitions[i].ResearchId)) visible.Add(definitions[i]);
            float inset = compact ? 10f : 16f;
            Rect viewport = new Rect(content.x + inset, content.y + inset, content.width - inset * 2f, content.height - inset * 2f);
            int columns = compact ? 1 : 2;
            float cardGap = compact ? 8f : 12f;
            float cardHeight = compact ? 132f : 164f;
            float cardWidth = (viewport.width - cardGap * (columns - 1)) / columns;
            float rows = Mathf.Ceil(visible.Count / (float)columns);
            researchFullscreenScroll = GUI.BeginScrollView(viewport, researchFullscreenScroll, new Rect(0f, 0f, viewport.width, Mathf.Max(viewport.height, rows * (cardHeight + cardGap))), false, true);
            for (int i = 0; i < visible.Count; i++)
            {
                int col = i % columns;
                int row = i / columns;
                DrawResearchFullscreenCard(new Rect(col * (cardWidth + cardGap), row * (cardHeight + cardGap), cardWidth, cardHeight), visible[i], compact);
            }
            GUI.EndScrollView();
            GUI.matrix = Matrix4x4.identity;
        }

        private static void DrawResearchFullscreenCard(Rect card, LocalPreviewResearchDefinition definition, bool compact)
        {
            bool official = OfficialResearchConfigured();
            HiveResearchScreenModel model = official ? OfficialResearchModel() : null;
            bool completed = official
                ? model != null && model.IsCompleted(definition.ResearchId)
                : LocalPreviewResearchCatalog.Contains(localPreviewQueueJournal.completedResearchIds, definition.ResearchId);
            bool running = official
                ? model != null && model.ActiveOperation != null && string.Equals(model.ActiveOperation.ResearchId, definition.ResearchId, StringComparison.Ordinal)
                : IsResearchRunning() && string.Equals(localPreviewResearchId, definition.ResearchId, StringComparison.Ordinal);
            Color accent = completed ? new Color(0.42f, 0.82f, 0.48f, 0.92f) : running ? new Color(0.70f, 0.62f, 1f, 0.94f) : new Color(0.38f, 0.72f, 1f, 0.82f);
            DrawPremiumPanel(card, new Color(0.035f, 0.048f, 0.062f, 0.97f), accent);
            DrawGameIcon(new Rect(card.x + 12f, card.y + 14f, compact ? 42f : 52f, compact ? 42f : 52f), definition.IconId, Color.white);
            float actionWidth = compact ? 100f : 118f;
            float textX = card.x + (compact ? 64f : 78f);
            float textWidth = card.width - actionWidth - textX + card.x - 18f;
            GUI.Label(new Rect(textX, card.y + 12f, textWidth, 22f), BeeLocalization.Text(definition.TitleKey, definition.ResearchId), new GUIStyle(badgeStyle) { fontSize = compact ? 12 : 14, normal = { textColor = accent } });
            GUI.Label(new Rect(textX, card.y + 38f, textWidth, compact ? 34f : 44f), BeeLocalization.Text(definition.SummaryKey, definition.ResearchId), new GUIStyle(smallStyle) { fontSize = compact ? 9 : 11, wordWrap = true });
            string detail;
            string reason;
            bool enabled;
            string actionLabel;
            if (official)
            {
                HiveResearchOfferModel offer = model == null ? null : model.OfferFor(definition.ResearchId);
                detail = offer == null ? OfficialResearchEffectText(definition.ResearchId) : OfficialResearchCostText(offer) + " · " + OfficialResearchEffectText(definition.ResearchId);
                reason = OfficialResearchStatusText(definition.ResearchId);
                enabled = OfficialResearchActionEnabled(definition.ResearchId);
                actionLabel = OfficialResearchActionLabel(definition.ResearchId);
            }
            else
            {
                detail = ResearchCostText(definition);
                reason = ResearchDisabledReason(definition);
                enabled = string.IsNullOrWhiteSpace(reason);
                actionLabel = completed ? "Terminée" : running ? "En cours" : "Lancer";
            }
            GUI.Label(new Rect(card.x + 14f, card.yMax - 30f, card.width - actionWidth - 28f, 22f), detail, new GUIStyle(tinyLabelStyle) { fontSize = compact ? 8 : 9, wordWrap = true });
            Rect action = new Rect(card.xMax - actionWidth - 12f, card.y + 14f, actionWidth, 42f);
            if (DrawPreviewActionButton(action, actionLabel, enabled && !completed && !running))
            {
                if (official) RunOfficialResearchAction(definition.ResearchId);
                else StartPreviewResearch(definition.ResearchId);
            }
            if (running) DrawProgressBar(new Rect(action.x, action.yMax + 8f, action.width, 7f), official && model != null ? (float)model.Progress01(researchController.Elapsed) : ResearchProgress01());
            else GUI.Label(new Rect(action.x - 4f, action.yMax + 6f, action.width + 8f, 22f), reason, new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 8 : 9, wordWrap = true });
        }

