        private static void DrawBottomRail()
        {
            bool portrait = IsPortraitLayout();
            if (portrait)
            {
                DrawPortraitBottomRail();
                return;
            }

            Rect rail = new Rect(8f, Screen.height - 76f, Screen.width - 16f, 68f);
            DrawPremiumPanel(rail, new Color(0.020f, 0.018f, 0.014f, 0.84f), new Color(0.86f, 0.58f, 0.16f, 0.68f));
            DrawBottomRailOrnament(rail);
            ThumbRailItem[] items =
            {
                Rail("SurfaceSwitch", referenceSurfaceMode == ReferenceSurfaceMode.WorldBoundary ? "Ruche" : "Carte", referenceSurfaceMode == ReferenceSurfaceMode.WorldBoundary ? "hive-nav" : "world"),
                Rail("Quests", "Quetes", "quests"),
                Rail("Champions", BeeLocalization.Text("champion_bees.entry_button_short", "Championnes"), "queen"),
                Rail("MilestoneEvent", MilestoneEventRailLabel(), "quests"),
                Rail("Bestiary", BeeLocalization.Text("bestiary_codex.entry_button_short", "Bestiaire"), "quests"),
                Rail("Bag", "Sac", "inventory"),
                Rail("Mail", "Mail", "inbox"),
                Rail("Chat", "Chat", "messages"),
                Rail("Alliance", "Alliance", "alliance"),
                Rail("More", "Plus", "more")
            };
            float gap = 8f;
            float itemWidth = (rail.width - 20f - gap * (items.Length - 1)) / items.Length;
            for (int i = 0; i < items.Length; i++)
            {
                ThumbRailItem entry = items[i];
                Rect item = new Rect(rail.x + 10f + i * (itemWidth + gap), rail.y + 7f, itemWidth, rail.height - 14f);
                bool surfaceSwitch = entry.ItemId == "SurfaceSwitch";
                bool active = !surfaceSwitch && (activeMainMenuId == entry.ItemId
                    || (entry.ItemId == "More" && activeMainMenuId == "Settings"));
                if (i > 0) DrawRailDivider(new Rect(item.x - gap * 0.5f - 1f, rail.y + 14f, 2f, rail.height - 28f));
                if (DrawIconButton(item, NavIconId(entry.IconId), entry.Label, active, entry.ItemId))
                {
                    if (surfaceSwitch)
                    {
                        activeMainMenuId = string.Empty;
                        if (referenceSurfaceMode == ReferenceSurfaceMode.WorldBoundary) SetReferenceSurfaceModeForProof("hive");
                        else OpenCanonicalWorldMap();
                        continue;
                    }

                    if (entry.ItemId == "Chat")
                    {
                        if (!communicationPanelOpen)
                        {
                            activeMainMenuId = string.Empty;
                            activeHiveMenu = HiveMenuMode.Hive;
                            ClearReferenceDetailPanelSelection();
                        }
                        ToggleMiniChat();
                        continue;
                    }

                    if (entry.ItemId == "Champions")
                    {
                        activeMainMenuId = string.Empty;
                        championBeesPanelOpen = true;
                        championBeesPanelAnimationStartedAt = NowForUi();
                        AudioManager.Instance?.PlayMenuOpen();
                        continue;
                    }

                    if (entry.ItemId == "MilestoneEvent")
                    {
                        activeMainMenuId = string.Empty;
                        OpenMilestoneEventOverlay();
                        continue;
                    }

                    if (entry.ItemId == "Bestiary")
                    {
                        activeMainMenuId = string.Empty;
                        OpenBestiaryCodexOverlay();
                        continue;
                    }

                    if (entry.ItemId == "Mail")
                    {
                        OpenCourierScreen();
                        continue;
                    }

                    if (entry.ItemId == "More" && activeMainMenuId == "Settings")
                    {
                        CloseActiveMainMenuPanel();
                        AudioManager.Instance?.PlayMenuClose();
                        continue;
                    }

                    bool opening = activeMainMenuId != entry.ItemId;
                    activeMainMenuId = opening ? entry.ItemId : string.Empty;
                    if (opening) AudioManager.Instance?.PlayMenuOpen();
                    else AudioManager.Instance?.PlayMenuClose();
                    if (opening && entry.ItemId == "Alliance") ActivateHiveMenu(HiveMenuMode.Alliance, "Menu alliance");
                    if (opening && entry.ItemId == "Bag")
                    {
                        localPreviewLoopMessage = BeeLocalization.Text("ledger.opened", "Sac & stocks ouvert");
                        localPreviewLastActionStatus = BeeLocalization.Text("ledger.title", "Sac & stocks");
                        BeginReferenceFeedbackPulse("preview");
                    }
                    if (opening && entry.ItemId != "Alliance")
                    {
                        if (entry.ItemId != "Bag") localPreviewLoopMessage = entry.Label + " - menu premium preview";
                        localPreviewLastActionStatus = entry.Label;
                        if (entry.ItemId != "Bag") BeginReferenceFeedbackPulse("future");
                    }
                }
            }
        }

private static Rect SurfaceSwitchButtonRect(bool portrait)
        {
            if (portrait)
            {
                Rect rail = new Rect(8f, Screen.height - 78f, Screen.width - 16f, 70f);
                const int itemCount = 5;
                const int switchIndex = 1;
                const float gap = 8f;
                float itemWidth = (rail.width - 20f - gap * (itemCount - 1)) / itemCount;
                return new Rect(rail.x + 10f + switchIndex * (itemWidth + gap), rail.y + 8f, itemWidth, rail.height - 16f);
            }

            Rect landscapeRail = new Rect(8f, Screen.height - 76f, Screen.width - 16f, 68f);
            const int landscapeItemCount = 10;
            const float landscapeGap = 8f;
            float landscapeItemWidth = (landscapeRail.width - 20f - landscapeGap * (landscapeItemCount - 1)) / landscapeItemCount;
            return new Rect(landscapeRail.x + 10f, landscapeRail.y + 7f, landscapeItemWidth, landscapeRail.height - 14f);
        }

        private static void DrawPortraitBottomRail()
        {
            Rect rail = new Rect(8f, Screen.height - 78f, Screen.width - 16f, 70f);
            DrawPremiumPanel(rail, new Color(0.020f, 0.018f, 0.014f, 0.84f), new Color(0.86f, 0.58f, 0.16f, 0.68f));
            DrawBottomRailOrnament(rail);
            ThumbRailItem[] items =
            {
                Rail("Chat", "Chat", "messages"),
                Rail("SurfaceSwitch", referenceSurfaceMode == ReferenceSurfaceMode.WorldBoundary ? "Ruche" : "Carte", referenceSurfaceMode == ReferenceSurfaceMode.WorldBoundary ? "hive-nav" : "world"),
                Rail("Quests", "Quetes", "quests"),
                Rail("Alliance", "Alliance", "alliance"),
                Rail("More", "Plus", "more")
            };
            float gap = 8f;
            float itemWidth = (rail.width - 20f - gap * (items.Length - 1)) / items.Length;
            for (int i = 0; i < items.Length; i++)
            {
                ThumbRailItem entry = items[i];
                Rect item = new Rect(rail.x + 10f + i * (itemWidth + gap), rail.y + 8f, itemWidth, rail.height - 16f);
                if (i > 0) DrawRailDivider(new Rect(item.x - gap * 0.5f - 1f, rail.y + 15f, 2f, rail.height - 30f));
                bool surfaceSwitch = entry.ItemId == "SurfaceSwitch";
                bool active = !surfaceSwitch && (activeMainMenuId == entry.ItemId
                    || (entry.ItemId == "More" && activeMainMenuId == "Settings")
                    || (entry.ItemId == "Alliance" && activeHiveMenu == HiveMenuMode.Alliance));
                if (DrawIconButton(item, NavIconId(entry.IconId), entry.Label, active, entry.ItemId))
                {
                    if (surfaceSwitch)
                    {
                        activeMainMenuId = string.Empty;
                        if (referenceSurfaceMode == ReferenceSurfaceMode.WorldBoundary) SetReferenceSurfaceModeForProof("hive");
                        else OpenCanonicalWorldMap();
                        continue;
                    }

                    if (entry.ItemId == "Chat")
                    {
                        if (!communicationPanelOpen)
                        {
                            activeMainMenuId = string.Empty;
                            activeHiveMenu = HiveMenuMode.Hive;
                            ClearReferenceDetailPanelSelection();
                        }
                        ToggleMiniChat();
                        continue;
                    }

                    if (entry.ItemId == "More" && activeMainMenuId == "Settings")
                    {
                        CloseActiveMainMenuPanel();
                        AudioManager.Instance?.PlayMenuClose();
                        continue;
                    }

                    bool opening = activeMainMenuId != entry.ItemId || activeHiveMenu != HiveMenuMode.Hive;
                    if (entry.ItemId == "Alliance" && activeHiveMenu == HiveMenuMode.Alliance) opening = false;
                    if (entry.ItemId == "Quests" && activeMainMenuId == "Quests") opening = false;
                    if (opening && entry.ItemId != "Alliance" && entry.ItemId != "Quests")
                    {
                        activeMainMenuId = opening ? entry.ItemId : string.Empty;
                        activeHiveMenu = HiveMenuMode.Hive;
                    }
                    else if (entry.ItemId == "Quests")
                    {
                        activeMainMenuId = opening ? "Quests" : string.Empty;
                        activeHiveMenu = HiveMenuMode.Hive;
                        ClearReferenceDetailPanelSelection();
                    }
                    else if (entry.ItemId == "Alliance")
                    {
                        activeMainMenuId = string.Empty;
                        if (opening)
                        {
                            ActivateHiveMenu(HiveMenuMode.Alliance, "Menu alliance");
                            AudioManager.Instance?.PlayMenuOpen();
                        }
                        else
                        {
                            activeHiveMenu = HiveMenuMode.Hive;
                            detailPanelClosed = true;
                            allianceActionPanelOpen = string.Empty;
                            AudioManager.Instance?.PlayMenuClose();
                        }
                        continue;
                    }
                    if (opening) AudioManager.Instance?.PlayMenuOpen();
                    else AudioManager.Instance?.PlayMenuClose();
                    if (opening)
                    {
                        localPreviewLoopMessage = entry.ItemId == "Quests"
                            ? BeeLocalization.Text("quest_journal.opened", "Journal de quêtes ouvert")
                            : entry.Label + " - menu premium preview";
                        if (entry.ItemId == "Bag") BeginReferenceFeedbackPulse("preview");
                    }
                }
            }
        }

