        // Pont vers WorldMapMmoFullscreenFoundationBootstrap : seuls ces noeuds ont une contrepartie
        // reelle cote serveur (memes identifiants que le catalogue serveur - miel/pollen/cire, les
        // seules ressources deja suivies dans l'economie du jeu). Les autres noeuds visibles sur la
        // carte (nectar/eau/propolis/gelee royale) restent volontairement locaux/demo pour l'instant.
        private static readonly HashSet<string> OfficialWorldResourceNodeIds = new HashSet<string>(StringComparer.Ordinal) { "res_pollen_core", "res_wax_core", "res_honey_core" };

        internal static bool IsOfficialWorldResourceNode(string nodeId) => !string.IsNullOrEmpty(nodeId) && OfficialWorldResourceNodeIds.Contains(nodeId);

        internal static WorldResourceCollectionScreenModel OfficialWorldResourceCollectionModelForWorldMap() =>
            OfficialWorldResourceCollectionConfigured() ? OfficialWorldResourceCollectionModel() : null;

        internal static void LaunchOfficialWorldResourceCollectionForWorldMap(string nodeId)
        {
            if (!OfficialWorldResourceCollectionConfigured() || !IsOfficialWorldResourceNode(nodeId)) return;
            ApplyDefaultWorldResourceCollectionEscort();
            worldResourceCollectionController.Launch(nodeId);
            ChampionVoiceBarkController.BarkForCollectionLaunch(localPreviewAssignedChampionBeeIds);
        }

        // Escouade reellement engagee (demande de Jeff, 2026-08-01) : tant qu'aucun composeur
        // interactif dedie n'existe pour ce vol (contrairement a Combat Patrol), une petite
        // escorte par defaut est choisie automatiquement parmi les troupes disponibles - jamais
        // zero, jamais plus que necessaire pour rendre le vol reel. Prefere les gardiennes, puis
        // voltigeuses, puis lanceuses. L'architecture (brouillon, disponibilite, ajustement)
        // reste identique a Combat Patrol et pourra recevoir un vrai composeur plus tard sans
        // changement de forme.
        private const int DefaultWorldResourceEscortSize = 3;
        private static void ApplyDefaultWorldResourceCollectionEscort()
        {
            WorldResourceCollectionScreenModel model = OfficialWorldResourceCollectionModel();
            if (model == null || model.DraftTotal > 0) return;
            foreach (string family in new[] { "guardians", "wingrunners", "darters" })
            {
                long available = model.AvailableRoster.GetValueOrDefault(family);
                if (available <= 0) continue;
                worldResourceCollectionController.AdjustDraft(family, (int)Math.Min(DefaultWorldResourceEscortSize, available));
                return;
            }
        }

        internal static void ClaimOfficialWorldResourceCollectionForWorldMap()
        {
            if (!OfficialWorldResourceCollectionConfigured()) return;
            worldResourceCollectionController.Claim();
        }

        internal static void RecallOfficialWorldResourceCollectionForWorldMap()
        {
            if (!OfficialWorldResourceCollectionConfigured()) return;
            worldResourceCollectionController.Recall();
        }

        internal static void RefreshOfficialWorldResourceCollectionForWorldMap()
        {
            if (!OfficialWorldResourceCollectionConfigured()) return;
            worldResourceCollectionController.Refresh();
        }

