        // Meme table de noms courts que WorldBestiaryNode.BestiaryLabel (World Map) - duplique ici
        // volontairement : purement de l'affichage, aucune donnee de jeu, pas besoin de coupler ce
        // presenteur au bootstrap de la carte pour deux tableaux de 7 lignes.
        private static string BestiaryCodexVariantLabel(int tier, int variant)
        {
            if (tier == 1) return variant == 1 ? "Puceron" : "Acarien";
            if (tier == 2) return variant == 1 ? "Fourmi" : "Scarabee";
            if (tier == 3) return variant == 1 ? "Araignee" : "Mouche";
            if (tier == 4) return variant == 1 ? "Mante" : "Scolopendre";
            if (tier == 5) return variant == 1 ? "Frelon" : "Lucane";
            if (tier == 6) return variant == 1 ? "Scorpion" : "Tarantule";
            return variant == 1 ? "Reine frelon" : "Titan lucane";
        }

        // Petite animation (demande de Jeff, 2026-08-02) : le badge "Legendaire" respire doucement au
        // lieu d'etre une couleur figee - purement decoratif, ne consomme aucun etat, se recalcule
        // chaque frame depuis l'horloge realtime.
        private static Color BestiaryCodexLegendaryPulseColor()
        {
            float pulse = 0.5f + 0.5f * Mathf.Sin(Time.realtimeSinceStartup * 3f);
            return Color.Lerp(new Color(0.86f, 0.42f, 0.32f, 1f), new Color(1f, 0.68f, 0.30f, 1f), pulse);
        }

        private static string BestiaryCodexBandLabel(string band)
        {
            if (band == "DecisiveVictory") return BeeLocalization.Text("bestiary_codex.band.decisive", "Victoire ecrasante");
            if (band == "Victory") return BeeLocalization.Text("bestiary_codex.band.victory", "Victoire");
            if (band == "HardWon") return BeeLocalization.Text("bestiary_codex.band.hard_won", "Victoire chere");
            return BeeLocalization.Text("bestiary_codex.band.none", "Aucun combat");
        }

        private static void DrawBestiaryCodexOverlay()
        {
            if (!bestiaryCodexOverlayOpen || !OfficialBestiaryCodexConfigured()) return;
            EnsureStyles();
            DrawPremiumModalBackdrop();
            BestiaryCodexScreenModel model = bestiaryCodexController.Model;
float bestiaryModalWidth = Mathf.Min(460f, Screen.width - 24f);
            float bestiaryModalHeight = IsPortraitLayout()
                ? Mathf.Min(880f, Screen.height - 40f)
                : Mathf.Min(480f, Screen.height - 40f);
            Rect panel = new Rect(Screen.width * 0.5f - bestiaryModalWidth * 0.5f, Screen.height * 0.5f - bestiaryModalHeight * 0.5f, bestiaryModalWidth, bestiaryModalHeight);
			DrawPremiumPanel(panel, new Color(0.026f, 0.024f, 0.020f, 0.95f), new Color(0.62f, 0.42f, 0.86f, 0.82f));
			DrawPremiumHeaderBand(new Rect(panel.x + 8f, panel.y + 8f, panel.width - 16f, 46f));
			if (DrawPremiumBackButton(new Rect(panel.x + 10f, panel.y + 9f, 44f, 44f))) { AudioManager.Instance?.PlayUIClick(); AudioManager.Instance?.PlayMenuClose(); bestiaryCodexOverlayOpen = false; return; }
			GUI.Label(new Rect(panel.x + 58f, panel.y + 15f, panel.width - 70f, 28f), BeeLocalization.Text("bestiary_codex.title", "Carnet du Bestiaire"), titleStyle);

            float y = panel.y + 62f;
            if (!model.Loaded)
            {
                GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 24f), BeeLocalization.Text("bestiary_codex.loading", "Chargement du carnet..."), smallStyle);
                return;
            }

            // Voix des Championnes (demande de Jeff, 2026-08-02) : detecte la transition "vient de
            // devenir Legendaire" - le serveur ne renvoie qu'un booleen plat, sans historique, donc la
            // comparaison avant/apres se fait ici, cote client, avec un simple ensemble de paliers deja
            // vus comme Legendaires.
            foreach (RemoteBestiaryCodexEntry tierEntry in model.Tiers)
            {
                if (!tierEntry.Legendary || championVoiceKnownLegendaryTiers.Contains(tierEntry.Tier)) continue;
                championVoiceKnownLegendaryTiers.Add(tierEntry.Tier);
                ChampionVoiceBarkController.BarkForLegendaryDiscovery(tierEntry.LastContributingChampionBeeIds);
            }

            GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 22f),
                string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("bestiary_codex.completion", "{0} / {1} paliers maitrises"), model.MasteredTierCount, model.TotalTierCount),
                new GUIStyle(tinyLabelStyle) { normal = { textColor = new Color(1f, 0.82f, 0.42f, 1f) } });
            y += 26f;

            Rect tierRow = new Rect(panel.x + 12f, y, panel.width - 24f, 32f);
            GUI.BeginGroup(tierRow);
            float tierW = tierRow.width / 7f;
            for (int t = 1; t <= 7; t++)
            {
                bool selected = bestiaryCodexSelectedTier == t;
                RemoteBestiaryCodexEntry entryForTab = model.Tiers.FirstOrDefault(e => e.Tier == t);
                bool tabLegendary = entryForTab != null && entryForTab.Legendary;
                bool tabMastered = entryForTab != null && entryForTab.Mastered;
                Color previousColor = GUI.color;
                // Presentation (demande de Jeff, 2026-08-02) : le statut d'un palier doit se lire
                // directement sur la grille des 7 onglets, pas seulement apres avoir ouvert sa fiche -
                // badge visible + legere pulsation sur "Legendaire" pour qu'il attire l'oeil sans
                // gener la lecture (petite animation, aucune nouvelle mecanique).
                if (tabLegendary && !selected) GUI.color = BestiaryCodexLegendaryPulseColor();
                else if (tabMastered && !selected) GUI.color = new Color(1f, 0.82f, 0.42f, 1f);
                string tabSuffix = tabLegendary ? " !" : tabMastered ? " *" : string.Empty;
                if (GUI.Toggle(new Rect((t - 1) * tierW, 0f, tierW - 2f, 30f), selected, "T" + t.ToString(CultureInfo.InvariantCulture) + tabSuffix, "Button") && !selected)
                    bestiaryCodexSelectedTier = t;
                GUI.color = previousColor;
            }
            GUI.EndGroup();
            y += 40f;

            RemoteBestiaryCodexEntry entry = model.Tiers.FirstOrDefault(e => e.Tier == bestiaryCodexSelectedTier);
            if (entry == null)
            {
                GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 24f), BeeLocalization.Text("bestiary_codex.unknown_tier", "Palier inconnu"), smallStyle);
                return;
            }

            GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 26f), entry.EnemyName, titleStyle);
            y += 28f;

            string state = entry.EncounterCount <= 0
                ? BeeLocalization.Text("bestiary_codex.state.unknown", "Inconnue")
                : entry.Mastered
                    ? BeeLocalization.Text("bestiary_codex.state.mastered", "Maitrisee")
                    : BeeLocalization.Text("bestiary_codex.state.met", "Rencontree");
            GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f), state + (entry.Legendary ? "  *  " + BeeLocalization.Text("bestiary_codex.legendary", "Legendaire") : string.Empty),
                new GUIStyle(smallStyle) { normal = { textColor = entry.Legendary ? new Color(0.86f, 0.42f, 0.32f, 1f) : entry.Mastered ? new Color(1f, 0.82f, 0.42f, 1f) : Color.white } });
            y += 24f;

            // Progression plus lisible (demande de Jeff, 2026-08-02) : le nombre brut de rencontres
            // ne dit pas a quel point le joueur est proche de "Maitrisee" - une barre le montre d'un
            // coup d'oeil, reutilise le meme helper que partout ailleurs dans l'interface.
            float masteryProgress01 = entry.Mastered || model.MasteryEncounterThreshold <= 0
                ? 1f
                : Mathf.Clamp01(entry.EncounterCount / (float)model.MasteryEncounterThreshold);
            DrawProgressBar(new Rect(panel.x + 12f, y, panel.width - 24f, 8f), masteryProgress01);
            y += 16f;

            // Les deux identites cosmetiques de ce palier (demande de Jeff) : "Apercue" est purement
            // client-local (voir LocalPreviewBestiarySightingsTracker), le reste de la fiche vient du
            // serveur et est partage par les deux variantes puisque le serveur ne suit que le Tier.
            for (int variant = 1; variant <= 2; variant++)
            {
                bool seen = LocalPreviewBestiarySightingsTracker.HasSeen(entry.Tier, variant);
                GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f),
                    (seen ? "> " : "? ") + BestiaryCodexVariantLabel(entry.Tier, variant) + " - " + (seen ? BeeLocalization.Text("bestiary_codex.seen", "Apercue") : BeeLocalization.Text("bestiary_codex.unseen", "Jamais apercue")),
                    new GUIStyle(tinyLabelStyle) { normal = { textColor = seen ? new Color(0.76f, 0.92f, 0.60f, 1f) : new Color(0.6f, 0.6f, 0.6f, 1f) } });
                y += 20f;
            }
            y += 8f;

            if (entry.EncounterCount > 0)
            {
                // Histoire personnelle (exigence de Jeff, 2026-08-01) : jamais une fiche de base de
                // donnees - chaque ligne raconte ce que CE joueur a vecu avec CETTE creature.
                GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f),
                    string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("bestiary_codex.first_encounter", "Premiere rencontre : {0:d}"), entry.FirstEncounteredAtUtc?.ToLocalTime() ?? DateTimeOffset.Now),
                    tinyLabelStyle);
                y += 20f;
                GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f),
                    string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("bestiary_codex.encounters", "Affrontee {0} fois - meilleur combat : {1}"), entry.EncounterCount, BestiaryCodexBandLabel(entry.BestBand)),
                    tinyLabelStyle);
                y += 20f;
                if (entry.BestBandAchievedAtUtc.HasValue)
                {
                    GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f),
                        string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("bestiary_codex.best_band_date", "Meilleure victoire obtenue le {0:d}"), entry.BestBandAchievedAtUtc.Value.ToLocalTime()),
                        tinyLabelStyle);
                    y += 20f;
                }
                GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f),
                    string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("bestiary_codex.loot", "Butin total : {0} miel / {1} pollen"), entry.TotalHoneyCredited, entry.TotalPollenCredited),
                    tinyLabelStyle);
                y += 20f;
                // Souvenir de combat (demande de Jeff, 2026-08-02) : le dernier affrontement precis,
                // distinct du cumul ci-dessus - "voici ce qui s'est passe la derniere fois", pas juste
                // un total impersonnel.
                GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f),
                    string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("bestiary_codex.last_encounter", "Dernier combat : {0} - {1} miel / {2} pollen"), BestiaryCodexBandLabel(entry.LastBand), entry.LastHoneyCredited, entry.LastPollenCredited),
                    new GUIStyle(tinyLabelStyle) { normal = { textColor = new Color(0.62f, 0.86f, 1f, 1f) } });
                y += 20f;
                if (entry.DailyFocusEncounterCount > 0)
                {
                    GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f),
                        string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("bestiary_codex.daily_focus_count", "Dont {0} fois sous Cible du jour"), entry.DailyFocusEncounterCount),
                        new GUIStyle(tinyLabelStyle) { normal = { textColor = new Color(1f, 0.82f, 0.42f, 1f) } });
                    y += 20f;
                }
                if (entry.LastContributingChampionBeeIds != null && entry.LastContributingChampionBeeIds.Count > 0)
                {
                    GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f),
                        string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("bestiary_codex.champions", "Championnes au dernier combat : {0}"), entry.LastContributingChampionBeeIds.Count),
                        new GUIStyle(tinyLabelStyle) { normal = { textColor = new Color(1f, 0.82f, 0.42f, 1f) } });
                    y += 20f;
                }
            }
            else
            {
                GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 40f),
                    BeeLocalization.Text("bestiary_codex.no_encounter_yet", "Aucune rencontre enregistree pour ce palier - pars en patrouille pour commencer son histoire."),
                    new GUIStyle(tinyLabelStyle) { wordWrap = true });
            }
        }

