        internal static string MilestoneEventEntryBadgeText()
        {
            if (!OfficialMilestoneEventConfigured()) return string.Empty;
            HiveMilestoneEventScreenModel model = milestoneEventController.Model;
            if (model.Claimed || model.WindowExpired) return string.Empty;
            return model.CanClaim ? "!" : model.CompletedCount + "/" + model.RequiredObjectiveCount;
        }

        internal static void OpenMilestoneEventOverlay()
        {
            milestoneEventOverlayOpen = true;
            milestoneEventController.Refresh();
            AudioManager.Instance?.PlayMenuOpen();
        }

        private static void DrawMilestoneEventOverlay()
        {
            if (!milestoneEventOverlayOpen || !OfficialMilestoneEventConfigured()) return;
            EnsureStyles();
            DrawPremiumModalBackdrop();
            HiveMilestoneEventScreenModel model = milestoneEventController.Model;
float milestoneModalWidth = Mathf.Min(460f, Screen.width - 24f);
            float milestoneModalHeight = IsPortraitLayout()
                ? Mathf.Min(760f, Screen.height - 40f)
                : Mathf.Min(440f, Screen.height - 40f);
            Rect panel = new Rect(Screen.width * 0.5f - milestoneModalWidth * 0.5f, Screen.height * 0.5f - milestoneModalHeight * 0.5f, milestoneModalWidth, milestoneModalHeight);
			DrawPremiumPanel(panel, new Color(0.026f, 0.024f, 0.020f, 0.95f), new Color(0.98f, 0.78f, 0.20f, 0.86f));
			DrawPremiumHeaderBand(new Rect(panel.x + 8f, panel.y + 8f, panel.width - 16f, 46f));
			if (DrawPremiumBackButton(new Rect(panel.x + 10f, panel.y + 9f, 44f, 44f))) { AudioManager.Instance?.PlayUIClick(); AudioManager.Instance?.PlayMenuClose(); milestoneEventOverlayOpen = false; return; }
			GUI.Label(new Rect(panel.x + 58f, panel.y + 15f, panel.width - 70f, 28f), BeeLocalization.Text("milestone_event.title", "Défi de la ruche"), titleStyle);

            float y = panel.y + 62f;
            if (model.State == HiveMilestoneEventScreenState.Error)
            {
                GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 40f), BeeLocalization.Text("milestone_event.error", "Erreur") + " : " + model.ErrorCode, smallStyle);
                return;
            }
            GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 40f),
                string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("milestone_event.intro", "Complète {0} objectifs sur {1} pour réclamer la récompense."), model.RequiredObjectiveCount, model.Objectives.Count),
                smallStyle);
            y += 44f;

            for (int i = 0; i < model.Objectives.Count; i++)
            {
                RemoteHiveMilestoneObjective objective = model.Objectives[i];
                Rect row = new Rect(panel.x + 12f, y, panel.width - 24f, 28f);
                GUI.DrawTexture(row, SolidTexture(new Color(0.08f, 0.07f, 0.045f, 0.6f)));
                string check = objective.Done ? "✓" : "…";
                GUI.Label(row, check + "  " + MilestoneObjectiveLabel(objective.ObjectiveKey), new GUIStyle(smallStyle) { normal = { textColor = objective.Done ? new Color(0.55f, 0.95f, 0.55f, 1f) : Color.white } });
                y += 32f;
            }

            y += 6f;
            GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 22f),
                BeeLocalization.Text("milestone_event.reward", "Récompense") + " : " + model.Reward.GetValueOrDefault("honey") + " " + BeeLocalization.Text("resource.honey", "miel") + " / " + model.Reward.GetValueOrDefault("pollen") + " " + BeeLocalization.Text("resource.pollen", "pollen"),
                smallStyle);
            y += 30f;

            bool expired = model.WindowExpired && !model.Claimed;
            string buttonLabel = model.Claimed
                ? BeeLocalization.Text("milestone_event.claimed", "Récompense déjà réclamée")
                : expired
                    ? BeeLocalization.Text("milestone_event.expired", "Fenêtre expirée")
                    : BeeLocalization.Text("milestone_event.claim", "Réclamer");
            GUI.enabled = model.CanClaim && milestoneEventController.IsConfigured && !milestoneEventController.IsBusy;
            if (GUI.Button(new Rect(panel.x + 12f, panel.yMax - 54f, panel.width - 24f, 40f), buttonLabel))
                milestoneEventController.Claim();
            GUI.enabled = true;
        }

        private static string MilestoneEventRailLabel()
        {
            string badge = MilestoneEventEntryBadgeText();
            string label = BeeLocalization.Text("milestone_event.entry_button_short", "Défi");
            return string.IsNullOrEmpty(badge) ? label : label + " " + badge;
        }

        private static string MilestoneObjectiveLabel(string objectiveKey)
        {
            switch (objectiveKey)
            {
                case "building_upgrade": return BeeLocalization.Text("milestone_event.objective.building_upgrade", "Améliore un bâtiment au niveau 2");
                case "troop_recruit": return BeeLocalization.Text("milestone_event.objective.troop_recruit", "Recrute des troupes");
                case "world_resource": return BeeLocalization.Text("milestone_event.objective.world_resource", "Collecte une ressource sur la carte du monde");
                case "strategic_path": return BeeLocalization.Text("milestone_event.objective.strategic_path", "Choisis ta voie stratégique");
                case "vip_tier": return BeeLocalization.Text("milestone_event.objective.vip_tier", "Atteins un palier VIP");
                default: return objectiveKey;
            }
        }

        internal static async void OpenCombatPatrolOverlayForWorldMap(int tier)
        {
            AudioManager.Instance?.PlayMenuOpen();
            combatPatrolOverlayOpen = true;
            combatPatrolController.ClearSelection();
            combatPatrolController.SelectTier(Mathf.Clamp(tier, 1, 7));
            combatPatrolController.Refresh();
            await System.Threading.Tasks.Task.Delay(600);
            var squad = MobileAccountSessionRuntimeBootstrap.SquadReservationControllerForHiveMap?.Model;
            if (squad != null && squad.HasReservation)
            {
                try
                {
                    var model = combatPatrolController.Model;
                    if (model != null)
                    {
                        model.AvailableRoster = new System.Collections.Generic.Dictionary<string, long>
                        {
                            ["guardians"] = squad.RosterGuardians,
                            ["wingrunners"] = squad.RosterWingrunners,
                            ["darters"] = squad.RosterDarters
                        };
                    }
                }
                catch { }
                combatPatrolController.AdjustDraft("guardians", -1000);
                combatPatrolController.AdjustDraft("wingrunners", -1000);
                combatPatrolController.AdjustDraft("darters", -1000);
                if (squad.ReservedGuardians > 0) combatPatrolController.AdjustDraft("guardians", (int)squad.ReservedGuardians);
                if (squad.ReservedWingrunners > 0) combatPatrolController.AdjustDraft("wingrunners", (int)squad.ReservedWingrunners);
                if (squad.ReservedDarters > 0) combatPatrolController.AdjustDraft("darters", (int)squad.ReservedDarters);
            }
        }

        private static async System.Threading.Tasks.Task RefreshCombatPatrolAsync()
        {
            combatPatrolController.Refresh();
            await System.Threading.Tasks.Task.Delay(600);
        }

        // Opens the overlay pre-focused on one already-launched encounter (from the queue strip).
        internal static void OpenCombatPatrolEncounterForWorldMap(Guid encounterId)
        {
            AudioManager.Instance?.PlayMenuOpen();
            combatPatrolOverlayOpen = true;
            combatPatrolController.SelectEncounter(encounterId);
        }

        // Read-only peek so the world map can draw marching lines to active patrols' targets
        // without depending on the panel controller's full interface.
        internal static CombatPatrolScreenModel PeekCombatPatrolModelForWorldMap() => combatPatrolController?.Model;

        // Permet a la carte du monde de relire l'etat de patrouille pendant que le joueur reste
        // simplement sur la carte (demande de Jeff, 2026-08-25 : "la troupe doit revenir toute
        // seule") sans passer par l'ouverture de l'Armee/de la fenetre Patrouille - chaque relecture
        // reclame automatiquement (AutoClaimFinishedEncountersAsync) toute rencontre terminee.
        internal static void RefreshCombatPatrolForWorldMap() => combatPatrolController?.Refresh();

        // Mission M021 (2026-08-26) : jeton de champion actuellement assigne (portee ruche
        // entiere, pas par marche - voir ChampionBeeProgressState.AssignedBeeIds) reutilise tel
        // quel pour representer le chef de formation sur la marche de combat de la carte du
        // monde. Deja charge par EnsureOfficialChampionBeeAndTroopTierStateLoaded pour l'ecran
        // Abeilles championnes - aucun nouvel appel reseau ici.
        internal static IReadOnlyList<string> PeekAssignedChampionBeeIdsForWorldMap()
            => officialAssignedChampionBeeIds ?? (IReadOnlyList<string>)Array.Empty<string>();

        // Recu de reclamation le plus recent pour une rencontre (mission M021) - permet a la
        // marche de retour de la carte du monde d'afficher la vraie composition de survivants
        // (CommittedTroops moins PermanentLosses) au lieu de rejouer la composition d'avant-combat
        // quand le recu a ete conserve (reclamation manuelle ou automatique).
        internal static bool TryGetCombatPatrolClaimReceiptForWorldMap(Guid encounterId, out RemoteCombatPatrolClaimReceipt receipt)
        {
            receipt = null;
            return combatPatrolController != null && combatPatrolController.TryGetRecentClaimReceipt(encounterId, out receipt);
        }

        internal static void DrawCombatPatrolOverlayForWorldMap()
        {
            DrawCombatPatrolQueueStrip();
            if (!combatPatrolOverlayOpen) return;
            EnsureStyles();
            DrawCombatPatrolPanel();
        }

        // Always-visible strip (even with the overlay closed) so a launched patrol never traps the
        // player behind a modal — matches Jeff's request: launching closes the panel and the
        // patrol shows up in a queue the player can keep glancing at while doing other things.
        private static void DrawCombatPatrolQueueStrip()
        {
            CombatPatrolScreenModel model = combatPatrolController.Model;
            if (model.ActiveEncounters == null || model.ActiveEncounters.Count == 0) return;
            EnsureStyles();
            float chipWidth = 148f;
            float chipHeight = 40f;
            float x = 12f;
            float y = 12f;
            for (int i = 0; i < model.ActiveEncounters.Count; i++)
            {
                RemoteCombatPatrolActiveEncounter encounter = model.ActiveEncounters[i];
                TimeSpan remaining = encounter.EndsAtUtc - DateTimeOffset.UtcNow;
                bool ready = remaining <= TimeSpan.Zero;
                Rect chip = new Rect(x + i * (chipWidth + 8f), y, chipWidth, chipHeight);
                DrawPremiumPanel(chip, ready ? new Color(0.10f, 0.09f, 0.03f, 0.92f) : new Color(0.02f, 0.02f, 0.018f, 0.86f), ready ? new Color(1f, 0.75f, 0.25f, 0.95f) : new Color(0.55f, 0.42f, 0.20f, 0.55f));
                string label = "T" + encounter.Tier.ToString(CultureInfo.InvariantCulture) + " · " + (ready ? BeeLocalization.Text("combat.patrol.ready", "Pret") : remaining.ToString(@"mm\:ss"));
                if (GUI.Button(chip, label, GUIStyle.none)) OpenCombatPatrolEncounterForWorldMap(encounter.EncounterId);
                GUI.Label(chip, label, centeredTinyLabelStyle);
            }
        }

        private static void DrawCombatPatrolPanel()
        {
            CombatPatrolScreenModel model = combatPatrolController.Model;
            Rect panel = new Rect(Screen.width / 2f - 220f, Screen.height / 2f - 230f, 440f, 460f);
            DrawPremiumPanel(panel, new Color(0.026f, 0.024f, 0.020f, 0.95f), new Color(0.92f, 0.64f, 0.18f, 0.82f));
            DrawPremiumHeaderBand(new Rect(panel.x + 8f, panel.y + 8f, panel.width - 16f, 46f));
			string title = model.SelectedEncounterId.HasValue
				? BeeLocalization.Text("combat.patrol.title", "Patrouille") + " — T" + (model.SelectedEncounter?.Tier ?? model.SelectedTier).ToString(CultureInfo.InvariantCulture)
				: BeeLocalization.Text("combat.patrol.title", "Patrouille") + " — T" + model.SelectedTier.ToString(CultureInfo.InvariantCulture);
			if (DrawPremiumBackButton(new Rect(panel.x + 10f, panel.y + 9f, 44f, 44f))) { AudioManager.Instance?.PlayUIClick(); AudioManager.Instance?.PlayMenuClose(); combatPatrolOverlayOpen = false; return; }
			GUI.Label(new Rect(panel.x + 58f, panel.y + 15f, panel.width - 70f, 28f), title, titleStyle);

            float y = panel.y + 62f;

            if (model.State == CombatPatrolScreenState.Debrief && model.Debrief != null)
            {
                CombatPatrolDebrief debrief = model.Debrief;
                // Voix des Championnes (demande de Jeff, 2026-08-02) : une victoire ecrasante est un
                // moment "memorable" au sens de Jeff - garde d'unicite par EncounterId puisque ce
                // rapport se redessine a chaque frame tant qu'il reste ouvert.
                if (string.Equals(debrief.Band, "DecisiveVictory", StringComparison.Ordinal) && debrief.EncounterId != championVoiceLastVictoryEncounterId)
                {
                    championVoiceLastVictoryEncounterId = debrief.EncounterId;
                    ChampionVoiceBarkController.BarkForVictory(debrief.ContributingChampionBeeIds);
                }
                // Souvenir dans la ruche (demande de Jeff, 2026-08-03) : une victoire ecrasante OU
                // remportee pendant une menace en hausse (meme declencheur que le badge "Legendaire"
                // du Bestiaire) laisse une trace breve et rare au prochain passage dans LivingHive -
                // jamais pour un combat ordinaire. Garde d'unicite independante de celle des
                // Championnes ci-dessus (les deux reagissent au meme evenement mais restent decouplees).
                bool hiveMemoryWorthy = string.Equals(debrief.Band, "DecisiveVictory", StringComparison.Ordinal) || debrief.WorldEventApplied;
                if (hiveMemoryWorthy && debrief.EncounterId != hiveVictoryMemoryLastEncounterId)
                {
                    hiveVictoryMemoryLastEncounterId = debrief.EncounterId;
                    StampHiveVictoryMemory(debrief.WorldEventApplied);
                }
                // Premiere creature sauvage nommee dans le rapport (demande de Jeff) : reutilise
                // EnemyName deja renvoye par le vrai serveur (CombatPatrolCatalog, meme catalogue
                // que celui qui affiche deja ce nom dans l'aperçu avant lancement) plutot que
                // d'inventer une nouvelle donnee - aucun changement serveur necessaire.
                string creatureName = model.Preview?.EnemyName;
                if (!string.IsNullOrEmpty(creatureName))
                {
                    GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 24f), BeeLocalization.Text("combat.patrol.creature", "Creature") + ": " + creatureName, smallStyle); y += 26f;
                }
                GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 24f), BeeLocalization.Text("combat.patrol.outcome", "Issue") + ": " + debrief.Band, smallStyle); y += 26f;
                if (debrief.RequiredPower > 0)
                {
                    GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f),
                        BeeLocalization.Text("combat.patrol.power", "Puissance requise/disponible") + ": " + debrief.RequiredPower + " / " + debrief.AvailablePower,
                        tinyLabelStyle);
                    y += 22f;
                }
                GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 24f), BeeLocalization.Text("combat.patrol.loot", "Butin") + ": " + debrief.CreditedByResource.GetValueOrDefault("honey") + " " + BeeLocalization.Text("resource.honey", "miel") + " / " + debrief.CreditedByResource.GetValueOrDefault("pollen") + " " + BeeLocalization.Text("resource.pollen", "pollen"), smallStyle); y += 26f;
                // Cible du jour (demande de Jeff, 2026-07-31) : ce palier est designe "cible du
                // jour" et le butin ci-dessus inclut deja le bonus - le joueur doit comprendre
                // pourquoi le butin est plus genereux que d'habitude, pas juste le constater.
                if (debrief.DailyFocusApplied)
                {
                    GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f),
                        BeeLocalization.Text("combat.patrol.daily_focus", "Cible du jour : butin +50% deja inclus"),
                        new GUIStyle(tinyLabelStyle) { wordWrap = true, normal = { textColor = new Color(1f, 0.68f, 0.20f, 1f) } });
                    y += 26f;
                }
                // Evenement mondial dynamique (demande de Jeff, 2026-08-01) : la menace du moment
                // a deja modifie le butin ci-dessus - meme raisonnement que la Cible du jour, mais
                // cette source change plusieurs fois par jour au lieu d'une fois par jour.
                if (debrief.WorldEventApplied)
                {
                    GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f),
                        string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("world_event.combat.applied", "{0} : butin +25% deja inclus"), WorldEventDisplayName(debrief.WorldEventKey)),
                        new GUIStyle(tinyLabelStyle) { wordWrap = true, normal = { textColor = new Color(0.86f, 0.42f, 0.32f, 1f) } });
                    y += 26f;
                }
                // Rapport de combat explicatif (demande de Jeff) : chaque source de bonus reelle
                // s'affiche sur sa propre ligne, pour que le joueur comprenne toujours pourquoi il
                // a gagne (ou perdu) - palier de troupe d'abord, puis championnes. De futures
                // sources (recherche, batiments, alliance) s'ajouteront ici de la meme facon.
                string troopTierText = CombatPatrolTroopTierBonusText(debrief);
                if (!string.IsNullOrEmpty(troopTierText))
                {
                    GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f), troopTierText,
                        new GUIStyle(tinyLabelStyle) { wordWrap = true, normal = { textColor = new Color(0.62f, 0.86f, 1f, 1f) } });
                    y += 30f;
                }
                if (debrief.ContributingChampionBeeIds != null && debrief.ContributingChampionBeeIds.Count > 0)
                {
                    GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f), CombatPatrolChampionBonusText(debrief),
                        new GUIStyle(tinyLabelStyle) { wordWrap = true, normal = { textColor = new Color(1f, 0.82f, 0.42f, 1f) } });
                    y += 30f;
                }
                string strategicPathLine = CombatPatrolStrategicPathBonusText(debrief);
                if (!string.IsNullOrEmpty(strategicPathLine))
                {
                    GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f), strategicPathLine,
                        new GUIStyle(tinyLabelStyle) { wordWrap = true, normal = { textColor = new Color(0.76f, 0.92f, 0.60f, 1f) } });
                    y += 30f;
                }
                foreach (KeyValuePair<string, long> loss in debrief.WoundedLosses) if (loss.Value > 0) { GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f), loss.Key + ": " + loss.Value + " " + BeeLocalization.Text("combat.patrol.wounded", "blessee(s), en convalescence"), tinyLabelStyle); y += 20f; }
                foreach (KeyValuePair<string, long> loss in debrief.PermanentLosses) if (loss.Value > 0) { GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f), loss.Key + ": " + loss.Value + " " + BeeLocalization.Text("combat.patrol.lost", "perte(s) definitive(s)"), tinyLabelStyle); y += 20f; }
                if (GUI.Button(new Rect(panel.x + 12f, panel.yMax - 54f, panel.width - 24f, 40f), "OK")) combatPatrolController.DismissDebrief();
                return;
            }

            if (model.SelectedEncounterId.HasValue && model.SelectedEncounter != null)
            {
                RemoteCombatPatrolActiveEncounter encounter = model.SelectedEncounter;
                foreach (KeyValuePair<string, long> troop in encounter.CommittedTroops) if (troop.Value > 0)
                { GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 22f), troop.Key + ": " + troop.Value, tinyLabelStyle); y += 20f; }
                y += 6f;
                TimeSpan remaining = model.RemainingAtRead;
                GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 24f), remaining > TimeSpan.Zero ? BeeLocalization.Text("combat.patrol.in_progress", "En patrouille...") + " " + remaining.ToString(@"mm\:ss") : BeeLocalization.Text("combat.patrol.returned", "De retour"), smallStyle);
                y += 30f;
                // Retour visuel explicite pendant la mutation (demande de Jeff, 2026-08-26) : sans
                // ca, un clic sur Rappeler/Reclamer semble ne rien faire pendant l'aller-retour
                // reseau, et un second clic peut consommer un deuxieme jeton de rappel pour rien.
                bool mutating = model.State == CombatPatrolScreenState.Mutating;
                GUI.enabled = model.CanClaim && !mutating;
                string claimLabel = mutating ? BeeLocalization.Text("combat.patrol.working", "...") : BeeLocalization.Text("combat.patrol.claim", "Reclamer");
                if (GUI.Button(new Rect(panel.x + 12f, y, panel.width - 24f, 40f), claimLabel)) combatPatrolController.Claim();
                y += 46f;
                GUI.enabled = model.CanRecall && !mutating;
                string recallLabel = (mutating ? BeeLocalization.Text("combat.patrol.working", "...") : BeeLocalization.Text("combat.patrol.recall", "Rappeler")) + " (" + model.RecallTokenCount.ToString(CultureInfo.InvariantCulture) + ")";
                if (GUI.Button(new Rect(panel.x + 12f, y, panel.width - 24f, 34f), recallLabel)) combatPatrolController.Recall();
                GUI.enabled = true;
                y += 38f;
                if (model.RecallTokenCount <= 0)
                {
                    GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f), BeeLocalization.Text("combat.patrol.recall_no_token", "Aucun jeton de rappel"), tinyLabelStyle);
                    y += 20f;
                }
                y += 4f;
                if (GUI.Button(new Rect(panel.x + 12f, y, panel.width - 24f, 30f), BeeLocalization.Text("combat.patrol.back_to_composer", "Retour a la composition"))) combatPatrolController.ClearSelection();
                if (model.State == CombatPatrolScreenState.Error)
                    GUI.Label(new Rect(panel.x + 12f, panel.yMax - 46f, panel.width - 24f, 34f), BeeLocalization.Text("combat.patrol.error", "Erreur") + ": " + model.ErrorCode, tinyLabelStyle);
                return;
            }

            Rect tierRow = new Rect(panel.x + 12f, y, panel.width - 24f, 32f);
            GUI.BeginGroup(tierRow);
            float tierW = tierRow.width / 7f;
            for (int t = 1; t <= 7; t++)
            {
                bool selected = model.SelectedTier == t;
                // Cible du jour (demande de Jeff, 2026-07-31) : le palier du jour ressort avant
                // meme de lancer un combat, pour que le choix se fasse au moment de decider quoi
                // faire aujourd'hui, pas seulement en relisant le rapport apres coup.
                bool isFeatured = model.FeaturedTier == t;
                // Localisation (demande de Jeff, 2026-08-01) : contrairement a la Cible du jour
                // ci-dessus, une "menace en hausse" ne marque plus qu'UN SEUL palier precis parmi
                // ceux de sa famille - le joueur doit reperer LEQUEL, pas juste la famille.
                bool isWorldEventFeatured = model.WorldEventFeaturedTier == t;
                Color previousColor = GUI.color;
                if (isWorldEventFeatured && !selected) GUI.color = new Color(0.86f, 0.42f, 0.32f, 1f);
                else if (isFeatured && !selected) GUI.color = new Color(1f, 0.82f, 0.42f, 1f);
                string suffix = (isFeatured ? " *" : string.Empty) + (isWorldEventFeatured ? " !" : string.Empty);
                if (GUI.Toggle(new Rect((t - 1) * tierW, 0f, tierW - 2f, 30f), selected, "T" + t.ToString(CultureInfo.InvariantCulture) + suffix, "Button") && !selected)
                    combatPatrolController.SelectTier(t);
                GUI.color = previousColor;
            }
            GUI.EndGroup();
            y += 40f;
            if (model.FeaturedTier >= 1 && model.FeaturedTier <= 7)
            {
                GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f),
                    string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("combat.patrol.daily_focus_hint", "* Cible du jour (T{0}) : butin +50%"), model.FeaturedTier),
                    new GUIStyle(tinyLabelStyle) { normal = { textColor = new Color(1f, 0.82f, 0.42f, 1f) } });
                y += 22f;
            }
            // Evenement mondial dynamique, localise (demande de Jeff, 2026-08-01) : contrairement a
            // la Cible du jour ci-dessus (fixe pour la journee), cette banniere change plusieurs
            // fois par jour - seule une "menace en hausse" affecte reellement le combat ici, et
            // seulement sur LE palier precis nomme (marque "!" ci-dessus), pas toute sa famille.
            if (model.WorldEvent != null && string.Equals(model.WorldEvent.Kind, "ThreatSurge", StringComparison.Ordinal) && model.WorldEventFeaturedTier.HasValue)
            {
                GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f),
                    string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("world_event.combat.hint", "{0} : T{1} butin +25% jusqu'a {2:HH:mm}"), WorldEventDisplayName(model.WorldEvent.Key), model.WorldEventFeaturedTier.Value, model.WorldEvent.EndsAtUtc.ToLocalTime()),
                    new GUIStyle(tinyLabelStyle) { normal = { textColor = new Color(0.86f, 0.42f, 0.32f, 1f) } });
                y += 22f;
            }

            GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 22f), BeeLocalization.Text("combat.patrol.slots", "Emplacements") + ": " + model.UsedSlots + " / " + model.TotalSlots, tinyLabelStyle);
            y += 22f;
            if (model.CanPurchaseResourceSlot)
            {
                string cost = model.NextResourceSlotCost.Honey + " " + BeeLocalization.Text("resource.honey", "miel") + " / " + model.NextResourceSlotCost.Pollen + " " + BeeLocalization.Text("resource.pollen", "pollen");
                if (GUI.Button(new Rect(panel.x + 12f, y, panel.width - 24f, 30f), BeeLocalization.Text("combat.patrol.buy_slot", "Debloquer un emplacement") + " (" + cost + ")")) combatPatrolController.PurchaseResourceSlot();
                y += 34f;
            }

            DrawCombatPatrolDraftRow(panel, ref y, "guardians", BeeLocalization.Text("combat.family.guardians", "Gardiennes"), model.DraftGuardians);
            DrawCombatPatrolDraftRow(panel, ref y, "wingrunners", BeeLocalization.Text("combat.family.wingrunners", "Voltigeuses"), model.DraftWingrunners);
            DrawCombatPatrolDraftRow(panel, ref y, "darters", BeeLocalization.Text("combat.family.darters", "Lanceuses"), model.DraftDarters);
            y += 4f;
            GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 20f), BeeLocalization.Text("combat.patrol.capacity", "Capacite") + ": " + model.DraftTotal + " / " + model.Capacity, tinyLabelStyle);
            y += 24f;

            if (DrawPreviewActionButton(new Rect(panel.x + 12f, y, panel.width - 24f, 28f),
                BeeLocalization.Text("champion_bees.entry_button", "Abeilles championnes") + " (" + localPreviewAssignedChampionBeeIds.Count + "/" + CurrentMaxAssignedChampionBees() + ")", true, true))
            {
                championBeesPanelOpen = true;
                championBeesPanelAnimationStartedAt = NowForUi();
                AudioManager.Instance?.PlayMenuOpen();
            }
            y += 32f;

            GUI.Label(
                new Rect(panel.x + 12f, y, panel.width - 24f, 20f),
                BeeLocalization.Text("champion_bees.combat_summary_prefix", "Bonus championnes (apercu local)") + ": " + ChampionBeeCombatSummaryLine(),
                new GUIStyle(tinyLabelStyle) { wordWrap = true });
            y += 26f;

            RemoteCombatPatrolPreview preview = model.Preview;
            if (preview != null)
            {
                string enemyLine = preview.EnemyName + " (" + preview.HazardFamily + ")" +
                    (preview.IsWorldEventBoosted ? " " + BeeLocalization.Text("world_event.combat.tier_marker", "[menace en hausse +25%]") : string.Empty);
                GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 24f), enemyLine, smallStyle); y += 26f;
                GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 24f), BeeLocalization.Text("combat.patrol.power", "Puissance requise/disponible") + ": " + preview.RequiredPower + " / " + preview.AvailablePower, tinyLabelStyle); y += 22f;
                if (!preview.CanLaunch)
                {
                    GUI.Label(new Rect(panel.x + 12f, y, panel.width - 24f, 24f), BeeLocalization.Text("combat.patrol.blocked", "Bloque") + ": " + preview.BlockReason, tinyLabelStyle);
                    y += 24f;
                }
            }

            bool hasSquadForChampion = MobileAccountSessionRuntimeBootstrap.SquadReservationControllerForHiveMap?.Model?.HasReservation ?? false;
            bool championRequirementMet = model.DraftTotal <= 0 || localPreviewAssignedChampionBeeIds.Count > 0 || hasSquadForChampion;
            if (!championRequirementMet)
            {
                GUI.Label(
                    new Rect(panel.x + 12f, y, panel.width - 24f, 24f),
                    BeeLocalization.Text("champion_bees.escort_required", "Une abeille championne doit accompagner tes troupes."),
                    new GUIStyle(tinyLabelStyle) { wordWrap = true });
                y += 26f;
            }

            GUI.enabled = model.CanLaunch && championRequirementMet;
            if (GUI.Button(new Rect(panel.x + 12f, y, panel.width - 24f, 44f), BeeLocalization.Text("combat.patrol.launch", "Lancer la patrouille")))
            {
                ChampionVoiceBarkController.BarkForPatrolLaunch(localPreviewAssignedChampionBeeIds, new Dictionary<string, long>
                {
                    ["guardians"] = model.DraftGuardians,
                    ["wingrunners"] = model.DraftWingrunners,
                    ["darters"] = model.DraftDarters
                });
                combatPatrolController.Launch();
                combatPatrolOverlayOpen = false;
                return;
            }
            GUI.enabled = true;

            if (model.State == CombatPatrolScreenState.Error)
                GUI.Label(new Rect(panel.x + 12f, panel.yMax - 46f, panel.width - 24f, 34f), BeeLocalization.Text("combat.patrol.error", "Erreur") + ": " + model.ErrorCode, tinyLabelStyle);
        }

        // Rend concret, dans le debrief, l'effet reel d'une abeille championne assignee sur ce
        // combat precis (demande explicite de Jeff) - le serveur calcule deja ce bonus dans
        // CombatPatrolResolution/ChampionBeeCatalog.CombatContribution, ceci n'en est que l'affichage.
        private static string CombatPatrolChampionBonusText(CombatPatrolDebrief debrief)
        {
            string names = string.Join(", ", debrief.ContributingChampionBeeIds.Select(id =>
                ChampionBeeCatalog.TryResolve(id, out ChampionBeeDefinition championDefinition)
                    ? ChampionBeeName(championDefinition)
                    : id));
            List<string> bonusParts = new List<string>();
            if (debrief.ChampionPowerBonusBpByFamily != null)
            {
                foreach (KeyValuePair<string, long> entry in debrief.ChampionPowerBonusBpByFamily)
                    if (entry.Value > 0)
                        bonusParts.Add(CombatFamilyLabel(entry.Key) + " +" + (entry.Value / 100d).ToString("0.#", CultureInfo.CurrentCulture) + "%");
            }
            string bonusText = bonusParts.Count > 0
                ? string.Join(" · ", bonusParts)
                : BeeLocalization.Text("combat.patrol.champion_bonus_present", "escorte presente");
            return string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("combat.patrol.champion_bonus", "Grace a {0} : {1}"), names, bonusText);
        }

        // Meme principe que CombatPatrolChampionBonusText, pour la contribution du palier de
        // troupe (T1-T3) - vide si aucune famille engagee n'a depasse le palier 1.
        private static string CombatPatrolTroopTierBonusText(CombatPatrolDebrief debrief)
        {
            if (debrief.TroopTierByFamily == null || debrief.TroopPowerBonusBpByFamily == null) return string.Empty;
            List<string> parts = new List<string>();
            foreach (KeyValuePair<string, long> entry in debrief.TroopPowerBonusBpByFamily)
            {
                if (entry.Value <= 0) continue;
                int tier = debrief.TroopTierByFamily.GetValueOrDefault(entry.Key, 1);
                parts.Add(CombatFamilyLabel(entry.Key) + " T" + tier.ToString(CultureInfo.InvariantCulture) +
                    " +" + (entry.Value / 100d).ToString("0.#", CultureInfo.CurrentCulture) + "%");
            }
            if (parts.Count == 0) return string.Empty;
            return BeeLocalization.Text("combat.patrol.troop_tier_bonus", "Palier de troupe") + " : " + string.Join(" · ", parts);
        }

        // Troisieme source de bonus de combat suivie separement dans le rapport explicatif
        // (apres championnes et palier de troupe) - le chemin strategique (choix permanent de
        // classe) accorde un petit bonus de puissance a royal_guard/striker uniquement.
        private static string CombatPatrolStrategicPathBonusText(CombatPatrolDebrief debrief)
        {
            if (string.IsNullOrEmpty(debrief.StrategicPathId) || debrief.StrategicPathPowerBonusBpByFamily == null) return string.Empty;
            List<string> parts = new List<string>();
            foreach (KeyValuePair<string, long> entry in debrief.StrategicPathPowerBonusBpByFamily)
            {
                if (entry.Value <= 0) continue;
                parts.Add(CombatFamilyLabel(entry.Key) + " +" + (entry.Value / 100d).ToString("0.#", CultureInfo.CurrentCulture) + "%");
            }
            if (parts.Count == 0) return string.Empty;
            string pathName = HiveStrategicPathCatalog.TryResolve(debrief.StrategicPathId, out HiveStrategicPathDefinition definition)
                ? BeeLocalization.Text(definition.NameKey, StrategicPathFallbackName(definition.ClassId))
                : debrief.StrategicPathId;
            return string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("combat.patrol.strategic_path_bonus", "Voie stratégique ({0}) : {1}"),
                pathName, string.Join(" · ", parts));
        }

        private static string CombatFamilyLabel(string family)
        {
            if (string.Equals(family, "guardians", StringComparison.Ordinal)) return BeeLocalization.Text("combat.family.guardians", "Gardiennes");
            if (string.Equals(family, "wingrunners", StringComparison.Ordinal)) return BeeLocalization.Text("combat.family.wingrunners", "Voltigeuses");
            if (string.Equals(family, "darters", StringComparison.Ordinal)) return BeeLocalization.Text("combat.family.darters", "Lanceuses");
            return family;
        }

        // Evenement mondial dynamique (demande de Jeff, 2026-08-01) : nom d'affichage pour chacune
        // des 6 entrees du catalogue serveur WorldEventCatalog (cle stable, jamais affichee brute).
        // Interne (pas prive) car WorldMapMmoFullscreenFoundationBootstrap l'utilise aussi pour
        // l'etiquette des noeuds de collecte sur la carte.
        internal static string WorldEventDisplayName(string key)
        {
            switch (key)
            {
                case "blossom": return BeeLocalization.Text("world_event.name.blossom", "Floraison exceptionnelle");
                case "rain": return BeeLocalization.Text("world_event.name.rain", "Pluie abondante");
                case "drought": return BeeLocalization.Text("world_event.name.drought", "Sécheresse locale");
                case "ant_invasion": return BeeLocalization.Text("world_event.name.ant_invasion", "Invasion de fourmis");
                case "spider_surge": return BeeLocalization.Text("world_event.name.spider_surge", "Activité accrue des araignées");
                case "hornet_swarm": return BeeLocalization.Text("world_event.name.hornet_swarm", "Essaim de frelons");
                default: return key ?? string.Empty;
            }
        }

        private static void DrawCombatPatrolDraftRow(Rect panel, ref float y, string family, string label, int value)
        {
            Rect row = new Rect(panel.x + 12f, y, panel.width - 24f, 30f);
            GUI.Label(new Rect(row.x, row.y + 4f, row.width - 100f, 22f), label + ": " + value.ToString(CultureInfo.InvariantCulture), smallStyle);
            if (GUI.Button(new Rect(row.xMax - 92f, row.y, 40f, 28f), "-")) combatPatrolController.AdjustDraft(family, -1);
            if (GUI.Button(new Rect(row.xMax - 46f, row.y, 40f, 28f), "+")) combatPatrolController.AdjustDraft(family, 1);
            y += 34f;
        }

        // Sprint-015 : le bouton est le seul point d'entree visible du systeme de
        // communication. La fenetre flottante partage l'etat et les donnees du Chat Premium.
        private static void DrawWorldMapChatButton()
        {
            EnsureChatData();
            DrawChatEntryButton(WorldMapChatButtonRect(), IsPortraitLayout());
        }

        private static void DrawChatEntryButton(Rect button, bool compact)
        {
            int unread = ChatUnreadTotal();
            DrawPremiumPanel(button, new Color(0.028f, 0.024f, 0.018f, 0.96f), new Color(0.86f, 0.58f, 0.16f, 0.82f));
            DrawChatRailAttention(button);
            DrawGameIcon(new Rect(button.x + 8f, button.y + (button.height - 24f) * 0.5f, 24f, 24f), "messages", Color.white);
            GUI.Label(new Rect(button.x + 38f, button.y + 4f, button.width - 78f, button.height - 8f), "Chat", new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 10 : 11 });
            if (unread > 0)
            {
                string badge = unread > 9 ? "9+" : unread.ToString(CultureInfo.InvariantCulture);
                DrawMiniChatBadge(new Rect(button.xMax - 34f, button.y + 5f, 26f, 17f), badge);
            }
            if (GUI.Button(button, string.Empty, GUIStyle.none)) ToggleMiniChat();
        }

private static void DrawMiniChatFloating(bool compact, bool worldMap)
        {
            if (!communicationPanelOpen || !MiniChatFloatingShouldRender(worldMap)) return;
            EnsureChatData();
            EnsureMiniChatSelection();

            Rect panel = MiniChatFloatingOcclusionRect(worldMap);
            float fade = UIAnimationLibrary.GetFadeProgress("communication", 1f);
            DrawPremiumPanel(panel, new Color(0.024f, 0.021f, 0.017f, 0.985f * fade), new Color(0.92f, 0.64f, 0.18f, 0.90f * fade));

			float headerHeight = 46f;
			Rect header = new Rect(panel.x + 8f, panel.y + 8f, panel.width - 16f, headerHeight);
			DrawPremiumHeaderBand(header);
			string channel = MiniChatResolvedChannel();
			int unread = MiniChatUnreadForChannel(channel);
			if (DrawPremiumBackButton(new Rect(header.x + 2f, header.y + 1f, 44f, 44f)))
			{
				CloseMiniChat();
				return;
			}
			Rect cycleButton = new Rect(header.x + 50f, header.y + 9f, 30f, 28f);
			if (DrawPremiumHitButton(cycleButton, "↻", 13))
            {
                AudioManager.Instance?.PlayUIClick();
                SetMiniChatWatchMode(MiniChatCycleNextMode());
                PrepareMiniChatSelection();
                return;
            }
			GUI.Label(new Rect(header.x + 84f, header.y + 5f, header.width - 242f, 22f), MiniChatChannelDisplayName(channel), new GUIStyle(badgeStyle) { fontSize = compact ? 11 : 12 });
			GUI.Label(new Rect(header.x + 84f, header.y + 25f, header.width - 242f, 14f), "Mini-chat · " + MiniChatWatchModeSuffix(), new GUIStyle(tinyLabelStyle) { fontSize = 8 });
            if (unread > 0) DrawMiniChatBadge(new Rect(header.xMax - 154f, header.y + 12f, 32f, 18f), unread > 9 ? "9+" : unread.ToString(CultureInfo.InvariantCulture));
            bool blinking = unread > 0 && MiniChatBlinkVisible();
Rect blinkToggle = new Rect(header.xMax - 184f, header.y + 9f, 24f, 24f);
            DrawMiniChatBlinkDot(new Rect(blinkToggle.x + 6f, blinkToggle.y + 6f, 12f, 12f), blinking);
			if (DrawPremiumHitButton(blinkToggle, string.Empty, 0))
            {
                AudioManager.Instance?.PlayUIClick();
                SetMiniChatBlinkEnabled(!miniChatBlinkEnabled);
                return;
            }

            Rect openButton = new Rect(header.xMax - 112f, header.y + 7f, 62f, 28f);
            if (GUI.Button(openButton, "Ouvrir"))
            {
                AudioManager.Instance?.PlayUIClick();
                OpenChatScreenForMiniChat();
                return;
            }

			Rect titleHit = new Rect(header.x + 84f, header.y + 2f, header.width - 254f, header.height - 4f);
            if (GUI.Button(titleHit, string.Empty, GUIStyle.none))
            {
                AudioManager.Instance?.PlayUIClick();
                OpenChatScreenForMiniChat();
                return;
            }

            float composerHeight = compact ? 58f : 54f;
            Rect composer = new Rect(panel.x + 8f, panel.yMax - composerHeight - 8f, panel.width - 16f, composerHeight);
            float bodyTop = header.yMax + 8f;
            float bodyBottom = composer.y - 8f;
            List<ChatMessageData> recent = MiniChatRecentMessages(channel, 8);
            int rowCount = Mathf.Clamp(Mathf.FloorToInt((bodyBottom - bodyTop) / 27f), 1, 8);
            rowCount = Mathf.Min(rowCount, recent.Count);
            if (rowCount == 0)
            {
                GUI.Label(new Rect(panel.x + 16f, bodyTop + 8f, panel.width - 32f, 36f), "Aucun message dans ce canal.", new GUIStyle(centeredTinyLabelStyle) { fontSize = 10 });
            }
            else
            {
                float rowTop = bodyTop;
                for (int i = 0; i < rowCount; i++)
                {
                    ChatMessageData message = recent[i];
                    Rect row = new Rect(panel.x + 10f, rowTop, panel.width - 20f, 25f);
                    DrawPremiumPanel(row, new Color(0.045f, 0.035f, 0.022f, 0.88f), new Color(0.48f, 0.34f, 0.14f, 0.48f));
                    string author = string.IsNullOrWhiteSpace(message.Author) ? "Joueur" : message.Author;
                    GUI.Label(new Rect(row.x + 6f, row.y + 1f, row.width - 94f, 13f), author + " · " + message.TimeLabel, new GUIStyle(badgeStyle) { fontSize = 8 });
                    GUI.Label(new Rect(row.x + 6f, row.y + 13f, row.width - 12f, 12f), MiniChatTruncate(message.Text, compact ? 42 : 64), new GUIStyle(tinyLabelStyle) { fontSize = 8 });
                    if (GUI.Button(row, string.Empty, GUIStyle.none))
                    {
                        AudioManager.Instance?.PlayUIClick();
                        OpenChatScreenForMiniChat();
                        return;
                    }
                    rowTop += 27f;
                }
            }

            ChatConversationData conversation = ChatConversationById(chatSelectedConversation);
            if (conversation == null || conversation.ReadOnly)
            {
                GUI.Label(new Rect(composer.x, composer.y + 8f, composer.width, composer.height - 16f), "Conversation en lecture seule.", new GUIStyle(centeredTinyLabelStyle) { fontSize = 9 });
            }
            else
            {
                DrawChatComposer(composer, compact);
            }
        }

        private static bool MiniChatFloatingShouldRender(bool worldMap)
        {
            if (worldMap) return !combatPatrolOverlayOpen;
            if (courierScreenOpen || friendsScreenOpen || chatScreenOpen || activeHiveMenu == HiveMenuMode.Research) return false;
            if (!string.IsNullOrEmpty(activeMainMenuId)) return false;
            if (activeHiveMenu == HiveMenuMode.Alliance || activeHiveMenu == HiveMenuMode.Army) return false;
            if (referenceHotspotSelected && !detailPanelClosed) return false;
            if (strategicPathPanelOpen || formationReadinessOpen || milestoneEventOverlayOpen || bestiaryCodexOverlayOpen) return false;
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.Inactive) return false;
            return true;
        }

