        private static Rect ChatRailButtonRect(bool portrait) => ChatRailButtonRectForProof(portrait, Screen.width, Screen.height);

public static Rect ChatRailButtonRectForProof(bool portrait, float screenWidth, float screenHeight)
        {
            Rect rail = portrait
                ? new Rect(8f, screenHeight - 78f, screenWidth - 16f, 70f)
                : new Rect(8f, screenHeight - 76f, screenWidth - 16f, 68f);
            int itemCount = portrait ? 5 : 10;
            int chatIndex = portrait ? 0 : 7;
            float gap = 8f;
            float itemWidth = (rail.width - 20f - gap * (itemCount - 1)) / itemCount;
            float yInset = portrait ? 8f : 7f;
            float heightInset = portrait ? 16f : 14f;
            return new Rect(rail.x + 10f + chatIndex * (itemWidth + gap), rail.y + yInset, itemWidth, rail.height - heightInset);
        }

        public static Rect[] MobileBottomRailItemRectsForProof(float screenWidth, float screenHeight)
        {
            Rect rail = new Rect(8f, screenHeight - 78f, screenWidth - 16f, 70f);
            const int itemCount = 5;
            const float gap = 8f;
            float itemWidth = (rail.width - 20f - gap * (itemCount - 1)) / itemCount;
            Rect[] result = new Rect[itemCount];
            for (int i = 0; i < itemCount; i++)
            {
                result[i] = new Rect(rail.x + 10f + i * (itemWidth + gap), rail.y + 8f, itemWidth, rail.height - 16f);
            }
            return result;
        }

