        public static Rect MobileHudResourceChipsRectForProof(float screenWidth, float screenHeight)
        {
            Rect panel = MobileHudRectForProof(screenWidth, screenHeight);
            float gap = 6f;
            float chipY = panel.y + 52f;
            float chipH = panel.yMax - chipY - 6f;
            float chipW = (panel.width - 22f - gap * 2f) / 3f;
            return new Rect(panel.x + 11f, chipY, chipW, chipH);
        }

