        public static Rect MiniChatFloatingRectForProof(bool portrait, float screenWidth, float screenHeight, bool worldMap)
        {
            float bottom = worldMap
                ? (portrait ? screenHeight - 190f - 8f - 56f : screenHeight - 108f) - 10f
                : (portrait ? screenHeight - 78f : screenHeight - 76f) - 10f;
            float safeTop = portrait ? 126f : 112f;
            float width = portrait ? screenWidth - 20f : Mathf.Min(520f, screenWidth * 0.46f);
            float desiredHeight = portrait ? 330f : 360f;
            float availableHeight = Mathf.Max(160f, bottom - safeTop);
            float height = Mathf.Min(desiredHeight, availableHeight);
            float x = portrait ? 10f : 12f;
            if (!portrait && bottom - height < 306f) x = Mathf.Max(12f, screenWidth - width - 12f);
            return new Rect(x, bottom - height, width, height);
        }

        // =================================================================================
        // Centre de Missions (Sprint-016) : logique de progression, navigation et rendu.
        // Le catalogue (MissionCatalog.cs) fournit les donnees ; cette region transpose le
        // catalogue en progression lisible (etat reel du royaume ou credits simules), ouvre
        // les modules associes au clic, et dessine l'ecran plein + le widget de missions
        // echangees sur la Ruche et la carte du monde.
        // =================================================================================

        private static void OpenMissionsCenter()
        {
            missionsCenterOpen = true;
            missionsCenterOpenedAt = NowForUi();
            missionsToast = string.Empty;
            missionsToastAt = -10f;
            missionsExpandedChapter = string.Empty;
            activeMainMenuId = string.Empty;
            activeHiveMenu = HiveMenuMode.Hive;
            AudioManager.Instance?.PlayMenuOpen();
        }

        private static void CloseMissionsCenter()
        {
            missionsCenterOpen = false;
            AudioManager.Instance?.PlayMenuClose();
        }

        private static void ShowMissionsToast(string message)
        {
            missionsToast = message;
            missionsToastAt = NowForUi();
        }

        private static void SetMissionsSection(MissionSectionKind section)
        {
            if (missionsSection != section)
            {
                missionsSection = section;
                missionsSectionChangedAt = NowForUi();
            }
            missionsScroll = Vector2.zero;
            missionsExpandedChapter = string.Empty;
        }

        private static MissionSectionKind MissionSectionFromId(string id)
        {
            if (string.Equals(id, "histoire", StringComparison.Ordinal)) return MissionSectionKind.Histoire;
            if (string.Equals(id, "hebdomadaires", StringComparison.Ordinal)) return MissionSectionKind.Hebdomadaires;
            if (string.Equals(id, "defis", StringComparison.Ordinal)) return MissionSectionKind.Defis;
            if (string.Equals(id, "succes", StringComparison.Ordinal)) return MissionSectionKind.Succes;
            if (string.Equals(id, "success", StringComparison.Ordinal)) return MissionSectionKind.Succes;
            return MissionSectionKind.Quotidiennes;
        }

        private static string MissionSectionId(MissionSectionKind section)
        {
            switch (section)
            {
                case MissionSectionKind.Histoire: return "histoire";
                case MissionSectionKind.Hebdomadaires: return "hebdomadaires";
                case MissionSectionKind.Defis: return "defis";
                case MissionSectionKind.Succes: return "succes";
                default: return "quotidiennes";
            }
        }

        // ---- Progression : etat reel du royaume, ou credit de navigation simule. ----
        private static float MissionHoneyAmount()
        {
            HiveStockScreenModel stock = OfficialHiveStockModel();
            HiveStockResourceModel honey = stock != null ? stock.FindResource("honey") : null;
            if (honey != null) return honey.Amount;
            return localPreviewHoney;
        }

        private static int MissionTotalBuildingLevels()
        {
            int total = 0;
            foreach (KeyValuePair<string, int> entry in localPreviewBuildingLevels) total += Math.Max(0, entry.Value);
            return total;
        }

        private static int MissionDistinctBuildings()
        {
            int count = 0;
            foreach (KeyValuePair<string, int> entry in localPreviewBuildingLevels) if (entry.Value >= 1) count++;
            return count;
        }

        private static int MissionMaxBuildingLevel()
        {
            int max = 0;
            foreach (KeyValuePair<string, int> entry in localPreviewBuildingLevels) if (entry.Value > max) max = entry.Value;
            return max;
        }

        private static int MissionResearchCount()
        {
            HiveResearchScreenModel model = OfficialResearchModel();
            if (model != null && model.Completed != null) return model.Completed.Count;
            return 0;
        }

        private static int MissionChampionCount()
        {
            int count = localPreviewAssignedChampionBeeIds != null ? localPreviewAssignedChampionBeeIds.Count : 0;
            if (localPreviewHiveProgress != null && localPreviewHiveProgress.championBees != null && localPreviewHiveProgress.championBees.Count > count)
                count = localPreviewHiveProgress.championBees.Count;
            return count;
        }

        private static int MissionTotalPower()
        {
            return ComputeRealTotalPower();
        }

        private static int MissionApproxLevel()
        {
            return 1 + MissionTotalPower() / 20000;
        }

        private static void MissionRecordVisit(MissionNavigationKind navigation)
        {
            switch (navigation)
            {
                case MissionNavigationKind.Chat:
                    missionsMessagesCredits = Math.Min(missionsMessagesCredits + 1, 500);
                    break;
                case MissionNavigationKind.Alliance:
                    missionsAllianceHelpCredits = Math.Min(missionsAllianceHelpCredits + 1, 500);
                    break;
                case MissionNavigationKind.Bestiary:
                    missionsEnemiesCredits = Math.Min(missionsEnemiesCredits + 1, 500);
                    break;
            }
        }

        private static int MissionCurrentValue(string id)
        {
            if (missionsProgressOverrides.TryGetValue(id, out int overrideValue)) return overrideValue;
            switch (id)
            {
                case "q_collect":
                case "w_collect":
                case "s_gold":
                    return Mathf.RoundToInt(MissionHoneyAmount());
                case "q_build":
                case "s_first_colony":
                    return MissionDistinctBuildings();
                case "w_build":
                case "s_architect":
                    return MissionTotalBuildingLevels();
                case "d_building_20":
                    return MissionMaxBuildingLevel();
                case "q_research":
                case "s_scholar":
                    return MissionResearchCount();
                case "q_champion":
                case "d_champion":
                case "s_legend":
                    return MissionChampionCount();
                case "d_level_10":
                    return MissionApproxLevel();
                case "d_power_100k":
                    return MissionTotalPower();
                case "q_alliance_help":
                case "w_help":
                    return missionsAllianceHelpCredits;
                case "q_alliance_message":
                case "w_chat":
                    return missionsMessagesCredits;
                case "q_enemies":
                case "w_enemies":
                    return missionsEnemiesCredits;
                default:
                    return 0;
            }
        }

        private static int MissionProgressValue(MissionDefinition mission)
        {
            if (mission == null) return 0;
            return MissionCurrentValue(mission.Id);
        }

        private static bool MissionIsComplete(MissionDefinition mission)
        {
            return mission != null && MissionProgressValue(mission) >= mission.TargetCount;
        }

        private static bool MissionIsClaimed(MissionDefinition mission)
        {
            return mission != null && missionsClaimedIds.Contains(mission.Id);
        }

        private static float MissionProgress01(MissionDefinition mission)
        {
            if (mission == null) return 0f;
            return Mathf.Clamp01(MissionProgressValue(mission) / (float)mission.TargetCount);
        }

        private static string MissionTitle(MissionDefinition mission)
        {
            return mission == null ? string.Empty : BeeLocalization.Text(mission.TitleKey, mission.TitleFallback);
        }

        private static string MissionBody(MissionDefinition mission)
        {
            return mission == null ? string.Empty : BeeLocalization.Text(mission.BodyKey, mission.BodyFallback);
        }

        private static int MissionClaimableCount()
        {
            int count = 0;
            for (int i = 0; i < MissionCatalog.AllMissions.Length; i++)
            {
                MissionDefinition m = MissionCatalog.AllMissions[i];
                if (MissionIsComplete(m) && !MissionIsClaimed(m)) count++;
            }
            return count;
        }

        private static int MissionCompletedCountForSection(MissionSectionKind section)
        {
            int count = 0;
            MissionDefinition[] list = MissionCatalog.MissionsForSection(section);
            for (int i = 0; i < list.Length; i++) if (MissionIsComplete(list[i])) count++;
            return count;
        }

        private static void ClaimMission(MissionDefinition mission)
        {
            if (mission == null) return;
            if (!MissionIsComplete(mission))
            {
                ShowMissionsToast("Mission en cours : termine la pour réclamer.");
                return;
            }
            if (missionsClaimedIds.Contains(mission.Id))
            {
                ShowMissionsToast("Mission déjà reclamée.");
                return;
            }
            missionsClaimedIds.Add(mission.Id);
            missionsClaimCommitCount++;
            if (mission.RewardHoney > 0) localPreviewHoney += mission.RewardHoney;
            if (mission.RewardWax > 0) localPreviewWax += mission.RewardWax;
            if (mission.RewardPollen > 0) localPreviewPollen += mission.RewardPollen;
            localPreviewCapacityUsed += mission.RewardHoney + mission.RewardWax + mission.RewardPollen;
            BeginReferenceFeedbackPulse("preview");
            ShowMissionsToast(MissionTitle(mission) + " : +" + mission.RewardHoney + " miel, +" + mission.RewardWax + " cire, +" + mission.RewardPollen + " pollen (apercu local).");
        }

        private static int ClaimAllCompletedMissions()
        {
            int claimed = 0;
            for (int i = 0; i < MissionCatalog.AllMissions.Length; i++)
            {
                MissionDefinition m = MissionCatalog.AllMissions[i];
                if (MissionIsComplete(m) && !MissionIsClaimed(m))
                {
                    missionsClaimedIds.Add(m.Id);
                    missionsClaimCommitCount++;
                    if (m.RewardHoney > 0) localPreviewHoney += m.RewardHoney;
                    if (m.RewardWax > 0) localPreviewWax += m.RewardWax;
                    if (m.RewardPollen > 0) localPreviewPollen += m.RewardPollen;
                    localPreviewCapacityUsed += m.RewardHoney + m.RewardWax + m.RewardPollen;
                    claimed++;
                }
            }
            if (claimed > 0) BeginReferenceFeedbackPulse("preview");
            ShowMissionsToast(claimed > 0
                ? claimed.ToString(CultureInfo.InvariantCulture) + " mission(s) reclamées : récompenses créditées dans l'aperçu local."
                : "Aucune récompense à réclamer.");
            return claimed;
        }

        private static void ClaimChapter(MissionChapterDefinition chapter)
        {
            if (chapter == null) return;
            if (missionsChaptersClaimed.Contains(chapter.Id))
            {
                ShowMissionsToast("Chapitre déjà réclamé.");
                return;
            }
            missionsChaptersClaimed.Add(chapter.Id);
            missionsClaimCommitCount++;
            if (chapter.RewardHoney > 0) localPreviewHoney += chapter.RewardHoney;
            if (chapter.RewardWax > 0) localPreviewWax += chapter.RewardWax;
            if (chapter.RewardPollen > 0) localPreviewPollen += chapter.RewardPollen;
            localPreviewCapacityUsed += chapter.RewardHoney + chapter.RewardWax + chapter.RewardPollen;
            BeginReferenceFeedbackPulse("preview");
            ShowMissionsToast(MissionTitleForChapter(chapter) + " : +" + chapter.RewardHoney + " miel, +" + chapter.RewardWax + " cire, +" + chapter.RewardPollen + " pollen (apercu local).");
        }

        private static string MissionTitleForChapter(MissionChapterDefinition chapter)
        {
            return chapter == null ? string.Empty : BeeLocalization.Text(chapter.TitleKey, chapter.TitleFallback);
        }

        private static bool MissionIsPinned(string id)
        {
            for (int i = 0; i < missionsPinnedIds.Count; i++)
            {
                if (string.Equals(missionsPinnedIds[i], id, StringComparison.Ordinal)) return true;
            }
            return false;
        }

        private static bool MissionTogglePinned(string id)
        {
            if (MissionCatalog.Find(id) == null) return false;
            for (int i = 0; i < missionsPinnedIds.Count; i++)
            {
                if (string.Equals(missionsPinnedIds[i], id, StringComparison.Ordinal))
                {
                    missionsPinnedIds.RemoveAt(i);
                    PersistMissionPins();
                    ShowMissionsToast("Mission retirée des favoris.");
                    return true;
                }
            }
            if (missionsPinnedIds.Count >= MissionCatalog.MaxPinnedMissions)
            {
                ShowMissionsToast("Tu peux épingler jusqu'à " + MissionCatalog.MaxPinnedMissions + " missions.");
                return false;
            }
            missionsPinnedIds.Add(id);
            PersistMissionPins();
            ShowMissionsToast("Mission épinglée · elle apparaît en jeu (widget masquable).");
            return true;
        }

        private static string[] PinnedMissionIds()
        {
            string[] result = new string[missionsPinnedIds.Count];
            for (int i = 0; i < missionsPinnedIds.Count; i++) result[i] = missionsPinnedIds[i];
            return result;
        }

        private static void MissionNavigate(MissionDefinition mission)
        {
            if (mission == null) return;
            MissionRecordVisit(mission.Navigation);
            missionsCenterOpen = false;
            switch (mission.Navigation)
            {
                case MissionNavigationKind.Collect:
                case MissionNavigationKind.Building:
                    NavigateToDailyRoundTask(DailyRoundCollectTask);
                    break;
                case MissionNavigationKind.Alliance:
                    activeMainMenuId = string.Empty;
                    ActivateHiveMenu(HiveMenuMode.Alliance, "Menu alliance");
                    AudioManager.Instance?.PlayMenuOpen();
                    break;
                case MissionNavigationKind.Chat:
                    OpenChatScreenTargeted("alliance", "alliance-general", true);
                    break;
                case MissionNavigationKind.Friends:
                    OpenFriendsScreen();
                    break;
                case MissionNavigationKind.Courier:
                    OpenCourierScreen();
                    break;
                case MissionNavigationKind.Champions:
                    activeMainMenuId = string.Empty;
                    championBeesPanelOpen = true;
                    championBeesPanelAnimationStartedAt = NowForUi();
                    AudioManager.Instance?.PlayMenuOpen();
                    break;
                case MissionNavigationKind.Research:
                    activeMainMenuId = string.Empty;
                    ActivateHiveMenu(HiveMenuMode.Research, "Missions");
                    break;
                case MissionNavigationKind.Bestiary:
                    OpenBestiaryCodexOverlay();
                    break;
                default:
                    ShowMissionsToast("Module associé à un prochain sprint.");
                    missionsCenterOpen = true;
                    break;
            }
            BeginReferenceFeedbackPulse("preview");
        }

        // ---- Rendu plein ecran ----
        private static void DrawMissionsCenterScreen(bool compact)
        {
            if (!missionsCenterOpen) return;
            float anim = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((NowForUi() - missionsCenterOpenedAt) / 0.18f));
            float zoom = Mathf.Lerp(0.97f, 1f, anim);
            Rect full = new Rect(0f, 0f, Screen.width, Screen.height);
            GUI.matrix = Matrix4x4.TRS(full.center, Quaternion.identity, new Vector3(zoom, zoom, 1f)) * Matrix4x4.Translate(-full.center);
            GUI.color = new Color(0.006f, 0.005f, 0.004f, 0.99f * anim);
            GUI.DrawTexture(full, Texture2D.blackTexture, ScaleMode.StretchToFill, false);
            GUI.color = Color.white;
            float bannerHeight = compact
                ? Mathf.Min(150f, Screen.height * 0.20f)
                : Mathf.Clamp(Screen.height * 0.20f, 150f, 190f);
            DrawMissionsBanner(bannerHeight, compact);
            DrawMissionsTopBar(bannerHeight, compact);

            float actionY = bannerHeight + 6f;
            float actionHeight = compact ? 44f : 52f;
            DrawMissionsActionBar(new Rect(0f, actionY, Screen.width, actionHeight), compact);

            float tabsY = actionY + actionHeight + 6f;
            DrawMissionsTabs(compact, tabsY);

            float contentTop = tabsY + 40f;
            float searchHeight = missionsSearchOpen ? 46f : 0f;
            Rect body = new Rect(0f, contentTop + searchHeight, Screen.width, Mathf.Max(1f, Screen.height - contentTop - searchHeight));
            // M043T-CL: DrawMissionsGuideOverlay is this screen's own sub-modal, drawn on top of
            // this same content below - see DrawUnderOwnOverlayGate's standing convention.
            DrawUnderOwnOverlayGate(missionsGuideOpen, () =>
            {
                if (missionsSearchOpen) DrawMissionsSearchBar(contentTop, compact);
                DrawMissionsTabContent(body, compact);
            });
            DrawMissionsGuideOverlay(compact);
            DrawMissionsToast();
            GUI.matrix = Matrix4x4.identity;
        }

        private static void DrawMissionsBanner(float height, bool compact)
        {
            Rect banner = new Rect(0f, 0f, Screen.width, height);
            Texture2D bannerTexture = Resources.Load<Texture2D>("PremiumBeeReference/BuildingBanners/missions_hall");
            if (bannerTexture == null)
                bannerTexture = Resources.Load<Texture2D>("PremiumBeeReference/BuildingBanners/alliance_future_hall");
            if (bannerTexture != null)
            {
                GUI.color = Color.white;
                GUI.DrawTexture(banner, bannerTexture, ScaleMode.ScaleAndCrop, true);
            }
            else
            {
                DrawPremiumPanel(banner, new Color(0.14f, 0.085f, 0.025f, 0.98f), new Color(1f, 0.68f, 0.16f, 0.90f));
            }
            GUI.color = new Color(0.01f, 0.008f, 0.004f, 0.48f);
            GUI.DrawTexture(banner, Texture2D.blackTexture, ScaleMode.StretchToFill, true);
            GUI.color = Color.white;
            GUI.Label(new Rect(28f, height - (compact ? 42f : 48f), Screen.width * 0.62f, 26f), "CENTRE DE MISSIONS", new GUIStyle(titleStyle) { fontSize = compact ? 20 : 28, fontStyle = FontStyle.Bold });
            GUI.Label(new Rect(30f, height - (compact ? 20f : 23f), Screen.width * 0.70f, 16f), "Votre guide quotidien du royaume", new GUIStyle(smallStyle) { fontSize = compact ? 9 : 12 });
        }

        private static void DrawMissionsTopBar(float bannerHeight, bool compact)
        {
            Color previous = GUI.color;
            GUI.color = new Color(1f, 0.60f, 0.14f, 0.95f);
            GUI.DrawTexture(new Rect(0f, bannerHeight - 1f, Screen.width, 1f), Texture2D.whiteTexture, ScaleMode.StretchToFill, false);
            GUI.color = previous;
			if (DrawPremiumBackButton(new Rect(4f, 2f, 48f, 46f)))
            {
                AudioManager.Instance?.PlayUIClick();
                AudioManager.Instance?.PlayMenuClose();
                missionsCenterOpen = false;
                return;
            }
            GUI.Label(new Rect(54f, 12f, Screen.width - 170f, 24f), "CENTRE DE MISSIONS", new GUIStyle(badgeStyle) { fontSize = 11 });
            int claimable = MissionClaimableCount();
            if (claimable > 0)
            {
                Rect count = new Rect(Screen.width - 108f, 10f, 96f, 28f);
                DrawPremiumPanel(count, new Color(0.36f, 0.22f, 0.05f, 0.96f), new Color(1f, 0.72f, 0.18f, 0.90f));
                GUI.Label(count, claimable.ToString(CultureInfo.InvariantCulture) + " À RÉCLAMER", new GUIStyle(centeredTinyLabelStyle) { fontSize = 9, normal = { textColor = new Color(1f, 0.92f, 0.62f, 1f) } });
            }
        }

        private static void DrawMissionsActionBar(Rect rect, bool compact)
        {
            string[] ids = { "claim", "pinned", "guide", "ranking", "search" };
            string[] labels = { "Réclamer tout", "Favoris", "Guide", "Classement", "Recherche" };
            float gap = 6f;
            float itemWidth = compact ? 118f : Mathf.Max(118f, (rect.width - gap * (ids.Length - 1f)) / ids.Length);
            float contentWidth = ids.Length * itemWidth + (ids.Length - 1f) * gap + 8f;
            DrawPremiumPanel(rect, new Color(0.025f, 0.022f, 0.017f, 0.98f), new Color(0.82f, 0.54f, 0.14f, 0.84f));
            missionsGuideScroll.y = 0f;
            Vector2 scroll = GUI.BeginScrollView(new Rect(0f, rect.y, rect.width, rect.height), Vector2.zero, new Rect(0f, 0f, contentWidth, rect.height - 2f), false, false);
            for (int i = 0; i < ids.Length; i++)
            {
                Rect button = new Rect(4f + i * (itemWidth + gap), rect.y + 6f, itemWidth, rect.height - 12f);
                bool selected = (ids[i] == "pinned" && missionsFavoritesOnly) || (ids[i] == "guide" && missionsGuideOpen) || (ids[i] == "search" && missionsSearchOpen);
                DrawPremiumPanel(button, selected ? new Color(0.30f, 0.20f, 0.06f, 0.96f) : new Color(0.06f, 0.045f, 0.025f, 0.94f), selected ? new Color(1f, 0.72f, 0.18f, 0.90f) : new Color(0.64f, 0.44f, 0.14f, 0.64f));
                GUI.Label(button, labels[i], new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 9 : 10, fontStyle = selected ? FontStyle.Bold : FontStyle.Normal });
                if (GUI.Button(button, string.Empty, GUIStyle.none))
                {
                    AudioManager.Instance?.PlayUIClick();
                    if (ids[i] == "claim")
                    {
                        ClaimAllCompletedMissions();
                    }
                    else if (ids[i] == "pinned")
                    {
                        missionsFavoritesOnly = !missionsFavoritesOnly;
                        ShowMissionsToast(missionsFavoritesOnly ? "Favoris : uniquement vos missions épinglées." : "Favoris : toutes les missions.");
                    }
                    else if (ids[i] == "guide")
                    {
                        missionsGuideOpen = !missionsGuideOpen;
                    }
                    else if (ids[i] == "ranking")
                    {
                        ShowMissionsToast("Le classement des alliances arrive à un prochain sprint.");
                    }
                    else
                    {
                        missionsSearchOpen = !missionsSearchOpen;
                        if (!missionsSearchOpen) missionsSearchQuery = string.Empty;
                    }
                }
            }
            GUI.EndScrollView();
        }

        private static void DrawMissionsTabs(bool compact, float y)
        {
            string[] ids = { "histoire", "quotidiennes", "hebdomadaires", "defis", "succes" };
            string[] labels = { "Histoire", "Quotidiennes", "Hebdomadaires", "Défis", "Succès" };
            if (compact)
            {
                float chipW = 138f;
                float gap = 6f;
                float contentWidth = ids.Length * (chipW + gap) + 10f;
                DrawMissionsRailBar(MissionsTabsRect(compact, y), new Color(0.018f, 0.016f, 0.013f, 0.98f), new Color(0.70f, 0.46f, 0.13f, 0.68f));
                missionsSectionScroll = GUI.BeginScrollView(MissionsTabsRect(compact, y), missionsSectionScroll, new Rect(0f, 0f, contentWidth, 36f), false, false);
                for (int i = 0; i < ids.Length; i++)
                {
                    DrawMissionsTabChip(compact, y, ids[i], labels[i], new Rect(5f + i * (chipW + gap), 2f, chipW, 34f));
                }
                GUI.EndScrollView();
            }
            else
            {
                DrawMissionsRailBar(new Rect(0f, y, Screen.width, 38f), new Color(0.018f, 0.016f, 0.013f, 0.98f), new Color(0.70f, 0.46f, 0.13f, 0.68f));
                float inset = 10f;
                float gap = 6f;
                float chipW = (Screen.width - inset * 2f - gap * 4f) / 5f;
                for (int i = 0; i < ids.Length; i++)
                {
                    DrawMissionsTabChip(compact, y, ids[i], labels[i], new Rect(inset + i * (chipW + gap), y + 2f, chipW, 34f));
                }
            }
        }

        private static void DrawMissionsRailBar(Rect rect, Color fill, Color border)
        {
            DrawPremiumPanel(rect, fill, border);
        }

        private static Rect MissionsTabsRect(bool compact, float y)
        {
            return MissionsTabsRectForProof(compact, y);
        }

        private static Rect MissionsTabsRectForProof(bool compact, float y)
        {
            return compact ? new Rect(0f, y, Screen.width, 38f) : new Rect(0f, y, Screen.width, 38f);
        }

        private static void DrawMissionsTabChip(bool compact, float y, string id, string label, Rect chip)
        {
            MissionSectionKind section = MissionSectionFromId(id);
            bool selected = missionsSection == section;
            bool hovered = chip.Contains(Event.current != null ? Event.current.mousePosition : Vector2.zero);
            Color fill = selected ? new Color(0.38f, 0.22f, 0.05f, 0.98f) : hovered ? new Color(0.16f, 0.11f, 0.035f, 0.96f) : new Color(0.035f, 0.030f, 0.022f, 0.90f);
            Color border = selected ? new Color(1f, 0.72f, 0.18f, 0.96f) : new Color(0.54f, 0.38f, 0.14f, 0.60f);
            DrawPremiumPanel(chip, fill, border);
            string display = label;
            if (section != MissionSectionKind.Histoire)
            {
                int total = MissionCatalog.MissionCountForSection(section);
                int done = MissionCompletedCountForSection(section);
                display = label + " · " + done.ToString(CultureInfo.InvariantCulture) + "/" + total.ToString(CultureInfo.InvariantCulture);
            }
            GUI.Label(chip, display, new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 8 : 10, fontStyle = selected ? FontStyle.Bold : FontStyle.Normal, normal = { textColor = selected ? new Color(1f, 0.92f, 0.70f, 1f) : Color.white } });
            if (GUI.Button(chip, string.Empty, GUIStyle.none))
            {
                AudioManager.Instance?.PlayUIClick();
                if (missionsSection != section)
                {
                    SetMissionsSection(section);
                }
            }
        }

        private static void DrawMissionsSearchBar(float heightTop, bool compact)
        {
            Rect row = new Rect(10f, heightTop, Screen.width - 92f, 38f);
            DrawPremiumPanel(row, new Color(0.040f, 0.033f, 0.021f, 0.95f), new Color(0.70f, 0.48f, 0.14f, 0.62f));
            missionsSearchQuery = GUI.TextField(row, missionsSearchQuery, new GUIStyle(smallStyle) { fontSize = compact ? 12 : 14 });
            if (GUI.Button(new Rect(Screen.width - 74f, heightTop, 64f, 38f), "OK"))
            {
                AudioManager.Instance?.PlayUIClick();
                missionsSearchOpen = false;
            }
        }

        private static void DrawMissionsTabContent(Rect area, bool compact)
        {
            float fade = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((NowForUi() - missionsSectionChangedAt) / 0.14f));
            float slide = Mathf.Lerp(12f, 0f, fade);
            GUI.color = new Color(1f, 1f, 1f, fade);
            Rect body = new Rect(area.x + slide, area.y, area.width, area.height);
            if (missionsSection == MissionSectionKind.Histoire)
            {
                DrawMissionsHistorySection(body, compact);
            }
            else
            {
                int countless = 0;
                MissionDefinition[] list = MissionCatalog.MissionsForSection(missionsSection);
                for (int i = 0; i < list.Length; i++) if (MissionMatchesFilter(list[i])) countless++;
                if (countless == 0)
                {
                    GUI.Label(body, "Aucune mission ne correspond à ce filtre.", new GUIStyle(centeredTinyLabelStyle) { fontSize = 11 });
                }
                else
                {
                    DrawMissionsListSection(body, compact);
                }
            }
            GUI.color = Color.white;
        }

        private static bool MissionMatchesFilter(MissionDefinition mission)
        {
            if (missionsFavoritesOnly && !MissionIsPinned(mission.Id)) return false;
            if (missionsSearchOpen && !string.IsNullOrWhiteSpace(missionsSearchQuery))
            {
                string needle = missionsSearchQuery.Trim();
                if (!MissionTitle(mission).ToLowerInvariant().Contains(needle.ToLowerInvariant())
                    && !MissionBody(mission).ToLowerInvariant().Contains(needle.ToLowerInvariant()))
                    return false;
            }
            return true;
        }

        private static void DrawMissionsHistorySection(Rect area, bool compact)
        {
            float inset = 10f;
            float headerH = 26f;
            float listTop = area.y + inset + headerH;
            Rect viewport = new Rect(area.x + inset, listTop, Mathf.Max(1f, area.width - inset * 2f), Mathf.Max(1f, area.yMax - listTop - inset));
            if (viewport.width < 40f || viewport.height < 40f) return;
            float rowH = compact ? 150f : 168f;
            float contentH = Mathf.Max(viewport.height, headerH + 8f + MissionCatalog.AllChapters.Length * (rowH + 8f));
            missionsHistoryScroll = GUI.BeginScrollView(viewport, missionsHistoryScroll, new Rect(0f, 0f, viewport.width, contentH), false, true);
            GUI.Label(new Rect(0f, 0f, viewport.width, headerH), "PROGRESSION PRINCIPALE", new GUIStyle(badgeStyle) { fontSize = compact ? 10 : 12 });
            float y = headerH + 8f;
            for (int i = 0; i < MissionCatalog.AllChapters.Length; i++)
            {
                MissionChapterDefinition chapter = MissionCatalog.AllChapters[i];
                bool expanded = missionsExpandedChapter == chapter.Id;
                float height = rowH + (expanded ? chapter.ObjectiveIds.Length * (compact ? 58f : 66f) : 0f);
                if (height > viewport.height + 40f) height = viewport.height + 40f;
                DrawMissionsChapterCard(new Rect(0f, y, viewport.width, Mathf.Max(rowH, height)), chapter, compact);
                y += height + 8f;
            }
            GUI.EndScrollView();
        }

        private static void DrawMissionsChapterCard(Rect rect, MissionChapterDefinition chapter, bool compact)
        {
            DrawPremiumPanel(rect, new Color(0.040f, 0.033f, 0.021f, 0.95f), new Color(0.70f, 0.48f, 0.14f, 0.62f));
            string title = BeeLocalization.Text(chapter.TitleKey, chapter.TitleFallback);
            string subtitle = BeeLocalization.Text(chapter.SubtitleKey, chapter.SubtitleFallback);
            float iconSize = compact ? 44f : 52f;
            DrawGameIcon(new Rect(rect.x + 10f, rect.y + 8f, iconSize, iconSize), chapter.IconId, Color.white);
            float textX = rect.x + 10f + iconSize + 10f;
            float textW = rect.width - textX - 12f;
            int completed = 0;
            for (int i = 0; i < chapter.ObjectiveIds.Length; i++)
            {
                MissionDefinition objective = MissionCatalog.Find(chapter.ObjectiveIds[i]);
                if (objective != null && MissionIsComplete(objective)) completed++;
            }
            float progress01 = Mathf.Clamp01(completed / (float)Mathf.Max(1, chapter.ObjectiveIds.Length));
            Color stateColor = completed >= chapter.ObjectiveIds.Length ? new Color(0.45f, 0.95f, 0.55f, 1f) : completed > 0 ? new Color(1f, 0.78f, 0.28f, 1f) : new Color(1f, 0.94f, 0.78f, 0.9f);
            GUI.Label(new Rect(textX, rect.y + 5f, textW - 80f, 20f), title, new GUIStyle(badgeStyle) { fontSize = compact ? 12 : 14, alignment = TextAnchor.MiddleLeft });
            string stateLabel = completed >= chapter.ObjectiveIds.Length ? "Terminé" : completed > 0 ? "En cours" : "À venir";
            GUIStyle stateStyle = new GUIStyle(badgeStyle) { fontSize = compact ? 8 : 9, normal = { textColor = stateColor } };
            GUI.Label(new Rect(rect.xMax - 76f, rect.y + 7f, 68f, 18f), stateLabel, stateStyle);
            GUI.Label(new Rect(textX, rect.y + 24f, textW, 15f), subtitle, new GUIStyle(tinyLabelStyle) { fontSize = compact ? 8 : 9, normal = { textColor = new Color(1f, 0.82f, 0.45f, 1f) } });
            Rect bar = new Rect(textX, rect.y + 44f, textW - 96f, 10f);
            DrawProgressBar(bar, progress01);
            GUI.Label(new Rect(bar.xMax + 8f, bar.y - 5f, 74f, 20f), completed + "/" + chapter.ObjectiveIds.Length, new GUIStyle(badgeStyle) { fontSize = 9 });
            string rewardLabel = "+" + chapter.RewardHoney + " miel";
            if (chapter.RewardWax > 0) rewardLabel += " · +" + chapter.RewardWax + " cire";
            if (chapter.RewardPollen > 0) rewardLabel += " · +" + chapter.RewardPollen + " pollen";
            Rect reward = new Rect(rect.x + 10f, rect.y + 58f, rect.width - 20f, 18f);
            GUI.Label(reward, "Récompenses : " + rewardLabel, new GUIStyle(tinyLabelStyle) { fontSize = compact ? 8 : 9 });

            bool allDone = completed >= chapter.ObjectiveIds.Length;
            bool currentlyClaimed = missionsClaimedIds.Contains("chapter_" + chapter.Id)
                || (allDone && missionsChaptersClaimed.Contains(chapter.Id));
            if (allDone && !currentlyClaimed)
            {
                Rect claim = new Rect(rect.xMax - 104f, rect.y + 4f, 92f, 26f);
                DrawPremiumPanel(claim, new Color(0.30f, 0.20f, 0.06f, 0.96f), new Color(1f, 0.72f, 0.18f, 0.90f));
                GUI.Label(claim, "Réclamer", new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 9 : 10 });
                if (GUI.Button(claim, string.Empty, GUIStyle.none))
                {
                    AudioManager.Instance?.PlayUIClick();
                    ClaimChapter(chapter);
                }
            }
            else if (currentlyClaimed)
            {
                Rect claimed = new Rect(rect.xMax - 104f, rect.y + 4f, 92f, 26f);
                DrawPremiumPanel(claimed, new Color(0.05f, 0.04f, 0.025f, 0.90f), new Color(0.60f, 0.50f, 0.30f, 0.70f));
                GUI.Label(claimed, "Réclamé", new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 9 : 10, normal = { textColor = new Color(1f, 0.90f, 0.70f, 0.9f) } });
            }

            Rect expand = new Rect(rect.x + 10f, rect.yMax - 30f, 130f, 24f);
            bool expanded = missionsExpandedChapter == chapter.Id;
            if (GUI.Button(expand, expanded ? "Objectifs ▴" : "Objectifs ▾"))
            {
                AudioManager.Instance?.PlayUIClick();
                missionsExpandedChapter = expanded ? string.Empty : chapter.Id;
            }

if (expanded)
            {
                float oy = rect.yMax - 8f - chapter.ObjectiveIds.Length * (compact ? 58f : 66f);
                for (int i = 0; i < chapter.ObjectiveIds.Length; i++)
                {
                    MissionDefinition objective = MissionCatalog.Find(chapter.ObjectiveIds[i]);
                    if (objective == null) continue;
                    float oh = compact ? 54f : 62f;
                    DrawObjectiveRow(new Rect(rect.x + 12f, oy, rect.width - 24f, oh), objective, compact);
                    oy += oh + 4f;
                }
            }
        }

        private static void DrawObjectiveRow(Rect rect, MissionDefinition objective, bool compact)
        {
            DrawPremiumPanel(rect, new Color(0.028f, 0.024f, 0.018f, 0.92f), new Color(0.52f, 0.40f, 0.18f, 0.50f));
            DrawGameIcon(new Rect(rect.x + 8f, rect.y + 7f, 30f, 30f), objective.IconId, Color.white);
            float x = rect.x + 46f;
            string title = MissionTitle(objective);
            bool complete = MissionIsComplete(objective);
            string sub = complete ? "✓ Terminé" : MissionProgressValue(objective).ToString(CultureInfo.InvariantCulture) + " / " + objective.TargetCount.ToString(CultureInfo.InvariantCulture);
            GUI.Label(new Rect(x, rect.y + 4f, rect.width - 46f - 74f, 18f), title, new GUIStyle(badgeStyle) { fontSize = compact ? 10 : 11, alignment = TextAnchor.MiddleLeft, normal = { textColor = complete ? new Color(0.60f, 1f, 0.65f, 1f) : Color.white } });
            GUI.Label(new Rect(x, rect.y + 22f, rect.width - 46f - 74f, 18f), sub, new GUIStyle(tinyLabelStyle) { fontSize = compact ? 8 : 9, alignment = TextAnchor.MiddleLeft, normal = { textColor = complete ? new Color(0.60f, 1f, 0.65f, 1f) : new Color(1f, 0.80f, 0.45f, 1f) } });
            Rect bar = new Rect(x, rect.y + 30f, rect.width - 46f - 140f, 6f);
            if (bar.width > 10f)
            {
                DrawProgressBar(bar, MissionProgress01(objective));
            }
            string actionLabel = complete ? "Réclamer" : "Aller →";
            Rect action = new Rect(rect.xMax - 122f, rect.y + (rect.height - 30f) * 0.5f, 108f, 30f);
            bool emphasized = complete && !MissionIsClaimed(objective);
            DrawObjectiveActionButton(action, actionLabel, emphasized, compact);
            if (GUI.Button(action, string.Empty, GUIStyle.none))
            {
                AudioManager.Instance?.PlayUIClick();
                if (complete && !MissionIsClaimed(objective)) ClaimMission(objective);
                else MissionNavigate(objective);
            }
        }

        private static void DrawObjectiveActionButton(Rect rect, string label, bool emphasized, bool compact)
        {
            DrawPremiumPanel(rect,
                emphasized ? new Color(0.30f, 0.20f, 0.06f, 0.96f) : new Color(0.06f, 0.05f, 0.03f, 0.90f),
                emphasized ? new Color(1f, 0.72f, 0.18f, 0.90f) : new Color(0.60f, 0.48f, 0.30f, 0.60f));
            GUI.Label(rect, label, new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 8 : 9, fontStyle = emphasized ? FontStyle.Bold : FontStyle.Normal });
        }

        private static void DrawMissionsListSection(Rect area, bool compact)
        {
            float inset = 12f;
            float headerH = 22f;
            float listTop = area.y + inset + headerH;
            Rect viewport = new Rect(area.x + inset, listTop, Mathf.Max(1f, area.width - inset * 2f), Mathf.Max(1f, area.yMax - listTop - inset));
            if (viewport.width < 40f || viewport.height < 40f) return;
            MissionDefinition[] list = MissionCatalog.MissionsForSection(missionsSection);
            int columns = compact ? 1 : 2;
            float gap = compact ? 6f : 10f;
            float cardW = (viewport.width - gap * (columns - 1)) / columns;
            float cardH = compact ? 104f : 118f;
            int filtered = 0;
            for (int i = 0; i < list.Length; i++) if (MissionMatchesFilter(list[i])) filtered++;
            float rows = Mathf.CeilToInt(filtered / (float)columns);
            float contentH = Mathf.Max(viewport.height, headerH + 8f + rows * (cardH + gap) + 8f);
            missionsListScroll = GUI.BeginScrollView(viewport, missionsListScroll, new Rect(0f, 0f, viewport.width, contentH), false, true);
            string header = MissionSectionTitle(missionsSection) + " · " + MissionCompletedCountForSection(missionsSection).ToString(CultureInfo.InvariantCulture) + "/" + list.Length.ToString(CultureInfo.InvariantCulture);
            GUI.Label(new Rect(0f, 0f, viewport.width, headerH), header, new GUIStyle(badgeStyle) { fontSize = compact ? 10 : 12 });
            float y = headerH + 8f;
            int drawn = 0;
            for (int i = 0; i < list.Length; i++)
            {
                if (!MissionMatchesFilter(list[i])) continue;
                int col = drawn % columns;
                float rowIdx = drawn / columns;
                DrawMissionCard(new Rect(col * (cardW + gap), y + rowIdx * (cardH + gap), cardW, cardH), list[i], compact);
                drawn++;
            }
            GUI.EndScrollView();
        }

        private static string MissionSectionTitle(MissionSectionKind section)
        {
            switch (section)
            {
                case MissionSectionKind.Histoire: return "HISTOIRE";
                case MissionSectionKind.Hebdomadaires: return "MISSIONS HEBDOMADAIRES";
                case MissionSectionKind.Defis: return "DÉFIS";
                case MissionSectionKind.Succes: return "SUCCÈS";
                default: return "MISSIONS QUOTIDIENNES";
            }
        }

        private static void DrawMissionCard(Rect rect, MissionDefinition mission, bool compact)
        {
            DrawPremiumPanel(rect, new Color(0.040f, 0.033f, 0.021f, 0.95f), new Color(0.70f, 0.48f, 0.14f, 0.62f));
            bool complete = MissionIsComplete(mission);
            bool claimed = MissionIsClaimed(mission);
            float iconSize = compact ? 40f : 46f;
            DrawGameIcon(new Rect(rect.x + 10f, rect.y + 8f, iconSize, iconSize), mission.IconId, Color.white);
            float x = rect.x + 10f + iconSize + 8f;
            float xEnd = rect.xMax - 10f;
            float pinSize = 26f;
            bool pinned = MissionIsPinned(mission.Id);
            string pinGlyph = pinned ? "★" : "☆";
            Rect pin = new Rect(xEnd - pinSize, rect.y + 6f, pinSize, pinSize);
            GUI.Label(pin, pinGlyph, new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 13 : 15, normal = { textColor = pinned ? new Color(1f, 0.80f, 0.24f, 1f) : new Color(1f, 0.92f, 0.70f, 0.7f) } });
            if (GUI.Button(pin, string.Empty, GUIStyle.none))
            {
                AudioManager.Instance?.PlayUIClick();
                MissionTogglePinned(mission.Id);
            }

            float textW = xEnd - pinSize - x - 6f;
            float statusW = 56f;
            string status = claimed ? "Réclamée" : complete ? "Terminée" : "En cours";
            GUI.Label(new Rect(x, rect.y + 4f, textW - statusW, 18f), MissionTitle(mission), new GUIStyle(badgeStyle) { fontSize = compact ? 11 : 12, alignment = TextAnchor.MiddleLeft });
            Color statusX = complete && !claimed ? new Color(0.55f, 1f, 0.60f, 1f) : claimed ? new Color(1f, 0.90f, 0.70f, 0.85f) : new Color(1f, 0.80f, 0.40f, 1f);
            GUI.Label(new Rect(x + textW - statusW, rect.y + 4f, statusW, 18f), status, new GUIStyle(badgeStyle) { fontSize = compact ? 7 : 8, alignment = TextAnchor.MiddleRight, normal = { textColor = statusX } });

            GUI.Label(new Rect(x, rect.y + 22f, rect.width - x - 10f, 20f), MissionBody(mission), new GUIStyle(tinyLabelStyle) { fontSize = compact ? 8 : 9, wordWrap = true, normal = { textColor = new Color(1f, 0.86f, 0.62f, 0.95f) } });

            float bottom = rect.yMax - 8f;
            Rect bar = new Rect(x, bottom - 14f, 120f, 8f);
            DrawProgressBar(bar, MissionProgress01(mission));
            GUI.Label(new Rect(bar.xMax + 6f, bar.y - 5f, 60f, 18f),
                Mathf.Clamp(MissionProgressValue(mission), 0, mission.TargetCount).ToString(CultureInfo.InvariantCulture) + "/" + mission.TargetCount.ToString(CultureInfo.InvariantCulture),
                new GUIStyle(badgeStyle) { fontSize = 8 });

            string reward = MissionRewardLabel(mission);
            if (reward.Length > 0)
            {
                GUI.Label(new Rect(rect.x + 10f, bottom - 26f, rect.width - 20f, 12f), reward, new GUIStyle(tinyLabelStyle) { fontSize = compact ? 7 : 8, normal = { textColor = new Color(1f, 0.78f, 0.30f, 0.95f) } });
            }

            float actionW = 86f;
            Rect action = new Rect(rect.xMax - actionW - 10f, bottom, actionW, 30f);
            bool claimable = complete && !claimed;
            string actionLabel = claimable ? "Réclamer" : claimed ? "Réclamée" : "Aller →";
            DrawPreviewPanel(action, claimable ? new Color(0.30f, 0.20f, 0.06f, 0.96f) : new Color(0.06f, 0.05f, 0.03f, 0.90f), claimable ? new Color(1f, 0.72f, 0.18f, 0.90f) : new Color(0.60f, 0.48f, 0.30f, 0.60f));
            GUI.Label(action, actionLabel, new GUIStyle(centeredTinyLabelStyle) { fontSize = compact ? 8 : 9 });
            if (GUI.Button(action, string.Empty, GUIStyle.none))
            {
                AudioManager.Instance?.PlayUIClick();
                if (claimable) ClaimMission(mission);
                else if (claimed) ShowMissionsToast("Mission déjà reclamée.");
                else MissionNavigate(mission);
            }

            if (mission.Navigation != MissionNavigationKind.None && !complete && !claimed)
            {
                Rect go = new Rect(action.x - 44f - 8f, bottom, 44f, 30f);
                DrawPreviewPanel(go, new Color(0.06f, 0.05f, 0.03f, 0.90f), new Color(0.60f, 0.48f, 0.30f, 0.60f));
                GUI.Label(go, "Ouvrir", new GUIStyle(centeredTinyLabelStyle) { fontSize = 8 });
                if (GUI.Button(go, string.Empty, GUIStyle.none))
                {
                    AudioManager.Instance?.PlayUIClick();
                    MissionNavigate(mission);
                }
            }

            if (mission.SimulatedOnly)
            {
                Rect sim = new Rect(rect.x + 10f, rect.y + 6f, iconSize, iconSize);
                GUI.Label(new Rect(rect.x + 10f, rect.yMax - 20f, 90f, 14f), "SIMULÉ", new GUIStyle(badgeStyle) { fontSize = 7, normal = { textColor = new Color(0.75f, 0.65f, 0.40f, 0.9f) } });
            }
        }

        private static string MissionRewardLabel(MissionDefinition mission)
        {
            string text = string.Empty;
            if (mission.RewardHoney > 0) text += "+" + mission.RewardHoney.ToString(CultureInfo.InvariantCulture) + " miel";
            if (mission.RewardWax > 0) text += (text.Length > 0 ? " · " : string.Empty) + "+" + mission.RewardWax.ToString(CultureInfo.InvariantCulture) + " cire";
            if (mission.RewardPollen > 0) text += (text.Length > 0 ? " · " : string.Empty) + "+" + mission.RewardPollen.ToString(CultureInfo.InvariantCulture) + " pollen";
            return text;
        }

        private static void DrawPreviewPanel(Rect rect, Color fill, Color border)
        {
            DrawPremiumPanel(rect, fill, border);
        }

        private static void DrawMissionsGuideOverlay(bool compact)
        {
            if (!missionsGuideOpen) return;
            float panelWidth = Mathf.Min(Screen.width - 32f, 460f);
            float panelHeight = Mathf.Min(Screen.height * 0.55f, 360f);
            Rect panel = new Rect((Screen.width - panelWidth) * 0.5f, (Screen.height - panelHeight) * 0.5f, panelWidth, panelHeight);
			DrawFullScreen();
			DrawPremiumPanel(panel, new Color(0.030f, 0.026f, 0.020f, 0.99f), new Color(0.92f, 0.64f, 0.18f, 0.90f));
			DrawPremiumHeaderBand(new Rect(panel.x + 8f, panel.y + 8f, panel.width - 16f, 42f));
			if (DrawPremiumBackButton(new Rect(panel.x + 10f, panel.y + 7f, 44f, 44f)))
			{
				AudioManager.Instance?.PlayUIClick();
				missionsGuideOpen = false;
				return;
			}
			GUI.Label(new Rect(panel.x + 60f, panel.y + 12f, panel.width - 72f, 30f), "Guide du royaume", titleStyle);
            Rect viewport = new Rect(panel.x + 12f, panel.y + 58f, panel.width - 24f, panel.height - 70f);
            float innerWidth = viewport.width - 14f;
            missionsGuideScroll = GUI.BeginScrollView(viewport, missionsGuideScroll, new Rect(0f, 0f, innerWidth, 320f), false, true);
            GUI.Label(new Rect(0f, 0f, innerWidth, 280f),
                "Le Centre de Missions guide chaque pitit pas :\n\n" +
                "• Histoire : la progression principale en chapitres, avec récompenses à réclamer quand tous les objectifs sont terminés.\n" +
                "• Quotidiennes, Hebdomadaires et Défis : des objectifs renouvelés, avec progression en temps réel et boutons Réclamer.\n" +
                "• Succès : données simulées cette sprint, prêtes à être connectées au vrai système.\n\n" +
                "Choisis jusqu'à 3 missions en favori (★) : elles apparaissent dans le petit widget de la Ruche et de la carte, masquable (👁).\n\n" +
                "Chaque mission est aussi un point d'entrée : clique Aller → pour ouvrir directement le module concerné.",
                new GUIStyle(smallStyle) { fontSize = compact ? 11 : 12, wordWrap = true });
            GUI.EndScrollView();
        }

        private static void DrawMissionsToast()
        {
            if (missionsToastAt < 0f) return;
            float age = NowForUi() - missionsToastAt;
            float fade = 1f - Mathf.Clamp01((age - 1.5f) / 0.8f);
            if (fade <= 0f) return;
            float tw = Mathf.Min(Screen.width - 24f, 460f);
            Rect toast = new Rect((Screen.width - tw) * 0.5f, Screen.height - 90f, tw, 46f);
            Color previous = GUI.color;
            GUI.color = new Color(1f, 1f, 1f, fade);
            DrawPremiumPanel(toast, new Color(0.05f, 0.04f, 0.025f, 0.98f), new Color(0.86f, 0.58f, 0.16f, 0.90f));
            GUI.Label(new Rect(toast.x + 10f, toast.y + 6f, toast.width - 20f, 34f), missionsToast, new GUIStyle(smallStyle) { fontSize = 10, alignment = TextAnchor.MiddleCenter, wordWrap = true });
            GUI.color = previous;
        }

        private static void DrawFullScreen()
        {
            GUI.color = new Color(0f, 0f, 0f, 0.55f);
            GUI.DrawTexture(new Rect(0f, 0f, Screen.width, Screen.height), Texture2D.blackTexture, ScaleMode.StretchToFill, false);
            GUI.color = Color.white;
        }

        // ---- Widget de missions echangees (Ruche + carte du monde) ----
        private static bool MissionsWidgetShouldRender(bool worldMap)
        {
            if (missionsPinnedIds.Count == 0) return false;
            if (missionsWidgetHidden) return false;
            if (worldMap) return !combatPatrolOverlayOpen;
            if (missionsCenterOpen) return false;
            if (courierScreenOpen || friendsScreenOpen || chatScreenOpen || activeHiveMenu == HiveMenuMode.Research) return false;
            if (!string.IsNullOrEmpty(activeMainMenuId)) return false;
            if (activeHiveMenu == HiveMenuMode.Alliance || activeHiveMenu == HiveMenuMode.Army) return false;
            if (referenceHotspotSelected && !detailPanelClosed) return false;
            if (strategicPathPanelOpen || formationReadinessOpen || milestoneEventOverlayOpen || bestiaryCodexOverlayOpen) return false;
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.Inactive) return false;
            return true;
        }

        private static Rect MissionsWidgetRect(bool compact, bool worldMap)
            => MissionsWidgetRectForProof(IsPortraitLayout(), Screen.width, Screen.height, worldMap);

        public static Rect MissionsWidgetRectForProof(bool portrait, float screenWidth, float screenHeight, bool worldMap)
        {
            int rows = Mathf.Clamp(missionsPinnedIds.Count, 1, MissionCatalog.MaxPinnedMissions);
            float headerH = 30f;
            float rowH = 30f;
            float pad = 10f;
            float width = portrait ? Mathf.Min(196f, screenWidth - 20f) : Mathf.Min(252f, screenWidth * 0.20f);
            float height = headerH + rows * rowH + pad;
            float bottom;
            float x;
            if (worldMap)
            {
                bottom = (portrait ? screenHeight - 190f - 8f - 56f : screenHeight - 108f) - 10f;
                x = portrait ? 12f : Mathf.Max(12f, screenWidth - width - 12f);
            }
            else
            {
                bottom = (portrait ? screenHeight - 78f : screenHeight - 76f) - 10f;
                x = portrait ? 10f : Mathf.Max(10f, screenWidth - width - 12f);
            }
            float y = Mathf.Max(100f, bottom - height);
            return new Rect(x, y, width, height);
        }

        private static void DrawMissionsWidget(bool compact, bool worldMap)
        {
            if (missionsPinnedIds.Count == 0) return;
            if (missionsWidgetHidden)
            {
                DrawMissionsWidgetTeaserChip(compact, worldMap);
                return;
            }
            if (!MissionsWidgetShouldRender(worldMap)) return;
            Rect rect = MissionsWidgetRect(compact, worldMap);
            Color widgetFill = new Color(0.022f, 0.020f, 0.016f, 0.97f);
            Color widgetBorder = new Color(0.86f, 0.58f, 0.16f, 0.80f);
            DrawPremiumPanel(rect, widgetFill, widgetBorder);
            DrawPremiumHeaderBand(new Rect(rect.x + 6f, rect.y + 5f, rect.width - 12f, 24f));
            GUI.Label(new Rect(rect.x + 10f, rect.y + 6f, rect.width - 70f, 22f), "MISSIONS · " + missionsPinnedIds.Count.ToString(CultureInfo.InvariantCulture) + "/3", new GUIStyle(badgeStyle) { fontSize = compact ? 10 : 11 });
            Rect eye = new Rect(rect.xMax - 40f, rect.y + 4f, 32f, 24f);
            if (GUI.Button(eye, "👁"))
            {
                AudioManager.Instance?.PlayUIClick();
                SetMissionsWidgetHidden(true);
                return;
            }
            float ry = rect.y + 5f + 26f;
            for (int i = 0; i < missionsPinnedIds.Count; i++)
            {
                MissionDefinition mission = MissionCatalog.Find(missionsPinnedIds[i]);
                if (mission == null) continue;
                Rect row = new Rect(rect.x + 5f, ry, rect.width - 10f, 28f);
                DrawGameIcon(new Rect(row.x, row.y + 2f, 22f, 22f), mission.IconId, Color.white);
                string line = MiniChatTruncate(MissionTitle(mission), compact ? 24 : 30);
                GUI.Label(new Rect(row.x + 28f, row.y + 1f, row.width - 28f, 16f), line, new GUIStyle(badgeStyle) { fontSize = compact ? 9 : 10 });
                Rect bar = new Rect(row.x + 28f, row.y + 18f, row.width - 28f - 44f, 6f);
                DrawProgressBar(bar, MissionProgress01(mission));
                GUI.Label(new Rect(bar.xMax + 4f, bar.y - 3f, 38f, 14f),
                    Mathf.Clamp(MissionProgressValue(mission), 0, mission.TargetCount).ToString(CultureInfo.InvariantCulture) + "/" + mission.TargetCount, tinyLabelStyle);
                if (GUI.Button(row, string.Empty, GUIStyle.none))
                {
                    AudioManager.Instance?.PlayUIClick();
                    OpenMissionsCenter();
                    SetMissionsSection(mission.Section);
                    ShowMissionsToast(MissionTitle(mission));
                }
                ry += 30f;
            }
        }

        private static void DrawMissionsWidgetTeaserChip(bool compact, bool worldMap)
        {
            Rect rect = worldMap
                ? new Rect(12f, Screen.height - 190f - 8f - 56f - 36f, 120f, 30f)
                : new Rect(Screen.width - (compact ? 150f : 190f) - 12f, Screen.height - (compact ? 78f : 76f) - 40f, (compact ? 150f : 190f), 30f);
            DrawPremiumPanel(rect, new Color(0.022f, 0.020f, 0.016f, 0.90f), new Color(0.86f, 0.58f, 0.16f, 0.80f));
            GUI.Label(new Rect(rect.x + 8f, rect.y + 5f, rect.width - 40f, 20f), "📌 Missions suive", new GUIStyle(badgeStyle) { fontSize = 9 });
            if (GUI.Button(rect, string.Empty, GUIStyle.none))
            {
                AudioManager.Instance?.PlayUIClick();
                SetMissionsWidgetHidden(false);
            }
        }

        // ---- Hooks de preuve (tests EditMode) ----
        public static bool MissionsCenterOpenForProof => missionsCenterOpen;
        public static void SetMissionsCenterOpenForProof(bool open) { if (open) OpenMissionsCenter(); else CloseMissionsCenter(); }
        public static string MissionsSectionForProof => MissionSectionId(missionsSection);
        public static void SetMissionsSectionForProof(string id) => SetMissionsSection(MissionSectionFromId(id));
        public static string[] MissionIdsForSectionForProof(string section)
        {
            MissionSectionKind kind = MissionSectionFromId(section);
            MissionDefinition[] list = MissionCatalog.MissionsForSection(kind);
            string[] result = new string[list.Length];
            for (int i = 0; i < list.Length; i++) result[i] = list[i].Id;
            return result;
        }
        public static string[] MissionCatalogAllIdsForProof()
        {
            string[] result = new string[MissionCatalog.AllMissions.Length];
            for (int i = 0; i < MissionCatalog.AllMissions.Length; i++) result[i] = MissionCatalog.AllMissions[i].Id;
            return result;
        }
        public static int MissionCatalogChapterCountForProof => MissionCatalog.AllChapters.Length;
        public static int MissionProgressForProof(string id) { MissionDefinition m = MissionCatalog.Find(id); return m != null ? MissionProgressValue(m) : 0; }
        public static void SeedMissionProgressForProof(string id, int value) { missionsProgressOverrides[id] = Mathf.Max(0, value); }
        public static void ClearMissionProgressForProof() { missionsProgressOverrides.Clear(); }
        public static bool MissionIsCompleteForProof(string id) { MissionDefinition m = MissionCatalog.Find(id); return m != null && MissionIsComplete(m); }
        public static void ClaimMissionForProof(string id) { MissionDefinition m = MissionCatalog.Find(id); if (m != null) ClaimMission(m); }
        public static bool MissionIsClaimedForProof(string id) => missionsClaimedIds.Contains(id);
        public static int MissionClaimedCountForProof => missionsClaimedIds.Count;
        public static int MissionsClaimCommitCountForProof => missionsClaimCommitCount;
        public static string[] PinnedMissionIdsForProof => missionsPinnedIds.ToArray();
        public static bool MissionPinnedForProof(string id) => MissionIsPinned(id);
        public static void ToggleMissionPinnedForProof(string id) => MissionTogglePinned(id);
        public static bool MissionsWidgetHiddenForProof => missionsWidgetHidden;
        public static void SetMissionsWidgetHiddenForProof(bool hidden) => SetMissionsWidgetHidden(hidden);
public static void ResetMissionsStateForProof()
        {
            missionsCenterOpen = false;
            missionsPinnedIds.Clear();
            missionsClaimedIds.Clear();
            missionsProgressOverrides.Clear();
            missionsWidgetHidden = false;
            missionsGuideOpen = false;
            missionsSearchOpen = false;
            missionsSearchQuery = string.Empty;
            missionsFavoritesOnly = false;
            missionsExpandedChapter = string.Empty;
            missionsAllianceHelpCredits = 0;
            missionsMessagesCredits = 0;
            missionsEnemiesCredits = 0;
        }

