        private static void DrawMoreMenuPanel(bool compact)
        {
            Rect panel = MoreMenuPanelRect(compact, Screen.width, Screen.height);
            panel = UIAnimationLibrary.ApplyWindowAnimation(panel, "more_menu");
            float fade = UIAnimationLibrary.GetFadeProgress("more_menu", 1f);
            DrawPremiumPanel(panel, new Color(0.026f, 0.024f, 0.020f, 0.97f * fade), new Color(0.92f, 0.64f, 0.18f, 0.82f * fade));

            string courierLabel = "Courrier";
            if (CourierNotificationCount() > 0) courierLabel += " · " + CourierNotificationCount().ToString(CultureInfo.InvariantCulture);
            string friendsLabel = "Amis";
            if (socialReceivedRequests.Count > 0) friendsLabel += " · " + socialReceivedRequests.Count.ToString(CultureInfo.InvariantCulture);
            string researchLabel = IsResearchRunning()
                ? BeeLocalization.Text("research.more.running", "Recherche · en cours")
                : BeeLocalization.Text("research.more.title", "Recherche");
            string missionsLabel = BeeLocalization.Text("ui.missions.menu.title", "Missions");
            if (missionsPinnedIds.Count > 0) missionsLabel += " · " + missionsPinnedIds.Count.ToString(CultureInfo.InvariantCulture) + "/3";
            string settingsLabel = BeeLocalization.Text("settings.panel.title", "Paramètres");
            if (productionReducedMotionForProof || mobileEconomyMode || !mobileComfortPreferences.soundEnabled || !mobileComfortPreferences.musicEnabled)
                settingsLabel += " · " + BeeLocalization.Text("settings.mobile.custom", "personnalisé");

            string[] labels =
            {
                courierLabel,
                friendsLabel,
                BeeLocalization.Text("bestiary_codex.entry_button_short", "Bestiaire"),
                MilestoneEventRailLabel(),
                BeeLocalization.Text("champion_bees.entry_button_short", "Championnes"),
                BeeLocalization.Text("ledger.title", "Sac & stocks"),
                researchLabel,
                missionsLabel,
                settingsLabel,
                BeeLocalization.Text("speedup.menu.title", "Accélérations")
            };

            float rowH = 50f;
            float gap = 4f;
            Rect viewport = new Rect(panel.x + 10f, panel.y + 10f, panel.width - 20f, panel.height - 20f);
            float contentH = labels.Length * rowH + (labels.Length - 1) * gap;
            bool scrollable = contentH > viewport.height;
            if (scrollable)
            {
                moreMenuScroll = GUI.BeginScrollView(viewport, moreMenuScroll, new Rect(0f, 0f, viewport.width - 8f, contentH), false, false);
            }
            for (int i = 0; i < labels.Length; i++)
            {
                Rect row = new Rect(
                    scrollable ? 0f : viewport.x,
                    (scrollable ? 0f : viewport.y) + i * (rowH + gap),
                    scrollable ? viewport.width - 8f : viewport.width,
                    rowH);
                if (GUI.Button(row, labels[i]))
                {
                    AudioManager.Instance?.PlayUIClick();
                    switch (i)
                    {
                        case 0:
                            OpenCourierScreen();
                            break;
                        case 1:
                            OpenFriendsScreen();
                            break;
                        case 2:
                            OpenBestiaryCodexOverlay();
                            break;
                        case 3:
                            OpenMilestoneEventOverlay();
                            break;
                        case 4:
                            activeMainMenuId = string.Empty;
                            championBeesPanelOpen = true;
                            championBeesPanelAnimationStartedAt = NowForUi();
                            AudioManager.Instance?.PlayMenuOpen();
                            break;
                        case 5:
                            activeMainMenuId = "Bag";
                            localPreviewLoopMessage = BeeLocalization.Text("ledger.opened", "Sac & stocks ouvert");
                            localPreviewLastActionStatus = BeeLocalization.Text("ledger.title", "Sac & stocks");
                            BeginReferenceFeedbackPulse("preview");
                            break;
                        case 6:
                            activeMainMenuId = string.Empty;
                            ActivateHiveMenu(HiveMenuMode.Research, BeeLocalization.Text("research.menu.title", "Recherche"));
                            AudioManager.Instance?.PlayMenuOpen();
                            break;
                        case 7:
                            OpenMissionsCenter();
                            AudioManager.Instance?.PlayMenuOpen();
                            break;
                        case 8:
                            ToggleSettingsPanel();
                            localPreviewLoopMessage = BeeLocalization.Text("settings.mobile.opened", "Réglages de confort ouverts");
                            BeginReferenceFeedbackPulse("preview");
                            AudioManager.Instance?.PlayMenuOpen();
                            break;
                        case 9:
                            OpenSpeedUpDialog(SpeedUpCategory.Universal, string.Empty, 0L);
                            AudioManager.Instance?.PlayMenuOpen();
                            break;
                    }
                }
            }
            if (scrollable) GUI.EndScrollView();
        }

        private static void DrawMobileComfortSettingsPanel(bool compact)
        {
            EnsureMobileComfortPreferencesLoaded();
            Rect panel = MobileComfortSettingsPanelRect(compact, Screen.width, Screen.height);
			DrawPremiumPanel(panel, new Color(0.026f, 0.024f, 0.020f, 0.985f), new Color(0.92f, 0.64f, 0.18f, 0.88f));
			DrawPremiumHeaderBand(new Rect(panel.x + 8f, panel.y + 8f, panel.width - 16f, 44f));
			if (DrawPremiumBackButton(new Rect(panel.x + 10f, panel.y + 8f, 44f, 44f)))
			{
				AudioManager.Instance?.PlayUIClick();
				AudioManager.Instance?.PlayMenuClose();
				CloseActiveMainMenuPanel();
				return;
			}
			GUI.Label(
				new Rect(panel.x + 60f, panel.y + 15f, panel.width - 72f, 28f),
				BeeLocalization.Text("settings.panel.title", "Paramètres"),
				titleStyle);

            // Tout le contenu est dessine en coordonnees locales dans une scrollview : le nombre
            // de reglages grandit (langue, son, musique...) et un viewport fixe ne doit jamais
            // rendre une option inatteignable (meme bug/le meme correctif que l'ecran de connexion).
            Rect viewport = new Rect(panel.x + 8f, panel.y + 58f, panel.width - 16f, panel.height - 66f);
            float innerWidth = viewport.width - 18f;
            const float ContentBudget = 620f;
            settingsPanelScroll = GUI.BeginScrollView(viewport, settingsPanelScroll, new Rect(0f, 0f, innerWidth, ContentBudget));
            float ly = 0f;

            GUI.Label(
                new Rect(0f, ly, innerWidth, 42f),
                BeeLocalization.Text("settings.mobile.intro", "Adapte l'animation et la charge visuelle de cette ruche sur cet appareil."),
                smallStyle);
            ly += 48f;

            if (DrawMobileComfortToggle(
                    new Rect(0f, ly, innerWidth, 76f),
                    BeeLocalization.Text("settings.mobile.reduced_motion", "Mouvement réduit"),
                    BeeLocalization.Text("settings.mobile.reduced_motion.body", "Fige les pulsations et révèle immédiatement les textes animés."),
                    productionReducedMotionForProof))
            {
                SetMobileReducedMotion(!productionReducedMotionForProof);
            }
            ly += 82f;

            if (DrawMobileComfortToggle(
                    new Rect(0f, ly, innerWidth, 76f),
                    BeeLocalization.Text("settings.mobile.economy", "Mode économie"),
                    BeeLocalization.Text("settings.mobile.economy.body", "Réduit les abeilles d'ambiance et les traînées, jamais les abeilles affectées."),
                    mobileEconomyMode))
            {
                SetMobileEconomyMode(!mobileEconomyMode);
            }
            ly += 82f;

            if (DrawMobileComfortToggle(
                    new Rect(0f, ly, innerWidth, 76f),
                    BeeLocalization.Text("settings.audio.sound", "Effets sonores"),
                    BeeLocalization.Text("settings.audio.sound.body", "Active les sons d'interface et d'action."),
                    mobileComfortPreferences.soundEnabled))
            {
                SetMobileSoundEnabled(!mobileComfortPreferences.soundEnabled);
            }
            ly += 82f;

            if (DrawMobileComfortToggle(
                    new Rect(0f, ly, innerWidth, 76f),
                    BeeLocalization.Text("settings.audio.music", "Musique"),
                    BeeLocalization.Text("settings.audio.music.body", "Active la musique de fond de la ruche."),
                    mobileComfortPreferences.musicEnabled))
            {
                SetMobileMusicEnabled(!mobileComfortPreferences.musicEnabled);
            }
            ly += 82f;

            GUI.Label(new Rect(0f, ly, innerWidth, 26f), BeeLocalization.Text("settings.language.title", "Langue"), badgeStyle);
            ly += 30f;
            float languageButtonWidth = (innerWidth - 8f) * 0.5f;
            bool isFrench = string.Equals(BeeLocalization.CurrentLocale, "fr-CA", StringComparison.OrdinalIgnoreCase);
            Rect frButton = new Rect(0f, ly, languageButtonWidth, 44f);
            Rect enButton = new Rect(languageButtonWidth + 8f, ly, languageButtonWidth, 44f);
            DrawPremiumPanel(frButton, isFrench ? new Color(0.62f, 0.34f, 0.055f, 0.98f) : new Color(0.08f, 0.065f, 0.04f, 0.96f), isFrench ? new Color(1f, 0.82f, 0.24f, 1f) : new Color(0.70f, 0.50f, 0.20f, 0.76f));
            GUI.Label(frButton, "Français", new GUIStyle(centeredTinyLabelStyle) { fontStyle = isFrench ? FontStyle.Bold : FontStyle.Normal });
            if (GUI.Button(frButton, string.Empty, GUIStyle.none) && !isFrench)
                SetPreferredLocaleForRuntime("fr-CA");
            DrawPremiumPanel(enButton, !isFrench ? new Color(0.62f, 0.34f, 0.055f, 0.98f) : new Color(0.08f, 0.065f, 0.04f, 0.96f), !isFrench ? new Color(1f, 0.82f, 0.24f, 1f) : new Color(0.70f, 0.50f, 0.20f, 0.76f));
            GUI.Label(enButton, "English", new GUIStyle(centeredTinyLabelStyle) { fontStyle = !isFrench ? FontStyle.Bold : FontStyle.Normal });
            if (GUI.Button(enButton, string.Empty, GUIStyle.none) && isFrench)
                SetPreferredLocaleForRuntime("en-US");
            ly += 58f;

            GUI.Label(
                new Rect(0f, ly, innerWidth, 42f),
                BeeLocalization.Text("settings.mobile.device_only", "Préférences de cet appareil · aucune ressource ni progression modifiée"),
                tinyLabelStyle);
            ly += 42f;

            GUI.EndScrollView();
        }

        private static bool DrawMobileComfortToggle(Rect rect, string label, string body, bool enabled)
        {
            DrawPremiumPanel(rect, new Color(0.035f, 0.030f, 0.023f, 0.94f), new Color(0.58f, 0.42f, 0.18f, 0.55f));
            GUI.Label(new Rect(rect.x + 12f, rect.y + 10f, rect.width - 84f, 22f), label, badgeStyle);
            GUI.Label(new Rect(rect.x + 12f, rect.y + 34f, rect.width - 84f, 32f), body, tinyLabelStyle);
            Rect toggle = new Rect(rect.xMax - 62f, rect.y + 18f, 48f, 34f);
            GUI.Label(toggle, enabled ? "ON" : "OFF", centeredTinyLabelStyle);
            return GUI.Button(rect, string.Empty, GUIStyle.none);
        }

        private static bool DrawPremiumButton(Rect rect, string label, string animationKey)
        {
            DrawPremiumPanel(rect, new Color(0.12f, 0.075f, 0.025f, 0.96f), new Color(0.95f, 0.66f, 0.18f, 0.88f));
            GUI.Label(rect, label, centeredTinyLabelStyle);
            return GUI.Button(rect, string.Empty, GUIStyle.none);
