        private static void DrawSpeedUpContent(Rect viewport, SpeedUpCategory category, string targetHotspotId)
        {
            EnsureSpeedUpDemoInventorySeeded();
            speedUpDialogDisplayStacks.Clear();
            IReadOnlyList<SpeedUpStack> specialized = SpeedUpInventory.GetStacks(category);
            for (int i = 0; i < specialized.Count; i++) speedUpDialogDisplayStacks.Add(specialized[i]);
            if (category != SpeedUpCategory.Universal)
            {
                IReadOnlyList<SpeedUpStack> universal = SpeedUpInventory.GetStacks(SpeedUpCategory.Universal);
                for (int i = 0; i < universal.Count; i++) speedUpDialogDisplayStacks.Add(universal[i]);
            }
            speedUpDialogDisplayStacks.Sort((left, right) => right.Item.DurationSeconds.CompareTo(left.Item.DurationSeconds));
            IReadOnlyList<SpeedUpStack> stacks = speedUpDialogDisplayStacks;
            float y = viewport.y;
            if (OfficialSpeedUpConfigured()) y = DrawOfficialSpeedUpBlock(viewport, y) + 8f;
            if (stacks == null || stacks.Count == 0)
            {
                GUI.Label(new Rect(viewport.x + 12f, y + 24f, viewport.width - 24f, 32f), BeeLocalization.Text("speedup.empty", "Aucune accélération disponible"), centeredTinyLabelStyle);
                return;
            }

            for (int i = 0; i < stacks.Count; i++)
            {
                SpeedUpStack stack = stacks[i];
                if (stack == null || stack.Item == null || stack.Count <= 0) continue;
                Rect row = new Rect(viewport.x + 4f, y + 4f, viewport.width - 8f, 48f);
                DrawPremiumPanel(row, new Color(0.035f, 0.030f, 0.023f, 0.94f), new Color(0.55f, 0.40f, 0.16f, 0.48f));
                GUI.Label(new Rect(row.x + 10f, row.y + 6f, row.width * 0.42f, 18f), stack.Item.FormattedDuration, badgeStyle);
                GUI.Label(new Rect(row.x + 10f, row.y + 25f, row.width * 0.42f, 16f), stack.Item.Rarity.ToString(), tinyLabelStyle);
                GUI.Label(new Rect(row.xMax - 116f, row.y + 6f, 52f, 18f), "x" + stack.Count.ToString(CultureInfo.InvariantCulture), badgeStyle);
                Rect use = new Rect(row.xMax - 58f, row.y + 6f, 48f, 36f);
                if (GUI.Button(use, BeeLocalization.Text("speedup.use", "Utiliser"), centeredTinyLabelStyle))
                {
                    if (SpeedUpInventory.Remove(stack.Item.Id, 1))
                        ApplySpeedUpToTarget(stack.Item, 1);
                }
                y += 56f;
                if (y > viewport.yMax - 52f) break;
            }
        }

        // Bloc serveur officiel (SpeedUp + ledger Rewards) dessine au-dessus de la demo :
        // inventaire server-authoritatif, timers avec application idempotente, recompenses
        // claimables. Additif : si aucun controle officiel n'est configure, la demo reste seule.
        private static float DrawOfficialSpeedUpBlock(Rect viewport, float y)
        {
            EnsureStyles();
            float cursor = y;
            HiveSpeedUpScreenModel speedUpModel = speedUpController.Model;
            HiveRewardLedgerScreenModel ledgerModel = rewardLedgerController.Model;
            Rect header = new Rect(viewport.x + 4f, cursor, viewport.width - 8f, 24f);
            GUI.Label(new Rect(header.x + 8f, header.y + 3f, header.width - 112f, 18f), BeeLocalization.Text("speedup.server_block", "Serveur officiel"), badgeStyle);
            GUI.enabled = !speedUpController.IsBusy && !rewardLedgerController.IsBusy;
            if (GUI.Button(new Rect(header.xMax - 96f, header.y + 1f, 88f, 22f), BeeLocalization.Text("speedup.refresh", "Actualiser"), centeredTinyLabelStyle))
            {
                speedUpController.Refresh();
                rewardLedgerController.Refresh();
                AudioManager.Instance?.PlayUIClick();
            }
            GUI.enabled = true;
            cursor += 28f;

            if (ledgerModel.State == HiveRewardLedgerScreenState.Error)
            {
                GUI.Label(new Rect(viewport.x + 12f, cursor, viewport.width - 24f, 20f), BeeLocalization.Text("speedup.ledger_error", "Récompenses") + " : " + ledgerModel.ErrorCode, tinyLabelStyle);
                cursor += 24f;
            }
            else if (ledgerModel.State == HiveRewardLedgerScreenState.Ready)
            {
                int pending = ledgerModel.PendingRewardCount;
                string rewardsLabel = pending > 0
                    ? string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("speedup.rewards_pending", "Récompenses : {0} en attente"), pending)
                    : BeeLocalization.Text("speedup.rewards_none", "Récompenses : aucune en attente");
                GUI.Label(new Rect(viewport.x + 12f, cursor, viewport.width - 24f, 20f), rewardsLabel, tinyLabelStyle);
                cursor += 22f;
                for (int i = 0; i < ledgerModel.Rewards.Count && cursor < viewport.yMax - 60f; i++)
                {
                    RemoteRewardLedgerEntry reward = ledgerModel.Rewards[i];
                    if (reward.Claimed) continue;
                    GUI.Label(new Rect(viewport.x + 20f, cursor, viewport.width - 40f, 18f),
                        reward.ResourceKey + " x" + reward.Amount.ToString(CultureInfo.InvariantCulture) + " (" + reward.Source + ")",
                        new GUIStyle(tinyLabelStyle) { normal = { textColor = new Color(0.85f, 0.95f, 0.60f, 1f) } });
                    cursor += 20f;
                }
            }

            if (speedUpModel.State == HiveSpeedUpScreenState.Error)
            {
                GUI.Label(new Rect(viewport.x + 12f, cursor, viewport.width - 24f, 20f), BeeLocalization.Text("speedup.server_error", "Serveur indisponible") + " : " + speedUpModel.ErrorCode, tinyLabelStyle);
                return cursor + 24f;
            }
            if (speedUpModel.State != HiveSpeedUpScreenState.Ready)
            {
                GUI.Label(new Rect(viewport.x + 12f, cursor, viewport.width - 24f, 20f), BeeLocalization.Text("speedup.loading", "Chargement du serveur…"), tinyLabelStyle);
                return cursor + 24f;
            }

            GUI.Label(new Rect(viewport.x + 12f, cursor, viewport.width - 24f, 20f),
                string.Format(CultureInfo.CurrentCulture, BeeLocalization.Text("speedup.server_inventory", "Inventaire serveur : {0} objet(s) — {1} accélération(s) active(s)"), speedUpModel.TotalItemCount, speedUpModel.Timers.Count),
                tinyLabelStyle);
            cursor += 24f;

            int shown = 0;
            for (int i = 0; i < speedUpModel.Timers.Count && shown < 3; i++)
            {
                RemoteSpeedUpTimer timer = speedUpModel.Timers[i];
                if (timer.Status != "running") continue;
                Rect row = new Rect(viewport.x + 4f, cursor, viewport.width - 8f, 30f);
                DrawPremiumPanel(row, new Color(0.035f, 0.030f, 0.023f, 0.94f), new Color(0.55f, 0.40f, 0.16f, 0.48f));
                double remainingSeconds = (timer.CompletesAtUtc - DateTimeOffset.UtcNow).TotalSeconds;
                string remaining = remainingSeconds > 0 ? Mathf.CeilToInt((float)remainingSeconds) + "s" : "…";
                GUI.Label(new Rect(row.x + 8f, row.y + 6f, row.width - 80f, 18f),
                    SpeedUpCategoryLabelFromKey(timer.Category) + " / " + ShortId(timer.TargetId) + " (" + remaining + ")", tinyLabelStyle);
                string itemId = BestApplicableItemId(speedUpModel, timer.Category);
                bool canApply = !speedUpController.IsBusy && itemId != null && speedUpModel.Inventory.TryGetValue(itemId, out int quantity) && quantity > 0;
                GUI.enabled = canApply;
                if (GUI.Button(new Rect(row.xMax - 68f, row.y + 4f, 60f, 22f), BeeLocalization.Text("speedup.apply", "Appliquer"), centeredTinyLabelStyle))
                {
                    long duration = ItemDurationSeconds(itemId);
                    if (duration > 0 && speedUpController.TryApply(itemId, timer.Category, timer.TargetId, duration))
                        AudioManager.Instance?.PlayUIClick();
                }
                GUI.enabled = true;
                cursor += 34f;
                shown++;
            }
            if (shown == 0)
            {
                GUI.Label(new Rect(viewport.x + 12f, cursor, viewport.width - 24f, 20f), BeeLocalization.Text("speedup.no_timers", "Aucune accélération active"), tinyLabelStyle);
                cursor += 24f;
            }
            return cursor;
        }

        private static string SpeedUpCategoryLabelFromKey(string category)
        {
            switch (category)
            {
                case "construction": return BeeLocalization.Text("speedup.category.construction", "Construction");
                case "research": return BeeLocalization.Text("speedup.category.research", "Recherche");
                case "training": return BeeLocalization.Text("speedup.category.training", "Entraînement");
                case "healing": return BeeLocalization.Text("speedup.category.healing", "Guérison");
                case "manufacturing": return BeeLocalization.Text("speedup.category.manufacturing", "Fabrication");
                case "universal": return BeeLocalization.Text("speedup.category.universal", "Universelle");
                default: return category;
            }
        }

        private static string BestApplicableItemId(HiveSpeedUpScreenModel model, string category)
        {
            if (model.Inventory == null) return null;
            if (model.Inventory.TryGetValue(category + "_60s", out int count) && count > 0) return category + "_60s";
            foreach (KeyValuePair<string, int> item in model.Inventory)
                if (item.Value > 0 && (item.Key.StartsWith(category + "_", StringComparison.Ordinal) || item.Key.StartsWith("universal_", StringComparison.Ordinal)))
                    return item.Key;
            return null;
        }

        private static long ItemDurationSeconds(string itemId)
        {
            if (string.IsNullOrEmpty(itemId)) return 0;
            int lastUnderscore = itemId.LastIndexOf('_');
            if (lastUnderscore < 0 || !itemId.EndsWith("s", StringComparison.Ordinal)) return 0;
            string digits = itemId.Substring(lastUnderscore + 1, itemId.Length - lastUnderscore - 2);
            return long.TryParse(digits, NumberStyles.None, CultureInfo.InvariantCulture, out long seconds) ? seconds : 0;
        }

        private static string ShortId(string id)
        {
            if (string.IsNullOrEmpty(id)) return string.Empty;
            return id.Length <= 13 ? id : id.Substring(0, 13);
        }

        private static void EnsureSpeedUpDemoInventorySeeded()
        {
            if (speedUpDemoInventorySeeded) return;
            speedUpDemoInventorySeeded = true;
            if (SpeedUpInventory.GetAllStacks().Count > 0) return;

            SpeedUpInventory.Add("universal_60s", 3);
            SpeedUpInventory.Add("construction_300s", 2);
            SpeedUpInventory.Add("research_900s", 2);
            SpeedUpInventory.Add("training_1800s", 2);
            SpeedUpInventory.Add("healing_3600s", 1);
            SpeedUpInventory.Add("manufacturing_10800s", 1);
        }

        private static string SpeedUpCategoryLabel(SpeedUpCategory category)
        {
            switch (category)
            {
                case SpeedUpCategory.Construction: return "Construction";
                case SpeedUpCategory.Research: return "Recherche";
                case SpeedUpCategory.Training: return "Entraînement";
                case SpeedUpCategory.Healing: return "Guérison";
                case SpeedUpCategory.Manufacturing: return "Fabrication";
                default: return "Universelle";
            }
        }

        private static void DrawSpeedUpCategoryTab(Rect tab, SpeedUpCategory category, string label)
        {
            bool isActive = speedUpSelectedCategory == category;
            Color fill = isActive ? new Color(0.060f, 0.050f, 0.034f, 0.94f) : new Color(0.035f, 0.030f, 0.023f, 0.78f);
            Color border = isActive ? new Color(1f, 0.69f, 0.15f, 0.82f) : new Color(0.55f, 0.40f, 0.18f, 0.52f);
            DrawPremiumPanel(tab, fill, border);
            GUI.Label(tab, label, new GUIStyle(centeredTinyLabelStyle) { fontSize = 11 });
            if (GUI.Button(tab, string.Empty, GUIStyle.none))
            {
                speedUpSelectedCategory = category;
                AudioManager.Instance?.PlayUIClick();
            }
        }

        private static void DrawSpeedUpWindow(bool compact)
        {
            if (!speedUpWindowOpen) return;

            float fade = UIAnimationLibrary.GetFadeProgress("speedup_window", 1f);
            Rect panel = SpeedUpWindowRect(compact, Screen.width, Screen.height);
            panel = UIAnimationLibrary.ApplyWindowAnimation(panel, "speedup_window");
            DrawPremiumPanel(panel, new Color(0.026f, 0.024f, 0.020f, 0.985f * fade), new Color(0.94f, 0.64f, 0.16f, 0.96f * fade));

            Rect header = new Rect(panel.x + 12f, panel.y + 12f, panel.width - 24f, compact ? 52f : 64f);
            DrawPremiumHeaderBand(header);
            if (DrawPremiumBackButton(new Rect(header.x + 2f, header.y + (compact ? 2f : 8f), compact ? 44f : 48f, compact ? 44f : 48f)))
            {
                speedUpWindowOpen = false;
                SpeedUpDialog.Close();
                AudioManager.Instance?.PlayMenuClose();
                return;
            }
            float titleX = compact ? 56f : 62f;
            GUI.Label(new Rect(header.x + titleX, header.y + 8f, header.width - titleX - 8f, 24f), BeeLocalization.Text("speedup.menu.title", "Accélérations"), new GUIStyle(titleStyle) { fontSize = compact ? 16 : 23 });
            GUI.Label(new Rect(header.x + titleX, header.y + 33f, header.width - titleX - 8f, 18f), BeeLocalization.Text("speedup.menu.subtitle", "Réduisez le temps restant de vos opérations"), tinyLabelStyle);

            if (!string.IsNullOrEmpty(speedUpTargetHotspotId))
            {
                float remaining = GetSpeedUpRemainingForHotspot(speedUpTargetHotspotId, speedUpSelectedCategory);
                GUI.Label(new Rect(header.x + titleX, header.y + (compact ? 52f : 58f), header.width - titleX - 8f, 18f), FormatTimeRemaining(remaining), new GUIStyle(badgeStyle) { fontSize = compact ? 12 : 14, alignment = TextAnchor.MiddleRight });
            }

            Rect tabBar = new Rect(panel.x, panel.yMax - 44f, panel.width, 44f);
            DrawPremiumPanel(tabBar, new Color(0.020f, 0.018f, 0.014f, 0.88f), new Color(0.70f, 0.48f, 0.16f, 0.60f));
            bool contextual = !string.IsNullOrEmpty(SpeedUpDialog.Context.TargetId);
            if (contextual)
            {
                DrawSpeedUpCategoryTab(new Rect(tabBar.x, tabBar.y, tabBar.width * 0.5f, tabBar.height), SpeedUpCategory.Universal, "Universelle");
                DrawSpeedUpCategoryTab(new Rect(tabBar.x + tabBar.width * 0.5f, tabBar.y, tabBar.width * 0.5f, tabBar.height), speedUpSelectedCategory, SpeedUpCategoryLabel(speedUpSelectedCategory));
            }
            else
            {
                float tabWidth = tabBar.width / 6f;
                string[] tabs = { "Universelle", "Construction", "Recherche", "Entraînement", "Guérison", "Fabrication" };
                for (int i = 0; i < 6; i++)
                {
                    DrawSpeedUpCategoryTab(new Rect(tabBar.x + i * tabWidth, tabBar.y, tabWidth, tabBar.height), (SpeedUpCategory)i, tabs[i]);
                }
            }

            Rect actionBar = new Rect(panel.x, panel.yMax - 90f, panel.width, 44f);
            DrawPremiumPanel(actionBar, new Color(0.020f, 0.018f, 0.014f, 0.88f), new Color(0.70f, 0.48f, 0.16f, 0.60f));

            Rect autoBtn = new Rect(actionBar.x + 12f, actionBar.y + 6f, actionBar.width * 0.5f - 18f, 32f);
            if (DrawPremiumButton(autoBtn, BeeLocalization.Text("speedup.auto_use", "Utiliser automatiquement"), "speedup"))
            {
                var plan = SpeedUpAutoUse.ComputeBestPlan(speedUpSelectedCategory, (long)GetSpeedUpRemainingForHotspot(speedUpTargetHotspotId, speedUpSelectedCategory));
                if (plan != null && SpeedUpAutoUse.ApplyPlan(plan, speedUpSelectedCategory))
                {
                    for (int i = 0; i < plan.Stacks.Count; i++)
                        ApplySpeedUpToTarget(plan.Stacks[i].Item, plan.Stacks[i].Count);
                    UIFeedbackSystem.ShowFloatingText(BeeLocalization.Text("speedup.auto_applied", "Accélérations appliquées"), Vector2.zero, new Color(1f, 0.85f, 0.25f));
                    AudioManager.Instance?.PlayUIClick();
                }
                else
                {
                    UIFeedbackSystem.ShowFloatingText(BeeLocalization.Text("speedup.insufficient", "Pas assez d'accélérations"), Vector2.zero, new Color(0.8f, 0.3f, 0.2f));
                }
            }

            Rect finishBtn = new Rect(actionBar.xMax - 12f - (actionBar.width * 0.5f - 18f), actionBar.y + 6f, actionBar.width * 0.5f - 18f, 32f);
            if (DrawPremiumButton(finishBtn, BeeLocalization.Text("speedup.finish_now", "Terminer immédiatement"), "gem"))
            {
                UIFeedbackSystem.ShowFloatingText(BeeLocalization.Text("speedup.gem_feature_soon", "Bientôt disponible avec gemmes"), Vector2.zero, new Color(0.4f, 0.8f, 1f));
                AudioManager.Instance?.PlayUIClick();
            }

            float contentY = header.yMax + 10f;
            float contentHeight = actionBar.y - contentY - 10f;
            Rect contentViewport = new Rect(panel.x + 10f, contentY, panel.width - 20f, contentHeight);

            DrawSpeedUpContent(contentViewport, speedUpSelectedCategory, speedUpTargetHotspotId);
        }

