        private static string MiniChatBarText(string channelId)
        {
            List<ChatMessageData> recent = MiniChatRecentMessages(channelId, 1);
            if (recent.Count == 0) return MiniChatChannelDisplayName(channelId) + " · " + BeeLocalization.Text("chat.mini.empty", "Aucun message");
            ChatMessageData last = recent[0];
            string author = string.IsNullOrWhiteSpace(last.Author) ? BeeLocalization.Text("chat.sender.unknown", "Joueur") : last.Author;
            return MiniChatChannelDisplayName(channelId) + " · " + author + ": " + MiniChatTruncate(last.Text, 34);
        }
