        private static bool IsActiveHiveMenu(string id)
        {
            if (id == "Hive") return activeHiveMenu == HiveMenuMode.Hive;
            if (id == "Actions") return activeHiveMenu == HiveMenuMode.Actions;
            if (id == "Army") return activeHiveMenu == HiveMenuMode.Army;
            if (id == "Research") return activeHiveMenu == HiveMenuMode.Research;
            if (id == "Alliance") return activeHiveMenu == HiveMenuMode.Alliance;
            return false;
        }

        private static void ActivateHiveMenu(HiveMenuMode menu, string label)
        {
            referenceSurfaceMode = ReferenceSurfaceMode.Hive;
            if (menu != HiveMenuMode.Army) ResetFormationReadinessDraft();
            activeHiveMenu = menu;
            detailPanelClosed = menu != HiveMenuMode.Hive && menu != HiveMenuMode.Actions;
            if (menu == HiveMenuMode.Alliance)
            {
                allianceScreenOpenedAt = NowForUi();
                allianceOverviewTab = "overview";
                allianceTabChangedAt = allianceScreenOpenedAt;
            }
            if (menu == HiveMenuMode.Research)
            {
                researchFullscreenOpenedAt = NowForUi();
                researchFullscreenFilter = "all";
                researchFullscreenScroll = Vector2.zero;
            }
            localPreviewLoopMessage = menu == HiveMenuMode.Research && OfficialResearchConfigured()
                ? BeeLocalization.Text("research.official.opened", "Recherche officielle ouverte")
                : label + " ouvert - simulation locale";
            localPreviewLastActionStatus = label;
        }

        private static void DrawSideRail()
        {
            if (IsPortraitLayout()) return;
            // Ce widget de file d'attente est visible en permanence, meme quand aucun
            // panneau de batiment n'est ouvert - sans son propre sondage periodique, il
            // reste fige sur l'instantane de la derniere ouverture de panneau (ex. "0"
            // au lieu de "A valider" une fois le chantier termine).
            if (OfficialBuildingUpgradeConfigured() && !buildingUpgradeController.IsBusy &&
                NowForUi() - officialProductionDetailLastLiveRefreshAt > 5f)
            {
                buildingUpgradeController.Refresh();
            }
            HiveBuildingUpgradeScreenModel officialUpgrade = OfficialBuildingUpgradeConfigured()
                ? OfficialBuildingUpgradeModel()
                : null;
            HiveResearchScreenModel officialResearch = OfficialResearchConfigured()
                ? OfficialResearchModel()
                : null;
            HiveDoctrineRecruitmentScreenModel officialRecruitment =
                OfficialDoctrineRecruitmentConfigured()
                    ? OfficialDoctrineRecruitmentModel()
                    : null;
            bool officialConstruction = officialUpgrade != null && officialUpgrade.ActiveOperation != null;
            bool officialResearchActive = officialResearch != null && officialResearch.ActiveOperation != null;
            bool officialTrainingActive = officialRecruitment != null &&
                officialRecruitment.ActiveOperation != null;
            bool constructionRunning = OfficialBuildingUpgradeConfigured() ? officialConstruction : IsUpgradeRunning();
            bool trainingRunning = OfficialDoctrineRecruitmentConfigured()
                ? officialTrainingActive
                : IsTrainingRunning();
            bool researchRunning = OfficialResearchConfigured() ? officialResearchActive : IsResearchRunning();
            string idle = BeeLocalization.Text("ui.queue.idle", "Inactif");
            string free = BeeLocalization.Text("ui.queue.free", "Libre");
            string[] labels =
            {
                BeeLocalization.Text("ui.queue.build", "Construction"),
                BeeLocalization.Text("ui.queue.train", "Entraînement"),
                BeeLocalization.Text("ui.queue.research", "Recherche")
            };
            string[] icons = { "build", "sword", "research" };
            string inProgress = BeeLocalization.Text("ui.queue.in_progress", "En cours");
            string[] states =
            {
                constructionRunning ? inProgress : free,
                trainingRunning ? inProgress : free,
                researchRunning ? inProgress : free
            };
            string[] statusKinds =
            {
                officialConstruction && officialUpgrade.ActiveOperation.IsAwaitingCompletion
                    ? "ready"
                    : constructionRunning ? "running" : "idle",
                officialTrainingActive &&
                    officialRecruitment.ActiveOperation.AwaitingCompletion
                    ? "ready"
                    : trainingRunning ? "running" : "idle",
                officialResearchActive && officialResearch.ActiveOperation.IsAwaitingCompletion
                    ? "ready"
                    : researchRunning ? "research" : "idle"
            };
            float[] progress =
            {
                officialConstruction
                    ? (float)officialUpgrade.Progress01(buildingUpgradeController.Elapsed)
                    : constructionRunning ? UpgradeProgress01() : 0f,
                officialTrainingActive
                    ? (float)officialRecruitment.Progress01(
                        doctrineRecruitmentController.Elapsed)
                    : trainingRunning ? TrainingProgress01() : 0f,
                officialResearchActive
                    ? (float)officialResearch.Progress01(researchController.Elapsed)
                    : researchRunning ? ResearchProgress01() : 0f
            };
            string[] times =
            {
                officialConstruction
                    ? (officialUpgrade.ActiveOperation.IsAwaitingCompletion
                        ? BeeLocalization.Text("building_upgrade.queue.ready", "À valider")
                        : FormatBuildingUpgradeDuration(officialUpgrade.Remaining(buildingUpgradeController.Elapsed)))
                    : constructionRunning ? RemainingQueueSeconds(UpgradeProgress01(), localPreviewUpgradeDuration) : idle,
                officialTrainingActive
                    ? (officialRecruitment.ActiveOperation.AwaitingCompletion
                        ? BeeLocalization.Text(
                            "formation_readiness.official.queue.ready",
                            "À réclamer")
                        : FormatBuildingUpgradeDuration(
                            officialRecruitment.Remaining(
                                doctrineRecruitmentController.Elapsed)))
                    : trainingRunning
                        ? RemainingQueueSeconds(
                            TrainingProgress01(),
                            localPreviewTrainingDuration)
                        : idle,
                officialResearchActive
                    ? (officialResearch.ActiveOperation.IsAwaitingCompletion
                        ? BeeLocalization.Text("research.official.queue.ready", "À valider")
                        : FormatBuildingUpgradeDuration(officialResearch.Remaining(researchController.Elapsed)))
                    : researchRunning ? RemainingQueueSeconds(ResearchProgress01(), localPreviewResearchDuration) : idle
            };

            Rect railBack = new Rect(8f, 88f, 124f, labels.Length * 68f + 4f);
            DrawSideTimerBackplate(railBack);
            for (int i = 0; i < labels.Length; i++)
            {
                Rect card = new Rect(12f, 96f + i * 68f, 116f, 58f);
                DrawQueueTimerCard(card, icons[i], labels[i], states[i], times[i], progress[i], statusKinds[i]);
                bool timerActive = i == 0 ? constructionRunning : i == 1 ? trainingRunning : researchRunning;
                if (timerActive)
                {
                    SpeedUpCategory category = i == 0 ? SpeedUpCategory.Construction : i == 1 ? SpeedUpCategory.Training : SpeedUpCategory.Research;
                    string targetId = i == 0
                        ? (officialConstruction ? officialUpgrade.ActiveOperation.BuildingKey : localPreviewUpgradeHotspotId)
                        : i == 1
                            ? (officialTrainingActive ? officialRecruitment.ActiveOperation.Family : localPreviewTrainingTroopType)
                            : (officialResearchActive ? officialResearch.ActiveOperation.ResearchId : localPreviewResearchId);
                    float remaining = i == 0
                        ? GetBuildingUpgradeRemaining(targetId)
                        : i == 1
                            ? officialTrainingActive
                                ? Mathf.Max(0f, (float)officialRecruitment.Remaining(doctrineRecruitmentController.Elapsed).TotalSeconds)
                                : GetTrainingRemaining(targetId)
                            : GetResearchRemaining(targetId);
                    Rect speedUpButton = new Rect(card.xMax - 25f, card.y + 5f, 20f, 18f);
                    DrawPremiumPanel(speedUpButton, new Color(0.20f, 0.12f, 0.025f, 0.96f), new Color(1f, 0.72f, 0.18f, 0.90f));
                    GUI.Label(speedUpButton, "S", centeredTinyLabelStyle);
                    if (GUI.Button(speedUpButton, string.Empty, GUIStyle.none))
                    {
                        OpenSpeedUpDialog(category, targetId, (long)Mathf.Max(0, Mathf.CeilToInt(remaining)));
                        continue;
                    }
                }
                if (!GUI.Button(card, string.Empty, GUIStyle.none)) continue;

                activeMainMenuId = string.Empty;
                if (i == 0)
                {
                    string hotspotId = officialConstruction ? officialUpgrade.ActiveOperation.BuildingKey : localPreviewUpgradeHotspotId;
                    ReferenceHiveHotspot hotspot = FindReferenceHotspot(hotspotId);
                    activeHiveMenu = HiveMenuMode.Hive;
                    if (!string.IsNullOrWhiteSpace(hotspot.HotspotId))
                    {
                        detailPanelClosed = false;
                        SelectReferenceHotspot(hotspot);
                    }
                }
                else if (i == 1)
                {
                    if (!officialTrainingActive && !string.IsNullOrWhiteSpace(localPreviewTrainingTroopType))
                        selectedLocalTroopType = localPreviewTrainingTroopType;
                    activeHiveMenu = HiveMenuMode.Army;
                }
                else
                {
                    activeHiveMenu = HiveMenuMode.Research;
                }
            }
        }

        private static void DrawSideTimerBackplate(Rect rect)
        {
            Color previous = GUI.color;
            GUI.color = new Color(0f, 0f, 0f, 0.20f);
            GUI.DrawTexture(new Rect(rect.x + 4f, rect.y + 6f, rect.width, rect.height), GetPremiumTexture("panel-shadow"), ScaleMode.StretchToFill, true);
            GUI.color = new Color(0.018f, 0.016f, 0.013f, 0.42f);
            GUI.DrawTexture(rect, GetPremiumTexture("panel-grain"), ScaleMode.StretchToFill, true);
            GUI.color = new Color(1f, 0.70f, 0.16f, 0.18f);
            GUI.DrawTexture(new Rect(rect.x + 15f, rect.y + 16f, 2f, rect.height - 32f), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            GUI.color = previous;
        }

        private static void DrawQueueTimerCard(Rect rect, string icon, string label, string state, string time, float progress, string statusKind)
        {
            Color accent = TimerAccentColor(statusKind);
            DrawPremiumPanel(rect, new Color(0.026f, 0.024f, 0.020f, 0.80f), new Color(accent.r, accent.g, accent.b, 0.64f));
            Rect iconWell = new Rect(rect.x + 7f, rect.y + 8f, 32f, 32f);
            DrawPremiumPanel(iconWell, new Color(0.018f, 0.018f, 0.015f, 0.68f), new Color(accent.r, accent.g, accent.b, 0.46f));
            DrawGameIcon(new Rect(iconWell.x + 4f, iconWell.y + 4f, 24f, 24f), icon, Color.white);

            GUIStyle timerLabelStyle = new GUIStyle(smallStyle)
            {
                fontSize = label.Length > 10 ? 9 : label.Length > 6 ? 10 : smallStyle.fontSize,
                wordWrap = false,
                clipping = TextClipping.Clip
            };
            GUI.Label(new Rect(rect.x + 44f, rect.y + 7f, rect.width - 50f, 15f), label, timerLabelStyle);
            GUI.Label(new Rect(rect.x + 44f, rect.y + 22f, rect.width - 50f, 13f), state, tinyLabelStyle);

            Rect timeBadge = new Rect(rect.x + 44f, rect.y + 36f, rect.width - 52f, 16f);
            GUI.color = new Color(0f, 0f, 0f, 0.24f);
            GUI.DrawTexture(timeBadge, Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            GUI.color = Color.white;
            GUI.Label(timeBadge, time, centeredTinyLabelStyle);

            DrawProgressBar(new Rect(rect.x + 8f, rect.yMax - 5f, rect.width - 16f, 4f), progress);
            GUI.color = new Color(accent.r, accent.g, accent.b, 0.40f);
            GUI.DrawTexture(new Rect(rect.x + 2f, rect.y + 9f, 2f, rect.height - 18f), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            GUI.color = Color.white;
        }

        private static Color TimerAccentColor(string statusKind)
        {
            switch (statusKind)
            {
                case "running": return new Color(0.58f, 0.86f, 1f, 1f);
                case "ready": return new Color(0.52f, 1f, 0.62f, 1f);
                case "idle": return new Color(0.62f, 0.52f, 0.34f, 1f);
                case "research": return new Color(0.70f, 0.62f, 1f, 1f);
                default: return new Color(1f, 0.70f, 0.16f, 1f);
            }
        }

        private static string UpgradeQueueBuildingLabel()
        {
            return string.IsNullOrWhiteSpace(localPreviewUpgradeHotspotId)
                ? BeeLocalization.Text("ui.queue.free", "Libre")
                : LocalizedHotspotLabel(FindReferenceHotspot(localPreviewUpgradeHotspotId));
        }

        private static string RemainingQueueSeconds(float progress, float duration)
        {
            return Mathf.CeilToInt((1f - Mathf.Clamp01(progress)) * duration).ToString(CultureInfo.InvariantCulture) + "s";
        }

        private static string LocalizedTroopType(string troopType)
        {
            if (IsWorkerTrainingType(troopType)) return BeeLocalization.Text("bee.worker", troopType);
            if (string.Equals(troopType, "Gardiennes", StringComparison.Ordinal)) return BeeLocalization.Text("bee.guardian", troopType);
            if (string.Equals(troopType, "Voltigeuses", StringComparison.Ordinal)) return BeeLocalization.Text("combat_doctrine.family.wingrunners.name", troopType);
            if (string.Equals(troopType, "Lanceuses", StringComparison.Ordinal)) return BeeLocalization.Text("combat_doctrine.family.darters.name", troopType);
            if (string.Equals(troopType, "Eclaireuses", StringComparison.Ordinal)) return BeeLocalization.Text("bee.scout", troopType);
            if (string.Equals(troopType, "Soldats", StringComparison.Ordinal)) return BeeLocalization.Text("bee.soldier", troopType);
            return troopType;
        }

