        public static string[] QueueRailForProof()
        {
            HiveBuildingUpgradeScreenModel officialUpgrade = OfficialBuildingUpgradeConfigured()
                ? OfficialBuildingUpgradeModel()
                : null;
            bool officialConstruction = officialUpgrade != null && officialUpgrade.ActiveOperation != null;
            bool constructionRunning = OfficialBuildingUpgradeConfigured() ? officialConstruction : IsUpgradeRunning();
            string constructionTarget = officialConstruction
                ? officialUpgrade.ActiveOperation.BuildingKey
                : constructionRunning ? localPreviewUpgradeHotspotId : "none";
            float constructionProgress = officialConstruction
                ? (float)officialUpgrade.Progress01(buildingUpgradeController.Elapsed)
                : constructionRunning ? UpgradeProgress01() : 0f;
            HiveDoctrineRecruitmentScreenModel officialRecruitment =
                OfficialDoctrineRecruitmentConfigured()
                    ? OfficialDoctrineRecruitmentModel()
                    : null;
            bool officialTrainingActive = officialRecruitment != null &&
                officialRecruitment.ActiveOperation != null;
            bool trainingRunning = OfficialDoctrineRecruitmentConfigured()
                ? officialTrainingActive
                : IsTrainingRunning();
            string trainingTarget = officialTrainingActive
                ? officialRecruitment.ActiveOperation.Family
                : trainingRunning
                    ? localPreviewTrainingTroopType
                    : "none";
            float trainingProgress = officialTrainingActive
                ? (float)officialRecruitment.Progress01(
                    doctrineRecruitmentController.Elapsed)
                : trainingRunning ? TrainingProgress01() : 0f;
            HiveResearchScreenModel officialResearch = OfficialResearchConfigured()
                ? OfficialResearchModel()
                : null;
            bool officialResearchActive = officialResearch != null && officialResearch.ActiveOperation != null;
            bool researchRunning = OfficialResearchConfigured() ? officialResearchActive : IsResearchRunning();
            string researchTarget = officialResearchActive
                ? officialResearch.ActiveOperation.ResearchId
                : researchRunning ? localPreviewResearchId : "none";
            float researchProgress = officialResearchActive
                ? (float)officialResearch.Progress01(researchController.Elapsed)
                : researchRunning ? ResearchProgress01() : 0f;
            return new[]
            {
                "queue_slots:3",
                "construction_active:" + BoolProof(constructionRunning),
                "construction_target:" + constructionTarget,
                "construction_label:" + (constructionRunning ? LocalizedHotspotLabel(FindReferenceHotspot(constructionTarget)) : BeeLocalization.Text("ui.queue.free", "Libre")),
                "construction_progress:" + constructionProgress.ToString("0.###", CultureInfo.InvariantCulture),
                "construction_authority:" + (OfficialBuildingUpgradeConfigured() ? "server" : "local_preview"),
                "construction_offline_read_only:" + BoolProof(officialUpgrade != null && officialUpgrade.IsReadOnly),
                "training_active:" + BoolProof(trainingRunning),
                "training_target:" + trainingTarget,
                "training_progress:" + trainingProgress.ToString("0.###", CultureInfo.InvariantCulture),
                "training_authority:" +
                    (OfficialDoctrineRecruitmentConfigured()
                        ? "server"
                        : "local_preview"),
                "training_offline_read_only:" +
                    BoolProof(
                        officialRecruitment != null &&
                        officialRecruitment.IsReadOnly),
                "research_active:" + BoolProof(researchRunning),
                "research_target:" + researchTarget,
                "research_label:" + (researchRunning ? ResearchTitle(researchTarget) : BeeLocalization.Text("ui.queue.free", "Libre")),
                "research_progress:" + researchProgress.ToString("0.###", CultureInfo.InvariantCulture),
                "research_authority:" + (OfficialResearchConfigured() ? "server" : "local_preview"),
                "research_offline_read_only:" + BoolProof(officialResearch != null && officialResearch.IsReadOnly),
                "static_placeholder_timers:false"
            };
        }

