        public static Rect[] OfficialDailyRoundActionRectsForProof(
            bool portrait,
            float screenWidth,
            float screenHeight)
        {
            Rect panel =
                GuidedQuestMenuPanelRect(portrait, screenWidth, screenHeight);
            float top = panel.y + 110f;
            float contentX = panel.x + 18f;
            float contentWidth = panel.width - 36f;
            float refreshWidth = portrait ? 82f : 96f;
            float rowHeight = portrait ? 58f : 62f;
            float rowsTop = top + 99f;
            var result = new Rect[5];
            result[0] = new Rect(
                contentX + contentWidth - refreshWidth,
                top,
                refreshWidth,
                44f);
            float statusWidth = portrait ? 66f : 78f;
            for (int index = 0; index < 3; index++)
            {
                Rect row = new Rect(
                    contentX,
                    rowsTop + index * (rowHeight + 4f),
                    contentWidth,
                    rowHeight);
                result[index + 1] = new Rect(
                    row.xMax - statusWidth - 6f,
                    row.y + (row.height - 44f) * 0.5f,
                    statusWidth,
                    44f);
            }
            float rewardY =
                rowsTop + 3f * (rowHeight + 4f) + 5f;
            Rect reward = new Rect(
                contentX,
                rewardY,
                contentWidth,
                Mathf.Max(82f, panel.yMax - rewardY - 12f));
            float actionWidth = portrait ? 106f : 126f;
            result[4] = new Rect(
                reward.xMax - actionWidth - 10f,
                reward.y + Mathf.Max(8f, (reward.height - 44f) * 0.5f),
                actionWidth,
                44f);
            return result;
        }

