        public static Rect[] OfficialBuildingUpgradeActionRectsForProof(
            bool portrait,
            float screenWidth,
            float screenHeight,
            bool alongsideProduction)
        {
            Rect panel;
            if (portrait)
            {
                panel = new Rect(10f, screenHeight - 78f - PortraitDetailPanelHeight - 12f,
                    screenWidth - 20f, PortraitDetailPanelHeight);
            }
            else
            {
                bool tablet = screenWidth >= 1600f && screenHeight >= 900f;
                float width = tablet ? 332f : 292f;
                float height = tablet ? 264f : 248f;
                float top = tablet ? 132f : 112f;
                float bottom = tablet ? 104f : 82f;
                float x = Mathf.Max(tablet ? 160f : 148f, screenWidth - width - 18f);
                float y = Mathf.Min(118f, Mathf.Max(top + 12f, screenHeight - bottom - height - 18f));
                panel = new Rect(x, y, width, height);
            }

            Rect row = portrait
                ? new Rect(panel.x + 18f, panel.y + 50f, panel.width - 36f, 44f)
                : new Rect(panel.x + 14f, panel.y + 164f, panel.width - 28f, 44f);
            if (!alongsideProduction) return new[] { row };
            float productionRatio = portrait ? 0.56f : 0.58f;
            Rect production = new Rect(row.x, row.y, Mathf.Floor(row.width * productionRatio), row.height);
            Rect upgrade = new Rect(production.xMax + 6f, row.y, row.xMax - production.xMax - 6f, row.height);
            return new[] { production, upgrade };
        }

        public static string[] OfficialBuildingUpgradeForProof(string hotspotId)
        {
            HiveBuildingUpgradeScreenModel model = OfficialBuildingUpgradeModel();
            HiveBuildingUpgradeOfferModel offer = model == null ? null : model.OfferFor(hotspotId);
            HiveBuildingUpgradeOperationModel operation = model == null ? null : model.ActiveOperation;
