                "building_upgrade_active_operation:" + (operation == null ? "none" : operation.OperationId.ToString("D")),
                "building_upgrade_active_status:" + (operation == null ? "none" : operation.Status),
                "building_upgrade_can_start:" + BoolProof(model != null && model.CanStart(hotspotId)),
