        public static void PersistLocalPreviewBuildingLevelForProof(string hotspotId, int level)
        {
            int safeLevel = Mathf.Clamp(level, 1, LocalPreviewHiveProgressCodec.MaxBuildingLevel);
            localPreviewBuildingLevels[hotspotId] = Mathf.Max(EnsureLocalPreviewLevel(hotspotId), safeLevel);
            PersistLocalPreviewBuildingLevel(hotspotId, localPreviewBuildingLevels[hotspotId]);
        }

        public static void PersistLocalPreviewPopulationForProof(string populationId, int count)
        {
            int safeCount = Mathf.Clamp(count, 0, LocalPreviewHiveProgressCodec.MaxPopulationCount);
            switch (populationId)
            {
                case "workers": localPreviewWorkers = Mathf.Max(localPreviewWorkers, safeCount); break;
                case "soldiers": localPreviewSoldiers = Mathf.Max(localPreviewSoldiers, safeCount); break;
                case "guardians": localPreviewGuardians = Mathf.Max(localPreviewGuardians, safeCount); break;
                case "scouts": localPreviewScouts = Mathf.Max(localPreviewScouts, safeCount); break;
                case "wingrunners": localPreviewWingrunners = Mathf.Max(localPreviewWingrunners, safeCount); break;
                case "darters": localPreviewDarters = Mathf.Max(localPreviewDarters, safeCount); break;
                default: return;
            }
            PersistLocalPreviewPopulationCount(populationId, safeCount);
        }

