        public static void PrepareLocalPreviewHiveProgressCaptureForProof(string state)
        {
            SetPlayableHiveLoopProofState("idle");
            bool building = string.Equals(state, "building_en", StringComparison.Ordinal);
            SetLocaleForRuntime(building ? "en-US" : "fr-CA");
            SetReferenceSurfaceModeForProof("hive");
            communicationPanelOpen = false;
            activeMainMenuId = string.Empty;
            playerMenuOpen = false;
            vipMenuOpen = false;
            powerMenuOpen = false;
            localPreviewQueueResumeNoticeVisible = false;

            string profileId = localPreviewStrategicProfile?.profileId ?? "capture-profile";
            localPreviewHiveProgress = LocalPreviewHiveProgressCodec.CreateDefault(profileId);
            LocalPreviewHiveProgressCodec.MergeBuildingLevel(localPreviewHiveProgress, "honey_storage", 28);
            LocalPreviewHiveProgressCodec.MergeBuildingLevel(localPreviewHiveProgress, "wax_workshop", 25);
            LocalPreviewHiveProgressCodec.MergeBuildingLevel(localPreviewHiveProgress, "guard_post", 27);
            LocalPreviewHiveProgressCodec.MergePopulationCount(localPreviewHiveProgress, "workers", 36);
            LocalPreviewHiveProgressCodec.MergePopulationCount(localPreviewHiveProgress, "soldiers", 34);
            LocalPreviewHiveProgressCodec.MergePopulationCount(localPreviewHiveProgress, "guardians", 16);
            LocalPreviewHiveProgressCodec.MergePopulationCount(localPreviewHiveProgress, "scouts", 17);
            LocalPreviewHiveProgressCodec.MergePopulationCount(localPreviewHiveProgress, "wingrunners", 6);
            LocalPreviewHiveProgressCodec.MergePopulationCount(localPreviewHiveProgress, "darters", 8);
            localPreviewHiveProgressLoaded = true;
            localPreviewHiveProgressRestoreStatus = "restored_device_preview";
            localPreviewBuildingLevels.Clear();
            for (int i = 0; i < localPreviewHiveProgress.buildings.Count; i++)
            {
                LocalPreviewBuildingProgress entry = localPreviewHiveProgress.buildings[i];
                localPreviewBuildingLevels[entry.hotspotId] = entry.level;
            }
            localPreviewWorkers = localPreviewHiveProgress.workers;
            localPreviewSoldiers = localPreviewHiveProgress.soldiers;
            localPreviewGuardians = localPreviewHiveProgress.guardians;
            localPreviewScouts = localPreviewHiveProgress.scouts;
            localPreviewWingrunners = localPreviewHiveProgress.wingrunners;
            localPreviewDarters = localPreviewHiveProgress.darters;

            if (building)
            {
                activeHiveMenu = HiveMenuMode.Hive;
                detailPanelClosed = false;
                ReferenceHiveHotspot hotspot = FindReferenceHotspot("wax_workshop");
                SelectReferenceHotspot(hotspot);
                localPreviewLastCompletedUpgradeHotspotId = hotspot.HotspotId;
                localPreviewLastActionStatus = BeeLocalization.Text("hive_progress.building.saved", "Saved on device · server not synchronized");
            }
            else
            {
                activeHiveMenu = HiveMenuMode.Army;
                detailPanelClosed = true;
                selectedLocalTroopType = "Eclaireuses";
                localPreviewArmyPanelMode = "detail";
                localPreviewLastActionStatus = BeeLocalization.Text("hive_progress.army.restored", "Effectifs restaurés depuis l'appareil");
            }
        }

