        public static void ExpireLocalPreviewQueuesForProof()
        {
            EnsureLocalPreviewQueueJournalLoaded();
            long expired = UtcNowTicks() - TimeSpan.FromSeconds(1d).Ticks;
            if (localPreviewQueueJournal.upgrade.Exists)
            {
                localPreviewQueueJournal.upgrade.endsUtcTicks = expired;
                localPreviewUpgradeStartedAt = NowForUi() - localPreviewUpgradeDuration - 0.1f;
            }
            if (localPreviewQueueJournal.training.Exists)
            {
                localPreviewQueueJournal.training.endsUtcTicks = expired;
                localPreviewTrainingStartedAt = NowForUi() - localPreviewTrainingDuration - 0.1f;
            }
            if (localPreviewQueueJournal.research.Exists)
            {
                localPreviewQueueJournal.research.endsUtcTicks = expired;
                localPreviewResearchStartedAt = NowForUi() - localPreviewResearchDuration - 0.1f;
            }
            SaveLocalPreviewQueueJournal();
        }

