        private static void OpenCanonicalWorldMap()
        {
            bool guidedWorldDeparture = GuidedCollectionTutorialTargetsSurfaceSwitch();
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.Inactive
                && !guidedWorldDeparture)
            {
                guidedCollectionTutorialBlockedClicks++;
                return;
            }

            if (guidedWorldDeparture) DepartToGuidedWorldMapForProof();

            // La navigation principale "Carte" doit toujours ouvrir la vraie carte du monde,
            // jamais la scene de test Wave5 Premium 25x25 - cette scene de test n'a pas de bouton
            // retour et affiche des informations de debug (hash Git, compteurs de tuiles) au
            // joueur. Le bascule PlayerPrefs Wave5PremiumMapMode reste utilisable depuis le menu
            // "Developpement" (Editeur/Development build uniquement) pour ouvrir cette scene de
            // test directement via TryOpenWave5Premium25x25, mais ne doit plus jamais influencer
            // ce bouton de navigation en jeu (voir PREMIUM_PLAYTEST_REPORT.md, PB-002 - un joueur
            // reel s'est retrouve bloque sans issue sur cette scene de test).
            SplashDevelopmentSceneConfig.DisableWave5PremiumMapMode();
            localPreviewLoopMessage = "Ouverture de la carte mondiale Wave6 50x50 exact-crop";
            localPreviewLastActionStatus = "Carte mondiale";
            SceneManager.LoadScene(SplashDevelopmentSceneConfig.WorldMapScenePath, LoadSceneMode.Single);
        }

        private static string LocalizedBuildingActivity(HiveBuildingActivityDefinition definition)
        {
            if (definition == null) return BeeLocalization.Text("building.activity.chamber", "Entretien de la chambre");
            return BeeLocalization.Text(definition.LocalizationKey, definition.HotspotId);
        }

        private static string BuildingActivityStatus(ReferenceHiveHotspot hotspot)
        {
            HiveBuildingActivityDefinition definition = HiveBuildingActivityCatalog.Resolve(hotspot.HotspotId);
            string activity = LocalizedBuildingActivity(definition);
            if (IsUpgradeRunning() && string.Equals(localPreviewUpgradeHotspotId, hotspot.HotspotId, StringComparison.Ordinal))
            {
                return string.Format(
                    CultureInfo.CurrentCulture,
                    BeeLocalization.Text("building.activity.upgrade", "Amélioration en cours · {0}%"),
                    Mathf.RoundToInt(UpgradeProgress01() * 100f));
            }

            if (string.Equals(hotspot.HotspotId, "nursery_cluster", StringComparison.Ordinal) && IsWorkerTrainingRunning())
            {
                return string.Format(
                    CultureInfo.CurrentCulture,
                    BeeLocalization.Text("building.activity.worker_training", "Éclosion d’une ouvrière · {0}%"),
                    Mathf.RoundToInt(TrainingProgress01() * 100f));
            }

            if (string.Equals(hotspot.HotspotId, "guard_post", StringComparison.Ordinal) && IsTrainingRunning() && !IsWorkerTrainingRunning())
            {
                return string.Format(
                    CultureInfo.CurrentCulture,
                    BeeLocalization.Text("building.activity.guard_training", "Formation en cours · {0}%"),
                    Mathf.RoundToInt(TrainingProgress01() * 100f));
            }

            if (!string.IsNullOrWhiteSpace(ManualProductionIcon(hotspot.HotspotId)))
            {
                if (OfficialOfflineProductionConfigured())
                {
                    HiveOfflineProductionScreenModel officialModel = OfficialOfflineProductionModel();
                    HiveOfflineProductionLineModel officialLine = OfficialOfflineProductionLine(hotspot.HotspotId);
                    // Client optimiste (demande de Jeff) : une collecte ou une erreur reseau ne
                    // concerne qu'UN batiment a la fois, meme si le modele partage bascule son State
                    // global le temps de la mutation. Les DEUX AUTRES batiments doivent continuer a
                    // afficher leur propre remplissage reel (officialLine, deja a jour) plutot que de
                    // basculer sur un message generique de synchronisation - sinon toute la ruche a
                    // l'air d'attendre le serveur alors qu'un seul batiment est concerne.
                    bool thisBuildingCollecting = officialModel != null &&
                        officialModel.State == HiveOfflineProductionScreenState.Collecting &&
                        string.Equals(officialModel.CollectingBuildingKey, hotspot.HotspotId, StringComparison.Ordinal);
                    bool thisBuildingRetryTarget = officialModel != null &&
                        officialModel.State == HiveOfflineProductionScreenState.Error &&
                        string.Equals(officialModel.RetryBuildingKey, hotspot.HotspotId, StringComparison.Ordinal);
                    if (officialModel == null || officialLine == null || thisBuildingCollecting || thisBuildingRetryTarget)
                        return OfficialProductionStatusText();
                    if (officialModel.State != HiveOfflineProductionScreenState.Ready &&
                        officialModel.State != HiveOfflineProductionScreenState.Collecting &&
                        officialModel.State != HiveOfflineProductionScreenState.OfflineReadOnly &&
                        officialModel.State != HiveOfflineProductionScreenState.Error)
                        return OfficialProductionStatusText();
                }

                ManualProductionForecast forecast = ManualProductionForecastFor(hotspot.HotspotId);
                if (forecast.State == ManualProductionForecastState.Full)
                {
                    return string.Format(
                        CultureInfo.CurrentCulture,
                        BeeLocalization.Text("building.activity.full", "{0} · plein, collecte manuelle"),
                        activity);
                }
                return string.Format(
                    CultureInfo.CurrentCulture,
                    BeeLocalization.Text("building.activity.production", "{0} · remplissage {1}%"),
                    activity,
                    Mathf.RoundToInt((float)forecast.Fill01 * 100f));
            }

            if (string.Equals(hotspot.HotspotId, "nursery_cluster", StringComparison.Ordinal))
            {
                return string.Format(
                    CultureInfo.CurrentCulture,
                    BeeLocalization.Text("building.activity.nursery_status", "{0} · nutrition {1}%"),
                    activity,
                    Mathf.RoundToInt(localPreviewBroodNutrition));
            }

            if (string.Equals(hotspot.HotspotId, "guard_post", StringComparison.Ordinal))
            {
                return string.Format(
                    CultureInfo.CurrentCulture,
                    BeeLocalization.Text("building.activity.guard_status", "{0} · sécurité {1}%"),
                    activity,
                    localPreviewHiveSecurity);
            }

            return activity;
        }

        private static Color BuildingActivityAccent(HiveBuildingActivityKind kind)
        {
            switch (kind)
            {
                case HiveBuildingActivityKind.NectarStorage: return new Color(1f, 0.68f, 0.10f, 0.92f);
                case HiveBuildingActivityKind.WaxCrafting: return new Color(1f, 0.82f, 0.30f, 0.92f);
                case HiveBuildingActivityKind.PollenSorting: return new Color(0.72f, 0.92f, 0.22f, 0.92f);
                case HiveBuildingActivityKind.BroodCare: return new Color(0.38f, 0.92f, 0.58f, 0.92f);
                case HiveBuildingActivityKind.GuardPatrol: return new Color(0.98f, 0.36f, 0.18f, 0.92f);
                default: return new Color(0.72f, 0.64f, 0.42f, 0.88f);
            }
        }

        private static float BuildingActivityMotionPhase(string hotspotId, float time, int index, bool reducedMotion)
        {
            HiveBuildingActivityDefinition definition = HiveBuildingActivityCatalog.Resolve(hotspotId);
            if (reducedMotion) return (index + 1f) / (definition.SignalCount + 1f);
            return Mathf.Repeat(time * (float)definition.MotionSpeed + index / (float)definition.SignalCount, 1f);
        }

