        private static void DrawBuildingActivityBanner(Rect rect, ReferenceHiveHotspot hotspot, bool compact)
        {
            HiveBuildingActivityDefinition definition = HiveBuildingActivityCatalog.Resolve(hotspot.HotspotId);
            Color accent = BuildingActivityAccent(definition.Kind);
            if (!compact)
            {
                DrawPremiumPanel(rect, new Color(0.036f, 0.032f, 0.024f, 0.94f), new Color(accent.r, accent.g, accent.b, 0.72f));
            }

            Rect label = new Rect(rect.x + (compact ? 0f : 7f), rect.y + 1f, rect.width - (compact ? 48f : 62f), rect.height - 2f);
            GUI.Label(label, BuildingActivityStatus(hotspot), NoWrapClippedLabelStyle(tinyLabelStyle));

            Color previous = GUI.color;
            float lineY = rect.yMax - 2f;
            GUI.color = new Color(accent.r, accent.g, accent.b, compact ? 0.72f : 0.58f);
            GUI.DrawTexture(new Rect(rect.x, lineY, rect.width, 2f), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            GUI.color = previous;
        }

