        public static Rect BuildingActivityBannerRectForProof(bool portrait, float screenWidth, float screenHeight)
        {
            Rect panel;
            if (portrait)
            {
                panel = new Rect(10f, screenHeight - 78f - PortraitDetailPanelHeight - 12f, screenWidth - 20f, PortraitDetailPanelHeight);
                return BuildingActivityBannerRect(true, panel);
            }

            bool tablet = screenWidth >= 1600f && screenHeight >= 900f;
            float width = tablet ? 332f : 292f;
            float height = 264f;
            float x = Mathf.Max(tablet ? 160f : 148f, screenWidth - width - 18f);
            float top = tablet ? 132f : 112f;
            float bottom = tablet ? 104f : 82f;
            float y = Mathf.Min(118f, Mathf.Max(top + 12f, screenHeight - bottom - height - 18f));
            panel = new Rect(x, y, width, height);
            return BuildingActivityBannerRect(false, panel);
        }

