                RunOfficialBuildingUpgradeAction(hotspot.HotspotId);
            DrawProgressBar(new Rect(panel.x + 16f, panel.y + 216f, panel.width - 32f, 7f), progress);
            DrawLocalContextualSpeedUpButton(panel, hotspot, false, false);
            GUI.Label(new Rect(panel.x + 16f, panel.y + 228f, panel.width - 32f, 28f),
                BeeLocalization.Text("building_upgrade.disclosure", "Coût, durée, heure et niveau validés par le serveur · cache hors ligne en lecture seule"),
                new GUIStyle(tinyLabelStyle) { wordWrap = true });
        }

        private static float officialProductionDetailLastLiveRefreshAt = -100f;
        // M016E-CL: dedicated timer for the queue sidebar's research card periodic refresh - kept
        // separate from officialProductionDetailLastLiveRefreshAt above so construction's refresh
        // cadence never resets research's (or vice versa).
        private static float officialResearchQueueLastLiveRefreshAt = -100f;
        private static void DrawOfficialProductionDetail(Rect panel, ReferenceHiveHotspot hotspot, bool compact)
        {
            // Le panneau reste ouvert plusieurs minutes pendant que la production
            // s'accumule cote serveur - sans ce sondage periodique, les quantites
            // affichees restent figees a l'instant de l'ouverture du panneau.
            if (OfficialOfflineProductionConfigured() && !offlineProductionController.IsBusy &&
                NowForUi() - officialProductionDetailLastLiveRefreshAt > 5f)
            {
                officialProductionDetailLastLiveRefreshAt = NowForUi();
                offlineProductionController.Refresh();
            }
            // Meme sondage periodique pour l'amelioration de batiment - sinon une erreur
            // passagere (ex. redemarrage du serveur) laisse le panneau bloque sur "Reponse
            // serveur refusee" indefiniment, jusqu'a ce que le joueur clique "Actualiser".
            if (OfficialBuildingUpgradeConfigured() && !buildingUpgradeController.IsBusy &&
                NowForUi() - officialProductionDetailLastLiveRefreshAt > 5f)
            {
                buildingUpgradeController.Refresh();
            }

            HiveOfflineProductionScreenModel model = OfficialOfflineProductionModel();
            HiveOfflineProductionLineModel line = OfficialOfflineProductionLine(hotspot.HotspotId);
            bool hasServerLine = line != null;
            bool canAct = OfficialProductionPrimaryActionEnabled(hotspot.HotspotId);

            if (compact)
            {
                Rect action = new Rect(panel.x + 18f, panel.y + 50f, panel.width - 36f, 44f);
                bool showOfficialUpgrade = IsOfficialUpgradeBuilding(hotspot.HotspotId) && OfficialBuildingUpgradeConfigured();
                Rect productionAction = showOfficialUpgrade
                    ? new Rect(action.x, action.y, Mathf.Floor(action.width * 0.56f), action.height)
                    : action;
                if (DrawPreviewActionButton(productionAction, OfficialProductionPrimaryActionLabel(hotspot.HotspotId), canAct))
                    RunOfficialProductionPrimaryAction(hotspot.HotspotId);
                if (showOfficialUpgrade)
                {
                    Rect upgradeAction = new Rect(productionAction.xMax + 6f, action.y, action.xMax - productionAction.xMax - 6f, action.height);
                    if (DrawPreviewActionButton(upgradeAction, OfficialBuildingUpgradeActionLabel(hotspot.HotspotId),
                        OfficialBuildingUpgradeActionEnabled(hotspot.HotspotId)))
                        RunOfficialBuildingUpgradeAction(hotspot.HotspotId);
                }

                GUIStyle wrapped = new GUIStyle(tinyLabelStyle) { wordWrap = true };
                GUI.Label(new Rect(panel.x + 18f, panel.y + 99f, panel.width - 36f, 34f), OfficialProductionAndConstructionStatus(hotspot.HotspotId), wrapped);
                if (hasServerLine)
                {
                    GUI.Label(
                        new Rect(panel.x + 18f, panel.y + 132f, panel.width - 36f, 16f),
                        FormatResource((float)line.PendingAmount) + " / " + FormatResource(line.ProductionCapacity) + " · +" + FormatResource((float)line.HourlyRate) + "/h",
                        tinyLabelStyle);
                    DrawProgressBar(
                        new Rect(panel.x + 18f, panel.y + 151f, panel.width - 36f, 6f),
                        line.ProductionCapacity <= 0L ? 0f : (float)(line.PendingAmount / line.ProductionCapacity));
                }
                else
                {
                    GUI.Label(
                        new Rect(panel.x + 18f, panel.y + 139f, panel.width - 36f, 16f),
                        BeeLocalization.Text("production.official.no_device_value", "Aucune quantité officielle inventée sur l’appareil"),
                        tinyLabelStyle);
                }
                return;
            }

            Rect resourceCard = new Rect(panel.x + 14f, panel.y + 70f, panel.width - 28f, 82f);
            DrawPremiumPanel(resourceCard, new Color(0.055f, 0.060f, 0.052f, 0.88f), new Color(0.66f, 0.46f, 0.16f, 0.72f));
            DrawGameIcon(new Rect(resourceCard.x + 12f, resourceCard.y + 14f, 42f, 42f), ManualProductionIcon(hotspot.HotspotId), Color.white);
            if (hasServerLine)
            {
                GUI.Label(new Rect(resourceCard.x + 66f, resourceCard.y + 10f, resourceCard.width - 146f, 34f), FormatResource((float)line.PendingAmount), new GUIStyle(titleStyle) { fontSize = 26 });
                GUI.Label(new Rect(resourceCard.xMax - 78f, resourceCard.y + 24f, 66f, 20f), "+" + FormatResource((float)line.HourlyRate) + "/h", badgeStyle);
                Rect progress = new Rect(resourceCard.x + 66f, resourceCard.y + 52f, resourceCard.width - 84f, 10f);
                GUI.DrawTexture(progress, GetPremiumTexture("progress-bg"), ScaleMode.StretchToFill, true);
                float fill = line.ProductionCapacity <= 0L ? 0f : (float)(line.PendingAmount / line.ProductionCapacity);
                GUI.DrawTexture(new Rect(progress.x + 2f, progress.y + 2f, (progress.width - 4f) * Mathf.Clamp01(fill), progress.height - 4f), GetPremiumTexture("progress-fill"), ScaleMode.StretchToFill, true);
                GUI.Label(new Rect(resourceCard.x + 12f, resourceCard.yMax - 20f, 110f, 16f), BeeLocalization.Text("production.official.card.capacity_label", "Capacité totale"), tinyLabelStyle);
                GUI.Label(new Rect(resourceCard.xMax - 82f, resourceCard.yMax - 20f, 70f, 16f), FormatResource(line.ProductionCapacity), tinyLabelStyle);
            }
            else
            {
                GUIStyle wrapped = new GUIStyle(smallStyle) { wordWrap = true };
                GUI.Label(new Rect(resourceCard.x + 66f, resourceCard.y + 10f, resourceCard.width - 78f, 38f), OfficialProductionStatusText(), wrapped);
                GUI.Label(
                    new Rect(resourceCard.x + 66f, resourceCard.y + 51f, resourceCard.width - 78f, 18f),
                    BeeLocalization.Text("production.official.no_device_value", "Aucune quantité officielle inventée sur l’appareil"),
                    tinyLabelStyle);
            }

            Rect actionRow = new Rect(panel.x + 14f, panel.y + 164f, panel.width - 28f, 44f);
            bool showLandscapeOfficialUpgrade = IsOfficialUpgradeBuilding(hotspot.HotspotId) && OfficialBuildingUpgradeConfigured();
            Rect primaryAction = showLandscapeOfficialUpgrade
                ? new Rect(actionRow.x, actionRow.y, Mathf.Floor(actionRow.width * 0.58f), actionRow.height)
                : actionRow;
            if (DrawPreviewActionButton(primaryAction, OfficialProductionPrimaryActionLabel(hotspot.HotspotId), canAct))
                RunOfficialProductionPrimaryAction(hotspot.HotspotId);
            if (showLandscapeOfficialUpgrade)
            {
                Rect upgradeAction = new Rect(primaryAction.xMax + 6f, actionRow.y, actionRow.xMax - primaryAction.xMax - 6f, actionRow.height);
                if (DrawPreviewActionButton(upgradeAction, OfficialBuildingUpgradeActionLabel(hotspot.HotspotId),
                    OfficialBuildingUpgradeActionEnabled(hotspot.HotspotId)))
                    RunOfficialBuildingUpgradeAction(hotspot.HotspotId);
                HiveBuildingUpgradeScreenModel upgradeModel = OfficialBuildingUpgradeModel();
                if (upgradeModel?.ActiveOperation != null && string.Equals(upgradeModel.ActiveOperation.BuildingKey, hotspot.HotspotId, StringComparison.Ordinal))
                    DrawProgressBar(new Rect(upgradeAction.x, upgradeAction.yMax + 4f, upgradeAction.width, 5f), (float)upgradeModel.Progress01(buildingUpgradeController.Elapsed));
            }
            GUI.Label(new Rect(panel.x + 16f, panel.y + 212f, panel.width - 32f, 28f), OfficialProductionAndConstructionStatus(hotspot.HotspotId), new GUIStyle(tinyLabelStyle) { wordWrap = true });
        }

        private static bool OfficialProductionPrimaryActionEnabled(string hotspotId)
        {
            if (!OfficialOfflineProductionConfigured() || offlineProductionController == null || offlineProductionController.IsBusy) return false;
            HiveOfflineProductionScreenModel model = OfficialOfflineProductionModel();
            if (model == null || model.State == HiveOfflineProductionScreenState.NotConfigured || model.State == HiveOfflineProductionScreenState.Loading || model.State == HiveOfflineProductionScreenState.Collecting || model.State == HiveOfflineProductionScreenState.OfflineReadOnly) return false;
            if (model.CanCollect(hotspotId)) return true;
            return model.State == HiveOfflineProductionScreenState.Error && !string.Equals(model.ErrorCode, "authentication_required", StringComparison.Ordinal);
        }

        private static string OfficialProductionPrimaryActionLabel(string hotspotId)
        {
            HiveOfflineProductionScreenModel model = OfficialOfflineProductionModel();
            if (model == null || model.State == HiveOfflineProductionScreenState.NotConfigured)
                return BeeLocalization.Text("production.official.action.unavailable", "Serveur requis");
            if (model.State == HiveOfflineProductionScreenState.Loading)
                return BeeLocalization.Text("production.official.loading.short", "Synchronisation");
            if (model.State == HiveOfflineProductionScreenState.Collecting)
                return BeeLocalization.Text("production.official.collecting.short", "Collecte en cours");
            if (model.State == HiveOfflineProductionScreenState.OfflineReadOnly)
                return BeeLocalization.Text("production.official.offline.short", "Lecture hors ligne");
            if (model.CanCollect(hotspotId))
                return model.State == HiveOfflineProductionScreenState.Error
                    ? BeeLocalization.Text("production.official.action.retry", "Réessayer")
                    : BeeLocalization.Text("common.collect", "Récolter");
            if (model.State == HiveOfflineProductionScreenState.Error)
                return BeeLocalization.Text("production.official.action.refresh", "Actualiser");
            return BeeLocalization.Text("production.official.in_progress", "Production serveur en cours");
        }

        private static void RunOfficialProductionPrimaryAction(string hotspotId)
        {
            if (!OfficialProductionPrimaryActionEnabled(hotspotId)) return;
            HiveOfflineProductionScreenModel model = OfficialOfflineProductionModel();
            if (model != null && model.CanCollect(hotspotId)) offlineProductionController.Collect(hotspotId);
            else offlineProductionController.Refresh();
            localPreviewLastActionStatus = OfficialProductionStatusText();
            BeginReferenceFeedbackPulse("preview");
        }

