        private static void DrawPlayableDetailActions(Rect panel, ReferenceHiveHotspot hotspot)
        {
            int level = EnsureLocalPreviewLevel(hotspot.HotspotId);
            bool barracks = hotspot.HotspotId == "guard_post";
            bool upgradeRunning = localPreviewUpgradeHotspotId == hotspot.HotspotId && IsUpgradeRunning();
            bool upgradeCompleted = !barracks && string.Equals(localPreviewLastCompletedUpgradeHotspotId, hotspot.HotspotId, StringComparison.Ordinal);
            bool trainingRunning = IsTrainingRunning();
            string reason = EffectiveActionDisabledReason(barracks ? TrainingDisabledReason(selectedLocalTroopType) : UpgradeDisabledReason(hotspot));
            string actionLabel = barracks ? (trainingRunning ? "Entrainement en cours" : "Entrainer " + TroopShortLabel(selectedLocalTroopType)) : (upgradeCompleted ? "Upgrade termine" : upgradeRunning ? "Amelioration en cours" : "Ameliorer");
            string actionSummary = barracks ? "Resultat: +" + TrainingBatchSize(selectedLocalTroopType) + " " + selectedLocalTroopType : (upgradeCompleted ? "Termine: niv. " + level + " atteint" : "Niveau " + level + " -> " + (level + 1));
            string costSummary = barracks ? TrainingCostText(selectedLocalTroopType) + " / " + Mathf.RoundToInt(localPreviewTrainingDuration) + "s" : UpgradeCostText(hotspot) + " / " + Mathf.RoundToInt(localPreviewUpgradeDuration) + "s";
            float progress = barracks ? TrainingProgress01() : UpgradeProgress01();

            GUI.Label(new Rect(panel.x + 24f, panel.y + 218f, panel.width - 48f, 22f), "Action principale", titleStyle);
            GUI.Label(new Rect(panel.x + 24f, panel.y + 242f, panel.width - 48f, 18f), upgradeCompleted ? actionSummary : actionSummary + " - " + LocalizedHotspotRole(hotspot), smallStyle);

            Rect actionRect = new Rect(panel.x + 24f, panel.y + 266f, panel.width - 48f, 34f);
            if (DrawPreviewActionButton(actionRect, actionLabel, string.IsNullOrWhiteSpace(reason)))
            {
                if (barracks) StartPreviewTraining(selectedLocalTroopType);
                else StartPreviewUpgrade(hotspot);
            }

            DrawDisabledReason(new Rect(panel.x + 24f, panel.y + 306f, panel.width - 48f, 22f), reason);

            Rect cost = new Rect(panel.x + 24f, panel.y + 338f, panel.width - 48f, 46f);
            DrawPremiumPanel(cost, new Color(0.055f, 0.048f, 0.035f, 0.92f), new Color(0.70f, 0.48f, 0.16f, 0.80f));
            GUI.Label(new Rect(cost.x + 12f, cost.y + 7f, cost.width - 24f, 16f), "Cout reserve / duree", smallStyle);
            GUI.Label(new Rect(cost.x + 12f, cost.y + 25f, cost.width - 24f, 16f), ActionCostReservationText(costSummary), tinyLabelStyle);

            Rect status = new Rect(panel.x + 24f, panel.y + 388f, panel.width - 48f, 44f);
            DrawPremiumPanel(status, new Color(0.055f, 0.048f, 0.035f, 0.92f), new Color(0.70f, 0.48f, 0.16f, 0.80f));
            string statusText = barracks
                ? (trainingRunning ? TrainingQueueSummary() : "File libre - simulation non officielle")
                : (upgradeCompleted
                    ? BeeLocalization.Text("hive_progress.building.saved", "Enregistré sur l'appareil · serveur non synchronisé")
                    : (upgradeRunning ? "En amelioration locale - double action bloquee" : "Pret pour amelioration locale"));
            GUI.Label(new Rect(status.x + 12f, status.y + 5f, status.width - 24f, 15f), PlayerFacingActionHeader(statusText), smallStyle);
            GUI.Label(new Rect(status.x + 12f, status.y + 20f, status.width - 24f, 12f), PlayerFacingActionSubline(), tinyLabelStyle);
            DrawProgressBar(new Rect(status.x + 12f, status.y + 34f, status.width - 24f, 7f), progress);
            GUI.Label(new Rect(panel.x + 24f, panel.y + 432f, panel.width - 48f, 14f), PlayerFacingActionFooter(barracks ? localPreviewTrainingNextAction : localPreviewUpgradeRewardText), tinyLabelStyle);

            if (barracks)
            {
                DrawTrainingPreview(panel, 450f);
            }
            else
            {
                DrawLocalArmySection(new Rect(panel.x + 24f, panel.y + 450f, panel.width - 48f, 42f));
            }
        }

        // Selecteur compact de type de troupe pour la Caserne, affiche a la place du bloc
        // "Capacite" generique (non pertinent pour ce batiment) dans le petit popup de detail
        // atteint en cliquant directement sur le hotspot - Jeff veut voir et choisir le type
        // entraine avant de lancer l'entrainement, pas un bouton "Entrainer" generique.
        private static void DrawBarracksTroopSelector(Rect rect)
        {
            string[] troops = { "Soldats", "Gardiennes", "Eclaireuses" };
            float gap = 6f;
            float troopWidth = (rect.width - gap * 2f) / 3f;
            float tierStripHeight = 18f;
            for (int i = 0; i < troops.Length; i++)
            {
                Rect troop = new Rect(rect.x + i * (troopWidth + gap), rect.y, troopWidth, rect.height);
                string populationId = PopulationIdForTroopType(troops[i]);
                bool selected = troops[i] == selectedLocalTroopType;
                DrawPremiumPanel(troop, selected ? new Color(0.060f, 0.050f, 0.034f, 0.98f) : new Color(0.045f, 0.050f, 0.040f, 0.88f), selected ? new Color(1f, 0.78f, 0.18f, 0.78f) : new Color(0.66f, 0.46f, 0.16f, 0.74f));

                // Bande du haut reservee au badge de palier + bouton de promotion (rects distincts
                // de la zone de selection ci-dessous pour eviter tout chevauchement de clic).
                int tier = TroopTier(populationId);
                GUI.Label(
                    new Rect(troop.x + 4f, troop.y + 1f, troop.width - 24f, tierStripHeight - 2f),
                    "T" + tier.ToString(CultureInfo.InvariantCulture),
                    new GUIStyle(tinyLabelStyle) { fontSize = 10 });

                bool maxed = tier >= LocalPreviewHiveProgressCodec.MaxTroopTier;
                if (!maxed)
                {
                    Vector2 promotionCost = TroopTierPromotionCost(tier);
                    bool canAfford = localPreviewHoney >= promotionCost.x && localPreviewPollen >= promotionCost.y;
                    Rect promoteRect = new Rect(troop.xMax - 20f, troop.y + 1f, 18f, tierStripHeight - 2f);
                    Color previousColor = GUI.color;
                    GUI.color = canAfford ? Color.white : new Color(1f, 1f, 1f, 0.4f);
                    if (GUI.Button(promoteRect, "+", centeredTinyLabelStyle) && canAfford)
                    {
                        PromoteTroopTier(populationId);
                    }
                    GUI.color = previousColor;
                }

                Rect selectRect = new Rect(troop.x, troop.y + tierStripHeight, troop.width, troop.height - tierStripHeight);
                if (GUI.Button(selectRect, string.Empty, GUIStyle.none))
                {
                    if (IsTrainingRunning())
                    {
                        localPreviewDisabledReason = "File occupee";
                        localPreviewLoopMessage = "Selection bloquee: entrainement en cours";
                        SetPlayerFacingActionState("disabled", "File deja occupee", "Attends la fin de la formation avant de changer de troupe.");
                    }
                    else
                    {
                        selectedLocalTroopType = troops[i];
                        localPreviewDisabledReason = string.Empty;
                        localPreviewLoopMessage = "Troupe choisie: " + troops[i];
                        SetPlayerFacingActionState("confirmation", "Troupe selectionnee", troops[i] + " pret a entrainer en preview.");
                    }
                }

                DrawGameIcon(new Rect(troop.x + 8f, selectRect.y + 6f, 26f, 26f), i == 1 ? "guard-bee" : i == 2 ? "bee" : "worker-bee", Color.white);
                GUI.Label(new Rect(troop.x + 6f, troop.yMax - 34f, troop.width - 12f, 15f), TroopShortLabel(troops[i]), tinyLabelStyle);
                GUI.Label(new Rect(troop.x + 6f, troop.yMax - 18f, troop.width - 12f, 16f), TroopCount(troops[i]).ToString(CultureInfo.InvariantCulture), badgeStyle);
            }
        }

