                }

                DrawGameIcon(new Rect(troop.x + 6f, troop.y + 7f, 24f, 24f), i == 1 ? "guard-bee" : i == 2 ? "bee" : "worker-bee", Color.white);
                GUI.Label(new Rect(troop.x + 32f, troop.y + 4f, troop.width - 34f, 15f), TroopShortLabel(troops[i]), tinyLabelStyle);
                GUI.Label(new Rect(troop.x + 32f, troop.y + 21f, troop.width - 34f, 15f), TroopCount(troops[i]).ToString(CultureInfo.InvariantCulture), badgeStyle);
