        // "playUiClickSound" par defaut a false (Sprint Audio Polish, 2026-08-05) : cette fonction
        // sert aussi bien des actions purement UI (Voir, Retour, Fermer...) que des actions de
        // gameplay liees a un batiment/ressource/troupe (Collecter, Ameliorer, Entrainer...), qui ne
        // doivent jamais declencher le son de clic d'interface (elles recevront leurs propres effets
        // sonores plus tard). Seuls les appels purement UI passent explicitement "true".
        private static bool DrawPreviewActionButton(Rect rect, string label, bool enabled, bool playUiClickSound = false)
        {
            DrawPremiumPanel(rect, enabled ? new Color(0.28f, 0.16f, 0.035f, 0.98f) : new Color(0.080f, 0.075f, 0.065f, 0.92f), enabled ? new Color(1f, 0.72f, 0.16f, 0.94f) : new Color(0.46f, 0.42f, 0.34f, 0.72f));
            bool clicked = enabled && GUI.Button(rect, string.Empty, GUIStyle.none);
            if (clicked && playUiClickSound) AudioManager.Instance?.PlayUIClick();
            GUI.Label(rect, label, new GUIStyle(smallStyle) { alignment = TextAnchor.MiddleCenter });
            if (!enabled && GUI.Button(rect, string.Empty, GUIStyle.none))
            {
                localPreviewLoopMessage = string.IsNullOrWhiteSpace(localPreviewDisabledReason) ? "Action indisponible" : localPreviewDisabledReason;
                localPreviewLastActionStatus = "Bloque: " + localPreviewLoopMessage;
                SetPlayerFacingActionState("disabled", "Action indisponible", ShortDisabledReason(localPreviewLoopMessage) + " - " + localPreviewRecoveryGuidance);
                BeginReferenceFeedbackPulse("locked");
            }

            return clicked;
        }

        private static string ActionCostReservationText(string baseCostSummary)
        {
            if (!string.Equals(localPreviewLastReservedCostText, "Aucun cout reserve", StringComparison.Ordinal))
            {
                return localPreviewLastReservedCostText;
            }

            return baseCostSummary;
        }

        private static string ShortDisabledReason(string reason)
        {
            if (reason.IndexOf("Batiment deja", StringComparison.OrdinalIgnoreCase) >= 0) return "Deja en cours";
            if (reason.IndexOf("Autre amelioration", StringComparison.OrdinalIgnoreCase) >= 0) return "Autre upgrade";
            if (reason.IndexOf("File", StringComparison.OrdinalIgnoreCase) >= 0) return "File occupee";
            if (reason.IndexOf("Miel", StringComparison.OrdinalIgnoreCase) >= 0) return "Miel insuffisant";
            if (reason.IndexOf("Cire", StringComparison.OrdinalIgnoreCase) >= 0) return "Cire insuffisante";
            if (reason.IndexOf("Pollen", StringComparison.OrdinalIgnoreCase) >= 0) return "Pollen insuffisant";
            if (reason.IndexOf("Serveur", StringComparison.OrdinalIgnoreCase) >= 0 || reason.IndexOf("Service futur", StringComparison.OrdinalIgnoreCase) >= 0) return "Serveur requis";
            if (reason.IndexOf("Conflit", StringComparison.OrdinalIgnoreCase) >= 0) return "Conflit snapshot";
            if (reason.IndexOf("Capacite", StringComparison.OrdinalIgnoreCase) >= 0) return "Capacite atteinte";
            return reason;
        }

        private static void DrawDisabledReason(Rect rect, string reason)
        {
            if (string.IsNullOrWhiteSpace(reason))
            {
                GUI.Label(rect, "Source: " + localPreviewActionSource, tinyLabelStyle);
                return;
            }

            localPreviewDisabledReason = reason;
            DrawPremiumPanel(rect, new Color(0.10f, 0.045f, 0.030f, 0.92f), new Color(1f, 0.42f, 0.18f, 0.82f));
            GUI.Label(new Rect(rect.x + 6f, rect.y - 1f, rect.width - 12f, rect.height + 2f), ShortDisabledReason(reason) + " - " + localPreviewRecoveryGuidance, new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleLeft });
        }

        private static void DrawProgressBar(Rect rect, float progress01)
        {
            GUI.DrawTexture(rect, GetPremiumTexture("progress-bg"), ScaleMode.StretchToFill, true);
            Rect fill = new Rect(rect.x + 2f, rect.y + 2f, Mathf.Max(0f, rect.width - 4f) * Mathf.Clamp01(progress01), Mathf.Max(1f, rect.height - 4f));
            GUI.DrawTexture(fill, GetPremiumTexture("progress-fill"), ScaleMode.StretchToFill, true);
        }

        private static bool NurseryNeedsCare()
        {
            return localPreviewBroodNutrition < 99.5f;
        }

        private static string BroodFeedingDisabledReason()
        {
            if (!NurseryNeedsCare()) return "Couvain rassasie";
            if (localPreviewHoney < BroodFeedingHoneyCost) return "Miel insuffisant";
            return string.Empty;
        }

        private static float StartPreviewBroodFeeding()
        {
            return ApplyPreviewBroodFeeding(BroodFeedingNutritionGain + localPreviewBroodCareBonus);
        }

        private static float ApplyPreviewBroodFeeding(float nutritionGain)
        {
            string reason = BroodFeedingDisabledReason();
            if (!string.IsNullOrWhiteSpace(reason))
            {
                localPreviewDisabledReason = reason;
                localPreviewLoopMessage = reason;
                localPreviewRecoveryGuidance = reason == "Miel insuffisant" ? "Recolte la reserve de miel." : "La nurserie peut maintenant etre amelioree.";
                SetDevOnlyActionState("rejected", reason == "Miel insuffisant" ? "insufficient_resources" : "brood_full", "brood_feed", "T2_decision_rejected");
                SetPlayerFacingActionState("refusal", "Soin impossible", reason + " - " + localPreviewRecoveryGuidance);
                BeginReferenceFeedbackPulse("locked");
                return 0f;
            }

            float before = localPreviewBroodNutrition;
            localPreviewHoney -= BroodFeedingHoneyCost;
            localPreviewBroodNutrition = Mathf.Min(100f, localPreviewBroodNutrition + Mathf.Max(0f, nutritionGain));
            localPreviewLastBroodNutritionGain = localPreviewBroodNutrition - before;
            localPreviewBroodFeedingFeedbackStartedAt = NowForUi();
            localPreviewBroodFeedCount++;
            localPreviewReservedHoney = BroodFeedingHoneyCost;
            localPreviewReservedWax = 0f;
            localPreviewReservedPollen = 0f;
            localPreviewLastReservedCostText = Mathf.RoundToInt(BroodFeedingHoneyCost).ToString(CultureInfo.InvariantCulture) + " miel consomme";
            localPreviewLastActionStatus = NurseryNeedsCare() ? "Couvain nourri" : "Couvain rassasie";
            localPreviewLoopMessage = "+" + Mathf.RoundToInt(localPreviewLastBroodNutritionGain).ToString(CultureInfo.InvariantCulture) + "% nutrition du couvain";
            localPreviewResourceFeedbackText = "-" + Mathf.RoundToInt(BroodFeedingHoneyCost).ToString(CultureInfo.InvariantCulture) + " miel";
            localPreviewResourceFeedbackStartedAt = NowForUi();
            localPreviewDailyStep = "couvain";
            localPreviewDailyFeedback = NurseryNeedsCare() ? "Le couvain reprend des forces" : "Couvain rassasie; amelioration disponible";
            localPreviewSessionPrompt = NurseryNeedsCare() ? "Poursuis les soins de la nurserie." : "La nurserie est prete a etre amelioree.";
            localPreviewDisabledReason = string.Empty;
            localPreviewRecoveryGuidance = NurseryNeedsCare() ? "Nourris encore ou poursuis la visite." : "Ameliore la nurserie quand tu es pret.";
            SetDevOnlyActionState("accepted", "none", "brood_feed", "T4_brood_care_result");
