            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.BroodIncubationDoctrineChoice) return;

            float honeyCost = firstShift
                ? GuidedBroodIncubationFirstShiftHoneyCost
                : GuidedBroodIncubationResilienceHoneyCost;
            float pollenCost = firstShift ? GuidedBroodIncubationFirstShiftPollenCost : 0f;
            float waxCost = firstShift ? 0f : GuidedBroodIncubationResilienceWaxCost;
            if (localPreviewHoney < honeyCost || localPreviewPollen < pollenCost || localPreviewWax < waxCost)
            {
                localPreviewDisabledReason = localPreviewWax < waxCost
                    ? "Cire insuffisante"
                    : localPreviewPollen < pollenCost ? "Pollen insuffisant" : "Miel insuffisant";
                localPreviewRecoveryGuidance = "Choisis l'autre protocole ou recolte davantage de ressources.";
                BeginReferenceFeedbackPulse("locked");
                return;
            }

            guidedBroodIncubationDoctrinePlan = firstShift ? "first_shift" : "resilience";
            guidedBroodIncubationDoctrineDuration = firstShift
                ? GuidedBroodIncubationFirstShiftDoctrineDuration
                : GuidedBroodIncubationResilienceDoctrineDuration;
            guidedBroodIncubationDoctrineAssignedBees = firstShift ? 3 : 2;
            guidedBroodIncubationDoctrineStartedAt = NowForUi();
            guidedBroodIncubationDoctrineCommitCount++;
            guidedBroodIncubationDoctrineHoneyCost = honeyCost;
            guidedBroodIncubationDoctrinePollenCost = pollenCost;
            guidedBroodIncubationDoctrineWaxCost = waxCost;
            localPreviewHoney -= honeyCost;
            localPreviewPollen -= pollenCost;
            localPreviewWax -= waxCost;
            localPreviewReservedHoney = honeyCost;
            localPreviewReservedPollen = pollenCost;
            localPreviewReservedWax = waxCost;
            localPreviewLastReservedCostText = firstShift
                ? "140 miel et 60 pollen engages"
                : "80 miel et 40 cire engages";
            localPreviewDisabledReason = string.Empty;
            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.BroodIncubationDoctrineRunning);
            localPreviewSessionPrompt = firstShift ? "Preparation du premier quart" : "Protocole de resilience en cours";
        }

        private static void StartGuidedWorkerCare(bool measured)
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.WorkerFeedReady) return;
            if (!NurseryNeedsCare())
            {
                SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerEmergenceReady);
                return;
            }

            float honeyCost = GuidedWorkerCareHoneyCost(measured);
            if (localPreviewHoney < honeyCost)
            {
                localPreviewDisabledReason = "Miel insuffisant";
                localPreviewRecoveryGuidance = "Recolte la reserve de miel.";
                BeginReferenceFeedbackPulse("locked");
                return;
            }

            guidedWorkerCareMode = measured ? "measured" : "urgent";
            guidedWorkerAssignedNurses = measured ? 3 : 5;
            guidedWorkerCareDuration = measured ? GuidedWorkerMeasuredCareDuration : GuidedWorkerUrgentCareDuration;
            guidedWorkerPendingHoneyCost = honeyCost;
            guidedWorkerPendingNutritionGain = Mathf.Max(0f, 100f - localPreviewBroodNutrition);
            guidedWorkerCareStartedAt = NowForUi();
            guidedWorkerCareCommitCount++;
            localPreviewReservedHoney = honeyCost;
            localPreviewReservedWax = 0f;
            localPreviewReservedPollen = 0f;
            localPreviewLastReservedCostText = Mathf.RoundToInt(honeyCost).ToString(CultureInfo.InvariantCulture) + " miel prepare";
            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerFeedProgress);
            localPreviewSessionPrompt = measured ? "Ration mesuree en preparation" : "Ration urgente en preparation";
        }

        private static float GuidedWorkerCareHoneyCost(bool measured)
