        private static void RegisterGuidedWorkerCertificationCheck(int index)
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.WorkerCertificationCheck) return;
            int clamped = Mathf.Clamp(index, 0, 2);
            int bit = 1 << clamped;
            if ((guidedWorkerCertificationChecksMask & bit) != 0) return;

            guidedWorkerCertificationChecksMask |= bit;
            guidedWorkerCertificationCheckCount++;
            guidedWorkerCertificationTotalCheckCount++;
            guidedWorkerCertificationLastCheck = clamped == 0 ? "precision" : clamped == 1 ? "cadence" : "securite";
            BeginReferenceFeedbackPulse("preview");
            if (guidedWorkerCertificationCheckCount < 3)
            {
                localPreviewSessionPrompt = "Controle qualite " + guidedWorkerCertificationCheckCount.ToString(CultureInfo.InvariantCulture) + "/3";
                return;
            }

            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerCertificationMentorshipChoice);
            localPreviewSessionPrompt = "Controles valides: choisis l'encadrement";
