        private static void CompleteGuidedWorkerWorkshopHandoffIfReady()
        {
            if (guidedCollectionTutorialStep != GuidedCollectionTutorialStep.WorkerWorkshopHandoffRunning
                || GuidedWorkerWorkshopHandoffProgress01() < 1f) return;
            guidedWorkerWorkshopHandoffAssignedBees = 0;
            float produced = guidedWorkerWorkshopHandoffPlan == "wax_convoy" ? GuidedWorkerWorkshopWaxProduced : GuidedWorkerWorkshopHoneyProduced;
            if (guidedWorkerWorkshopHandoffPlan == "wax_convoy")
            {
                float before = localPreviewPendingWax;
                localPreviewPendingWax = Mathf.Min(PendingManualProductionCapacity("wax_workshop"), before + produced);
                guidedWorkerWorkshopHandoffPendingResource = localPreviewPendingWax - before;
            }
            else
            {
                float before = localPreviewPendingHoney;
                localPreviewPendingHoney = Mathf.Min(PendingManualProductionCapacity("honey_storage"), before + produced);
                guidedWorkerWorkshopHandoffPendingResource = localPreviewPendingHoney - before;
            }
            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.WorkerWorkshopHandoffCollect);
            localPreviewSessionPrompt = "Lot de liaison pret: recolte manuellement";
            BeginReferenceFeedbackPulse("preview");
        }

