            guidedUpgradeBatchQualificationSuccessCount = 1;
            guidedUpgradeBatchQualificationRecommendation = production ? "reserve" : "nursery";
            SetGuidedCollectionTutorialStep(GuidedCollectionTutorialStep.UpgradeApplicationReady);
