            guidedUpgradeOperationsChecksMask |= bit;
            guidedUpgradeOperationsCheckCount++;
            guidedUpgradeOperationsTotalCheckCount++;
            guidedUpgradeOperationsLastCheck = clamped == 0 ? "adhesion" : clamped == 1 ? "ventilation" : "charge";
