        private static string ResearchDisabledReason(LocalPreviewResearchDefinition definition)
        {
            if (definition == null) return BeeLocalization.Text("research.reason.unknown", "Étude inconnue");
            EnsureLocalPreviewQueueJournalLoaded();
            if (LocalPreviewResearchCatalog.Contains(localPreviewQueueJournal.completedResearchIds, definition.ResearchId))
                return BeeLocalization.Text("research.reason.completed", "Étude déjà terminée");
            if (IsResearchRunning())
                return string.Equals(localPreviewResearchId, definition.ResearchId, StringComparison.Ordinal)
                    ? BeeLocalization.Text("research.reason.already_running", "Étude déjà en cours")
                    : BeeLocalization.Text("research.reason.queue_busy", "Une autre étude est en cours");
            if (localPreviewHoney < definition.HoneyCost)
                return string.Format(
                    CultureInfo.CurrentCulture,
                    BeeLocalization.Text("research.reason.honey_missing", "Miel manquant : {0}"),
                    Mathf.CeilToInt(definition.HoneyCost - localPreviewHoney));
            if (localPreviewPollen < definition.PollenCost)
                return string.Format(
                    CultureInfo.CurrentCulture,
                    BeeLocalization.Text("research.reason.pollen_missing", "Pollen manquant : {0}"),
                    Mathf.CeilToInt(definition.PollenCost - localPreviewPollen));
            return string.Empty;
        }

        private static string ResearchShortageResource(LocalPreviewResearchDefinition definition)
        {
            if (definition == null || IsResearchRunning()
                || LocalPreviewResearchCatalog.Contains(localPreviewQueueJournal.completedResearchIds, definition.ResearchId)) return string.Empty;
            if (localPreviewHoney < definition.HoneyCost) return "honey";
            if (localPreviewPollen < definition.PollenCost) return "pollen";
            return string.Empty;
        }

        private static void NavigateToResearchResourceSource(string resource)
        {
            string hotspotId = string.Equals(resource, "pollen", StringComparison.Ordinal) ? "warehouse_cells" : "honey_storage";
            ReferenceHiveHotspot hotspot = FindReferenceHotspot(hotspotId);
            if (string.IsNullOrWhiteSpace(hotspot.HotspotId)) return;
            activeMainMenuId = string.Empty;
            activeHiveMenu = HiveMenuMode.Hive;
            detailPanelClosed = false;
            SelectReferenceHotspot(hotspot);
            localPreviewResearchLastSourceRoute = hotspotId;
            localPreviewLastActionStatus = BeeLocalization.Text("research.source.opened", "Source ouverte");
            localPreviewLoopMessage = string.Format(
                CultureInfo.CurrentCulture,
                BeeLocalization.Text("research.source.feedback", "{0} ouverte · collecte toujours manuelle"),
                LocalizedHotspotLabel(hotspot));
            BeginReferenceFeedbackPulse("preview");
        }

        private static string ResearchCostText(LocalPreviewResearchDefinition definition)
        {
            if (definition == null) return string.Empty;
            return string.Format(
                CultureInfo.CurrentCulture,
                BeeLocalization.Text("research.cost", "{0} miel · {1} pollen · {2}s"),
                Mathf.RoundToInt(definition.HoneyCost),
                Mathf.RoundToInt(definition.PollenCost),
                Mathf.RoundToInt(definition.DurationSeconds));
        }

        private static bool StartPreviewResearch(string researchId)
        {
            EnsureLocalPreviewQueueJournalLoaded();
            LocalPreviewResearchDefinition definition = LocalPreviewResearchCatalog.Find(researchId);
            string reason = ResearchDisabledReason(definition);
            if (!string.IsNullOrWhiteSpace(reason))
            {
                localPreviewRepeatedResearchBlockedCount++;
                localPreviewDisabledReason = reason;
                localPreviewLoopMessage = reason;
                SetDevOnlyActionState("rejected", IsResearchRunning() ? "queue_busy" : "research_unavailable", "research", "T2_decision_rejected");
                SetPlayerFacingActionState("refusal", BeeLocalization.Text("research.message.refused", "Recherche refusée"), reason);
                BeginReferenceFeedbackPulse("locked");
                return false;
            }

            localPreviewHoney -= definition.HoneyCost;
            localPreviewPollen -= definition.PollenCost;
            localPreviewResearchId = definition.ResearchId;
            localPreviewResearchDuration = definition.DurationSeconds;
            localPreviewResearchStartedAt = NowForUi();
            localPreviewResearchApplied = false;
            localPreviewResearchCommitCount++;
            localPreviewQueueJournal.research = NewResearchQueueOperation(definition);
            SaveLocalPreviewQueueJournal();
            RecordDailyRoundTask(DailyRoundOperationTask);
            localPreviewReservedHoney = definition.HoneyCost;
            localPreviewReservedWax = 0f;
            localPreviewReservedPollen = definition.PollenCost;
            localPreviewLastReservedCostText = QueueOperationCostText(localPreviewQueueJournal.research);
            localPreviewDisabledReason = BeeLocalization.Text("research.reason.already_running", "Étude déjà en cours");
            localPreviewLoopMessage = string.Format(
                CultureInfo.CurrentCulture,
                BeeLocalization.Text("research.message.started", "Étude lancée : {0}"),
                ResearchTitle(definition.ResearchId));
            localPreviewLastActionStatus = BeeLocalization.Text("research.status.running", "En cours");
            SetDevOnlyActionState("pending", "none", "research", "T3_queue_running");
            SetPlayerFacingActionState("confirmation", BeeLocalization.Text("research.message.started_title", "Recherche lancée"), localPreviewLastReservedCostText + " · " + BeeLocalization.Text("research.local_disclosure", "aperçu local non officiel"));
            BeginReferenceFeedbackPulse("preview");
            return true;
        }

        private static bool CanStartUpgrade(ReferenceHiveHotspot hotspot)
        {
            return string.IsNullOrWhiteSpace(UpgradeDisabledReason(hotspot));
        }

        private static string UpgradeDisabledReason(ReferenceHiveHotspot hotspot)
        {
            if (IsUpgradeRunning()) return localPreviewUpgradeHotspotId == hotspot.HotspotId ? "Batiment deja en amelioration" : "Autre amelioration en cours";
            if (!string.Equals(hotspot.HotspotId, "administration_core", StringComparison.Ordinal)
                && EnsureLocalPreviewLevel(hotspot.HotspotId) >= CoeurRoyalLevel())
                return "Niveau du Coeur royal insuffisant";
            Vector2 cost = UpgradeCost(hotspot);
            if (localPreviewHoney < cost.x) return "Miel insuffisant";
            if (localPreviewWax < cost.y) return "Cire insuffisante";
            return string.Empty;
        }

        private static Vector2 UpgradeCost(ReferenceHiveHotspot hotspot)
        {
            int level = EnsureLocalPreviewLevel(hotspot.HotspotId);
            float honey = 900f + level * 72f;
            float wax = 220f + level * 31f;
            if (string.Equals(hotspot.HotspotId, "wax_workshop", StringComparison.Ordinal))
            {
                honey = Mathf.Max(0f, honey - guidedWorkerWorkshopHoneyDiscount);
                wax = Mathf.Max(0f, wax - guidedWorkerWorkshopWaxDiscount);
            }
            else if (string.Equals(hotspot.HotspotId, "administration_core", StringComparison.Ordinal))
            {
                // Le Coeur royal est le hub qui plafonne tous les autres batiments ; cout volontairement
                // plus eleve que la formule generique pour refleter son role central.
                honey *= 2f;
                wax *= 2f;
            }
            return new Vector2(honey, wax);
        }

        private static string UpgradeCostText(ReferenceHiveHotspot hotspot)
        {
            Vector2 cost = UpgradeCost(hotspot);
            return Mathf.RoundToInt(cost.x).ToString(CultureInfo.InvariantCulture) + " miel, " + Mathf.RoundToInt(cost.y).ToString(CultureInfo.InvariantCulture) + " cire";
        }

        private static void StartPreviewUpgrade(ReferenceHiveHotspot hotspot)
        {
            EnsureLocalPreviewQueueJournalLoaded();
            if (!CanStartUpgrade(hotspot))
            {
                if (IsUpgradeRunning()) localPreviewRepeatedUpgradeBlockedCount++;
                localPreviewDisabledReason = UpgradeDisabledReason(hotspot);
                localPreviewLoopMessage = localPreviewDisabledReason;
                SetDevOnlyActionState("rejected", IsUpgradeRunning() ? "already_running" : "insufficient_resources", "upgrade", "T2_decision_rejected");
                SetPlayerFacingActionState("refusal", "Amelioration refusee", ShortDisabledReason(localPreviewDisabledReason) + " - " + localPreviewRecoveryGuidance);
                BeginReferenceFeedbackPulse("locked");
                return;
            }

            Vector2 cost = UpgradeCost(hotspot);
            ReserveUpgradeCost(hotspot);
            localPreviewHoney -= cost.x;
            localPreviewWax -= cost.y;
            localPreviewUpgradeHotspotId = hotspot.HotspotId;
            localPreviewUpgradeStartedAt = NowForUi();
            localPreviewUpgradeApplied = false;
            localPreviewUpgradeCommitCount++;
            localPreviewQueueJournal.upgrade = NewQueueOperation(hotspot.HotspotId, localPreviewUpgradeDuration, cost, true);
            SaveLocalPreviewQueueJournal();
            RecordDailyRoundTask(DailyRoundOperationTask);
            localPreviewDisabledReason = "Batiment deja en amelioration";
            localPreviewLoopMessage = "Amelioration lancee en preview: " + LocalizedHotspotLabel(hotspot);
            localPreviewLastActionStatus = "En cours";
            SetDevOnlyActionState("pending", "none", "upgrade", "T3_timer_running");
            SetPlayerFacingActionState("confirmation", "Amelioration confirmee", localPreviewLastReservedCostText + " - timer local actif.");
            BeginReferenceFeedbackPulse("preview");
        }

        private static bool StartPreviewDefense(int requestedGuardians, float duration, float waxCost)
        {
            if (IsDefenseRunning() || localPreviewDefenseResolved)
            {
                localPreviewRepeatedDefenseBlockedCount++;
                return false;
            }

            if (localPreviewGuardians < requestedGuardians)
            {
                localPreviewDisabledReason = "Gardiennes insuffisantes";
                SetPlayerFacingActionState("refusal", "Mobilisation impossible", "Il faut " + requestedGuardians.ToString(CultureInfo.InvariantCulture) + " gardiennes disponibles.");
                return false;
            }

            if (localPreviewWax < waxCost)
            {
                localPreviewDisabledReason = "Cire insuffisante";
                SetPlayerFacingActionState("refusal", "Barrage impossible", "Il faut " + Mathf.RoundToInt(waxCost).ToString(CultureInfo.InvariantCulture) + " cire disponible.");
                return false;
            }

            localPreviewDefenseStartedAt = NowForUi();
            localPreviewDefenseDuration = duration;
            localPreviewDefenseResolved = false;
            localPreviewDefenseGuardiansMobilized = requestedGuardians;
            localPreviewDefenseCommitCount++;
            localPreviewWax -= waxCost;
            localPreviewDisabledReason = "Intervention deja en cours";
            localPreviewLoopMessage = requestedGuardians.ToString(CultureInfo.InvariantCulture) + " gardiennes repoussent la fausse-teigne";
            localPreviewLastActionStatus = "Defense locale en cours";
            localPreviewLastReservedCostText = waxCost > 0f
                ? Mathf.RoundToInt(waxCost).ToString(CultureInfo.InvariantCulture) + " cire engagee"
                : "Aucune ressource consommee";
            SetDevOnlyActionState("pending", "none", "local_defense", "T3_timer_running");
            SetPlayerFacingActionState("confirmation", "Gardiennes mobilisees", requestedGuardians.ToString(CultureInfo.InvariantCulture) + " gardiennes interviennent pendant " + Mathf.RoundToInt(duration).ToString(CultureInfo.InvariantCulture) + " secondes.");
            BeginReferenceFeedbackPulse("preview");
            return true;
        }

        private static bool CanStartTraining(string troopType)
        {
            return string.IsNullOrWhiteSpace(TrainingDisabledReason(troopType));
        }

        private static string TrainingDisabledReason(string troopType)
        {
            if (IsTrainingRunning()) return "File entrainement occupee";
            if (IsWorkerTrainingType(troopType) && NurseryNeedsCare()) return "Nutrition insuffisante";
            Vector2 cost = TrainingCost(troopType);
            if (localPreviewHoney < cost.x) return "Miel insuffisant";
            if (localPreviewPollen < cost.y) return "Pollen insuffisant";
            return string.Empty;
        }

        private static string EffectiveActionDisabledReason(string localReason)
        {
            if (string.Equals(localPreviewActionDecision, "server_required", StringComparison.OrdinalIgnoreCase))
            {
                return string.IsNullOrWhiteSpace(localPreviewDisabledReason) ? "Serveur requis - service futur" : localPreviewDisabledReason;
            }

            if (string.Equals(localPreviewActionDecision, "rejected", StringComparison.OrdinalIgnoreCase) && string.IsNullOrWhiteSpace(localReason))
            {
                return RejectionMicrocopy(localPreviewActionRejectionCode);
            }

            return localReason;
        }

        private static Vector2 TrainingCost(string troopType)
        {
            if (IsWorkerTrainingType(troopType)) return new Vector2(420f, 180f);
            if (HiveDoctrineRecruitmentCatalog.TryResolveTroopType(troopType, out HiveDoctrineRecruitmentDefinition recruitment))
                return new Vector2(recruitment.HoneyCost, recruitment.PollenCost);
            if (troopType == "Gardiennes") return new Vector2(680f, 180f);
            if (troopType == "Eclaireuses") return new Vector2(420f, 260f);
            return new Vector2(500f, 120f);
        }

        private static string TrainingCostText(string troopType)
        {
            Vector2 cost = TrainingCost(troopType);
            return Mathf.RoundToInt(cost.x).ToString(CultureInfo.InvariantCulture) + " miel, " + Mathf.RoundToInt(cost.y).ToString(CultureInfo.InvariantCulture) + " pollen";
        }

        private static string TrainingQueueSummary()
        {
            if (IsTrainingRunning())
            {
                return "File: " + localPreviewTrainingTroopType + " - " + Mathf.RoundToInt(TrainingProgress01() * 100f).ToString(CultureInfo.InvariantCulture) + "%";
            }

            return "File libre - ouv. " + localPreviewWorkers.ToString(CultureInfo.InvariantCulture)
                + " / troupes: S " + localPreviewSoldiers.ToString(CultureInfo.InvariantCulture)
                + " / G " + localPreviewGuardians.ToString(CultureInfo.InvariantCulture)
                + " / E " + localPreviewScouts.ToString(CultureInfo.InvariantCulture);
        }

        private static void StartPreviewTraining(string troopType)
        {
            EnsureLocalPreviewQueueJournalLoaded();
            if (!CanStartTraining(troopType))
            {
                if (IsTrainingRunning()) localPreviewRepeatedTrainingBlockedCount++;
                localPreviewDisabledReason = TrainingDisabledReason(troopType);
                localPreviewLoopMessage = localPreviewDisabledReason;
                SetDevOnlyActionState("rejected", IsTrainingRunning() ? "queue_busy" : "insufficient_resources", "training", "T2_decision_rejected");
                SetPlayerFacingActionState("refusal", "Formation refusee", ShortDisabledReason(localPreviewDisabledReason) + " - " + localPreviewRecoveryGuidance);
                BeginReferenceFeedbackPulse("locked");
                return;
            }

            Vector2 cost = TrainingCost(troopType);
            if (HiveDoctrineRecruitmentCatalog.TryResolveTroopType(troopType, out HiveDoctrineRecruitmentDefinition recruitment))
                localPreviewTrainingDuration = recruitment.DurationSeconds;
            ReserveTrainingCost(troopType);
            localPreviewHoney -= cost.x;
            localPreviewPollen -= cost.y;
            localPreviewTrainingTroopType = troopType;
            localPreviewTrainingStartedAt = NowForUi();
            localPreviewTrainingApplied = false;
            localPreviewTrainingCommitCount++;
            localPreviewQueueJournal.training = NewQueueOperation(troopType, localPreviewTrainingDuration, cost, false);
            SaveLocalPreviewQueueJournal();
            RecordDailyRoundTask(DailyRoundOperationTask);
            localPreviewDisabledReason = "File entrainement occupee";
            localPreviewLoopMessage = "Entrainement lance en preview: " + troopType;
            localPreviewLastActionStatus = "En cours";
            SetDevOnlyActionState("pending", "none", "training", "T3_queue_running");
            SetPlayerFacingActionState("confirmation", "Formation confirmee", localPreviewLastReservedCostText + " - file locale active.");
            BeginReferenceFeedbackPulse("preview");
        }

        private static bool IsWorkerTrainingType(string troopType)
        {
            return string.Equals(troopType, WorkerTrainingType, StringComparison.Ordinal);
        }

        private static bool IsWorkerTrainingRunning()
        {
            return IsTrainingRunning() && IsWorkerTrainingType(localPreviewTrainingTroopType);
        }

        private static void StartPreviewWorkerTraining()
        {
            StartPreviewTraining(WorkerTrainingType);
            if (!IsWorkerTrainingRunning()) return;

            localPreviewLoopMessage = "Formation d'une ouvriere lancee";
            localPreviewLastActionStatus = "Ouvriere en formation";
            localPreviewSessionPrompt = "Attends l'eclosion de la nouvelle ouvriere.";
            localPreviewRecoveryGuidance = "La file affichera son arrivee.";
            SetDevOnlyActionState("pending", "none", "worker_training", "T3_queue_running");
            SetPlayerFacingActionState("confirmation", "Formation lancee", localPreviewLastReservedCostText + " - ouvriere en incubation.");
        }

        private static Rect AnimatedDetailPanelRect(Rect target, bool compact)
        {
            if (productionReducedMotionForProof) return target;

            float elapsed = NowForUi() - referencePanelAnimationStartedAt;
            if (elapsed < 0f || elapsed > DetailPanelAnimationSeconds) return target;

            float t = Mathf.Clamp01(elapsed / DetailPanelAnimationSeconds);
            float eased = 1f - Mathf.Pow(1f - t, 3f);
            float offset = compact ? Mathf.Lerp(26f, 0f, eased) : Mathf.Lerp(42f, 0f, eased);
            if (compact) return new Rect(target.x, target.y + offset, target.width, target.height);
            return new Rect(target.x + offset, target.y, target.width, target.height);
        }

        private static string CompactDisclosure(ReferenceHiveHotspot hotspot)
        {
            if (hotspot.StateIcon == "server") return "Serveur futur requis. Non synchronise.";
            if (hotspot.StateIcon == "locked") return "Zone verrouillee. Service en preparation.";
            if (hotspot.StateIcon == "future") return "Fonction future. Service en preparation.";
            return "Demo non officielle.";
        }

        private static void DrawResourceChip(Rect rect, string icon, string label, string value, int index)
        {
            float chipScale = UIAnimationLibrary.ApplyChipScale("chip_" + icon, 1f);
            Color accent = ResourceAccentColor(icon);
            DrawPremiumPanel(rect, new Color(0.026f, 0.024f, 0.020f, 0.88f), new Color(accent.r, accent.g, accent.b, 0.70f));
            if (rect.width < 82f)
            {
                float iconSize = Mathf.Min(26f, rect.height - 13f) * chipScale;
                DrawGameIcon(new Rect(rect.x + rect.width * 0.5f - iconSize * 0.5f, rect.y + 4f, iconSize, iconSize), icon, accent);
                GUI.Label(new Rect(rect.x + 4f, rect.y + rect.height - 16f, rect.width - 8f, 14f), value, centeredTinyLabelStyle);
                if (icon == "capacity") GUI.DrawTexture(new Rect(rect.x + 8f, rect.y + rect.height - 7f, rect.width - 16f, 4f), GetPremiumTexture("progress-fill"), ScaleMode.StretchToFill, true);
                return;
            }

            float scale = LandscapeUiScale() * chipScale;
            float resourceIconSize = Mathf.Min(rect.height - 8f, 42f * scale);
            float left = 8f * scale;
            Rect iconWell = new Rect(rect.x + left, rect.y + (rect.height - resourceIconSize) * 0.5f, resourceIconSize, resourceIconSize);
            DrawPremiumPanel(iconWell, new Color(0.016f, 0.016f, 0.014f, 0.68f), new Color(accent.r, accent.g, accent.b, 0.46f));
            DrawGameIcon(new Rect(iconWell.x + 4f, iconWell.y + 4f, iconWell.width - 8f, iconWell.height - 8f), icon, accent);
            float textX = rect.x + left + resourceIconSize + 8f * scale;
            GUI.Label(new Rect(textX, rect.y + 5f, rect.width - (textX - rect.x) - 10f, 20f * scale), label, new GUIStyle(tinyLabelStyle) { fontSize = ScaledFont(10f) });
            GUI.Label(new Rect(textX, rect.y + rect.height - 29f * scale, rect.width - (textX - rect.x) - 10f, 24f * scale), value, new GUIStyle(badgeStyle) { fontSize = ScaledFont(12f) });
            GUI.Label(new Rect(rect.xMax - 60f * scale, rect.y + 5f, 54f * scale, 18f * scale), ResourceTickShortText(index), new GUIStyle(tinyLabelStyle) { alignment = TextAnchor.MiddleRight, fontSize = ScaledFont(9f) });
            DrawResourceGrowthFeedback(rect, index);
            if (icon == "capacity") GUI.DrawTexture(new Rect(textX, rect.y + rect.height - 8f, rect.width - (textX - rect.x) - 10f, 5f), GetPremiumTexture("progress-fill"), ScaleMode.StretchToFill, true);
        }

        private static void DrawResourceGrowthFeedback(Rect rect, int index)
        {
            if (index != localPreviewResourceFeedbackIndex) return;
            float elapsed = NowForUi() - localPreviewResourceFeedbackStartedAt;
            if (elapsed < 0f || elapsed > 0.72f) return;

            float alpha = productionReducedMotionForProof ? 0.75f : Mathf.Sin(Mathf.Clamp01(elapsed / 0.72f) * Mathf.PI) * 0.92f;
            Color previous = GUI.color;
            GUI.color = new Color(1f, 0.82f, 0.20f, alpha);
            Texture2D glow = GetPremiumTexture("progress-fill");
            GUI.DrawTexture(new Rect(rect.x + 3f, rect.y + 3f, rect.width - 6f, 2f), glow, ScaleMode.StretchToFill, true);
            GUI.DrawTexture(new Rect(rect.x + 3f, rect.yMax - 5f, rect.width - 6f, 2f), glow, ScaleMode.StretchToFill, true);
            GUI.DrawTexture(new Rect(rect.x + 3f, rect.y + 3f, 2f, rect.height - 6f), glow, ScaleMode.StretchToFill, true);
            GUI.DrawTexture(new Rect(rect.xMax - 5f, rect.y + 3f, 2f, rect.height - 6f), glow, ScaleMode.StretchToFill, true);
            GUI.color = previous;
        }

        private static string ResourceTickShortText(int index)
        {
            switch (index)
            {
                case 0: return "+42/s";
                case 1: return "+20/s";
                case 2: return "+27/s";
                case 3: return "+3/s";
                case 4: return "+4/s";
                default: return string.Empty;
            }
        }

        private static string ResourceTickText(int index)
        {
            switch (index)
            {
                case 0: return "+42 miel/s";
                case 1: return "+20 cire/s";
                case 2: return "+27 pollen/s";
                case 3: return "+3 abeilles/s";
                case 4: return "+4 cap./s";
                default: return string.Empty;
            }
        }

        private static string CompactResourceLabel(string label)
        {
            switch (label)
            {
                case "Abeilles": return "Abe.";
                case "Pollen": return "Pol.";
                case "Miel": return "Miel";
                case "Cire": return "Cire";
                case "Cap.": return "Cap.";
                default: return label.Length > 4 ? label.Substring(0, 4) + "." : label;
            }
        }

        private static bool DrawIconButton(Rect rect, string iconId, string label, bool active, string itemId = "")
        {
            bool mapButton = itemId == "World";
            Color fill = active ? new Color(0.060f, 0.050f, 0.034f, 0.94f) : mapButton ? new Color(0.040f, 0.035f, 0.024f, 0.86f) : new Color(0.035f, 0.030f, 0.023f, 0.78f);
            Color border = active ? new Color(1f, 0.69f, 0.15f, 0.82f) : mapButton ? new Color(1f, 0.68f, 0.18f, 0.72f) : new Color(0.55f, 0.40f, 0.18f, 0.52f);
            DrawPremiumPanel(rect, fill, border);
            if (itemId == "Chat") DrawChatRailAttention(rect);
            if (mapButton)
            {
                DrawMapButtonEmphasis(rect);
            }
            if (active)
            {
                DrawPremiumHeaderBand(new Rect(rect.x + 6f, rect.y + 5f, rect.width - 12f, Mathf.Max(8f, rect.height * 0.34f)));
                GUI.color = new Color(1f, 0.72f, 0.16f, 0.76f);
                GUI.DrawTexture(new Rect(rect.x + rect.width * 0.22f, rect.yMax - 5f, rect.width * 0.56f, 2f), GetPremiumTexture("progress-fill"), ScaleMode.StretchToFill, true);
                GUI.color = Color.white;
            }
            DrawMenuBadge(rect, itemId);

            bool clicked = GUI.Button(rect, string.Empty, GUIStyle.none);
            if (clicked)
            {
                AudioManager.Instance?.PlayUIClick();
                UIAnimationLibrary.BeginButtonPress("icon_btn_" + itemId);
            }
            else if (Event.current.type == EventType.MouseUp && rect.Contains(Event.current.mousePosition))
            {
                UIAnimationLibrary.BeginButtonRelease("icon_btn_" + itemId);
            }
            if (rect.height <= 44f)
            {
                float compactIcon = Mathf.Min(34f, rect.height - 8f);
                float btnScale = UIAnimationLibrary.GetButtonPressProgress("icon_btn_" + itemId);
                Rect scaledRect = new Rect(
                    rect.x + (rect.width * (1f - btnScale)) * 0.5f,
                    rect.y + (rect.height * (1f - btnScale)) * 0.5f,
                    rect.width * btnScale,
                    rect.height * btnScale);
                DrawMenuIcon(new Rect(scaledRect.x + 8f * btnScale, scaledRect.y + scaledRect.height * 0.5f - compactIcon * 0.5f * btnScale, compactIcon * btnScale, compactIcon * btnScale), iconId, active);
                GUI.Label(new Rect(scaledRect.x + compactIcon * btnScale + 20f * btnScale, scaledRect.y + 4f * btnScale, scaledRect.width - compactIcon * btnScale - 26f * btnScale, scaledRect.height - 8f * btnScale), label, centeredTinyLabelStyle);
                return clicked;
            }

            float iconSize = Mathf.Min(74f, rect.height * 0.76f);
            float btnScale2 = UIAnimationLibrary.GetButtonPressProgress("icon_btn_" + itemId);
            Rect scaledRect2 = new Rect(
                rect.x + (rect.width * (1f - btnScale2)) * 0.5f,
                rect.y + (rect.height * (1f - btnScale2)) * 0.5f,
                rect.width * btnScale2,
                rect.height * btnScale2);
            DrawMenuIcon(new Rect(scaledRect2.x + scaledRect2.width * 0.5f - iconSize * 0.5f * btnScale2, scaledRect2.y + 2f * btnScale2, iconSize * btnScale2, iconSize * btnScale2), iconId, active);
            GUIStyle labelStyle = active ? new GUIStyle(centeredTinyLabelStyle) { fontSize = 11 } : new GUIStyle(centeredTinyLabelStyle) { fontSize = 11 };
            if (!active) labelStyle.normal.textColor = new Color(0.92f, 0.84f, 0.66f, 1f);
            GUI.Label(new Rect(scaledRect2.x + 2f * btnScale2, scaledRect2.y + scaledRect2.height - 22f * btnScale2, scaledRect2.width - 4f * btnScale2, 20f * btnScale2), label, labelStyle);
            return clicked;
        }

