        private static void DrawMenuBadge(Rect itemRect, string itemId)
        {
            string badge = MenuBadgeText(itemId);
            if (string.IsNullOrEmpty(badge)) return;

            float badgeFade = UIAnimationLibrary.GetFadeProgress("menu_badge_" + itemId, 1f);
            bool urgent = badge == "!";
            Rect rect = new Rect(itemRect.xMax - 23f, itemRect.y + 4f, urgent ? 18f : 24f, 17f);
            Color fill = urgent ? new Color(0.72f, 0.030f, 0.020f, 0.96f * badgeFade) : new Color(0.10f, 0.38f, 0.66f, 0.94f * badgeFade);
            Color border = urgent ? new Color(1f, 0.74f, 0.24f, 0.92f * badgeFade) : new Color(0.55f, 0.86f, 1f, 0.72f * badgeFade);
            DrawPremiumPanel(rect, fill, border);
            GUI.color = new Color(1f, 1f, 1f, badgeFade);
            GUI.Label(rect, badge, centeredTinyLabelStyle);
            GUI.color = Color.white;
        }

        private static string MenuBadgeText(string itemId)
        {
            if (string.Equals(itemId, "Chat", StringComparison.Ordinal))
            {
                int unread = ChatUnreadTotal();
                return unread > 0 ? (unread > 9 ? "9+" : unread.ToString(CultureInfo.InvariantCulture)) : string.Empty;
            }

            if (string.Equals(itemId, "Quests", StringComparison.Ordinal))
            {
                if (OfficialDailyRoundConfigured())
                {
                    HiveDailyRoundScreenModel official = OfficialDailyRoundModel();
                    return official != null && official.HasSnapshot &&
                        official.ClaimAvailable &&
                        !official.IsClaimed ? "!" : string.Empty;
                }

                EnsureLocalPreviewDailyRoundLoaded();
                return (localPreviewDailyRound.tasksMask & DailyRoundAllTasks) == DailyRoundAllTasks
                    && !localPreviewDailyRound.rewardClaimed ? "!" : string.Empty;
            }

            return string.Empty;
        }

