        private static void DrawMenuIcon(Rect rect, string iconId, bool active)
        {
            Rect glow = new Rect(rect.x - rect.width * 0.22f, rect.y - rect.height * 0.22f, rect.width * 1.44f, rect.height * 1.44f);
            Color previous = GUI.color;
            GUI.color = active ? new Color(1f, 0.78f, 0.15f, 0.42f) : new Color(0f, 0f, 0f, 0.34f);
            GUI.DrawTexture(glow, GetPremiumTexture(active ? "selected-glow" : "soft-shadow"), ScaleMode.ScaleToFit, true);

            GUI.color = active ? Color.white : new Color(1f, 0.92f, 0.64f, 0.94f);
            GUI.DrawTexture(rect, GetPremiumTexture("icon-socket"), ScaleMode.ScaleToFit, true);

            float inset = rect.width * 0.14f;
            DrawHighDefinitionMenuIcon(new Rect(rect.x + inset, rect.y + inset, rect.width - inset * 2f, rect.height - inset * 2f), iconId, active);
            GUI.color = previous;
        }

        private static void DrawHighDefinitionMenuIcon(Rect rect, string iconId, bool active)
        {
            Texture2D texture = GetHighDefinitionMenuIconTexture(iconId);
            Color previous = GUI.color;
            GUI.color = active ? Color.white : new Color(1f, 0.86f, 0.48f, 0.96f);
            GUI.DrawTexture(rect, texture, ScaleMode.ScaleToFit, true);
            GUI.color = previous;
        }

        private static Texture2D GetHighDefinitionMenuIconTexture(string iconId)
        {
            string key = "menu-hd-" + (string.IsNullOrWhiteSpace(iconId) ? "future" : iconId);
            if (IconTextures.TryGetValue(key, out Texture2D cached)) return cached;
            Texture2D texture = CreateHighDefinitionMenuIconTexture(iconId);
            IconTextures[key] = texture;
            return texture;
        }

        private static Texture2D CreateHighDefinitionMenuIconTexture(string iconId)
        {
            const int size = 256;
            Texture2D texture = new Texture2D(size, size, TextureFormat.RGBA32, false);
            texture.hideFlags = HideFlags.HideAndDontSave;
            ConfigureUiTexture(texture);
            for (int y = 0; y < size; y++)
            {
                for (int x = 0; x < size; x++)
                {
                    texture.SetPixel(x, y, Color.clear);
                }
            }

            string id = string.IsNullOrWhiteSpace(iconId) ? "future" : iconId;
            Color dark = new Color(0.12f, 0.055f, 0.012f, 0.98f);
            Color gold = new Color(1f, 0.70f, 0.14f, 1f);
            Color light = new Color(1f, 0.96f, 0.56f, 1f);
            Color blue = new Color(0.40f, 0.78f, 1f, 1f);
            Color violet = new Color(0.48f, 0.30f, 0.92f, 1f);

            StrokeHex(texture, 128, 130, 104, dark, 15);
            StrokeHex(texture, 128, 128, 96, gold, 9);
            StrokeHex(texture, 128, 128, 78, new Color(1f, 0.86f, 0.28f, 0.40f), 4);

            switch (id)
            {
                case "hive":
                case "hive-nav":
                    FillHex(texture, 128, 136, 54, new Color(0.96f, 0.54f, 0.07f, 1f));
                    StrokeHex(texture, 128, 136, 62, light, 9);
                    FillHex(texture, 128, 136, 25, dark);
                    FillCircle(texture, 128, 86, 31, gold);
                    StrokeCircle(texture, 128, 86, 34, light, 6);
                    DrawLine(texture, 82, 132, 174, 108, new Color(0.38f, 0.16f, 0.02f, 0.65f), 8);
                    break;
                case "trophy":
                case "shield":
                    FillRect(texture, 104, 88, 48, 72, gold);
                    FillEllipse(texture, 128, 86, 54, 34, light);
                    StrokeCircle(texture, 85, 104, 30, gold, 8);
                    StrokeCircle(texture, 171, 104, 30, gold, 8);
                    DrawLine(texture, 128, 158, 128, 186, light, 12);
                    FillRect(texture, 88, 188, 80, 18, gold);
                    FillRect(texture, 72, 210, 112, 16, dark);
                    break;
                case "quests":
                case "detail":
                    FillRect(texture, 76, 70, 104, 132, new Color(0.72f, 0.40f, 0.10f, 1f));
                    FillRect(texture, 91, 84, 74, 100, new Color(0.18f, 0.095f, 0.030f, 1f));
                    StrokeRect(texture, 76, 70, 104, 132, light);
                    DrawLine(texture, 102, 112, 154, 112, gold, 8);
                    DrawLine(texture, 102, 140, 154, 140, gold, 8);
                    DrawLine(texture, 102, 168, 140, 168, gold, 8);
                    break;
                case "events":
                    FillCircle(texture, 128, 132, 58, violet);
                    StrokeCircle(texture, 128, 132, 65, light, 8);
                    FillTriangle(texture, 128, 62, 145, 113, 199, 113, gold);
                    FillTriangle(texture, 199, 113, 155, 145, 172, 200, gold);
                    FillTriangle(texture, 172, 200, 128, 166, 84, 200, gold);
                    FillTriangle(texture, 84, 200, 101, 145, 57, 113, gold);
                    FillTriangle(texture, 57, 113, 111, 113, 128, 62, gold);
                    break;
                case "shop":
                    FillRect(texture, 72, 106, 112, 88, new Color(0.62f, 0.31f, 0.075f, 1f));
                    StrokeRect(texture, 72, 106, 112, 88, light);
                    StrokeCircle(texture, 128, 104, 43, gold, 10);
                    DrawLine(texture, 72, 128, 184, 128, dark, 8);
                    DrawLine(texture, 100, 156, 156, 156, light, 7);
                    break;
                case "world":
                case "map":
                    FillCircle(texture, 128, 130, 58, new Color(0.10f, 0.38f, 0.58f, 1f));
                    StrokeCircle(texture, 128, 130, 65, blue, 9);
                    DrawLine(texture, 64, 130, 192, 130, light, 5);
                    DrawLine(texture, 128, 66, 128, 194, light, 5);
                    StrokeCircle(texture, 128, 130, 31, new Color(0.64f, 0.92f, 1f, 0.95f), 5);
                    break;
                case "alliance":
                    FillCircle(texture, 92, 132, 32, blue);
                    FillCircle(texture, 164, 132, 32, violet);
                    FillCircle(texture, 128, 96, 30, gold);
                    StrokeCircle(texture, 92, 132, 36, light, 6);
                    StrokeCircle(texture, 164, 132, 36, light, 6);
                    StrokeCircle(texture, 128, 96, 34, light, 6);
                    DrawLine(texture, 112, 122, 144, 122, light, 8);
                    break;
                case "inbox":
                    FillRect(texture, 66, 88, 124, 90, new Color(0.14f, 0.18f, 0.20f, 1f));
                    StrokeRect(texture, 66, 88, 124, 90, light);
                    DrawLine(texture, 66, 88, 128, 142, gold, 9);
                    DrawLine(texture, 190, 88, 128, 142, gold, 9);
                    DrawLine(texture, 82, 170, 174, 170, blue, 7);
                    break;
                case "sword":
                    DrawLine(texture, 78, 184, 172, 70, light, 20);
                    DrawLine(texture, 88, 194, 182, 80, gold, 10);
                    DrawLine(texture, 70, 152, 108, 190, new Color(0.56f, 0.26f, 0.05f, 1f), 16);
                    FillTriangle(texture, 172, 70, 204, 46, 192, 96, light);
                    break;
                case "research":
                case "book":
                    FillRect(texture, 66, 72, 58, 118, new Color(0.62f, 0.36f, 0.11f, 1f));
                    FillRect(texture, 132, 72, 58, 118, new Color(0.85f, 0.54f, 0.15f, 1f));
                    StrokeRect(texture, 62, 68, 132, 126, light);
                    DrawLine(texture, 128, 74, 128, 190, dark, 7);
                    DrawLine(texture, 82, 112, 112, 112, light, 6);
                    DrawLine(texture, 144, 112, 176, 112, light, 6);
                    break;
                default:
                    StrokeCircle(texture, 128, 128, 56, blue, 10);
                    DrawLine(texture, 128, 86, 128, 132, gold, 12);
                    DrawLine(texture, 128, 132, 162, 154, gold, 12);
                    break;
            }

            texture.Apply();
            return texture;
        }

        private static void DrawGameIcon(Rect rect, string iconId, Color tint)
        {
            Texture2D texture = GetIconTexture(iconId);
            Rect safeRect = IconSafeRect(rect);
            Color previous = GUI.color;
            string key = string.IsNullOrWhiteSpace(iconId) ? "future" : iconId;
            GUI.color = OfficialIconKeys.Contains(key) || PremiumIconKeys.Contains(key) ? Color.white : tint;
            GUI.DrawTexture(safeRect, texture, ScaleMode.ScaleToFit, true);
            GUI.color = previous;
        }

        private static void DrawCellIllustration(Rect rect, string iconId)
        {
            string key = "cell-illustration-" + iconId;
            if (!IconTextures.TryGetValue(key, out Texture2D texture))
            {
                texture = CreateIconTexture(iconId);
                IconTextures[key] = texture;
            }

            Color previous = GUI.color;
            GUI.color = Color.white;
            GUI.DrawTexture(rect, texture, ScaleMode.ScaleToFit, true);
            GUI.color = previous;
        }

        private static Rect IconSafeRect(Rect rect)
        {
            float inset = Mathf.Max(1f, Mathf.Min(rect.width, rect.height) * 0.06f);
            return new Rect(rect.x + inset, rect.y + inset, Mathf.Max(1f, rect.width - inset * 2f), Mathf.Max(1f, rect.height - inset * 2f));
        }

        private static void DrawPremiumPanel(Rect rect, Color fill, Color border)
        {
            Color previous = GUI.color;
            GUI.color = new Color(1f, 1f, 1f, Mathf.Clamp01(fill.a * 0.52f));
            GUI.DrawTexture(new Rect(rect.x + 5f, rect.y + 8f, rect.width, rect.height), GetPremiumTexture("panel-shadow"), ScaleMode.StretchToFill, true);

            GUI.color = Color.white;
            GUI.DrawTexture(rect, GetPremiumTexture("panel-outer-grain"), ScaleMode.StretchToFill, true);

            Rect inner = new Rect(rect.x + 4f, rect.y + 4f, Mathf.Max(1f, rect.width - 8f), Mathf.Max(1f, rect.height - 8f));
            Color refinedFill = Color.Lerp(fill, new Color(0.014f, 0.012f, 0.009f, fill.a), 0.58f);
            GUI.color = refinedFill;
            GUI.DrawTexture(inner, GetPremiumTexture("panel-fill"), ScaleMode.StretchToFill, true);

            GUI.color = new Color(border.r, border.g, border.b, Mathf.Clamp01(border.a * 0.30f));
            GUI.DrawTexture(new Rect(rect.x + 7f, rect.y + 1f, rect.width - 14f, 1f), GetPremiumTexture("etched-line"), ScaleMode.StretchToFill, true);
            GUI.DrawTexture(new Rect(rect.x + 7f, rect.yMax - 2f, rect.width - 14f, 1f), GetPremiumTexture("etched-line"), ScaleMode.StretchToFill, true);
            GUI.DrawTexture(new Rect(rect.x + 1f, rect.y + 7f, 1f, rect.height - 14f), GetPremiumTexture("etched-line"), ScaleMode.StretchToFill, true);
            GUI.DrawTexture(new Rect(rect.xMax - 2f, rect.y + 7f, 1f, rect.height - 14f), GetPremiumTexture("etched-line"), ScaleMode.StretchToFill, true);

            GUI.color = new Color(1f, 0.82f, 0.34f, Mathf.Clamp01(border.a * 0.50f));
            float cap = Mathf.Min(14f, rect.width * 0.12f);
            DrawPanelCorner(new Rect(rect.x + 3f, rect.y + 3f, cap, cap), false, false);
            DrawPanelCorner(new Rect(rect.xMax - cap - 3f, rect.y + 3f, cap, cap), true, false);
            DrawPanelCorner(new Rect(rect.x + 3f, rect.yMax - cap - 3f, cap, cap), false, true);
            DrawPanelCorner(new Rect(rect.xMax - cap - 3f, rect.yMax - cap - 3f, cap, cap), true, true);

            GUI.color = new Color(1f, 0.60f, 0.12f, Mathf.Clamp01(border.a * 0.10f));
            GUI.DrawTexture(new Rect(rect.x + 10f, rect.y + 5f, rect.width - 20f, Mathf.Max(2f, rect.height * 0.07f)), GetPremiumTexture("amber-veil"), ScaleMode.StretchToFill, true);
            GUI.color = previous;
        }

        private static void DrawPanelCorner(Rect rect, bool right, bool bottom)
        {
            float x0 = right ? rect.xMax - 2f : rect.x;
            float y0 = bottom ? rect.yMax - 2f : rect.y;
            float x1 = right ? rect.x : rect.xMax - 2f;
            float y1 = bottom ? rect.y : rect.yMax - 2f;
            GUI.DrawTexture(new Rect(Mathf.Min(x0, x1), y0, Mathf.Abs(x1 - x0), 2f), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            GUI.DrawTexture(new Rect(x0, Mathf.Min(y0, y1), 2f, Mathf.Abs(y1 - y0)), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            GUI.DrawTexture(new Rect(rect.center.x - 1.5f, rect.center.y - 1.5f, 3f, 3f), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
        }

        private static void DrawPremiumHeaderBand(Rect rect)
        {
            Color previous = GUI.color;
            GUI.color = new Color(0.090f, 0.064f, 0.034f, 0.52f);
            GUI.DrawTexture(rect, GetPremiumTexture("panel-outer-grain"), ScaleMode.StretchToFill, true);

            GUI.color = new Color(1f, 0.66f, 0.16f, 0.12f);
            GUI.DrawTexture(new Rect(rect.x + 2f, rect.y + 2f, rect.width - 4f, Mathf.Max(2f, rect.height * 0.34f)), GetPremiumTexture("amber-veil"), ScaleMode.StretchToFill, true);

            GUI.color = new Color(1f, 0.86f, 0.34f, 0.28f);
            GUI.DrawTexture(new Rect(rect.x + 6f, rect.y + 2f, rect.width - 12f, 1f), GetPremiumTexture("etched-line"), ScaleMode.StretchToFill, true);

            GUI.color = new Color(0f, 0f, 0f, 0.32f);
            GUI.DrawTexture(new Rect(rect.x + 6f, rect.yMax - 2f, rect.width - 12f, 1f), Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            GUI.color = previous;
        }

        private static Texture2D GetPremiumTexture(string id)
        {
            string key = "premium-" + id;
            if (IconTextures.TryGetValue(key, out Texture2D cached)) return cached;
            Texture2D texture = CreatePremiumTexture(id);
            IconTextures[key] = texture;
            return texture;
        }

        private static Texture2D CreatePremiumTexture(string id)
        {
            const int size = 192;
            Texture2D texture = new Texture2D(size, size, TextureFormat.RGBA32, false);
            texture.hideFlags = HideFlags.HideAndDontSave;
            for (int y = 0; y < size; y++)
            {
                for (int x = 0; x < size; x++)
                {
                    texture.SetPixel(x, y, Color.clear);
                }
            }

            if (id == "tutorial-spotlight-mask")
            {
                for (int y = 0; y < size; y++)
                {
                    for (int x = 0; x < size; x++)
                    {
                        float dx = ((x + 0.5f) / size - 0.5f) * 2f;
                        float dy = ((y + 0.5f) / size - 0.5f) * 2f;
                        float distance = Mathf.Sqrt(dx * dx + dy * dy);
                        float alpha = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.82f, 1.0f, distance));
                        texture.SetPixel(x, y, new Color(1f, 1f, 1f, alpha));
                    }
                }
                texture.wrapMode = TextureWrapMode.Clamp;
                texture.filterMode = FilterMode.Bilinear;
            }
            else if (id == "cave-background")
            {
                for (int y = 0; y < size; y++)
                {
                    for (int x = 0; x < size; x++)
                    {
                        float dx = (x - size * 0.5f) / size;
                        float dy = (y - size * 0.5f) / size;
                        float d = Mathf.Clamp01(Mathf.Sqrt(dx * dx + dy * dy) * 1.85f);
                        float vein = Mathf.Sin(x * 0.09f + y * 0.045f) * 0.06f + Mathf.Cos(y * 0.12f) * 0.05f;
                        Color c = Color.Lerp(new Color(0.30f, 0.16f, 0.040f, 1f), new Color(0.010f, 0.012f, 0.008f, 1f), d - vein);
                        texture.SetPixel(x, y, c);
                    }
                }
            }
            else if (id == "wax-field")
            {
                for (int y = 0; y < size; y++)
                {
                    for (int x = 0; x < size; x++)
                    {
                        float dx = (x - size * 0.5f) / (size * 0.5f);
                        float dy = (y - size * 0.5f) / (size * 0.5f);
                        float dist = Mathf.Clamp01(Mathf.Sqrt(dx * dx + dy * dy));
                        float v = ((x * 17 + y * 31) % 47) / 47f;
                        float honey = Mathf.Sin((x + y) * 0.085f) * 0.08f + Mathf.Cos((x - y) * 0.055f) * 0.06f;
                        Color c = Color.Lerp(new Color(0.15f, 0.082f, 0.022f, 0.96f), new Color(0.56f, 0.32f, 0.075f, 0.96f), Mathf.Clamp01(v * 0.38f + honey + 0.22f));
                        c.a = Mathf.Lerp(0.12f, 0.98f, Mathf.Clamp01(1.14f - dist * 1.28f));
                        texture.SetPixel(x, y, c);
                    }
                }
            }
            else if (id == "cave-vignette")
            {
                for (int y = 0; y < size; y++)
                {
                    for (int x = 0; x < size; x++)
                    {
                        float dx = (x - size * 0.5f) / (size * 0.5f);
                        float dy = (y - size * 0.5f) / (size * 0.5f);
                        float d = Mathf.Clamp01(Mathf.Sqrt(dx * dx + dy * dy));
                        Color c = Color.Lerp(new Color(0.34f, 0.18f, 0.035f, 0.86f), new Color(0.01f, 0.008f, 0.004f, 0.98f), d);
                        texture.SetPixel(x, y, c);
                    }
                }
            }
            else if (id == "panel-grain")
            {
                for (int y = 0; y < size; y++)
                {
                    for (int x = 0; x < size; x++)
                    {
                        float nx = x / (float)size;
                        float ny = y / (float)size;
                        float vignette = Mathf.Clamp01(Mathf.Min(Mathf.Min(nx, 1f - nx), Mathf.Min(ny, 1f - ny)) * 7.5f);
                        float wave = Mathf.Sin(x * 0.19f + y * 0.07f) * 0.045f + Mathf.Cos(x * 0.05f - y * 0.17f) * 0.035f;
                        float fleck = ((x * 37 + y * 17 + (x * y) % 29) % 97) / 97f;
                        Color baseColor = Color.Lerp(new Color(0.018f, 0.014f, 0.010f, 0.98f), new Color(0.18f, 0.105f, 0.026f, 0.98f), Mathf.Clamp01(0.32f + wave + fleck * 0.10f));
                        baseColor.a = Mathf.Lerp(0.86f, 0.99f, vignette);
                        texture.SetPixel(x, y, baseColor);
                    }
                }
            }
            else if (id == "panel-outer-grain")
            {
                for (int y = 0; y < size; y++)
                {
                    for (int x = 0; x < size; x++)
                    {
                        float nx = x / (float)(size - 1);
                        float ny = y / (float)(size - 1);
                        float edge = 1f - Mathf.Clamp01(Mathf.Min(Mathf.Min(nx, 1f - nx), Mathf.Min(ny, 1f - ny)) * 9f);
                        float wave = Mathf.Sin(x * 0.15f + y * 0.04f) * 0.055f + Mathf.Cos(x * 0.037f - y * 0.19f) * 0.040f;
                        float cell = Mathf.Sin((x + y) * 0.075f) * Mathf.Cos((x - y) * 0.052f) * 0.055f;
                        float fleck = ((x * 53 + y * 29 + (x * y) % 41) % 101) / 101f;
                        Color darkWax = new Color(0.025f, 0.018f, 0.011f, 0.96f);
                        Color warmWax = new Color(0.22f, 0.115f, 0.030f, 0.96f);
                        Color c = Color.Lerp(darkWax, warmWax, Mathf.Clamp01(0.28f + wave + cell + fleck * 0.09f + edge * 0.16f));
                        c.a = Mathf.Lerp(0.72f, 0.98f, Mathf.Clamp01(edge * 0.85f + 0.20f));
                        texture.SetPixel(x, y, c);
                    }
                }
            }
            else if (id == "etched-line")
            {
                for (int y = 0; y < size; y++)
                {
                    for (int x = 0; x < size; x++)
                    {
                        float scratch = Mathf.Sin(x * 0.31f + y * 0.13f) * 0.12f + (((x * 11 + y * 7) % 17) / 17f) * 0.10f;
                        float alpha = Mathf.Clamp01(0.42f + scratch);
                        texture.SetPixel(x, y, new Color(1f, 0.78f, 0.28f, alpha));
                    }
                }
            }
            else if (id == "amber-veil")
            {
                for (int y = 0; y < size; y++)
                {
                    for (int x = 0; x < size; x++)
                    {
                        float nx = x / (float)(size - 1);
                        float ny = y / (float)(size - 1);
                        float center = Mathf.Clamp01(1f - Mathf.Abs(ny - 0.32f) * 2.9f);
                        float streak = Mathf.Sin(nx * 28f + ny * 4f) * 0.06f + Mathf.Cos(nx * 12f - ny * 17f) * 0.05f;
                        float alpha = Mathf.Clamp01((center + streak) * 0.64f);
                        Color c = Color.Lerp(new Color(0.44f, 0.18f, 0.025f, alpha), new Color(1f, 0.70f, 0.16f, alpha), Mathf.Clamp01(center * 0.72f + streak));
                        texture.SetPixel(x, y, c);
                    }
                }
            }
            else if (id == "icon-socket")
            {
                for (int y = 0; y < size; y++)
                {
                    for (int x = 0; x < size; x++)
                    {
                        float dx = (x - size * 0.5f) / (size * 0.5f);
                        float dy = (y - size * 0.5f) / (size * 0.5f);
                        float d = Mathf.Clamp01(Mathf.Sqrt(dx * dx + dy * dy));
                        float grain = Mathf.Sin(x * 0.17f + y * 0.06f) * 0.04f + Mathf.Cos(x * 0.05f - y * 0.21f) * 0.035f;
                        float alpha = Mathf.Clamp01(1.12f - d * 1.18f);
                        Color c = Color.Lerp(new Color(0.020f, 0.016f, 0.011f, alpha), new Color(0.24f, 0.12f, 0.028f, alpha), Mathf.Clamp01(0.30f + grain));
                        texture.SetPixel(x, y, c);
                    }
                }

                StrokeHex(texture, 96, 98, 78, new Color(0.08f, 0.035f, 0.008f, 0.98f), 16);
                StrokeHex(texture, 96, 96, 70, new Color(1f, 0.72f, 0.16f, 0.92f), 7);
                StrokeHex(texture, 96, 96, 56, new Color(1f, 0.88f, 0.34f, 0.42f), 3);
                FillCircle(texture, 72, 62, 9, new Color(1f, 0.86f, 0.36f, 0.44f));
                DrawLine(texture, 58, 58, 134, 42, new Color(1f, 0.84f, 0.28f, 0.22f), 4);
                FillCircle(texture, 124, 130, 8, new Color(0f, 0f, 0f, 0.24f));
            }
            else if (id == "honey-glow-pool")
            {
                for (int y = 0; y < size; y++)
                {
                    for (int x = 0; x < size; x++)
                    {
                        float dx = (x - size * 0.5f) / (size * 0.5f);
                        float dy = (y - size * 0.5f) / (size * 0.5f);
                        float d = Mathf.Clamp01(Mathf.Sqrt(dx * dx + dy * dy));
                        float alpha = Mathf.Clamp01(1f - d) * 0.76f;
                        Color c = Color.Lerp(new Color(1f, 0.66f, 0.04f, alpha), new Color(0.35f, 0.13f, 0.02f, 0f), d);
                        texture.SetPixel(x, y, c);
                    }
                }
            }
            else if (id == "wax-blob")
            {
                FillEllipse(texture, 96, 104, 80, 44, new Color(0.41f, 0.20f, 0.045f, 0.72f));
                FillEllipse(texture, 78, 88, 46, 34, new Color(0.84f, 0.48f, 0.08f, 0.78f));
                FillEllipse(texture, 118, 98, 38, 28, new Color(0.96f, 0.64f, 0.13f, 0.70f));
                FillEllipse(texture, 96, 78, 24, 16, new Color(1f, 0.86f, 0.26f, 0.62f));
                StrokeCircle(texture, 86, 88, 42, new Color(0.18f, 0.07f, 0.018f, 0.46f), 5);
            }
            else if (id == "moss-patch")
            {
                FillEllipse(texture, 72, 102, 48, 28, new Color(0.18f, 0.31f, 0.12f, 0.72f));
                FillEllipse(texture, 104, 88, 52, 32, new Color(0.25f, 0.42f, 0.16f, 0.68f));
                FillEllipse(texture, 126, 112, 34, 22, new Color(0.13f, 0.25f, 0.10f, 0.72f));
                FillCircle(texture, 84, 72, 8, new Color(0.74f, 0.54f, 0.16f, 0.78f));
                FillCircle(texture, 132, 84, 6, new Color(0.58f, 0.34f, 0.78f, 0.70f));
            }
            else if (id == "gold-bar")
            {
                for (int y = 0; y < size; y++)
                {
                    for (int x = 0; x < size; x++)
                    {
                        float dy = Mathf.Abs(y - size * 0.38f) / size;
                        float streak = Mathf.Sin(x * 0.12f + y * 0.035f) * 0.06f + Mathf.Cos(x * 0.031f - y * 0.16f) * 0.04f;
                        float fleck = ((x * 19 + y * 43 + (x * y) % 31) % 89) / 89f;
                        float glow = Mathf.Clamp01(0.54f - dy + streak + fleck * 0.06f);
                        Color c = Color.Lerp(new Color(0.18f, 0.095f, 0.028f, 0.78f), new Color(0.82f, 0.51f, 0.13f, 0.88f), glow);
                        if (y < size * 0.16f) c = Color.Lerp(c, new Color(1f, 0.84f, 0.28f, 0.76f), 0.22f);
                        if (y > size * 0.78f) c = Color.Lerp(c, new Color(0.06f, 0.030f, 0.012f, 0.82f), 0.34f);
                        texture.SetPixel(x, y, c);
                    }
                }
            }
            else if (id == "progress-bg")
            {
                FillRect(texture, 0, 0, size, size, new Color(0.06f, 0.04f, 0.025f, 0.95f));
            }
            else if (id == "progress-fill")
            {
                for (int y = 0; y < size; y++)
                {
                    Color c = Color.Lerp(new Color(1f, 0.50f, 0.02f, 1f), new Color(1f, 0.92f, 0.18f, 1f), y / (float)size);
                    for (int x = 0; x < size; x++) texture.SetPixel(x, y, c);
                }
            }
            else if (id == "wax-bridge")
            {
                for (int y = 0; y < size; y++)
                {
                    float edge = Mathf.Abs(y - size * 0.5f) / (size * 0.5f);
                    Color c = Color.Lerp(new Color(1f, 0.88f, 0.30f, 0.98f), new Color(0.70f, 0.34f, 0.04f, 0.94f), edge);
                    for (int x = 0; x < size; x++) texture.SetPixel(x, y, c);
                }
            }
            else if (id == "wax-bridge-shadow")
            {
                FillEllipse(texture, 96, 96, 92, 24, new Color(0f, 0f, 0f, 0.52f));
            }
            else if (id == "honey-preview")
            {
                for (int y = 0; y < size; y++)
                {
                    for (int x = 0; x < size; x++)
                    {
                        float wave = Mathf.Sin(x * 0.11f + y * 0.07f) * 0.11f;
                        Color c = Color.Lerp(new Color(0.36f, 0.16f, 0.025f, 1f), new Color(1f, 0.68f, 0.05f, 1f), Mathf.Clamp01(y / (float)size + wave));
                        texture.SetPixel(x, y, c);
                    }
                }

                DrawLine(texture, 22, 64, 170, 52, new Color(1f, 0.92f, 0.25f, 0.82f), 8);
                DrawLine(texture, 30, 112, 168, 95, new Color(1f, 0.78f, 0.12f, 0.70f), 6);
                FillCircle(texture, 64, 80, 18, new Color(1f, 0.90f, 0.18f, 0.72f));
                FillCircle(texture, 126, 114, 12, new Color(1f, 0.84f, 0.12f, 0.62f));
            }
            else if (id == "red-badge")
            {
                FillCircle(texture, 96, 96, 70, new Color(0.82f, 0.02f, 0.02f, 1f));
                StrokeCircle(texture, 96, 96, 72, new Color(1f, 0.78f, 0.42f, 1f), 8);
                FillCircle(texture, 96, 96, 18, Color.white);
            }
            else if (id == "soft-shadow" || id == "panel-shadow" || id == "cell-shadow")
            {
                FillEllipse(texture, 96, 96, 78, 48, new Color(0f, 0f, 0f, id == "panel-shadow" ? 0.38f : 0.55f));
            }
            else if (id == "selected-glow")
            {
                FillHex(texture, 96, 96, 90, new Color(1f, 0.80f, 0.08f, 0.22f));
                StrokeHex(texture, 96, 96, 84, new Color(1f, 0.94f, 0.18f, 0.86f), 10);
                StrokeHex(texture, 96, 96, 70, new Color(0.20f, 0.96f, 1f, 0.80f), 5);
            }
            else if (id == "queen-hive")
            {
                FillCircle(texture, 96, 102, 58, new Color(1f, 0.60f, 0.05f, 1f));
                FillCircle(texture, 96, 82, 40, new Color(1f, 0.83f, 0.22f, 1f));
                StrokeCircle(texture, 96, 102, 62, new Color(0.58f, 0.22f, 0.02f, 1f), 8);
                FillTriangle(texture, 54, 62, 74, 24, 92, 62, new Color(1f, 0.94f, 0.30f, 1f));
                FillTriangle(texture, 82, 62, 96, 18, 110, 62, new Color(1f, 0.94f, 0.30f, 1f));
                FillTriangle(texture, 100, 62, 122, 24, 138, 62, new Color(1f, 0.94f, 0.30f, 1f));
            }
            else if (id.StartsWith("cell-", StringComparison.Ordinal))
            {
                Color rim = id == "cell-selected" ? new Color(1f, 0.96f, 0.08f, 1f) : id == "cell-server" ? new Color(0.12f, 0.86f, 1f, 1f) : new Color(1f, 0.62f, 0.10f, 1f);
                Color body = id == "cell-locked" ? new Color(0.24f, 0.15f, 0.07f, 1f) : id == "cell-future" ? new Color(0.27f, 0.22f, 0.11f, 1f) : new Color(0.86f, 0.45f, 0.07f, 1f);
                FillHex(texture, 99, 104, 88, new Color(0.02f, 0.01f, 0.004f, 0.82f));
                FillHex(texture, 96, 86, 86, rim);
                FillHex(texture, 96, 88, 72, new Color(0.46f, 0.22f, 0.035f, 1f));
                FillHex(texture, 96, 78, 62, body);
                FillHex(texture, 84, 64, 34, new Color(1f, 0.86f, 0.28f, 0.45f));
                FillHex(texture, 112, 102, 38, new Color(0.12f, 0.045f, 0.012f, 0.42f));
                StrokeHex(texture, 96, 86, id == "cell-selected" ? 91 : 84, rim, id == "cell-selected" ? 10 : 7);
                StrokeHex(texture, 96, 88, 67, new Color(1f, 0.74f, 0.16f, 0.64f), 4);
                DrawLine(texture, 46, 88, 136, 62, new Color(1f, 0.82f, 0.24f, 0.52f), 5);
                DrawLine(texture, 56, 120, 144, 92, new Color(0.10f, 0.035f, 0.008f, 0.54f), 6);
                for (int dot = 0; dot < 10; dot++)
                {
                    int px = 48 + ((dot * 23) % 88);
                    int py = 58 + ((dot * 31) % 66);
                    FillCircle(texture, px, py, 3, new Color(1f, 0.78f, 0.20f, 0.34f));
                }
            }
            else
            {
                FillRect(texture, 0, 0, size, size, new Color(0.08f, 0.06f, 0.03f, 0.92f));
            }

            texture.Apply();
            return texture;
        }

        private static void FillHex(Texture2D texture, int cx, int cy, int radius, Color color)
        {
            Vector2Int[] points = HexPoints(cx, cy, radius);
            for (int i = 1; i < points.Length - 1; i++)
            {
                FillTriangle(texture, points[0].x, points[0].y, points[i].x, points[i].y, points[i + 1].x, points[i + 1].y, color);
            }
            FillTriangle(texture, cx, cy, points[0].x, points[0].y, points[points.Length - 1].x, points[points.Length - 1].y, color);
            for (int i = 0; i < points.Length - 1; i++)
            {
                FillTriangle(texture, cx, cy, points[i].x, points[i].y, points[i + 1].x, points[i + 1].y, color);
            }
        }

        private static void StrokeHex(Texture2D texture, int cx, int cy, int radius, Color color, int thickness)
        {
            Vector2Int[] points = HexPoints(cx, cy, radius);
            for (int i = 0; i < points.Length; i++)
            {
                Vector2Int a = points[i];
                Vector2Int b = points[(i + 1) % points.Length];
                DrawLine(texture, a.x, a.y, b.x, b.y, color, thickness);
            }
        }

        private static Vector2Int[] HexPoints(int cx, int cy, int radius)
        {
            Vector2Int[] points = new Vector2Int[6];
            for (int i = 0; i < 6; i++)
            {
                float angle = Mathf.Deg2Rad * (60f * i + 30f);
                points[i] = new Vector2Int(cx + Mathf.RoundToInt(Mathf.Cos(angle) * radius), cy + Mathf.RoundToInt(Mathf.Sin(angle) * radius));
            }

            return points;
        }

        private static void CreateWaxAmbience(Transform parent)
        {
            GameObject basePlate = GameObject.CreatePrimitive(PrimitiveType.Cube);
            basePlate.name = "Hive Wax Ambience Background";
            basePlate.transform.SetParent(parent, false);
            basePlate.transform.localPosition = new Vector3(0f, -0.08f, 0f);
            basePlate.transform.localScale = new Vector3(7.6f, 0.06f, 6.4f);
            Renderer renderer = basePlate.GetComponent<Renderer>();
            if (renderer != null) renderer.material.color = new Color(0.24f, 0.18f, 0.075f);

            GameObject highlight = new GameObject("Hive Wax Readability Highlight");
            highlight.name = "Hive Wax Readability Highlight";
            highlight.transform.SetParent(parent, false);
            highlight.transform.localPosition = new Vector3(-0.3f, -0.025f, 0.2f);
            highlight.AddComponent<MeshFilter>().sharedMesh = CreateHexMesh(3.15f);
            MeshRenderer highlightRenderer = highlight.AddComponent<MeshRenderer>();
            highlightRenderer.material = CreateHiveRuntimeMaterial();
            if (highlightRenderer != null) highlightRenderer.material.color = new Color(0.58f, 0.36f, 0.09f);

            Vector3[] moss = { new Vector3(-3.7f, 0f, 1.9f), new Vector3(3.4f, 0f, 1.6f), new Vector3(-2.4f, 0f, -2.3f), new Vector3(2.7f, 0f, -2.2f), new Vector3(0.8f, 0f, 2.7f) };
            for (int i = 0; i < moss.Length; i++)
            {
                GameObject patch = GameObject.CreatePrimitive(PrimitiveType.Sphere);
                patch.name = "Hive Moss Accent " + i;
                patch.transform.SetParent(parent, false);
                patch.transform.localPosition = moss[i] + new Vector3(0f, 0.035f, 0f);
                patch.transform.localScale = new Vector3(0.48f, 0.08f, 0.34f);
                Renderer patchRenderer = patch.GetComponent<Renderer>();
                if (patchRenderer != null) patchRenderer.material.color = new Color(0.18f, 0.27f, 0.12f);
            }
        }

