        {
            RenderSettings.ambientLight = new Color(0.58f, 0.42f, 0.20f);
            RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Flat;

            GameObject sun = new GameObject("Hive Product Warm Key Light");
