        private static void CreateHexLayer(Transform parent, string name, float radius, Vector3 localPosition, Color color)
        {
            GameObject layer = new GameObject("Hive Hex " + name);
            layer.transform.SetParent(parent, false);
            layer.transform.localPosition = localPosition;
            layer.AddComponent<MeshFilter>().sharedMesh = CreateHexMesh(radius);
            MeshRenderer renderer = layer.AddComponent<MeshRenderer>();
            renderer.material = CreateHiveRuntimeMaterial();
            renderer.material.color = color;
        }

        private static void CreateRuntimeIsoWall(Transform parent, string name, int side, float radius, Color color)
        {
            GameObject wall = new GameObject("Hive Hex " + name);
            wall.transform.SetParent(parent, false);
            wall.transform.localPosition = Vector3.zero;
            MeshFilter filter = wall.AddComponent<MeshFilter>();
            Mesh mesh = new Mesh { name = "Runtime Hive Iso Wall" };
            float drop = 0.20f;
            Vector3 a = new Vector3(side * radius * 0.86f, -0.010f, radius * 0.48f);
            Vector3 b = new Vector3(side * radius * 0.86f, -0.010f, -radius * 0.48f);
            Vector3 c = new Vector3(side * radius * 0.72f, -drop, -radius * 0.40f);
            Vector3 d = new Vector3(side * radius * 0.72f, -drop, radius * 0.40f);
            mesh.vertices = new[] { a, b, c, d };
            mesh.triangles = side > 0 ? new[] { 0, 1, 2, 0, 2, 3 } : new[] { 0, 2, 1, 0, 3, 2 };
            mesh.RecalculateNormals();
            filter.sharedMesh = mesh;
            MeshRenderer renderer = wall.AddComponent<MeshRenderer>();
            renderer.material = CreateHiveRuntimeMaterial();
            renderer.material.color = color;
        }

