                CreateZonePrimitive(parent, "Locked Crossbar B", PrimitiveType.Cube, new Vector3(0.20f, 0.205f, -0.08f), new Vector3(0.22f, 0.100f, 0.60f), new Color(0.045f, 0.032f, 0.020f));
                CreateZonePrimitive(parent, "Lock Body Token", PrimitiveType.Cube, new Vector3(0.00f, 0.39f, 0.39f), new Vector3(0.40f, 0.26f, 0.13f), new Color(1f, 0.67f, 0.08f));
                CreateZonePrimitive(parent, "Lock Keyhole Token", PrimitiveType.Cylinder, new Vector3(0.00f, 0.43f, 0.46f), new Vector3(0.07f, 0.05f, 0.07f), new Color(0.06f, 0.04f, 0.02f));
                CreateZonePrimitive(parent, "Lock Shackle Token", PrimitiveType.Capsule, new Vector3(0.00f, 0.60f, 0.39f), new Vector3(0.24f, 0.30f, 0.12f), new Color(1f, 0.86f, 0.24f));
