                CreateZonePrimitive(parent, "Server Badge Screen", PrimitiveType.Cube, new Vector3(-0.15f, 0.48f, 0.43f), new Vector3(0.22f, 0.14f, 0.08f), new Color(0.88f, 1f, 1f));
                CreateZonePrimitive(parent, "Server Signal Mast", PrimitiveType.Cylinder, new Vector3(0.20f, 0.52f, 0.43f), new Vector3(0.10f, 0.30f, 0.10f), new Color(0.55f, 0.98f, 1f));
                CreateZonePrimitive(parent, "Server Signal Ping", PrimitiveType.Sphere, new Vector3(0.20f, 0.76f, 0.43f), new Vector3(0.20f, 0.20f, 0.20f), new Color(0.35f, 0.93f, 1f));
                CreateZonePrimitive(parent, "Server Second Ping", PrimitiveType.Sphere, new Vector3(0.36f, 0.66f, 0.39f), new Vector3(0.12f, 0.12f, 0.12f), new Color(0.80f, 1f, 1f));
