            else if (cell.State == HiveCellStateKind.EmptyPreview)
            {
                CreateZonePrimitive(parent, "Future Diagonal Pattern A", PrimitiveType.Cube, new Vector3(-0.24f, 0.158f, 0.17f), new Vector3(0.48f, 0.044f, 0.070f), new Color(0.22f, 0.76f, 0.96f));
