                CreateZonePrimitive(parent, "Future Ghost Column", PrimitiveType.Cylinder, new Vector3(-0.32f, 0.28f, 0.28f), new Vector3(0.13f, 0.30f, 0.13f), new Color(0.16f, 0.62f, 0.82f));
