        }

        private static void CreateZoneProp(Transform parent, HiveHexCell cell)
        {
            Color color = ZoneColor(cell.ZoneId, cell.State);
            if (cell.ZoneId == "Storage")
            {
                CreateZonePrimitive(parent, "Honey Vault A", PrimitiveType.Cylinder, new Vector3(-0.18f, 0.10f, -0.12f), new Vector3(0.16f, 0.08f, 0.16f), color);
                CreateZonePrimitive(parent, "Honey Vault B", PrimitiveType.Cylinder, new Vector3(0.02f, 0.12f, -0.08f), new Vector3(0.13f, 0.10f, 0.13f), new Color(1f, 0.79f, 0.24f));
                return;
            }

            if (cell.ZoneId == "Nursery")
            {
                CreateZonePrimitive(parent, "Nursery Egg A", PrimitiveType.Sphere, new Vector3(-0.20f, 0.10f, -0.10f), new Vector3(0.16f, 0.11f, 0.12f), color);
                CreateZonePrimitive(parent, "Nursery Egg B", PrimitiveType.Sphere, new Vector3(0.02f, 0.11f, -0.13f), new Vector3(0.13f, 0.10f, 0.11f), new Color(1f, 0.88f, 0.55f));
                return;
            }

            if (cell.ZoneId == "Defense")
            {
                CreateZonePrimitive(parent, "Defense Gate", PrimitiveType.Cube, new Vector3(-0.10f, 0.10f, -0.08f), new Vector3(0.32f, 0.08f, 0.10f), color);
                CreateZonePrimitive(parent, "Defense Stinger", PrimitiveType.Capsule, new Vector3(0.12f, 0.18f, -0.08f), new Vector3(0.09f, 0.18f, 0.09f), new Color(1f, 0.70f, 0.18f));
                return;
            }

            if (cell.ZoneId == "Research")
            {
                CreateZonePrimitive(parent, "Research Crystal", PrimitiveType.Capsule, new Vector3(-0.12f, 0.18f, -0.10f), new Vector3(0.12f, 0.24f, 0.12f), new Color(0.62f, 0.86f, 0.92f));
                CreateZonePrimitive(parent, "Research Base", PrimitiveType.Cylinder, new Vector3(0.02f, 0.10f, -0.08f), new Vector3(0.20f, 0.05f, 0.20f), color);
                return;
            }

            if (cell.ZoneId == "Production")
            {
                CreateZonePrimitive(parent, "Wax Press Base", PrimitiveType.Cube, new Vector3(-0.12f, 0.10f, -0.08f), new Vector3(0.28f, 0.10f, 0.20f), color);
                CreateZonePrimitive(parent, "Wax Press Drop", PrimitiveType.Sphere, new Vector3(0.13f, 0.14f, -0.08f), new Vector3(0.12f, 0.12f, 0.12f), new Color(1f, 0.62f, 0.16f));
                return;
            }

            CreateZonePrimitive(parent, "Alliance Beacon", PrimitiveType.Capsule, new Vector3(-0.10f, 0.18f, -0.08f), new Vector3(0.12f, 0.22f, 0.12f), color);
            CreateZonePrimitive(parent, "Alliance Glow", PrimitiveType.Sphere, new Vector3(0.08f, 0.19f, -0.08f), new Vector3(0.12f, 0.12f, 0.12f), new Color(0.50f, 0.72f, 0.95f));
        }

        private static void CreateZonePrimitive(Transform parent, string name, PrimitiveType type, Vector3 localPosition, Vector3 localScale, Color color)
        {
            GameObject prop = GameObject.CreatePrimitive(type);
            prop.name = "Hive Zone Landmark " + name;
            prop.transform.SetParent(parent, false);
            prop.transform.localPosition = localPosition;
            prop.transform.localScale = localScale;
            Renderer renderer = prop.GetComponent<Renderer>();
            if (renderer != null) renderer.material.color = color;
        }

        private static void BuildCells()
        {
            if (Cells.Count > 0) return;
            Rooms.Clear();
            IReadOnlyList<HiveRoomPreviewSlot> rooms = RoomPreview.RoomSlots;
            for (int i = 0; i < rooms.Count; i++) Rooms[rooms[i].CellId] = rooms[i];
            for (int q = -2; q <= 2; q++)
            {
                int r1 = Math.Max(-2, -q - 2);
                int r2 = Math.Min(2, -q + 2);
                for (int r = r1; r <= r2; r++)
                {
                    string id = "cell-" + q + "-" + r;
                    Cells.Add(new HiveHexCell(id, q, r, ZoneFor(q, r), StateFor(id, q, r)));
                }
            }
        }

        private static void RefreshSelectionRims()
        {
            if (root == null) return;
            Renderer[] renderers = root.GetComponentsInChildren<Renderer>();
            for (int i = 0; i < renderers.Length; i++)
            {
                if (!renderers[i].name.StartsWith("Hive Hex Rim ", StringComparison.Ordinal)) continue;
                string cellId = renderers[i].name.Substring("Hive Hex Rim ".Length);
                HiveHexCell cell = Cells.Find(c => c.CellId == cellId);
                renderers[i].material.color = RimColor(cell, cellId == focusedCellId);
            }
        }

        private static void FocusNextCell()
        {
            BuildCells();
            int index = Cells.FindIndex(c => c.CellId == focusedCellId);
            focusedCellId = Cells[(index + 1 + Cells.Count) % Cells.Count].CellId;
            lastTouchFeedback = "Selection ruche: " + focusedCellId;
            RefreshSelectionRims();
        }

        private static Mesh CreateHexMesh(float radius)
        {
            Vector3[] vertices = new Vector3[7];
            vertices[0] = Vector3.zero;
            for (int i = 0; i < 6; i++)
            {
                float angle = Mathf.Deg2Rad * (60f * i + 30f);
                vertices[i + 1] = new Vector3(Mathf.Cos(angle) * radius, 0f, Mathf.Sin(angle) * radius);
            }
            int[] triangles = { 0, 1, 2, 0, 2, 3, 0, 3, 4, 0, 4, 5, 0, 5, 6, 0, 6, 1 };
            Mesh mesh = new Mesh { name = "Hive Hex Mesh" };
            mesh.vertices = vertices;
            mesh.triangles = triangles;
            mesh.RecalculateNormals();
            return mesh;
        }

        private static Vector3 AxialToWorld(int q, int r)
        {
            const float size = 0.88f;
            float x = size * Mathf.Sqrt(3f) * (q + r * 0.5f);
            float z = size * 1.5f * r;
            return new Vector3(x, 0f, z);
        }

