        private static HiveCellStateKind StateFor(string id, int q, int r)
        {
            if (Rooms.ContainsKey(id)) return id == "cell--1-1" ? HiveCellStateKind.ServerRequired : id == "cell--1-0" ? HiveCellStateKind.Locked : id == "cell-0-1" ? HiveCellStateKind.UpgradeCandidate : HiveCellStateKind.OccupiedPreview;
            return Math.Abs(q) == 2 || Math.Abs(r) == 2 ? HiveCellStateKind.Locked : HiveCellStateKind.EmptyPreview;
        }

        private static string ZoneFor(int q, int r)
        {
            if (q == 0 && r == 0) return "Storage";
            if (q > 0) return "Nursery";
            if (r > 0) return "Production";
            if (q < 0 && r > 0) return "Defense";
            if (q < 0) return "Research";
            return "SocialGate";
        }

        private static Vector2[] P(params float[] xy)
        {
            if (xy == null || xy.Length % 2 != 0) throw new ArgumentException("Polygon coordinates must be x/y pairs.");
            Vector2[] points = new Vector2[xy.Length / 2];
            for (int i = 0; i < points.Length; i++)
            {
                points[i] = new Vector2(xy[i * 2], xy[i * 2 + 1]);
            }

            return points;
        }

