        private static Texture2D SolidTexture(Color color)
        {
            Texture2D texture = new Texture2D(1, 1);
            texture.hideFlags = HideFlags.HideAndDontSave;
            texture.SetPixel(0, 0, color);
            texture.Apply();
            return texture;
        }

        private static Texture2D GetIconTexture(string id)
        {
            string key = string.IsNullOrWhiteSpace(id) ? "future" : id;
            if (IconTextures.TryGetValue(key, out Texture2D cached))
            {
                return cached;
            }

            Texture2D texture = Resources.Load<Texture2D>("PremiumBeeIcons/" + key);
            if (texture != null)
            {
                ConfigureUiTexture(texture);
                PremiumIconKeys.Add(key);
                IconTextures[key] = texture;
                return texture;
            }

            if (IsPremiumRuntimeIcon(key))
            {
                texture = CreateIconTexture(key);
                PremiumIconKeys.Add(key);
                IconTextures[key] = texture;
                return texture;
            }

            texture = Resources.Load<Texture2D>("UI031Icons/" + key);
            if (texture == null)
            {
                texture = CreateIconTexture(key);
                PremiumIconKeys.Add(key);
            }
            else
            {
                ConfigureUiTexture(texture);
                OfficialIconKeys.Add(key);
            }
            IconTextures[key] = texture;
            return texture;
        }

        private static void ConfigureUiTexture(Texture2D texture)
        {
            if (texture == null) return;
            texture.filterMode = FilterMode.Bilinear;
            texture.wrapMode = TextureWrapMode.Clamp;
            texture.anisoLevel = 1;
        }

        private static bool IsPremiumRuntimeIcon(string key)
        {
            switch (key)
            {
                case "honey":
                case "wax":
                case "pollen":
                case "bee":
                case "capacity":
                case "queen":
                case "preview":
                case "hive":
                case "hive-nav":
                case "shield":
                case "detail":
                case "events":
                case "shop":
                case "world":
                case "alliance":
                case "inbox":
                case "zones":
                case "resources":
                case "more":
                case "back":
                case "close":
                case "nursery":
                case "research":
                case "production":
                case "future":
                case "server":
                case "locked":
                case "flower":
                case "sword":
                case "book":
                case "upgrade-ready":
                    return true;
                default:
                    return false;
            }
        }

        private static Texture2D CreateIconTexture(string id)
        {
            const int size = 192;
            Texture2D texture = new Texture2D(size, size, TextureFormat.RGBA32, false);
            texture.hideFlags = HideFlags.HideAndDontSave;
            ConfigureUiTexture(texture);
            for (int y = 0; y < size; y++)
            {
                for (int x = 0; x < size; x++)
                {
                    texture.SetPixel(x, y, Color.clear);
                }
            }

            Color shadow = new Color(0.08f, 0.045f, 0.018f, 0.92f);
            Color body = new Color(1f, 0.86f, 0.34f, 1f);
            Color glow = new Color(1f, 0.98f, 0.70f, 1f);
            Color blue = new Color(0.46f, 0.86f, 1f, 1f);

            switch (id)
            {
                case "honey":
                    FillCircle(texture, 64, 44, 25, shadow);
                    FillCircle(texture, 64, 52, 25, new Color(1f, 0.68f, 0.05f, 1f));
                    FillTriangle(texture, 42, 58, 86, 58, 64, 108, new Color(1f, 0.58f, 0.02f, 1f));
                    StrokeCircle(texture, 64, 55, 29, glow, 5);
                    FillCircle(texture, 56, 55, 7, new Color(1f, 0.95f, 0.45f, 1f));
                    break;
                case "wax":
                    FillHex(texture, 64, 66, 48, new Color(0.94f, 0.62f, 0.12f, 1f));
                    StrokeHex(texture, 64, 66, 52, glow, 6);
                    DrawLine(texture, 36, 78, 92, 44, new Color(0.42f, 0.18f, 0.02f, 0.65f), 5);
                    DrawLine(texture, 42, 94, 102, 60, new Color(1f, 0.84f, 0.28f, 1f), 4);
                    break;
                case "pollen":
                    for (int i = 0; i < 8; i++)
                    {
                        float angle = i * Mathf.PI * 2f / 8f;
                        FillCircle(texture, 64 + Mathf.RoundToInt(Mathf.Cos(angle) * 24f), 64 + Mathf.RoundToInt(Mathf.Sin(angle) * 20f), 14, i % 2 == 0 ? body : new Color(0.95f, 0.56f, 0.16f, 1f));
                    }
                    FillCircle(texture, 64, 64, 17, glow);
                    break;
                case "bee":
                    FillEllipse(texture, 45, 62, 26, 18, new Color(0.70f, 0.94f, 1f, 0.72f));
                    FillEllipse(texture, 83, 62, 26, 18, new Color(0.70f, 0.94f, 1f, 0.72f));
                    FillEllipse(texture, 64, 70, 22, 34, body);
                    DrawLine(texture, 44, 60, 84, 60, shadow, 8);
                    DrawLine(texture, 46, 76, 82, 76, shadow, 8);
                    FillCircle(texture, 64, 35, 16, shadow);
                    FillCircle(texture, 58, 32, 3, glow);
                    FillCircle(texture, 70, 32, 3, glow);
                    break;
                case "capacity":
                    StrokeCircle(texture, 64, 66, 42, shadow, 7);
                    DrawLine(texture, 64, 66, 94, 86, body, 8);
                    FillCircle(texture, 64, 66, 10, glow);
                    DrawLine(texture, 32, 102, 96, 102, body, 7);
                    break;
                case "flower":
                case "nursery":
                    for (int i = 0; i < 8; i++)
                    {
                        float angle = i * Mathf.PI * 2f / 8f;
                        FillEllipse(texture, 64 + Mathf.RoundToInt(Mathf.Cos(angle) * 24f), 64 + Mathf.RoundToInt(Mathf.Sin(angle) * 22f), 15, 26, new Color(1f, 0.78f, 0.30f, 1f));
                    }
                    FillCircle(texture, 64, 64, 18, new Color(1f, 0.96f, 0.42f, 1f));
                    FillCircle(texture, 64, 64, 8, shadow);
                    break;
                case "sword":
                    DrawLine(texture, 36, 98, 88, 34, glow, 12);
                    DrawLine(texture, 44, 104, 96, 40, body, 6);
                    DrawLine(texture, 34, 84, 54, 104, new Color(0.50f, 0.25f, 0.06f, 1f), 9);
                    FillTriangle(texture, 88, 34, 104, 22, 98, 48, glow);
                    break;
                case "book":
                case "research":
                    FillRect(texture, 26, 34, 34, 62, new Color(0.72f, 0.45f, 0.14f, 1f));
                    FillRect(texture, 66, 34, 34, 62, new Color(0.88f, 0.62f, 0.22f, 1f));
                    StrokeRect(texture, 24, 32, 78, 66, glow);
                    DrawLine(texture, 63, 36, 63, 96, shadow, 4);
                    DrawLine(texture, 34, 52, 54, 52, glow, 3);
                    DrawLine(texture, 74, 52, 94, 52, glow, 3);
                    break;
                case "queen":
                    FillTriangle(texture, 24, 88, 44, 34, 60, 86, body);
                    FillTriangle(texture, 46, 88, 64, 22, 82, 88, glow);
                    FillTriangle(texture, 72, 88, 96, 34, 104, 88, body);
                    StrokeCircle(texture, 64, 70, 46, shadow, 6);
                    break;
                case "resources":
                    FillCircle(texture, 24, 27, 7, body);
                    FillCircle(texture, 40, 27, 7, glow);
                    FillCircle(texture, 32, 42, 8, new Color(0.70f, 0.88f, 0.28f, 1f));
                    StrokeCircle(texture, 32, 33, 23, shadow, 3);
                    break;
                case "hive":
                case "hive-nav":
                    FillHex(texture, 64, 68, 44, new Color(1f, 0.64f, 0.08f, 1f));
                    StrokeHex(texture, 64, 68, 50, glow, 7);
                    FillHex(texture, 64, 68, 22, new Color(0.55f, 0.24f, 0.03f, 1f));
                    FillCircle(texture, 64, 44, 18, body);
                    break;
                case "zones":
                    FillHex(texture, 45, 50, 22, body);
                    FillHex(texture, 76, 50, 22, new Color(1f, 0.72f, 0.18f, 1f));
                    FillHex(texture, 60, 80, 24, glow);
                    StrokeHex(texture, 60, 62, 54, shadow, 4);
                    break;
                case "production":
                    FillRect(texture, 34, 50, 58, 38, new Color(0.82f, 0.42f, 0.08f, 1f));
                    StrokeRect(texture, 34, 50, 58, 38, glow);
                    FillCircle(texture, 50, 48, 12, body);
                    FillCircle(texture, 78, 48, 12, body);
                    DrawLine(texture, 42, 98, 88, 98, shadow, 6);
                    break;
                case "server":
                    FillRect(texture, 28, 42, 72, 46, new Color(0.05f, 0.20f, 0.34f, 1f));
                    StrokeRect(texture, 28, 42, 72, 46, blue);
                    FillCircle(texture, 48, 64, 8, new Color(0.82f, 1f, 1f, 1f));
                    FillCircle(texture, 76, 64, 8, blue);
                    DrawLine(texture, 64, 88, 64, 108, blue, 6);
                    DrawLine(texture, 42, 108, 86, 108, blue, 6);
                    break;
                case "locked":
                    FillRect(texture, 34, 58, 60, 42, new Color(0.12f, 0.07f, 0.035f, 1f));
                    StrokeRect(texture, 34, 58, 60, 42, body);
                    StrokeCircle(texture, 64, 58, 28, body, 8);
                    FillCircle(texture, 64, 78, 7, glow);
                    DrawLine(texture, 64, 82, 64, 94, glow, 5);
                    break;
                case "alliance":
                    FillCircle(texture, 48, 62, 18, body);
                    FillCircle(texture, 80, 62, 18, glow);
                    DrawLine(texture, 40, 84, 88, 84, body, 10);
                    StrokeCircle(texture, 64, 66, 46, new Color(0.58f, 0.74f, 1f, 1f), 5);
                    break;
                case "shop":
                    FillRect(texture, 28, 56, 72, 42, new Color(0.62f, 0.32f, 0.08f, 1f));
                    StrokeRect(texture, 28, 56, 72, 42, glow);
                    DrawLine(texture, 36, 58, 48, 32, body, 8);
                    DrawLine(texture, 92, 58, 80, 32, body, 8);
                    FillCircle(texture, 46, 76, 6, shadow);
                    FillCircle(texture, 82, 76, 6, shadow);
                    break;
                case "events":
                    FillTriangle(texture, 30, 90, 64, 26, 98, 90, new Color(0.42f, 0.24f, 0.78f, 1f));
                    StrokeCircle(texture, 64, 64, 42, glow, 6);
                    FillStar(texture, 64, 64, 26, 12, body);
                    break;
                case "detail":
                    StrokeRect(texture, 18, 14, 28, 36, body);
                    DrawLine(texture, 23, 24, 41, 24, glow, 3);
                    DrawLine(texture, 23, 33, 41, 33, glow, 3);
                    DrawLine(texture, 23, 42, 34, 42, glow, 3);
                    break;
                case "more":
                    FillCircle(texture, 22, 32, 5, body);
                    FillCircle(texture, 32, 32, 5, glow);
                    FillCircle(texture, 42, 32, 5, body);
                    break;
                case "preview":
                    FillEllipse(texture, 32, 32, 24, 13, blue);
                    FillCircle(texture, 32, 32, 7, shadow);
                    FillCircle(texture, 35, 35, 3, glow);
                    break;
                case "shield":
                    FillTriangle(texture, 18, 18, 46, 18, 32, 52, body);
                    DrawLine(texture, 32, 20, 32, 48, shadow, 3);
                    StrokeRect(texture, 21, 17, 22, 8, glow);
                    break;
                case "world":
                    StrokeCircle(texture, 32, 32, 22, body, 3);
                    DrawLine(texture, 12, 32, 52, 32, glow, 2);
                    DrawLine(texture, 32, 10, 32, 54, glow, 2);
                    StrokeCircle(texture, 32, 32, 10, blue, 2);
                    break;
                case "inbox":
                    StrokeRect(texture, 15, 21, 34, 24, body);
                    DrawLine(texture, 15, 21, 32, 36, glow, 3);
                    DrawLine(texture, 49, 21, 32, 36, glow, 3);
                    break;
                case "back":
                    DrawLine(texture, 42, 16, 22, 32, body, 5);
                    DrawLine(texture, 22, 32, 42, 48, body, 5);
                    DrawLine(texture, 23, 32, 52, 32, glow, 4);
                    break;
                case "close":
                    DrawLine(texture, 20, 20, 44, 44, body, 4);
                    DrawLine(texture, 44, 20, 20, 44, body, 4);
                    break;
                case "upgrade-ready":
                    FillCircle(texture, 64, 64, 46, new Color(0.24f, 0.58f, 0.30f, 1f));
                    StrokeCircle(texture, 64, 64, 48, glow, 6);
                    DrawLine(texture, 42, 66, 58, 84, glow, 11);
                    DrawLine(texture, 58, 84, 90, 40, glow, 11);
                    break;
                case "future":
                default:
                    StrokeCircle(texture, 32, 32, 20, blue, 3);
                    DrawLine(texture, 32, 18, 32, 33, body, 4);
                    DrawLine(texture, 32, 33, 43, 39, body, 4);
                    break;
            }

            texture.Apply();
            return texture;
        }

        private static void SetIconPixel(Texture2D texture, int x, int y, Color color)
        {
            if (x < 0 || y < 0 || x >= texture.width || y >= texture.height) return;
            texture.SetPixel(x, y, color);
        }

        private static void FillRect(Texture2D texture, int x, int y, int width, int height, Color color)
        {
            for (int py = y; py < y + height; py++)
            {
                for (int px = x; px < x + width; px++)
                {
                    SetIconPixel(texture, px, py, color);
                }
            }
        }

        private static void StrokeRect(Texture2D texture, int x, int y, int width, int height, Color color)
        {
            DrawLine(texture, x, y, x + width, y, color, 3);
            DrawLine(texture, x + width, y, x + width, y + height, color, 3);
            DrawLine(texture, x + width, y + height, x, y + height, color, 3);
            DrawLine(texture, x, y + height, x, y, color, 3);
        }

        private static void FillCircle(Texture2D texture, int cx, int cy, int radius, Color color)
        {
            int r2 = radius * radius;
            for (int y = cy - radius; y <= cy + radius; y++)
            {
                for (int x = cx - radius; x <= cx + radius; x++)
                {
                    int dx = x - cx;
                    int dy = y - cy;
                    if (dx * dx + dy * dy <= r2) SetIconPixel(texture, x, y, color);
                }
            }
        }

        private static void FillEllipse(Texture2D texture, int cx, int cy, int rx, int ry, Color color)
        {
            for (int y = cy - ry; y <= cy + ry; y++)
            {
                for (int x = cx - rx; x <= cx + rx; x++)
                {
                    float dx = (x - cx) / (float)rx;
                    float dy = (y - cy) / (float)ry;
                    if (dx * dx + dy * dy <= 1f) SetIconPixel(texture, x, y, color);
                }
            }
        }

        private static void StrokeCircle(Texture2D texture, int cx, int cy, int radius, Color color, int thickness)
        {
            int outer = radius * radius;
            int innerRadius = Mathf.Max(1, radius - thickness);
            int inner = innerRadius * innerRadius;
            for (int y = cy - radius; y <= cy + radius; y++)
            {
                for (int x = cx - radius; x <= cx + radius; x++)
                {
                    int dx = x - cx;
                    int dy = y - cy;
                    int distance = dx * dx + dy * dy;
                    if (distance <= outer && distance >= inner) SetIconPixel(texture, x, y, color);
                }
            }
        }

        private static void DrawLine(Texture2D texture, int x0, int y0, int x1, int y1, Color color, int thickness)
        {
            int dx = Mathf.Abs(x1 - x0);
            int dy = Mathf.Abs(y1 - y0);
            int sx = x0 < x1 ? 1 : -1;
            int sy = y0 < y1 ? 1 : -1;
            int err = dx - dy;
            while (true)
            {
                FillCircle(texture, x0, y0, Mathf.Max(1, thickness / 2), color);
                if (x0 == x1 && y0 == y1) break;
                int e2 = 2 * err;
                if (e2 > -dy)
                {
                    err -= dy;
                    x0 += sx;
                }
                if (e2 < dx)
                {
                    err += dx;
                    y0 += sy;
                }
            }
        }

        private static void FillTriangle(Texture2D texture, int x1, int y1, int x2, int y2, int x3, int y3, Color color)
        {
            int minX = Mathf.Min(x1, Mathf.Min(x2, x3));
            int maxX = Mathf.Max(x1, Mathf.Max(x2, x3));
            int minY = Mathf.Min(y1, Mathf.Min(y2, y3));
            int maxY = Mathf.Max(y1, Mathf.Max(y2, y3));
            float area = Edge(x1, y1, x2, y2, x3, y3);
            if (Mathf.Abs(area) < 0.01f) return;
            for (int y = minY; y <= maxY; y++)
            {
                for (int x = minX; x <= maxX; x++)
                {
                    float w0 = Edge(x2, y2, x3, y3, x, y);
                    float w1 = Edge(x3, y3, x1, y1, x, y);
                    float w2 = Edge(x1, y1, x2, y2, x, y);
                    if ((w0 >= 0f && w1 >= 0f && w2 >= 0f) || (w0 <= 0f && w1 <= 0f && w2 <= 0f))
                    {
                        SetIconPixel(texture, x, y, color);
                    }
                }
            }
        }

        private static float Edge(int x1, int y1, int x2, int y2, int x, int y)
        {
            return (x - x1) * (y2 - y1) - (y - y1) * (x2 - x1);
        }

        private static void DrawHexIcon(Texture2D texture, int cx, int cy, int radius, Color color, int thickness)
        {
            Vector2Int[] points = new Vector2Int[6];
            for (int i = 0; i < points.Length; i++)
            {
                float angle = Mathf.PI / 6f + i * Mathf.PI / 3f;
                points[i] = new Vector2Int(cx + Mathf.RoundToInt(Mathf.Cos(angle) * radius), cy + Mathf.RoundToInt(Mathf.Sin(angle) * radius));
            }

            for (int i = 0; i < points.Length; i++)
            {
                Vector2Int a = points[i];
                Vector2Int b = points[(i + 1) % points.Length];
                DrawLine(texture, a.x, a.y, b.x, b.y, color, thickness);
            }
        }

        private static void FillStar(Texture2D texture, int cx, int cy, int outerRadius, int innerRadius, Color color)
        {
            Vector2Int[] points = new Vector2Int[10];
            for (int i = 0; i < points.Length; i++)
            {
                float angle = -Mathf.PI / 2f + i * Mathf.PI / 5f;
                int radius = i % 2 == 0 ? outerRadius : innerRadius;
                points[i] = new Vector2Int(cx + Mathf.RoundToInt(Mathf.Cos(angle) * radius), cy + Mathf.RoundToInt(Mathf.Sin(angle) * radius));
            }

            for (int i = 1; i < points.Length - 1; i++)
            {
                FillTriangle(texture, points[0].x, points[0].y, points[i].x, points[i].y, points[i + 1].x, points[i + 1].y, color);
            }
        }
    }

    public sealed class HiveViewCellMarker : MonoBehaviour
    {
        public string CellId;
    }
